def _durable_ring_key(client_meta: dict | None) -> tuple[str, str] | None:
    """Centralized ring-key derivation for the durable KV ring.
    Returns (role, session_id) or None if missing. Mirrors save/restore client_meta usage.
    
    Derives role from the client's is_* BOOLEANS via _class_from_label (priority:
    is_curator > is_compression > is_sub_agent > is_main). Falls back to literal
    'role' string if present, then 'main'. This ensures curator/sub/main are
    DISTINCT keys even when the harness doesn't send a top-level 'role' string."""
    if not client_meta:
        return None
    from turbohaul.kv_classify import _class_from_label
    role = _class_from_label(client_meta) or client_meta.get("role") or "main"
    session_id = client_meta.get("session_id")
    if not session_id:
        return None
    return (role, str(session_id))


def _bin_role(client_meta: dict | None) -> str | None:
    """SPEC-V2 (design note): trusted role for bin keying. Label-derived first
    (is_curator > is_compression > is_sub_agent > is_main via _class_from_label).
    A literal client_meta['role'] string is honored for NON-main roles only —
    'main' is reachable ONLY via an explicit is_main label, NEVER by default or
    by a bare literal. Returns None when the request is unlabeled, which means
    RAW thread_id keying (today's behavior) — an unlabeled variant can therefore
    never collide with, restore, or reset the main session bin."""
    if not client_meta:
        return None
    from turbohaul.kv_classify import _class_from_label
    role = _class_from_label(client_meta)
    if role is not None:
        if str(role) == "main" and not client_meta.get("is_main"):
            return None
        return str(role)
    r = client_meta.get("role")
    if r and str(r) != "main":
        return str(r)
    return None


def _norm_tip_role(role: str | None) -> str:
    """Canonicalize the None/"main" split that every
    OTHER role check in this file already treats as one bucket (see
    `role not in (None, "main")` at other call sites and the docstring
    above: "'main' is reachable ONLY via an explicit is_main label... None
    = unlabeled (today's main)"). The VRAM-anchor tip_role comparison
    (_probe_and_save_clean_kv's three write sites, _maybe_force_clean_
    restore's read) MUST use this same canonicalization — comparing raw
    None vs "main" with strict equality would treat two genuinely-main
    turns as a role MISMATCH whenever the harness is inconsistent about
    sending an explicit is_main label from one turn to the next, spuriously
    denying a legitimate main-to-main VRAM reuse (the signature:
    a main turn declining an anchor that legitimately
    was its own)."""
    return "main" if role in (None, "main") else role


def _bin_identity(thread_id: str, client_meta: dict | None, chain: list | None = None) -> str:
    """SPEC-V2 bin key: ONE KV copy per (session_id, role). Fed to
    Manager._thread_hash for filenames AND stamped as meta 'thread_id', so the
    byte-locked kv_policy.resolve_kv owner string-compare keys on (session,
    role) with ZERO kv_policy/kv_classify edits.

    - session_id absent OR role unlabeled -> raw thread_id (today, byte-for-byte).
    - sub-agent / curator roles carry an 8-hex conversation fingerprint from the
      first TWO admission-chain entries (system + first user turn — chain[0]
      alone can be a sibling-shared system prompt), so concurrent same-role
      siblings in one session get DISTINCT bins (design note — no
      last-longest-wins starvation, no sibling reset ping-pong). chain
      unavailable -> raw thread_id (safe per-thread bin).
    """
    cm = client_meta or {}
    session_id = cm.get("session_id")
    if not session_id:
        return thread_id or ""
    role = _bin_role(cm)
    if role is None:
        return thread_id or ""
    from turbohaul.kv_classify import CLASS_SUB_AGENT, CLASS_CURATOR
    if role in (CLASS_SUB_AGENT, CLASS_CURATOR):
        if not chain:
            return thread_id or ""
        fp = hashlib.sha256("|".join(str(h) for h in chain[:2]).encode()).hexdigest()[:8]
        return f"sess:{session_id}:{role}:{fp}"
    return f"sess:{session_id}:{role}"


def _select_ring_bin(ring: list, inc_chain: list, model_tag: str):
    """Select the first ring entry (newest-first) that matches ALL criteria:
    (a) same model_tag,
    (b) NON-EMPTY hash_chain (guard against [] -> trivially prefix of anything but yields 0 common-prefix),
    (c) valid PREFIX of inc_chain (reuses _is_prefix_match, the SAME check default path uses).
    
    Returns the matching ring_entry or None. Prefers clean_prefix=True when multiple qualify.
    """
    from turbohaul.kv_classify import _is_prefix_match
    
    clean_matches = []
    other_matches = []
    
    for entry in ring:
        # (a) same model_tag
        if entry.get("model_tag") != model_tag:
            continue
        # (b) NON-EMPTY hash_chain
        chain = entry.get("hash_chain", [])
        if not chain:
            continue
        # (c) valid PREFIX of inc_chain (same check as default path)
        if _is_prefix_match(chain, inc_chain):
            if entry.get("clean_prefix", False):
                clean_matches.append(entry)
            else:
                other_matches.append(entry)
    
    # Prefer clean_prefix=True when multiple qualify (don't let polluted bin clobber clean default)
    if clean_matches:
        return clean_matches[0]  # newest clean (ring is newest-first)
    if other_matches:
        return other_matches[0]  # newest non-clean
    return None


def _shadow_reprefill_enabled() -> bool:
    """True IFF TURBOHAUL_SHADOW_REPREFILL is set truthy. Default OFF so
    Option A (SAVE-side shadow-reprefill) ships completely INERT: no shadow bin is
    written and zero extra work runs until PL opts in for a smoke. This gate is
    SAVE-side only — the restore gate is unchanged and never consumes the
    shadow bin (that restore-preference is a SEPARATE, PL-owned step)."""
    return os.environ.get("TURBOHAUL_SHADOW_REPREFILL", "").strip().lower() in (
        "1", "true", "yes", "on",
    )


def _shadow_restore_prefer_enabled() -> bool:
    """True IFF TURBOHAUL_SHADOW_RESTORE_PREFER is set truthy. Default OFF so
    step (d) (the shadow RESTORE-preference) ships completely INERT: the restore path
    is byte-identical to today (the clean anchor is chosen) until PL opts in for a
    smoke. This gate is RESTORE-side only and mirrors the SAVE-side
    _shadow_reprefill_enabled(); the two are independent (no shadow bin exists to
    prefer unless the SAVE gate wrote one, so with SAVE off this reader is a no-op).

    When ON it ONLY adds a preference for a PROVEN-PREFIX `.shadow` bin over the clean
    anchor at the one warm forced-restore seam (_maybe_force_clean_restore). It does
    NOT weaken any prefix-validity/owner check: a shadow bin is eligible only if it
    passes the SAME _is_prefix_match bar the clean path uses, and even a wrongly-
    preferred bin only ever costs a reprefill via the engine's get_common_prefix
    backstop — never a wrong answer (see _maybe_force_clean_restore)."""
    return os.environ.get("TURBOHAUL_SHADOW_RESTORE_PREFER", "").strip().lower() in (
        "1", "true", "yes", "on",
    )


def _shadow_cold_restore_enabled() -> bool:
    """True IFF the COLD-path (wave-return / swap-back)
    shadow restore-preference is active.

    DISTINCT gate from the WARM ``_shadow_restore_prefer_enabled()``
    (TURBOHAUL_SHADOW_RESTORE_PREFER, held 0 on purpose): at the WARM grace-follow-up
    seam the engine already holds a warm KV, and native warm reuse (an equal-or-longer
    valid prefix) should win — so preferring a shadow there is disabled. The COLD
    swap-back has NO warm KV at all (the sidecar was just re-spawned), so the
    byte-matching think-free ``.shadow`` bin (turns 1..N think-free) is the CORRECT
    cold restore target: restoring it lets the next decode STRICT-EXTEND the think-free
    state (reprefill only the appended sub-result tail) instead of a fresh full
    prefill. Because the two seams want opposite defaults, they MUST be independent
    gates (do not fold the cold path under the warm flag).

    Default: ON whenever the SAVE-side ``TURBOHAUL_SHADOW_REPREFILL`` is enabled — a
    shadow bin only exists to prefer when the save gate wrote one, so the cold
    preference should activate exactly when (and only when) shadows are being written.
    An explicit ``TURBOHAUL_SHADOW_COLD_RESTORE`` overrides the default in EITHER
    direction (``1/true/yes/on`` force-ON; ``0/false/no/off`` force-OFF — e.g. to A/B
    the SAVE side without the cold restore). With SHADOW_REPREFILL off (default) this
    ships INERT: no shadow bins exist, so the cold path is byte-identical to today."""
    v = os.environ.get("TURBOHAUL_SHADOW_COLD_RESTORE", "").strip().lower()
    if v in ("1", "true", "yes", "on"):
        return True
    if v in ("0", "false", "no", "off"):
        return False
    return _shadow_reprefill_enabled()


def _cold_restore_size_guard_enabled() -> bool:
    """True IFF the
    cold/wave-return restore path's token-size decline guard is active.

    Analogous in SPIRIT to the warm-slot size check (never force-restore a bin a live
    engine query proves cannot be covered), NOT in mechanism: the warm-slot size check compares a
    candidate bin's tokens against a WARM slot's already-resident token count
    (``bin_tokens < live_slot_tokens`` -> decline) — that has no cold-path
    equivalent, because a freshly-spawned engine has nothing resident to
    protect. This guard instead compares the candidate bin's own recorded
    token count against a live-tokenized count of what the INCOMING request
    actually renders to, declining when the bin is LARGER than what the
    request could possibly need — the token-level extension of the
    turn-level "PHYSICS BELT" kv_policy.py's ``_resolve_restore`` already
    applies (never restore a bin with MORE TURNS than incoming); this closes
    the same class of hazard where turn-count matches but token count does
    not.

    Default ON — this is a decline-only backstop; disabling it returns the
    cold path to exactly today's behavior (restore always attempted; the
    engine's own get_common_prefix + CLEAR remains the final backstop either
    way). ``TURBOHAUL_COLD_RESTORE_SIZE_GUARD=0/false/no/off`` force-disables
    it (ops kill-switch, same idiom as every other guard in this file)."""
    v = os.environ.get("TURBOHAUL_COLD_RESTORE_SIZE_GUARD", "").strip().lower()
    return v not in ("0", "false", "no", "off")


# Tokenizer-boundary slack for the cold-restore size guard, NOT an
# attempt to model the engine's own n_rs_seq bound (tiny, per-model, and only
# knowable via a live engine call this guard deliberately avoids adding). This
# is a coarse backstop sized against the excess-token cases already seen (single-
# digit-thousands to tens-of-thousands of excess tokens), not a precise
# predictor of every case the engine's own get_common_prefix would still
# accept as a small, in-bound stale tail.
_COLD_RESTORE_SIZE_MARGIN_TOKENS = 32


def _classify_cold_restore_size(
        bin_kind: str, bin_clean: bool,
        bin_tokens: "int | None", incoming_tokens: "int | None",
        margin: int) -> "tuple[bool, str]":
    """Four-way decision for the cold-restore size
    guard, enumerated by POSITIVE VALIDATION of what's actually known (same
    discipline as ``_classify_dirty_tip_probe``, not by failure mode):
      - bin_kind == "clean" and NOT bin_clean (a WITH-THINK/polluted bin) ->
        proceed, OUT OF SCOPE. A polluted bin is EXPECTED to carry more raw
        tokens than a think-stripped incoming resend — the reasoning-tag
        content the harness never sends back — and that is the PRE-EXISTING,
        already-documented recurrent-rewind limit
        exposure. Applying a size check there would decline the ordinary,
        designed-for fallback restore on every single with-think bin — the
        same SHAPE of mistake as an over-broad size check (a check that fires on
        the common healthy case, not the rare bad one). A clean/shadow bin
        carries no such expected excess — it exists specifically to
        byte-match the resend — so real excess there is a genuine anomaly.
      - bin_tokens is None or incoming_tokens is None (the bin's own count or
        the live tokenize probe is unavailable) -> proceed, FAIL OPEN. A cold
        restore that silently refuses on an unknown is a full reprefill,
        which is the cost this guard exists to remove.
      - bin_tokens > incoming_tokens + margin -> DECLINE. The bin cannot be
        covered by what the incoming request actually renders to; restoring
        it would leave a tail with nothing in the incoming stream to match,
        the exact shape of every known case.
      - else -> proceed, size is consistent with what's being asked for.
    Returns (proceed, case); case is one of "polluted_out_of_scope",
    "unknown_fail_open", "size_decline", "size_ok". PURE; never raises."""
    if bin_kind == "clean" and not bin_clean:
        return True, "polluted_out_of_scope"
    if bin_tokens is None or incoming_tokens is None:
        return True, "unknown_fail_open"
    if bin_tokens > incoming_tokens + margin:
        return False, "size_decline"
    return True, "size_ok"


def _clean_stamp_evidence_gate_enabled() -> bool:
    """Ops kill-switch — True IFF the
    evidence-required clean-stamp gate is active on force_clean saves.

    The gate declines a force_clean save that has no probe-recorded think-free
    render count for the port (the pre-fix behavior stamped clean_prefix=True
    on the slot-count fallback, which covers the with-think tokens the client
    never re-sends — the poisoned-bin failure).

    Default ON. ``TURBOHAUL_CLEAN_STAMP_EVIDENCE_GATE=0/false/no/off``
    force-disables the gate (same idiom as every other guard in this file):
    force_clean saves then fall back to the pre-fix stamp behaviour (clean on
    the fallback cap) with a loud per-save warning — the operator's explicit
    lever if an engine build regresses the probe's usage/tokens_evaluated
    reporting and the declines eat anchor freshness."""
    v = os.environ.get("TURBOHAUL_CLEAN_STAMP_EVIDENCE_GATE", "").strip().lower()
    return v not in ("0", "false", "no", "off")


def _first_divergent_turn_index(saved_chain: list, incoming_chain: list) -> int:
    """Index of the FIRST diverging turn between the saved chain
    and the incoming chain, or len(saved_chain) when saved is a valid prefix of
    incoming (the divergence sits exactly at the clean extension boundary).
    When the INCOMING chain is the shorter one, the divergence is its end
    (zip stops at the shorter chain).
    A turn-hash chain only says which TURNS match; it is blind to token drift
    WITHIN a turn (the think-tail class of divergence), so this is the only
    manager-side signal for where the chains part. PURE; never raises."""
    i = 0
    for a, b in zip(saved_chain or [], incoming_chain or [], strict=False):
        if a != b:
            break
        i += 1
    return i


def _tooltail_restore_skip_enabled() -> bool:
    """crit3 — True IFF the TOOL-tail restore-skip guard is active.

    DEFAULT OFF (unset / 0/false/no/off): the forced/cold restore fires normally even
    when the divergent tail (turns beyond the common prefix) contains a hash-INVISIBLE
    tool turn. ON (1/true/yes/on): when that tail is tool-opaque, SKIP the restore and
    safe-degrade to the engine's native get_common_prefix checkpoint reuse.

    Why the default is now OFF: the guard was ON to prevent a token-STALE POST -> engine
    CLEAR on a tool tail. That failure mode is now closed upstream by Fix B
    (`_covered_scaffold_strip_enabled`, DEFAULT ON): the SAVE probes prefill the
    think-stripped HISTORICAL-form prompt, so the saved clean/shadow bin now BYTE-MATCHES
    the harness's future think-stripped resend across the covered tool region. With the
    tokens matching, the FALSE-POSITIVE chain "match" no longer POSTs a stale bin -> the
    engine can no longer hit stale > n_rs_seq and CLEAR. So this skip is now REDUNDANT
    (Fix B already prevents the CLEAR) AND HARMFUL: it force-degrades to a full
    reprocess instead of the cheap clean-restore reuse Fix B enables. PL verified live
    with env=0 that the restore reuses at pe~265 (no CLEAR). Flag-on (`1/true/yes/on`)
    is RETAINED as an emergency A/B-rollback floor if a covered tool region is ever
    found still drifting despite Fix B.

    ⚠ Flag-on is a BLUNT containment lever, NOT a clean-correctness path: it reverts to
    the pre-crit3 behavior, which scans `inc_messages[common:]` — for a validated strict-
    prefix clean bin `common == len(clean_chain)`, so that span is the FRESH APPENDED tail.
    A tool-heavy fresh tail therefore still OVER-SKIPS (forces a full reprocess, forfeiting
    the cheap clean-restore) — that over-skip is the exact residual this default-flip fixes.
    Enable it ONLY to contain a suspected Fix-B regression on a genuinely-drifting COVERED
    tool region, accepting the fresh-tail over-skip as the cost. Coupling invariant (NOT
    code-enforced, operator-owned): default-OFF here is safe BECAUSE `_covered_scaffold_strip
    _enabled` (Fix B) is DEFAULT ON; if Fix B is ever disabled, explicitly set this guard ON.

    Mechanism (unchanged): `_prefix_hash_chain` (kv_policy, UNTOUCHED) hashes role+content
    ONLY, so an assistant turn with truthy tool_calls (content null) and a role=="tool"
    result are invisible to the chain. When ON and the harness re-serializes that tool
    region nondeterministically, the guard treats the tail-tool chain "match" as
    untrustworthy and skips the restore rather than POST a possibly token-STALE bin."""
    v = os.environ.get("TURBOHAUL_TOOLTAIL_RESTORE_SKIP", "").strip().lower()
    return v in ("1", "true", "yes", "on")


def _staletail_restore_skip_enabled() -> bool:
    """True IFF the WARM-path stale-tail restore-skip guard is active. DEFAULT ON.

    The warm force-restore gate (would_force/warm_covers) checks whether the clean
    bin is a valid prefix of the incoming request and whether the resident warm
    state already covers it — it does not check whether the resident warm state
    has MORE turns than the incoming request itself represents. When it does (e.g.
    a background turn served on the same shared engine slot appended content past
    the last turn the current conversation has ever produced), forcing the restore
    loads the shorter clean bin but leaves the surplus warm KV resident; the
    engine's trim budget for that surplus is small and fixed, and any multi-turn
    surplus exceeds it — the engine CLEARS the slot and does a full reprefill
    instead of the incremental reuse the restore was meant to provide. In
    practice a warm-turns-exceeds-incoming-turns forced restore
    ends in this engine-side CLEAR; these are the most
    expensive events (tens of thousands of tokens each), not the
    most frequent.

    Compared against the INCOMING request's own turn count, not the clean bin's —
    a clean bin can legitimately be several turns behind a normal, healthy
    conversation (nothing wrong with that; it is what the restore is for). Warm
    state exceeding the incoming request's own turn count is structurally
    different: `_is_prefix_match` (kv_policy) refuses a saved chain longer than
    incoming outright, so `warm_turns > inc_turns` already guarantees
    `warm_covers` is false and can only mean the extra content does not belong to
    this conversation's own trajectory at all. Turn-count proxy, not a token-level
    compare: the manager has no token-level staleness figure at this decision
    point without an extra live query, and the engine's actual trim capacity is
    not reliably obtainable here either (a same-named field elsewhere in this file
    is a different runtime quantity, not the engine's true value). Any such
    surplus is treated as unsafe regardless of size.

    DEFAULT ON because the guard is decline-only: worst case it forgoes a forced
    restore and falls through to the engine's native reuse, the path this file
    already treats as the healthy default elsewhere — it cannot corrupt state, so
    an inert (default-off) flag would ship no protection against an active
    problem. OFF (0/false/no/off): the forced restore fires
    regardless of warm/incoming turn counts, today's behavior."""
    v = os.environ.get("TURBOHAUL_STALETAIL_RESTORE_SKIP", "").strip().lower()
    if v in ("0", "false", "no", "off"):
        return False
    return True


def _ram_reanchor_enabled() -> bool:
    """Option C — per-turn RAM save+restore re-anchor. DEFAULT ON when
    SLOT_SAVE_DIR is tmpfs. Kill-switches (no recreate):
      hot: touch /var/lib/turbohaul/.ram_reanchor_off
      env: TURBOHAUL_RAM_REANCHOR=0
    """
    if os.path.exists("/var/lib/turbohaul/.ram_reanchor_off"):
        return False
    v = os.environ.get("TURBOHAUL_RAM_REANCHOR", "").strip().lower()
    if v in ("0", "false", "no", "off"):
        return False
    return True


_DEFAULT_MOUNTINFO_PATH = "/proc/self/mountinfo"


def _parse_mountinfo(mountinfo_path: str = _DEFAULT_MOUNTINFO_PATH) -> tuple[dict[str, str], bool]:
    """Parse ``mountinfo_path`` (mountinfo(5) format) into {mount_point: fstype}.

    Authoritative for what THIS process/
    container sees — the host's view can mislead, for example
    a tmpfs mount missing INSIDE the container while the host still had its
    own, unrelated view of the same path.

    Returns ``(mounts, readable)``. ``readable=False`` (empty dict) on ANY
    read/parse failure — the caller treats an unreadable mountinfo as its own
    LOUD case, never a crash. Never raises.
    """
    mounts: dict[str, str] = {}
    try:
        with open(mountinfo_path) as f:
            lines = f.readlines()
    except OSError:
        return {}, False
    for line in lines:
        # mountinfo(5): "<fields...> - <fstype> <source> <super-opts>". The
        # optional-tag fields before " - " never contain " - " themselves, so
        # splitting on the literal separator is reliable.
        parts = line.split(" - ", 1)
        if len(parts) != 2:
            continue
        left_fields = parts[0].split()
        if len(left_fields) < 5:
            continue
        mount_point = left_fields[4]
        right_fields = parts[1].split()
        if not right_fields:
            continue
        mounts[mount_point] = right_fields[0]
    return mounts, True


@dataclass(frozen=True)
class _MountCheck:
    path: str
    is_own_mount: bool
    fstype: str | None
    mountinfo_readable: bool


def _check_mount(path: str, *, mountinfo_path: str = _DEFAULT_MOUNTINFO_PATH) -> _MountCheck:
    """Best-effort mount/fstype detection for ``path``. NEVER raises.

    Mechanism: a directory that IS a mountpoint has a DIFFERENT
    ``st_dev`` than its own parent directory — that is ``is_own_mount``,
    verified independently of what any file claims. The fstype comes from
    ``/proc/self/mountinfo``, matched by LONGEST mount-point prefix (a path
    several levels under a mountpoint still resolves to that mountpoint's
    fstype). An unmounted path still resolves to SOME fstype via its parent
    mount — ``is_own_mount=False`` is the signal that flags it regardless of
    what that inherited type happens to be; fstype alone is not sufficient
    (that IS the silent-redirect shape this check exists to catch).
    """
    mounts, mountinfo_readable = _parse_mountinfo(mountinfo_path)
    norm = path.rstrip("/") or "/"
    fstype: str | None = None
    best_len = -1
    for mp, ft in mounts.items():
        mp_norm = mp.rstrip("/") or "/"
        if norm == mp_norm or norm.startswith(mp_norm + "/"):
            if len(mp_norm) > best_len:
                best_len = len(mp_norm)
                fstype = ft
    is_own_mount = False
    try:
        st = os.stat(path)
        parent = os.path.dirname(norm) or "/"
        parent_st = os.stat(parent)
        is_own_mount = st.st_dev != parent_st.st_dev
    except OSError:
        pass
    return _MountCheck(
        path=path, is_own_mount=is_own_mount, fstype=fstype,
        mountinfo_readable=mountinfo_readable,
    )


def _classify_kv_dir_mount(
    path: str,
    *,
    expected_fstype: str | None = None,
    forbidden_fstypes: frozenset[str] = frozenset(),
    mountinfo_path: str = _DEFAULT_MOUNTINFO_PATH,
) -> tuple[bool, str]:
    """Classify one KV directory's mount state.

    Returns ``(loud, reason)``. ``loud=True`` means: log it, count it, KEEP
    SERVING — never raise, never refuse to boot (that decision belongs to the
    caller's informational-only posture, matching the foreign-GPU precedent).

    Two mutually-exclusive assertion shapes (pass at most one):
      - ``expected_fstype`` (SLOT_SAVE_DIR shape): LOUD unless ``path`` IS its
        own mount AND its fstype matches exactly. ``None`` disables the
        assertion (own-mount-ness is not checked either — quiet, informational
        only, for a directory with no grounded expectation).
      - ``forbidden_fstypes`` (SLOT_PERSIST_DIR shape): LOUD iff the resolved
        fstype is in this set. Own-mount-ness is deliberately NEVER asserted
        by this branch (see ``_check_kv_dir_mounts`` docstring for why).

    Anything unclassifiable (missing path, unreadable mountinfo) is its own
    LOUD case, checked FIRST, before either assertion shape runs. Never raises.
    """
    if not os.path.isdir(path):
        return True, f"{path}: path missing or not a directory"

    check = _check_mount(path, mountinfo_path=mountinfo_path)
    if not check.mountinfo_readable:
        return True, f"{path}: /proc/self/mountinfo unreadable, cannot verify fstype"

    if expected_fstype is not None:
        if not check.is_own_mount:
            return True, (
                f"{path}: expected a distinct mount (fstype={expected_fstype!r}) "
                f"but it is NOT its own mount (inherited fstype={check.fstype!r} "
                "from its parent — a missing/unmounted expected mount silently "
                "redirects writes instead of erroring)"
            )
        if check.fstype != expected_fstype:
            return True, (
                f"{path}: expected fstype={expected_fstype!r}, observed "
                f"{check.fstype!r}"
            )
        return False, f"{path}: OK (own mount, fstype={check.fstype!r})"

    if forbidden_fstypes:
        if check.fstype in forbidden_fstypes:
            return True, (
                f"{path}: fstype={check.fstype!r} is FORBIDDEN for this "
                "directory (cold-storage tier must never be volatile — it "
                "would silently evaporate on restart)"
            )
        return False, f"{path}: OK (fstype={check.fstype!r}, not forbidden)"

    return False, f"{path}: no assertion configured (informational only)"


def _warm_natural_skip_enabled() -> bool:
    """Gate the warm-anchor-natural-skip. DEFAULT OFF.

    The skip serves the engine's NATURAL slot state (which, for a thinking model,
    carries the generated ``<think>...</think>`` tokens) instead of restoring the
    think-STRIPPED clean bin. When the harness resends assistant turns WITHOUT
    reasoning (the AI harness case — proven: incoming assistant turns have no
    reasoning_content), the think-full natural state diverges from the think-less
    resend at the first generated think block -> get_common_prefix truncates to the
    last-user boundary -> the whole since-last-user span reprefills every turn.
    Restoring the stripped clean bin (crash-free) matches the resend
    byte-for-byte -> delta-only. So default OFF. Set ON only for a harness that
    PRESERVES reasoning_content on resent turns (natural == resend), where the
    skip validly avoids a redundant restore."""
    return os.environ.get("TURBOHAUL_WARM_NATURAL_SKIP", "").strip().lower() in (
        "1", "true", "yes", "on",
    )


def _curator_reuse_main_active() -> bool:
    """True IFF the curator reuse-main route is active.

    DEFAULT OFF: a curator turn is classified but NOT remapped — it keeps its own
    identity + saves normally, byte-identical to today. ON (1/true/yes/on): a
    labelled curator RESTORES the shared main bin (identity hermes-main-<sid>, via
    the admission remap) and its slot save is SKIPPED (save_ok=False, this file's
    save-gate) so it never overwrites main's anchor. resolve_kv / kv_policy are
    byte-identical either way — only the thread_id fed IN and whether a save fires
    change. Flag- AND label-gated: with the flag off OR the labels absent it is
    fully inert."""
    return os.environ.get("TURBOHAUL_CURATOR_REUSE_MAIN", "").strip().lower() in (
        "1", "true", "yes", "on",
    )


def _role_save_enabled(role, client_meta=None) -> bool:
    """Per-role KV-save toggle. HARNESS-LEVEL ONLY — the sole
    source is the FRONT-END/backend setting delivered on the request as
    ``client_meta["save_kv"]`` (bool). Design rule: NO environment variables. The harness wires
    an AI harness's per-role UI toggle to this field; if present it is authoritative for THIS
    request's role. DEFAULT (field absent) = False = DISPOSABLE ROLE IS NOT SAVED — the
    default (main always saves; curator/sub-agent/compression off unless the front-end turns
    that role on, e.g. a big-VRAM box that wants to keep everything). Called ONLY for disposable
    roles (the gate is `_disp_role is not None`); main never reaches here, so main ALWAYS saves."""
    if isinstance(client_meta, dict) and isinstance(client_meta.get("save_kv"), bool):
        return client_meta["save_kv"]
    return str(role) == "main"


def _displacement_save_allowed(
    outgoing_client_meta: dict | None, incoming_client_meta: dict | None
) -> tuple[bool, str | None, str | None]:
    """The displacement gate: SINGLE resolve point for 'may a same-model,
    no-unload displacement of the OUTGOING identity trigger a clean-KV save?'
    (single source of truth — no scattered role-ifs, mirrors
    _seam_flush_allowed's shape one function down). True iff the OUTGOING
    side is main-class (_bin_role convention: None or explicit 'main', same
    as _probe_and_save_clean_kv's own _disp_role check) AND the INCOMING
    visitor is a new-tag curator or sub-agent request. is_compression is
    explicitly EXCLUDED — a compression event is about to rewrite main's own
    context by design, so a pre-compression bin would protect a context that
    is about to be obsolete.

    Returns (allowed, outgoing_role, incoming_class): incoming_class is the
    resolved _class_from_label of the incoming visitor (None if outgoing
    was never main-class to begin with — this gate was never in play, no need
    for a caller to even evaluate it). Compare incoming_class to
    kv_classify.CLASS_COMPRESSION to log the specific 'excluded, not just
    absent' case.

    KNOWN EXPOSURE (not fixed here, by design): an `allowed=True` result
    only means the gate WILL ATTEMPT the save — the shared chokepoint
    (_probe_and_save_clean_kv) still applies its own independent 40000-char
    _MIN_CTX_LEN floor before anything is written. A short displaced main
    thread (or the unlabeled/null-session edge case — see the min-ctx-bar
    DECLINED log line) still pays a full reprefill on its next turn even
    though this predicate said yes. The bar exists to bound multi-GB re-save
    cost on trivial contexts and is an economy threshold, not a correctness
    one; revisit only on evidence, not as part of this change."""
    from turbohaul.kv_classify import CLASS_CURATOR, CLASS_SUB_AGENT, _class_from_label
    outgoing_role = _bin_role(outgoing_client_meta)
    if outgoing_role not in (None, "main"):
        return False, outgoing_role, None
    incoming_class = _class_from_label(
        incoming_client_meta if isinstance(incoming_client_meta, dict) else None)
    allowed = incoming_class in (CLASS_CURATOR, CLASS_SUB_AGENT)
    return allowed, outgoing_role, incoming_class


def _seam_flush_allowed(thread_id: str, client_meta: dict | None) -> tuple[bool, str | None]:
    """SINGLE resolve point for 'may an unload seam persist this
    identity?' (code-unification doctrine — no scattered role-ifs). Labels first: a
    disposable role (curator/compression/sub-agent) whose per-role save is OFF
    (client_meta['save_kv'] contract — honored via
    _role_save_enabled so the FE toggle keeps working) never flushes — kills the
    junk sess:*:sub-agent:* seam bins. Unlabeled (role=None) traffic flushes
    (raw-thread main back-compat; main always saves) UNLESS the thread name
    proves disposable/auto provenance: hermes-sub-* (harness contract) or the
    auto-minted walk-in fallback agent-ip-*/auto-*. Returns (allowed, resolved_role)
    so every caller logs the decision with identifiers."""
    role = _bin_role(client_meta)
    if role not in (None, "main") and not _role_save_enabled(role, client_meta):
        return False, role
    _tid = thread_id or ""
    if role is None and _tid.startswith(("hermes-sub-", "agent-ip-", "auto-")):
        return False, role
    return True, role


def _classify_dirty_tip_probe(
        probe_ok: bool, populated_count: "int | None",
        erased: bool) -> "tuple[bool, str]":
    """Dirty-tip zero-populated-proceed handling —
    four-way decision for whether an unload-seam save may PROCEED (with or without an
    erase) or must be REFUSED, enumerated by POSITIVE VALIDATION of what the /slots
    probe actually observed (same discipline as the other classifiers in this file, not by failure mode):
      - probe_ok is False (the /slots GET itself never completed), or populated_count
        is None (defensive: should not happen when probe_ok is True, but treated the
        same way if it ever does) -> REFUSE, "probe_failed". An unknown state is not a
        proven-clean state; this side fails CLOSED on ambiguity -- the mirror of the
        cold-restore size guard failing OPEN, because there the wrong-way cost is an
        extra reprefill and here it is a silently poisoned bin a future restore will
        trust.
      - populated_count == 0 -> PROCEED, "zero_populated" (skip the erase POST, nothing
        to erase). Caller MUST compute populated_count from BOTH n_prompt_tokens>0 AND
        n_prompt_tokens_cache>0 per slot (either one nonzero counts as populated) -- see
        the call site. n_prompt_tokens alone is provably not sufficient: two engine call
        sites (server-context.cpp:2099 LoRA-adapter-change, :3043 failed SLOT_RESTORE)
        clear the token vector WITHOUT clearing KV, and neither routes through
        reset()/release() (server-context.cpp:703), the only place that zeroes
        n_prompt_tokens_cache. Folding that second signal into populated_count is what
        makes this branch actually safe rather than the original unproven assumption.
      - populated_count == 1, erased -> PROCEED, "single_erased".
      - populated_count == 1, not erased (the erase POST itself failed/raised) ->
        REFUSE, "single_erase_failed".
      - populated_count >= 2 -> REFUSE, "multi_populated" (ambiguous, cannot identify
        which slot is dirty).
    Returns (proceed, case). PURE; never raises."""
    if not probe_ok or populated_count is None:
        return False, "probe_failed"
    if populated_count == 0:
        return True, "zero_populated"
    if populated_count == 1:
        return (True, "single_erased") if erased else (False, "single_erase_failed")
    return False, "multi_populated"


def _rearm_dirty_tip_on_incomplete_remediation(
        kv_dirty_tail: dict, port: int, dirty_record: "dict | None") -> dict:
    """Re-arm a port's dirty-tip record when a seam
    remediation erased successfully (flag already popped) but the reprefill
    or save that was SUPPOSED to follow did not complete.

    WHY THE POP CANNOT SIMPLY MOVE TO "after a confirmed save" (the simplest
    fix, and the more obvious-looking one): verified directly
    against _save_slot_kv_inner's own seam-flush chokepoint (manager.py, the
    "ENFORCEMENT CHOKEPOINT" comment on that function) that it
    unconditionally REFUSES any save while this port is still marked dirty —
    its own comment says the remediation "clears the flag before calling
    us". Moving the pop later would make the save this SAME function is
    about to attempt refuse itself, self-defeating the whole erase+
    reprefill+save cycle, not just the three failure paths this function handles. So
    the early pop stays; this function exists to put the flag back ONLY
    when the erase's own promise (a fresh, confirmed clean save) was not
    kept.

    Re-arms the ORIGINAL captured record (not a fresh stamp), so a later
    remediation attempt still names the same foreign role/thread/pid this
    erase was already responding to — not a new, unrelated dirty event.

    No-op (returns kv_dirty_tail unchanged) when dirty_record is falsy: the
    ordinary, never-dirty seam-flush shares these same downstream return
    sites and has nothing to re-arm. PURE; never raises."""
    if not dirty_record:
        return kv_dirty_tail
    _dt = dict(kv_dirty_tail or {})
    _dt[port] = dirty_record
    return _dt


# Frozen-prefix re-prefill: max distinct threads kept in
# the per-thread tools fingerprint. Bounded FIFO (same idiom as
# _SHADOW_BYTEMATCH_CAP) so the dict can never leak across a long-running
# manager process.
_TOOLS_FINGERPRINT_CAP: int = 512


def _tools_fingerprint(tools: "list | None") -> "str | None":
    """SHA256 hex of the canonicalized ``tools`` array (sort_keys, so key ORDER
    within a single tool's schema never causes a false-positive change), or
    None for no/empty tools -- a real, distinguishable state (one a thread
    reaches when its tool count varies between turns), not
    folded into a fixed sentinel hash. PURE; never raises -- a non-JSON-
    serializable tools value degrades to hashing its repr() rather than
    crashing the turn it is merely observing."""
    if not tools:
        return None
    try:
        canon = json.dumps(tools, sort_keys=True, default=str)
    except Exception:
        canon = repr(tools)
    return hashlib.sha256(canon.encode("utf-8", "replace")).hexdigest()


def _tools_names(tools: "list | None") -> "frozenset[str]":
    """Best-effort tool/function names for a human-readable delta -- the OpenAI
    shape (``{"type":"function","function":{"name":...}}``) is checked first,
    falling back to a bare ``{"name":...}`` shape. An entry with neither yields
    the literal "?" rather than being silently dropped, so entered/left counts
    still add up to the real cur/prev counts. PURE; never raises."""
    names = set()
    for t in (tools or []):
        if not isinstance(t, dict):
            names.add("?")
            continue
        fn = t.get("function")
        if isinstance(fn, dict) and fn.get("name"):
            names.add(str(fn["name"]))
        elif t.get("name"):
            names.add(str(t["name"]))
        else:
            names.add("?")
    return frozenset(names)


def _classify_tools_fingerprint(
        prev: "dict | None", cur_hash: "str | None",
        cur_names: "frozenset") -> "tuple[bool, dict]":
    """Observability -- pure decision: has this thread's
    `tools` set changed since the last live turn we saw it on? `prev` is
    whatever this manager instance has stored for the thread (None on first
    sight). Returns (changed, delta); delta always carries prev_count/
    cur_count/entered/left -- POSITIVE VALIDATION discipline matching every
    other classifier in this file: report what is PROVEN (the counts and the
    name-set difference), not an open-ended "something differs" guess.
      - prev is None (first turn ever seen for this thread on this manager
        instance) -> NOT changed. A cold thread's first turn is never itself a
        regression signal; delta reports cur_count only, entered/left empty,
        prev_count 0.
      - prev["hash"] == cur_hash -> NOT changed, regardless of the name-level
        view (identical content by construction -- sort_keys makes the hash
        insensitive to schema key order).
      - else -> changed. entered = names now present that were not; left =
        names that were present and are gone. A same-name, different-schema
        edit (rare -- not the common shape) still flips
        `changed` via the hash even though entered/left both come back empty;
        callers must still log the raw counts in that case, not just the
        (possibly empty) name sets.
    PURE; never raises."""
    if prev is None:
        return False, {
            "prev_count": 0, "cur_count": len(cur_names) if cur_hash else 0,
            "entered": [], "left": [],
        }
    if prev.get("hash") == cur_hash:
        return False, {
            "prev_count": prev.get("count", 0), "cur_count": prev.get("count", 0),
            "entered": [], "left": [],
        }
    prev_names = prev.get("names") or frozenset()
    return True, {
        "prev_count": prev.get("count", 0), "cur_count": len(cur_names),
        "entered": sorted(cur_names - prev_names),
        "left": sorted(prev_names - cur_names),
    }


def _cold_restore_tools_fingerprint_guard_enabled() -> bool:
    """True IFF the
    cold-restore path's tools-fingerprint decline guard is active.

    The chain hash in kv_policy.py being blind to `tools` is why a
    tools-driven prompt divergence looks like a MATCH to the manager. Fixing
    that by changing the chain hash itself was considered and rejected:
    the minimal
    "fold tools in only when present" design leaves a real coincidental-
    collision path for an old tools-bearing bin against a later tools-less
    request on the same thread -- not a rare edge case here, it occurs
    on a meaningful share of threads. A fully safe hash change would need an
    unconditional format bump (every bin invalidated, tools or not), which is
    strictly bigger than the alternative below.

    Instead: decline reuse of a restore candidate whose bin has a POSITIVELY
    RECORDED tools fingerprint (persisted by the save path, reusing the
    `_tools_fingerprint`) that differs from the incoming request's current
    one. Reuses the already-live, already-tested fingerprint machinery;
    touches nothing every other restore guard depends on (kv_policy.py stays
    untouched); needs no bin-format version marker -- one new OPTIONAL meta
    field, read with `.get()` like every other optional field on this path
    (`clean_prefix`, `stale`), so an old bin with no field is a clean absent,
    never a parse error, never a hard failure.

    Default ON -- this is a decline-only backstop, same idiom as
    `_cold_restore_size_guard_enabled`; disabling it returns the cold path to
    exactly today's tools-blind behavior. `TURBOHAUL_COLD_RESTORE_TOOLS_
    FINGERPRINT_GUARD=0/false/no/off` force-disables it."""
    v = os.environ.get(
        "TURBOHAUL_COLD_RESTORE_TOOLS_FINGERPRINT_GUARD", "").strip().lower()
    return v not in ("0", "false", "no", "off")


def _classify_tools_fingerprint_restore_guard(
        bin_fingerprint: "str | None",
        incoming_fingerprint: "str | None") -> "tuple[bool, str]":
    """Three-way decision for the
    cold-restore tools-fingerprint guard, enumerated by POSITIVE VALIDATION of
    what's actually recorded (same discipline as every other classifier in
    this file, not by failure mode):
      - bin_fingerprint is None (the candidate bin has no recorded tools
        fingerprint -- either it predates the tools-fingerprint feature, or it was
        genuinely saved for a toolless conversation, and `.get()` cannot
        distinguish the two, nor does it need to: BOTH cases must proceed) ->
        proceed, "unknown_fail_open". Absence is not evidence of instability;
        manufacturing a decline out of a metadata gap is the exact failure
        shape this guard must not repeat, now inverted for a REFUSE-shaped
        change: a thread whose tools legitimately never change must never
        pay for this, old bin or new.
      - bin_fingerprint == incoming_fingerprint (covers both a real match AND
        both sides being None, i.e. a toolless bin vs a toolless incoming
        request) -> proceed, "match".
      - else -> DECLINE, "fingerprint_mismatch". A positively-recorded
        fingerprint that disagrees with what the incoming request renders to
        is exactly the failure mechanism: the chain hash says match, the
        rendered prompt has already diverged.
    Returns (proceed, case). PURE; never raises."""
    if bin_fingerprint is None:
        return True, "unknown_fail_open"
    if bin_fingerprint == incoming_fingerprint:
        return True, "match"
    return False, "fingerprint_mismatch"


# ---------------------------------------------------------------------------
# Observability: every opportunity that could save or displace main-class KV
# emits exactly one of KV_SAVE_FIRING / KV_SAVE_DECLINE, via the two helpers
# below. reason_name is always one of the KV_DECLINE_* constants -- never a
# free-text string -- so a decline is a grep target, not prose a human has
# to read to understand. call_site distinguishes which road produced the
# line when more than one exists inside a single function.
# ---------------------------------------------------------------------------
KV_DECLINE_SAVE_DISABLED = "SAVE_DISABLED"
KV_DECLINE_SINGLE_SERIES_GATE = "SINGLE_SERIES_GATE"
KV_DECLINE_BELOW_MIN_CTX = "BELOW_MIN_CTX"
KV_DECLINE_NO_MESSAGES = "NO_MESSAGES"
KV_DECLINE_DISPOSABLE_ROLE_SAVE_OFF = "DISPOSABLE_ROLE_SAVE_OFF"
KV_DECLINE_UNLOAD_SEAM_ONLY = "UNLOAD_SEAM_ONLY"
KV_DECLINE_DIRTY_TIP_ERASE_FAILED = "DIRTY_TIP_ERASE_FAILED"
KV_DECLINE_ZERO_TURN_CHAIN = "ZERO_TURN_CHAIN"
KV_DECLINE_NEVER_OVERWRITE_SMALLER = "NEVER_OVERWRITE_SMALLER"
KV_DECLINE_ZERO_GROWTH_THROTTLE = "ZERO_GROWTH_THROTTLE"
KV_DECLINE_STRIP_PROBE_FAILED = "STRIP_PROBE_FAILED"
KV_DECLINE_PROBE_POST_FAILED = "PROBE_POST_FAILED"
KV_DECLINE_NO_PROBE_EVIDENCE = "NO_PROBE_EVIDENCE"
# The evidence-congruence declines. An extent or chain
# mismatch -> EVIDENCE_MISMATCH (the save proceeds NON-CLEAN); a re-probe of a
# context whose clean bin already proved poison (reused-to-zero) ->
# POISON_REPROBE (same non-clean fall-through). Same convention as the block:
# grep-able constant, never free-text.
KV_DECLINE_EVIDENCE_MISMATCH = "EVIDENCE_MISMATCH"
KV_DECLINE_POISON_REPROBE = "POISON_REPROBE"
KV_DECLINE_SAVE_NOT_CONFIRMED = "SAVE_NOT_CONFIRMED"
KV_DECLINE_UNVERIFIED_EXIT = "UNVERIFIED_EXIT"
KV_DECLINE_DISPLACEMENT_COMPRESSION_EXCLUDED = "DISPLACEMENT_COMPRESSION_EXCLUDED"
KV_DECLINE_DISPLACEMENT_STALE_MODEL = "DISPLACEMENT_STALE_MODEL"
KV_DECLINE_DISPLACEMENT_NO_MAIN_IDENTITY = "DISPLACEMENT_NO_MAIN_IDENTITY"
KV_DECLINE_NO_SLOT_IDENTITY = "NO_SLOT_IDENTITY"
KV_DECLINE_HANDLE_NOT_ALIVE = "HANDLE_NOT_ALIVE"
KV_DECLINE_CANCELLATION_UNWIND_NO_SAVE = "CANCELLATION_UNWIND_NO_SAVE"
KV_DECLINE_FORCE_COLD_NO_SAVE = "FORCE_COLD_NO_SAVE"


# Foundation for the chain check: the clean-prefill register
# holds fresh PROBE EVIDENCE, not a bare count — the save side must be able to
# ask "is this evidence for THIS context?" before it can stamp clean.
@dataclass(frozen=True)
class CleanPrefillEvidence:
    """Fresh probe evidence for a port's clean-stamp gate.

    `count`    — engine-reported think-free render token count of the probed context.
    `chain_fp` — _chain_fp(_prefix_hash_chain(messages)) of the probed context
                 (the context binding; _chain_fp is the IDENTICAL derivation the
                 save side and the poison set use).
    `arm`      — "strip" | "plain": which probe arm recorded it.

    Invariant (extends the register invariant at init): the register answers
    "is there fresh evidence for (port, THIS context)?". Present key = fresh,
    absent key = no clean boundary known. The pop sites (spawn, probe-failure)
    remove the whole entry on failure and are value-type-agnostic.
    """
    count: int
    chain_fp: str
    arm: str


def _chain_fp(chain) -> str:
    """Scalar fingerprint of a turn-hash chain. The IDENTICAL
    derivation every CleanPrefillEvidence.chain_fp, the save-side chain comparison,
    the poison set, and the retired-bin fingerprint use — a chain is a list of
    per-turn hashes; join+sha256 keeps it a stable str. Empty/None chain ->
    "" (can never match a probed non-empty chain)."""
    if not chain:
        return ""
    return hashlib.sha256("|".join(str(h) for h in chain).encode()).hexdigest()


# Tolerance: the save-side extent congruence bound.
# Single-series gate: the slot's live n_prompt_tokens is the engine-reported
# prompt length with MTP draft cells excluded, and the probe's tokens_evaluated
# is the FULL prompt count of the clean render (see the strip-probe docstring:
# it stays correct on a warm slot — no template-overhead delta). 8 tokens
# covers tokenization edge noise on a ~80k-token context; a larger legitimate
# delta would have to be evidenced in-scope before this is sized up.
_CLEAN_STAMP_EVIDENCE_EPS = 8


def _log_kv_save_firing(*, bin_id, thread_id, role, n_tokens, nbytes, trigger, tier, call_site) -> bool:
    """The one shape every confirmed KV save is logged in, regardless of
    which caller reached it. Returns True so a call site can fold the emit
    into its own single-verdict flag in one statement.

    tier is RAM or SSD, required (no default) so a new call site can't
    silently omit it -- the two tiers are indistinguishable without it,
    which is the entire reason this field exists."""
    log.info(
        "KV_SAVE_FIRING bin_id=%s thread_hash=%s role=%s n_tokens=%s bytes=%s "
        "trigger=%s tier=%s call_site=%s",
        bin_id, thread_id or "", role, n_tokens, nbytes, trigger, tier, call_site)
    return True


def _log_kv_save_decline(reason_name: str, *, thread_id="", role=None, call_site="") -> bool:
    """The one shape every decline is logged in. reason_name must be one of
    the KV_DECLINE_* constants above."""
    log.info(
        "KV_SAVE_DECLINE reason_name=%s thread_hash=%s role=%s call_site=%s",
        reason_name, thread_id or "", role, call_site)
    return True


def _tooltail_scan_covered_enabled() -> bool:
    """crit2/crit3 (Fix A — emergency FLOOR, default OFF) — True IFF the crit3
    tool-opaque restore-skip should scan the ENTIRE bin-covered span (start=0) instead of
    only the divergent tail (start=common).

    DEFAULT OFF (unset / 0/false/no/off): pre-Fix-A behavior — the skip scans only
    ``inc_messages[common:]`` (the tail beyond the settled common prefix). ON
    (1/true/yes/on): scan ``inc_messages[0:]``, so a tool-opaque turn ANYWHERE the
    clean/shadow bin covers (even inside the reused prefix) forces the restore to
    safe-degrade to the engine's native get_common_prefix reuse.

    This is the EMERGENCY FLOOR behind Fix B: with Fix B (default ON) the saved bin already
    byte-matches the historical resend across the covered tool region, so the primary path
    is MATCH+REUSE and this wider skip stays OFF. Turn it ON only to fall back to native
    reuse for the whole covered span if a covered tool region is still drifting (Fix B is
    the proof path; this is the rollback safety net)."""
    v = os.environ.get("TURBOHAUL_TOOLTAIL_SCAN_COVERED", "").strip().lower()
    return v in ("1", "true", "yes", "on")


# crit2/crit3 (Fix B): the ``<think>\n...\n</think>\n\n`` block(s) the chat template
# emits position-based for the ASSISTANT turn after last_query_index. SCOPED to each individual
# assistant turn's own span — from its ``<|im_start|>assistant\n`` header to the NEXT
# ``<|im_start|>`` (or end of string) — not to the whole rendered prompt: an unscoped global
# strip also nukes a LITERAL ``<think>...</think>\n\n`` embedded in USER/TOOL content, and the
# common case of operators pasting this very template + engine logs -> those turns are
# saturated with literal think blocks -> the strip would corrupt the save prompt ->
# REUSE->CLEAR regression (silent Fix-B failure on the exact threads it targets). Structural
# exclusion, not a lucky regex: a span that never starts at ``<|im_start|>assistant\n`` is never
# even a candidate, so USER/TOOL content is untouched regardless of what it contains. WITHIN a
# matched assistant span, every think block is removed, not just the first: a single-block-only
# strip left a SECOND block — e.g. reason -> tool_call -> reason -> answer, one generation, two
# blocks — sitting past where an anchor-only, single-match regex could reach, baking un-stripped
# reasoning into bins stamped clean_prefix=true. Non-greedy + DOTALL pairs each open with its own
# close and spans interior newlines, so each block removes both the FILLED form and the empty
# ``<think>\n\n</think>\n\n`` scaffold.
_THINK_SCAFFOLD_TURN_RE = re.compile(
    r"<\|im_start\|>assistant\n.*?(?=<\|im_start\|>|\Z)", re.DOTALL)
_THINK_BLOCK_IN_TURN_RE = re.compile(r"<think>\n.*?\n</think>\n\n", re.DOTALL)
_ASSISTANT_HEADER = "<|im_start|>assistant\n"


def _strip_think_scaffold(rendered: str, messages: list | None = None) -> str:
    """crit2/crit3 (Fix B) — remove every assistant
    ``<think>\\n...\\n</think>\\n\\n`` scaffold block from an ALREADY-RENDERED chat-template
    prompt so a SAVE probe's prefill byte-matches the render those SAME covered turns receive
    once they fall BEFORE last_query_index on the next resend (historical position -> the
    template emits no scaffold for them).

    SCOPED per assistant turn: each match is bounded to one ``<|im_start|>assistant\\n`` span,
    ending at the next ``<|im_start|>`` or end of string. USER/TOOL turns are never even a
    candidate span — a literal ``<think>...</think>\\n\\n`` sitting in USER/TOOL content (the
    common case of operators pasting this template + logs) SURVIVES untouched by construction,
    not by anchoring alone -> no self-inflicted REUSE->CLEAR on those threads. WITHIN a matched
    span, EVERY think block is stripped, not just the first: one assistant turn can legitimately
    contain more than one — reason, call a tool, reason about the result, answer — and a
    single-match regex left the second block's reasoning baked into the saved bin.

    GATE (byte target): ``<|im_start|>assistant\\n<think>\\n{reasoning}\\n</think>\\n\\n<tool_call>``
    -> ``<|im_start|>assistant\\n<tool_call>``; the empty scaffold ``<think>\\n\\n</think>\\n\\n``
    collapses identically; a MULTI-block turn ``...assistant\\n<think>\\na\\n</think>\\n\\nMID
    <think>\\nb\\n</think>\\n\\nEND`` -> ``...assistant\\nMIDEND`` (both blocks gone, inter-block
    text kept).

    PURE + None/non-str safe (passthrough) + idempotent (after one pass every think tag inside
    each assistant span is gone, so a second pass finds nothing left to strip -> no-op)."""
    if not isinstance(rendered, str):
        return rendered
    _preserved = set()
    for _m in (messages or []):
        if isinstance(_m, dict) and _m.get("role") == "assistant":
            _rc = _m.get("reasoning_content")
            if isinstance(_rc, str) and _rc.strip():
                _preserved.add(_rc.strip())

    def _block_sub(bmo):
        _body = bmo.group(0)[len("<think>\n"):-len("\n</think>\n\n")]
        if _body.strip() in _preserved:
            return bmo.group(0)  # preserved reasoning (DATA) — the resend re-emits it
        return ""                # positional scaffold — strip (original behavior)

    def _turn_sub(tmo):
        turn = tmo.group(0)
        body = turn[len(_ASSISTANT_HEADER):]
        return _ASSISTANT_HEADER + _THINK_BLOCK_IN_TURN_RE.sub(_block_sub, body)

    return _THINK_SCAFFOLD_TURN_RE.sub(_turn_sub, rendered)


def _turn_is_tool_opaque(turn) -> bool:
    """True IFF a single incoming turn is HASH-INVISIBLE to _prefix_hash_chain in a way
    that lets its tokens drift undetected (see _tooltail_restore_skip_enabled).

    Tool-opaque when ANY of (crit3 constraint #2):
      - role == "tool"                            (a tool RESULT turn)
      - role == "assistant" AND truthy tool_calls (a tool-CALL turn; content null)
      - content is null / empty                   (contributes nothing distinguishing
                                                   to the chain hash -> unverifiable)
    `content` is read exactly as _prefix_hash_chain reads it (turn.get("content", "")),
    so the null/empty test matches what the chain would (fail to) distinguish. A
    non-dict turn is coerced to str() by the chain (always non-empty) so it is never
    tool-opaque here. PURE; never raises."""
    if not isinstance(turn, dict):
        return False
    role = turn.get("role", "")
    if role == "tool":
        return True
    if role == "assistant" and turn.get("tool_calls"):
        return True
    # Legacy OpenAI function-calling shapes (pre-tool_calls) are equally
    # hash-opaque and drift the same way — cover them too.
    if role == "function":
        return True
    if role == "assistant" and turn.get("function_call"):
        return True
    content = turn.get("content", "")
    if content is None:
        return True
    if isinstance(content, str) and not content.strip():
        return True
    if isinstance(content, (list, dict)) and not content:
        return True
    return False


def _divergent_tail_is_tool_opaque(inc_messages, common: int, *, scan_covered: bool = False) -> bool:
    """SINGLE source (crit3 code-unification) called by BOTH the warm force gate
    (_maybe_force_clean_restore) AND the cold gate (_restore_slot_kv): True IFF the
    span a restore would rely on contains a tool-opaque turn.

    Scans `inc_messages[common:]` — the first diverging turn and everything the
    clean/shadow bin covers beyond the settled common prefix (constraint #2: a tool
    turn strictly BEFORE `common`, already inside the stable reused prefix, does NOT
    count -> a settled tool region never over-triggers the skip). `inc_messages` is
    the admission messages (client_meta["messages"]) which are 1:1 aligned with the
    inc_chain `common` indexes into. PURE: no I/O; empty/None messages (e.g. a streamed
    submit that carried none) -> False = safe-degrade to the pre-crit3 restore (never
    worse than today). `common` is clamped to >= 0.

    crit2/crit3 (Fix A — emergency FLOOR): when `scan_covered` is True the scan
    starts at 0 (the ENTIRE bin-covered span, including the reused prefix) instead of
    `common`, so a tool-opaque turn ANYWHERE the bin covers forces the skip. The caller
    passes `scan_covered=_tooltail_scan_covered_enabled()` (default OFF); the env read is
    kept OUT of this function so it stays PURE + unit-testable by passing the bool
    directly."""
    if not inc_messages:
        return False
    start = 0 if scan_covered else (common if common > 0 else 0)
    for turn in inc_messages[start:]:
        if _turn_is_tool_opaque(turn):
            return True
    return False


def _kv_shadow_save_fn(model_tag: str, sid: int, thread_hash: str, port: int) -> str:
    """Option A shadow-reprefill save filename. DISTINCT `.shadow` marker
    (load-bearing): derived from the canonical clean/normal bin name (kv_save_fn,
    single source of the base scheme) with `.shadow` inserted before `.bin`. Placing
    `.shadow` AFTER the slot number keeps the shadow bin a SEPARATE artifact from the
    clean_prefix anchor (`.slot{sid}.bin`) so a mispredicted shadow can never
    overwrite/demote it, AND makes _restore_slot_kv's bin parser reject it (its slot
    token parses to `{sid}.shadow`, which is not all-digits -> skipped, never
    restored)."""
    return kv_save_fn(model_tag, sid, thread_hash, port)[:-len(".bin")] + ".shadow.bin"


def _kv_shadow_meta_fn(model_tag: str, sid: int, thread_hash: str, port: int) -> str:
    """Sidecar metadata filename for the shadow-reprefill bin (see _kv_shadow_save_fn
    for the distinct-marker rationale)."""
    return kv_meta_fn(model_tag, sid, thread_hash, port)[:-len(".json")] + ".shadow.json"


def _ckpt_sidecar_enabled() -> bool:
    """Mirror the ENGINE's TURBOHAUL_CKPT_SIDECAR gate
    (same env var, same container) so the manager only finalizes the checkpoint-
    ladder .ckpt sidecar name when the engine is actually writing one. Absent/off
    -> no .tmp.ckpt is produced, so the finalize is a no-op either way; the flag
    just skips the os.path.exists probe on the OFF path."""
    return os.environ.get("TURBOHAUL_CKPT_SIDECAR", "").strip().lower() in ("1", "true", "yes", "on")


def _finalize_ckpt_sidecar(tmp_path: str, final_path: str, bin_fn: str) -> None:
    """Finalize the engine's checkpoint-ladder
    sidecar NAME alongside the atomic .bin rename. The engine writes the sidecar to
    ``<save-filename>.ckpt`` == ``<bin>.tmp.ckpt`` (save filename is ``<bin>.tmp``);
    the atomic ``os.replace(<bin>.tmp -> <bin>)`` finalizes ONLY the .bin, orphaning
    ``<bin>.tmp.ckpt``. SLOT_RESTORE reads ``<bin>.ckpt`` -> ABSENT -> empty ladder ->
    stale-too-large CLEAR+reprefill (the pre-fix live behavior). This renames it to
    ``<bin>.ckpt``.

    BEST-EFFORT + called AFTER the .bin rename (bin FIRST): a crash/restore in the
    window safely CLEARs (a .bin can exist with NO/older .ckpt, never a .bin with a
    mismatched newer .ckpt) — and the sidecar's own bin_nwrite header ties it to the
    .bin so a stale .ckpt can never mispair (engine rejects it). Flag-gated; any
    failure is logged + swallowed (never breaks the save)."""
    if not _ckpt_sidecar_enabled():
        return
    ckpt_tmp = tmp_path + ".ckpt"
    if not os.path.exists(ckpt_tmp):
        return
    try:
        os.replace(ckpt_tmp, final_path + ".ckpt")
    except OSError as e:  # noqa: BLE001 — best-effort; restore safely CLEARs on absence
        log.warning("ckpt sidecar finalize failed for %s: %s (restore will CLEAR-safe)", bin_fn, e)


class EventBus:
    """Pub-sub for state-level events broadcast to /ws/state subscribers.

    Per the redaction policy: callers are responsible for emitting only
    safe events. This bus enforces a denylist (prompt/response/stderr/context)
    on publish as defense-in-depth — even if a caller accidentally includes one
    of those keys, it gets stripped before fan-out.

    Note: publish_nowait has no event-loop affinity of its
    own. asyncio.Queue.put_nowait wakes a getter via Future.set_result ->
    loop.call_soon, which is NOT thread-safe (verified against CPython's own
    asyncio/base_events.py: call_soon only checks the calling thread in debug
    mode; the production path is a bare deque.append with no wakeup signal).
    An off-loop caller + an idle loop parked in epoll_wait means the wakeup is
    queued but never observed until something ELSE happens to wake that loop —
    delayed or lost delivery, not a clean crash, and no log line names it.
    Confirmed LIVE (not merely theoretical): _audit (in this module)
    is offloaded via `asyncio.to_thread` in `_audit_async`, and its own
    docstring plus `audit_db_session`'s guard (state.py) mean it can
    ONLY run off the event-loop thread, by construction, on every audited
    lifecycle transition.

    Fix: bind the owning loop lazily at `subscribe()` — never at
    `publish_nowait()`, deliberately. `subscribe()` is only ever reached from
    the /ws/state route handler (api/ws_state.py), which is unconditionally
    on-loop, so the binding is correct regardless of whatever ordering of
    off-loop publish_nowait calls happens before or after it. Binding inside
    publish_nowait instead would be ordering-dependent: an off-loop call
    arriving before any on-loop call had ever bound the loop could otherwise
    capture nothing (or worse, be mistaken for "no protection needed"),
    silently reproducing the exact bug this fixes. Every publish_nowait call
    then compares the CALLING thread's running loop against the bound one:
    same loop -> the original, cheap direct path; anything else (a different
    loop, or no loop on this thread at all, e.g. _audit's worker thread) ->
    routed through call_soon_threadsafe, the one primitive documented safe
    from any thread. Deliberately NOT unconditional call_soon_threadsafe for
    every call: that would add a self-pipe write plus a lock to every single
    generation_tick event during live token streaming (5 of 6 callers are
    already loop-affine and fire on that hot path) to fix one caller that
    needs it.
    """

    REDACTED_KEYS: frozenset[str] = frozenset({
        "prompt",
        "response",
        "context",
        "stderr",
        "stdout",
        "messages",
        # Security: a publisher must never be able
        # to leak these by key, even by accident -- belt-and-suspenders
        # alongside every payload builder's own explicit redaction.
        "thread_id",
        "ip",
        "client_meta",
        "idle_client_meta",
    })

    def __init__(self) -> None:
        self._subscribers: set[asyncio.Queue] = set()
        # Bound in subscribe(), deliberately not here and not in
        # publish_nowait() -- see the class docstring's note on thread safety.
        self._loop: asyncio.AbstractEventLoop | None = None

    def subscribe(self, q: asyncio.Queue) -> None:
        if self._loop is None:
            try:
                self._loop = asyncio.get_running_loop()
            except RuntimeError:
                pass  # no running loop on this thread -- leave unbound
        self._subscribers.add(q)

    def unsubscribe(self, q: asyncio.Queue) -> None:
        self._subscribers.discard(q)

    @property
    def subscriber_count(self) -> int:
        return len(self._subscribers)

    def publish_nowait(self, event: dict) -> None:
        """Publish an event. Sensitive keys are stripped (denylist).

        Each subscriber gets a copy. Full subscriber queues drop on back-pressure
        rather than block the publisher (worker_loop must stay responsive).

        Safe to call from any thread. See the class docstring.
        """
        safe_event = {k: v for k, v in event.items() if k not in self.REDACTED_KEYS}
        if self._loop is None:
            # No subscriber has ever connected (subscribe() is the only
            # place _loop gets bound) -- self._subscribers is therefore
            # necessarily empty, so there is nothing to deliver to and no
            # thread-safety question to answer either way.
            self._deliver(safe_event)
            return
        try:
            on_loop = asyncio.get_running_loop() is self._loop
        except RuntimeError:
            on_loop = False
        if on_loop:
            self._deliver(safe_event)
        else:
            self._loop.call_soon_threadsafe(self._deliver, safe_event)

    def _deliver(self, safe_event: dict) -> None:
        for q in list(self._subscribers):
            try:
                q.put_nowait(safe_event)
            except asyncio.QueueFull:
                log.warning("event_bus subscriber queue full — dropping event")


def _pid_is_alive(pid: int, kill_fn: Callable[[int, int], None] | None = None) -> bool:
    """Defensive check: is pid currently alive on this host?"""
    fn = kill_fn or os.kill
    try:
        fn(pid, 0)
        return True
    except ProcessLookupError:
        return False
    except PermissionError:
        return True  # exists but not ours - conservatively treat as alive


# Multi-slot refactor PHASE-0 (resident-registry scaffold). The manager today
# runs a single-sidecar invariant (one model loaded at a time); the eventual
# multi-slot work needs a per-model resident registry so >1 sidecar can be
# tracked concurrently. This constant PINS the registry to exactly ONE resident
# for Phase-0 so runtime behaviour is byte-for-byte identical to the deployed
# v0.3.8 single-sidecar manager. Phase-1 (dispatcher / driver-tasks / LRU-evict
# / multi-spawn — explicitly OUT of Phase-0 scope) is the place that raises this
# and migrates the live FSM state onto the registry behind its own concurrency
# tests. Do NOT bump this in Phase-0.
MAX_PARALLEL_SIDECARS = 1

# Max times the dispatcher re-queues an unroutable slot (all
# residents busy, no idle victim to evict) before failing its future (a 503-
# equivalent) so an unroutable slot can't busy-loop the dispatcher / starve.
# The fixed 50 (~2.5s at the backoff below) starved the
# "model fits, residents just busy" scenario -- retired in
# favor of a DERIVED cap, see _max_busy_defers.

# Named (was a hardcoded 0.05 in _requeue_after_backoff) — byte-identical value.
_DISPATCH_DEFER_BACKOFF_S = 0.05

# Cap>=2 engine-stall-detector parity: the cap<=1 idle-dead
# sweep gets its ~50ms tick cadence for free from worker_loop's own dispatch
# loop; the cap>=2 idle-liveness sweep is a standalone task with no other
# reason to tick fast, so its cadence is a deliberate value, not a side
# effect. 2s closes the "died while idle" reactive-discovery gap (previously:
# not noticed until the next request routed onto it, or an unrelated idle
# timeout eventually reached the teardown path) without material overhead.
# The 2s value is a deliberate choice.
_MULTI_ENGINE_IDLE_LIVENESS_SWEEP_INTERVAL_S = 2.0

# Bounded budget for _defer_admission_window. Provisional -- no profiling basis
# yet, chosen only to stay well under _DISPATCH_DEFER_BACKOFF_S's own 50ms cadence
# times a few iterations, so a real cross-model claim gets several chances to land.
# This budget is the ANTI-STARVATION guarantee for the INCUMBENT resident's own
# backlog (it can never be deferred past RETRIES x INTERVAL_S) -- it is NOT the staleness grant
# (which protects a repeatedly-EVICTED waiter, the opposite direction) and does not
# replace the staleness-grant protection defined below.
_DEFER_ADMISSION_RETRIES = 3
_DEFER_ADMISSION_INTERVAL_S = 0.01

# Staleness grant window. Provisional, no profiling basis -- a deliberately
# distinct quantity from max_other_model_wait_s (that measures QUEUE wait-time
# for a never-yet-served slot; this measures RESIDENT-side elapsed time since a
# client was LAST evicted after already being served at least once -- reusing
# the other config would let either change silently retune the other).
_STALENESS_GRANT_THRESHOLD_S = 20.0
_STALENESS_GRANT_WINDOW_S = 60.0
_STALENESS_GRANTS_MAX = 256

# Fast Lane claim registry bound (guards memory use). Sized to
# match a case of 100 rank-9 claims followed by one rank-0 claim, not
# independently profiled -- same "no profiling basis"
# posture _STALENESS_GRANT_THRESHOLD_S already documents above.
_CLAIMS_MAX = 100
# TTL-expiry release condition. PLACEHOLDER: the value below is not
# derived from any measurement -- this is a
# placeholder, not a tuned value.
# Deliberately its own constant, not a reuse of max_normal_wait_s (that one
# is reserved for the unregistered-traffic floor, a different
# mechanism, different population).
_FASTLANE_CLAIM_TTL_S = 1800.0

# The VRAM-fit / evict-pending defer path waits on an ASYNC resident
# teardown to free VRAM, or on a still-ACTIVE/GRACE blocker to become
# idle-evictable — both far slower than the "all residents transiently busy"
# defer above. A LONGER backoff keeps the nvidia-smi re-probe rate ~1/s while
# re-routing within ~1s of the freed VRAM appearing; the cap is SIZED from the
# grace config so a slot queued behind a grace-holding blocker survives a full
# grace cycle (+ teardown margin) before it 503s (see _max_vram_defers).
_VRAM_DEFER_BACKOFF_S = 1.0
_VRAM_DEFER_TEARDOWN_MARGIN_S = 60.0   # slack for SIGTERM + KV-save after grace
_VRAM_DEFER_MIN_DEFERS = 60            # >= ~60s window even at grace_seconds=0
_VRAM_DEFER_MAX_DEFERS = 1800          # clamp: a pathological grace config can't
                                       # make a slot defer for days
_VRAM_DEFER_RETRY_AFTER_S = 10         # HTTP Retry-After on genuine exhaustion

# OOM-requeue: the park cadence for a
# requeued-on-OOM slot's background retry-wait. Long relative to the busy/
# VRAM-defer backoffs above -- a real _make_room_signal wake short-circuits
# it, so this is only the lost-wake backstock, never the
# routine advance. Named/injectable so tests never wait the real interval.
_OOM_REQUEUE_POLL_S = 30.0
# After a REAL wake, swallow further
# notifies for this long so a burst of near-simultaneous frees collapses to
# exactly ONE retry attempt. Tests inject ~0.
_OOM_REQUEUE_SETTLE_S = 0.25

# Spawn-reclaim-barrier re-gate cadence. On a VRAM-only refusal with
# a bounded reclaim already in flight, the barrier re-runs the FULL safety gate
# every this-many seconds (or on every watched task completing, whichever
# first) until either the gate clears or spawn_reclaim_wait_max_s' absolute
# deadline (computed once at entry) is reached. 2.0s keeps the re-gate cost
# (a fresh manifest read + up to three nvidia-smi calls, each 5s-timeout) well
# under the tick itself in the common case.
_SPAWN_RECLAIM_REGATE_TICK_S = 2.0
# Cap for _reasoning_effort_mismatch_warned, same
# value/shape as _REASONING_BUDGET_WARN_CAP in api/chat_completion.py.
_REASONING_EFFORT_MISMATCH_WARN_CAP = 64
# The over-eviction guard is the per-card
# pending-reclaim accounting (_pending_reclaim_mib / _vram_admits_locked credit_pending),
# NOT a fixed inter-eviction settle timer. Raising the settle to a
# teardown-scale value would not help, since a fixed settle would BLOCK a necessary
# multi-victim eviction long enough to false-503 at the minimum defer budget.
# So there is intentionally NO settle timer: the accounting evicts
# exactly as many victims as the need requires (credit_pending=False on each pass ->
# evict; each eviction credits its reclaim so the next pass stops the instant enough is
# pending), immediately and never more.

# A one-card (split_mode none) model still leaves roughly 1.3 GB of CUDA context
# on every card it is NOT placed on; its weights figure does not include that
# (see docs/PLACEMENT_AND_CORESIDENCE.md, the section on the context left on the
# other card). The reclaim-first decision keeps this much free on each other
# card, on top of the safety floor, before it places a model on one card.
OTHER_CARD_CUDA_RESIDUE_MIB = 1300


class ReclaimFirstChoice(NamedTuple):
    """Result of ``_reclaim_first_card_locked``: the one card the model is
    placed on, the idle VRAM on that card that an unload would reclaim, the
    VRAM already on its way back there (unloads in flight), and the MiB that
    still has to be unloaded for the model to fit."""

    card: int
    reclaimable_mib: int
    pending_mib: int
    needed_mib: int


# Bounded poll interval for the cap<=1 fan-out drain's
# continuous rider-admit. The drain wakes on EITHER a slot completion OR this
# timeout, so a same-model rider that arrives mid-burst (after the one-shot
# admit already ran, while a --parallel slot is still free) joins within this
# bound instead of waiting out the anchor. Small relative to any real request
# (sub-agents run for seconds); the wake only does a cheap non-blocking
# pop_next while a fan-out is already active.
_FANOUT_ADMIT_POLL_S = 0.1

# Residency: bounded warm-hold applied when a client's
# keep_alive would unload the model NOW (idle_seconds <= 0) BUT the very next
# queued request is the SAME model. Keeps the resident loaded just long enough
# for that queued same-model request to warm-inherit on the next worker tick
# (it is popped within ~_FANOUT_ADMIT_POLL_S), instead of paying a teardown +
# respawn. Never indefinite — if the queued request vanishes before it is
# popped, this window idle-expires and the model tears down normally.
_SAME_MODEL_QUEUED_HOLD_S = 30.0

# The single registry key under which the lone Phase-0 resident lives. Phase-1
# keys residents by ``model_tag``; in Phase-0 the registry holds exactly one
# entry under this sentinel so ``_residents`` is non-empty and shape-correct
# without claiming a model binding the FSM hasn't actually made yet.
_SINGLETON_RESIDENT_KEY = "__phase0_singleton__"
# LRU bound on the (model_tag, session_key) -> resident_key affinity
# map. Module-global (methods reference it as a bare name); ~4096 live sessions
# per process is far past realistic, and overflow just re-homes a cold session.
_AFFINITY_MAX = 4096


class ResidentState(enum.StrEnum):
    """Resident lifecycle. RESERVED_LOADING: budget claimed under
    _registry_lock, sidecar spawning. ACTIVE: serving. GRACE: warm grace window.
    IDLE_EVICTABLE: warm-idle + LRU-evictable. DEAD: driver died/evicted, pending
    deregister. The dispatcher is the SOLE writer of the _residents dict + each
    resident's ``state`` (under _registry_lock); the per-resident driver owns r.*."""

    RESERVED_LOADING = "RESERVED_LOADING"
    ACTIVE = "ACTIVE"
    GRACE = "GRACE"
    IDLE_EVICTABLE = "IDLE_EVICTABLE"
    DEAD = "DEAD"

# LEGAL_TRANSITIONS: ResidentState transition guard
# Prevents impossible state transitions during concurrent access.
_RESIDENT_LEGAL_TRANSITIONS: dict[ResidentState, frozenset[ResidentState]] = {
    ResidentState.RESERVED_LOADING: frozenset({
        ResidentState.ACTIVE,
        ResidentState.DEAD,
    }),
    ResidentState.ACTIVE: frozenset({
        ResidentState.GRACE,
        ResidentState.IDLE_EVICTABLE,
        ResidentState.DEAD,
    }),
    ResidentState.GRACE: frozenset({
        ResidentState.IDLE_EVICTABLE,
        ResidentState.DEAD,
    }),
    ResidentState.IDLE_EVICTABLE: frozenset({
        ResidentState.ACTIVE,
        ResidentState.DEAD,
    }),
    ResidentState.DEAD: frozenset(),  # terminal state
}

def _transition_resident_state(state: ResidentState, new_state: ResidentState) -> None:
    """Validate a resident state transition; log warning instead of raising.

    Self-transitions (new_state == state) are always permitted and return
    immediately. Genuinely illegal transitions are logged as warnings instead
    of raising ValueError, so detached asyncio worker/teardown tasks don't
    strand the resident on a throw. The caller is responsible for actually
    assigning r.state = new_state after this function returns.
    """
    if new_state == state:
        return
    allowed = _RESIDENT_LEGAL_TRANSITIONS.get(state, frozenset())
    if new_state not in allowed:
        log.warning(
            "Illegal resident state transition: %s -> %s (legal targets: %s)",
            state,
            new_state,
            sorted(allowed),
        )
        return
class ResidentPhase(NamedTuple):
    """What phase a resident is in, and how long is left in it.

    ``phase`` carries the ``ResidentState`` VALUE NAMES VERBATIM (a deliberate choice,
    kept stable) -- RESERVED_LOADING / ACTIVE / GRACE / IDLE_EVICTABLE / DEAD.
    It means exactly "what ``r.state`` would say if GRACE were assignable", so the fix
    introduces ZERO new names. The alternative sketch (ACTIVE|GRACE|IDLE|LOADING|DEAD)
    was rejected because ``IDLE``/``LOADING`` are neither ``ResidentState`` nor
    ``SlotState`` spellings -- it would have been a FOURTH vocabulary in a change whose
    whole purpose is to stop having several.

    ``resolved_from`` is provenance: one chokepoint is only worth having if it can say
    WHICH rule fired. Cheap here, and it is what a future reader needs when the phase
    disagrees with their expectation.
    """

    phase: str
    remaining_s: int | None
    resolved_from: str


def _resident_phase(r: "Resident", now: float) -> ResidentPhase:
    """THE single resolver for a resident's phase + its countdown.

    WHY THIS EXISTS. ``ResidentState.GRACE`` has ZERO assignments in this tree, so a
    resident serving out its grace window still reads ``state == ACTIVE``. The live
    grace truth is ``r.grace`` (a real GraceTimer, started by ``_serve_on_resident`` on
    EVERY turn completion regardless of cap) and it was projected only into the
    TOP-LEVEL ``status_snapshot()['grace']`` via ``_resolve_top_level_grace_resident``.
    ``_residents_snapshot`` -- the cap>=2 per-resident view the FE card is built from --
    read none of it, so the card had no input and rendered no countdown.

    ⛔ ORDERING: IDLE_EVICTABLE IS TESTED BEFORE GRACE, so the ``idle_expires_in_s`` alias
    is provably unchanged. The alias derives from this function's ``remaining_s`` (see
    ``_residents_snapshot``); testing IDLE first makes its condition byte-identical to the
    pre-change one (``state is IDLE_EVICTABLE and idle_expires_at is not None``). The two are
    mutually exclusive in practice -- grace EXPIRING is what triggers the idle flip -- so
    this costs the grace fix nothing and removes a whole class of "the alias moved"
    questions.

    ⭐ A RECORDED DECISION, NOT AN OVERSIGHT: THERE IS NO "SERVING BEATS GRACE" GUARD HERE.
    Do not add one back without reading this.

    A resident serving a follow-up inside its grace window reports ``GRACE``, because
    ``r.grace`` is not cleared when the next turn starts. That is deliberate:

    · **It is not a lie.** The grace window governs warm-slot reuse (``GraceTimer``, see
      queue.py) -- during a follow-up the window is not stale, it is exactly what makes the
      reuse legal. "Serving" and "in grace" are two simultaneously true facts; a single
      ``phase`` is a lossy projection of both, and this picks one on purpose.
    · **It does not disagree with the top-level surface.** ``status_snapshot``'s gate is
      ``if grace_resident is not None and active_info is None``, and in this exact window
      ``active_info`` is ALSO None -- so the top level reports grace too. Adding a
      per-resident precedence here would make the two surfaces DISAGREE, which is the
      defect this resolver exists to remove.
    · **No signal exists to implement it anyway.** Measured across pure-grace vs serving on
      the model-keyed (cap>=2) path: ``r.inflight`` is always 0 even mid-turn (and
      ``_current_request_identity``'s own docstring already records that it cannot
      distinguish busy from idle); ``r.active_slot`` is always set and never cleared;
      ``_resolve_top_level_active_slot()`` is None throughout a model-keyed turn, identical
      to pure grace; ``r.inbox.qsize()`` flickers 1->0->1 within one in-flight window and
      would strobe the card. Only ``r.grace.thread_id`` moves, and nothing exposes the
      thread being served for a model-keyed resident.

    ⇒ There is deliberately no ``r.state is ACTIVE and r.inflight`` guard here.
    Measured in the test suite, such a guard evaluates TRUE zero times, and removing it
    changes no test result.

    ⚠ **IT IS NOT DEAD CODE, AND THAT DISTINCTION IS THE WHOLE REASON THIS PARAGRAPH EXISTS**
    (the distinction is between code that is unreachable as deployed and code that is dead).
    ``r.inflight``'s writer chain is LIVE: ``_launch()`` does ``r.inflight.append(s)`` on the
    LAYER-2 per-model parallelism path, pulling riders from ``r.inbox`` up to ``n_parallel``.
    That is gated on a MANIFEST FLAG -- ``llama_server_flags.parallel``.
    ⇒ **UNREACHABLE while ``parallel: 1``, not dead**.

    ⛔ TWO FURTHER POINTS ON THE REACHABILITY OF THE FAN-OUT (exercised by
    the manifest-flip surfaces-agree tests):

    (Code below is cited by SYMBOL + ENCLOSING FUNCTION, never by line number.
    A line number goes stale as soon as the file is edited -- a
    docstring cannot carry a base, and editing it moves the very lines it cites. Several of
    these symbols also occur in more than one function, so the enclosing name is load-bearing,
    not decoration. If you add a reference here, name the symbol and its function.)

    · **The resurrecting reader is the ARGV, not ``manifest_parallel``.** The two are easy to
      confuse. The manifest's ``parallel`` flag is read twice and bound to a DIFFERENT LOCAL
      each time -- ``manifest_parallel`` in ``_process_slot``, ``mp`` in
      ``_run_spawn_safety_gate`` -- and both feed the VRAM SAFETY GATE
      (``all_safety_gates(parallel=...)``). What actually gates the fan-out is
      ``handle.parallel``, pinned by ``spawn_sidecar`` from the ``--parallel`` argv
      (in subprocess_mgr.py) -- whose own docstring says "never a later manifest read".
      Chain: manifest flag -> ``flags_to_argv`` -> spawn argv -> ``handle.parallel`` ->
      ``n_parallel`` -> ``if n_parallel > 1`` (both in ``_serve_on_resident``, NOT the
      same-named pair in ``_process_slot``) -> ``r.inflight.append`` (in ``_launch``).
    · **"Set ``parallel > 1``" is not a valid manifest on its own.** The validator rejects
      it: *"parallel=2 requires kv_unified: true"*. The flip is a PAIR of flags.

    ⭐ THE MANIFEST FLIP, EXERCISED -- a reason that is only reasoned about is
    not a measurement. At ``parallel: 2`` + ``kv_unified: true``: ``handle.parallel``
    reaches 2, the LAYER-2 path IS entered, and ``r.inflight`` reaches 1 on a held ANCHOR
    turn (the firing control -- at ``parallel: 1`` it stays 0). **But in the window this
    guard would have to discriminate -- a resident serving a FOLLOW-UP inside an OPEN grace
    window -- ``r.inflight`` is 0 at BOTH flag values**, because that follow-up is served by
    the ACTIVE_MATCH warm-reuse path and never re-enters ``_serve_on_resident`` at all
    (exactly ONE call is recorded across both turns). The guard could not do its job even
    with the flag flipped.

    ⇒ **SO THERE IS NO GUARD, FOR THE SURFACES-AGREE REASON ABOVE, NOT FOR BEING DEAD.** Measured
    at BOTH flag values, with the guard's precondition INJECTED so it actually fires: the top
    level reports GRACE, this resolver without the guard reports GRACE (agree), and this
    resolver WITH the guard reports ACTIVE (disagree). The guard manufactures exactly the
    surface disagreement this resolver exists to remove, identically at ``parallel`` 1 and 2.
    That reason survives a manifest change; "it never fires" does not.
    (The guard is simply omitted, because it would only create a disagreement between
    the two surfaces.)

    PURE over (r, now): no locks, no clock read of its own. ``_residents_snapshot`` is
    documented LOCK-FREE and this must not change that.
    """
    if r.state is ResidentState.DEAD:
        return ResidentPhase(ResidentState.DEAD.value, None, "r.state")

    if r.state is ResidentState.IDLE_EVICTABLE and r.idle_expires_at is not None:
        return ResidentPhase(
            ResidentState.IDLE_EVICTABLE.value,
            max(0, int(r.idle_expires_at - now)),
            "r.idle_expires_at",
        )

    grace = getattr(r, "grace", None)
    # Report the GRACE countdown ONLY when the resident is
    # IDLE in its grace window (in_grace_loop True and countdown NOT paused by
    # active serving). When actively serving a follow-up, grace.is_paused() is
    # True -- fall through to r.state (ACTIVE) so the countdown is invisible,
    # NOT advancing against real wall-clock. GraceTimer.remaining_s() is used
    # only for its numeric value; the pause mechanism (is_paused / _paused_remaining)
    # is what gates visibility.
    if (
        grace is not None
        and not grace.expired()
        and getattr(r, "in_grace_loop", False)
        and not grace.is_paused()
    ):
        return ResidentPhase(
            ResidentState.GRACE.value, max(0, int(grace.remaining_s())), "r.grace"
        )

    return ResidentPhase(r.state.value, None, "r.state")


# Stream timeout constant (eliminates duplicate 3600.0 literals)
# Previously hardcoded in 7+ places across manager.py
_STREAM_TIMEOUT_S: float = 3600.0  # 1 hour cap on stream waits

# Divergence-capture dump targets (see _log_serve_divergence / _divergence_dump_write).
# Split by value, not rotated: the rare Case-A / extended byte-diff records this
# facility exists to produce are appended here forever, never capped or evicted.
_DIVERGENCE_CAPTURE_FILE = "/var/log/turbohaul/divergence-debug.jsonl"
# The high-volume benign case (length_mismatch: turn count changed, common
# prefix still matched) goes to its own file so its volume can never put the
# valuable file above at risk. Capped (see _DIVERGENCE_BENIGN_MAX_BYTES) --
# losing this one costs nothing, unlike the file above.
_DIVERGENCE_BENIGN_FILE = "/var/log/turbohaul/divergence-debug-benign.jsonl"
# Each length_mismatch entry carries BOTH the incoming and previous FULL
# message sets -- roughly 0.25 MB per entry on a 65k-token
# conversation, and a long run can produce very many of them, so size matters. Left
# indefinitely on, this grows forever with no other bound. 100 MB gives
# several runs' worth of benign history before rolling -- comfortably above
# one run's volume, comfortably bounded (with the single backup below, ~200
# MB worst case) on a host with periodic space cleanup.
_DIVERGENCE_BENIGN_MAX_BYTES = 100 * 1024 * 1024

# Idempotent completion-cache — kills the retry-storm
# RE-DECODE. When a NON-streaming request completes but its client already timed
# out / disconnected, the answer is discarded and the client's byte-identical
# retry re-decodes the SAME answer. We cache the completed result keyed by the
# FULL messages exact-bytes ⊕ thread_id ⊕ model_tag, so an identical retry
# returns it instantly (no enqueue, no engine call). Bounded LRU + TTL.
# Correctness > hit-rate: a MISS always falls through to normal processing; a
# stale / model-mismatched entry is NEVER served (swap-clear + model_tag-in-key
# + TTL guarantee this). Efficacy is gated on the harness resending byte-
# identical retries; if it does not, the exact key simply MISSES (harmless).
_COMPLETION_CACHE_MAX = 64  # max resident cached completions (oldest LRU-evicted)
_COMPLETION_CACHE_TTL_DEFAULT_S = 120.0

# Fast Lane: max resident discovered-address census rows. Overflow
# REFUSES the insert (never LRU-evicts) -- the least-recently-seen address is
# exactly the rare caller an operator is hunting for, so evicting it would be
# a silent lie about what's actually been observed.
_FASTLANE_CENSUS_MAX = 256
# Fallback when self.runtime.fastlane is absent (the config integration not landed
# yet) or unset -- matches FastLaneConfig.census_ttl_hours' own default, so
# behavior is identical once the real config value is present.
_FASTLANE_CENSUS_TTL_DEFAULT_HOURS = 168


def _fastlane_census_key(raw_ip: str) -> str:
    """The census dict's KEY, normalized -- not
    just the comparisons. Two raw forms of the same host (`192.0.2.10` vs
    `::ffff:192.0.2.10`) collapse to ONE census entry instead of two, which
    fixes the duplicate-row bug alongside the false assigned:false/premature
    age-out bugs (all three were the same raw-vs-normalized root cause).
    Returns a STRING (not the ipaddress object normalize_address gives back)
    so `self._fastlane_census: dict[str, dict]`'s existing type contract is
    unchanged -- every caller that already assumes string keys keeps working.

    Falls back to the raw string itself on a ValueError (unparseable input)
    -- mirrors match_fastlane's own fail-soft posture (fastlane.py's
    `except ValueError: return None`); one malformed observed address must
    never crash census observation, it should just not get the normalization
    benefit."""
    try:
        return str(normalize_address(raw_ip))
    except ValueError:
        return raw_ip


def _resolve_fastlane_match(meta: "dict | None", table: list):
    """The ONE resolution step both eviction ordering
    (``_unload_priority_key_for_meta``) and claim designation
    (``_resident_priority_key``) need. Extracted so the two can never
    resolve a different match for the same ``(meta, table)`` -- there is
    exactly one place that answers "is this resident listed, and what is
    its rule_index/rank." Fail-open matches ``match_fastlane``'s own
    posture (returns None on no match, feature off, or any internal
    failure -- never raises).
    """
    return match_fastlane(table, (meta or {}).get("ip"), meta) if meta else None


def _unload_priority_key_for_meta(
    meta: "dict | None", table: list, last_active: float,
) -> "tuple[int, int, int, float]":
    """Pure extraction of ``TurbohaulManager._resident_unload_priority_key``'s
    body (the one deliberate exception to "call, never
    rewrite"): a module-level function taking exactly the three values the
    method needs, with no dependence on ``self`` or a live ``Resident``, so a
    drift test can call it directly against synthetic (meta, table,
    last_active) inputs without constructing a ``Resident``.

    Sort key for ``_lru_idle_unloadable``: unlisted-or-unresolvable residents
    sort first (tier 0, evicted before any listed resident); among listed
    residents (tier 1) a HIGHER rule_index -- lower Fast Lane priority --
    sorts first, and inside one rule_index the numerically larger (worse) tag
    rank sorts first; ``last_active`` only breaks a tie between residents with
    an equal ``(rule_index, rank)``, never crosses tiers or ranks (a tier-0
    resident is always picked over a tier-1 one regardless of recency, and a
    worse tag of one client goes before a better tag of that client however
    recently each was used). rule_index is POSITIONAL (config.py: "LIST INDEX
    IS THE PRIORITY"); nothing about priority is ever stored, only resolved
    against the live ``table`` passed in.
    """
    match = _resolve_fastlane_match(meta, table)
    if match is None:
        return (0, 0, 0, last_active)
    # Within one rule_index the numerically larger (worse) tag rank sorts
    # first under min(); rank is the third slot, so it is only ever decided
    # between residents of the same rule_index, and recency comes last.
    return (1, -match.rule_index, -match.rank, last_active)

# Sentinel resolved onto a single-flight future when the LEADER's flight ended
# WITHOUT a cache write (eviction / timeout / exception / a cap>=2 path that did
# not write). A rider awaiting the flight sees it and falls through to normal
# processing instead of hanging. A plain object (NOT an exception) so a
# released-but-unawaited future never logs "exception was never retrieved".
_FLIGHT_FAILED = object()

# Tool-call reuse: the n_predict=0 KV prefill PROBES
# (_probe_and_save_clean_kv + _shadow_reprefill_and_save) must render the SAME
# tool-definitions preamble the live streaming request renders. Qwen's chat template
# injects `tools` at the FRONT of the prompt, so a tools-LESS probe saves a bin that
# diverges from a tools-BEARING request ~3-40 tokens in -> engine "large stale, CLEAR"
# + full reprefill on EVERY tool turn (byte-proven: C1-toolcall/toolresult pe~82k).
# Forward these knobs VERBATIM from client_meta so the probe tokenizes byte-identically
# to the live request (mirrors chat_completion._STREAM_FORWARDED_KNOBS's tool subset;
# duplicated here — not imported — to avoid the manager<->api import cycle). `tools` is
# NOT in the hash chain (kv_policy untouched), so this changes ONLY prefill rendering;
# a request WITHOUT tools -> every knob None -> payload byte-identical to today (tools-
# less turns cannot regress).
_KV_PROBE_TOOL_KNOBS = ("tools", "tool_choice", "parallel_tool_calls", "function_call", "functions")

# Shadow byte-match self-check (DORMANT observability): max distinct
# threads kept in the per-thread probe stash. Bounded FIFO — the oldest write is
# evicted past this cap so the dict can never leak (see _record/_compare below).
_SHADOW_BYTEMATCH_CAP: int = 64


def _read_completion_cache_ttl_s() -> float:
    """TTL (seconds) for the completion-cache from TURBOHAUL_COMPLETION_CACHE_TTL_S
    (default 120.0). A malformed value falls back to the default — never raise at
    manager construction."""
    try:
        return float(
            os.environ.get(
                "TURBOHAUL_COMPLETION_CACHE_TTL_S", _COMPLETION_CACHE_TTL_DEFAULT_S
            )
        )
    except (TypeError, ValueError):
        return _COMPLETION_CACHE_TTL_DEFAULT_S


@dataclass
class Resident:
    """A single loaded-model sidecar tracked by the manager (PHASE-0 scaffold).

    This is the data structure the multi-slot refactor will key by ``model_tag``
    in ``TurbohaulManager._residents``. In PHASE-0 the registry is pinned to one
    resident (``MAX_PARALLEL_SIDECARS == 1``) and is NOT yet the authoritative
    source for the live FSM scalars — the manager continues to drive the
    deployed single-sidecar attributes (``_active_handle`` / ``_active_slot`` /
    ``_spawn_seq`` / the ``_idle_*`` holder) verbatim. The fields below mirror
    the exact shape Phase-1 will adopt; only ``inflight`` is wired to the live
    list (shared by reference with ``_inflight`` so in-place ``append``/``remove``
    on the manager's fan-out rider set stays visible through the resident view).
    The scalar fields stay at their construction placeholders in Phase-0 and
    become authoritative only when Phase-1 routes the FSM through the registry.

    Fields:
      model_tag:       the model this resident serves (None until Phase-1 binds).
      handle:          the live ``SidecarHandle`` (Phase-1 authoritative).
      port:            the sidecar's listen port (Phase-1 authoritative).
      inflight:        the concurrent fan-out rider Slots (anchor at index 0).
      spawn_seq:       monotonic spawn counter for fixed-port swap detection.
      idle_expires_at: monotonic deadline of the warm-idle hold, if any.
      active_slot:     the anchor Slot currently driven on this resident.
    """

    model_tag: str | None = None
    handle: "SidecarHandle | None" = None
    port: int | None = None
    inflight: list[Slot] = field(default_factory=list)
    spawn_seq: int = 0
    idle_expires_at: float | None = None
    # Stamped ONCE, at reservation, from the same
    # time.monotonic() call that sets last_active_monotonic below -- unlike
    # that field, this one is NEVER overwritten again, so it keeps meaning
    # "when this resident was admitted" for the resident's whole life. Lets
    # _reconcile_orphaned_vram_credit release a stranded credit from
    # registry evidence alone (a resident admitted after the credit was
    # raised now occupies the card), with no VRAM witness needed -- NOT
    # proof the full credited amount returned; see the release-log wording
    # in that function for the precise, observation-only claim.
    reserved_at_monotonic: float = 0.0
    active_slot: "Slot | None" = None
    # Ports the `_grace_tip` discipline from the single-sidecar loop
    # (_process_slot) into the per-resident loop. It tracks whichever Slot's content is ACTUALLY live in
    # the engine's KV right now AND is main-class -- the anchor `slot` until a
    # main-class `matched` follow-up completes, the last such `matched` after
    # that. `active_slot` above is deliberately restored to the anchor after
    # each grace-window promotion (see _serve_on_resident's r.active_slot =
    # slot at the end of its ACTIVE_MATCH branch) -- it remains "the GRACE
    # driver" for teardown bookkeeping, exactly the single-sidecar loop's own reasoning for
    # keeping a separate tip pointer (see that loop's comment on the
    # local `_grace_tip`). Reset to the new anchor at the top of every turn in
    # _drive_resident (same site as rank_client_meta below); reassigned only on
    # a COMPLETED, MAIN-CLASS ACTIVE_MATCH promotion in _serve_on_resident's
    # grace loop -- both gates ported from the single-sidecar loop's own fix and
    # _bin_role gate, not just the bare pointer swap.
    grace_tip: "Slot | None" = None
    # State-migration: per-resident mirrors of the manager-global
    # idle holder (``_idle_handle`` / ``_idle_model_tag``) + the latest keep_alive
    # intent + this resident's own grace/idle timers. At ``MAX_PARALLEL_SIDECARS
    # == 1`` they mirror the singleton manager scalars 1:1 (byte-identical); P1d's
    # dispatcher makes them authoritative per concurrent resident. ``grace``/
    # ``idle`` are constructed + wired in ``TurbohaulManager.__init__`` (the
    # GraceTimer/IdleHotTimer classes live in queue.py, imported — queue.py
    # untouched per the RC guardrail).
    idle_handle: "SidecarHandle | None" = None
    idle_model_tag: str | None = None
    idle_thread_id: str | None = None
    idle_client_meta: dict | None = None
    idle_admission_ctx_len: int = 0
    # The client of the resident's LATEST turn: stamped at reserve, at every turn
    # start, and where a same-thread follow-up served inside the grace window
    # advances grace_tip. Every rank decision (designation, the outrank gate, the
    # victim pool and the idle-eviction key) reads it through _resident_rank_meta.
    # idle_client_meta is only its fallback for an idle resident with nothing
    # stamped: it reflects whoever was served BEFORE parking, which is a
    # stale/wrong identity for a resident now serving a DIFFERENT client
    # (residents are keyed by model_tag, not by client).
    rank_client_meta: dict | None = None
    latest_keep_alive_s: int | None = None
    grace: "GraceTimer | None" = None
    idle: "IdleHotTimer | None" = None
    # True when the grace window is LIVE (started, not yet
    # lapsed). True covers BOTH idle-in-grace AND actively-serving a follow-up.
    # Consumed by _resident_phase to gate the countdown display. Does NOT gate
    # _grace_active_exclusions (that keeps using grace.expired() for grace-window victim
    # protection).
    in_grace_loop: bool = False
    # Grace-loop fairness floor: a different-model waiter that
    # ``_defer_unroutable`` (manager.py) most recently found starved
    # (aged past ``max_other_model_wait_s``) and could not route while
    # THIS resident's grace window was live. Set synchronously, from
    # inside the SAME no-await critical section that already decides the
    # slot is unroutable -- not derived by polling ``_staging``/
    # ``_accept_buf`` from the grace loop, because a capacity-blocked
    # waiter spends most of its wait popped OUT of both buffers while
    # ``_requeue_after_backoff`` backs off (measured: the re-enqueue and
    # the dispatcher's wake-driven re-pop land in the SAME event-loop
    # tick, so an independently-polling reader can never observe the
    # buffer in between). Cleared whenever grace exits for any reason.
    starvation_breakout_candidate: "Slot | None" = None
    # Dispatcher/concurrency fields. Populated under _registry_lock
    # at reservation (state / reserved_need_mib / parallel / main_gpu / port from the
    # in-lock manifest read) and on spawn (booting_pid then handle). ``inbox`` is the
    # dispatcher->driver slot hand-off queue; ``driver_task`` is this resident's
    # _drive_resident task; ``torn_down`` is the lock-guarded exactly-once teardown
    # claim shared by the driver finally + the death-supervisor reaper.
    state: ResidentState = ResidentState.ACTIVE
    reserved_need_mib: int = 0
    # When this resident is evicted for make-room, the MiB credited to
    # _pending_reclaim_mib[main_gpu]; the paired decrement in _unload_teardown's finally
    # reads it back (0 => not a make-room eviction => no decrement, underflow-safe).
    reclaim_credited_mib: int = 0
    booting_pid: int | None = None
    parallel: int = 1
    main_gpu: int = 0
    # The manifest split_mode this resident loaded under. Co-residence
    # is supported ONLY for single-GPU-pinned ('none') models on DISTINCT cards; a
    # layer/row/tensor-split sibling spans all cards (no free distinct card to
    # guarantee) so the cross-resident gate refuse-blinds against it (interim until
    # per-card layer-split accounting lands). Default 'layer' matches the footprint
    # degrade-open default.
    split_mode: str = "layer"
    # PROVENANCE of the two fields above -- True when this resident's
    # admitted main_gpu/split_mode did NOT come from its manifest verbatim, i.e.
    # _reserve_and_start_locked was handed a main_gpu_override/split_mode_override
    # (Fast Lane cross-card relocation; the
    # Nth-engine card pick). main_gpu/split_mode are ALREADY the admitted values
    # -- they are assigned only in the constructor and never mutated -- so this
    # records nothing about the VALUE, only whether anything overrode it. That is
    # precisely the question the argv build (_spawn_for_resident) and the spawn
    # safety gate (_run_spawn_safety_gate) must answer, and which they previously
    # had to INFER from manifest.auto_place. That inference was complete in
    # the original design, when the auto-placer was the only producer, and stopped being
    # complete the moment an override PARAMETER was added that is not gated
    # on auto_place. Same shape and lifecycle as reasoning_budget_override below:
    # decided ONCE at reservation, read at spawn, never recomputed.
    # False = the manifest's own flags govern argv (byte-identical).
    placement_overridden: bool = False
    # The FIRST caller's reasoning_effort, resolved
    # against this model's manifest reasoning_budget ONCE at reservation
    # (_reserve_and_start_locked) and read at spawn (_spawn_for_resident) to
    # override the manifest's own reasoning_budget launch flag -- same
    # shape/lifecycle as main_gpu/split_mode above: decided once, locked for
    # this resident's entire life, never recomputed for a later caller.
    # None = no override (spawn with whatever the manifest declares
    # unmodified) -- either no reasoning_effort was asked, or the manifest's
    # own reasoning_budget is absent/non-positive (nothing to take a
    # fraction of).
    reasoning_budget_override: int | None = None
    # The raw validated reasoning_effort key that PRODUCED
    # reasoning_budget_override above, kept alongside it purely so the
    # first-caller-wins mismatch check (_warn_if_reasoning_effort_mismatch)
    # can compare a later request's key against this resident's locked-in
    # one with a cheap string compare -- no manifest re-read on every warm
    # request. None whenever reasoning_budget_override is None.
    reasoning_effort_locked: str | None = None
    # Per-model sleep_idle_seconds from the manifest. -1 = pin/keep-warm (never
    # idle-unload this model), 0 = unload immediately after request, N>0 = idle
    # timeout in seconds. Default 0 means "use global default" — the driver will
    # fall back to runtime.queue.idle_hot_load_seconds.
    sleep_idle_seconds: int = 0
    last_active_monotonic: float = 0.0
    torn_down: bool = False
    driver_task: "asyncio.Task | None" = None
    inbox: "asyncio.Queue | None" = None
    # Residency tag for per-(role,session) ring.
    # Set on cold restore success to the ring_key of the restored session.
    # Used by warm paths to log would-reload when resident_tag != request_tag.
    resident_state_tag: "tuple[str, str] | None" = None
    # Registry re-key: the dict key this resident is stored
    # under in _residents, and its 0-based per-tag instance ordinal. instance_idx
    # 0 => resident_key == model_tag (NO suffix, so every legacy
    # self._residents.get(model_tag) / del self._residents[model_tag] stays
    # byte-identical for the default single-instance case); instance_idx N>=1 =>
    # resident_key == f"{model_tag}#{N}". Assigned at reservation
    # (_reserve_and_start_locked); the Phase-0 singleton carries
    # _SINGLETON_RESIDENT_KEY.
    resident_key: str = ""
    instance_idx: int = 0
    # Set/cleared under _registry_lock (entry / _await_reclaim_barrier's
    # finally) while this resident's HIT/_route_to path is intercepted for a
    # spawn-reclaim-barrier wait on ANOTHER slot's spawn attempt. A same-tag
    # arrival must not be inboxed (loses disconnect interception for the whole
    # hold) while this is True -- it goes to _defer_unroutable(evict_pending=True)
    # instead, keeping its own bounded budget. Orthogonal to ResidentState: a
    # barriered resident stays wherever it already was in the state machine
    # (typically RESERVED_LOADING), this is not a new state.
    spawn_barrier_active: bool = False
    # The request this engine was started for, when its spawn was refused and the
    # request was handed to another live engine of the same tag instead. The
    # driver must not fail it as an orphan on the way out.
    rerouted_slot: "Slot | None" = None


# === Shadow-diagnosis INSTRUMENTATION helpers ======================
# Cheap, pure, never-raise fingerprints for the SHADOW_SAVE / KV_RESTORE /
# SHADOW_BYTEPARITY structured log lines. They emit LENGTHS + HASHES + offsets
# only (never raw prompt content), and are called ONLY from the off-hot-path
# save/restore/GC code (never on the response TTFT path). Instrumentation only —
# they drive NO decision.
def _fnv1a_64(s: str) -> str:
    """64-bit FNV-1a hex digest of a string. Non-crypto, allocation-light — used
    to fingerprint a think-free / resend region in a log line WITHOUT logging the
    raw content. Never raises (returns 'fnverr' on any failure)."""
    try:
        h = 0xCBF29CE484222325
        for b in s.encode("utf-8", errors="replace"):
            h = ((h ^ b) * 0x100000001B3) & 0xFFFFFFFFFFFFFFFF
        return f"{h:016x}"
    except Exception:
        return "fnverr"


def _chain_fp(chain: "list[str] | None") -> "str | None":
    """Cheap fingerprint of a hash-chain (a list of per-turn hashes), reusing
    _fnv1a_64 above. None in -> None out (distinguishes "no chain at all"
    from an empty-but-known chain, whose fingerprint is _fnv1a_64(''))."""
    if chain is None:
        return None
    return _fnv1a_64("|".join(chain))


def _chain_divergence_index(a: "list[str] | None", b: "list[str] | None") -> "int | None":
    """First index i where a[i] != b[i]. None if one chain is a clean prefix
    of the other (including equal chains, either being empty, or either
    being None) -- there is no divergence to report, only a length
    difference or a genuinely absent chain. Settles, from the log alone,
    whether a DIVERGED restore refusal is a real early-turn rewrite (a small
    index) or a pure append that was wrongly refused (this would return
    None, since a pure append IS a prefix).

    None-safe like _chain_fp above: a saved bin's on-disk meta can carry a
    JSON `null` for hash_chain (key present, value explicitly null) rather
    than the key being absent -- resolve_kv() and the sibling scan-cache
    reader both defend the identical field with `or []`; this must too, or
    one bin with that shape raises out of the per-bin loop and silently
    drops every OTHER candidate bin from consideration for that identity."""
    for i, (x, y) in enumerate(zip(a or [], b or [])):
        if x != y:
            return i
    return None


def _first_diff_offset(a: str, b: str) -> int:
    """First character index at which ``a`` and ``b`` differ, or -1 if they are
    byte-identical. If one is a strict prefix of the other, returns the length of
    the shorter (the offset where the longer one still has bytes). Never raises."""
    try:
        n = min(len(a), len(b))
        for i in range(n):
            if a[i] != b[i]:
                return i
        return -1 if len(a) == len(b) else n
    except Exception:
        return -2


from turbohaul.engine_budget import EngineBudgetInputs, effective_engine_cap


class TurbohaulManager:
    """Top-level orchestrator.

    Responsibilities:
    - Boot reconcile: orphan reap + foreign-GPU detect + state.sqlite slot cleanup
    - Verify binary sha256 pin at boot
    - Accept fresh requests via submit() → push to queue (head if grace match)
    - Expose status_snapshot() for /status endpoint
    - Drive the FSM via worker_loop (skeleton in the initial phase; full streaming in a follow-up phase)
    - Clean shutdown
    """

    # Lag-reducer (SAVE-path THROTTLE). Re-save the clean-prefix
    # KV anchor only once the incoming clean-prefix chain has grown by >= this many
    # turns beyond the saved anchor's n_context_turns. Bounds BOTH the multi-GB re-save
    # cost AND the sawtooth reuse lag to ~this many turns. Documented tunable.
    LAGREDUCER_MIN_GROWTH_TURNS = int(os.environ.get("TURBOHAUL_LAGREDUCER_MIN_GROWTH_TURNS", "1"))  # per-turn re-save (the clean bin IS the always-fresh single copy); env-tunable so the operator owns the SSD-write budget without a redeploy

    # Ceiling-GC: minimum seconds between KV-cache file-GC passes. The
    # GC piggybacks on the park-sweep loop but is THROTTLED to this floor so a
    # scandir of the multi-GB save dir never runs on the 60s park cadence.
    _KV_GC_MIN_INTERVAL_S = 300

    def __init__(
        self,
        boot: BootConfig,
        runtime: RuntimeConfig,
        *,
        spawn_fn: Callable | None = None,
        health_fn: Callable | None = None,
        sigterm_fn: Callable | None = None,
        vram_fn: Callable | None = None,
        gpu_used_mib_fn: Callable | None = None,
        vram_total_mib_fn: Callable | None = None,
        complete_fn: Callable | None = None,
    ) -> None:
        self.boot = boot
        self.runtime = runtime
        # Cache of parsed GGUF attention dims for the dimension-aware
        # KV-fit estimate, keyed by content-addressed blob sha (immutable, so the
        # parse happens at most once per unique GGUF, off the hot spawn path).
        self._attn_dims_cache: dict[str, object] = {}
        # Cache of parsed GGUF tensor-offset expert layout for the MoE
        # RAM-fit gate, same immutable-sha positive-cache pattern as above.
        self._expert_layout_cache: dict[str, object] = {}
        # Warn-once-per-(resident, requested-value)
        # cache for the first-caller-wins mismatch log -- same
        # warn-once-and-cap shape as the analogous cache in
        # api/chat_completion.py, an independent instance for this module's
        # own condition. See _warn_if_reasoning_effort_mismatch.
        self._reasoning_effort_mismatch_warned: dict[str, None] = {}
        # Fast Lane: compiled-rule-table cache. Keyed on
        # id(self.runtime.fastlane) so a `put_config` replace of self.runtime
        # invalidates the cache STRUCTURALLY (a new RuntimeConfig object has a
        # new id, whether or not its .fastlane sub-object also changed) rather
        # than relying on every config-mutation call site remembering to call
        # invalidate_fastlane(). Four existing queue settings already made the
        # mistake this avoids — copied into the queue once at construction and
        # never refreshed, while the endpoint still claims "no restart
        # required". Read the policy live at decision time instead.
        self._fastlane_table_cache: tuple[tuple, list] | None = None
        # Cheap, lock-free, staleness-tolerant HINT for _should_defer_admission
        # -- the SAME listed_waiter_model_tags() snapshot _route_or_reserve already
        # computes under queue._lock, stashed as a side effect so the
        # per-resident driver can read it without awaiting queue._lock itself. Never
        # trusted for a decision beyond "is it worth opening a window" -- the actual
        # eviction/swap decision always stays with the properly-locked path.
        self._cross_model_defer_hint: "frozenset[str]" = frozenset()
        # Normalized-address -> monotonic eviction timestamp, re-armed on
        # EVERY eviction of that identity (not just the first) -- targets a
        # client caught in a served-briefly/evicted/re-queued/evicted-again
        # cycle, not merely "queued a long time ago" (max_normal_wait_s's own
        # job, and structurally unable to serve a LISTED client regardless).
        # Mirrors _fastlane_census's shape: bounded,
        # fails CLOSED on overflow (existing entries kept, new distinct
        # identities refused). NEVER lives on the Resident -- eviction is
        # exactly the moment _begin_unload_locked destroys the object this
        # state would otherwise need to live on.
        self._fastlane_staleness_grants: dict[str, float] = {}
        # Re-gate: refused-at-capacity counts, by reason (currently
        # one key, "capacity") -- same dict[str, int]-by-reason shape as
        # queue.py's own _fastlane_refusal_counts. A silent capacity refusal
        # here is exactly the failure this is meant to make visible; the
        # rarer it fires, the less likely anyone is watching, the more this
        # counter is worth. Scope: ONE increment, no behaviour change.
        self._fastlane_staleness_refusals: dict[str, int] = {}
        # Per-card VRAM (MiB) pledged-to-free by in-flight evict
        # teardowns (bumped in _begin_unload_locked, dropped in _unload_teardown's
        # finally). The over-commit make-room path CREDITS this so N concurrent misses
        # don't each evict a resident for VRAM a sibling teardown is already freeing.
        # The ACTUAL reserve gate NEVER credits it (never spawn on not-yet-free VRAM).
        self._pending_reclaim_mib: dict[int, int] = {}
        # The model_tag of the reservation currently in flight, or None.
        # Written ONLY by the ``_reserving`` context manager -- see its docstring for
        # why the clearing is the contract. Read by ``status_snapshot``'s swapgap
        # branch to name the incoming model during the window in which it has no
        # Resident object yet.
        self._reserving_model_tag: "str | None" = None
        # Per-card monotonic instant the credit was
        # last RAISED (overwritten, not accumulated, on every additional
        # contribution -- deliberately the LATEST raise, the more
        # conservative choice when a card's credit accumulates across more
        # than one eviction before a reconcile runs). No explicit clearing
        # needed elsewhere: once _pending_reclaim_mib[card] returns to 0 the
        # reconciler's own `mib > 0` candidates filter already excludes the
        # card regardless of what this dict still holds, and the next real
        # raise overwrites the stale value before it is ever consulted.
        self._pending_reclaim_raised_at: dict[int, float] = {}
        # Per-card strong refs to the tasks that OWN a
        # decrement of _pending_reclaim_mib[card] -- _unload_teardown and
        # _late_vram_reconcile, registered the moment each is spawned,
        # self-discarding on completion (mirrors _bg_tasks/_spawn_bg's own
        # strong-ref pattern). A card's credit is safe to reconcile ONLY
        # when this set is empty: neither existing releaser has a live claim
        # on it. See _reconcile_orphaned_vram_credit.
        self._card_release_tasks: dict[int, set[asyncio.Task]] = {}
        # Dispatcher wake: set by the queue's on_enqueue hook -- fired by
        # enqueue(), enqueue_tail() and enqueue_head() right after a slot
        # lands. enqueue_head() is the unroutable/evict-pending requeue's
        # re-entry point; enqueue_tail() is the designated-victim backlog's
        # own re-entry point. _dispatch_loop
        # waits on this instead of an unconditional poll; the wait is bounded
        # (asyncio.wait_for) so a hook gap degrades to today's poll cadence
        # rather than hanging.
        self._dispatch_wake = asyncio.Event()
        # Fast Lane claim registry. Keyed
        # (fastlane_rule, model_tag) -- see
        # _fastlane_claim_key. Population is bounded by _CLAIMS_MAX with
        # worst-priority overflow eviction, never unbounded growth.
        self._fastlane_claims: "dict[tuple[str, str], dict]" = {}
        # Slots already handed
        # to a resident inbox but NOT yet being served. Deliberately a
        # SEPARATE registry from _fastlane_claims above and NOT an extension
        # of the claim's lifetime (a deliberate choice): the whole-time
        # duty and the "rank" field are carried on the QUEUE
        # TAB, while the claim record carries neither. Keyed by
        # slot_id; entries are pruned on read by
        # _handed_off_waiting_rows(), which is the only reader.
        self._handed_off_waiting: "dict[str, Slot]" = {}
        # The registry now records ALL handed-off traffic,
        # not only Fast Lane claimants, so /status is no longer the only pruner
        # (see _note_handed_off_waiting). Watermark for the amortised sweep.
        self._handed_off_prune_at: int = _HANDED_OFF_PRUNE_FLOOR
        # Refused/evicted-at-capacity counts, by reason -- same
        # dict[str, int]-by-reason shape as _fastlane_staleness_refusals
        # above and queue.py's own _fastlane_refusal_counts.
        self._fastlane_claim_refusals: "dict[str, int]" = {}
        self.queue = TurbohaulQueue(
            staging_max=runtime.queue.staging_queue_depth,
            acceptance_max=runtime.queue.acceptance_buffer_max,
            max_consecutive_same_model=runtime.queue.max_consecutive_same_model,
            max_other_model_wait_s=runtime.queue.max_other_model_wait_s,
            main_lane_reserved=runtime.queue.main_lane_reserved,
            main_lane_identity_keys=tuple(runtime.queue.main_lane_identity_keys),
            on_enqueue=self._dispatch_wake.set,
        )
        self.grace = GraceTimer(
            grace_seconds=runtime.queue.grace_seconds,
            max_extensions=runtime.queue.max_grace_extensions,
        )
        self.idle = IdleHotTimer(idle_seconds=runtime.queue.idle_hot_load_seconds)
        self._active_handle: SidecarHandle | None = None
        self._active_slot: Slot | None = None
        # Per-model concurrent dispatch (Design #1): the rider set for the
        # CURRENT anchor cycle when the active model's manifest declares
        # parallel>1. Element 0 is the anchor. Mutated ONLY by worker_loop
        # (append at fan-out admit, remove at per-rider drain, cleared after the
        # drain barrier); read await-free by status_snapshot. Stays [] for
        # parallel:1 models, so the single-mutator discipline above (no lock) is
        # preserved verbatim — worker_loop remains the sole writer and routes
        # only ever set their OWN slot.stream_done_event.
        self._inflight: list[Slot] = []
        # Manager-level idle holder (model warm post-grace).
        # When grace expires without a thread match, the sidecar is NOT
        # torn down -- it migrates here and stays alive for idle_seconds.
        # Next slot of same model_tag inherits the handle; different
        # model_tag tears it down first.
        self._idle_handle: SidecarHandle | None = None
        self._idle_model_tag: str | None = None
        self._idle_expires_at: float | None = None
        # Track thread_id through idle holder so the
        # C++ engine can save KV cache during idle teardown (it needs a
        # valid thread_id to do it — empty thread_id returns do_it=False).
        self._idle_thread_id: str | None = None
        # Track admission_ctx_len through idle holder so KV save
        # uses the admission-time context length for prompt_len in metadata.
        self._idle_admission_ctx_len: int = 0
        # Track client_meta through idle holder so warm-inherit can
        # restore session_id and other identity labels on cold-start requests.
        # Initialized to None to avoid AttributeError when no idle holder exists yet.
        self._idle_client_meta: dict | None = None
        # Latest request's keep_alive intent across the ACTIVE_MATCH
        # chain on a single warm slot. Reset per anchor (_process_slot entry);
        # captured on ACTIVE for the anchor and on each ACTIVE_MATCH promotion
        # of a matched follow-up; consumed (cleared) at grace→idle entry. The
        # "latest request wins" rule mirrors Ollama keep_alive semantics
        # (timer resets on request receipt, not on response completion).
        # Without this, stale keep_alive from request N leaks into IDLE_HOT
        # window computed after request N+M.
        self._latest_keep_alive_s: int | None = None
        # /status metrics counters for client-disconnect
        # eviction observability. Updated in worker_loop's is_evicted branch.
        self._unload_count: int = 0
        self._last_unloaded_at_iso: str | None = None
        # Classifier observability: per-event decision counts +
        # forced-clean-restore total + last decision, surfaced on /status. PROVES
        # "Turbohaul determines each event" (continuation / user-message /
        # compression / sub-agent / guard-skip) and whether it forced the clean bin.
        self._kv_classifier_counts: dict[str, int] = {}
        self._kv_classifier_forced: int = 0
        # Distinct COLD-path counter. forced_clean_restores is WARM-
        # only (set in _maybe_force_clean_restore); a working wave-return (cold clean-
        # restore in _restore_slot_kv) leaves it 0, so it is invisible. This counter
        # makes the cold clean-restore PROVABLE in PL's smoke.
        self._kv_classifier_wave_return: int = 0
        self._kv_classifier_last: dict | None = None
        # Last emitted
        # per-request structured identity dict (see _emit_request_identity),
        # surfaced on /status so the FE can render it live. DISPLAY/
        # OBSERVABILITY ONLY — read-only surface of the class the manager
        # already resolved; drives no decision.
        self._last_request_identity: dict | None = None
        # Same identity dict as above, keyed per-resident so /status.residents[]
        # can show each card its OWN last request instead of every card flip-flopping
        # to whichever resident served most recently on the single global. Keyed by
        # model_tag, exactly like `live_generations` one line of intent below.
        # LIFETIME (deliberately NOT the same as the global above): pruned on FULL
        # eviction only, mirroring live_generations.pop(tag, None) (live_monitor.py)
        # -- populated on request, KEPT while the resident is ACTIVE **or** IDLE
        # (still present in self._residents), popped only when the resident is torn
        # down and removed from self._residents. NEVER pop this on an idle transition
        # -- an idle-but-still-resident engine must keep showing what it last served;
        # popping there would silently blank every idle card's last-request strip.
        # The top-level global above is never pruned at all (a single entry, so
        # never-clearing costs nothing); this dict grows one small entry per distinct
        # model_tag ever served (bounded in practice, ~100 manifest tags = kilobytes)
        # -- same principle of not losing the operator's answer, different cost shape,
        # hence the different lifetime.
        self._last_request_identity_by_model: dict[str, dict] = {}
        # Fast Lane: discovered-address census. address -> record dict
        # (first_seen/last_seen/request_count/served_count/classes/models/
        # thread_ids). `assigned`/`ambiguous` are DERIVED at read time in
        # fastlane_census_snapshot(), never stored, so a rule-list edit is
        # reflected immediately without a census rebuild. Bounded at
        # _FASTLANE_CENSUS_MAX; overflow REFUSES new distinct addresses (see
        # _fastlane_census_observe) rather than LRU-evicting one.
        self._fastlane_census: dict[str, dict] = {}
        self._fastlane_census_overflow_refused: int = 0
        # Rate-limits the overflow log.error to once, not once per refused
        # request.
        self._fastlane_census_overflow_logged: bool = False
        # Requests with no `ip` in client_meta (today: only the
        # /v1/embeddings path, which never calls _derive_client_meta_identity)
        # would otherwise manufacture a null-address census row. Counted so
        # the gap is visible instead of silently absent.
        self._fastlane_census_skipped_no_ip: int = 0
        # Idempotent completion-cache + single-flight.
        # _completion_cache maps completion-key -> (result, expiry_monotonic); an
        # OrderedDict so the oldest is LRU-evicted via popitem(last=False) once it
        # exceeds _COMPLETION_CACHE_MAX. _completion_inflight maps completion-key ->
        # the LEADER request's Future, so a concurrent byte-identical retry rides
        # the first flight (single-flight dedupe) instead of launching a 2nd decode.
        # SINGLE-MUTATOR NOTE: both dicts are touched ONLY on the event loop —
        # written by _process_slot (worker_loop) at completion, by submit_and_wait
        # on admission, and cleared on the teardown/swap paths — all on the one
        # loop with no await between check-and-register, so NO lock is needed (same
        # discipline as _active_*/_inflight). NON-STREAMING ONLY: the streaming
        # path (submit_for_streaming) never reads or writes either dict.
        self._completion_cache: OrderedDict[str, tuple[dict, float]] = OrderedDict()
        self._completion_inflight: dict[str, asyncio.Future] = {}
        self._completion_cache_ttl_s: float = _read_completion_cache_ttl_s()
        # Shadow byte-match self-check (DORMANT observability). Measures the
        # ONE assumption the shadow-reprefill reuse hinges on: does the manager's THINK-
        # FREE assistant-turn strip byte-match the harness's think-STRIPPED resend of the
        # SAME turn next turn? Turn N stashes its think-free assistant hash; turn N+1
        # admission compares the resent assistant turn against it. PURE read+hash+log+
        # count — writes NO KV, changes NO routing/restore/admission/save decision.
        # Bounded FIFO (evict oldest write past _SHADOW_BYTEMATCH_CAP) so it cannot leak.
        self._shadow_bytematch_probe: dict[str, dict] = {}
        self._shadow_bytematch_counts: dict[str, int] = {}
        # Frozen-prefix re-prefill: per-thread `tools`
        # fingerprint (see _classify_tools_fingerprint). PURE read+hash+log --
        # never gates a routing/restore/admission/save decision, exactly the
        # shape intended: observability regardless of cause.
        # Bounded FIFO (evict oldest write past _TOOLS_FINGERPRINT_CAP) so it
        # cannot leak across a long-running manager process.
        self._tools_fingerprint_by_thread: dict[str, dict] = {}
        # Option A shadow-reprefill (SAVE-side; INERT unless env
        # TURBOHAUL_SHADOW_REPREFILL). Per-(port, thread_hash) save-in-flight Lock
        # so a shadow reprefill+save can never overlap the next turn reading a
        # half-written shadow bin for the same thread (atomic tmp+os.replace already
        # protects readers; the lock serialises the WORK vs the single series).
        # Bounded (UNHELD locks pruned past _SHADOW_BYTEMATCH_CAP) so it cannot leak.
        # Counts (saved / skipped_* / reprefill_post_failed) surfaced on /status.
        self._shadow_reprefill_locks: dict[tuple, asyncio.Lock] = {}
        self._shadow_reprefill_counts: dict[str, int] = {}
        # Freshness: the FRESHEST think-free shadow source
        # (think-free `messages` ready to re-save) from the most recent per-turn shadow
        # save, keyed by {thread_id, model_tag, port}. Updated by _shadow_reprefill_and_
        # save on EVERY reconstructable main/grace turn (so it tracks the LATEST turn's
        # slot, not the stale anchor — the outgoing slot object is nulled at swap time).
        # _shadow_save_at_swap reads it at the model-swap teardown to re-save a fresh
        # shadow AS CLOSE TO SIGTERM as possible. Re-keyed per (thread_id, model_tag)
        # so an intervening OTHER-model save can't clobber the outgoing
        # thread's source; bounded evict-oldest (cap 64). INERT unless SHADOW_REPREFILL.
        self._last_shadow_src: OrderedDict[tuple, dict] = OrderedDict()
        # Shadow-diag (INSTRUMENTATION-ONLY): per-(thread_id, model_tag)
        # think-free recon text for SHADOW_BYTEPARITY, so candidate (d) survives
        # intervening shadow saves of OTHER threads (on a swap-back a 27b source is not
        # clobbered by 35b sub-agent saves the way the single-global _last_shadow_src
        # is). Bounded (evict-oldest). NEVER read by _shadow_save_at_swap / any
        # decision — pure observability; _last_shadow_src stays untouched.
        self._byteparity_recon_by_key: dict[tuple, str] = {}
        # Previous-turn state for divergence capture on warm serve.
        # Keyed by (thread_id, model_tag). Gated by TURBOHAUL_DIVERGENCE_DEBUG=1 (OFF by default).
        self._divergence_prev: dict[tuple, dict] = {}
        # Shadow-restore PREFERENCE (RESTORE-side; INERT unless env
        # TURBOHAUL_SHADOW_RESTORE_PREFER). Counts which bin the ONE warm forced-restore
        # seam preferred: {preferred: chose the think-free .shadow bin (a longer valid
        # prefix -> next decode strict-extends), clean_fallback: no valid+long-enough
        # shadow -> today's clean anchor}. Belt observability only; drives NO decision —
        # the force gate + prefix-validity + owner checks are UNCHANGED.
        self._kv_shadow_restore_counts: dict[str, int] = {}
        # TOOL-tail restore skip: counts of forced/cold restores
        # SKIPPED because their divergent tail beyond the common prefix was tool-opaque
        # (hash-invisible -> the chain "match" is untrustworthy). {warm: the
        # _maybe_force_clean_restore force path, cold: the _restore_slot_kv wave-return
        # path}. Obs-only belt; the guard's real effect is the force=False / POST-skip
        # itself. Default OFF (TURBOHAUL_TOOLTAIL_RESTORE_SKIP) now that Fix B byte-matches
        # the covered tool region; flag-on is the emergency A/B-rollback floor.
        self._kv_tooltail_skip_counts: dict[str, int] = {}
        # STALE-tail restore skip: counts of WARM forced restores SKIPPED because
        # the resident warm state had more turns than the incoming request itself
        # (see _staletail_restore_skip_enabled). Obs-only belt; the guard's real
        # effect is the force=False / POST-skip itself. Default ON.
        self._kv_staletail_skip_counts: dict[str, int] = {}
        # I/O optimization: cache of SLOT_SAVE_DIR .json sidecar scans so
        # the O(N) listdir+load loop is NOT repeated on every probe/restore call.
        # _kvcache_dir_mtime tracks the last known SLOT_SAVE_DIR mtime at scan time;
        # the cache is invalidated whenever a write/delete in SLOT_SAVE_DIR occurs.
        self._kvcache_dir_mtime: float | None = None
        self._kvcache_clean_bins: dict[tuple, tuple[int, str, list, int] | None] = {}
        self._kvcache_shadow_bins: dict[tuple, tuple[int, str, list, int] | None] = {}
        # Per-key "already resolved hydrate for this key during
        # the current RAM-empty gap" latch. Cleared by _kvcache_scan_cache_
        # invalidate (the SAME chokepoint every RAM-tier write/delete/rename
        # already calls) — so it can never outlive the RAM-empty condition it
        # exists to short-circuit, and can never permanently suppress a bin
        # that a later real save legitimately un-stales.
        self._kvcache_hydrate_attempted: dict[tuple, bool] = {}
        # port -> CLEAN PREFILL PROBE EVIDENCE: value =
        # CleanPrefillEvidence(count, chain_fp, arm) — the engine-reported
        # think-free render count BOUND to the probed context's turn-hash
        # fingerprint. Written only by the strip/prefill probes from the
        # engine's own reply; read only when choosing how far a save should
        # reach and whether a force_clean save may stamp clean. Deliberately
        # absent rather than stale: the probe removes the entry whenever it
        # cannot obtain a fresh count, so a save can tell "no clean boundary
        # is known" apart from "the boundary is N".
        self._clean_prefill_tokens: dict[int, CleanPrefillEvidence] = {}
        # Poison guard: port -> set of context
        # chain-fps whose clean-stamped bin PROVED POISON (the engine's own
        # heartbeat reported reused-to-zero on the restored bin) and was
        # retired. A force_clean save whose save-context fp is in the set
        # declines the stamp (KV_DECLINE_POISON_REPROBE) instead of
        # re-stamping a bin the engine will just discard again. WRITTEN by the
        # reuse-zero retirement; a fresh probe that re-records evidence
        # for a context DISCARDS that fp (the context was re-proven); CLEARED
        # whole on engine spawn, alongside the register (a new process has no
        # memory of the old slot's KV).
        self._poisoned_chain_fps: dict[int, set] = {}
        # port -> filename of the last KV bin this
        # process RESTORED into that engine (set by the restore paths).
        # Initialized here so the reuse-zero retirement can always look it
        # up — a guaranteed instance attribute, not a lazy one (the
        # retirement reads it via getattr with a default anyway, but a
        # guaranteed init keeps the retirement path total and testable).
        self._last_restored_bin: dict[int, str] = {}
        # Disk-at-unload: live in-VRAM clean-anchor registry.
        # port -> {thread_hash, model_tag, pid, chain, prompt_len, stamp}. Written by
        # _probe_and_save_clean_kv after EVERY successful per-turn normalizing
        # prefill (which physically overwrites the engine slot -> keyed by port).
        # Read by _maybe_force_clean_restore (staleness/ownership gate) + the
        # classifier overlay. pid stamps the sidecar generation: a respawned engine
        # on the same port has a different pid -> record automatically FOREIGN (no
        # invalidation hooks). NEVER persisted: restart = empty = cold path.
        self._kv_vram_anchor: dict[int, dict] = {}
        # SHADOW-DIAGNOSIS instrumentation (INSTRUMENTATION ONLY):
        # per-cold-restore + byte-parity counters surfaced under /status.shadow_diag
        # so a forcing-full swap-back CONCRETELY names WHY (candidate a/b/c/d). These
        # drive NO decision — every writer is a best-effort log/counter belt.
        #   restores:   which bin the cold _restore_slot_kv chose per pass
        #               (chose_shadow / chose_clean / chose_clean_withthink / fresh).
        #   byteparity: manager reconstructed-think-free vs harness resend region
        #               (match / diverge / no_recon_src) — shows whether a saved bin
        #               BYTE-DIVERGES from the resend, as distinct from a wrong-bin pick.
        #   evictions:  a `.shadow` bin reaped by the ceiling/over-cap GC
        #               (shadow_evicted) — makes a saved-but-EVICTED bin observable: the
        #               unprotected shadow is deleted FIRST under over-cap while
        #               pinned dead-session clean anchors hold the floor.
        self._shadow_diag_counts: dict[str, dict[str, int]] = {
            "restores": {},
            "byteparity": {},
            "evictions": {},
        }
        # Latest ceiling-GC snapshot (total/over_cap/protected-bin bytes + the
        # top protected thread_hashes that hold the 64GB floor). Written once per
        # throttled GC pass by _gc_kv_cache (off the hot path); read into the
        # KV_RESTORE line + /status.shadow_diag.kvgc. None until the first pass.
        self._last_kvgc_snapshot: dict | None = None
        # Background sweeper state-row finalizer counters.
        # Finalizes evictions that landed audit-only on the hot path
        # (deferred state-row write to keep worker_loop off SQLite
        # fsync stall). Sweeper is OFF the hot path — its sync SQL is fine.
        self._slots_finalized_lifetime: int = 0
        self._last_sweep_iso: str | None = None
        self._sweeper_task: asyncio.Task | None = None
        # Cap>=2 idle-engine-liveness sweep task handle. A mutator
        # (calls _begin_unload_locked), not an observer -- shutdown() must
        # cancel it in the same step as _sweeper_task, never grouped with
        # the pure-observer live-poller/live-supervisor tasks.
        self._idle_liveness_task: asyncio.Task | None = None
        # Ceiling-GC throttle clock. Init to NOW so the first file-GC
        # fires one _KV_GC_MIN_INTERVAL_S AFTER startup (never at t=0), which
        # also keeps short-lived unit-test sweeper spins from touching the dir.
        self._last_kv_gc_monotonic: float = time.monotonic()
        # Monotonic throttle for the sweeper-side fingerprint
        # purge (the startup call is unthrottled). 0.0 = never run -> first sweep
        # after enable purges immediately.
        self._last_fp_purge_mono: float = 0.0
        self._worker_task: asyncio.Task | None = None
        # Per-(role,session) ring index + counters.
        # Ring: last-3 newest-overrides-oldest, keyed by (role, session_id) from client_meta.
        # Counters: ring_write, would_reload (warm/cold), residency_mismatch.
        # INERT when TURBOHAUL_DURABLE_RING=OFF (default).
        self._durable_ring_index: dict[tuple[str, str], list[dict]] = {}
        self._durable_ring_counts: dict[str, int] = {}
        # Live inference monitor. Pure-observer plane:
        # worker_loop never reads/writes live_generation/live_output, so the
        # single-mutator FSM invariant is structurally untouched. _spawn_seq is
        # bumped by worker_loop at each _active_handle assignment so the poller
        # can detect a fixed-port (11500) sidecar swap across its httpx await.
        self._spawn_seq: int = 0
        self.live_generation: dict | None = None  # written ONLY by LiveSlotsPoller
        self.live_output = LiveOutputBuffer()      # fed ONLY by the streaming tee
        self._live_poller = None
        self._live_poller_task: asyncio.Task | None = None
        # Per-resident live-inference monitor (cap>=2). The single
        # LiveSlotsPoller above stays the cap<=1 path (byte-identical). At cap>=2 a
        # LiveResidentsSupervisor task polls EACH resident's /slots and writes its
        # generation into ``live_generations`` (keyed by model_tag), mirroring the
        # most-recently-active resident into ``live_generation`` (the back-compat
        # alias status_snapshot + live_stream.py already read). It also caches per-GPU
        # free VRAM off the hot path so status_snapshot can emit ``vram[]`` await-free
        # (status_snapshot is LOCK-FREE and must NEVER call nvidia-smi synchronously).
        self.live_generations: dict[str, dict] = {}   # model_tag -> generation block
        self._vram_free_mib: list[int] | None = None  # per-GPU free MiB (cached ~1Hz)
        # Per-GPU SM utilization %, cached the SAME way (same
        # pollers, same ~1Hz cadence, same None-on-probe-failure degrade) so
        # MAKE_ROOM_STARVED can report it without ever shelling out on the
        # _registry_lock-held path. See live_monitor.py's _refresh_vram.
        self._gpu_util_pct: list[int] | None = None
        # Populated LAZILY, on first use, by
        # _begin_unload_locked -- NOT called here at __init__ time. An eager
        # synchronous probe here is avoided, because
        # subprocess.check_output on a nonexistent
        # nvidia-smi still forks a child and reaps it via a REAL os.waitpid
        # call before raising FileNotFoundError -- verified empirically --
        # which collided with tests that monkeypatch os.waitpid/os.kill
        # BEFORE constructing a TurbohaulManager (e.g.
        # TestCancelDuringLoading), consuming the first scripted waitpid
        # response meant for a LATER, legitimate booting_pid reap check and
        # silently suppressing os.kill. Storing the callable here and
        # calling it lazily on first eviction keeps construction itself
        # side-effect-free, matching every other DI seam in this __init__
        # (spawn_fn/health_fn/sigterm_fn/vram_fn/gpu_used_mib_fn are all
        # invoked later, never at construction). This field is NOT dead: it
        # is already populated by live_monitor.LiveSlotsPoller._refresh_vram
        # (cap<=1, lazy first-tick boot-read) but NEVER by
        # LiveResidentsSupervisor._refresh_vram (cap>=2, only refreshes
        # _vram_free_mib) -- an asymmetry between the two pollers, not a
        # dead field. A host running the supervisor is why
        # /status can show vram_total_mib: null.
        # Populating it lazily here removes the capacity invariant and the
        # orphaned-credit reconciler from depending on that asymmetry
        # entirely; LiveSlotsPoller's own "if is None" lazy-populate simply
        # no-ops once this has already run. The poller asymmetry is
        # a known limitation -- not touched here.
        self._vram_total_mib_fn = vram_total_mib_fn or _read_total_vram_all_mib
        self._vram_total_mib: list[int] | None = None  # per-GPU total MiB
        self._live_supervisor = None
        self._live_supervisor_task: asyncio.Task | None = None
        # Plugin registry boot + periodic health probe.
        # Pure observer, same as the live-inference monitor pair above -- it
        # only reads mgr.boot.plugins.registry and never touches a resident.
        self._plugin_health = None
        self._plugin_health_task: asyncio.Task | None = None
        self._stop_event = asyncio.Event()
        # Removed unused self._lock = asyncio.Lock(). It had
        # zero acquire sites (single-task worker_loop discipline protects
        # _active_handle / _active_slot mutations). If Wave-6 lands a
        # second mutating task, re-add it purposefully and wrap the call
        # sites that actually need it.
        #
        # MULTI-SLOT PHASE-0 (resident-registry scaffold): introduce the
        # registry data structure anticipated earlier, PINNED to one resident
        # (``MAX_PARALLEL_SIDECARS == 1``) so runtime behaviour is byte-for-byte
        # identical to the deployed single-sidecar manager. In Phase-0 the
        # registry is NOT yet authoritative — the FSM keeps driving the
        # ``_active_*`` / ``_inflight`` / ``_spawn_seq`` / ``_idle_*`` attributes
        # verbatim (zero call-site churn = the 480-green proof is a tautology).
        # The lone resident's ``inflight`` SHARES the live ``self._inflight``
        # list object so the registry view never diverges from the fan-out rider
        # set; the scalar fields stay at placeholders until Phase-1 migrates the
        # FSM onto the registry behind its own concurrency tests.
        #
        # ``_registry_lock`` is the lock that was to be "re-added purposefully"
        # when a second mutating task lands. It is DEFINED here but INTENTIONALLY
        # UNACQUIRED in Phase-0 (single-task worker_loop discipline is unchanged);
        # the Phase-1 dispatcher/driver-tasks that introduce a second mutator MUST
        # acquire it around every ``_residents`` read-modify-write.
        self._residents: dict[str, Resident] = {}
        self._registry_lock = asyncio.Lock()
        # Turn-boundary handoff. SHARES _registry_lock
        # (does not wrap or replace it) -- notify_all() is called from inside
        # an already-held `async with self._registry_lock:` block (the park
        # site in _drive_resident), which is legal without a separate
        # `async with self._make_room_signal:` because Condition.notify()/
        # notify_all() only require self.locked() to be true, and that
        # delegates to the SAME shared Lock object. See
        # `_wait_for_park_or_timeout` for the wait side.
        self._make_room_signal = asyncio.Condition(self._registry_lock)
        # (model_tag, session_key) -> resident_key sticky map.
        # Bounded LRU; mutated ONLY under _registry_lock (same discipline as
        # _residents). Keeps a session on its engine instance for KV reuse.
        self._session_affinity: "OrderedDict[tuple[str, str], str]" = OrderedDict()
        # Strong refs to load-bearing fire-and-forget tasks
        # (teardown / inbox-requeue / death-reap). asyncio holds only a WEAK ref to
        # a bare create_task result, so an unreferenced task can be GC'd mid-flight,
        # silently cancelling the cleanup. _spawn_bg() parks each here and discards
        # on completion. Only used on the cap>=2 dispatcher path.
        self._bg_tasks: set[asyncio.Task] = set()
        # Model tags whose hybrid-KV discount has already been announced. The
        # discount is a static model property, so it is worth stating ONCE per
        # model; two of the three call sites below sit on the per-spawn and
        # per-slot paths, where an unconditional log line would repeat on every
        # request for the busiest model and stop being read.
        self._hybrid_kv_announced: set[str] = set()
        # Eagerly create the one permanent Phase-0 resident (never dropped in
        # Phase-0 — its lifetime is the manager's). ``inflight`` is the SAME list
        # object as ``self._inflight`` so in-place append/remove stay in sync.
        self._residents[_SINGLETON_RESIDENT_KEY] = Resident(
            # The singleton is keyed by the sentinel, so its
            # resident_key must match (never model_tag) — keeps _model_residents /
            # _instances_for exclusion + any get(resident_key)-guarded del correct.
            resident_key=_SINGLETON_RESIDENT_KEY,
            inflight=self._inflight,
            # P1c: the lone resident HOLDS the manager's grace/idle timers (same
            # objects at max=1, so every existing self.grace/self.idle read stays
            # byte-identical). P1d gives each concurrent resident its OWN timer
            # pair + routes the FSM through the active resident's pair.
            grace=self.grace,
            idle=self.idle,
        )
        self._binary_fd: int | None = None  # TOCTOU-pinned fd
        # Event bus for /ws/state subscribers (redacted)
        self.event_bus = EventBus()
        # Injection points (default = real subprocess_mgr; tests inject mocks)
        self._spawn = spawn_fn or spawn_sidecar
        self._wait_healthy = health_fn or wait_until_healthy
        self._sigterm = sigterm_fn or drained_sigterm
        self._vram_verify = vram_fn or verify_vram_cleared
        # Pre-teardown raw-snapshot seam (distinct from
        # _vram_verify's poll-to-threshold shape) so _unload_teardown can measure
        # the actual pre/post-teardown delta for honest credit reconciliation.
        self._gpu_used_mib = gpu_used_mib_fn or get_gpu_memory_used_mib
        # _complete_fn: replaced with httpx → llama-server /v1/chat/completions
        _real_complete_fn = complete_fn or self._default_complete

        # Observability wrap, non-streaming completion: this is the single DI
        # seam every non-streaming call site awaits, so wrapping it here once
        # covers all of them without touching any call site. By the time the
        # wrapped call returns (or raises), the engine's own generation for
        # this slot is done -- report the real outcome from exactly one place,
        # regardless of which of _complete_fn's several callers reached it.
        # Return value / exception behaviour is unchanged in every branch —
        # this only adds a log line.
        async def _complete_fn_with_kv_reuse_outcome(slot: Slot, handle):
            try:
                result = await _real_complete_fn(slot, handle)
            except asyncio.CancelledError:
                self._log_kv_reuse_outcome(slot, handle, wait_state="cancelled")
                raise
            except Exception:
                self._log_kv_reuse_outcome(slot, handle, wait_state="exception")
                raise
            else:
                self._log_kv_reuse_outcome(slot, handle, wait_state="completed")
                return result

        self._complete_fn = _complete_fn_with_kv_reuse_outcome
        # Flap/degradation telemetry (observe-only)
        self._telemetry = init_telemetry(
            log_dir=getattr(boot.storage, "state_db_path", None) and
                     boot.storage.state_db_path.parent / "telemetry",
            enabled=True,
        )

    async def _default_complete(self, slot: Slot, handle: SidecarHandle) -> dict | None:
        """Default no-op completion. The httpx proxy is wired via DI."""
        await asyncio.sleep(0.001)
        return None

    # === Idempotent completion-cache + single-flight ======
    # Kills the retry-storm RE-DECODE: a non-streaming completion whose client
    # already gave up is cached so a byte-identical retry replays instantly. All
    # four helpers run ONLY on the event loop (no lock — see the __init__ note).

    def _completion_cache_key(
        self,
        model_tag: str,
        thread_id: str,
        context: "list[dict] | None",
        client_meta: "dict | None",
    ) -> "str | None":
        """sha256 of a CANONICAL serialization of the FULL messages list ⊕
        thread_id ⊕ model_tag ⊕ output-knobs. NON-STREAMING ONLY. Returns None (cache disabled
        for this request) on a streaming request, absent context, or ANY
        serialization error — the caller then falls through to normal processing.

        RED-HAT: the key hashes the EXACT bytes of the full messages list (NOT the
        lossy _prefix_hash_chain, NOT a join) plus thread_id AND model_tag, so a
        different thread or a mutated message can NEVER collide onto another
        request's answer, and a result is never served for the wrong model. The
        dict wrapper + sort_keys makes the three fields unambiguous (no delimiter-
        collision between messages and thread_id) and the serialization canonical."""
        if context is None:
            return None
        if isinstance(client_meta, dict) and client_meta.get("stream"):
            return None  # defensive — submit_and_wait is the non-streaming entry
        try:
            # Fold the output-affecting generation
            # knobs into the key so two requests identical in messages+thread+model
            # but differing in ANY sampling/output knob (temperature / top_p / top_k /
            # max_tokens / seed / response_format / tools / reasoning_budget /
            # penalties / ...) do NOT collide onto one cached result. Local import
            # breaks the manager<-api circular dep (chat_completion imports manager,
            # not vice-versa) + keeps ONE source of truth for the knob list (no drift).
            # Absent knobs -> None uniformly, so the retry-storm case (a byte-identical
            # retry carrying identical knobs) still HITS.
            from turbohaul.api.chat_completion import _COMMON_FORWARDED_KNOBS
            knobs = (
                {k: client_meta.get(k) for k in _COMMON_FORWARDED_KNOBS}
                if isinstance(client_meta, dict)
                else {}
            )
            # Under the spawn-time design, the
            # collision this would otherwise cause is INVISIBLE by
            # construction, not just easy to miss -- reasoning_effort's
            # resolved budget is no longer IN any request payload at all (it
            # only ever affects a NEW resident's one-time spawn argv), so
            # there is nothing left in client_meta's knob set for two
            # different efforts to differ ON. The knobs dict above alone
            # therefore cannot tell "low" and "high" apart any more, even
            # though it is required that two requests differing only in
            # reasoning_effort must not collide in this cache. Folded in
            # explicitly here, separate from the knobs dict (so it still
            # never touches the _COMMON_FORWARDED_KNOBS allow-list this
            # cache key otherwise shares with the actual engine payload),
            # so that guarantee keeps holding under the new design.
            reasoning_effort = (
                client_meta.get("reasoning_effort")
                if isinstance(client_meta, dict)
                else None
            )
            payload = json.dumps(
                {
                    "messages": context,
                    "thread_id": thread_id,
                    "model_tag": model_tag,
                    "knobs": knobs,
                    "reasoning_effort": reasoning_effort,
                },
                sort_keys=True,
                separators=(",", ":"),
                ensure_ascii=False,
            )
            return hashlib.sha256(payload.encode("utf-8")).hexdigest()
        except (TypeError, ValueError, ImportError, AttributeError):
            return None  # unserializable/uninit -> no cache, never fail the request

    # ==================== Fast Lane ====================================

    def _fastlane_table(self) -> list:
        """Compiled rule table, cached and keyed on id(self.runtime.fastlane)
        so a put_config replace of self.runtime invalidates the cache
        structurally — no call site has to remember to call
        invalidate_fastlane(). Returns [] (not None) when the feature is
        absent/off/empty, so callers never need a None-check.
        """
        cfg = getattr(self.runtime, "fastlane", None)
        if cfg is None:
            self._fastlane_table_cache = None
            return []
        # The key carries the resolver's generation as well as the config
        # identity. A container_name rule's addresses change when docker hands
        # its container a new lease, WITHOUT the config object changing at all
        # -- so keying on id(cfg) alone would serve a stale table until the next
        # PUT. generation bumps only when a resolved set actually moves, so a
        # rolled address recompiles and a quiet tick does not. This preserves
        # this method's own doctrine: no call site has to remember to
        # invalidate.
        resolver = getattr(self, "_fastlane_resolver", None)
        key = (id(cfg), resolver.generation if resolver is not None else 0)
        if self._fastlane_table_cache is not None and self._fastlane_table_cache[0] == key:
            return self._fastlane_table_cache[1]
        compiled = (
            compile_fastlane(
                cfg.rules,
                resolve_name=resolver.addresses_for if resolver is not None else None,
            )
            if getattr(cfg, "enabled", False)
            else []
        )
        self._fastlane_table_cache = (key, compiled)
        return compiled

    def fastlane_rule_names(self) -> set[str]:
        """container_name values in the CURRENT rule set, for the resolver.

        Read from config, NOT from the compiled table: compiling a name rule
        needs resolved addresses, and resolving needs the names -- taking the
        names from the compiled table would be circular. Asked fresh every
        tick (mirrors plugin_health's registry_fn) because PUT /api/config can
        change the rule set under a long-lived resolver.
        """
        cfg = getattr(self.runtime, "fastlane", None)
        if cfg is None:
            return set()
        return {
            n
            for n in (getattr(r, "container_name", None) for r in getattr(cfg, "rules", []))
            if n
        }

    def _fastlane_rule_addresses(self) -> set[str]:
        """Every address currently claimed by a Fast Lane rule, as strings.

        Built from the ALREADY-NORMALIZED CompiledRule field (.address,
        set at compile_fastlane() time), never .raw_address -- so it is
        directly comparable to the normalized census keys, with no second
        normalize_address() call on the caller's side. Comparing against a
        raw display field instead is the assigned:false bug this shape
        exists to prevent.

        Single source of truth on purpose: this expression previously
        appeared verbatim at three call sites, and a rule is about to be
        able to claim MORE THAN ONE address (container-name rules
        resolve to a v4 and a v6 form at minimum). Three copies of a
        one-address assumption would be three separate places to forget.

        A rule with NO address is skipped rather than stringified. Once a
        rule can identify its client by container name, `address` is
        None for those rules, and `str(None)` would put the literal "None"
        into this set -- a phantom key that every census call site would
        then treat as rule-claimed: age-out would protect a row that does
        not exist, and the census would report assigned:true against
        nonsense. This could not happen until the schema
        change made it reachable.
        """
        claimed: set[str] = set()
        for r in self._fastlane_table():
            addr = getattr(r, "address", None)
            if addr is not None:
                claimed.add(str(addr))
            # A container_name rule has NO .address -- its identity
            # is the resolved set. Without this, a name-matched client's
            # traffic reads UNASSIGNED in the census and its rows age out as
            # though no rule referenced them, which is precisely the state
            # container-name rules exist to remove. One name resolves to a v4 AND a v6 form,
            # so this is also why the one-address assumption had to go.
            for resolved in getattr(r, "match_addresses", ()) or ():
                claimed.add(str(resolved))
        return claimed

    def _inbox_waiting_count(self) -> int:
        """Requests waiting in resident inboxes -- invisible to queue.py.

        A request whose model already has a live resident is handed straight
        to that resident's inbox and returns; queue.enqueue() is never called,
        so it never enters _staging/_accept_buf. queue.py has no visibility
        into resident inboxes and must not import them, so the count is
        supplied from here, where the resident registry lives.

        NOT _model_residents(): that also drops the legacy singleton, and the
        inbox bypass applies at any max_parallel_sidecars value, not only the
        cap>=2 dispatcher path -- a singleton resident's inbox holds real
        waiters.

        DEAD residents are excluded as a GUARD AGAINST A FUTURE EDIT, not
        against a defect visible today -- the distinction matters, so state
        it rather than implying more than is true. A dead resident's inbox is
        drained and re-enqueued into the queue (_requeue_slots_or_fail, at
        the staging head), where _staging counts it, so counting it here too
        WOULD double-count. But both sites that set
        ResidentState.DEAD (_begin_unload_locked and the driver task's finally
        block): each drains the inbox BEFORE marking DEAD and deletes the
        resident in the SAME synchronous stretch with no await between, and
        this method's caller is synchronous too -- so a DEAD-but-still-present
        resident cannot actually be observed. The filter is free and it is the
        right guard the moment an await appears between those two lines.

        ⚠ A NARROWER GAP REMAINS AND IS NOT FIXED HERE: once a
        resident is deleted, its drained slots sit in a local list that is
        neither in _residents nor yet in _staging -- _begin_unload_locked hands
        them to a detached background task, and the driver-finally path
        requeues only after KV-save and process reap. In that window those
        requests are invisible to BOTH counters. /status is documented
        best-effort and lock-skip-OK, so this is recorded rather than chased.

        Await-free list() snapshot, same lock-skip-OK convention /status
        already uses.
        """
        counted = [
            r for r in list(self._residents.values())
            if getattr(r, "inbox", None) is not None
            and getattr(r, "state", None) is not ResidentState.DEAD
        ]
        by_key = {getattr(r, "resident_key", None): r for r in counted}
        # A live claim parked in one of these inboxes is counted with the claims
        # (``queue.depth(claims_waiting=...)``), so leave it out here. The mark
        # is only a resident key, and a key can outlive its resident (a later
        # resident reuses it), so the request must really sit in that inbox: a
        # claim whose request is not in the inbox (re-queued, already taken
        # out by the driver for its turn, or the claim has moved on to another
        # request) is counted with the claims only.
        def parked_in_counted(c: dict) -> bool:
            return bool(
                c.get("parked_on") and c["parked_on"] in by_key
                and self._inbox_holds_slot(by_key[c["parked_on"]], c["slot"])
            )

        parked = 0
        for c in list(self._fastlane_claims.values()):
            if parked_in_counted(c) and self._claim_is_live(c) is None:
                # Liveness may have moved the claim to a request that is not in the
                # inbox: it counts as parked only if it still is.
                if parked_in_counted(c):
                    parked += 1
        return max(0, sum(r.inbox.qsize() for r in counted) - parked)

    def _handed_off_still_waiting(self, slot: "Slot") -> bool:
        """Membership predicate for ``_handed_off_waiting`` — ONE definition.

        This is a separate method so the read-prune and the new
        write-prune cannot drift apart. ``_handed_off_waiting_rows``'s own
        docstring makes the load-bearing argument for deriving membership from
        ``slot.state`` on each pass rather than hooking ~20 transition sites;
        that argument is unchanged, and a SECOND hand-written copy of the
        predicate would have quietly reintroduced the drift it rules out.
        """
        fut = slot.completion_future
        return (
            slot.state in (SlotState.STAGED, SlotState.ACCEPT_BUFFER)
            and not slot.is_evicted
            and not (
                slot.disconnect_event is not None
                and slot.disconnect_event.is_set()
            )
            and not (fut is not None and fut.done())
        )

    def _prune_handed_off_waiting(self) -> None:
        """Drop entries that have stopped waiting, and re-arm the watermark.

        ⚠ THE BOUND ON ``n``, because O(n)-per-write would be QUADRATIC UNDER BURST
        and nothing in this process bounds the burst: ``_route_to`` performs NO
        capacity check before ``inbox.put_nowait``, and the inbox hand-off bypasses
        ``queue.enqueue()`` entirely, so ``staging_max`` does NOT apply. The number
        of handed-off waiters is limited only by concurrent in-flight requests.
        ⇒ So the bound is IMPOSED HERE rather than assumed: the sweep runs only when
        the registry has DOUBLED since the last sweep, which gives
            * size      <= max(FLOOR, 2 x live-waiters-at-last-sweep)
            * cost      O(1) AMORTISED per hand-off (each entry is swept at most
                        once per doubling, so N hand-offs cost O(N) total, not O(N^2))
        A burst of N therefore costs O(N) sweeping in total, not O(N^2), and the
        registry never exceeds twice the genuinely-waiting population plus the floor.
        """
        reg = self._handed_off_waiting
        for slot_id in list(reg):
            if not self._handed_off_still_waiting(reg[slot_id]):
                del reg[slot_id]
        self._handed_off_prune_at = max(_HANDED_OFF_PRUNE_FLOOR, 2 * len(reg))

    def _inbox_returning_turns(self, ip, grace_started_at) -> int:
        """Inbox waiters PROVABLY this client's own next turn.

        The grace gate's inbox evidence was ``_inbox_waiting_count()``: a bare
        ``sum(r.inbox.qsize())``. A number has no ``ip`` and no ``created_at``, so a
        returning turn parked in a resident inbox was indistinguishable from a
        concurrent sibling and the gate refused the match. Such a refusal logs, for example:
        ``IPMATCH_REFUSED ... visible_siblings=0 unseen_outstanding=1``.

        ⛔ THIS SUBTRACTS; IT DOES NOT REPLACE. The caller keeps the full ``qsize``
        total and removes only what is POSITIVELY PROVEN to be this client's own
        returning turn. That asymmetry is deliberate and load-bearing:
        ``_handed_off_waiting`` is written at the three hand-off sites, but there is a
        FOURTH ``inbox.put_nowait`` (the drain-and-restore in
        ``_priority_admit_from_inbox``) with no write beside it. Restored slots were
        recorded on their original hand-off and are still waiting, so the registry
        should stay complete -- but "should" is not "is", and if it is ever wrong it is
        wrong by MISSING entries. Subtracting only proven returns means a gap leaves the
        count HIGHER, which REFUSES. Replacing the count would have made a gap
        UNDER-count, which ALLOWS -- the one direction this gate must never fail in.

        Same three tests as the staging side: same monotonic clock, unreadable values
        resolve to "not a returning turn" (i.e. still counted), and the threshold is the
        one ``pop_matched_ip`` itself uses to pick.
        """
        from turbohaul.slot import _arrived_after_grace_started

        if not isinstance(ip, str) or not ip.strip():
            return 0
        n = 0
        for slot in list(self._handed_off_waiting.values()):
            if not self._handed_off_still_waiting(slot):
                continue
            cm = getattr(slot, "client_meta", None)
            other = cm.get("ip") if isinstance(cm, dict) else None
            if not isinstance(other, str) or other != ip:
                continue
            if _arrived_after_grace_started(slot, grace_started_at):
                n += 1
        return n

    def _note_handed_off_waiting(self, slot: "Slot") -> None:
        """Record ``slot`` as handed off but not
        yet served, so /status can keep showing it for the WHOLE wait.

        Called at the three inbox hand-off sites, each beside the claim park
        (``_park_fastlane_claim_locked``): the request's claim stays registered,
        marked as parked on the resident, until the request's own turn starts,
        so the claim surface keeps showing it. The hand-off itself is what
        removed it from the queue surface (``pop_next`` already took it out of
        ``_staging``), and this registry covers that surface for the whole wait
        in ``r.inbox``, which is what showing it "the whole time" requires.

        ⛔ SCOPE WIDENED. Earlier, ONLY Fast Lane claimants were recorded here.
        The registry's duty was scoped to the waiting high-priority request, and
        mirroring ordinary traffic here would have grown the registry with every
        routed request for no stated requirement.

        ⚠ The earlier scope is described here so that a reader sees WHY the
        scope changed rather than finding a silently different gate.
        Ordinary traffic is still counted elsewhere:
        ``queue_depth_total`` already counts those requests
        (``_inbox_waiting_count``, just above, is the counter for exactly
        this population).

        Earlier scope: record only Fast Lane claimants, because the registry only
        had to cover the waiting high-priority request.
        Current scope: record every waiting slot, because the grace-match gate
        needs per-slot detail (the ``ip`` and the ``created_at``) that a bare
        count cannot carry. The reason is spelled out in the paragraph below,
        and the pruning that the wider population needs is covered
        further below (see ``_prune_handed_off_waiting``).

        ⇒ THERE IS NOW A STATED REQUIREMENT. The grace-match gate must tell
        "this client's own next turn is waiting" (ALLOW) from "a concurrent
        sibling is waiting" (REFUSE). ``_inbox_waiting_count`` cannot: it
        returns ``sum(r.inbox.qsize())``, and a NUMBER carries neither the
        ``ip`` nor the ``created_at`` the decision needs. As a result, the
        gate would refuse a real returning turn on exactly this evidence:
        ``IPMATCH_REFUSED ... visible_siblings=0 unseen_outstanding=1``.
        The Slots recorded here carry both fields.
        ⇒ Reading ``r.inbox._queue`` instead is BARRED (it is internal state, and it
        UNDER-reports items already handed to a parked getter, which fails
        PERMISSIVE -- the one direction this gate must not fail in).

        ⚠ Widening the population means /status is no longer the only pruner,
        so the write now prunes too -- see ``_prune_handed_off_waiting`` for the
        bound on ``n`` and why the sweep is amortised rather than per-write.
        """
        self._handed_off_waiting[slot.slot_id] = slot
        if len(self._handed_off_waiting) >= self._handed_off_prune_at:
            self._prune_handed_off_waiting()

    def _handed_off_waiting_rows(self) -> "list[dict]":
        """Rows for claimants handed to a
        resident inbox but not yet serving. Same row shape and same
        redaction rule as ``queue.queue_snapshot()`` (``thread_id_prefix``
        only -- never ``client_meta``/``ip``), plus ``handed_off: True``.

        PRUNES AS IT READS, and that a PREDICATE rather than a removal hook
        decides membership is the load-bearing choice here. A slot stops
        waiting the moment ``fsm.transition()`` moves it out of
        STAGED/ACCEPT_BUFFER -- and that one function is the choke point
        every transition site in this file already routes through, so
        deriving membership from ``slot.state`` on each read cannot drift.
        Hooking the ~20 individual ``transition(slot, ...)`` call sites
        would be ~20 chances to miss one and leak a row forever.

        ``position`` is None, deliberately: these rows sit in no deque and
        hold no index in one. Inventing a staging index for them is the one
        thing ``queue_snapshot``'s own ``position`` docstring rules out --
        a number that is not "where it sits right now".
        """
        rows: list[dict] = []
        for slot_id in list(self._handed_off_waiting):
            slot = self._handed_off_waiting[slot_id]
            if not self._handed_off_still_waiting(slot):
                del self._handed_off_waiting[slot_id]
                continue
            # THE FAST LANE
            # FILTER LIVES HERE NOW -- moved from the writer, NOT deleted.
            #
            # It was doing TWO jobs at the write site and only one of them was
            # about recording. On the READ side it is the only thing capping this
            # surface: hand-off rows are prepended UNCAPPED and they LEAD, so
            # admitting ordinary traffic here would let it outrank the very
            # claimant this surface exists to keep visible.
            # ⇒ The registry now RECORDS all handed-off traffic, because the
            #   grace-match gate needs each waiter's ip and created_at to tell a
            #   returning turn from a concurrent sibling
            #   (``_inbox_returning_turns``). ``/status`` SURFACES only claimants,
            #   exactly as before. One gate, one job each, and the
            #   claimant-visibility guarantee is UNCHANGED.
            # ⚠ The prune above deliberately runs for EVERY entry, claimant or
            #   not -- membership is about still-waiting, never about priority.
            if slot.fastlane is None:
                continue
            fl = slot.fastlane
            rows.append({
                "position": None,
                "slot_id": slot.slot_id,
                "model_tag": slot.model_tag,
                "thread_id_prefix": (slot.thread_id or "")[:8],
                "state": slot.state.value,
                "waited_s": round(time.monotonic() - slot.created_at, 1),
                "fastlane": (
                    {
                        "rule_index": fl.rule_index,
                        "rank": fl.rank,
                        "label": fl.label,
                        "fastlane_rule": fl.raw_address,
                    }
                    if fl is not None
                    else None
                ),
                "floor_promoted": slot.floor_promoted,
                "handed_off": True,
            })
        return rows

    def _waiting_surface_rows(self, queue_rows: "list[dict]") -> "list[dict]":
        """The whole ``queue.waiting[]`` surface
        -- claimants past the hand-off, then the rows still in a deque.

        DEDUPED BY slot_id, and this is not defensive: an inbox drain
        re-enqueues its slots at the staging head
        (``_requeue_slots_or_fail``), so a requeued claimant is legitimately
        back in ``queue_snapshot`` while this registry has not yet pruned it
        -- its state is STAGED again, which is exactly the predicate
        ``_handed_off_waiting_rows`` keeps. Without the dedup that claimant
        appears TWICE and the surface overstates the queue. The queue row
        wins because it carries a real ``position`` and a handed-off row
        cannot.

        Hand-off rows LEAD: they are further along than anything still
        resting in a deque, and this surface is a description of what an
        operator sees top-to-bottom.
        """
        staged_ids = {row["slot_id"] for row in queue_rows}
        handed_off_rows = [
            row for row in self._handed_off_waiting_rows()
            if row["slot_id"] not in staged_ids
        ]
        for row in queue_rows:
            row["handed_off"] = False
        return handed_off_rows + queue_rows

    def invalidate_fastlane(self) -> None:
        """Explicit cache-bust for the rare case something mutates
        self.runtime.fastlane IN PLACE (same object id) rather than
        replacing self.runtime wholesale via put_config."""
        self._fastlane_table_cache = None

    def _fastlane_pop_kwarg(self) -> "FastLanePopPolicy | None":
        """Built fresh on every call from live config — NOT cached, unlike
        the compiled rule table, since caching would reintroduce the exact
        stale-copy bug this method exists to avoid. Returns None when the feature
        is absent/off, which is what makes queue.pop_next's fastlane branch a
        no-op.

        ``loaded_priority_keys`` DELEGATES to
        ``_resident_priority_key`` instead of re-deriving each resident's
        identity here. This loop previously read ``r.idle_client_meta`` alone,
        which is a second, divergent answer to a question the rank-identity rule already settles --
        that field reflects whoever was served BEFORE the resident last
        parked, which is a WRONG identity (not merely a missing one) for a
        resident now mid-turn for a different client (see
        ``_resident_rank_meta``, the one reader of a resident's rank identity:
        it prefers the stamped latest turn and falls back to
        ``idle_client_meta`` only for an idle resident with nothing stamped;
        ``_model_residents()`` is not park-filtered, so this loop needs that
        reader too).

        The divergence ran in BOTH directions, which is why no change to the
        consumer's ``all(())`` in queue.py could have reached it: a
        resident with a resolvable ``rank_client_meta`` contributed NOTHING,
        manufacturing an empty tuple the consumer reads as "nothing is
        loaded" and exempting every candidate from the swap budget; while a
        resident mid-turn for a different, UNLISTED client contributed the
        PREVIOUS client's key. Delegating rather than mirroring the rank-identity rule is
        deliberate -- a mirrored copy is a second source of truth that can
        drift, and ``_resolve_fastlane_match``'s docstring already claims
        "there is exactly one place that answers 'is this resident listed'".
        """
        cfg = getattr(self.runtime, "fastlane", None)
        if cfg is None or not getattr(cfg, "enabled", False):
            return None
        table = self._fastlane_table()
        loaded_priority_keys = []
        for r in self._model_residents():
            key = self._resident_priority_key(r, table)
            if key is not None:
                loaded_priority_keys.append(key)
        # Hand the pick the best LIVE claim so a
        # claimant that is mid-backoff -- and therefore in NEITHER queue buffer
        # -- still orders the admission it is entitled to.
        #
        # ⛔ NO LOCK IS TAKEN HERE, AND THAT IS THE POINT, NOT AN OVERSIGHT.
        # ``_governing_claim_locked`` documents "CALLER HOLDS _registry_lock",
        # and that precondition CANNOT be honoured at a placement that is also
        # deadlock-safe. Both alternatives are closed:
        #   * inside ``_pick_fastlane_locked`` (which holds ``queue._lock``, the
        #     correct outer lock) -- impossible: that method is SYNC and
        #     ``_registry_lock`` is an ``asyncio.Lock``;
        #   * here, but wrapped in ``async with self._registry_lock`` -- that
        #     acquires _registry_lock and then ``queue._lock`` inside
        #     ``pop_next``, which INVERTS the established
        #     ``queue._lock -> _registry_lock`` order and is a deadlock.
        # Taking NO lock is therefore not the weakest option, it is the only
        # safe one: a path that acquires nothing cannot invert an order.
        #
        # WHAT MAKES THE LOCK-FREE READ CORRECT, stated precisely -- the whole
        # path from here down (``_governing_claim_priority_key_locked`` ->
        # ``_governing_claim_locked`` -> ``_claim_is_live`` /
        # ``queue._fastlane_priority_key``) is SYNC AND AWAIT-FREE, so no
        # other coroutine can interleave DURING the read. That is what makes
        # iterating ``_fastlane_claims`` without the lock safe from "dict
        # changed size during iteration" -- the same justification
        # ``_model_residents`` states for its own ``list()`` snapshot
        # ("Await-free ``list()`` snapshot so a concurrent mutation can't
        # error").
        #
        # ⛔ IT DOES NOT MAKE THE VALUE FRESH AT THE POP, AND MUST NOT BE READ
        # AS SAYING SO. Every caller evaluates this as an ARGUMENT to
        # ``await queue.pop_next(...)``, so the loop CAN run in between --
        # ``_dispatch_loop`` even has an explicit ``grace_active=await
        # self._grace_active_exclusions()`` evaluated in the SAME argument
        # list, immediately after this one. The key can therefore be stale by
        # the time the pop runs, and that is TOLERATED, not overlooked:
        #   * stale non-None -> one slot is held aside for a single pop that
        #     did not need it. Bounded, self-correcting: this policy is
        #     rebuilt from scratch on EVERY call and never cached.
        #   * stale None -> the outranked slot is served once, i.e. exactly
        #     the previous behaviour for one tick.
        # Neither is unbounded and neither can deadlock, which is why a lock
        # (whose only purpose here would be freshness) is not worth inverting
        # the lock order for.
        #
        # ⛔ AND THE SYNCHRONY ARGUMENT HOLDS ONLY AGAINST COROUTINES, NOT
        # THREADS. Audited in this tree: ``_fastlane_claims`` is mutated in
        # exactly three methods (``_register_fastlane_claim_locked``,
        # ``_release_fastlane_claim_locked``, ``fastlane_claims_snapshot``),
        # all reached only from event-loop code; ``asyncio.to_thread`` is the
        # tree's only thread mechanism and none of its targets reaches a
        # mutator; and every FastAPI route is ``async def`` -- a SYNC ``def``
        # route would run in a worker thread and could put the registry's own
        # pruner (``status_snapshot`` -> ``fastlane_claims_snapshot``) off the
        # loop. The claim RECORDS (not the dict) are also edited in place: by the
        # waiter bookkeeping (``_note_claim_waiter``,
        # ``_repoint_claim_to_best_waiter``), by the parked mark
        # (``_park_fastlane_claim_locked``, ``_unpark_fastlane_claim``) and, through
        # ``_claim_is_live`` (it moves a claim whose request is gone to the best
        # remaining waiter), by this lock-free read itself. All of it is sync,
        # await-free, event-loop code only, and none of it adds or removes a key,
        # so iterating the dict stays safe.
        # ⚠ All of the above is pinned executably in
        # the readmission-rank tests
        # (``TestTheLockFreeReadIsStructurallyPinned``): if anyone adds an
        # ``await``, takes a lock on this path, introduces a thread mechanism,
        # or declares a sync route, those tests go RED rather than the process
        # deadlocking or tearing a dict in production.
        return FastLanePopPolicy(
            max_normal_wait_s=cfg.max_normal_wait_s,
            cross_model_switches_per_min=cfg.cross_model_switches_per_min,
            loaded_priority_keys=tuple(loaded_priority_keys),
            governing_claim_key=self._governing_claim_priority_key_locked(),
        )

    def _fastlane_census_age_out_locked(self, now: float) -> None:
        """Age out census entries older than census_ttl_hours that NO current
        rule references — a rule-referenced address is kept regardless of
        age (the operator explicitly cares about it). Called opportunistically
        before a new-distinct-address insert (bounded table, ≤256 rows, so an
        O(n) sweep here is negligible), not on a separate timer."""
        cfg = getattr(self.runtime, "fastlane", None)
        ttl_hours = getattr(cfg, "census_ttl_hours", None) if cfg is not None else None
        if ttl_hours is None:
            ttl_hours = _FASTLANE_CENSUS_TTL_DEFAULT_HOURS
        ttl_s = ttl_hours * 3600.0
        rule_addresses = self._fastlane_rule_addresses()
        stale = [
            ip for ip, row in self._fastlane_census.items()
            if ip not in rule_addresses and (now - row["last_seen"]) > ttl_s
        ]
        for ip in stale:
            del self._fastlane_census[ip]

    def _fastlane_census_observe(
        self, client_meta: "dict | None", thread_id: str, model_tag: str,
    ) -> None:
        """Record one request against the discovered-address census. Called
        pre-admission (before any submit()/queue outcome is known), so it
        counts every request that reaches this point — cache hits, riders,
        QueueFull/QueueClosed rejections, and normal admissions alike
        (request_count), while served_count is only incremented later by
        _fastlane_census_mark_served / _mark_slot_active for requests that
        actually got a real answer.

        Guard: /v1/embeddings builds its own client_meta with no "ip" key
        (never calls _derive_client_meta_identity) — skip+count rather than
        manufacture a null-address row.
        """
        cm = client_meta or {}
        ip = cm.get("ip")
        if not ip:
            self._fastlane_census_skipped_no_ip += 1
            return
        # The census dict is keyed by the NORMALIZED address so two raw
        # forms of the same host collapse to one entry (fixes the
        # duplicate-row bug). `ip` from here on is the normalized key;
        # the RAW form the operator/request actually used is kept
        # separately below, in row["address"], set ONLY at row creation.
        norm_ip = _fastlane_census_key(ip)
        # WALL-CLOCK (time.time()), deliberately NOT time.monotonic(): these
        # timestamps must survive a restart for census_ttl_hours aging and
        # the boot_reconcile rebuild (which seeds from state.sqlite's ISO
        # wall-clock created_at) to mean anything. monotonic() resets to ~0
        # every boot, which would make an aging/rebuild comparison nonsense.
        now = time.time()
        row = self._fastlane_census.get(norm_ip)
        if row is None:
            self._fastlane_census_age_out_locked(now)
            if len(self._fastlane_census) >= _FASTLANE_CENSUS_MAX:
                self._fastlane_census_overflow_refused += 1
                if not self._fastlane_census_overflow_logged:
                    log.error(
                        "Fast Lane census at capacity (%d) — refusing new distinct "
                        "addresses. Existing entries are kept, none evicted.",
                        _FASTLANE_CENSUS_MAX,
                    )
                    self._fastlane_census_overflow_logged = True
                return
            row = {
                # RAW form, kept for display (operator sees what actually
                # hit the server) -- set ONCE, here, never overwritten by a
                # later request arriving via a DIFFERENT raw form of the
                # same normalized host, so the displayed address can never
                # flicker between representations of one host.
                "address": ip,
                "normalized_address": norm_ip,
                "first_seen": now,
                "last_seen": now,
                "request_count": 0,
                "served_count": 0,
                "classes": {},
                "models": set(),
                "thread_ids": set(),
                # Container name behind this address. Set only by the
                # background name task, and only after a forward lookup
                # confirmed that the name resolves back to this address.
                # Display only: it never reaches the request matcher, and
                # it is not persisted (a restart rebuilds the row without
                # it and the task fills it in again).
                "container_name": None,
            }
            self._fastlane_census[norm_ip] = row
        row["last_seen"] = now
        row["request_count"] += 1
        from turbohaul.kv_classify import _class_from_label
        cls = _class_from_label(cm) or "unclassified"
        row["classes"][cls] = row["classes"].get(cls, 0) + 1
        if model_tag:
            row["models"].add(model_tag)
        if thread_id:
            row["thread_ids"].add(thread_id)

    def _fastlane_census_mark_served(self, client_meta: "dict | None") -> None:
        """Increment served_count for an already-observed address. A miss
        (no matching row — e.g. embeddings' no-ip gap, or a census entry
        aged out between observe and serve) is silently a no-op; this method
        never creates a row, only OBSERVE does."""
        cm = client_meta or {}
        ip = cm.get("ip")
        if not ip:
            return
        row = self._fastlane_census.get(_fastlane_census_key(ip))  # normalized lookup
        if row is not None:
            row["served_count"] += 1
            row["last_seen"] = time.time()  # wall-clock, see _fastlane_census_observe

    def _mark_slot_active(self, slot: "Slot") -> None:
        """Single owner for the ACTIVE-transition timestamp + Fast Lane
        served-mark. Replaces five previously-duplicated
        `slot.started_active_at = time.monotonic()` call sites — five copies
        of a timestamp plus five copies of a census call is guaranteed
        drift, so both live here once.

        Also the per-turn seam for the tools-change check —
        ONE call to a pure zero-I/O method, deliberately not the logic itself,
        so this stays the narrow thing its name promises."""
        slot.started_active_at = time.monotonic()
        self._fastlane_census_mark_served(slot.client_meta)
        self._check_thread_tools_fingerprint(slot)

    def _check_thread_tools_fingerprint(self, slot: "Slot") -> None:
        """Warn when a thread's `tools` set changes
        between its own turns. PURE observability: a dict read, a hash, a stash
        write and a log. ZERO I/O, gates nothing, and must stay that way.

        WHY IT LIVES HERE AND NOT IN _probe_and_save_clean_kv, where it was
        born: that method performs REAL I/O (a direct sidecar prefill POST and
        a multi-GB KV write) and is only reached on SOME per-turn paths. The
        check sat inside it purely because it "already runs on every live
        per-turn probe" — a convenience, never a semantic fit — and the two
        streaming/fan-out arms of _serve_on_resident never call it at all, so
        the ordinary chat shape was blind. Moving the check to the
        per-turn seam covers every path without putting an observability
        concern inside an I/O method.

        WHERE IT IS REACHED FROM — six sites, five of them via
        _mark_slot_active (the _serve_on_resident anchor,
        _fan_out_and_drain, _admit_nonstreaming_riders, and two sites in
        _process_slot) plus ONE direct call at _serve_on_resident's matched
        promotion, which reaches no _mark_slot_active call of its own.

        ONCE PER TURN, BY CONSTRUCTION: every one of those sites receives a
        distinct Slot that came off the queue as its own request — the anchor,
        `queue.pop_matched_thread(...)` for a grace-window follow-up, or
        `queue.pop_next(...)` for a rider. Two calls therefore mean two TURNS,
        never one turn counted twice.

        NOT REACHED ON THE UNLOAD/SEAM PATH, and that guarantee changed shape:
        it used to be the `save_to_disk=False` FLAG on the old call site; it is
        now a PLACEMENT property — the seam path never marks a slot ACTIVE, so
        it cannot arrive here. Stronger against a flag mistake, but enforced
        somewhere else, which is worth knowing before moving this again.
        """
        tid = getattr(slot, "thread_id", "") or ""
        if not tid:
            return
        client_meta = getattr(slot, "client_meta", None) or {}
        try:
            _cur_tools = client_meta.get("tools")
            _cur_hash = _tools_fingerprint(_cur_tools)
            _cur_names = _tools_names(_cur_tools)
            _prev_fp = self._tools_fingerprint_by_thread.get(tid)
            _tools_changed, _tools_delta = _classify_tools_fingerprint(
                _prev_fp, _cur_hash, _cur_names)
            if _tools_changed:
                log.warning(
                    "TOOLS CHANGED mid-thread: thread=%s prev_count=%d "
                    "cur_count=%d entered=%s left=%s fingerprint=%s -- a tools-"
                    "set change between turns of the SAME thread caps the "
                    "engine's warm-slot common-prefix match at a constant "
                    "early offset (right where the rendering diverges), "
                    "self-perpetuating full re-prefill + checkpoint erasure "
                    "until it changes back or the engine gives up",
                    (tid or "?")[:40], _tools_delta["prev_count"],
                    _tools_delta["cur_count"], _tools_delta["entered"],
                    _tools_delta["left"], (_cur_hash or "none")[:12])
            # pop-then-set so a re-stashed active thread moves to
            # most-recent (true write-LRU eviction below; mirrors
            # _record_shadow_bytematch_probe's idiom in this file).
            _tfp = dict(self._tools_fingerprint_by_thread)
            _tfp.pop(tid, None)
            _tfp[tid] = {"hash": _cur_hash, "names": _cur_names,
                         "count": len(_cur_names)}
            while len(_tfp) > _TOOLS_FINGERPRINT_CAP:
                _tfp.pop(next(iter(_tfp)))
            self._tools_fingerprint_by_thread = _tfp
        except Exception:
            log.debug("tools fingerprint check best-effort failed", exc_info=True)

    def fastlane_census_snapshot(self) -> dict:
        """Full discovered-address census, fourteen fields per row, `assigned`/
        `ambiguous`/`ambiguity_reason` DERIVED at read time (never stored) so
        a rule-list edit is reflected immediately. This is the DATA method —
        the API-layer route calls this and serializes the result; no HTTP
        route lives in this file, since the census endpoint belongs with the
        rest of the API layer, not the manager."""
        rule_addresses = self._fastlane_rule_addresses()
        rows = []
        for ip, row in self._fastlane_census.items():
            classes_seen = set(row["classes"])
            ambiguous = len(classes_seen) >= 2
            models = sorted(row["models"])
            rows.append({
                "address": row["address"],
                "normalized_address": row["normalized_address"],
                "first_seen": row["first_seen"],
                "last_seen": row["last_seen"],
                "request_count": row["request_count"],
                "served_count": row["served_count"],
                "classes": dict(row["classes"]),
                "models": models[:8],
                "models_truncated": len(models) > 8,
                "thread_count": len(row["thread_ids"]),
                "container_name": row.get("container_name"),
                "ambiguous": ambiguous,
                "ambiguity_reason": (
                    "A rule on the address alone will apply to all of them - if "
                    "these are different callers they cannot be told apart here; "
                    "add a tag to narrow it."
                ) if ambiguous else None,
                "assigned": row["normalized_address"] in rule_addresses,
            })
        return {
            "rows": rows,
            "overflow": {
                "active": self._fastlane_census_overflow_refused > 0,
                "refused_distinct": self._fastlane_census_overflow_refused,
            },
            "skipped_no_ip": self._fastlane_census_skipped_no_ip,
        }

    def fastlane_census_name_targets(self) -> list[tuple[str, str | None]]:
        """(census key, current container name or None) for each census row,
        for the background name task. At most _FASTLANE_CENSUS_MAX pairs. The
        key is the normalized-address string that keys the census dict."""
        return [
            (key, row.get("container_name"))
            for key, row in list(self._fastlane_census.items())[:_FASTLANE_CENSUS_MAX]
        ]

    def fastlane_census_set_name(self, census_key: str, name: str | None) -> None:
        """Set (or clear, with None or an empty string) the container name
        shown on one census row. A row that is gone -- aged out since the
        task read its targets -- is a silent no-op; this method never
        creates a row, only OBSERVE does."""
        row = self._fastlane_census.get(census_key)
        if row is None:
            return
        row["container_name"] = (name.strip() if name else "") or None

    def _fastlane_status_badge(self) -> dict:
        """Cheap four-scalar summary for the 1Hz-polled /status endpoint — a
        256-row table does not belong there. Avoids
        fastlane_census_snapshot()'s per-row class/ambiguity expansion."""
        cfg = getattr(self.runtime, "fastlane", None)
        enabled = bool(getattr(cfg, "enabled", False)) if cfg is not None else False
        rule_addresses = self._fastlane_rule_addresses()
        census_count = len(self._fastlane_census)
        unassigned_count = sum(
            1 for ip in self._fastlane_census if ip not in rule_addresses
        )
        return {
            "enabled": enabled,
            "census_count": census_count,
            "unassigned_count": unassigned_count,
            "census_overflow": self._fastlane_census_overflow_refused > 0,
            "refusals_by_reason": self.queue.fastlane_refusal_counts(),
            "swaps_by_reason": self.queue.fastlane_swap_counts(),
        }

    # ==================== /Fast Lane ===========================================

    def _completion_cache_lookup(self, key: str) -> "dict | None":
        """Return a FRESH cached result for key, or None on miss / expiry. An
        expired entry is dropped on access; a hit is LRU-touched (move_to_end)."""
        entry = self._completion_cache.get(key)
        if entry is None:
            return None
        result, expiry = entry
        if time.monotonic() >= expiry:
            self._completion_cache.pop(key, None)
            return None
        self._completion_cache.move_to_end(key)
        return result

    def _completion_cache_store(self, slot: Slot, result: "dict | None") -> None:
        """WRITE site helper: cache a NON-streaming completion + release its single-
        flight future. No-op unless this slot is a cache LEADER (its submit_and_wait
        stashed ``completion_cache_key``). Only a real dict result is cached; a None
        result (no backend wired) is not cached but still releases riders so they do
        not hang. Bounded LRU: evict the oldest when over _COMPLETION_CACHE_MAX. Any
        bookkeeping error is swallowed — the cache must NEVER break a completion."""
        key = getattr(slot, "completion_cache_key", None)
        if key is None:
            return
        try:
            if isinstance(result, dict):
                self._completion_cache[key] = (
                    result, time.monotonic() + self._completion_cache_ttl_s,
                )
                self._completion_cache.move_to_end(key)
                while len(self._completion_cache) > _COMPLETION_CACHE_MAX:
                    self._completion_cache.popitem(last=False)  # drop the oldest
            # Resolve + retire the single-flight future so any riders get the answer.
            fut = self._completion_inflight.pop(key, None)
            if fut is not None and not fut.done():
                fut.set_result(result if isinstance(result, dict) else _FLIGHT_FAILED)
        except Exception:  # noqa: BLE001 — cache is best-effort, never fail a request
            log.exception("completion-cache store failed (best-effort)")

    def _completion_cache_clear(self, reason: str = "") -> None:
        """SWAP-CLEAR: drop every cached completion + release every single-flight
        rider. MUST fire whenever the model swaps / the active sidecar is torn down
        — cached results are engine/build-specific, so an answer must NEVER survive
        a swap (RED-HAT). Released riders fall through to normal processing against
        the NEW engine. Idempotent (clearing empty dicts is a no-op)."""
        if self._completion_cache:
            self._completion_cache.clear()
        if self._completion_inflight:
            for fut in list(self._completion_inflight.values()):
                if not fut.done():
                    fut.set_result(_FLIGHT_FAILED)
            self._completion_inflight.clear()

    @staticmethod
    def _identity_dict(
        *, ip, model_tag: str, client_meta: dict | None, thread_id: str,
        fastlane=None,
    ) -> dict:
        """Pure identity-dict builder, extracted out of
        ``_emit_request_identity`` so the "last
        admitted" emit path and the new "current, live right now" surface
        (``_current_request_identity``) build the IDENTICAL shape from ONE
        source — never hand-built twice. No side effects, no try/except of
        its own: callers own error handling for their own context (the
        existing best-effort wrapping in ``_emit_request_identity`` is
        unchanged; ``_current_request_identity`` wraps its own call).

        ``resolved_class`` is a READ-ONLY surface of ``kv_classify.
        _class_from_label`` — the SAME read already used elsewhere (e.g.
        ``_durable_ring_key``); this call makes NO decision and drives
        nothing.
        """
        from turbohaul.kv_classify import _class_from_label
        cm = client_meta or {}
        return {
            "ip": ip,
            "model_tag": model_tag,
            "session_id": cm.get("session_id"),
            "is_main": cm.get("is_main"),
            "is_sub_agent": cm.get("is_sub_agent"),
            "is_curator": cm.get("is_curator"),
            "is_compression": cm.get("is_compression"),
            "resolved_class": _class_from_label(cm),
            "thread_id": thread_id,
            # Observability: re-emits the SAME req_id the API layer's
            # identity_recompose line stamped into client_meta, so the two
            # layers' identity views join by grep under load. Absent (None)
            # on any caller that never went through identity_recompose
            # (e.g. a direct submit() from a non-HTTP path) -- named, not
            # silently missing.
            "req_id": cm.get("req_id"),
            # The operator-saved Fast Lane label for THIS
            # request's source IP, when one exists. Read from the
            # admission-time match (slot.fastlane, manager's submit path)
            # -- never re-matched here. Null when fastlane is disabled,
            # no rule matches, or the rule has no saved label: the FE
            # renders nothing for null (no placeholder, no 'unknown'),
            # and a label entered later in the Fast Lane tab shows up on
            # the next admitted request automatically.
            "label": (getattr(fastlane, "label", "") or None),
            # The matched rule's own STABLE identifier -- the
            # operator's identifying string verbatim, a container name for a
            # name rule or an address for an address rule (fastlane.py's
            # CompiledRule.raw_address). Carried so a read surface can
            # re-resolve `label` from the LIVE table instead of trusting the
            # one stamped here, which was true at admission and can be wrong
            # by the time an operator reads it.
            #
            # ⛔ NOT `rule_index`. Index is POSITIONAL -- compile_fastlane
            # enumerates, so removing a rule promotes every rule below it and
            # a stored index would later resolve to a DIFFERENT rule and
            # render its label with total confidence. Stale-then-blank is
            # survivable; stale-then-plausibly-wrong is worse than the bug.
            "fastlane_rule": getattr(fastlane, "raw_address", None),
        }

    def _emit_request_identity(
        self, *, ip, model_tag: str, client_meta: dict | None, thread_id: str,
        fastlane=None,
    ) -> None:
        """DISPLAY/
        OBSERVABILITY ONLY. Emits ONE greppable structured log line
        (``R2B_REQ_IDENTITY``) + stashes the same dict on
        ``self._last_request_identity`` for ``/status`` — proof that the
        manager reads + trusts the structured client_meta identity fields
        instead of guessing off the thread_id prefix. This is the LAST
        admitted request, regardless of whether it is still running — see
        ``_current_request_identity`` for what's actually live right now
        (a separate read surface).

        Best-effort / None-safe: wrapped so a malformed ``client_meta`` can
        NEVER raise into the decode path (mirrors the existing best-effort
        ``identity_recompose`` log pattern in chat_completion.py).
        """
        try:
            identity = self._identity_dict(
                ip=ip, model_tag=model_tag, client_meta=client_meta,
                thread_id=thread_id, fastlane=fastlane,
            )
            log.info("R2B_REQ_IDENTITY %s", json.dumps(identity))
            self._last_request_identity = identity
            # Same stash, per-resident. model_tag is already a keyword param
            # of this function -- no threading needed.
            self._last_request_identity_by_model[model_tag] = identity
        except Exception:  # noqa: BLE001 — display-only, never fail a request
            log.debug("R2B_REQ_IDENTITY emit failed (ignored)", exc_info=True)

    def _live_fastlane_label(self, raw_address: "str | None") -> "str | None":
        """The label the CURRENT rule table gives the rule identified by
        ``raw_address`` -- None when no current rule carries that identity.

        Keyed on the rule's own identifying string, never on ``rule_index``:
        index is positional, so a stored one silently re-points to a
        different rule the moment a rule above it is removed. ``raw_address``
        survives reordering, insertion and deletion.

        Fail-closed by construction, the same way ``match_fastlane`` is: a
        deleted or re-pointed rule resolves to nothing, and nothing can never
        be resolved into some OTHER client's label. None is the value
        ``_identity_dict`` already documents the FE as rendering as blank, so
        the absent case needs no new frontend handling.

        Resolved on READ rather than invalidated on WRITE. The alternative
        considered was busting the stored identities from
        ``invalidate_fastlane()``; that hook does fire on the only path that
        can change a rule (rules are replaced wholesale by a config write and
        nowhere else), but it would drop the WHOLE record -- ip, session_id,
        req_id, model_tag and resolved_class are in the same dict and none of
        them are config-derived, so four true fields would be destroyed to
        correct one, and every resident card would blank its identity strip
        on each config save until the next request arrived. It would also be
        one more hook a future mutation path has to remember to call.
        Resolving here cannot be forgotten and cannot over-invalidate, which
        is the same reasoning ``_fastlane_table`` gives for keying its cache
        structurally instead of relying on that hook.
        """
        if not raw_address:
            return None
        for rule in self._fastlane_table():
            if rule.raw_address == raw_address:
                return rule.label or None
        return None

    def _identity_with_live_label(self, identity: dict | None) -> dict | None:
        """A read-surface copy of a stored identity whose ``label`` is
        resolved from the live rule table.

        The STORED record keeps whatever label it was stamped with, because
        the emitted ``R2B_REQ_IDENTITY`` log line is a historical record of
        what was true at admission and must stay one. What ``/status`` shows
        an operator is a claim about NOW, so it is resolved now. The
        label on a resident card could carry a stamp that predated the
        corrected table by seconds -- true when written, wrong when read.

        Copies rather than mutates: the stored dict is shared with the log
        line that was already emitted from it.
        """
        if identity is None:
            return None
        return {
            **identity,
            "label": self._live_fastlane_label(identity.get("fastlane_rule")),
        }

    def _current_request_identity(self, slot: "Slot | None") -> dict | None:
        """The request identity actually driving the system
        RIGHT NOW, built from a live ``active_slot`` — as opposed to
        ``_last_request_identity``/``_last_request_identity_by_model``,
        which is the LAST admitted request regardless of whether it is
        still running (see the front-end request-identity strip: "this strip is a
        REQUEST RECORD (the manager's LAST-ADMITTED request), NOT the
        resident's current identity" — that FE comment already named this
        exact gap; this is the surface it was missing).

        Returns None when idle (``slot`` is None) — NEVER falls back to the
        last identity and NEVER an empty dict. A stale identity is the
        defect this avoids: the label showed a FINISHED session as if it
        were live. ``self._active_slot`` and a resident's own
        ``r.active_slot`` are two READS of the SAME fact, not two facts
        that happen to agree — ``_set_active_slot``
        writes both in the one place, so callers here can never observe
        them drift apart.

        Deliberately built from the slot itself, never from ``inflight``:
        ``inflight`` counts fan-out riders EXCLUDING the anchor request, so
        ``inflight == 0`` is normal, correct behaviour while genuinely busy
        AND while genuinely idle — it cannot distinguish the two directions
        (true on both a busy and an idle system).

        Best-effort: any failure returns None rather than raising into a
        /status or /residents read (this runs on that hot path).

        Note: ``slot is not
        None`` is NOT enough. A resident's ``active_slot`` stays set to a
        FINISHED request for its entire GRACE window (for example,
        resident.current stays populated with an already-done session until it
        clears on the IDLE_EVICTABLE flip) -- so a null-check alone would
        show a finished session as "current" for the whole grace window,
        reintroducing the original stale-identity defect at a delay
        instead of instantly. Gate on the Slot's own FSM state instead: only
        ACTIVE/ACTIVE_MATCH mean a request is genuinely being served RIGHT
        NOW; GRACE (warm-held, done) and everything else null out
        immediately. This mirrors live_monitor.py's own
        ``_ACTIVE_STATES = {"ACTIVE", "ACTIVE_MATCH"}`` -- the
        SAME distinction, already shipped and battle-tested there, reused
        directly against the FSM's synchronous state rather than routed
        through that poller's ~1Hz/debounced cache (the wrong latency/
        false-positive profile for a synchronous /status read).

        This gate is inside the SHARED helper deliberately: both call sites
        (status_snapshot's singleton read and _residents_snapshot's
        per-resident read) need the identical grace-window protection --
        putting it in one place here means it can never drift between the
        two the way two separate call-site guards could.
        """
        if slot is None:
            return None
        if getattr(getattr(slot, "state", None), "value", None) not in (
            "ACTIVE",
            "ACTIVE_MATCH",
        ):
            return None
        try:
            return self._identity_dict(
                ip=(slot.client_meta or {}).get("ip"),
                model_tag=slot.model_tag,
                client_meta=slot.client_meta,
                thread_id=slot.thread_id,
                fastlane=slot.fastlane,
            )
        except Exception:  # noqa: BLE001 — display-only, never fail a request
            log.debug(
                "current_request_identity build failed (ignored)", exc_info=True
            )
            return None

    async def _await_completion_with_oom_exemption(
        self, slot: Slot, timeout_s: float
    ) -> Any:
        """The ONE await
        site ``timeout_s`` governs in ``submit_and_wait``. A request that
        went back in the queue after an OOM load failure, AND has a live
        disconnect signal, is NOT ended by ``timeout_s`` -- only disconnect
        or being served ends it there. Every other wait (ordinary queue
        waits; any requeue-eligible slot with no ``disconnect_event``) keeps
        ``timeout_s`` exactly as before this exemption.

        Implemented as a PAUSABLE deadline: the remaining ``timeout_s``
        budget stops counting down while ``slot.oom_requeue_pending`` is
        True (and ``disconnect_event`` is not None), and resumes the moment
        the slot is re-admitted or fails for a non-requeue reason (both
        clear the flag -- see ``_requeue_on_oom_load_failure`` /
        ``worker_loop``'s admission site). The flag can flip during a single
        call (a slot may OOM-requeue more than once), so this re-checks it
        on every loop iteration rather than deciding once up front.

        ``asyncio.shield`` is required: a bare
        ``asyncio.wait_for(slot.completion_future, ...)`` CANCELS the
        awaited future on ITS OWN timeout, and ``slot.completion_future`` is
        the SAME object a LATER admission attempt will resolve -- cancelling
        it here would crash that later ``set_result``/``set_exception`` call
        with ``InvalidStateError``. Shielding lets this wait's own timeout
        expire and loop without ever touching the real future. On the
        never-exempt path this is behaviourally byte-identical to the bare
        ``wait_for`` it replaces: success returns the same result, and a
        genuine timeout re-raises the SAME ``asyncio.TimeoutError``.
        """
        def _is_exempt() -> bool:
            return (
                getattr(slot, "oom_requeue_pending", False)
                and slot.disconnect_event is not None
            )

        remaining = timeout_s
        while True:
            per_wait = None if _is_exempt() else remaining
            started = time.monotonic()
            try:
                return await asyncio.wait_for(
                    asyncio.shield(slot.completion_future), timeout=per_wait
                )
            except asyncio.TimeoutError:
                # per_wait can only have been a real number here: with
                # per_wait=None, wait_for cannot itself raise TimeoutError.
                # Re-check the flag NOW (fresh, not the value from loop
                # top) — the slot may have become OOM-requeued partway
                # through this bounded wait, in which case this expiry must
                # NOT end the request: don't count this window against the
                # budget, loop back into an (now) unbounded wait instead.
                if _is_exempt():
                    continue
                remaining -= time.monotonic() - started
                if remaining <= 0:
                    raise

    async def submit_and_wait(
        self,
        model_tag: str,
        prompt: str = "",
        thread_id: str = "",
        context: list[dict] | None = None,
        client_meta: dict | None = None,
        timeout_s: float = 7200.0,
        disconnect_event: "asyncio.Event | None" = None,
        admission_ctx_len: int = 0,
        admission_hash_chain: list[str] | None = None,
    ) -> tuple[Slot, Any]:
        """Submit + await the slot's completion. Returns (slot, completion_result).

        Caller may pass a ``disconnect_event`` that the
        route's ``watch_disconnect`` task sets on client close. The queue
        pops with eviction-awareness; if the slot is evicted before activation,
        worker_loop fails the completion_future with SlotEvictedError which
        propagates out of this ``await`` for the caller to map to HTTP 499.

        Idempotent completion-cache + single-flight, on the
        NON-streaming path only. BEFORE enqueue we compute the completion-key and
        either (a) return a fresh cached result instantly on a HIT (no enqueue, no
        engine call), (b) ride an in-flight byte-identical request's future
        (single-flight dedupe), or (c) become the flight LEADER — register the
        future, process normally, and let the _process_slot WRITE site cache the
        result + resolve the future at completion. A cache HIT / rider returns
        ``(None, result)``; callers on this path use only ``result`` and never
        dereference the slot. Any cache-path error falls through to normal
        processing (correctness > hit-rate). The check-and-register is await-free
        so two identical requests can never both become leader.
        """
        # Fast Lane OBSERVE: above the completion-cache block so it catches all
        # three pre-submit() exits below (cache hit, single-flight rider,
        # QueueFull/QueueClosed raised inside submit()) as well as the normal
        # admission path. Best-effort — never block a real request.
        try:
            self._fastlane_census_observe(client_meta, thread_id, model_tag)
        except Exception:
            log.exception("Fast Lane census observe failed in submit_and_wait")
        # --- M5 completion-cache READ + single-flight admission (non-streaming) ---
        cache_key = self._completion_cache_key(
            model_tag, thread_id, context, client_meta
        )
        am_leader = False
        if cache_key is not None:
            hit = self._completion_cache_lookup(cache_key)
            if hit is not None:
                self._fastlane_census_mark_served(client_meta)
                return None, hit  # instant retry replay — no enqueue, no decode
            existing = self._completion_inflight.get(cache_key)
            if existing is not None:
                # A byte-identical request is already in flight — ride its future.
                try:
                    riden = await existing
                except Exception:  # noqa: BLE001 — leader failed; re-submit below
                    riden = _FLIGHT_FAILED
                if riden is not _FLIGHT_FAILED:
                    self._fastlane_census_mark_served(client_meta)
                    return None, riden
                # Leader's flight failed -> fall through as an ordinary request. Do
                # NOT re-lead (worst case mirrors no-single-flight, still correct).
            else:
                # Become the flight leader: register BEFORE enqueue (await-free from
                # the get above) so concurrent siblings dedupe onto this future.
                self._completion_inflight[cache_key] = (
                    asyncio.get_running_loop().create_future()
                )
                am_leader = True

        try:
            slot = await self.submit(
                model_tag=model_tag,
                prompt=prompt,
                thread_id=thread_id,
                context=context,
                client_meta=client_meta,
                wait_for_completion=True,
                disconnect_event=disconnect_event,
                admission_ctx_len=admission_ctx_len,
                admission_hash_chain=admission_hash_chain,
            )
            # Emit the proof-surface identity line ONCE per
            # admitted request, at the chokepoint where client_meta + thread_id +
            # model_tag co-exist. slot.thread_id (not the raw param) — submit()
            # may have auto-derived it. Best-effort (see _emit_request_identity).
            self._emit_request_identity(
                ip=(slot.client_meta or {}).get("ip"),
                model_tag=model_tag,
                client_meta=slot.client_meta,
                thread_id=slot.thread_id,
                fastlane=slot.fastlane,
            )
            if am_leader:
                # Stash the key so the _process_slot WRITE site can cache the result
                # and resolve this leader's single-flight future keyed by it.
                slot.completion_cache_key = cache_key
            result = await self._await_completion_with_oom_exemption(slot, timeout_s)
            return slot, result
        finally:
            # LEADER cleanup (try/finally so it can't leak): if the flight ended
            # WITHOUT a cache write (eviction / timeout / exception / a cap>=2 path
            # that did not write), _process_slot never resolved the inflight future
            # -> release riders here so they fall through instead of hanging. On the
            # normal cap<=1 SUCCESS path _process_slot already popped it, so
            # ``pop(..., None)`` returns None and this is a no-op.
            if am_leader:
                pending = self._completion_inflight.pop(cache_key, None)
                if pending is not None and not pending.done():
                    pending.set_result(_FLIGHT_FAILED)

    async def submit_for_streaming(
        self,
        model_tag: str,
        prompt: str = "",
        thread_id: str = "",
        context: list[dict] | None = None,
        client_meta: dict | None = None,
        disconnect_event: "asyncio.Event | None" = None,
        admission_ctx_len: int = 0,
        admission_hash_chain: list[str] | None = None,
    ) -> Slot:
        """SSE streaming pass-through.

        Submit a request that will be consumed by an SSE-streaming route. Unlike
        submit_and_wait, this returns the slot immediately (without awaiting
        the completion_future). Streaming coordination events are armed in
        submit() BEFORE the slot is enqueued, so the worker can NEVER observe
        None events. This method makes the arming
        idempotent — if events are already present (set by submit), it
        preserves them; otherwise it creates them as a safety net.

          - ``slot.stream_ready_event``: worker_loop sets this once the slot
            reaches ACTIVE and the SidecarHandle is stored on
            ``slot.stream_handle``. The route awaits this before opening its
            own httpx.stream() to the sidecar's port.
          - ``slot.stream_done_event``: the route sets this when the stream
            closes (normal exhaustion, client disconnect, or error). Only then
            does worker_loop advance the slot ACTIVE → GRACE.

        client_meta MUST include ``"stream": True`` for worker_loop to
        recognise the streaming path. Existing non-streaming callers are
        unaffected.

        By design, keeping the slot
        ACTIVE for the full stream lifetime prevents ACTIVE_MATCH from
        promoting a second submission against the same sidecar (single-slot
        invariant preserved).
        """
        # Fast Lane OBSERVE — above the submit() call, same discipline
        # as submit_and_wait. Best-effort. NOTE: /v1/embeddings reaches this
        # path with a client_meta carrying no "ip" key (see
        # _fastlane_census_observe's guard) — those requests are counted as
        # skipped, not silently absent.
        try:
            self._fastlane_census_observe(client_meta, thread_id, model_tag)
        except Exception:
            log.exception("Fast Lane census observe failed in submit_for_streaming")
        slot = await self.submit(
            model_tag=model_tag,
            prompt=prompt,
            thread_id=thread_id,
            context=context,
            client_meta=client_meta,
            wait_for_completion=True,  # still attach future so error paths surface
            disconnect_event=disconnect_event,
            admission_ctx_len=admission_ctx_len,
            admission_hash_chain=admission_hash_chain,
            # This IS the one caller that fulfills the
            # stream_ready_event/stream_done_event handshake (see the arming
            # block in submit() for the full rationale) -- explicitly opt in.
            arm_stream_events=True,
        )
        # Events are armed in submit() before enqueue. Make this
        # idempotent — only create if somehow still None (defensive).
        if slot.stream_ready_event is None:
            slot.stream_ready_event = asyncio.Event()
        if slot.stream_done_event is None:
            slot.stream_done_event = asyncio.Event()
        # Emit the proof-surface identity line ONCE per
        # admitted streaming request (mirrors submit_and_wait). Best-effort.
        self._emit_request_identity(
            ip=(slot.client_meta or {}).get("ip"),
            model_tag=model_tag,
            client_meta=slot.client_meta,
            thread_id=slot.thread_id,
            fastlane=slot.fastlane,
        )
        return slot

    # === Error propagation on worker exceptions ==============================

    def _fail_completion_future(self, slot: Slot, exc: BaseException) -> None:
        """If a slot has a pending completion_future, mark it failed (don't hang caller).

        Two gaps are closed here, both on the SAME failure path --
        every failure in this file funnels through this one function (33 call
        sites), so fixing it here closes both everywhere, not just the streaming
        path where the problem was first observed.

        (a) On the streaming path (submit_for_streaming), completion_future is
        attached "so error paths surface" but nothing ever awaits it --
        submit_and_wait is the ONLY caller that does (its own
        ``await asyncio.wait_for(slot.completion_future, ...)``). A set-but-
        never-read exception on a GC'd Future is exactly what asyncio's "Future
        exception was never retrieved" warning is FOR -- and that
        warning is what surfaced this bug in the first place. fut.exception()
        marks it retrieved WITHOUT consuming it -- Future.exception()/.result()
        are idempotent reads, not one-shot consumes, so submit_and_wait's own
        later real await still sees and re-raises the identical exception,
        unaffected. This is a genuine trade, not a strict improvement: the
        never-retrieved warning was a real, if generic and path-blind, signal
        that SOME failure went unobserved somewhere; silencing it here removes
        that safety net for the streaming path specifically. What replaces it
        is (b) below -- a route-visible, path-specific signal instead of a
        generic asyncio warning nobody was routing anywhere actionable.

        (b) On the streaming path specifically, stream_ready_event was NEVER
        set by any failure path -- the route's ready-wait (chat_completion.py,
        the SLOT_READY_TIMEOUT_S deadline loop) blocked for the full 7200s
        instead of failing fast. Waking it here is safe: chat_completion.py
        ALREADY re-checks ``slot.stream_handle is None`` immediately after the
        ready-wait unblocks, before ever opening its httpx.stream() -- and
        EVERY success path in this file (7 call sites)
        assigns stream_handle strictly on the line before
        calling stream_ready_event.set(), so a failure-triggered wakeup with
        stream_handle still None can never be mistaken for a real success.
        stream_ready_failed_reason (slot.py) mirrors the existing
        stream_done_forced_reason idiom on the same dataclass -- stamped before
        the event, so the route can show the real reason instead of its
        original generic fallback message. Guarded on ``not ...is_set()`` so a
        failure arriving after a slot was already legitimately readied cannot
        overwrite a reason nobody will read.
        """
        fut = slot.completion_future
        if fut is not None and not fut.done():
            fut.set_exception(exc)
            fut.exception()  # mark retrieved (a) -- see docstring; safe for a later real await too
        if slot.stream_ready_event is not None and not slot.stream_ready_event.is_set():
            slot.stream_ready_failed_reason = str(exc)
            slot.stream_ready_event.set()

    # === Boot lifecycle =====================================================

    def _migrate_manifest_store(self) -> None:
        """One-time sweep of the manifest store at boot: rewrite each stored manifest
        that still carries a retired key without it. Best effort: any failure is
        logged (no values) and never propagates, so it can never block the start."""
        try:
            rewritten = migrate_retired_keys(self.boot.storage.manifests_path)
        except Exception:
            log.exception("boot: retired-key sweep of the manifest store failed")
            return
        if rewritten:
            log.info("boot: retired-key sweep rewrote %d manifest file(s)", len(rewritten))

    def boot_reconcile(
        self,
        pid_is_alive_fn: Callable[[int], bool] | None = None,
        reap_orphan_fn: "Callable[..., tuple[bool, str]] | None" = None,
    ) -> dict:
        """Run at startup. Returns summary dict for audit logging.

        DURABLE ENGINE-IDENTITY ownership proof (replaces the heuristic
        parent-chain proof): a candidate is reaped ONLY if its live
        (pid, port, starttime) matches a recorded identity in state.sqlite
        (persisted atomically at spawn via record_engine_identity). PPid=1 /
        parent-chain heuristics are NOT ownership proof — a foreign/independent
        llama-server that is itself orphaned (PPid=1) has no recorded identity
        and is report-only, never reaped. The starttime cross-check prevents
        PID reuse.

        BOOT-TIME OWNERSHIP INVARIANT: the orphan reaper's known_pids
        skip-list is EMPTY at boot. Rationale: flock guarantees singleton
        ownership of the manager, so if THIS manager booted, any other
        manager is dead and any of its engines still in /proc are STALE
        orphans to reap — not active sidecars to preserve. Passing live_pids
        (alive per state.sqlite) as known_pids was a correctness bug: a
        recorded P12 no-listener stale engine is alive by definition, so it
        landed in live_pids and was SKIPPED by the reaper, defeating boot
        cleanup. live_pids is still consumed by reconcile_orphaned_slots
        (slots whose pid is dead → COLD) — its correct, separate role.

        UNAVOIDABLE CRASH WINDOW (atomicity limitation): record_engine_identity
        writes the (pid, port, starttime) triple atomically in its own database
        transaction. But there is a window between process spawn (the engine
        is alive in /proc) and
        the identity persisting to state.sqlite: if the manager crashes in
        that window, the engine is alive, unrecorded, and therefore NOT
        reaped by boot_reconcile (no recorded identity → report-only). This is
        a CONSERVATIVE fail-safe: the engine is left for manual/operator
        recovery rather than risked as a false-positive kill of a foreign
        process. It is NOT a silent-data-loss bug — the engine keeps running
        and is surfaced via the stale_listeners diagnostics count + the audit
        log. Closing this window would require persisting the identity BEFORE
        spawn (impossible — starttime is unknown until the process exists) or
        a fork-inheritor pattern (out of scope for PR1).

        Reconciliation passes:
          1. orphan reaper (process-group safe + durable engine-identity pass,
             known_pids=EMPTY at boot): reaps /proc llama-server candidates in
             the managed port range ONLY when their live (pid, port, starttime)
             matches a recorded identity (the P12 no-listener orphan route —
             the manager crashed after recording the identity, the engine has
             no listener, but the record + starttime match proves ownership).
             A foreign llama-server in the range has no record → report-only.
             A diagnostics-only listener scan reports ports still occupied but
             does not reap.
          2. foreign GPU detect — informational only.
          3. state.sqlite reconcile: any slot whose pid is no longer alive → COLD.
          4. KV-cache dir mount/fstype assertion — informational
             only, same posture as pass 2: logged + counted, never a reason to
             refuse to boot.
        """
        self._migrate_manifest_store()
        port_base = self.boot.runtime.default_port_base

        # state.sqlite reconcile: any slot whose pid is no longer alive → COLD.
        # Read recorded engine identities (the durable ownership proof) in the
        # SAME session so the reaper + the reconcile see one snapshot. The
        # durable proof: a candidate is reaped ONLY if its live (pid, port,
        # starttime) matches a recorded identity. PPid=1 / parent-chain
        # heuristics are NOT ownership proof.
        check_alive = pid_is_alive_fn or _pid_is_alive
        with state_db_session(self.boot.storage.state_db_path) as conn:
            stale_pids = known_active_pids(conn)
            recorded_identities = known_engine_identities(conn)
            live_pids = {pid for pid in stale_pids if check_alive(pid)}
            reconciled = reconcile_orphaned_slots(conn, live_pids)

        # 1. orphan reaper (process-group safe + durable engine-identity pass).
        # BOOT-TIME: there is NO current-manager active sidecar to preserve —
        # flock guarantees singleton ownership, so if THIS manager booted, any
        # other manager is dead and its engines are stale orphans. Therefore the
        # known_pids skip-list is EMPTY: the durable-identity match in the
        # stale-engine scan is the SOLE reaping authority. Passing live_pids
        # here was a correctness bug — a recorded P12 no-listener stale engine
        # is alive by definition, so it landed in live_pids (passed as
        # known_pids) and was SKIPPED by the reaper, defeating boot cleanup.
        # live_pids is still consumed by reconcile_orphaned_slots above (slots
        # whose pid is dead -> COLD) — that is its correct, separate role.
        reap = boot_orphan_reaper(
            port_base=port_base,
            reap_fn=reap_orphan_fn,
            manager_pids={os.getpid()},
            known_pids=set(),  # boot: nothing to preserve (flock singleton)
            known_engine_identities=recorded_identities,
        )

        # 2. foreign GPU detect — informational only (we don't refuse to start here;
        # that's a CLI-flag decision)
        foreign = detect_foreign_gpu_apps()

        # 4. KV-cache dir mount/fstype assertion:
        #    FAIL LOUD, KEEP SERVING. Same informational-only posture as the
        #    foreign-GPU detect above — a mismatch is logged + counted, never
        #    a reason to refuse to boot (a running deployment must keep serving). The defect
        #    this closes: a missing/wrong mount does not error, it silently
        #    redirects writes to whatever filesystem is underneath — that
        #    silence, not the GC, is what lets large amounts of KV data strand
        #    unreachably on the backing store.
        kv_mount_issues = self._check_kv_dir_mounts()

        with audit_db_session(self.boot.storage.state_db_path) as conn:
            record_audit_event(
                conn,
                "boot_reconcile",
                {
                    "orphans_reaped": reap["reaped"],
                    "foreign_gpu_apps_count": len(foreign),
                    "slots_reconciled_to_cold": reconciled,
                    "stale_listeners_reaped": reap.get("stale_listeners", 0),
                    "kv_mount_issues_count": len(kv_mount_issues),
                    "kv_mount_issues": kv_mount_issues,
                },
            )

        # Fast Lane: rebuild the discovered-address census from
        # existing tables — NO new table, NO migration. request_count
        # rebuilds correctly (one slots row = one request). served_count
        # UNDERCOUNTS by design and this is a KNOWN, ACCEPTED consequence,
        # not a bug to chase here: the
        # ACTIVE_MATCH warm-reuse serve path emits no audit event, and the
        # completion-cache hit / single-flight rider exits in
        # submit_and_wait never create a slots row at all. Best-effort —
        # never fail boot over a census rebuild.
        try:
            from turbohaul.kv_classify import _class_from_label
            self._fastlane_census.clear()
            with state_db_session(self.boot.storage.state_db_path) as conn:
                rows = conn.execute(
                    "SELECT slot_id, thread_id, model_tag, created_at, client_meta_json "
                    "FROM slots"
                ).fetchall()
                served_counts: dict[str, int] = {}
                for slot_id, count in conn.execute(
                    "SELECT slot_id, COUNT(*) FROM audit_events "
                    "WHERE event_type IN ('active', 'fanout_rider_active') "
                    "GROUP BY slot_id"
                ).fetchall():
                    served_counts[slot_id] = count
            for slot_id, thread_id, model_tag, created_at, client_meta_json in rows:
                try:
                    client_meta = json.loads(client_meta_json) if client_meta_json else {}
                except (TypeError, ValueError):
                    client_meta = {}
                ip = client_meta.get("ip")
                if not ip:
                    self._fastlane_census_skipped_no_ip += 1
                    continue
                # Same normalized-key treatment as _fastlane_census_observe
                # -- two raw forms of one host must rebuild into ONE row here
                # too, or a restart would re-split what live traffic had
                # already merged.
                norm_ip = _fastlane_census_key(ip)
                try:
                    seen_at = datetime.fromisoformat(created_at).timestamp()
                except (TypeError, ValueError):
                    seen_at = time.time()
                row = self._fastlane_census.get(norm_ip)
                if row is None:
                    if len(self._fastlane_census) >= _FASTLANE_CENSUS_MAX:
                        self._fastlane_census_overflow_refused += 1
                        continue
                    row = {
                        "address": ip, "normalized_address": norm_ip,
                        "first_seen": seen_at, "last_seen": seen_at,
                        "request_count": 0, "served_count": 0, "classes": {},
                        "models": set(), "thread_ids": set(),
                        "container_name": None,
                    }
                    self._fastlane_census[norm_ip] = row
                row["first_seen"] = min(row["first_seen"], seen_at)
                row["last_seen"] = max(row["last_seen"], seen_at)
                row["request_count"] += 1
                row["served_count"] += served_counts.get(slot_id, 0)
                cls = _class_from_label(client_meta) or "unclassified"
                row["classes"][cls] = row["classes"].get(cls, 0) + 1
                if model_tag:
                    row["models"].add(model_tag)
                if thread_id:
                    row["thread_ids"].add(thread_id)
        except Exception:
            log.exception("Fast Lane census boot rebuild failed — starting with an empty census")
            self._fastlane_census.clear()

        return {
            "orphans_reaped": reap["reaped"],
            "orphans_failed": reap["failed"],
            "foreign_gpu_apps": foreign,
            "slots_reconciled_to_cold": reconciled,
            "stale_listeners": reap.get("stale_listeners", 0),
            "kv_mount_issues": kv_mount_issues,
        }

    def _check_kv_dir_mounts(self) -> list[str]:
        """Boot-time assertion that SLOT_SAVE_DIR
        and SLOT_PERSIST_DIR are on the filesystem the manager expects.

        FAIL LOUD (log.error + a reason string per issue), NEVER refuse to
        boot — mirrors the foreign-GPU check's informational-only posture
        above. Best-effort throughout: each directory's check is independently
        try/except-guarded so a bug in one check can never take down boot, let
        alone the other check.

        Two DIFFERENT assertion shapes (verified against a running
        configuration):
          - SLOT_SAVE_DIR (RAM/tmpfs tier): must be its OWN mount AND match
            ``runtime.kv.kv_save_expected_fstype`` exactly. This is the
            directory most exposed to this failure — a missing tmpfs mount here
            silently redirects every RAM-tier write to the backing store.
          - SLOT_PERSIST_DIR (cold-storage/disk tier): the INVERSE assertion —
            a FORBIDDEN-fstype list (``runtime.kv.kv_persist_forbidden_fstypes``),
            not an expected one. Own-mount-ness is deliberately NOT asserted
            here: verified against a running configuration, kvcache_persist is a plain
            directory on the underlying filesystem (not its own mount) BY
            DESIGN — asserting own-mount would fire LOUD on a correctly
            configured host on its very first boot. What IS
            assertable: cold storage must never land on a volatile
            filesystem, or it silently evaporates on restart (the same
            failure shape as the one above, on the opposite tier).

        Returns the list of LOUD reason strings (empty == everything nominal).
        Never raises.
        """
        from turbohaul.subprocess_mgr import SLOT_PERSIST_DIR, SLOT_SAVE_DIR

        issues: list[str] = []

        try:
            loud, reason = _classify_kv_dir_mount(
                SLOT_SAVE_DIR,
                expected_fstype=self.runtime.kv.kv_save_expected_fstype,
            )
            if loud:
                issues.append(reason)
                log.error("KV_MOUNT_CHECK save_dir LOUD: %s", reason)
            else:
                log.debug("KV_MOUNT_CHECK save_dir OK: %s", reason)
        except Exception:
            reason = f"{SLOT_SAVE_DIR}: mount check itself raised unexpectedly"
            issues.append(reason)
            log.exception("KV_MOUNT_CHECK save_dir check failed")

        try:
            loud, reason = _classify_kv_dir_mount(
                SLOT_PERSIST_DIR,
                forbidden_fstypes=frozenset(self.runtime.kv.kv_persist_forbidden_fstypes),
            )
            if loud:
                issues.append(reason)
                log.error("KV_MOUNT_CHECK persist_dir LOUD: %s", reason)
            else:
                log.debug("KV_MOUNT_CHECK persist_dir OK: %s", reason)
        except Exception:
            reason = f"{SLOT_PERSIST_DIR}: mount check itself raised unexpectedly"
            issues.append(reason)
            log.exception("KV_MOUNT_CHECK persist_dir check failed")

        return issues

    def verify_binary(self) -> bool:
        """Verify + TOCTOU-pin llama_server_binary at boot.

        Empty expected_sha256 = dev mode -- verify_binary_sha256 returns True
        with no fd pinning; spawn_sidecar falls back to path-based exec.
        Non-empty + matching hash = an inode-pinned fd is held on
        self._binary_fd and every spawn execs via ``/proc/self/fd/<fd>``,
        closing the swap window.
        """
        binary_path = self.boot.runtime.llama_server_binary
        expected = self.boot.runtime.llama_server_binary_sha256
        if not verify_binary_sha256(binary_path, expected):
            return False
        if self._binary_fd is not None:
            # Defensive: close prior fd if verify_binary called twice
            with contextlib.suppress(OSError):
                os.close(self._binary_fd)
            self._binary_fd = None
        if expected:
            self._binary_fd = open_and_verify_binary(binary_path, expected)
            if self._binary_fd is None:
                log.error(
                    "binary hash drift between verify and fd-pin -- refusing"
                )
                return False
        return True

    # === Request acceptance =================================================

    async def submit(
        self,
        model_tag: str,
        prompt: str = "",
        thread_id: str = "",
        context: list[dict] | None = None,
        client_meta: dict | None = None,
        wait_for_completion: bool = False,
        disconnect_event: "asyncio.Event | None" = None,
        admission_ctx_len: int = 0,
        admission_hash_chain: list[str] | None = None,
        arm_stream_events: bool = False,
    ) -> Slot:
        """Accept a fresh inference request.

        - If thread_id is empty, auto-derive from prompt-prefix-hash.
        - If grace window is open for this thread+model → enqueue at FIFO HEAD
          + restart grace timer (max_grace_extensions cap applies).
        - admission_ctx_len: incoming context size recorded at admission
        - admission_hash_chain: incoming turn-hash chain recorded at admission
        - arm_stream_events: must be True ONLY from a
          caller that will actually fulfill the stream_ready_event/stream_done_event
          handshake (today: submit_for_streaming only). See the arming block below
          for why this cannot be inferred from client_meta alone.
        - Otherwise → normal FIFO enqueue.

        Raises RuntimeError if the manager is shutting down.
        """
        # Refuse new submissions after shutdown signal so
        # callers fail fast instead of hanging on a completion_future that
        # will never resolve (worker is dead, queue.close() clears staging).
        # Raises queue.QueueClosed to match existing test_manager contract +
        # the documented queue-closed exception type.
        if self._stop_event.is_set():
            from turbohaul.queue import QueueClosed
            raise QueueClosed(
                "TurbohaulManager is shutting down — new submissions are refused."
            )

        if not thread_id:
            thread_id = derive_thread_id_prefix_hash(
                prompt, model_tag,
                prefix_tokens=self.runtime.queue.prefix_token_count,
            )

        slot = Slot.new(
            model_tag=model_tag,
            prompt=prompt,
            thread_id=thread_id,
            context=context,
            client_meta=client_meta,
            admission_ctx_len=admission_ctx_len,
            admission_hash_chain=admission_hash_chain,
        )
        # Stamp the ADMISSION-resolved role BEFORE enqueue —
        # the warm-inherit clobber (T3 restore) replaces slot.client_meta wholesale
        # for same-session inherits, so a role read there can mis-see a disposable
        # as "main" (FP F1). This attribute survives the clobber (client_meta is
        # the only field it replaces) and equals _bin_role-at-admission by
        # construction (same vocabulary as _disp_role).
        slot.admission_role = _bin_role(client_meta)
        # Fast Lane: admission-time priority match. Best-effort —
        # never let a matcher failure block a real request; slot.fastlane
        # stays None (feature-off equivalent) on any exception. Must be
        # BEFORE the grace-window fork below so a grace-matched re-cue is
        # untouched by this stamp.
        try:
            slot.fastlane = match_fastlane(
                self._fastlane_table(),
                (client_meta or {}).get("ip"),
                client_meta,
            )
        except Exception:
            log.exception("Fast Lane match_fastlane failed at admission — degrading to no match")
            slot.fastlane = None
        # Caller-attached disconnect_event (lazy-init in
        # the route's own loop). None for non-HTTP callers
        # (BootInventory orphan-replay, internal probes, tests pre-attach).
        slot.disconnect_event = disconnect_event

        # Arm streaming events BEFORE enqueue so the worker
        # can NEVER see None. submit_for_streaming previously armed these AFTER
        # submit() returned — leaving a window where ACTIVE_MATCH promotion
        # could observe None events and assert-crash. Arming here closes the
        # race entirely (events always exist before the slot is visible to worker).
        #
        # Arming is not gated on client_meta["stream"]
        # ALONE. That flag is CLIENT-influenced data (it traces back to whatever
        # the HTTP caller sent) and must not control an INTERNAL PROTOCOL
        # decision (does the manager require the CALLER's own code to fulfill the
        # stream_ready_event -> httpx.stream() -> stream_done_event handshake).
        # ollama_chat sets client_meta["stream"]=True to faithfully record the
        # client's request shape, but always calls submit_and_wait — which never
        # awaits stream_ready_event, never opens a stream, and never sets
        # stream_done_event. _serve_on_resident (and its ACTIVE_MATCH / idle-hot
        # mirrors) pick the streaming branch from is_streaming, which only checks
        # client_meta["stream"] + both events non-None; for a slot with armed events
        # and no caller-side handshake the worker would wait on
        # `asyncio.wait_for(stream_done_event.wait(), timeout=_STREAM_TIMEOUT_S)`
        # until the timeout expires, then force-resolve with a placeholder
        # {"_streamed": True} result instead of the real completion. `arm_stream_events` is
        # an explicit, WRAPPER-controlled signal instead: only submit_for_streaming
        # passes True (it and its caller-side route are the only code that
        # actually performs the handshake). submit_and_wait passes nothing (False
        # by default), so a slot it creates can never have non-None stream events,
        # which makes every downstream is_streaming check (all of which require
        # both events to be non-None) correctly evaluate False regardless of what
        # client_meta["stream"] says — closing this at the one place events are
        # ever created, not at each individual branch site.
        if (arm_stream_events and isinstance(client_meta, dict)
                and client_meta.get("stream")):
            slot.stream_ready_event = asyncio.Event()
            slot.stream_done_event = asyncio.Event()
            slot.stream_handle = None

        # Attach a future BEFORE enqueue so worker_loop can resolve it on completion.
        if wait_for_completion:
            slot.completion_future = asyncio.get_running_loop().create_future()

        # Grace-window matched-thread shortcut
        if self.grace.matches(thread_id, model_tag):
            await self.queue.enqueue_head(slot)
            # restart_for_followup may return False if at extension cap; that's fine,
            # the request still queues at head once, but the slot will pop next cycle.
            self.grace.restart_for_followup()
        else:
            await self.queue.enqueue(slot)
            # Register a Fast Lane claim the
            # instant the slot LANDS in staging (not only later at a
            # failed route). Without this, a fastlane-eligible request
            # that is never popped by pop_next -- because a resident is
            # busy in pop_matched_thread for same-thread grace follow-ups
            # -- never reaches _defer_unroutable and therefore never gets
            # a claim. No claim => _governing_claim_locked returns None =>
            # _is_designated_unload_target_locked returns False forever,
            # regardless of wait time. Registering at staging arrival
            # closes that gap. The dedup in _register_fastlane_claim_locked
            # makes the later _defer_unroutable call a
            # no-op refresh; the existing "admitted" release at every HIT
            # path cleans it up when the slot is served.
            await self._register_staged_claim(slot, "staging_arrival")

        # Audit — slot-write stays on state_db_session; audit-write goes
        # through the pool wrapped in asyncio.to_thread (sync-only guard).
        with state_db_session(self.boot.storage.state_db_path) as conn:
            upsert_slot(
                conn,
                {
                    "slot_id": slot.slot_id,
                    "model_tag": slot.model_tag,
                    "thread_id": slot.thread_id,
                    "state": slot.state.value,
                    "client_meta": slot.client_meta,
                },
            )

        def _audit_submit() -> None:
            with audit_db_session(self.boot.storage.state_db_path) as audit_conn:
                record_audit_event(
                    audit_conn,
                    "submit",
                    {"thread_id_prefix": (thread_id or "")[:8], "model_tag": model_tag},
                    slot_id=slot.slot_id,
                )

        await asyncio.to_thread(_audit_submit)

        # Telemetry — capture request arrival + queue state
        try:
            self._telemetry.on_request_arrival(slot)
            self._telemetry.on_queue_state(self.queue.depth(), slot)
        except Exception:
            pass  # observe-only: never break the hot path

        # Shadow byte-match self-check (DORMANT, observability ONLY): on this
        # (N+1) admission, compare the harness's resent think-stripped assistant-N turn
        # against turn N's stashed think-free hash. PURE measurement — the slot is already
        # enqueued above; this only reads/hashes/logs/counts and changes NO decision.
        # Self-protecting (internal try/except) so it can never raise into submit().
        self._compare_shadow_bytematch_probe(thread_id, context, client_meta)

        # Compression: a LABELED is_compression request for a session marks
        # that session's MAIN clean anchor stale at ADMISSION. Label-gated
        # (resolved class must be compression per the PL priority order) ->
        # zero cost for normal traffic; best-effort, never raises into submit.
        try:
            _cm = client_meta or {}
            if _cm.get("is_compression") and _cm.get("session_id"):
                from turbohaul.kv_classify import _class_from_label, CLASS_COMPRESSION
                if _class_from_label(_cm) == CLASS_COMPRESSION:
                    self._mark_main_bin_stale_for_session(
                        str(_cm.get("session_id")), reason="is_compression_submit")
        except Exception:
            log.debug("R-COMP submit-time stale-mark failed (best-effort)", exc_info=True)

        return slot

    # === Status snapshot =====================================================

    def status_snapshot(self) -> dict:
        """/status payload."""
        # A request whose model already has a live resident is handed
        # straight to that resident's inbox and returns -- queue.enqueue() is
        # never called, so it never enters _staging/_accept_buf and queue.py
        # cannot see it. Without this the reported depth reads 0 while work is
        # genuinely queued. queue.py has no visibility into resident inboxes
        # and must not import them, so the count is supplied from here.
        #
        # Also count live Fast Lane claims here.
        # _defer_unroutable parks MISS/defer slots in _fastlane_claims,
        # invisible to staging+accepted+inbox_waiting during the backoff
        # requeue window -- operator reads 0 while claims genuinely wait.
        # fastlane_claims_snapshot() prunes dead claims inline, so len() of
        # its live result is the correct count. Reused below at the
        # fastlane_claims_snapshot field to avoid a second prune pass.
        # A claim parked in a resident inbox is counted once: inbox_waiting
        # leaves it out (see _inbox_waiting_count).
        claims_snapshot = self.fastlane_claims_snapshot()
        depth = self.queue.depth(
            inbox_waiting=self._inbox_waiting_count(),
            claims_waiting=len(claims_snapshot),
        )

        # queue.py's queue_snapshot() rows
        # can't resolve a LIVE fastlane label or likely_victim -- both need
        # manager-only state (_live_fastlane_label, the resident registry)
        # that module has no access to (same boundary depth()'s own
        # inbox_waiting parameter already respects). Enriched here, once,
        # before this reaches /status -- never inside queue.py.
        queue_waiting = self._waiting_surface_rows(
            self.queue.queue_snapshot(limit=50))
        likely_victim = self._likely_unload_target_model_tag()
        for row in queue_waiting:
            row["likely_victim"] = likely_victim
            fl = row.get("fastlane")
            if fl is not None:
                fl["label"] = self._live_fastlane_label(fl["fastlane_rule"])

        active_info: dict | None = None
        loading_info: dict | None = None
        # Resolve cap-awarely (template: _resolve_top_level_active_slot).
        # At cap>=2, self._active_slot is PERMANENTLY unwritten (worker_loop branches
        # into _dispatch_loop, and all _set_active_slot call sites live inside
        # _process_slot, which is never reached again). The live per-resident
        # active_slot is maintained by _drive_resident/_serve_on_resident.
        slot = self._resolve_top_level_active_slot()
        handle = self._resolve_top_level_active_handle()
        if slot is not None:
            # FE LOADING transition fix: split status into ACTIVE vs the
            # pre-active transitional states (STAGED / PRE_LOADING /
            # LOADING / READY). Before this split, FE saw active=null
            # for the whole 5-30s cold-load window — reads as a hang.
            state_v = slot.state.value
            if state_v == "ACTIVE" or state_v == "ACTIVE_MATCH":
                if handle is not None:
                    active_info = {
                        "slot_id": slot.slot_id,
                        "model_tag": slot.model_tag,
                        "state": state_v,
                        # Redaction: only first 8 chars of thread_id exposed
                        "thread_id_prefix": (slot.thread_id or "")[:8],
                        "pid": handle.pid,
                        "port": handle.port,
                        # Named engine operation for FE Dashboard pill
                        "engine_op": getattr(slot, "engine_op", "idle"),
                    }
            elif state_v in {"STAGED", "PRE_LOADING", "LOADING", "READY"}:
                elapsed = 0.0
                started = getattr(slot, "started_loading_at", None) or getattr(slot, "received_at", None)
                if started is not None:
                    elapsed = max(0.0, time.monotonic() - started)
                loading_info = {
                    "slot_id": slot.slot_id,
                    "model_tag": slot.model_tag,
                    "state": state_v,
                    "thread_id_prefix": (slot.thread_id or "")[:8],
                    "elapsed_s": round(elapsed, 1),
                    "pid": handle.pid if handle else None,
                    "port": handle.port if handle else None,
                    # Named engine operation for FE Dashboard pill
                    "engine_op": getattr(slot, "engine_op", "idle"),
                }

        # The slot-derived block above is skipped entirely when a sidecar
        # is still spawning, because the RESIDENT is RESERVED_LOADING and its
        # active_slot is None. Without this, active/loading/grace/idle_hot are ALL
        # None while residents[] is populated, synthesizeResident.ts renders
        # nothing, and the dashboard panel disappears for the whole spawn --
        # which can take tens of seconds. Only fills a gap: if the slot
        # path already produced active_info or loading_info, this is a no-op.
        if active_info is None and loading_info is None:
            _lr = self._resolve_top_level_loading_resident()
            if _lr is not None:
                _elapsed = 0.0
                _res_at = getattr(_lr, "reserved_at_monotonic", 0.0) or 0.0
                if _res_at:
                    _elapsed = max(0.0, time.monotonic() - _res_at)
                _lh = getattr(_lr, "handle", None)
                loading_info = {
                    "slot_id": getattr(_lr, "resident_key", None),
                    "model_tag": _lr.model_tag,
                    "state": ResidentState.RESERVED_LOADING.value,
                    "thread_id_prefix": "",
                    "elapsed_s": round(_elapsed, 1),
                    "pid": (getattr(_lh, "pid", None) if _lh is not None
                            else getattr(_lr, "booting_pid", None)),
                    "port": (getattr(_lh, "port", None) if _lh is not None
                             else getattr(_lr, "port", None)),
                    "engine_op": "loading",
                }

        # The resident panel can be empty DURING A SWAP even
        # with the loading-resident fix above in place. It is a DIFFERENT window and that fix cannot cover
        # it: that fix resolves a RESIDENT OBJECT in RESERVED_LOADING, and here there is no
        # resident object at all.
        #
        # THE WINDOW, as it appears in the manager log:
        #   MAKE_ROOM_EVICTION model-a          -> del self._residents[...]
        #   KV_SAVE_DECLINE ... reap_resident_handle
        #   spawning llama-server model-b...    -> next reservation, seconds LATER
        # Between the del and the next reservation the
        # registry is EMPTY while the dying process STILL HOLDS THE CARD. residents[] is [],
        # every top-level surface is None, and synthesizeResident.ts -- which is
        # `active ?? loading ?? grace ?? idle_hot` -- yields null and renders NOTHING, while
        # the VRAM bar reads a SEPARATE field and still shows the card nearly full.
        # Behaviour guarded: the registry is empty while the VRAM bar still shows the card nearly full, so no resident card would be drawn.
        #
        # Requirement: the panel must show that the new model is loading and must
        # not just disappear entirely. If one of the cards is loaded with a model, it
        # must still be shown.
        #
        # ONLY fills a gap: if anything above already claimed active/loading, this is a no-op.
        if active_info is None and loading_info is None:
            _free = self._vram_free_mib
            _tot = self._vram_total_mib
            # The INCOMING tag, resolved BEFORE the gate because the gate
            # now depends on it. ``_reserving_model_tag`` (see ``_reserving``) is the
            # only thing that names a model mid-reserve: by then it has been DEQUEUED,
            # so ``queue_waiting`` no longer carries it -- it rarely held the
            # incoming tag across the window. The queue scan is
            # kept as the fallback for the instant BEFORE the dequeue, and for a
            # reserve that no call site marked.
            _incoming = getattr(self, "_reserving_model_tag", None)
            if _incoming is None:
                for _row in (queue_waiting or []):
                    _mt = _row.get("model_tag") if isinstance(_row, dict) else None
                    if _mt:
                        _incoming = _mt
                        break
            # GATE WIDENED, for the reason below.
            # It was ``not self._residents_snapshot()``: the registry ENTIRELY empty.
            # That covers a swap which leaves NOTHING resident, but with any other
            # resident standing the registry is non-empty and this branch could never
            # fire -- while the incoming model still has no Resident object of its own,
            # so ``_resolve_top_level_loading_resident`` cannot fire either.
            # The two existing fixes have a GAP between them and the reserve window
            # sits in it: for most of the window the
            # incoming model is named on NO
            # display surface (residents/active/loading/grace/idle_hot), only on
            # ``request_identity``, which is a proof surface the dashboard never
            # renders a card from. Widened to "no Resident for the INCOMING tag", which
            # is strictly weaker: the empty-registry case still qualifies.
            _no_resident_for_incoming = bool(
                _incoming is not None and not self._instances_for(_incoming)
            )
            if _free is not None and _tot is not None and (
                not self._residents_snapshot() or _no_resident_for_incoming
            ):
                _held = [max(0, int(_t) - int(_f)) for _t, _f in zip(_tot, _free)]
                # "materially allocated" = a model, not a driver context. A card carrying a
                # model is GiBs; an idle card is tens of MiB.
                if any(_h > 1024 for _h in _held):
                    # (_incoming resolved above -- the gate needs it.)
                    loading_info = {
                        "slot_id": None,
                        # THE LOGIC GATE: show the old model
                        # name until it is known that a new model is incoming, and then keep showing
                        # the old model name until the VRAM
                        # drops. So model_tag is the OUTGOING model -- the one STILL ON THE
                        # CARD -- held until VRAM falls below the floor. That is the honest
                        # answer to the requirement that a card still holding a model stays
                        # visible: the card holds the OLD model, not the new one.
                        # The incoming model is reported ALONGSIDE it, never instead.
                        "model_tag": (getattr(self, "_last_unloaded", None) or {}).get("model_tag"),
                        "incoming_model_tag": _incoming,
                        "state": ("UNLOADING"
                                  if (getattr(self, "_last_unloaded", None) or {}).get("model_tag")
                                  else "TRANSITION"),
                        "thread_id_prefix": "",
                        "elapsed_s": 0.0,
                        "pid": None,
                        "port": None,
                        "engine_op": "swapping",
                        # Additive; a consumer that does not know these ignores them.
                        "transition": True,
                        "vram_held_mib": _held,
                    }

        grace_info: dict | None = None
        # Resolve grace from the representative RESIDENT grace state
        # instead of self.grace. self.grace is PERMANENTLY unwritten at every
        # cap level: its only start() call site lived inside _process_slot
        # which has since been retired. So self.grace.expired() is always
        # True and grace_info stays None forever — the FE has nothing to draw.
        # The live per-resident grace timer is maintained by _serve_on_resident
        # (r.grace.start(...), fired on every turn completion
        # regardless of cap). Resolve via _resolve_top_level_grace_resident.
        grace_resident = self._resolve_top_level_grace_resident()
        if grace_resident is not None and active_info is None:
            grace_info = {
                "remaining_s": int(grace_resident.grace.remaining_s()),
                "extension_count": grace_resident.grace.extension_count,
                "max_extensions": grace_resident.grace.max_extensions,
                "thread_id_prefix": (grace_resident.grace.thread_id or "")[:8] if grace_resident.grace.thread_id else "",
                "model_tag": grace_resident.grace.model_tag,
            }

        idle_info: dict | None = None
        # Resolve idle from the representative RESIDENT idle state
        # instead of self._idle_handle / self.idle. Both are PERMANENTLY
        # unwritten at every cap level: the only non-None write site for
        # self._idle_handle is _set_idle_holder, called
        # exclusively from _process_slot, which has been retired.
        # self.idle.start() is also only called from _process_slot. So both
        # manager-level scalars are always None/0 and idle_info stays None
        # forever — the same defect class as grace_info.
        # The live per-resident idle state is maintained by _serve_on_resident
        # (r.idle_expires_at = time.monotonic() + idle_window).
        idle_resident = self._resolve_top_level_idle_resident()
        if idle_resident is not None:
            remaining = int(idle_resident.idle_expires_at - time.monotonic())
            if remaining > 0:
                idle_info = {
                    "remaining_s": remaining,
                    "model_tag": idle_resident.model_tag,
                }

        # Cache the vram ref ONCE so the null-check + list() see the same value.
        # (status_snapshot is a sync def with no await, so single-threaded asyncio
        # already makes it atomic vs the supervisor's _vram_free_mib write — this is
        # belt-and-suspenders against a future await/second-writer ever sneaking in.)
        vram_cache = self._vram_free_mib
        return {
            "queue": {
                "acceptance_buffer_depth": depth["acceptance_buffer_depth"],
                "staging_queue_depth": depth["staging_queue_depth"],
                "staging_queue_max": depth["staging_queue_max"],
                # The number of requests ACTUALLY waiting, including
                # those held in a busy resident's inbox where the two fields
                # above cannot see them. Added ALONGSIDE them, never folded
                # into them: telemetry.py persists staging_queue_depth
                # verbatim into a durable per-event log keyed on its current
                # meaning, and the FE renders it as a capacity percentage
                # against staging_queue_max.
                "queue_depth_total": depth["queue_depth_total"],
                # Reports the live claims. It depends on the
                # claim-registration mechanism; with that
                # mechanism in place, this calls the real
                # method. This call site ONLY -- fastlane_claims_snapshot()'s
                # own body and shape are unchanged here.
                "fastlane_claims_snapshot": claims_snapshot,
                # The waiting-request surface
                # -- client/tag/rank/state for the whole wait, plus
                # likely_victim. See queue_snapshot()'s own docstring
                # (queue.py) for the row shape and the accept-buffer
                # inclusion rule.
                "waiting": queue_waiting,
            },
            "active": active_info,
            "loading": loading_info,
            "grace": grace_info,
            "idle_hot": idle_info,
            # Client-disconnect eviction observability.
            "evictions": {
                "total_lifetime": self._unload_count,
                "last_evicted_at": self._last_unloaded_at_iso,
            },
            # Per-card VRAM pledged-to-free by in-flight
            # evict teardowns. The direct observable for the
            # stuck-reclaim bug -- a card stuck non-zero here with no
            # eviction activity means make-room is permanently blocked on
            # it. Previously invisible (reclaims 0 times in normal
            # operation); additive, read-only.
            "pending_reclaim_mib": dict(self._pending_reclaim_mib),
            # KV CLASSIFIER: per-event decision counts + forced-clean-
            # restore total + last decision. PROVES "Turbohaul determines each event"
            # and reused the clean bin (vs CLEAR). event_type ∈ continuation |
            # user-message | compression | sub-agent | guard-skip. clean_bin_id is a
            # thread-HASHED filename (non-reversible; no raw thread_id exposed).
            "kv_classifier": {
                "events": dict(self._kv_classifier_counts),
                "forced_clean_restores": self._kv_classifier_forced,
                # Cold-path clean-restore (wave-return) total. Separate
                # from the WARM forced_clean_restores so a working wave-return proves out.
                "wave_return_restores": self._kv_classifier_wave_return,
                "last": self._kv_classifier_last,
            },
            # Proof surface: LAST per-request
            # structured identity dict (ip/model_tag/session_id/is_*/
            # resolved_class/thread_id) -- regardless of whether it is still
            # running. Additive; existing keys unchanged. See
            # RequestIdentityStrip.tsx for the FE's own naming of this same
            # distinction ("REQUEST RECORD... NOT the resident's current
            # identity"); current_request_identity below is that missing half.
            "request_identity": self._identity_with_live_label(
                self._last_request_identity
            ),
            # The identity actually
            # driving the system RIGHT NOW -- null when idle. LOAD-BEARING at
            # cap<=1 (residents is EMPTY there, so this key is the ONLY place
            # the feature is visible on that config) AND at cap>=2 (self.
            # _active_slot is never written once worker_loop branches into
            # _dispatch_loop -- see _resolve_top_level_active_slot's own
            # docstring for the full mechanism/why-not-staleness).
            "current_request_identity": self._identity_with_live_label(
                self._current_request_identity(self._resolve_top_level_active_slot())
            ),
            # Fast Lane: four-scalar badge only — a 256-row census
            # table does not belong on the 1Hz-polled /status. Full table is
            # fastlane_census_snapshot() (the API route serves it).
            "fastlane": self._fastlane_status_badge(),
            # Observability: last N LOAD_VERIFY records — per model
            # (re)spawn + KV restore, the REAL end-state (process_alive, model_resident,
            # kv_actual_n_past vs expected). Additive read-only surface; the emitter +
            # ring live in turbohaul.load_verify_log (module scope, no instance state).
            "load_verify": load_verify_log.get_recent(20),
            # Observability: last N SPEC_DOWNGRADE records --
            # per model, an informational "speculation ran without the
            # requested acceleration" event, NEVER an error/failure record
            # (those stay on ResidentState.LOADING_FAIL, a different field,
            # by construction -- see spec_downgrade_log.py). Additive
            # read-only surface, same module-scope-ring shape as load_verify
            # above.
            "spec_downgrade": spec_downgrade_log.get_recent(20),
            # D3 (ENGINE STALLED): set at the death-strike increment in the
            # worker_loop dead-idle sweep (restore-implicated engine death);
            # cleared on the next successful serve (ACTIVE->GRACE). None when
            # healthy. {active, attempt, max, bin, ts}. Additive, display-only —
            # FE renders "ENGINE STALLED — Retrying {attempt}/{max}" off .active.
            "engine_stall": getattr(self, "_engine_stall", None),
            # Shadow byte-match self-check (DORMANT observability): counts of
            # match / mismatch / skipped_{no_think,toolcall,empty}. PROVES whether the
            # manager's think-free strip byte-matches the harness's think-stripped resend
            # — the assumption shadow-reprefill reuse hinges on. Drives NO decision.
            "shadow_bytematch": dict(self._shadow_bytematch_counts),
            # Shadow-reprefill (SAVE-side): counts of shadow bins
            # written (saved) + guard skips (skipped_{toolcall,no_think,empty,
            # no_messages}) + reprefill_post_failed. INERT unless TURBOHAUL_SHADOW_
            # REPREFILL is on; drives NO restore/admission/routing decision.
            "shadow_reprefill": dict(self._shadow_reprefill_counts),
            # Shadow-restore PREFERENCE (RESTORE-side): counts of
            # warm forced-restores that PREFERRED the think-free .shadow bin (preferred)
            # vs fell back to the clean anchor (clean_fallback). INERT unless
            # TURBOHAUL_SHADOW_RESTORE_PREFER; drives NO restore/admission/routing
            # decision (obs-only belt, mirrors shadow_reprefill).
            "shadow_restore_prefer": dict(self._kv_shadow_restore_counts),
            # TOOL-tail restore skip: counts of restores skipped
            # because the divergent tail was tool-opaque (hash-invisible), split
            # warm (forced) vs cold (wave-return). Default ON; drives NO other
            # decision (the skip itself is the effect).
            "tooltail_restore_skip": dict(self._kv_tooltail_skip_counts),
            # STALE-tail restore skip: counts of WARM forced restores skipped
            # because resident warm turns exceeded the incoming request's own
            # turns. Default ON; drives no other decision (the skip itself is
            # the effect).
            "staletail_restore_skip": dict(self._kv_staletail_skip_counts),
            # SHADOW-DIAGNOSIS (INSTRUMENTATION ONLY): one block that lets
            # a forcing-full swap-back name WHY. `saves` (== _shadow_reprefill_counts)
            # carries the per-turn save outcomes {saved, skipped_*, reprefill_post_
            # failed} AND the swap-belt {swap_saved, swap_skip_have_fresher, swap_
            # reprefill_post_failed} = candidate (a) shadow-never-saved. `restores`
            # = which bin the cold restore chose (candidate (c) present-but-not-
            # selected). `byteparity` = candidate (d) selected-but-BYTE-DIVERGES.
            # `kvgc` = candidate (b) evicted-under-cap + the 64GB-floor characterization
            # (over_cap + protected bins/bytes + top protected thread_hashes). Drives
            # NO decision.
            "shadow_diag": {
                "saves": dict(self._shadow_reprefill_counts),
                "restores": dict(self._shadow_diag_counts["restores"]),
                "byteparity": dict(self._shadow_diag_counts["byteparity"]),
                # candidate (b): a `.shadow` bin reaped by the ceiling/over-cap GC
                # while dead-session clean anchors held the floor.
                "evictions": dict(self._shadow_diag_counts["evictions"]),
                "kvgc": dict(self._last_kvgc_snapshot) if self._last_kvgc_snapshot else {},
            },
            # Background sweeper that finalizes the
            # state-row for client-disconnect evictions (deferred from the hot path).
            # Sweeper runs every background_sweep_interval_s.
            "background_sweeper": {
                "last_sweep_iso": self._last_sweep_iso,
                "slots_finalized_lifetime": self._slots_finalized_lifetime,
            },
            "parallel_slots": {
                # Resolve cap-awarely. At cap>=2, self._inflight is
                # PERMANENTLY unwritten (only written in _process_slot / fan-out paths,
                # which are never reached again after the cap fork). The live per-resident
                # inflight is maintained by _drive_resident/_serve_on_resident.
                # Design #1: live in-flight rider count when a fan-out is active
                # (best-effort, await-free same-loop read), else 1 if a handle is
                # warm, else 0. `max` reads the runtime cap
                # (max_parallel_sidecars) UNCONDITIONALLY -- preferring
                # the active handle's OWN --parallel width shadowed the cap
                # whenever a handle resolved (for example used=2, max=1 with
                # width=1, cap=2 -- wrong precisely while serving). By design, max is
                # the maximum number of sidecars allowed versus
                # how many are actually active.
                "used": (
                    len(self._inflight)
                    if self._inflight
                    # At cap>=2 count EVERY serving
                    # resident. self._inflight is PERMANENTLY unwritten there (its
                    # only writers, _fan_out_and_drain / _drain_nonstreaming_riders,
                    # are reachable only from _process_slot), so the len() branch
                    # above is never taken; and _resolve_top_level_active_handle
                    # returns ONE handle (`return best_r.handle`), so `used`
                    # could never exceed 1 while two sidecars streamed. Without this
                    # fallback: used=0 with both residents ACTIVE.
                    # The FE renders this straight to the queue tab
                    # (src/frontend/src/components/Queue.tsx, "{used} / {max}").
                    # `or` keeps the legacy fallback, so cap<=1 -- where
                    # _model_residents() is EMPTY -- is byte-identical.
                    else (
                        sum(
                            1
                            for _r in self._model_residents()
                            if getattr(
                                getattr(_r.active_slot, "state", None), "value", None
                            )
                            in ("ACTIVE", "ACTIVE_MATCH")
                        )
                        or (1 if self._resolve_top_level_active_handle() else 0)
                    )
                ),
                "max": self.runtime.queue.max_parallel_sidecars,
            },
            # Live inference monitor: tok/s + progress, written await-free by the
            # LiveSlotsPoller (idle default = single idle_generation() shape).
            # Counts/rates only — no prompt/response/IP/full-thread-id (the
            # 8-char generation_id is non-reversible). At cap>=2 this is the
            # back-compat ALIAS = the most-recently-active resident's generation
            # (the supervisor mirrors it); the per-resident blocks ride residents[].
            "generation": self.live_generation or idle_generation(),
            # P1e multi-slot observability. ``residents`` = the live
            # per-model sidecars. At cap>=2 it's the registry snapshot; at cap<=1
            # the singleton resident is synthesized here from the same live FSM
            # state the FE's synthesizeResident() would use, plus the truthful
            # model_resident flag (from the latest LOAD_VERIFY record — see Fix A,
            # which probes /v1/models for MLX). This keeps the Residents panel
            # populated for single-sidecar installs instead of relying on the FE
            # fallback. ``vram`` = per-GPU free MiB cached off the hot path by the
            # supervisor (null at cap<=1 / probe-down).
            "residents": (
                self._residents_snapshot()
                if int(getattr(self.runtime.queue, "max_parallel_sidecars", 1) or 1) >= 2
                else self._singleton_resident_snapshot(
                    active_info, loading_info, grace_info, idle_info
                )
            ),
            "vram": list(vram_cache) if vram_cache is not None else None,
            "vram_total_mib": list(self._vram_total_mib) if self._vram_total_mib is not None else None,
            # Persist KV cache SSD usage snapshot for FE Settings cap display
            "persist_kvcache": self._persist_kvcache_snapshot(),
        }

    def _singleton_resident_snapshot(
        self,
        active_info: dict | None,
        loading_info: dict | None,
        grace_info: dict | None,
        idle_info: dict | None,
    ) -> "list[dict]":
        """cap<=1 Residents panel entry (single-sidecar install observability).

        At cap>=2 the registry snapshot (``_residents_snapshot``) is authoritative.
        At cap<=1 the singleton resident is intentionally NOT in ``_residents``
        (Phase-0 scaffold), so build one entry here from the live FSM state. We
        mirror the FE's ``synthesizeResident`` precedence (active > loading >
        grace > idle_hot) but pull ``state``/``pid``/``port`` from the REAL handle
        (``_active_handle`` / ``_idle_handle``) so the panel is fully populated, and
        fold in the truthful ``model_resident`` flag from the latest LOAD_VERIFY
        record (Fix A: MLX now reports resident correctly via /v1/models). Matches
        the frontend ``ResidentModel`` shape field-for-field. Await-free + lock-free
        (status_snapshot contract).
        """
        # Priority of FSM phases → the informative source dict + a state string.
        if active_info is not None:
            state_v: str | None = active_info.get("state")
            src = active_info
        elif loading_info is not None:
            state_v = loading_info.get("state")
            src = loading_info
        elif grace_info is not None:
            state_v = "GRACE"
            src = grace_info
        elif idle_info is not None:
            state_v = "IDLE_HOT"
            src = idle_info
        else:
            state_v = None
            src = None

        # Real handle (warm sidecar): idle holder at cap<=1, else the active one.
        handle = self._idle_handle or self._active_handle
        if src is None and handle is not None:
            # No transitional phase active but a sidecar is alive → treat as idle-hot.
            state_v = "IDLE_HOT"
            src = {"model_tag": self._idle_model_tag}

        if state_v is None or src is None:
            return []

        model_resident: bool | None = None
        for rec in reversed(load_verify_log.get_recent(20) or []):
            if rec.get("model_resident") is not None:
                model_resident = rec["model_resident"]
                break
        idle_in = None
        if state_v in ("GRACE", "IDLE_HOT"):
            idle_in = src.get("remaining_s")
        return [{
            "model_tag": src.get("model_tag"),
            "state": state_v,
            "port": int(src.get("port") or (handle.port if handle is not None else 0) or 0),
            "pid": int(src.get("pid") or (handle.pid if handle is not None else 0) or 0),
            "spawn_seq": getattr(self, "_spawn_seq", 0) or 0,
            "reserved_need_mib": 0,
            "parallel": 1,
            "main_gpu": 0,
            "split_mode": "single",
            "inflight": len(self._inflight),
            "idle_expires_in_s": idle_in,
            "model_resident": model_resident,
            "generation": self.live_generation or idle_generation(),
        }]

    def _residents_snapshot(self) -> "list[dict]":
        """Await-free per-resident view for /status (cap>=2 multi-slot observability).

        EMPTY at cap<=1 (``_SINGLETON_RESIDENT_KEY`` + DEAD residents excluded — the
        legacy active/loading/grace/idle_hot fields carry the single-sidecar state).
        Snapshots ``_residents`` via ``list()`` so a concurrent dispatcher mutation
        can't 'dict changed size during iteration'; reads each resident's scalars
        directly (sole-writer driver discipline). LOCK-FREE — never acquires
        ``_registry_lock`` (mirrors status_snapshot's hot-path-safe contract). Each
        entry carries the resident's live generation block (from ``live_generations``)
        so the FE shows per-model tok/s without a second round-trip."""
        out: list[dict] = []
        for k, r in list(self._residents.items()):
            if k == _SINGLETON_RESIDENT_KEY or r.state is ResidentState.DEAD:
                continue
            handle = r.handle
            pid = handle.pid if handle is not None else r.booting_pid
            # ONE resolver, TWO outputs. `idle_expires_in_s` is
            # DERIVED from this same call and never computed alongside it -- a second,
            # parallel computation would re-create, under the word "alias", exactly the
            # two-sources-of-truth defect this design exists to remove (the requirement is
            # structural: one function, two outputs, not a convention). Structurally
            # enforced here: there is no other read of
            # r.idle_expires_at or r.grace anywhere in this function.
            phase = _resident_phase(r, time.monotonic())
            idle_in = (
                phase.remaining_s
                if phase.phase == ResidentState.IDLE_EVICTABLE.value
                else None
            )
            out.append({
                "model_tag": r.model_tag,
                "state": r.state.value,
                # ADDITIVE -- `state` above is unchanged and still the
                # raw r.state. `phase` is what r.state WOULD say if ResidentState.GRACE
                # were ever assigned; it is the field the FE resident card branches on.
                # Additive per the convention this file already states elsewhere: a
                # consumer that does not know these ignores them.
                "phase": phase.phase,
                "remaining_s": phase.remaining_s,
                "phase_resolved_from": phase.resolved_from,
                "port": r.port,
                "pid": pid,
                "spawn_seq": r.spawn_seq,
                "reserved_need_mib": r.reserved_need_mib,
                "parallel": r.parallel,
                "main_gpu": r.main_gpu,
                "split_mode": r.split_mode,
                # Same class of field as main_gpu/
                # split_mode above -- decided once at reservation, locked for
                # this resident's life. None = no override in effect (no
                # reasoning_effort was asked, or nothing to take a fraction
                # of); an operator suspecting first-caller-wins drift reads
                # this here, same shape as the log warning emitted
                # for the same case.
                "reasoning_budget_override": r.reasoning_budget_override,
                "inflight": len(r.inflight),
                # Same accessor manager.py's
                # own _fastlane_claim_eligible-adjacent depth reads
                # already use for this identical value -- not invented
                # fresh here.
                "inbox_depth": r.inbox.qsize() if r.inbox is not None else 0,
                "idle_expires_in_s": idle_in,
                "generation": self.live_generations.get(r.model_tag),
                # This resident's OWN LAST-served identity, additive --
                # regardless of whether it is still running. Keyed identically
                # to `generation` above; see the field's declaration in
                # __init__ for the pruning lifetime (evict-only, never on idle).
                # See RequestIdentityStrip.tsx for the FE's own naming of
                # this "last, not current" distinction.
                "request_identity": self._identity_with_live_label(
                    self._last_request_identity_by_model.get(r.model_tag)
                ),
                # This resident's identity RIGHT NOW -- null
                # when this resident is idle, built from r.active_slot (the
                # SAME fact self._active_slot reads for the cap<=1 singleton:
                # _set_active_slot writes both in one place,
                # so the two can never drift apart).
                "current_request_identity": self._identity_with_live_label(
                    self._current_request_identity(r.active_slot)
                ),
            })
        return out

    # === Port allocation =====================================================

    def _alloc_port(self) -> int:
        """Lowest free sidecar port in ``[default_port_base, +100)``.

        A port is "held" if any LIVE resident in ``self._residents`` reports it
        via ``Resident.port`` (the Phase-1 authoritative listen port). Phase-0
        keeps ``MAX_PARALLEL_SIDECARS == 1`` and the lone resident's ``port``
        stays at its placeholder (``None``) because the FSM still drives the
        listen port through ``_active_handle.port``, not the registry scalar —
        so with one resident the window is empty of holds and this returns
        ``default_port_base`` verbatim (== the deployed hard-coded 11500). The
        scan only does real work once Phase-1 binds resident ports for a second
        concurrent sidecar; introducing it now means the spawn path is already
        port-registry aware with ZERO behaviour change at max=1.
        """
        base = self.boot.runtime.default_port_base
        held = {
            r.port
            for r in self._residents.values()
            if r.port is not None
        }
        for port in range(base, base + 100):
            if port not in held:
                return port
        # Window exhausted (>=100 live residents on contiguous ports). Phase-0
        # can never reach this (single resident); Phase-1's dispatcher gates
        # spawns on MAX_PARALLEL_SIDECARS long before 100 ports are claimed, so
        # this is a defensive fallback, not a live path. Return base so the
        # caller's spawn attempt fails fast on a real bind collision rather than
        # silently picking an out-of-window port.
        return base

    # === Spawn-sequence (live-monitor generation_id) =========================

    def _active_resident(self) -> "Resident | None":
        """The resident that owns the CURRENT active sidecar.

        Phase-0 (``MAX_PARALLEL_SIDECARS == 1``) has exactly one resident under
        ``_SINGLETON_RESIDENT_KEY``, so the active resident is unambiguously that
        singleton. Phase-1 keys residents by ``model_tag`` and resolves the
        active one from the FSM's current model; until then return the singleton
        (or ``None`` if the registry is somehow empty, so callers degrade-open).
        """
        return self._residents.get(_SINGLETON_RESIDENT_KEY)

    def _resolve_top_level_active_slot(self) -> "Slot | None":
        """Which Slot the top-level singleton ``current_request_identity``
        should describe.

        ``self._active_slot`` is NOT a source of truth here at cap>=2: ALL
        FIVE ``_set_active_slot`` call sites live inside ``_process_slot``,
        and ``worker_loop`` branches straight into ``_dispatch_loop`` at
        ``max_parallel_sidecars >= 2`` -- ``_process_slot`` is never
        called again for the manager's lifetime once that branch is taken.
        So ``self._active_slot`` isn't occasionally stale under cap>=2, it is
        PERMANENTLY unwritten (this is observable on a live system, though it is
        easily misdiagnosed as staleness before the mechanism
        is understood).

        At cap<=1, ``_model_residents()`` is empty by construction (it
        EXCLUDES the singleton) -- so this degrades to
        exactly ``self._active_slot``, byte-identical to the pre-rework
        behaviour there (``_process_slot`` IS the only driver at cap<=1 and
        already keeps that scalar correct, including through its own
        ACTIVE_MATCH copy).

        At cap>=2, scans the SAME per-resident ``active_slot`` that
        ``_residents_snapshot`` already reads correctly (maintained directly
        by ``_drive_resident``/``_serve_on_resident``, never through
        ``self._active_slot`` at all), filters to genuinely-live
        (ACTIVE/ACTIVE_MATCH -- the same states the shared
        ``_current_request_identity`` gate checks, applied here too so the
        tie-break only ever considers real candidates), and tie-breaks by
        ``last_active_monotonic``. NOT a new convention: the exact same
        idiom already ships twice --
        ``LiveResidentsSupervisor._update_primary_alias`` (live_monitor.py,
        keys on ``last_active_monotonic``) for ``live_generation``'s own
        back-compat alias, and ``max(live, key=...last_active_monotonic)``
        elsewhere in this file.

        ⚠ KNOWN LIMITATION: with TWO+ residents
        genuinely ACTIVE at the same instant, this can only name ONE — the
        top-level field is a REPRESENTATIVE of "someone is live right now",
        not an exhaustive list. ``residents[]`` (per-resident
        ``current_request_identity``) already carries the full truth for
        every model; this singleton exists for the one operator-facing row
        that predates per-resident identity entirely. A reader who takes a
        populated top-level row to mean "the ONLY thing running" will
        misread a genuinely busy multi-model system.
        """
        residents = self._model_residents()
        if not residents:
            return self._active_slot
        best_slot: "Slot | None" = None
        best_t: float | None = None
        for r in residents:
            slot = r.active_slot
            if slot is None:
                continue
            state = getattr(slot, "state", None)
            if getattr(state, "value", None) not in ("ACTIVE", "ACTIVE_MATCH"):
                continue
            t = getattr(r, "last_active_monotonic", 0.0)
            if best_t is None or t > best_t:
                best_slot, best_t = slot, t
        return best_slot

    def _resolve_top_level_idle_resident(self) -> "Resident | None":
        """Which Resident's idle state the top-level ``idle_info`` should
        describe (template: _resolve_top_level_active_slot).

        At cap>=2: scans per-resident state, tie-breaks by ``idle_expires_at``
        (soonest expiry wins — the one the FE should countdown first).

        At cap<=1: ``_model_residents()`` is empty by construction (it
        EXCLUDES the singleton) -- so this degrades to the
        singleton resident, whose idle state IS the source of truth at cap<=1.

        NOTE: ``r.idle_handle`` is NOT checked here because it is PERMANENTLY
        None at every cap level: the only non-None write site is
        ``_set_idle_holder``, called exclusively from
        ``_process_slot``, which has been retired. The handle's
        liveness is not what the FE countdown displays — the resident state and
        ``idle_expires_at`` deadline are the authoritative idle-hot signal.
        """
        residents = self._model_residents()
        if not residents:
            r = self._residents.get(_SINGLETON_RESIDENT_KEY)
            if (
                r is not None
                and r.state is ResidentState.IDLE_EVICTABLE
                and r.idle_expires_at is not None
            ):
                return r
            return None
        best_r: "Resident | None" = None
        best_t: float | None = None
        for r in residents:
            if r.state is not ResidentState.IDLE_EVICTABLE:
                continue
            if r.idle_expires_at is None:
                continue
            t = r.idle_expires_at
            if best_t is None or t < best_t:
                best_r, best_t = r, t
        return best_r

    def _resolve_top_level_loading_resident(self) -> "Resident | None":
        """Which Resident the top-level ``loading_info`` should describe when the
        loading is happening at the RESIDENT level and no Slot exists yet
        (template: _resolve_top_level_active_slot).

        WHY THIS EXISTS:
        ``status_snapshot`` builds ``active_info``/``loading_info`` inside
        ``if slot is not None:`` and gates the loading branch on the **SLOT**
        state (``STAGED``/``PRE_LOADING``/``LOADING``/``READY``). But while a
        sidecar is spawning, the **RESIDENT** is in ``RESERVED_LOADING`` and its
        ``active_slot`` is still None -- so the whole block is SKIPPED and every
        one of ``active``/``loading``/``grace``/``idle_hot`` stays None while
        ``residents[]`` is populated.

        ``src/frontend/src/components/dashboard/synthesizeResident.ts`` builds its
        panel as ``data.active ?? data.loading ?? grace ?? idle_hot``. All four
        None => it renders NOTHING, while the resident list beneath it is full.
        The two halves of the dashboard disagree and the panel VANISHES.

        While a sidecar spawns, the resident state stays
        RESERVED_LOADING and the slot state stays None on every status snapshot for
        the duration of the spawn, so the panel has nothing to draw during model or
        residency swaps. This is a user-facing gap, not a purely
        theoretical one: the same empty panel results whenever a sidecar
        spawns.

        This is NOT the stranded-scalar kind of defect (a *stranded scalar*, e.g. ``self.grace``
        never written). This is a *vocabulary mismatch*: RESIDENT states and SLOT
        states are different enums, and RESERVED_LOADING has no SLOT counterpart.
        The grace and idle_hot resolvers address stranded scalars and cannot fix this.

        At cap<=1 ``_model_residents()`` is empty by construction (it EXCLUDES the
        singleton), so this degrades to the singleton resident --
        unchanged behaviour whenever no resident is spawning.

        Tie-break: EARLIEST ``reserved_at_monotonic`` -- the resident that has been
        loading longest is the one whose elapsed time the FE should show, mirroring
        ``_resolve_top_level_idle_resident``'s soonest-expiry rule.
        """
        residents = self._model_residents()
        if not residents:
            r = self._residents.get(_SINGLETON_RESIDENT_KEY)
            if r is not None and r.state is ResidentState.RESERVED_LOADING:
                return r
            return None
        best_r: "Resident | None" = None
        best_t: float | None = None
        for r in residents:
            if r.state is not ResidentState.RESERVED_LOADING:
                continue
            t = getattr(r, "reserved_at_monotonic", 0.0)
            if best_t is None or t < best_t:
                best_r, best_t = r, t
        return best_r

    def _resolve_top_level_grace_resident(self) -> "Resident | None":
        """Which Resident's GraceTimer the top-level ``grace_info`` should
        describe (template: _resolve_top_level_active_slot).

        ``self.grace`` is PERMANENTLY unwritten at every cap level: its only
        ``start()`` call site lived inside ``_process_slot``,
        which has been retired (``_process_slot`` is never reached again). So
        ``self.grace.expired()`` is always True and ``grace_info`` stays None
        forever — the FE has nothing to draw. The live per-resident grace timer
        is maintained by ``_serve_on_resident`` (``r.grace.start(...)``,
        fired on every turn completion regardless of cap).

        At cap<=1, ``_model_residents()`` is empty by construction (it
        EXCLUDES the singleton) -- so this degrades to the
        singleton resident, whose grace timer IS the source of truth at cap<=1
        (started in ``_serve_on_resident``, same as cap>=2).

        At cap>=2, scans the per-resident grace timers and tie-breaks by
        ``last_active_monotonic`` (same idiom as ``_resolve_top_level_active_slot``).
        """
        residents = self._model_residents()
        if not residents:
            # cap<=1: singleton resident is the source of truth.
            r = self._residents.get(_SINGLETON_RESIDENT_KEY)
            if r is not None and r.grace is not None and not r.grace.expired():
                # Skip residents actively serving a
                # follow-up (grace paused) -- their countdown is frozen, not
                # live. The top-level grace_info should only describe an idle
                # grace resident whose clock is actually ticking.
                if not r.grace.is_paused():
                    return r
            return None
        best_r: "Resident | None" = None
        best_t: float | None = None
        for r in residents:
            if r.grace is None or r.grace.expired():
                continue
            # Skip actively-serving residents (grace paused).
            if r.grace.is_paused():
                continue
            t = getattr(r, "last_active_monotonic", 0.0)
            if best_t is None or t > best_t:
                best_r, best_t = r, t
        return best_r

    def _resolve_top_level_active_handle(self) -> "SidecarHandle | None":
        """Which SidecarHandle the top-level singleton should describe (template:
        _resolve_top_level_active_slot).

        cap<=1: degrades to exactly ``self._active_handle`` (byte-identical).
        cap>=2: returns the handle of the representative active resident (the one
        whose active_slot wins the same last_active_monotonic tie-break as
        _resolve_top_level_active_slot).
        """
        residents = self._model_residents()
        if not residents:
            return self._active_handle
        best_r = None
        best_t = None
        for r in residents:
            slot = r.active_slot
            if slot is None:
                continue
            state = getattr(slot, "state", None)
            if getattr(state, "value", None) not in ("ACTIVE", "ACTIVE_MATCH"):
                continue
            t = getattr(r, "last_active_monotonic", 0.0)
            if best_t is None or t > best_t:
                best_r, best_t = r, t
        if best_r is None:
            return self._active_handle
        return best_r.handle

    def _bump_spawn_seq(self) -> None:
        """Advance the spawn counter for a new active handle (worker_loop only).

        Single chokepoint: bumps the legacy global ``_spawn_seq`` AND mirrors it
        onto the active resident's ``spawn_seq`` so the registry view never
        diverges from the global. At max=1 the resident value equals the global
        exactly, so the live-monitor generation_id is unchanged. Keeping the
        global write here preserves every existing read site that still reads
        ``_spawn_seq`` directly (zero churn, identical behaviour); the per-read
        migration to ``_active_spawn_seq`` happens incrementally.
        """
        self._spawn_seq += 1
        resident = self._active_resident()
        if resident is not None:
            resident.spawn_seq = self._spawn_seq

    def _active_spawn_seq(self) -> int:
        """The active resident's spawn_seq (live-monitor generation_id input).

        Returns the active resident's mirrored ``spawn_seq``; falls back to the
        legacy global ``_spawn_seq`` if no resident is registered. At max=1 the
        two are identical (``_bump_spawn_seq`` keeps them in lock-step), so the
        unified generation_id computed by the metrics poller and the streaming
        tee is byte-for-byte unchanged from the deployed manager.
        """
        resident = self._active_resident()
        if resident is not None:
            return resident.spawn_seq
        return self._spawn_seq

    def _spawn_seq_for_model(self, model_tag: "str | None") -> int:
        """spawn_seq of the resident actually serving ``model_tag`` (live-monitor
        generation_id input for the streaming text tee).

        At cap>=2 the dispatcher path never bumps the singleton's spawn_seq, so
        ``_active_spawn_seq`` (which resolves the singleton) stays 0 while the
        metrics supervisor hashes the model_tag resident's bumped spawn_seq. The
        text-plane tee must use THIS value so its generation_id matches the
        LiveOutputBuffer key the supervisor publishes as the anchor -- otherwise
        the live pane subscribes to an unfed buffer and shows nothing (an earlier
        bug B). Falls back to ``_active_spawn_seq`` at cap<=1, where no
        model_tag-keyed resident exists -> byte-identical generation_id.
        """
        r = self._live_resident_for(model_tag)
        if r is not None:
            return r.spawn_seq
        return self._active_spawn_seq()

    # === State-migration mirror chokepoints ==================
    # Each writes the legacy manager-global scalar (AUTHORITATIVE — zero churn
    # for existing readers) AND mirrors it onto the active resident, exactly
    # like ``_bump_spawn_seq`` does for spawn_seq. At MAX_PARALLEL_SIDECARS == 1
    # the resident value tracks the global 1:1 (byte-identical); P1d's dispatcher
    # flips the resident copy to authoritative + migrates the read sites.

    def _set_active_handle(self, handle: "SidecarHandle | None") -> None:
        self._active_handle = handle
        r = self._active_resident()
        if r is not None:
            r.handle = handle

    def _set_active_slot(self, slot: "Slot | None") -> None:
        self._active_slot = slot
        r = self._active_resident()
        if r is not None:
            r.active_slot = slot

    def _set_idle_holder(
        self,
        handle: "SidecarHandle | None",
        model_tag: str | None,
        expires_at: float | None,
        thread_id: str | None = None,
        admission_ctx_len: int = 0,
        client_meta: dict | None = None,
    ) -> None:
        self._idle_handle = handle
        self._idle_model_tag = model_tag
        self._idle_expires_at = expires_at
        self._idle_thread_id = thread_id
        self._idle_admission_ctx_len = admission_ctx_len
        self._idle_client_meta = client_meta
        r = self._active_resident()
        if r is not None:
            r.idle_handle = handle
            r.idle_model_tag = model_tag
            r.idle_expires_at = expires_at
            r.idle_thread_id = thread_id
            r.idle_admission_ctx_len = admission_ctx_len
            r.idle_client_meta = client_meta

    def _clear_idle_holder(self) -> None:
        self._set_idle_holder(None, None, None, None, 0)

    def _set_idle_expires_at(self, expires_at: float | None) -> None:
        self._idle_expires_at = expires_at
        r = self._active_resident()
        if r is not None:
            r.idle_expires_at = expires_at

    def _set_latest_keep_alive(self, value: int | None) -> None:
        self._latest_keep_alive_s = value
        r = self._active_resident()
        if r is not None:
            r.latest_keep_alive_s = value

    # === Worker loop (full FSM-driven cycle) =================================

    async def worker_loop(self) -> None:
        """Drive the FSM forever: pop → spawn → active → complete → grace → pop → idle.

        Subprocess interactions are dependency-injected via ctor (spawn_fn,
        health_fn, sigterm_fn, vram_fn, complete_fn). Default implementations call the
        real subprocess_mgr functions. Tests inject mocks.
        """
        log.info("worker_loop started")
        # The fork was a cutover-safety gate whose
        # premise no longer holds once the cap is 2 or more. Design decision: route
        # EVERYTHING through _dispatch_loop — the cap<=1 body is now dead code
        # (marked UNCALLED below). At cap=1 the parallel path spawns ONE sidecar
        # and queues the rest, which is the intended two-or-lower mode: only spawn
        # one sidecar. The dead body is retained
        # for reference, not deleted; it is
        # never executed and must not be depended on.
        if self.runtime.queue.max_parallel_sidecars >= 1:
            return await self._dispatch_loop()
        # UNCALLED: the fork above
        # now routes ALL traffic to _dispatch_loop (>= 1 is provably
        # unconditional — config.py declares ge=1). This while loop and
        # everything below it is dead code: the cap<=1 worker_loop body
        # that used to drive _process_slot. RETAINED, NOT DELETED, for
        # reference (see
        # _legacy_defer_exhaustion_refusal's docstring for the rationale
        # text -- same reasoning, applied here again).
        # WHY unreachable: the if above always returns (cap>=1 is always
        # true, validated by the config.py constraint).
        while not self._stop_event.is_set():
            # Model-affinity hint for pop_next: the model currently warm in the
            # idle holder (preferred) or the active slot. This is a READ of the
            # manager scalars; a fire-and-forget _teardown_idle_holder task may
            # null _idle_handle/_idle_model_tag concurrently, but the read pair
            # below is AWAIT-FREE (atomic in the single-threaded event loop) and
            # `warm` is only a HINT -- a stale value just falls back to FIFO. No
            # new lock and no new mutator are introduced. warm=None => strict
            # FIFO (back-compat). _idle_model_tag is the confirmed attribute
            # (manager.__init__) for the idle holder's model tag.
            if self._idle_handle is not None:
                warm = self._idle_model_tag
            elif self._active_slot is not None:
                warm = self._active_slot.model_tag
            else:
                warm = None
            slot = await self.queue.pop_next(
                warm_model_tag=warm, fastlane_policy=self._fastlane_pop_kwarg(),
            )
            if slot is None:
                # Inline idle-expiry handling + fire-and-forget teardown
                # + MOD-α identity-guarded debounce.
                # MOD-α: capture `expires` into a local; only reset _idle_expires_at
                # if it is STILL the same object we observed. Prevents the race where a
                # concurrent reset (request promotion repopulates _idle_expires_at to a
                # fresh T+120 window) would otherwise be wiped by our stale-T0 debounce
                # → teardown fires on a legitimate fresh window → warm holder killed
                # mid-promotion.
                # Proactive DEAD-idle sweep.
                # The observed death was BETWEEN requests (llama-server died ~2min
                # after a wave-return while idle-hot); the reactive warm_inherit
                # is_alive() gate only fires on the NEXT request. Sweep holder
                # liveness every idle tick so a dead holder is torn down (dead-pid
                # teardown path: skip flush, reap) and the next request cold-spawns
                # clean instead of stranding on active_handle_pid=X alive=False.
                if (
                    self._idle_handle is not None
                    and not self._idle_handle.is_alive()
                ):
                    log.warning(
                        "Idle-hot holder DEAD between requests (model=%s pid=%s) — "
                        "proactive teardown (idle_dead)",
                        self._idle_model_tag,
                        getattr(self._idle_handle, "pid", None),
                    )
                    # NAME what the sweep just caught.
                    # Attribution only -- reads the SAME engine_log_path the
                    # LOAD_VERIFY spawn-side check already reads,
                    # best-effort, never raises, changes NOTHING about the
                    # teardown/recovery below (including the bin-strike
                    # accounting immediately after this block). A brand-new
                    # log line rather than editing the warning above, so any
                    # existing grep/tooling on that exact line survives
                    # untouched. See classify_idle_dead_holder's own
                    # docstring for why this is 4-way, not 2-way -- collapsing
                    # "could not check" or "checked, no known signature" into
                    # either named case would repeat, one level down, the
                    # exact silent-negative trap this change exists to close.
                    _death_class = load_verify_log.classify_idle_dead_holder(
                        getattr(self._idle_handle, "engine_log_path", None),
                    )
                    log.warning(
                        "IDLE_DEAD_CLASSIFY class=%s port=%s model=%s pid=%s "
                        "reason=%s matched=%r",
                        _death_class.get("death_class"),
                        getattr(self._idle_handle, "port", None),
                        self._idle_model_tag,
                        getattr(self._idle_handle, "pid", None),
                        _death_class.get("reason"),
                        _death_class.get("matched_line"),
                    )
                    # Attribute the death to the bin this
                    # port last restored; 3 strikes -> auto-quarantine the triplet
                    # (both tiers) so the next load goes FRESH instead of looping.
                    # Pure extract, zero behaviour change:
                    # this used to be inline here, reading self._idle_handle
                    # directly. Now a shared helper parametrized on port, so the
                    # cap>=2 idle-liveness sweep calls the SAME tested
                    # implementation instead of a drifting copy.
                    self._record_bin_death_strike(
                        getattr(self._idle_handle, "port", None)
                    )
                    # capture BEFORE nulling -- same reason the two
                    # idle_expired sites below do -- so the IDLE_TEARDOWN
                    # line's deadline_delta_s isn't unconditionally None here
                    # either.
                    _dead_expires = self._idle_expires_at
                    self._set_idle_expires_at(None)
                    _dtask = asyncio.create_task(
                        self._teardown_idle_holder("idle_dead", expires_at=_dead_expires)
                    )
                    _dtask.add_done_callback(
                        lambda t: t.exception() and log.error(
                            "dead-idle teardown failed: %s", t.exception()
                        )
                    )
                expires = self._idle_expires_at
                if (
                    self._idle_handle is not None
                    and expires is not None
                    and time.monotonic() >= expires
                ):
                    if self._idle_expires_at is expires:  # MOD-α identity check
                        self._set_idle_expires_at(None)
                        # FP Bonus-2: fire-and-forget — don't block worker_loop on
                        # the 5s SIGTERM grace + wait4 of the llama-server child.
                        # Add a done callback to log failures instead of silently swallowing.
                        _task = asyncio.create_task(
                            self._teardown_idle_holder("idle_expired", expires_at=expires)
                        )
                        _task.add_done_callback(
                            lambda t: t.exception() and log.error(
                                "idle teardown failed: %s", t.exception()
                            )
                        )
                await asyncio.sleep(0.05)
                continue

            # Client-disconnect eviction handling.
            if slot.is_evicted:
                self._fail_completion_future(
                    slot,
                    SlotEvictedError(
                        f"slot {slot.slot_id} evicted: client disconnect"
                    ),
                )
                # Audit-emit via the pool path; NO sync
                # state_db_session(mark_slot_ended) on the hot path —
                # SQLite fsync 1-3s stalls would bypass the pool entirely.
                # State-row finalization defers to terminal-park / a
                # background sweeper RC stub.
                try:
                    await self._audit_event_only_async(
                        slot.slot_id,
                        "slot_evicted",
                        {
                            "reason": "client_disconnect",
                            "time_in_queue_s": time.monotonic() - slot.created_at,
                        },
                    )
                except Exception:
                    log.exception(
                        "slot_evicted audit emit failed (best-effort)"
                    )
                # /status metric bookkeeping
                self._unload_count += 1
                self._last_unloaded_at_iso = datetime.now(
                    timezone.utc,
                ).isoformat()
                # SA Simp #3 (inline mirror) + MOD-α identity guard — same
                # idle-tick block on the eviction branch so consecutive
                # evictions don't starve idle expiry.
                expires = self._idle_expires_at
                if (
                    self._idle_handle is not None
                    and expires is not None
                    and time.monotonic() >= expires
                ):
                    if self._idle_expires_at is expires:
                        self._set_idle_expires_at(None)
                        # Add a done callback to log failures instead of silently swallowing.
                        _task2 = asyncio.create_task(
                            self._teardown_idle_holder("idle_expired", expires_at=expires)
                        )
                        _task2.add_done_callback(
                            lambda t: t.exception() and log.error(
                                "idle teardown failed: %s", t.exception()
                            )
                        )
                continue

            try:
                await self._process_slot(slot)
            except asyncio.CancelledError:
                raise
            except Exception as e:
                log.exception("slot %s processing failed", slot.slot_id)
                self._fail_completion_future(slot, e)
                # Teardown active sidecar BEFORE force_cold
                # to prevent PID leak. _force_cold only updates DB state; without
                # teardown the spawned llama-server keeps running and the
                # single-slot invariant breaks until boot_orphan_reaper at next
                # restart. Best-effort — don't let teardown failure mask the
                # original exception that triggered this path.
                if self._active_handle is not None:
                    try:
                        await self._teardown(slot, "worker-uncaught-exception")
                    except Exception:
                        log.exception(
                            "teardown during worker exception failed (best-effort)"
                        )
                await self._force_cold(slot, "worker-uncaught-exception")
        log.info("worker_loop exited")

    # === Multi-slot dispatcher (cap>=2 path) ================
    # worker_loop branches into _dispatch_loop when max_parallel_sidecars>=2. The
    # cap<=1 path above is UNTOUCHED (byte-identical, the 493-forked gate). The
    # dispatcher is the SOLE writer of the _residents dict + each resident's
    # ``state``, ALWAYS under _registry_lock. Each resident is driven by its own
    # long-lived _drive_resident task (sole writer of that r.* lock-free in ACTIVE).
    # The request-route (submit/chat_completion) NEVER takes _registry_lock.

    def _model_residents(self) -> "list[Resident]":
        """Live model_tag-keyed residents (EXCLUDES the legacy singleton + DEAD).
        Await-free ``list()`` snapshot so a concurrent mutation can't error."""
        return [
            r
            for k, r in list(self._residents.items())
            if k != _SINGLETON_RESIDENT_KEY and r.state is not ResidentState.DEAD
        ]

    def _other_active_residents(self, handle: "SidecarHandle | None") -> int:
        """Count residents that
        are ACTIVE right now, OTHER than the resident serving ``handle`` —
        i.e. the OBSERVED concurrency at this instant.

        The single-series KV-save gate keys off observed concurrency, not the
        static max_parallel_sidecars cap: with cap >= 2 and every other
        resident idle, the box is effectively single-series, so the clean-save
        proceeds (KV restore stays GREEN regardless of the parallel-sidecar
        setting). Note for authors: the FSM has RESERVED_LOADING
        -> ACTIVE and IDLE_EVICTABLE -> ACTIVE transitions, so the count is a
        POINT-IN-TIME snapshot — an unrelated admission CAN fire during the
        probe->save->real-req window (via _route_or_reserve; both states are
        in _model_residents()). The save is nonetheless safe to proceed when
        this returns 0, for these load-bearing invariants — NOT because only
        ACTIVE interleaves:

        (a) our resident is ACTIVE and holds its active_slot for the whole
            probe+save, and _lru_idle_unloadable NEVER evicts a busy resident
            — so our engine cannot be the eviction victim mid-probe;
        (b) a new co-resident gets NON-OVERLAPPING VRAM (_vram_admits_locked:
            co-residence only for split_mode:none on a per-card budget — it
            never displaces a sibling's KV);
        (c) separate per-port engine procs + the _vram_ours pid-guard
            safe-degrade on respawn / reused-port;
        (d) handle.parallel > 1 stays a hard decline regardless.

        Scope boundary: this recovers the IDLE-SIBLING case
        (in typical use). It does NOT eliminate cold-prefills when the
        box is genuinely two-models-busy (both ACTIVE) — that still declines,
        by design (single-series invariant). Do not oversell as "no more cold
        prefills under concurrency".

        Lock-free read guard: this reads dispatcher-owned
        Resident.state without _registry_lock (state is written only under
        _registry_lock; _model_residents is an await-free snapshot). A stale
        read can only MIScount, never corrupt — correctness leans on the
        co-residence VRAM-isolation invariant above, not on the count being
        exact. If per-card layer-split VRAM accounting lands (flagged in
        _vram_admits_locked), RE-AUDIT this gate.

        Handle-identity match (``r.handle is handle``), not model_tag: a
        model_tag can carry more than one resident (multi-instance routing)
        and the gate must exclude only the exact sidecar being saved. The
        legacy singleton key is excluded by _model_residents(), so cap==1
        worlds see 0 here and keep today's behavior exactly.
        """
        return sum(
            1
            for r in self._model_residents()
            if r.state is ResidentState.ACTIVE and r.handle is not handle
        )
    @contextlib.contextmanager
    def _reserving(self, model_tag: str):
        """Name the in-flight reservation for the duration of the reserve
        window, so ``status_snapshot`` can report the INCOMING model while it still
        has no ``Resident`` object.

        ⛔ THE CLEARING IS THE CONTRACT, NOT A TIDY-UP. A marker that outlives its
        window stops being "what is loading now" and becomes "what was admitted most
        recently" -- a historical record dressed as a live claim, right most of the
        time and silently wrong the rest. That is precisely the shape of a
        ``_last_request_identity``-style marker, which this reader avoids, so a leak here would
        reintroduce it under a different name. ``finally`` clears on EVERY exit:
        normal return (by which point the Resident exists and its own status reporting owns the
        surface), the VRAM-gate defer, and any exception.

        ⛔ IT WRAPS ``_route_or_reserve``, NOT ``_reserve_and_start_locked``, AND THAT
        IS A REQUIREMENT NOT A PREFERENCE. Wrapping the inner reserve covered only the
        second half of the window: once the VRAM probes ahead of it run off-loop, the
        observable window OPENS at the first of those probes, well before the reserve
        call is reached. The outer wrap covers the whole decision; the inner wrap
        left some observations dark. ``_route_or_reserve`` is the whole atomic
        critical section and has exactly one caller, so one ``with`` covers it.

        Marking a slot that turns out to ROUTE to an existing resident rather than
        reserve is harmless: the reader gates on ``not self._instances_for(tag)``, so a
        tag that already has a Resident is never reported by this path. The marker
        names intent; the gate decides whether it is worth reporting.

        A single scalar is sufficient because the ONE call site is the dispatcher's
        sequential slot loop -- it awaits ``_route_or_reserve`` for one slot before
        taking the next, so two reservations are never in flight together. ⚠ NOTE the
        reason is the SEQUENTIAL CALLER, not ``_registry_lock``: this marker is set
        BEFORE that lock is acquired inside ``_route_or_reserve``, so lock-held
        reasoning does not apply to it. If a second concurrent dispatch path is ever
        added, this must become per-tag, not a scalar.
        """
        self._reserving_model_tag = model_tag
        try:
            yield
        finally:
            self._reserving_model_tag = None

    def _instances_for(self, model_tag: "str | None") -> "list[Resident]":
        """Registry re-key: the live (non-DEAD, non-singleton)
        engine instances currently serving ``model_tag``. Backs the multi-instance
        cap/placement/affinity helpers + the multi-instance routing. Default-inert:
        a tag that is not placed one card per engine stays on the legacy single-engine
        path. _model_residents() already excludes the singleton +
        DEAD, so this is a pure tag filter over it."""
        return [r for r in self._model_residents() if r.model_tag == model_tag]

    # ============================================================================
    # Session->engine affinity + engine cap and placement.
    # All CALLER-HOLDS-_registry_lock; internally lock-free (dispatcher is sole
    # writer of _residents + _session_affinity). Seam deps on the registry re-key:
    # Resident.resident_key, _residents re-keyed by it, _instances_for(tag).
    # ============================================================================
    def _session_key_for(self, slot):
        """Stable per-session routing key from a Slot. Mirrors the identity precedence
        of _durable_ring_key / _bin_identity: session_id first, thread_id fallback.
        Returns None when NEITHER is present -> the caller applies NO stickiness (pure
        load-balance, never crash). Pure function; no lock required."""
        cm = getattr(slot, "client_meta", None)
        # client_meta is typed dict but be defensive — a non-dict (bad
        # upstream) must degrade to thread_id/None, never AttributeError in the dispatcher.
        sid = cm.get("session_id") if isinstance(cm, dict) else None
        if sid:
            return f"sess:{sid}"
        tid = getattr(slot, "thread_id", None)
        return f"tid:{tid}" if tid else None

    def _remember_affinity(self, model_tag, skey, resident_key):
        """Record/refresh (model_tag, skey) -> resident_key and enforce the LRU bound.
        Also called by the routing path after it SPAWNS a new instance for a session (it passes
        the freshly reserved resident_key). No-op when skey is None (unstickable
        request). CALLER HOLDS _registry_lock."""
        if skey is None:
            return
        key = (model_tag, skey)
        self._session_affinity[key] = resident_key
        self._session_affinity.move_to_end(key)
        while len(self._session_affinity) > _AFFINITY_MAX:
            self._session_affinity.popitem(last=False)

    def _sticky_resident_key(self, slot, model_tag):
        """READ helper for the routing path's sticky-lookup: the resident_key this slot's session
        is pinned to, or None. Refreshes LRU recency on a hit (so hot sessions are not
        evicted from the map) — that mutation is why the CALLER MUST HOLD _registry_lock.
        Does NOT validate that the resident is alive/present: the routing path re-checks
        self._residents.get(rk) + state and calls _drop_affinity on a stale/dead hit."""
        skey = self._session_key_for(slot)
        if skey is None:
            return None
        key = (model_tag, skey)
        rk = self._session_affinity.get(key)
        if rk is not None:
            self._session_affinity.move_to_end(key)
        return rk

    def _drop_affinity(self, slot, model_tag):
        """Drop this slot's session mapping (the routing path calls it when a sticky target resolves to
        a dead/missing resident -> the session re-homes on its next tick). CALLER HOLDS
        _registry_lock."""
        skey = self._session_key_for(slot)
        if skey is not None:
            self._session_affinity.pop((model_tag, skey), None)

    def _pick_instance_for(self, slot, model_tag, instances):
        """Choose the least-loaded live instance from ``instances`` (the tag's
        _instances_for list) for a session, RECORD the affinity under ``model_tag``, and
        return it. Load key = readiness (ready before booting) then pending load
        (inflight+active+inbox depth) then oldest last_active, so new sessions fill the
        least-busy READY engine. Returns None if ``instances`` has no live member (caller
        cold-starts a first instance).

        ``model_tag`` is passed EXPLICITLY (not re-derived from slot.model_tag) so the
        record-key tag matches the SAME tag the routing path uses for _sticky_resident_key /
        _drop_affinity lookups — sourcing it from the slot would silently
        lose stickiness if a caller ever resolved ``instances`` under an alias/normalized
        routing tag != slot.model_tag.

        This is the 'pick among the instances I am handed' primitive ONLY — it does NOT
        decide spawn-new-vs-use-existing (that is the routing path's job). CALLER HOLDS
        _registry_lock."""
        live = [r for r in instances if r.state is not ResidentState.DEAD]
        if not live:
            return None
        chosen = min(
            live,
            key=lambda r: (
                # Rank a still-booting RESERVED_LOADING instance AFTER
                # any ready one (ACTIVE/GRACE/IDLE_EVICTABLE) — a new session should not
                # wait out a cold boot when a warm engine can serve now.
                r.state is ResidentState.RESERVED_LOADING,
                # Total pending = riders in-flight (+1 while actively
                # serving) + slots already queued in this engine's inbox, so back-to-back
                # new sessions before the driver drains the inbox still spread evenly.
                len(r.inflight) + (1 if r.active_slot is not None else 0)
                + (r.inbox.qsize() if getattr(r, "inbox", None) is not None else 0),
                r.last_active_monotonic,
            ),
        )
        self._remember_affinity(model_tag, self._session_key_for(slot), chosen.resident_key)
        return chosen

    def _purge_affinity_for(self, r):
        """Drop every affinity entry pointing at r.resident_key. The routing path calls this from
        _begin_unload_locked right after the resident is deregistered, so a later
        same-session request re-homes instead of routing to a dead engine. Underflow-safe
        (no resident_key -> no-op). CALLER HOLDS _registry_lock."""
        dead_key = getattr(r, "resident_key", None)
        if not dead_key:   # None OR the "" dataclass default -> no-op
            return          # (never purge on an empty key: it would drop unrelated entries)
        stale = [k for k, rk in self._session_affinity.items() if rk == dead_key]
        for k in stale:
            self._session_affinity.pop(k, None)

    def _card_avail_mib(self):
        """Per-card available VRAM in MiB = live free (nvidia-smi) minus this card's
        RESERVED_LOADING siblings minus the safety floor. EXACT mirror of _auto_pick_gpu's
        per-card ``avail`` computation — deliberately a SEPARATE helper so _auto_pick_gpu
        stays byte-identical for the default-inert path (no refactor of an existing
        method). Empty list when the probe is unavailable. CALLER HOLDS _registry_lock."""
        vals = _read_free_vram_all_mib()
        if not vals:
            return []
        floor = self.runtime.queue.safety_min_free_vram_mib
        reserved_by_gpu = {}
        for r in self._model_residents():
            if r.state is ResidentState.RESERVED_LOADING:
                reserved_by_gpu[r.main_gpu] = reserved_by_gpu.get(r.main_gpu, 0) + r.reserved_need_mib
        return [vals[g] - reserved_by_gpu.get(g, 0) - floor for g in range(len(vals))]

    def _cards_that_fit(self, need_mib, exclude=frozenset()):
        """Count of visible cards (minus ``exclude``) that can each host a ``need_mib``
        footprint right now. _effective_cap uses it to bound a tag to the number of
        distinct cards it can occupy (even 1-per-card split). CALLER HOLDS
        _registry_lock."""
        avail = self._card_avail_mib()
        return sum(1 for g in range(len(avail)) if g not in exclude and avail[g] >= need_mib)

    def _auto_pick_gpu_excluding(self, need_mib, exclude):
        """Most-free FITTING card whose id is NOT in ``exclude`` as (gpu, 'none'); or
        (None, 'none') if no complement card fits. Thin variant of _auto_pick_gpu
        restricted to un-used cards — steers a tag's Nth engine onto a card that does not
        already host one (even split). Intentionally NO layer-split aggregate fallback: a
        distinct-card pick that spans every card is meaningless, so 'no distinct card
        fits' -> None (the caller keeps the plain _auto_pick_gpu result). CALLER HOLDS
        _registry_lock."""
        avail = self._card_avail_mib()
        if not avail:
            return None, "none"
        candidates = [g for g in range(len(avail)) if g not in exclude and avail[g] >= need_mib]
        if candidates:
            return max(candidates, key=lambda g: avail[g]), "none"
        return None, "none"

    def _pick_card_for_new_instance(self, model_tag, need_mib):
        """(gpu, split_mode) for a tag's NEXT engine, preferring a card that does NOT
        already host one of this tag's instances (even 1-per-card split). CALLER HOLDS
        _registry_lock.

        What it guarantees, in order:
          1. It prefers a card that does not already host one of this tag's instances.
          2. When the plain _auto_pick_gpu pick is a card this tag already uses and a
             card the tag does not use fits, it takes that unused card. When no unused
             card fits it keeps the plain pick (the used card).
          3. When no single card fits (the plain pick is a layer split across every
             card) it returns (None, 'none'), so the placement it hands back is never
             a card-spanning engine.
          4. (None, 'none') => nothing fits for this branch (or the free-VRAM probe was
             unreadable) => the caller must NOT spawn from here (route to an existing
             instance instead).
        """
        used = {r.main_gpu for r in self._instances_for(model_tag)}
        g, split = self._auto_pick_gpu(need_mib)
        # The second-engine path is gated by _wants_one_card_per_engine (auto_place true and
        # an explicit split_mode none), so a tag not placed one card per engine never reaches a
        # card count above one. If _auto_pick_gpu could only place the engine as an aggregate
        # layer-split (no single card fits), that is NOT a valid even-split target -> signal
        # no-fit (None): the caller routes to an existing instance, never a card-spanning engine.
        # Side by side with the legacy cold start (the "4." step in _route_or_reserve):
        #   this function:     never spans cards; a layer pick gets no-fit here.
        #   legacy cold start: first looks for one card that fits once its idle
        #                      models are unloaded (the reclaim-first decision), and
        #                      keeps a layer span only when no single card fits even
        #                      with that.
        if split != "none":
            return None, "none"
        if g is not None and g in used:
            g2, split2 = self._auto_pick_gpu_excluding(need_mib, used)
            if g2 is not None:
                g, split = g2, split2
        return g, split

    def _effective_cap(self, model_tag):
        """Max engine instances tag ``model_tag`` may run RIGHT NOW =
            min( #distinct cards that can host one  (this tag's current cards + other
                    cards that currently fit the footprint),
                 this tag's current instances + free GLOBAL engine slots ).
        The only limits are the box-wide ``queue.max_parallel_sidecars`` budget and
        the cards the model fits on. The windows each engine serves
        (``llama_server_flags.parallel``) are passed to the budget function and
        appear in its reason text; they never change the engine count.

        HOT PATH: this runs on every route, including a request for a tag that
        already has a live engine. When the box budget is already spent it answers
        from the live engine count alone, before any card probe. The probe is only
        reached while a slot is free, and only for a tag whose manifest asks for one
        card per engine (``_wants_one_card_per_engine``): any other tag can never be
        placed as a second engine, so its card probe answers nothing and is skipped.
        It returns the engines the tag already runs, at least 1 (a cold tag may start
        one engine, never a second). A manifest that cannot be read returns 1.
        Probe unavailable at cold start -> 1 (single instance), matching
        _auto_pick_gpu's 'probe unreadable -> degrade to pin' doctrine.
        CALLER HOLDS _registry_lock.

        The global slots term is ``len(_instances_for(tag)) + (max_parallel_sidecars -
        len(_model_residents()))``, NOT ``max_parallel_sidecars -
        len(_model_residents())``. The latter counts the tag's OWN live engines
        against the tag's OWN cap: with ``max_parallel_sidecars=2`` it collapses the cap
        to 1 the instant the first engine loads, so the 2nd engine never spawns and
        the 2nd card stays idle. Adding the tag's own count back says: 'this tag may
        occupy every global slot not held by OTHER tags'."""
        try:
            # Cached read -- this runs on EVERY route,
            # including the default single-instance HIT path, so an uncached
            # stat+read_text+yaml.safe_load+full pydantic validate on every
            # request is a real tail-latency regression at cutover, even
            # though it's functionally inert (see the except below).
            m = read_manifest_cached(self.boot.storage.manifests_path, model_tag)
            # Windows per engine: llama_server_flags.parallel, default 1. Anything
            # that is not an int >= 1 counts as 1. Read with the manifest so one
            # cached read serves both.
            _flags = getattr(m, "llama_server_flags", None)
            _parallel = _flags.get("parallel", 1) if isinstance(_flags, dict) else 1
            parallel_width = (
                _parallel
                if isinstance(_parallel, int) and not isinstance(_parallel, bool)
                and _parallel >= 1
                else 1
            )
        except Exception:
            # Fail-safe: _effective_cap runs on EVERY route (incl.
            # default single-instance HITs). A manifest read that raises (corrupt/invalid,
            # not merely missing) must NOT propagate out of _route_or_reserve and break
            # routing for ALL tags. Degrade to a single instance (pre-feature behavior);
            # a genuinely-broken manifest still surfaces at spawn (_read_model_footprint).
            return 1  # fail-safe, deliberately unchanged
        # The engine count is decided by the engine_budget module from the box-wide
        # budget and the card probe, the only two ceilings. The windows per engine
        # (``parallel_width``) are passed to the budget function (they show up in its
        # reason text) and never change the engine count. A manifest read that raises returned 1
        # above, which is the fail-safe.
        # FAST PATH: when the box budget cannot admit another engine, the answer is
        # known from the live engine count alone, so it is returned before the card
        # probe (nvidia-smi) and the footprint read. Only when a further engine is
        # within reach do we measure cards.
        current = self._instances_for(model_tag)
        # A tag may occupy every global slot ANOTHER tag is not holding, so its own
        # live engines must not count as consumed budget in the free-slot count
        # below, or a tag running 2 of 2 would shrink itself.
        # Budget spent: the answer is only ever this tag's own engines (0 when
        # cold), so the card probe cannot change it. This is the shape a box at its
        # sidecar limit hits on every request for a live tag, and it keeps that path
        # off nvidia-smi.
        budget_full = len(self._model_residents()) >= self.runtime.queue.max_parallel_sidecars
        if budget_full:
            return len(current) if current else 0
        free_global = (
            self.runtime.queue.max_parallel_sidecars
            - (len(self._model_residents()) - len(current))
        )
        if free_global <= 0:
            # No slot that another tag is not holding. The answer is knowable without
            # the probe, but the two cases differ and the difference is load-bearing:
            #   * the tag is RUNNING -- hold exactly what it has. Shrinking it would
            #     make the caller's len(instances) < cap gate false-shrink a live
            #     engine (test_effective_cap_probe_down_keeps_existing).
            #   * the tag is COLD -- return 0, NOT 1. A coarse floor of 1 would make
            #     0 < 1 true and admit an engine past max_parallel_sidecars, which is
            #     the max-2 breach test_effective_cap_budget_full_cold_is_zero guards.
            return len(current)
        # A tag that does not ask for one card per engine can only ever run the one
        # engine (a second copy has no card of its own to sit on), so the cards cannot
        # change the answer: keep the engines it already runs, at least 1 so a cold tag
        # may start its one engine. No footprint read, no card probe.
        if not _wants_one_card_per_engine(m):
            return max(1, len(current))
        need = self._read_model_footprint(model_tag)[0]
        used_cards = {r.main_gpu for r in current}
        n_cards = len(used_cards) + self._cards_that_fit(need, exclude=used_cards)
        _budget = effective_engine_cap(EngineBudgetInputs(
            max_parallel_sidecars=self.runtime.queue.max_parallel_sidecars,
            live_residents=len(self._model_residents()),
            own_instances=len(current),
            cards_that_fit=n_cards,
            parallel_width=parallel_width,
            manifest_unreadable=False,
        ))
        if _budget.engines <= 0:
            # Global engine budget is fully consumed by OTHER tags and this tag
            # has nothing live. Must stay 0: a coarse max(1, ...) would admit an
            # engine past max_parallel_sidecars.
            log.info("ENGINE_BUDGET tag=%s engines=0 reason=%s", model_tag, _budget.reason)
            return 0
        # ``_budget.engines`` is already the tag's TOTAL capacity. Adding
        # ``len(current)`` on top of it would double-count the tag's
        # own live engines, which is how a tag holding 1 engine while another tag
        # held the second slot would report 2 instead of 1.
        global_cap = _budget.engines
        # Floor ONLY the physical/manifest term, NOT the global
        # budget. n_cards==0 (probe down / no card fits) legitimately degrades to a single
        # pin (the VRAM gate still guards the actual spawn) — that is what the floor is for.
        # But global_cap==0 (this tag has 0 instances AND the global engine budget is fully
        # consumed by OTHER tags) MUST stay 0: a coarse max(1, min(...,global_cap)) would
        # lift it to 1, and under the routing path's `len(instances) < effective_cap` spawn gate that
        # admits a 3rd engine past max_parallel_sidecars — breaching the hard
        # "max 2 engines" cap on a card that happens to have spare VRAM.
        # The remaining ceiling is the physical one: the cards that can host this
        # model. The windows per engine are deliberately NOT in this min: they are
        # not an engine count. ``_budget.engines`` has already applied the global
        # budget and the card probe.
        return min(max(1, n_cards), global_cap)

    def _route_cap_and_placement(self, model_tag):
        """Both manifest-derived answers the routing decision needs, as
        ``(eff_cap, wants_one_card_per_engine)``, so one worker-thread call serves both.

        ``eff_cap`` is ``_effective_cap(model_tag)``, called as it is. The second value is
        the placement answer (``_wants_one_card_per_engine``) from the same cached
        manifest read. It must be computed here, off the event loop, and not by a second
        read in the routing decision: the cached accessor stats the file on every call.
        An unreadable manifest must not change routing, so the placement answer then
        falls back to ``eff_cap > 1``, the cap alone.
        Runs in a worker thread; it touches no state that needs the event loop."""
        eff_cap = self._effective_cap(model_tag)
        try:
            wants_parallel = _wants_one_card_per_engine(
                read_manifest_cached(self.boot.storage.manifests_path, model_tag)
            )
        except Exception:
            wants_parallel = eff_cap > 1
        return eff_cap, wants_parallel

    def _dispatch_warm_hint(self) -> "str | None":
        """pop_next affinity hint at cap>=2: the most-recently-active live
        resident's model_tag. HINT only — stale value falls back to FIFO, never
        starves a routable follower."""
        live = self._model_residents()
        if not live:
            return None
        return max(live, key=lambda r: r.last_active_monotonic).model_tag

    def _dispatch_room_hint(self) -> bool:
        """pop_next room hint at cap>=2 (the room check comes
        first: if there is a free sidecar slot, nothing is evicted):
        True iff the registry has a free slot RIGHT NOW, same
        ``len(self._model_residents()) >= cap`` fact ``_route_or_reserve``
        already computes as ``at_count_cap`` under ``_registry_lock`` --
        this is the un-locked, resolve-on-read HINT twin, same discipline and
        same staleness tolerance as ``_dispatch_warm_hint`` (a stale True
        races a concurrent reservation; the real, authoritative room check
        stays ``_route_or_reserve``'s own, this is advisory to the picker
        only). Deliberately COUNT-only, not VRAM-aware: a per-candidate VRAM
        fit needs that candidate's resolved placement (main_gpu/split_mode/
        need), which pop_next does not have until AFTER it has picked one --
        so it cannot be resolved before this call, and queue.py is barred
        from reaching for it itself. KNOWN LIMITATION: ``room_available=True``
        by this measure can still hit ``_route_or_reserve``'s cross-resident
        VRAM-over-commit evict-then-QUEUE path (registry slot free, but VRAM
        doesn't fit even so), because the check above is count-only and does
        not look at VRAM.
        """
        cap = self.runtime.queue.max_parallel_sidecars
        return len(self._model_residents()) < cap

    async def _grace_active_exclusions(self) -> "frozenset[tuple[str, str]]":
        """The set of (thread_id, model_tag) pairs
        pop_next must make invisible to its whole pick ladder for one call --
        each is a resident's own grace-loop poll (``_serve_on_resident``'s
        ``pop_matched_thread``) that must claim its warm follow-up, not a
        dispatcher pop. Resolved fresh from live residents on every call,
        under ``_registry_lock`` -- same resolve-on-read style as
        ``_fastlane_pop_kwarg`` and Phase-1's
        ``_resident_unload_priority_key``: caching this would reintroduce
        the stale-copy class of bug this design avoids.

        Rule: the designated victim (the lowest-priority loaded
        client) gets NO grace timer: not 30 seconds, not a warm-hold,
        nothing. Every other loaded client keeps its normal grace
        window (its cooldown), and a same-thread follow-up inside its grace is
        still served warm. So every OTHER resident's grace window is
        protected here; a designated victim's never is, even if ``r.grace``
        itself still reports one running (skipping the victim's own grace
        timer outright belongs to a separate mechanism, not to this function -- the
        check below is belt-and-suspenders in case the two are applied out of
        sequence).

        ``_is_designated_unload_target_locked(r)`` is probed with ``getattr``
        (the probe is an inert, named seam when the predicate is absent): every
        resident resolves as "protect it" while the class does not define the
        predicate; once it is defined, this function starts
        excluding the real victim, with no further change needed in
        this function.
        """
        pairs: set[tuple[str, str]] = set()
        async with self._registry_lock:
            is_unload_target = getattr(self, "_is_designated_unload_target_locked", None)
            for r in self._model_residents():
                if r.grace is None or r.grace.expired():
                    continue
                if is_unload_target is not None:
                    try:
                        if is_unload_target(r):
                            continue
                    except Exception:
                        # GRACE_VICTIM_CHECK_FAILED: degrade toward NOT
                        # protecting this one grace window rather than the
                        # reverse -- wrongly protecting a real designated
                        # victim would violate the grace rule; wrongly
                        # un-protecting an ordinary resident just reverts
                        # that one pop to the ordinary grace race, never a rule
                        # violation.
                        log.exception(
                            "GRACE_VICTIM_CHECK_FAILED resident_model=%s",
                            r.model_tag,
                        )
                        continue
                pairs.add((r.grace.thread_id, r.grace.model_tag))
        return frozenset(pairs)

    async def _dispatch_loop(self) -> None:
        """The cap>=2 dispatcher: pop -> route-or-reserve -> loop. Never blocks on
        an ACTIVE wait (the per-resident drivers own that).

        Diagnostic (essential, not optional): a census check runs on EVERY
        iteration, BEFORE
        ``pop_next`` -- not hung off the make-room path, which
        structurally never fires on an empty box (a MAKE_ROOM_STARVED event
        never reports residents=0), so
        anything gated on it can never see this condition. ``residents=`` and
        ``staging_depth=`` could otherwise not be joined for the empty-box case;
        this line exists to close that join, not to
        add a periodic heartbeat. It logs ONLY when the interesting case is
        true (residents==0 and staging_depth>0), at the loop's own backoff
        cadence for as long as it holds; silent otherwise, so it adds no
        volume to the (overwhelming) common case.
        Both reads are cheap sync snapshots (``_model_residents()`` is
        await-free; ``queue.depth()`` is the same lock-skip-OK snapshot
        already used for /status) -- no lock acquired, no nvidia-smi, no
        behaviour change.
        """
        log.info(
            "dispatcher started (max_parallel_sidecars=%d)",
            self.runtime.queue.max_parallel_sidecars,
        )
        while not self._stop_event.is_set():
            residents = len(self._model_residents())
            staging_depth = self.queue.depth()["staging_queue_depth"]
            if residents == 0 and staging_depth > 0:
                log.info(
                    "DISPATCH_EMPTY_BOX_STAGED_WORK residents=%d staging_depth=%d",
                    residents, staging_depth,
                )
            slot = await self.queue.pop_next(
                warm_model_tag=self._dispatch_warm_hint(),
                fastlane_policy=self._fastlane_pop_kwarg(),
                grace_active=await self._grace_active_exclusions(),
                room_available=self._dispatch_room_hint(),
            )
            if slot is None:
                # Wake on the queue's on_enqueue hook (set by enqueue() and
                # enqueue_head(), wired in __init__) instead of an
                # unconditional poll. Bounded by asyncio.wait_for so a missed
                # or disconnected hook degrades to today's poll cadence
                # rather than hanging -- same shape as _await_make_room's own
                # bounded Condition wait just above. Wait BEFORE clear (not
                # clear-then-wait): Event.wait() returns immediately if
                # already set, so a set() that lands between pop_next()
                # returning None and this wait starting is never lost -- it
                # is only a race that costs an extra pop_next() call, never a
                # missed wake. Safe to wake near-instantly now because
                # grace_active (passed to pop_next above) makes a same-thread
                # follow-up inside an active, non-victim grace window
                # invisible to this pop regardless of timing, closing the
                # race this wake used to have against the GRACE-loop's own
                # pop_matched_thread poll.
                try:
                    await asyncio.wait_for(
                        self._dispatch_wake.wait(), timeout=_DISPATCH_DEFER_BACKOFF_S
                    )
                except TimeoutError:
                    pass
                finally:
                    self._dispatch_wake.clear()
                continue
            if slot.is_evicted:
                self._handle_unloaded_slot(slot)
                continue
            try:
                with self._reserving(slot.model_tag):
                    await self._route_or_reserve(slot)
            except asyncio.CancelledError:
                raise
            except Exception:
                log.exception("dispatch of slot %s failed", slot.slot_id)
                self._fail_completion_future(
                    slot, RuntimeError("dispatch routing failed")
                )
        log.info("dispatcher exited")

    def _handle_unloaded_slot(self, slot: Slot) -> None:
        """Client-disconnect eviction (mirrors worker_loop's is_evicted branch).
        The per-resident idle tick is owned by the drivers, so it is NOT here."""
        self._fail_completion_future(
            slot,
            SlotEvictedError(f"slot {slot.slot_id} evicted: client disconnect"),
        )
        self._spawn_bg(self._audit_unloaded_slot(slot))
        self._unload_count += 1
        self._last_unloaded_at_iso = datetime.now(timezone.utc).isoformat()  # noqa: UP017

    async def _audit_unloaded_slot(self, slot: Slot) -> None:
        try:
            await self._audit_event_only_async(
                slot.slot_id,
                "slot_evicted",
                {
                    "reason": "client_disconnect",
                    "time_in_queue_s": time.monotonic() - slot.created_at,
                },
            )
            # Telemetry — client disconnect
            try:
                elapsed = time.monotonic() - slot.created_at
                self._telemetry.on_client_disconnect(slot, "client_disconnect", elapsed)
            except Exception:
                pass
        except Exception:
            log.exception("slot_evicted audit emit failed (best-effort)")

    def _live_resident_for(self, model_tag: "str | None") -> "Resident | None":
        """The live (non-DEAD) model_tag-keyed resident, or None."""
        if model_tag is None:
            return None
        r = self._residents.get(model_tag)
        if r is None or r.state is ResidentState.DEAD:
            return None
        return r

    def _fastlane_enabled(self) -> bool:
        """Is the Fast Lane feature switched ON right now?

        Read LIVE off ``self.runtime.fastlane`` on every call and NOT cached --
        the same discipline, and for the same reason, as
        ``_fastlane_pop_kwarg``: one cheap scalar read, where caching would
        reintroduce the exact stale-copy bug that helper exists to avoid. A
        ``put_config`` that replaces ``self.runtime`` wholesale AND an in-place
        mutation of ``self.runtime.fastlane`` are therefore both picked up on
        the next call, with no ``invalidate_fastlane`` hook required.

        DECISION, not a side effect: this is keyed on ``enabled``
        ALONE, deliberately NOT on ``_fastlane_table()`` being non-empty. The
        two are not equivalent, because the table is ALSO empty for
        ENABLED-WITH-NO-RULES -- and that is a live, behaviour-bearing
        configuration here, not a degenerate one. With an empty table every
        staged slot is "normal" (nothing matches a rule), which is precisely
        the population ``queue._pick_fastlane_locked``'s wall-clock fairness
        floor governs via ``policy.max_normal_wait_s``. The staleness grant is the
        RESIDENT-side member of that same anti-starvation family: it keys on
        client IDENTITY (``idle_client_meta["ip"]``) and never calls
        ``match_fastlane`` at all. Gating it on the rule table would make it
        depend on an input it does not consult, and would silently switch it
        off in a configuration where it still has work to do. Rule-RANKING
        callers (``_resident_unload_priority_key`` and friends) keep gating
        on the table, correctly: for those an empty table genuinely does mean
        "no ordering information exists."
        """
        cfg = getattr(self.runtime, "fastlane", None)
        return cfg is not None and bool(getattr(cfg, "enabled", False))

    def _fastlane_staleness_protects(self, r: "Resident") -> bool:
        """Is r CURRENTLY protected by an unexpired staleness grant?

        True only inside the window ``[threshold, threshold+window)`` after
        r's last recorded eviction. Before ``threshold``: not yet "long
        enough" to need rescue, ordinary eviction rules apply. At or past
        ``threshold+window`` with the grant never spent: EXPIRED, ordinary
        rules resume -- a client that never returns can never hold a
        permanent do-not-evict flag (the answer when every
        candidate is protected: a grant is single-use AND time-bounded, so
        this can never be a permanent condition, only a temporary one exactly
        like the pre-existing "nothing evictable right now" shape
        ``_route_or_reserve`` already handles via ``_defer_unroutable``).

        Same ``idle_client_meta`` resolution the unload ranking and ``_record_staleness_unload``
        use -- an UNRESOLVABLE identity (``idle_client_meta`` is ``None``,
        e.g. every ``parallel>=2`` engine) is never protected. KNOWN
        LIMITATION, stated on its own terms, not by reference to the ranking's: this
        is not a degraded ranking, it is the total, silent ABSENCE of the grant's
        guarantee for that population -- a repeatedly-evicted parallel>=2
        client can never be recorded, never accrues a clock, and can NEVER
        receive a grant. "No worse than today" does not carry here, because
        before staleness grants existed nobody had this guarantee at all.

        INERT while Fast Lane is switched off (``_fastlane_enabled``).
        The gate lives HERE, inside the predicate, rather than at either call
        site, so the real filter (``_lru_idle_unloadable``) and its diagnostic
        mirror (``_starvation_reason``) can never disagree about it -- the
        drift between those two is itself an instrumented invariant, and a
        call-site gate would have broken it by construction.
        """
        if not self._fastlane_enabled():
            return False
        meta = r.idle_client_meta
        ip = (meta or {}).get("ip")
        if not ip:
            return False
        evicted_at = self._fastlane_staleness_grants.get(_fastlane_census_key(ip))
        if evicted_at is None:
            return False
        elapsed = time.monotonic() - evicted_at
        return _STALENESS_GRANT_THRESHOLD_S <= elapsed < (
            _STALENESS_GRANT_THRESHOLD_S + _STALENESS_GRANT_WINDOW_S
        )

    def _record_staleness_unload(self, r: "Resident") -> None:
        """Re-arm the staleness clock for r's resolved client identity on
        EVERY eviction, not just the first -- a client evicted three times in
        quick succession has its clock reset each time, so the THIRD eviction
        is the one whose clock governs the next grant, matching "repeatedly
        evicted" rather than "evicted once, long ago." Called from
        ``_begin_unload_locked`` -- the sole eviction entry point already, for
        both ranking-driven and any other eviction reason.

        Same resolution and same fail-open posture as
        ``_fastlane_staleness_protects``: an unresolvable identity is simply
        never recorded (no exception, no penalty -- matches
        ``match_fastlane``'s own fail-open contract). Same bounded/fail-closed
        discipline as ``_fastlane_census``: an existing entry is always
        refreshable; a genuinely NEW distinct identity is refused once the
        table is at capacity, rather than evicting an existing grant to make
        room for it.

        Observability: the capacity refusal above is COUNTED, same
        dict[str, int]-by-reason shape as queue.py's own
        ``_fastlane_refusal_counts`` (keyed "ordinary_budget" now,
        a non-lane cross-model swap refused by the per-minute budget; the
        old "budget" lane-side reason can no longer occur) --
        observability only, no behaviour change: the refusal itself still
        happens exactly as before, on the exact same condition, this only
        makes it visible. Scope is deliberately ONE increment, nothing
        else -- no threshold tuning, no eviction policy, no new refusal
        reason. Surfacing (an API/metrics read path) is NOT wired here, because
        it is a wrong-object problem, not a missing-route one:
        The existing socket reads ``self.queue.fastlane_refusal_counts()``
        -- the QUEUE's own dict, a different module, a different refusal
        class (swap-budget, at pop-time) entirely from this one (staleness-
        grant capacity, at eviction-time, manager-scoped). Plugging this
        counter into that socket would misattribute one reason to the
        other's namespace. Instead, a WARNING log line, readable
        TODAY with no socket at all -- the manager runs at INFO, which is
        exactly why a DEBUG-only line (``_log_fastlane_declined``) leaves a refusal
        invisible; this must not repeat that one level down. 256 identities
        on a multi-client deployment means this should fire NEVER -- rare AND
        serious is WARNING, not DEBUG or INFO. The reason is named in the
        line itself (``reason=capacity``) so an ABSENT line is never
        ambiguous about which refusal class it would have been.

        Gated OFF with the feature. Nothing is recorded while Fast
        Lane is disabled, so on a box that never enabled it the grants table
        stays at its empty ``__init__`` state -- no growth toward
        ``_STALENESS_GRANTS_MAX``, and no ``FASTLANE_STALENESS_GRANT_REFUSED``
        WARNING from a feature the operator never switched on.

        This also settles the runtime-toggle question deliberately: enabling
        Fast Lane starts the staleness clock CLEAN rather than honouring evictions that
        happened while it was off. Those evictions were ordinary LRU, not
        Fast-Lane-mediated, so they are not the unfairness the staleness grant exists to repay;
        and honouring them would let one flip of the switch make up to
        ``_STALENESS_GRANTS_MAX`` identities simultaneously unevictable, at
        once, with no operator-visible cause. The reverse direction (ON->OFF)
        is covered by the gate in ``_fastlane_staleness_protects`` instead of
        by clearing the table here: a clear-on-toggle hook
        would only half-cover the config paths that exist.
        """
        if not self._fastlane_enabled():
            return
        meta = r.idle_client_meta
        ip = (meta or {}).get("ip")
        if not ip:
            return
        address = _fastlane_census_key(ip)
        if (
            address not in self._fastlane_staleness_grants
            and len(self._fastlane_staleness_grants) >= _STALENESS_GRANTS_MAX
        ):
            self._fastlane_staleness_refusals["capacity"] = (
                self._fastlane_staleness_refusals.get("capacity", 0) + 1
            )
            log.warning(
                "FASTLANE_STALENESS_GRANT_REFUSED reason=capacity address=%s cap=%d",
                address, _STALENESS_GRANTS_MAX,
            )
            return
        self._fastlane_staleness_grants[address] = time.monotonic()

    def _spend_staleness_grant_if_completed(self, slot: "Slot | None") -> None:
        """Spend (consume) a staleness grant -- ONLY here, ONLY once a
        turn has genuinely completed. Called exactly once
        ``_serve_on_resident`` has RETURNED for the anchor slot, which cannot
        happen without that slot's generation having already been delivered
        (``_serve_on_resident``'s own first action, before its grace loop
        even starts, is completing it and setting ``slot.completion_future``)
        -- a real observed signal, not an inference from a different
        guarantee. Never spent at reservation or admission: by design,
        consuming it at reservation would discharge the guarantee without
        ever delivering the thing guaranteed, which would be a promise that pays
        itself. Never touches ``_serve_on_resident`` itself.
        """
        ip = (slot.client_meta or {}).get("ip") if slot is not None else None
        if not ip:
            return
        self._fastlane_staleness_grants.pop(_fastlane_census_key(ip), None)

    @staticmethod
    def _resident_has_running_turn(r: "Resident") -> bool:
        """True while the resident is serving a turn (an active slot or
        in-flight riders). One predicate shared by every unload-candidate
        check so the primary list and the fallback arm cannot drift."""
        return r.active_slot is not None or bool(r.inflight)

    def _idle_unload_candidates(self) -> "list[Resident]":
        """The primary unload-candidate list: residents that are
        IDLE_EVICTABLE, have no running turn, and hold no unexpired staleness
        grant. This is the one definition of "reclaimable"; both
        ``_lru_idle_unloadable`` and the reclaim-first decision use it."""
        return [
            r
            for r in self._model_residents()
            if r.state is ResidentState.IDLE_EVICTABLE
            and not self._resident_has_running_turn(r)
            and not self._fastlane_staleness_protects(r)
        ]

    def _lru_idle_unloadable(
        self,
        *,
        main_gpu: "int | None" = None,
        split_mode: "str | None" = None,
    ) -> "Resident | None":
        """Least-recently-active resident that is IDLE_EVICTABLE with NO active
        slot and NO inflight riders. Busy residents are NEVER evictable.

        When ``main_gpu`` is given (VRAM over-commit make-room), the
        victim must be one whose eviction actually frees VRAM on the TARGET card, so
        we never evict a warm off-card resident that wouldn't relieve the over-commit.
        A ``split='none'`` resident occupies exactly its ``main_gpu``; a
        layer/row/tensor-split resident spans EVERY card (so it's on the target card
        too). For a ``split='none'`` incoming target we therefore keep only
        on-card-'none' + any-split victims; for a layer/aggregate incoming target
        (which budgets across all cards) freeing any card helps, so we keep all.
        ``main_gpu=None`` (a pure model-COUNT-cap make-room, where any freed registry
        slot suffices) keeps the original global-LRU behavior.

        Victim ORDER among the survivors is priority-aware, not pure LRU: an
        unlisted-or-unresolvable resident is preferred before any listed one;
        among listed residents the HIGHEST rule_index (lowest Fast Lane
        priority) goes first, and inside one rule_index the worse tag rank
        goes first; last_active_monotonic only breaks a tie between residents
        of an equal ``(rule_index, rank)``, never crosses tiers or ranks. See
        ``_resident_unload_priority_key`` for the resolution and the
        unresolvable/unlisted collapse. Feature-off (no fastlane table) or an
        all-unlisted pool degrades to the original global-LRU order exactly,
        byte-for-byte -- every resident lands in the same bottom tier.

        A resident is ALSO not a candidate while it holds an unexpired
        staleness grant (``_fastlane_staleness_protects``) -- a client
        repeatedly evicted before ever getting a meaningful turn earns one
        protected turn once it has waited long enough since its last
        eviction. Additive only: the three exclusions above are
        unchanged in effect.

        Fast Lane gate: ``_fastlane_staleness_protects`` returns False
        unconditionally while Fast Lane is disabled (``_fastlane_enabled``),
        and nothing is recorded while it is disabled either.
        The guarantee is therefore a feature gate, not an assumption
        about an empty table: on a box that never enabled Fast Lane
        the grants table stays empty, this clause is always False,
        and the candidate set is identical to the behavior before
        staleness grants existed. Grants are recorded only while
        Fast Lane is enabled, so the gate and the recording rule
        together keep a disabled deployment unaffected.
        With Fast Lane ENABLED the clause is live
        and does exclude protected residents;
        that is by design.
        """
        cands = self._idle_unload_candidates()
        if main_gpu is not None and (split_mode or "none").lower() == "none":
            cands = [
                r
                for r in cands
                if (r.split_mode or "layer").lower() != "none"
                or r.main_gpu == main_gpu
            ]
        # Fallback arm: when no idle-evictable resident exists, use the
        # designated victim even though its state is not idle. This is only
        # for a victim whose grace was already started and has ended (the
        # grace loop exited because the victim was designated) and that is
        # no longer running a turn. A resident on its first turn, or still
        # inside its grace loop, is never returned here. A resident with a
        # running turn (an active slot or in-flight riders) is never
        # returned either, however its grace state looks: that turn runs to
        # completion and the turn-end path tears the victim down at its
        # turn boundary.
        if not cands:
            for r in self._model_residents():
                if r.state is not ResidentState.ACTIVE:
                    continue
                if r.grace is None or r.grace._started_at is None or r.in_grace_loop:
                    continue
                if self._resident_has_running_turn(r):
                    continue
                if not self._is_designated_unload_target_locked(r):
                    continue
                if self._fastlane_staleness_protects(r):
                    continue
                # Card/split gate mirrors the IDLE_EVICTABLE arm
                # above: a 'none'-split resident on the wrong
                # card is skipped; a layer-split resident is always eligible.
                if (
                    main_gpu is not None
                    and (split_mode or "none").lower() == "none"
                    and (r.split_mode or "layer").lower() == "none"
                    and r.main_gpu != main_gpu
                ):
                    continue
                cands.append(r)
                break
        if not cands:
            return None
        table = self._fastlane_table()
        return min(
            cands, key=lambda r: self._resident_unload_priority_key(r, table)
        )

    def _fastlane_outrank_unload_target_locked(
        self,
        slot: Slot,
        split_mode: "str | None",
    ) -> "Resident | None":
        """CALLER HOLDS ``_registry_lock``. Fast Lane outrank gate,
        SHARED by the pinned and the auto_place arms of _route_or_reserve's
        VRAM over-commit make-room site (the two arms must
        apply the same priority rule -- one helper, two call sites, no
        drift). Returns the globally worst-ranked idle-evictable resident
        when the claimant HOLDS A LIVE FAST LANE CLAIM that STRICTLY
        OUTRANKS it (or the candidate is unlisted -- see below), else
        ``None`` so the caller falls through to its own fallback scope.

        "Strictly outranks" compares full ``(rule_index, rank)`` keys: the
        client rank decides first, so the tag rank only matters between the
        claim and a resident of the SAME client (a better tag's claim outranks
        a worse-tag resident of that client; a tag never lifts one client
        above another).

        Pure selection: no slot mutation (the relocation override is the
        Pinned caller's job -- the auto_place arm deliberately sets none,
        because its re-routing auto-placer re-picks the card on the
        evict-pending retry), no queue lock (``_fastlane_priority_key`` is
        a pure accessor over ``slot.fastlane``), no I/O.

        A ``candidate_key`` of ``None`` means the candidate is UNLISTED, not
        "no claim" -- by design an unlisted
        resident ranks below all registered ones and is trivially
        outranked by any live listed claimant (the claimant_key not-None
        guard is guaranteed above), so it JOINS the outrank condition
        instead of vetoing it -- _resident_unload_priority_key already
        sorts unlisted residents first (tier 0, cheapest to evict); this
        makes the widening agree with it. The claimant-side
        ``claimant_key is not None`` guard is unchanged: that None means
        "no live claim, decline" and is correct there."""
        claimant_key = self.queue._fastlane_priority_key(slot)
        if claimant_key is None:
            return None
        global_candidate = self._lru_idle_unloadable(
            split_mode=split_mode)
        if global_candidate is None:
            return None
        candidate_key = self._resident_priority_key(
            global_candidate, self._fastlane_table())
        if candidate_key is None or (
            self.queue._fastlane_strictly_higher(
                claimant_key, candidate_key
            )
        ):
            return global_candidate
        return None

    def _reclaim_first_applies(
        self,
        slot: Slot,
        auto_place: bool,
        auto_picked: bool,
        split_mode: "str | None",
    ) -> bool:
        """The one place that says which requests get the reclaim-first
        decision: every request whose card the auto-placer decides. That is a
        manifest whose own split is none and that is auto-placed (the manifest
        sets auto_place, or the fast lane is on), the same test
        ``_resolve_placement_locked`` applies before it calls ``_auto_pick_gpu``.
        A manifest that is not auto-placed with the lane off (its pin stays put)
        and a manifest whose own split is layer, row or tensor are not included.

        ``auto_place``, ``auto_picked`` and ``split_mode`` are the values
        ``_resolve_placement_locked`` returned, read BEFORE any override is
        applied: when the auto-pick was applied the manifest's own split was
        none, otherwise ``split_mode`` is still the manifest's own. ``slot`` is
        not read today; it is here so the rule can be narrowed to claimants of
        a live Fast Lane claim by adding one condition on it."""
        own_split_none = auto_picked or split_mode == "none"
        return own_split_none and (auto_place or self._fastlane_enabled())

    def _reclaim_card_rank_term(
        self, on_card: "list[Resident]", needed_g: int, table: list,
    ) -> "tuple[int, int, int]":
        """How protected the idle residents are that one card would have to
        unload: the most protected of them, as the first three parts of the
        unload priority key: the tier, then the Fast Lane rule order, then
        the tag rank inside one client (recency is left out). They are taken
        in unload order until their MiB cover ``needed_g``. A card that
        unloads nobody gets ``(-1, 0, 0)``, below any real resident's term.
        A smaller term means less protected."""
        rank: "tuple[int, int, int]" = (-1, 0, 0)
        if needed_g <= 0:
            return rank
        freed = 0
        for r in sorted(
            on_card, key=lambda c: self._resident_unload_priority_key(c, table),
        ):
            rank = max(rank, self._resident_unload_priority_key(r, table)[:3])
            freed += r.reserved_need_mib
            if freed >= needed_g:
                break
        return rank

    def _unload_on_decided_card_locked(
        self, slot: Slot, main_gpu: int, split_mode: "str | None",
        choice: "ReclaimFirstChoice | None", unload_reason: str,
        starved_reason: str, *, frees_count_slot: bool = False,
    ) -> None:
        """CALLER HOLDS ``_registry_lock``. Synchronous, no await. A claimant
        pinned to a card by the reclaim-first decision cannot start on this
        pass. Unload at most ONE idle resident ON that card (the same lookup
        the memory arm uses for a pinned claimant: an idle resident on it, or
        a layer-split one), and queue the claimant for the next pass; the
        unload frees memory only later, so nothing is reserved in-band.

        Unload only while this pass's decision still reports memory to free
        (``choice.needed_mib > 0``): when unloads already in flight on that
        card cover the need (``needed_mib == 0``) just wait, never a second
        unload for the same shortfall. No idle resident on the card: unload
        nothing and log the starvation.

        With ``frees_count_slot`` (the model-count cap arm) and
        ``needed_mib == 0`` the shortfall is the count, not the memory: the
        unloads in flight cover the memory, yet the registry is still full.
        Then the count slot is freed with that arm's usual victim order, any
        idle resident (no card restriction); with no idle resident at all the
        starvation is logged. Even then nothing is reserved in-band: the
        claimant is queued and the next pass decides the start."""
        if choice is not None and choice.needed_mib > 0:
            victim = self._lru_idle_unloadable(
                main_gpu=main_gpu, split_mode=split_mode)
            if victim is None:
                attribution = self._starvation_reason()
                self._log_make_room_starved(slot, starved_reason, attribution)
            else:
                self._log_make_room_unload(victim, unload_reason)
                self._begin_unload_locked(victim)
        elif frees_count_slot and choice is not None:
            victim = self._lru_idle_unloadable()
            if victim is None:
                attribution = self._starvation_reason()
                self._log_make_room_starved(slot, starved_reason, attribution)
            else:
                self._log_make_room_unload(victim, unload_reason)
                self._begin_unload_locked(victim)
        self._defer_unroutable(slot, evict_pending=True)

    def _reclaim_first_card_locked(
        self, slot: Slot, need: int, parallel: int,
        table: "list | None" = None,
    ) -> "ReclaimFirstChoice | None":
        """CALLER HOLDS ``_registry_lock``. Synchronous, no await; the caller
        runs it off the event loop because it reads live free VRAM. ``table``
        is the Fast Lane rule table, read by the caller on the event loop
        (it can recompile and write a cache, so it is not read here on the
        worker thread); None reads it here, for a direct call.

        Returns the one card ``slot`` fits on once the idle residents of that
        card count as free, or None (the caller keeps today's placement). Per
        card, a card is usable when ALL of these hold:
          - The card has something to reclaim: an idle resident (split none,
            see ``_idle_unload_candidates``) or VRAM already on its way back
            from an unload in flight. A card with neither is the placer's
            business, and the gate can admit blindly when its own probe read
            fails with no residents, which must never turn into a relocation.
          - FIT: ``_vram_admits_locked`` admits the model on that card with the
            card's idle residents counted as reclaimed and with unloads already
            in flight counted once (``credit_pending``), AND the card keeps the
            safety floor free, like the placer's own pick. Layer-split
            residents are not counted: their share of one card is not
            recorded.
          - RESIDUE: every other card keeps its free VRAM, net of models still
            booting there, minus ``OTHER_CARD_CUDA_RESIDUE_MIB``, at or above
            the safety floor.
        Among usable cards: the one whose most protected resident to be
        unloaded is the least protected first (see ``_reclaim_card_rank_term``;
        a card that unloads nobody, because it fits as it stands or through
        unloads already in flight, comes first of all), then the one that needs
        the fewest MiB unloaded now, then the largest headroom, then the lowest
        card index. Rank only orders usable cards and never decides whether a
        card is usable. This chooses WHERE; the existing victim order chooses
        WHICH idle resident on that card goes first.

        A refusal is logged only for a card that has a reclaimable resident or
        VRAM on its way back; with none of either on any card nothing is logged
        (except an unreadable probe while an idle candidate exists). With no
        idle candidate and no VRAM on its way back on any card it returns None
        before it reads the free-VRAM probe.
        """
        cands = [
            r for r in self._idle_unload_candidates()
            if (r.split_mode or "layer").lower() == "none"
        ]
        if not cands and not any(
            v > 0 for v in self._pending_reclaim_mib.values()
        ):
            return None
        live_free = _read_free_vram_all_mib()
        if not live_free:
            if cands:
                log.info(
                    "reclaim_first_refused claimant=%s card=%s reason=%s detail=%s",
                    slot.model_tag, "none", "probe_unreadable",
                    "free_vram_probe_returned_nothing",
                )
            return None
        floor = self.runtime.queue.safety_min_free_vram_mib
        reclaim_by_card: dict[int, int] = {}
        for r in cands:
            reclaim_by_card[r.main_gpu] = (
                reclaim_by_card.get(r.main_gpu, 0) + r.reserved_need_mib
            )
        # Free VRAM on a card is net of models still booting there: their
        # weights are not in the live reading yet.
        booting_by_card: dict[int, int] = {}
        for r in self._model_residents():
            if r.state is ResidentState.RESERVED_LOADING:
                booting_by_card[r.main_gpu] = (
                    booting_by_card.get(r.main_gpu, 0) + r.reserved_need_mib
                )
        if table is None:
            table = self._fastlane_table()
        usable: (
            "list[tuple[tuple[int, int, int], int, int, int, ReclaimFirstChoice]]"
        ) = []
        for g, free_g in enumerate(live_free):
            reclaim_g = reclaim_by_card.get(g, 0)
            pending_g = self._pending_reclaim_mib.get(g, 0)
            booting_g = booting_by_card.get(g, 0)
            if reclaim_g <= 0 and pending_g <= 0:
                continue
            available_now = free_g - booting_g + pending_g
            if not (
                self._vram_admits_locked(
                    need, parallel, g, "none",
                    credit_pending=True,
                    reclaim_mib_by_card={g: reclaim_g},
                )
                and available_now + reclaim_g - floor >= need
            ):
                log.info(
                    "reclaim_first_refused claimant=%s card=%s reason=%s "
                    "detail=%s",
                    slot.model_tag, g, "no_fit",
                    f"need_mib={need} free_mib={free_g} "
                    f"booting_mib={booting_g} pending_mib={pending_g} "
                    f"reclaimable_mib={reclaim_g} floor_mib={floor}",
                )
                continue
            short = next(
                (
                    (o, free_o)
                    for o, free_o in enumerate(live_free)
                    if o != g
                    and free_o - booting_by_card.get(o, 0)
                    - OTHER_CARD_CUDA_RESIDUE_MIB < floor
                ),
                None,
            )
            if short is not None:
                log.info(
                    "reclaim_first_refused claimant=%s card=%s reason=%s "
                    "detail=%s",
                    slot.model_tag, g, "residue",
                    f"card={short[0]} free_mib={short[1]} "
                    f"booting_mib={booting_by_card.get(short[0], 0)} "
                    f"residue_mib={OTHER_CARD_CUDA_RESIDUE_MIB} "
                    f"floor_mib={floor}",
                )
                continue
            needed_g = max(0, need + floor - available_now)
            headroom = available_now + reclaim_g - floor - need
            rank_g = self._reclaim_card_rank_term(
                [r for r in cands if r.main_gpu == g], needed_g, table,
            )
            usable.append((
                rank_g, needed_g, -headroom, g,
                ReclaimFirstChoice(g, reclaim_g, pending_g, needed_g),
            ))
        if not usable:
            return None
        return min(usable, key=lambda u: u[:4])[4]

    def _resident_unload_priority_key(
        self, r: "Resident", table: list,
    ) -> "tuple[int, int, int, float]":
        """Sort key for ``_lru_idle_unloadable`` -- ONE-LINE DELEGATE (the
        one deliberate exception to "call, never rewrite") to the
        module-level pure ``_unload_priority_key_for_meta``: unlisted-or-
        unresolvable residents sort first (tier 0, evicted before any listed
        resident); among listed residents (tier 1) a HIGHER rule_index -- lower
        Fast Lane priority -- sorts first, then the worse tag rank within one
        rule_index; ``last_active_monotonic`` only breaks a tie between equal
        ``(rule_index, rank)``. The meta is read through
        ``_resident_rank_meta``, the same reader ``_resident_priority_key``
        uses. See ``_unload_priority_key_for_meta``'s own docstring for the
        full contract, and ``_resolve_fastlane_match`` for why this can never
        disagree with ``_resident_priority_key`` (claim designation) about
        which resident is worst.
        """
        return _unload_priority_key_for_meta(
            self._resident_rank_meta(r), table, r.last_active_monotonic
        )

    @staticmethod
    def _resident_rank_meta(r: "Resident") -> "dict | None":
        """The ONE place that decides which client identity a resident's rank is read
        from: that of its latest turn. ``rank_client_meta`` is stamped at reserve, at
        every turn start and where a same-thread follow-up served inside the grace window
        advances ``grace_tip``; ``idle_client_meta`` is read only for an idle resident
        that has nothing stamped. The designation key, the outrank gate and the
        idle-eviction key all read their meta here, so they can never rank one resident
        by two different turns."""
        meta = r.rank_client_meta
        if meta is None and r.state is ResidentState.IDLE_EVICTABLE:
            meta = r.idle_client_meta
        return meta

    def _resident_priority_key(
        self, r: "Resident", table: list,
    ) -> "tuple[int, int] | None":
        """A resident's raw Fast Lane ``(rule_index, rank)``: the key claim
        designation, the outrank gate and the victim pool rank residents by
        (the same pair is shown as the ``rule_index``/``rank`` fields of
        ``fastlane_claims_snapshot``). Returns ``None`` for an unlisted-or-
        unresolvable resident (mirrors ``match_fastlane``'s own None
        contract), never a placeholder tuple.

        Identity resolution is ``_resident_rank_meta``: ``rank_client_meta``
        (the client of the resident's latest turn) is authoritative when
        present. ``idle_client_meta`` is used ONLY as a fallback for an IDLE
        resident with nothing stamped: it reflects whoever was served BEFORE
        the resident last parked, which is a WRONG identity (not merely a
        missing one) for a resident now mid-turn for a different client
        (residents are keyed by ``model_tag``, not by client). Neither
        present -> ``None`` (UNRESOLVABLE), never a stale guess -- the compute-fresh rule, "the
        decision must reflect reality, not a stale snapshot."

        Calls the SAME ``_resolve_fastlane_match(meta, table)`` that
        ``_unload_priority_key_for_meta`` calls, and both read their meta from
        ``_resident_rank_meta``, so "is this resident listed", "what is its
        rule_index" and "what is its rank" can never differ between
        designation (this function) and eviction (that one): there is exactly
        one place that picks the identity and one that resolves it. See the
        drift test for the property this guarantees.
        """
        match = _resolve_fastlane_match(self._resident_rank_meta(r), table)
        if match is None:
            return None
        return (match.rule_index, match.rank)

    def _governing_claim_priority_key_locked(self) -> "tuple[int, int] | None":
        """The best (numerically lowest) Fast Lane priority key among all
        LIVE claims, or ``None`` when no live claim exists.

        ⛔ THIS METHOD DOES NOT REQUIRE ``_registry_lock``: it changes no
        claim key, is sync and await-free, and it is called from
        ``_fastlane_pop_kwarg`` WITHOUT the lock, deliberately. The
        ``_locked`` suffix is kept only for naming symmetry with
        ``_governing_claim_locked``; it does not mean the lock is required.
        ⛔ DO NOT ADD A LOCK ACQUISITION HERE OR AT THAT CALLER. Doing
        so takes ``_registry_lock`` and then ``queue._lock`` inside
        ``pop_next``, which INVERTS the established
        ``queue._lock -> _registry_lock`` order and deadlocks. Holding the
        lock while calling this is also fine
        (``_is_designated_unload_target_locked`` does), but the
        lock-free call from ``_fastlane_pop_kwarg`` is the production
        path, so the lock must stay optional.
        What makes the lock-free read safe is that this whole path is sync
        and await-free, so no coroutine interleaves during it, and no THREAD
        mutates ``_fastlane_claims`` -- both pinned executably by
        the readmission-rank test. Staleness across the
        caller's subsequent ``await`` is tolerated and bounded; see
        ``_fastlane_pop_kwarg`` for why.

        This is the missing half of the outrank precondition. The Fast Lane
        rule opens with a precondition, not a state: a higher-priority request
        is waiting in the queue and the server is at capacity. From this
        moment on, the loaded clients are split into two classes. There is
        no designated victim when nothing is claiming -- the unconditional-grace rule governs instead,
        and that rule is explicit: grace is unconditional in this state, every
        loaded client gets it, registered or not.

        Liveness is re-derived here on every call via ``_claim_is_live``
        rather than trusted from the registry, because a dead claim must
        never govern an eviction (a security requirement, and the compute-fresh rule's "the decision
        must reflect reality, not a stale snapshot"). Dead claims are NOT
        pruned here: pruning mutates ``_fastlane_claims`` and this method is
        called from inside read-only predicates; ``fastlane_claims_snapshot``
        owns the prune. Skipping is sufficient: nothing is deleted here (the
        liveness call can only move a claim whose request is gone to the best
        remaining waiter, which edits the claim record and not the dict).

        Sync and await-free by construction -- it is called from under
        ``_registry_lock`` and must not introduce a suspension point there.
        ``queue._fastlane_priority_key`` is a pure accessor over
        ``slot.fastlane`` and takes NO queue lock, so this cannot invert the
        established ``queue._lock -> _registry_lock`` order.
        """
        governing = self._governing_claim_locked(include_parked=False)
        return None if governing is None else governing[0]

    def _governing_claim_locked(
        self, include_parked: bool = True,
    ) -> "tuple[tuple[int, int], Slot] | None":
        """The governing live claim as ``(priority_key, slot)``, or ``None``
        when no live claim exists.

        ⛔ This method takes no lock, for the same reason as
        ``_governing_claim_priority_key_locked`` above:
        it changes no claim
        key, is sync and await-free, and is reached lock-free through that
        projection. Read its note before adding any lock here.

        This is the ORIGINAL body of
        ``_governing_claim_priority_key_locked``, unchanged in every
        selection decision it makes, split out so that the multi-victim rule's victim-SET
        question can reach the CLAIMANT'S SLOT and not just its key. The
        set's size depends on what the claimant is (a layer-split model
        cannot co-reside at all -- ``_vram_admits_locked``), and that
        is a property of the slot, not of the priority key.

        It is a SPLIT, not a second loop, deliberately: a second traversal
        of ``_fastlane_claims`` could pick a different winner than this one
        on a tie and the two answers would drift silently. There is exactly
        one place that decides WHICH claim governs, and
        ``_governing_claim_priority_key_locked`` above is now a thin
        projection of it -- its own contract, return type and every one of
        its callers are untouched.

        Tie-handling is preserved exactly: the comparison is strict
        (``key < best[0]``), so the FIRST claim achieving the best key wins,
        which is what the pre-split ``key < best`` already did.

        ``include_parked=False`` leaves out claims parked in a resident's own
        inbox: they need no room, so the queue's hold-aside and the victim
        designation (both about claims that DO need room) must not see them.
        """
        best: "tuple[tuple[int, int], Slot] | None" = None
        for claim in self._fastlane_claims.values():
            if not include_parked and claim.get("parked_on"):
                continue
            if self._claim_is_live(claim) is not None:
                continue
            slot = claim["slot"]
            key = self.queue._fastlane_priority_key(slot)
            if key is None:
                continue
            if best is None or key < best[0]:
                best = (key, slot)
        return best

    def _is_worst_ranked_loaded_locked(self, r: "Resident") -> bool:
        """CALLER HOLDS ``_registry_lock``. Pure SELECTION: is ``r`` the
        worst-ranked loaded resident right now?

        This is the original body of ``_is_designated_unload_target_locked``,
        unchanged, split out under a name that says what it actually
        computes. It answers "who is worst", which is only HALF of
        "who is the designated victim" -- the other half is "is anyone
        claiming, and do they outrank this resident" (the opening of the outrank
        precondition). Keeping selection in exactly one place means the two
        questions cannot drift apart later, the same reason
        ``_unload_priority_key_for_meta`` was extracted earlier.

        Full ordering rationale -- loaded = {ACTIVE, GRACE}, unresolvable
        sorts WORST (the eviction pool for unregistered clients),
        worse tag rank first within one rule_index, ties between equal
        ``(rule_index, rank)`` broken by recency -- is on
        ``_is_designated_unload_target_locked`` below, which is the
        contract-named entry point callers use.
        """
        ordered = self._ranked_loaded_candidates_locked()
        return bool(ordered) and ordered[0] is r

    def _ranked_loaded_candidates_locked(self) -> "list[Resident]":
        """CALLER HOLDS ``_registry_lock``. THE CANDIDATE POOL, in
        victim order: **WORST FIRST**.

        This is the candidate-building loop lifted verbatim out
        of ``_is_worst_ranked_loaded_locked``, which is now a thin consumer
        of it (``ordered[0] is r``). The selection inputs are the
        ``_model_residents()`` source, the ``{ACTIVE, GRACE}`` filter, the
        tier-0/tier-1 split for unresolvable residents, and the key
        ``(tier, rule_index, rank, -last_active_monotonic)``, in which the
        worse tag rank goes first within one rule_index.

        WHY IT IS A SHARED HELPER AND NOT A SECOND IMPLEMENTATION. The
        multi-victim rule does not widen the candidate set: the
        set is the global eviction pool; it only permits taking more
        than one member of it. Because the single-victim selector and the
        victim-SET predicate now both read THIS list and neither builds its
        own, the multi-victim rule is structurally incapable of widening the pool -- there is
        no second filter that could drift from this one. That property is a
        consequence of the shape, not a promise in a comment, which is the
        same reason ``_resolve_fastlane_match`` and
        ``_unload_priority_key_for_meta`` were extracted before it.

        ``sort(reverse=True)`` IS EXACTLY THE OLD ``max()``, not merely
        close to it. Python's sort is stable and ``max`` returns the FIRST
        maximal element, so with equal keys -- reachable in practice, since
        two residents can share a ``last_active_monotonic`` -- the element
        landing at index 0 is the same object the old ``max()`` returned.
        The single-victim answer is therefore byte-identical, which is what
        lets the pre-existing designation tests stay untouched.

        Ordering is WORST FIRST because that is the order the victim-ordering rule defines
        and the multi-victim rule reuses ("victims are selected in the order that rule
        already defines -- lowest priority first, ties broken by recency
        within a rank"). Index 0 is the designated victim; index 1 is the
        next one the multi-victim rule may take.
        """
        table = self._fastlane_table()
        candidates = []
        for cand in self._model_residents():
            if cand.state not in (ResidentState.ACTIVE, ResidentState.GRACE):
                continue
            base = self._resident_priority_key(cand, table)
            if base is None:
                # UNLISTED/UNRESOLVABLE residents are the worst-ranked:
                # the Fast Lane rules make
                # unregistered clients the eviction
                # pool -- they rank BELOW all registered ones, so in this
                # max-selection they sort WORSE than any listed resident.
                # Tier 1 with the rule_index and rank slots zeroed (same
                # width as the listed key so the tuples compare); the
                # recency tie-break among unlisted keeps the eviction key's
                # own direction (least-recently-active first). Among LISTED
                # residents the key is (0, rule_index, rank,
                # -last_active): a higher rule_index goes first, and within
                # one rule_index the worse (larger) tag rank goes first,
                # the same order _unload_priority_key_for_meta gives.
                candidates.append(
                    (cand, (1, 0, 0, -cand.last_active_monotonic)))
                continue
            candidates.append(
                (cand, (0, base[0], base[1], -cand.last_active_monotonic)))
        candidates.sort(key=lambda pair: pair[1], reverse=True)
        return [cand for cand, _ in candidates]

    def _claimant_unloads_every_sibling_locked(self, slot: "Slot") -> bool:
        """CALLER HOLDS ``_registry_lock``. Does admitting ``slot``'s model
        require that EVERY loaded sibling go, rather than just the worst
        one? True exactly when the claimant is layer-split.

        This is the multi-victim rule's "until the claim can be satisfied", and it
        is answered from the ADMISSION GATE'S OWN STRUCTURE, never from
        VRAM arithmetic. ``_vram_admits_locked`` refuses ANY
        ``split_mode != 'none'`` claimant while ANY sibling exists and
        **never reads ``need`` on that branch** -- the refusal is
        structural, not budgetary ("a layer-split incoming model still
        cannot co-reside no matter how much VRAM frees up"). So for a
        layer-split claimant -- which is the multi-victim rule's own premise, "a model that
        does not fit on a single card" -- the real stopping condition is
        "until ZERO siblings remain", and there is no N to compute. A fix
        that summed VRAM here would be measuring a quantity that branch
        does not consult. (A binding constraint of
        this design.)

        WHY THE MANIFEST AND NOT THE EFFECTIVE PLACEMENT. The full
        resolution, ``_resolve_placement_locked``, reaches ``_auto_pick_gpu``
        -> ``_read_free_vram_all_mib``, which shells out to nvidia-smi
        (in safety.py, ``subprocess.check_output``). Two independent
        reasons not to call it from here, either of which alone decides it:

        1. ``_auto_pick_gpu`` IS PLACEMENT, and the multi-victim rule is a QUANTITY question,
           never a placement one -- relocation moves the CLAIMANT, not
           the victim order, and relocation sits upstream of
           the sort and of the multi-victim rule. Reading placement to answer "how
           many victims" is the category error that this rule exists to
           prevent. Whether the model fits on one card is a property of the
           MODEL, which is what the manifest describes; the auto-placer's
           split fallback is a property of the CARDS at one instant.
        2. This predicate is called on the grace-decision hot path
           (including ``_serve_on_resident``'s ``skip_grace``) and
           is documented pure and read-only. This package already forbids
           exactly that shape -- see ``status_snapshot``'s own contract,
           verbatim: "status_snapshot is LOCK-FREE and must NEVER call
           nvidia-smi synchronously".

           Every nvidia-smi probe reachable from the
           model-load path runs off the event loop, wrapped
           in ``asyncio.to_thread``. A probe is a
           subprocess call (``safety.py``'s
           ``subprocess.check_output(..., timeout=5)``), so
           a blocking call made on the loop stalls the
           whole API for up to 5.0s per probe: no coroutine
           runs meanwhile, including the ones serving live
           streams, and several probes sit on the model
           LOAD path inside ``async def
           _route_or_reserve``.

           The wrapped probes, by SYMBOL:
           ``_card_avail_mib``, ``_vram_admits_locked``'s
           retry (x2), ``_auto_pick_gpu``, and in
           ``safety.py`` ``_read_free_vram_mib``,
           ``_vram_budget`` and the tensor_split gate. The
           two calls in ``live_monitor.py`` are wrapped as
           well.

           The sibling probe ``_read_total_vram_all_mib``
           has the identical blocking shape and is reached
           from ``_begin_unload_locked``; it runs off the
           loop too.

           A list of callers is a measurement taken at one
           point in time, and it goes stale silently every
           time a call site is added. Do not argue from
           "the only caller" without re-deriving the caller
           list. This predicate is pure and read-only, so
           it must not add another unwrapped probe.

        ⚠ THE ERROR DIRECTION, STATED ON PURPOSE.
        The auto-placer fires ONLY when the manifest says ``split_mode ==
        'none'`` and can then fall back to a split. So this
        manifest read can say "not split" where the effective placement
        would say "split" -- a FALSE NEGATIVE. Its consequence is that the multi-victim rule
        does not engage and the earlier single-victim behaviour
        stands: a grace window that should have been removed is not. It can
        NEVER designate a victim that should not have been designated,
        which is the direction the multi-victim rule's third bullet ("does not widen the
        candidate set") actually cares about. The conservative error is
        preferred over putting an nvidia-smi probe on the grace path.

        ⭐ THE AFFIRMATIVE RULE. THE MULTI-VICTIM RULE engages ONLY
        on positive knowledge that the claimant is layer-split. A missing or
        unreadable manifest is NOT such knowledge, and this predicate returns
        False for it.

        Taking split_mode straight from ``_read_model_footprint``
        would be wrong, and it is an easy mistake to make: its
        missing-manifest branch returns ``(0, 1, 0, "layer", 0,
        False)``. That collapses "the manifest says layer-split"
        and "there is no manifest" into the same value, so EVERY
        claimant without a manifest would look layer-split and
        the multi-victim rule would engage universally,
        designating a NON-WORST resident as a victim. That is a
        FALSE POSITIVE, and it is the one direction the
        multi-victim rule forbids outright: the rule allows false
        negatives only and must never designate a victim that
        should not have been.

        The trap is that ``(x or "layer")`` IS the right convention at
        the admission gate and for the resident-side tests -- there,
        assuming layer-split means REFUSE co-residence, which is
        conservative. HERE the identical default means EVICT EVERY SIBLING,
        which is aggressive. **The same default has opposite safety
        directions in the two places**, and copying it across without asking
        which way it fails is what produced the defect. ``_read_model_
        footprint``'s own docstring calls that branch "degrade-OPEN for the
        footprint" -- open about ADMISSION, with the per-spawn safety gates
        still to come; it was never a licence to degrade-aggressive about
        eviction.

        So the manifest is consulted twice, deliberately and for two
        different questions: ``read_manifest_cached`` answers "do we know
        anything at all", and ``_read_model_footprint`` answers "what does it
        say". Only the second produces the value, so the two cannot drift.

        ``slot.fastlane_relocated_split_mode`` short-circuits both, mirroring
        the routing path's override, so this predicate and that path cannot disagree
        about what the claimant is. A relocation that already happened IS
        affirmative knowledge. ``None`` means "no relocation happened", not
        "split_mode is None", which is why it is compared against ``None``
        rather than truth-tested.

        Sync and await-free by construction -- ``_read_model_footprint`` is
        a sync manifest read with no probe call in it, verified by AST walk,
        so this introduces no suspension point under ``_registry_lock``.
        """
        if slot.fastlane_relocated_split_mode is not None:
            # A prior pass actually placed this slot, so this IS affirmative
            # knowledge of what the claimant is -- the routing path's own override,
            # mirrored so this predicate and the routing path cannot disagree.
            # Compared against ``None`` because None means "no relocation
            # happened", not "split_mode is None".
            return (slot.fastlane_relocated_split_mode or "layer").lower() != "none"
        try:
            read_manifest_cached(self.boot.storage.manifests_path, slot.model_tag)
        except Exception:
            # NO MANIFEST, OR AN UNREADABLE ONE => WE DO NOT KNOW => THE MULTI-VICTIM RULE DOES
            # NOT ENGAGE. See "the affirmative rule" in the docstring: absence
            # of knowledge must never become "evict every sibling".
            return False
        # Value from _read_model_footprint alone -- the single source of truth
        # for what the manifest SAYS. The read above establishes only that
        # there IS a manifest; it deliberately does not parse split_mode a
        # second time, because two parses could drift (that function owns it).
        # Cached read, the same reasoning _effective_cap gives:
        # this runs on a hot path, so an uncached
        # stat+read_text+yaml+validate here would be a real tail-latency
        # regression even though it is functionally inert.
        split_mode = self._read_model_footprint(slot.model_tag)[3]
        return (split_mode or "layer").lower() != "none"

    def _is_within_unload_target_set_locked(
        self, r: "Resident", claim_slot: "Slot",
    ) -> bool:
        """CALLER HOLDS ``_registry_lock``. Is ``r`` a member of the victim
        SET this claim needs -- the multi-victim rule's "two or more victims"?

        This is the whole behavioural change. The predicate
        it replaces at the top of ``_is_designated_unload_target_locked`` asked
        ``_is_worst_ranked_loaded_locked``, i.e. "are you THE single worst",
        so exactly one resident could ever answer True. The multi-victim rule: "A model
        that does not fit on a single card evicts TWO OR MORE victims...
        the selection continues until the claim can be satisfied." The
        intended behaviour is that evicting 2 or more lower-ranking clients
        to make space for a larger model is the exception to the single-
        victim case, because MULTIPLE RESIDENTS ARE DESIGNATED VICTIMS AT
        THAT POINT IN TIME.

        COMPUTED FRESH, NEVER STORED -- and that is what keeps the compute-fresh rule
        satisfied at the same time as the multi-victim rule. That rule: "the eviction decision is
        re-evaluated under lock at each lifecycle transition... NO CLIENT
        NAME IS CARRIED FORWARD from an earlier decision." Freshness and
        cardinality are ORTHOGONAL properties, and the compute-fresh rule governs only the
        first. It forbids PERSISTING a set -- a ``self._victim_set`` field,
        a cached list, anything surviving the lock release. It does not
        forbid COMPUTING one. This list is rebuilt from
        ``_ranked_loaded_candidates_locked`` on every single call, so it is
        exactly as fresh as the ``max()`` it replaces: same iteration, same
        candidates, same key, same instant. No name is carried forward
        because no name is stored. **Do not memoise this. A cached victim
        set is a stale snapshot with a friendly name** -- the same standing
        constraint ``_likely_unload_target_model_tag`` carries.

        WHY A FRESH SINGLE-VICTIM RE-EVALUATION IS NOT SUFFICIENT, which is
        the thing that makes this a real defect rather than a nicety.
        Victim 2's turn boundary can arrive BEFORE victim 1's. At that
        instant the single-victim question answers "no, you are not the
        worst" -- correctly, on its own terms -- and victim 2 enters a full
        grace window it must never have been granted. Re-evaluating later
        cannot take that window back: by the time victim 1 is evicted and
        the next decision moment names victim 2, victim 2 is already sitting
        in it. Re-evaluating a single-victim question more often does not
        make it a multi-victim answer. This can happen late in a
        window with both victims ACTIVE and nobody parked.

        THE MULTI-VICTIM RULE DOES NOT WIDEN THE CANDIDATE SET. The pool, the filter, the key
        and the order all come from ``_ranked_loaded_candidates_locked``,
        the SAME list ``_is_worst_ranked_loaded_locked`` reads -- this
        function cannot reach a resident that one could not, because
        neither builds its own. Only the COUNT taken from the front
        differs, which is precisely what the multi-victim rule's third bullet permits ("It
        only permits taking more than one member of it").

        MEMBERSHIP IS NOT SUFFICIENCY. Being in the set does not by itself
        strip a resident's grace: every member is still subject to the outrank precondition
        INDIVIDUALLY, and the caller applies that gate per resident (the
        live-claim precondition and the strictly-higher rank comparison
        below). A resident the claimant does not strictly outrank is in
        this list and still answers False overall -- which is exactly the
        lowest-priority-survival rule's "the lowest-priority client survives only one way" and the
        unconditional-grace rule, both preserved unchanged.
        """
        ordered = self._ranked_loaded_candidates_locked()
        if not ordered:
            return False
        if not self._claimant_unloads_every_sibling_locked(claim_slot):
            # Not the multi-victim rule's premise: single-victim selection, byte-identical to
            # the earlier behaviour this path had.
            return ordered[0] is r
        return any(cand is r for cand in ordered)

    def _is_designated_unload_target_locked(self, r: "Resident") -> bool:
        """Is ``r`` the designated victim RIGHT NOW -- the loaded
        resident with the worst effective rank? The Fast Lane rule is that the
        designated victim is the loaded client with the worst effective
        rank. Pure and read-only: consults the registry, evicts nothing,
        starts no teardown. Call under ``_registry_lock`` (the ``_locked``
        suffix convention this file already uses).

        "THE designated victim" IS NO LONGER ALWAYS ONE
        RESIDENT. Under the multi-victim rule a claimant that does not fit on a single card
        takes "two or more" victims, so more than one resident can be a
        designated victim at the same point in
        time. The first gate below therefore asks
        ``_is_within_unload_target_set_locked`` (membership in the set this claim
        needs) instead of ``_is_worst_ranked_loaded_locked`` (identity with
        the single worst). Everything AFTER that gate is unchanged: the outrank precondition is
        still applied to each member INDIVIDUALLY, so the live-claim
        precondition and the strictly-higher comparison still decide, per
        resident, whether membership actually costs it its grace. The
        "worst effective rank" identity keeps its own name and its own function --
        ``_is_worst_ranked_loaded_locked`` still answers "who is worst",
        byte-identically, and ``_likely_unload_target_model_tag`` still reads it.

        "Loaded" = ``ResidentState`` in ``{ACTIVE, GRACE}`` -- both are meant
        to be still resident and in-play for a pending Fast Lane claim.
        ``ResidentState.GRACE`` has ZERO assignments anywhere in this tree
        today (verified) -- the real grace mechanism is
        tracked per-SLOT (``SlotState.GRACE``), not per-resident. Kept in
        this filter as the documented, structurally-legal target
        (``_RESIDENT_LEGAL_TRANSITIONS``) for whenever resident-level grace
        state lands; today this filter reduces to ``state is ACTIVE`` alone,
        by construction, not by accident of an untested branch.
        ``IDLE_EVICTABLE`` is a different population entirely
        (``_lru_idle_unloadable``'s own LRU/capacity concern, not this one).

        Selection key is ``(tier, rule_index, rank, -last_active_monotonic)``
         with tier 0 = listed / tier 1 = unresolvable, taken worst
         first; ``(rule_index, rank)`` is the pair ``_resident_priority_key``
         returns. An unresolvable ``r``
         (``_resident_priority_key`` is ``None``) is the WORST resident --
         not outside the pool: unregistered clients rank below all
         registered ones, which places it at the bottom of the eviction pool, and
         the Fast Lane rules make unregistered clients the
         eviction pool outright, so it is never excluded from the pool
         and designation matches what eviction picks. The
         ordering stays in lockstep with
         ``_unload_priority_key_for_meta`` (unlisted first / worst, higher
         rule_index next, worse tag rank next, least-recently-active
         breaking ties in both) --
         the drift test's agreement arm
         (``test_designation_and_eviction_name_the_same_resident``) is what
         pins that lockstep for the unlisted cases too.

        RANK IS PART OF THIS ORDERING, AFTER THE CLIENT. Inside one client
        (the same rule_index) the tag rank decides before recency: the worse
        tag goes first, so a resident serving a worse tag is designated before
        a better-tag resident of the same client however recently each was
        used, and the least-recently-active resident only wins between equal
        tags. ``_unload_priority_key_for_meta`` orders its own key the same
        way, ``(tier, -rule_index, -rank, last_active)``, and both read the
        resident's meta through ``_resident_rank_meta``, so the two cannot
        rank one resident by two different turns. A shared resolver
        (``_resolve_fastlane_match``) does not make two orderings agree if one
        of them adds a term the other does not have, which is why the rank slot
        sits in both. The client rank still decides first: a tag rank never
        lifts one client above another. Recency ties break in the SAME
        direction ``_unload_priority_key_for_meta`` already breaks its own
        (the Fast Lane rule is that the victim sort already implements
        the ordering rule -- lowest-priority-first, recency breaking ties only within
        a rank) -- least-recently-active wins. The key is a local composite
        built from ``_resident_priority_key``'s ``(rule_index, rank)`` return.

        THE PRECONDITION. This predicate takes the resident AND asks who is
        claiming, and whether that claimant outranks the resident. A
        predicate that took ONLY the resident and asked "are you the
        worst-ranked loaded resident?" would be unconditionally True with a
        single loaded resident, so the sole resident on the host would be
        designated the victim of any claim at all, INCLUDING a claim from a
        client it outranks. For example, rule_index 0 (the highest-priority
        client) could lose its grace and be evicted for a rule_index 3
        claimant.

        THE RULE AT STAKE IS THE UNCONDITIONAL-GRACE RULE, NOT THE
        SURVIVAL RULE. The survival rule has its own precondition:
        a higher-priority request is queued and the server is at
        capacity, and the lowest-priority loaded client then keeps
        its slot only if certain conditions hold. In the example
        above the claimant is rule_index 3 against a rule_index 0
        resident, so the claimant does NOT outrank it, the outrank
        precondition never engages, and the survival rule is never
        in scope. What would be violated is the
        unconditional-grace rule ALONE: in this state every loaded
        client gets grace, registered or not, and a designated
        victim gets none, so a predicate that made every sole
        resident a victim would strip the grace that rule
        guarantees.

        THE CHECK SITS HERE AND NOT IN THE SELECTOR because the
        victim function is claimant-independent by design: the
        designated victim is the loaded client with the worst
        effective rank, and ``_is_worst_ranked_loaded_locked``
        computes exactly that. A call site must not consume a "who is
        worst" answer as though it were a "should this resident lose
        its grace" answer. The split keeps the identity question
        under its own name, and the outrank-gated question the call
        sites actually need keeps the contract name they already
        probe for.

        The outrank precondition opens with this statement: a HIGHER-PRIORITY
        REQUEST IS WAITING IN THE QUEUE and the server is at capacity, and only from
        that moment are the loaded clients split into two classes. No live claim =>
        no split => no designated victim => normal grace. A live claim that does NOT
        strictly outrank the candidate is likewise not a trigger for that
        precondition.

        Comparison is on the full ``(rule_index, rank)`` keys of the claim and
        of the resident: rule_index decides first, so the tag rank is only
        compared between a claim and a resident of the SAME client (a better
        tag's claim outranks a worse-tag resident of that client, never the
        other way round, and never lifts one client above another). It reuses
        ``queue._fastlane_strictly_higher``, the comparator the queue already
        owns, rather than writing a second one that could disagree with it;
        note that comparator treats an EQUAL key as NOT strictly higher, which
        is the behaviour the outrank precondition needs -- an equal-ranked claimant does not bump an
        equal-ranked resident. Being designated does not cut a running turn:
        the resident is unloaded only at its own turn boundary.
        """
        # The claim is resolved FIRST because set MEMBERSHIP now
        # depends on what the claimant is (layer-split => every sibling must
        # go), not only on who is worst. Pure reordering of a
        # conjunction of two read-only predicates -- both orders return the
        # same answer for every input, and no-live-claim still short-circuits
        # before any selection work happens.
        governing = self._governing_claim_locked(include_parked=False)
        if governing is None:
            return False
        claim_key, claim_slot = governing
        if not self._is_within_unload_target_set_locked(r, claim_slot):
            return False
        table = self._fastlane_table()
        victim_key = self._resident_priority_key(r, table)
        if victim_key is None:
            # UNLISTED/UNRESOLVABLE:
            # the tier-aware selector above has already named ``r`` the
            # machine's worst, and the gate two lines above guarantees a
            # live LISTED claim exists -- and every listed claim strictly
            # outranks an unlisted resident (unregistered
            # clients rank below all registered ones). The outrank precondition
            # is met: the unlisted machine-worst IS the designated
            # victim. Returning False here would read "rank below all registered"
            # backwards -- it means worst in the
            # eviction pool, not outside it. The claimant-side
            # ``claimant_key is not None`` guard in the widening of
            # ``_fastlane_outrank_unload_target_locked`` is a different
            # question (the CLAIMANT's standing) and is untouched.
            return True
        # Full (rule_index, rank) keys: rule_index decides first, so rank is
        # only ever compared between a claim and a resident of one client.
        return self.queue._fastlane_strictly_higher(claim_key, victim_key)

    def _likely_unload_target_model_tag(self) -> "str | None":
        """The ``likely_victim`` value for every row of
        ``queue.waiting[]`` -- the ``model_tag`` of whichever loaded
        resident ``_is_worst_ranked_loaded_locked`` currently resolves as
        the worst, or ``None`` if none does.

        WHY THIS READS THE SELECTOR AND NOT THE
        CLAIM-GATED PREDICATE, deliberately. When the two were one function
        this called ``_is_designated_unload_target_locked``; the split made the
        choice explicit and it is the selector, on the Fast Lane rule that
        the likely-victim field is DISPLAY-ONLY:
        the eviction decision is always the fresh under-lock evaluation
        (the compute-fresh rule), never the displayed name.

        The outrank precondition (a live claim that strictly outranks) governs
        GRACE and TEARDOWN. This field causes neither. Gating it would change
        no behaviour and would blank the dashboard whenever no claim happens
        to be registered -- removing the answer to "why did my model get
        unloaded?", which is the whole reason the field
        exists. This docstring's own first sentence already asked for "the
        WORST", which is the selector's question, not designation's.

        The reverse mistake is the dangerous one and is guarded by a test:
        a BEHAVIOURAL site (grace skip, victim requeue-to-tail) must never
        read this selector, because that is exactly the mistake that would evict
        rule_index 0 for a rule_index 3 claimant. A single, snapshot-wide answer
        (only one resident can be the current worst loaded one at a time),
        not a per-row computation.

        Calls the existing predicate once per candidate resident rather
        than reimplementing its ``(rule_index, rank, -last_active_monotonic)``
        selection here a second time. Computed FRESH on every call, never
        cached anywhere -- the binding constraint this exists
        under: a likely_victim that is CACHED is a stale
        snapshot with a friendly name -- the exact defect that
        computing it fresh under the lock exists to prevent.

        Sync, no literal ``_registry_lock`` acquisition: ``status_snapshot``
        (this method's only caller) is itself a sync ``def`` with no
        ``await`` anywhere in its call chain, so single-threaded asyncio
        already makes this atomic -- the SAME "await-free, so no
        interleaving is possible" contract ``depth()`` (queue.py) and
        ``_residents_snapshot``/``fastlane_claims_snapshot`` (this file)
        already rely on for the identical class of read-only /status
        assembly, not a new exception invented here.
        """
        for r in self._model_residents():
            if self._is_worst_ranked_loaded_locked(r):
                return r.model_tag
        return None

    def _log_make_room_unload(self, victim: "Resident", reason: str) -> None:
        """INFO observability for the two MAKE-ROOM eviction call
        sites in ``_route_or_reserve`` -- additive only, touches nothing
        inside ``_begin_unload_locked`` (the shared teardown fn all five of
        its callers use, per its own docstring "LRU-evict (or driver-death
        reap)") or any other ranking or admission logic. The lines belong HERE, at
        the call sites, precisely because instrumenting inside the shared
        function would reproduce the exact ambiguity this change removes.

        SYNCHRONOUS BY REQUIREMENT: both call sites are inside
        ``async with self._registry_lock:`` -- no ``await``
        anywhere in this function. Same class of hazard the
        ``_priority_admit_from_inbox`` docstring names for the identical
        reason: a suspension point here would change the routing hot
        path's locking semantics. Never touches ``queue._lock`` (an
        ``asyncio.Lock``, every use ``async with`` -- that path requires
        an await and is closed to this call site entirely.

        Calls ``self._fastlane_table()`` directly, synchronously -- the
        SAME live, cached, sync call that
        ``_resident_unload_priority_key`` already makes from inside this
        identical lock (via ``_lru_idle_unloadable``), so this reuses an
        already-safe pattern rather than inventing a new
        one. Unlike the listed-waiter snapshot (resolved via
        ``await self.queue.listed_waiter_model_tags()`` BEFORE this lock is
        entered, because that resolution needs ``queue._lock``),
        ``_fastlane_table()`` has no such constraint -- it never awaits,
        and the existing call site already proves it is cheap to call live
        here; no new precomputed parameter is needed.

        INFO, not WARNING: a normal, expected event an operator needs to
        see, not an alarm (unlike the staleness-grant-refusal line, which
        IS a refusal). ``reason`` is named per call site so an ABSENT line
        is never ambiguous about which make-room path it would have been.
        An unresolvable Fast Lane identity is stated explicitly as
        "unresolvable", never omitted -- a missing field and an
        unresolvable one must never look identical to a log reader.

        FIELD ORDER IS A CONTRACT: ``reason=`` ``model_tag=``
        ``fastlane_client=`` ``rule_index=`` keep their text and order, and
        ``rank=`` is appended LAST. ``rank=`` is the victim's tag rank inside
        its client as the unload decision read it: resolved from
        ``_resident_rank_meta(victim)`` (the identity of the resident's latest
        turn), the same reader the designation, the outrank gate, the victim
        pool and the eviction key use. ``fastlane_client=`` and
        ``rule_index=`` still come from ``idle_client_meta``, so when the two
        identities differ, or only one of them resolves, ``rank=`` and
        ``rule_index=`` can disagree about resolvability. ``rank=unresolvable``
        means the resident has no identity the lookup can resolve.
        """
        table = self._fastlane_table()
        meta = victim.idle_client_meta
        match = match_fastlane(table, (meta or {}).get("ip"), meta) if meta else None
        client = match.raw_address if match is not None else "unresolvable"
        rule_index = match.rule_index if match is not None else "unresolvable"
        rank_match = _resolve_fastlane_match(self._resident_rank_meta(victim), table)
        rank = rank_match.rank if rank_match is not None else "unresolvable"
        log.info(
            "MAKE_ROOM_EVICTION reason=%s model_tag=%s fastlane_client=%s rule_index=%s rank=%s",
            reason, victim.model_tag, client, rule_index, rank,
        )

    def _starvation_reason(
        self,
        *,
        main_gpu: "int | None" = None,
        split_mode: "str | None" = None,
    ) -> "dict[str, object]":
        """Full candidate-set attribution for a make-room MISS
        (``_lru_idle_unloadable`` returned None): which of the five filter
        clauses excluded EACH live resident, not just the single
        listed-waiter hypothesis, which would collapse everything
        else into one value.

        A poller sampling resident state cannot see this: how long a
        resident is OBSERVABLE as IDLE_EVICTABLE depends on inbox
        occupancy, not priority, so a state lasting milliseconds can have
        an expected sample-hit count near zero even if it occurs on every
        turn. ``_lru_idle_unloadable`` runs AT the exact instant the
        candidate set is evaluated -- already inside the window -- so this
        is the only instrument that can answer "why was nothing eligible."

        Returns a dict:
          ``why``           -- PRESERVED, UNCHANGED VALUES (a
                               frozen contract). Both string values
                               this field can take are retained
                               unchanged, byte for byte; the field's
                               meaning and computation stay as
                               described below. It names a single
                               hypothesis for a miss, and "reason_unknown" is
                               the value it takes whenever that
                               hypothesis does not apply (for
                               example, when the real cause is more
                               specific than that hypothesis), so
                               this value alone can under-explain --
                               ``per_resident`` below is the actual fix
                               for "a diagnostic that has the data and
                               cannot name the cause," not a change to
                               this field. Computed as follows:
                               a SECOND, read-only call to
                               ``_lru_idle_unloadable`` with the same
                               inputs -- the "all candidates protected as
                               listed waiters" arm is UNREACHABLE: that shield no longer
                               exists (it was the clause the probe existed to
                               differentiate; see the dead-code
                               marker at the call site); "reason_unknown"
                               is otherwise the only value this field can take.
                               With the all-cards scope it can be produced
                               again (a request whose decided card has no
                               idle victim while another card has one); the
                               caller normalises it to "reason_unknown"
                               before it is logged.
          ``residents``     -- live resident count at this instant.
          ``eligible``      -- residents excluded by NONE of the six
                               clauses below. Computed INDEPENDENTLY (a
                               count of survivors), never derived by
                               subtracting the six clause counts from
                               ``residents`` -- a resident excluded on
                               TWO grounds would be double-subtracted,
                               producing a wrong (possibly negative)
                               ``eligible`` on exactly the interesting
                               case. 0 if and only if
                               ``_lru_idle_unloadable`` returns None for
                               these same inputs -- see the drift-
                               detection test, which proves this
                               directly rather than assuming it.
          ``state_not_idle``, ``active_slot``, ``inflight``,
          ``staleness_protected``, ``card_split`` --
                               per-clause exclusion counts. A resident
                               excluded by MULTIPLE clauses is tallied in
                               EVERY matching clause, not just the first,
                               so the counts show the full picture rather
                               than an arbitrary first-match attribution.
                               ``inflight`` is structurally inert at
                               ``parallel==1`` (only
                               ``_fan_out_on_resident`` under
                               ``parallel>1`` populates it) -- reported
                               anyway for completeness.
          ``per_resident``  -- the per-resident diagnostic. One flat,
                               comma-joined entry per live resident, same
                               order as ``_model_residents()``:
                               ``"<model_tag>:<clause>+<clause>..."`` or
                               ``"<model_tag>:eligible"`` if none excluded.
                               Clause names reuse the six keys above so they
                               correlate directly against the totals. Two
                               residents sharing one ``model_tag`` (possible
                               under multi-instance routing) appear as two
                               separate entries with that same tag --
                               attribution is per RESIDENT, not per tag.
                               Additive and flat (no nested/quoted
                               sub-string) so it flows through
                               ``_log_make_room_starved``'s existing
                               generic field join unchanged.

        ``why`` IS DELIBERATELY LEFT AS-IS, INCLUDING ITS OWN
        ``"reason_unknown"`` DEGENERATE CASE (see the
        description of ``why`` in the paragraph
        above): the frozen-byte-for-byte contract wins. ``per_resident`` --
        not a change to ``why`` -- is what actually resolves "a diagnostic
        that has the data and cannot name the cause": it names the cause
        per resident even when ``why`` itself still reads
        ``"reason_unknown"``.

        DESIGN CHOICE (the tension named explicitly): this MIRRORS
        ``_lru_idle_unloadable``'s own filter clause-by-clause rather than
        restructuring that function to share one source with this one.
        ``_lru_idle_unloadable`` carries several established behaviours and a third
        feature depends on its exact current shape -- a behavior-preserving
        refactor is still an edit to established logic. The drift-detection
        test delivers the same safety property structurally: if this
        mirror and the real filter ever disagree, that test fails
        immediately rather than this line silently mis-explaining a miss.

        Cheap: one pass over ``_model_residents()`` (the same snapshot
        ``_lru_idle_unloadable`` itself scans), calling only
        ``_fastlane_staleness_protects`` (a pure predicate, verified) per
        resident -- same cost class as the decision this instruments, no
        new expensive work. Runs only on the MISS path, under the same
        ``_registry_lock`` as the real decision, so nothing can mutate
        ``_residents`` between the two `_lru_idle_unloadable` calls or the
        attribution pass -- deterministic, not a race.
        """
        if self._lru_idle_unloadable(main_gpu=main_gpu, split_mode=split_mode) is not None:
            # ★ UNREACHABLE for its original cause (the listed-waiter
            # shield no longer exists), so this branch is dead
            # code. It is kept in place, marked as dead, as the
            # legacy path rather than deleted, because it may
            # be useful in the future. (With the all-cards scope
            # it can still be taken for a different reason; see
            # the end of this comment.)
            # WHY unreachable: the probe now runs
            # _lru_idle_unloadable with the SAME inputs as the real call
            # that returned None above -- the listed-waiter shield (the
            # clause the probe existed to differentiate) was
            # removed under the rule that a client with
            # queued work that has not started is not protected by that
            # queue; it is protected by its rank, its grace window, its
            # cooldown -- and by nothing else. NOT MAINTAINED -- the
            # value "all candidates protected as listed waiters" is dead;
            # do not add new readers of it. WHAT REPLACED IT: nothing --
            # "reason_unknown" is now the only miss attribution; the
            # protection this value named no longer exists. With the
            # all-cards scope this branch can be taken again (a request whose
            # decided card has no idle victim while another card has one); the
            # caller normalises the value to "reason_unknown" before it is
            # logged.
            why = "all candidates protected as listed waiters"
        else:
            why = "reason_unknown"

        residents = self._model_residents()
        state_not_idle = active_slot = inflight = 0
        staleness_protected = card_split = 0
        stage1_survivors: "list[Resident]" = []
        # Per-resident clause set, built INSIDE this same pass (no new
        # loop, no new cost class) so `per_resident` below can name WHICH resident
        # hit WHICH clause instead of only the six anonymous totals -- two
        # residents excluded on different grounds yield byte-identical
        # totals, which would make "was it the shield or the state?" unanswerable. Parallel
        # list, indexed like `residents`; `survivor_indices` lets the card_split
        # second pass (below) update the right resident's own clause list in O(1)
        # rather than re-scanning for identity.
        per_resident_clauses: "list[list[str]]" = []
        survivor_indices: "list[int]" = []
        for idx, r in enumerate(residents):
            excluded = False
            clauses: "list[str]" = []
            if r.state is not ResidentState.IDLE_EVICTABLE:
                state_not_idle += 1
                excluded = True
                clauses.append("state_not_idle")
            if r.active_slot is not None:
                active_slot += 1
                excluded = True
                clauses.append("active_slot")
            if r.inflight:
                inflight += 1
                excluded = True
                clauses.append("inflight")
            if self._fastlane_staleness_protects(r):
                staleness_protected += 1
                excluded = True
                clauses.append("staleness_protected")
            if not excluded:
                stage1_survivors.append(r)
                survivor_indices.append(idx)
            per_resident_clauses.append(clauses)
        if main_gpu is not None and (split_mode or "none").lower() == "none":
            for r, idx in zip(stage1_survivors, survivor_indices):
                if not (
                    (r.split_mode or "layer").lower() != "none"
                    or r.main_gpu == main_gpu
                ):
                    card_split += 1
                    per_resident_clauses[idx].append("card_split")
        # Mirror the designated-victim fallback in _lru_idle_unloadable so
        # per_resident and eligible stay in lockstep with the real decision.
        # Same guard: only a resident whose grace was entered and has ended
        # (not in_grace_loop) and that is not running a turn. A state_not_idle
        # designated victim reaching this point is a make-room candidate, so
        # its clause list drops the state_not_idle exclusion.
        if not stage1_survivors:
            for idx, r in enumerate(residents):
                if idx in survivor_indices:
                    continue
                if r.state is not ResidentState.ACTIVE:
                    continue
                if r.grace is None or r.grace._started_at is None or r.in_grace_loop:
                    continue
                if self._resident_has_running_turn(r):
                    continue
                if not self._is_designated_unload_target_locked(r):
                    continue
                if self._fastlane_staleness_protects(r):
                    continue
                if (
                    main_gpu is not None
                    and (split_mode or "none").lower() == "none"
                    and (r.split_mode or "layer").lower() == "none"
                    and r.main_gpu != main_gpu
                ):
                    continue
                stage1_survivors.append(r)
                survivor_indices.append(idx)
                per_resident_clauses[idx] = [
                    c for c in per_resident_clauses[idx]
                    if c != "state_not_idle"
                ]
                break
        eligible = len(stage1_survivors) - card_split

        # Additive, flat (comma-joined, no nested/quoted sub-string) so
        # it flows through _log_make_room_starved's existing generic
        # `f"{k}={v}"` join with ZERO changes to that function -- one entry per
        # resident, "<model_tag>:<clause>+<clause>..." or "<model_tag>:eligible"
        # if none excluded. `why` (above) is UNCHANGED -- its two literal values
        # and its computation stay exactly as they are, frozen (the two
        # values are retained unchanged -- see `why`'s own docstring
        # above);
        # this field is the actual fix for "a diagnostic that has the data and
        # cannot name the cause," not `why`.
        per_resident = ",".join(
            f"{r.model_tag}:{'+'.join(clauses) if clauses else 'eligible'}"
            for r, clauses in zip(residents, per_resident_clauses)
        )

        return {
            "why": why,
            "residents": len(residents),
            "eligible": eligible,
            "state_not_idle": state_not_idle,
            "active_slot": active_slot,
            "inflight": inflight,
            "staleness_protected": staleness_protected,
            "card_split": card_split,
            "per_resident": per_resident,
        }

    def _log_make_room_starved(
        self, slot: "Slot", reason: str, attribution: "dict[str, object]",
    ) -> None:
        """INFO observability for a make-room MISS: ``_lru_idle_unloadable``
        found no eligible victim, so the incoming request is deferred
        instead of evicting anything. Additive, at the two ``victim is
        None`` branches in ``_route_or_reserve`` -- same synchronous, no-
        ``await`` discipline as ``_log_make_room_unload`` (both run
        under ``_registry_lock``), same reason-naming discipline (an
        absent line must never be ambiguous about which starvation path
        it would have been).

        Carries the INCOMING SLOT's identity (``model_tag`` + resolved
        Fast Lane client + ``rule_index`` + ``rank``), never a victim's -- there is
        no victim in the starvation case, so attributing eviction-side
        fields here would be a fabrication, not an observation. Same
        unresolvable-states-explicitly discipline as the eviction line.

        FIELD ORDER IS A CONTRACT, NOT COSMETIC: ``reason=`` ``why=``
        ``model_tag=`` ``fastlane_client=`` ``rule_index=`` in that exact
        order, with ``why='s`` two string values UNCHANGED (a frozen
        contract: the values are retained exactly
        as they are, byte
        for byte, and the field is
        documented in ``_starvation_reason``
        above). The new per-clause
        attribution from ``_starvation_reason`` is APPENDED after
        ``rule_index=``, fully flat (no nested/quoted sub-string), so it
        is independently greppable per field without disturbing the
        existing contract.

        ``rank=<n>`` is appended LAST, after every field above and after
        ``traffic_class=``: the incoming slot's tag rank inside its client,
        from the same Fast Lane match that yields ``rule_index=``
        (``rank=unresolvable`` exactly where ``rule_index=`` is). The
        fields before it keep their text and order.

        INFO, not WARNING: this is one EVENT line, not an alarm on a
        persistent CONDITION -- that alarm is the multi-victim rule's tripwire, which is a
        separate mechanism. Duplicating it here would be
        two mechanisms doing one job.

        Logging only, no behaviour change:
        it APPENDS two more groups after the ``_starvation_reason``
        block above, so the two field groups can be told apart without
        disturbing either one's own internal order:
          - per-card ``gpu{N}_util_pct=`` ``gpu{N}_vram_used_mib=``
            ``gpu{N}_vram_total_mib=``, N in probe index order, read ONLY
            from ``self._gpu_util_pct`` / ``_vram_free_mib`` / ``_vram_total_mib``
            -- the SAME off-loop ~1Hz cache ``status_snapshot`` already
            depends on (live_monitor.py's pollers). Never a live nvidia-smi
            call here: this line fires from inside the ``_registry_lock``
            critical section (_route_or_reserve), same discipline the
            class's own contract already states for the eviction line.
            A cache entry that is None (probe never succeeded, or this
            card index has no reading) prints ``unavailable`` rather than
            being silently omitted -- an absent field and a
            probe-never-ran field must stay distinguishable by a reader.
            If ALL THREE caches are None (no card count is known at all --
            e.g. before the first poller tick), there is nothing to index
            by card, so a single ``gpu_telemetry=unavailable`` sentinel is
            emitted instead of an empty per-card loop.
          - ``traffic_class=registered|unregistered`` -- NOT a new lookup:
            derived from ``match`` (computed above for ``fastlane_client=``
            / ``rule_index=``) being non-None. Existed as information on
            this line already, just not surfaced as its own field.
        Motivation: two starvation episodes that read
        IDENTICALLY on this line can have different causes (a genuine defect or a
        genuinely saturated host); GPU telemetry (as nvidia-smi reports it)
        tells them apart, which the line alone could not
        show. The starvation-observability test covers this field and checks
        that the value can print both readings,
        not only one.
        """
        table = self._fastlane_table()
        meta = slot.client_meta
        match = match_fastlane(table, (meta or {}).get("ip"), meta) if meta else None
        client = match.raw_address if match is not None else "unresolvable"
        rule_index = match.rule_index if match is not None else "unresolvable"
        rank = match.rank if match is not None else "unresolvable"
        appended = " ".join(
            f"{k}={v}" for k, v in attribution.items() if k != "why"
        )
        traffic_class = "registered" if match is not None else "unregistered"
        # getattr(..., None), never a bare attribute read: the same pattern
        # used elsewhere in this file -- a __new__-built test
        # harness manager (bypasses __init__ entirely) may legitimately not
        # have these attributes at all, not merely have them set to None.
        util = getattr(self, "_gpu_util_pct", None)
        free = getattr(self, "_vram_free_mib", None)
        total = getattr(self, "_vram_total_mib", None)
        n_cards = max(len(util or []), len(free or []), len(total or []))
        if n_cards == 0:
            # All three caches are None (probe never succeeded / not yet run)
            # -- there is no card COUNT to loop over, but the field must still
            # be PRESENT and say so: an absent field and a probe-never-ran
            # field must stay distinguishable (see docstring above).
            telemetry_fields = "gpu_telemetry=unavailable"
        else:
            card_fields = []
            for i in range(n_cards):
                u = util[i] if util is not None and i < len(util) else None
                f = free[i] if free is not None and i < len(free) else None
                t = total[i] if total is not None and i < len(total) else None
                used = (t - f) if (t is not None and f is not None) else None
                card_fields.append(f"gpu{i}_util_pct={u if u is not None else 'unavailable'}")
                card_fields.append(
                    f"gpu{i}_vram_used_mib={used if used is not None else 'unavailable'}"
                )
                card_fields.append(
                    f"gpu{i}_vram_total_mib={t if t is not None else 'unavailable'}"
                )
            telemetry_fields = " ".join(card_fields)
        log.info(
            "MAKE_ROOM_STARVED reason=%s why=%s model_tag=%s fastlane_client=%s "
            "rule_index=%s %s %s traffic_class=%s rank=%s",
            reason, attribution["why"], slot.model_tag, client, rule_index, appended,
            telemetry_fields, traffic_class, rank,
        )

    def _spawn_bg(self, coro) -> "asyncio.Task":
        """Fire-and-forget a load-bearing background coroutine while holding a STRONG
        reference (N2). asyncio keeps only a weak ref to a bare ``create_task``
        result, so an unreferenced teardown/requeue/reap task can be GC-cancelled
        mid-flight. The task is parked in ``self._bg_tasks`` and self-removes on
        completion."""
        task = asyncio.create_task(coro)
        self._bg_tasks.add(task)
        task.add_done_callback(self._bg_tasks.discard)
        return task

    def _register_card_release_task(self, card: int, task: "asyncio.Task") -> None:
        """Track the TASK OBJECT that owns a future
        decrement of ``_pending_reclaim_mib[card]`` -- one of
        ``_unload_teardown`` or ``_late_vram_reconcile``, called at the
        exact spawn site with no intervening ``await`` between crediting the
        counter and this registration, so there is never a window where a
        card has credit with no task claiming it.

        A per-card COUNTER (bumped on spawn, dropped in the SAME finally
        that drops the credit) was considered and rejected: the credit's own
        bug is that a task can die/be cancelled BEFORE that finally's
        decrement runs -- a counter dropped in that identical finally would
        be orphaned by the EXACT SAME event, reading "still in flight"
        forever and making the reconciler that depends on it dead on
        arrival. A task's ``.done()`` state is observable EVEN WHEN its
        ``finally`` never reached the decrement -- that asymmetry (not a
        counter, a task reference) is what actually discriminates "still
        working" from "died owing us a decrement". Mirrors ``_bg_tasks``'
        own strong-ref discipline, keyed per-card.
        """
        self._card_release_tasks.setdefault(card, set()).add(task)
        task.add_done_callback(
            lambda t, c=card: self._card_release_tasks.get(c, set()).discard(t)
        )

    def _max_vram_defers(self) -> int:
        """UNCALLED as of v0.8.0 (legacy code: nothing in the current dispatch path calls it).
        Retained, not deleted, deliberately: dead code is kept in place and marked
        as such in the comments, because it is the legacy path and may be
        useful again later; keeping it costs nothing, and removing it would
        lose the history of how the old exhaustion refusal worked.
        WHY unreachable: its only caller,
        `_defer_unroutable`'s exhaustion branch, was removed --
        once a request is queued it stays queued; it is only dropped when
        the client explicitly cancels it. NOT MAINTAINED --
        nothing consults this return value any more; verify it before
        reattaching a caller. WHAT REPLACED IT: nothing -- there is no cap
        any more (see `_defer_unroutable`'s own docstring and
        `_legacy_defer_exhaustion_refusal`, both manager.py).

        Evict-pending defer budget SIZED so a slot queued behind a
        grace-holding blocker survives a full grace cycle + teardown before it
        503s. window = grace_seconds*(1+max_grace_extensions) + teardown margin;
        defers = ceil(window / backoff), clamped [floor, ceiling]."""
        q = self.runtime.queue
        grace_cycle_s = q.grace_seconds * (1 + q.max_grace_extensions)
        window_s = grace_cycle_s + _VRAM_DEFER_TEARDOWN_MARGIN_S
        n = int(window_s // _VRAM_DEFER_BACKOFF_S)
        if window_s % _VRAM_DEFER_BACKOFF_S:
            n += 1  # ceil without importing math
        return max(_VRAM_DEFER_MIN_DEFERS, min(n, _VRAM_DEFER_MAX_DEFERS))

    def _max_busy_defers(self) -> int:
        """UNCALLED as of v0.8.0 (legacy code: nothing in the current dispatch path calls it).
        Retained, not deleted, deliberately: dead code is kept in place and marked
        as such in the comments, because it is the legacy path and may be
        useful again later; keeping it costs nothing, and removing it would
        lose the history of how the old exhaustion refusal worked.
        WHY unreachable: its only caller,
        `_defer_unroutable`'s exhaustion branch, was removed --
        once a request is queued it stays queued; it is only dropped when
        the client explicitly cancels it. NOT MAINTAINED --
        nothing consults this return value any more; verify it before
        reattaching a caller. WHAT REPLACED IT: nothing -- there is no cap
        any more (see `_defer_unroutable`'s own docstring and
        `_legacy_defer_exhaustion_refusal`, both manager.py).

        The busy regime (all residents busy, no idle victim
        to evict — the model FITS, it's just not this moment's turn) reused to
        get only 50 defers x 50ms = 2.5s before refusing, while the HARDER
        evict-pending regime (real VRAM over-commit) gets 60s-30min via
        _max_vram_defers' grace-cycle-derived window. The principle here is
        that the easier case must not get LESS patience than the harder one.

        Reuses _max_vram_defers' WINDOW (grace_cycle_s + teardown margin, clamped
        to the SAME 60s..1800s promise via _VRAM_DEFER_MIN/MAX_DEFERS *
        _VRAM_DEFER_BACKOFF_S) — not its raw defer COUNT. That distinction is
        load-bearing, not cosmetic: reusing the count (60) at busy's OWN faster
        0.05s backoff buys only ~3 seconds (60 x 0.05s), barely better than
        today's bug; reusing the WINDOW and re-deriving the count at busy's own
        backoff buys the intended ~60s+ of real wall-clock parity. Same source
        number, opposite outcome, depending on which unit is reused.

        Caveat: the window's own physical basis (grace
        cycle + teardown margin) is about EVICTION timing, not about how long a
        resident might stay busy serving a live generation — those are
        different physical quantities with no better-justified shared number in
        this codebase today. This is a defensible FLOOR by symmetry with the
        stated principle above, not a claim that grace-cycle math governs
        generation length. A busy-specific derivation (e.g. from measured
        generation-length telemetry) would be a separately-scoped follow-up.

        Client-boundedness (also considered)
        needs NO new code here: _dispatch_loop already calls
        queue.pop_next(...) -> is_evicted -> _handle_unloaded_slot on EVERY pop,
        including the re-pop that follows each _requeue_after_backoff cycle —
        so a slot whose caller disconnects mid-busy-wait is already intercepted
        and failed (SlotEvictedError -> 499) well before this larger budget
        would ever matter, at the busy backoff's own ~50ms cadence. Verified by
        reading queue.py's _pop_first_non_unloaded_from / _pop_first_matching_
        non_evicted_from, both of which flag is_evicted on the disconnect_event
        check for the slot ACTUALLY being popped, every single pop.
        """
        q = self.runtime.queue
        grace_cycle_s = q.grace_seconds * (1 + q.max_grace_extensions)
        window_s = grace_cycle_s + _VRAM_DEFER_TEARDOWN_MARGIN_S
        window_s = max(
            _VRAM_DEFER_MIN_DEFERS * _VRAM_DEFER_BACKOFF_S,
            min(window_s, _VRAM_DEFER_MAX_DEFERS * _VRAM_DEFER_BACKOFF_S),
        )
        n = int(window_s // _DISPATCH_DEFER_BACKOFF_S)
        if window_s % _DISPATCH_DEFER_BACKOFF_S:
            n += 1  # ceil without importing math
        return n

    # === Fast Lane claim registry ============================
    # Security requirements for claims (redaction, eligibility, dedup, audit). A "claim" is a
    # standing record that a Fast-Lane-eligible slot is currently stuck in the
    # _defer_unroutable retry loop waiting for eviction capacity -- registered
    # on each genuine defer, released the moment the slot is admitted or
    # leaves the system. See fastlane_claims_snapshot's docstring for the one
    # sub-check of the liveness rule NOT implemented in this change (a known
    # gap).

    def _fastlane_claim_eligible(self, slot: "Slot") -> bool:
        """Claim eligibility invariant. A claim is
        registered only when ``slot.fastlane is not None`` -- the match
        stamped ONCE at submit time (``match_fastlane``, before enqueue),
        NEVER re-derived from ``client_meta`` here. The single exception is
        a ``floor_promoted`` slot (the one-turn fairness
        floor for unregistered traffic).

        Checked independently of (never inferred from) ``_fastlane_claim_
        key``'s own None-return for the same case -- belt-and-suspenders:
        a future change to either function alone cannot silently widen
        eligibility without this gate still catching it.

        ``floor_promoted`` is a real dataclass member with a
        default: ``slot.py`` declares ``floor_promoted: bool =
        False``, and it is set where the one-turn wall-clock
        fairness floor serves a slot. Read it directly; it is
        not optional.

        Note: the ``getattr(..., False)`` below is a redundant
        defensive default. It is left in place deliberately:
        changing working code for style alone buys nothing and
        risks something. It is not a pattern to copy, because
        it suggests that the field is optional, and a reader who
        sees it tends to write a matching ``getattr`` of their
        own, which spreads the wrong belief that the field
        might be absent.

        In effect the check is two plain attribute reads on the
        slot: ``slot.fastlane is not None``, or else
        ``slot.floor_promoted``. Both attributes always exist.
        No defensive lookup is needed for either of them.
        """
        if slot.fastlane is not None:
            return True
        return bool(getattr(slot, "floor_promoted", False))

    def _fastlane_claim_key(self, slot: "Slot") -> "tuple[str, str] | None":
        """Dedup key: one live claim per (fastlane_rule,
        model_tag) -- NOT slot_id, so a second request or MISS for the same
        client+model adds no claim: it joins the existing one as a waiter, and
        the claim always points at the best still-waiting request of that
        client+model: the better client rank first, then the better tag rank,
        ties to the earlier arrival (see ``_register_fastlane_claim_locked``).
        The claim's registered_at keeps its original value, so waited_s keeps
        growing rather than resetting on every backoff tick. A ``floor_promoted`` slot (see
        ``_fastlane_claim_eligible``) has no fastlane rule to key by;
        keyed on its own slot_id instead so it can never collide with, or
        be silently absorbed into, a real rule's claim. ``None`` when the
        slot is not eligible at all. A request parked in an inbox holds a claim
        of its own, keyed by its slot id, when the shared claim points at
        another request or when a strictly better request of the same client
        takes over the shared key (see ``_park_fastlane_claim_locked`` and
        ``_register_fastlane_claim_locked``); that key wins while it is
        registered."""
        if slot.fastlane is not None:
            own = (f"parked:{slot.slot_id}", slot.model_tag)
            if own in self._fastlane_claims:
                return own
            return (slot.fastlane.raw_address, slot.model_tag)
        if getattr(slot, "floor_promoted", False):
            return (f"floor:{slot.slot_id}", slot.model_tag)
        return None

    def _fastlane_claim_sort_key(self, slot: "Slot") -> "tuple[int, int, int]":
        """Worst-first ordering for ``_CLAIMS_MAX`` overflow eviction:
        it reuses ``self.queue._fastlane_priority_key`` -- the ONE
        existing source of Fast Lane REQUEST-priority ordering (queue.py)
        -- rather than inventing a second one. That function returns
        ``None`` for an unlisted/floor slot; per ``_fastlane_strictly_
        higher``'s own established convention (``None`` is never strictly
        higher than a real tuple -- i.e. ``None`` IS the worst possible
        priority), a ``None`` key sorts into tier 1 (worse than every real
        match, tier 0); within tier 0 a numerically larger ``(rule_index,
        rank)`` is already a worse priority, so it composes directly.
        ``max()`` over this key picks the single worst claim.
        """
        key = self.queue._fastlane_priority_key(slot)
        if key is None:
            return (1, 0, 0)
        return (0, key[0], key[1])

    async def _emit_fastlane_claim_event(
        self, slot: "Slot", event_type: str, *, reason: "str | None" = None,
    ) -> None:
        """Audit (off-thread, via ``_audit_event_only_
        async``) + bus publish, BOTH off the lock -- callers ``_spawn_bg``
        this from inside a ``_registry_lock`` section, never await it
        there directly. ``_audit_event_only`` alone does NOT publish
        (a known gap) -- this helper
        closes that gap for these four events specifically; it does not
        fix the general gap.

        Redacted payload only -- ``thread_id_prefix``
        (``(slot.thread_id or "")[:8]``), never a full ``thread_id`` or
        any ``client_meta`` key; ``fastlane`` is a small explicit dict
        (rule_index/rank/label/fastlane_rule, label resolved LIVE via
        ``_live_fastlane_label``) or ``None``, never the ``FastLaneMatch``
        object itself.
        """
        fl = slot.fastlane
        fastlane_payload = (
            {
                "rule_index": fl.rule_index,
                "rank": fl.rank,
                "label": self._live_fastlane_label(fl.raw_address),
                "fastlane_rule": fl.raw_address,
            }
            if fl is not None
            else None
        )
        payload = {"fastlane": fastlane_payload}
        if reason is not None:
            payload["reason"] = reason
        # The audit write and the bus publish are two
        # unrelated destinations, and these events must be
        # registered *and* verified observable on the surface they're read
        # from. Before this, they were sequential with no guard, so a raising
        # audit write took the publish down with it and the event vanished
        # from the bus entirely -- the failure mode of events that go to the
        # audit table only and never reach the bus, one level down: the
        # publish itself is lost rather than never attempted.
        #
        # CancelledError is re-raised FIRST and deliberately: cancellation
        # means the caller is going away, not that the audit failed, and a
        # blanket swallow here would make this helper uncancellable.
        # The audit failure is LOGGED, never swallowed silently -- trading a
        # lost event for a lost error is not a fix.
        # The off-lock property the docstring above requires is untouched:
        # nothing here acquires a lock.
        #
        # ⚠ KNOWN LIMITATION: a HANGING audit write
        # still delays the publish. That needs a timeout VALUE, which is a
        # config decision rather than a shape choice, and this helper is
        # always _spawn_bg'd -- so a hang parks a background task rather than
        # wedging the manager.
        try:
            await self._audit_event_only_async(slot.slot_id, event_type, payload)
        except asyncio.CancelledError:
            raise
        except Exception:
            log.exception(
                "FASTLANE_CLAIM audit write FAILED for event=%s slot_id=%s -- "
                "publishing to the bus anyway (an event's observability "
                "must not depend on an unrelated database write)",
                event_type, slot.slot_id,
            )
        self.event_bus.publish_nowait({
            "event": event_type,
            "slot_id": slot.slot_id,
            "model_tag": slot.model_tag,
            "thread_id_prefix": (slot.thread_id or "")[:8],
            "fastlane": fastlane_payload,
            **({"reason": reason} if reason is not None else {}),
        })

    async def _register_staged_claim(self, slot: "Slot", reason: str) -> None:
        """Async wrapper around
        ``_register_fastlane_claim_locked`` that acquires ``_registry_lock``
        itself. Called from the staging-arrival site (after
        ``queue.enqueue`` returns, so ``queue._lock`` is already released)
        to register a claim the moment a fastlane-eligible request lands
        in staging -- not only later at a failed route.

        Lock order: queue._lock -> _registry_lock (acquired here), never
        reversed. This is the standing discipline for this codebase.
        """
        async with self._registry_lock:
            self._register_fastlane_claim_locked(slot, reason)

    def _register_fastlane_claim_locked(
        self, slot: "Slot", reason: str, key: "tuple[str, str] | None" = None,
    ) -> None:
        """CALLER HOLDS _registry_lock. Register that ``slot`` is waiting on a
        make-room MISS (or add it to the claim its client+model already
        holds) -- called from
        ``_defer_unroutable``, the single funnel both of
        ``_route_or_reserve``'s starvation call sites already share, right
        after each computes its defer/exhaust decision.

        Eligibility: gated on ``_fastlane_claim_eligible`` -- an
        unlisted, non-floor slot is refused a claim outright, never
        silently tracked.
        Dedup: keyed by ``_fastlane_claim_key``; a request for an
        ALREADY-claimed key adds no claim: it is recorded as a waiter of the
        existing one (``_note_claim_waiter``). The claim always carries the
        best request of that client+model that still waits (best is the lower
        ``(rule_index, rank)``, ties to the earlier arrival): it moves in place
        when a strictly better request arrives, or when the request it points
        at is gone; an EQUAL or worse request never moves it. A claim parked
        in a resident's inbox is split off under its own key (the parked
        request keeps it) only for a STRICTLY better request, and the shared
        key then belongs to the requests that still wait for room; an equal or
        worse request is then only a waiter, and the claim goes to the best
        remaining waiter when the parked request starts. Past ``_CLAIMS_MAX``,
        the single lowest-priority existing claim (by ``_fastlane_claim_sort_key``)
        is evicted to make room -- counted and logged at WARNING -- rather than
        refusing the new claim.
        Cadence: this is the ONLY call site for the "registered"
        transition -- fired once per genuine MISS+defer, never per-tick.
        ``key`` overrides the dedup key (the own claim of a parked request).
        """
        if not self._fastlane_claim_eligible(slot):
            return
        if key is None:
            key = self._fastlane_claim_key(slot)
        if key is not None and self._fastlane_claims.get(key, {}).get("slot") is slot:
            # Back in the queue after waiting in an inbox: a waiting claim again.
            self._unpark_fastlane_claim(slot)
        carried: "dict[str, Slot]" = {}
        existing = None if key is None else self._fastlane_claims.get(key)
        if (
            existing is not None and existing["slot"] is not slot
            and existing.get("parked_on") and existing.get("waiters") is not None
            and self.queue._fastlane_strictly_higher(
                self.queue._fastlane_priority_key(slot),
                self.queue._fastlane_priority_key(existing["slot"]),
            )
        ):
            # The shared claim points at a request parked in an inbox and a STRICTLY
            # better request arrives: the parked request keeps its claim under its own
            # key, and the shared key is free for the requests that still wait for room.
            # An equal or worse request does not touch the claim; it is only recorded as
            # a waiter (below), so the claim and its priority stay where they are.
            parked_slot = existing["slot"]
            own = (f"parked:{parked_slot.slot_id}", parked_slot.model_tag)
            if own not in self._fastlane_claims:
                moved = self._fastlane_claims.pop(key)
                carried = {
                    sid: w for sid, w in moved["waiters"].items() if w is not parked_slot
                }
                moved["waiters"] = {parked_slot.slot_id: parked_slot}
                self._fastlane_claims[own] = moved
        if key is not None and key in self._fastlane_claims:
            self._note_claim_waiter(key, slot)
            return
        if key is None:
            return
        if len(self._fastlane_claims) >= _CLAIMS_MAX:
            worst_key = max(
                self._fastlane_claims,
                key=lambda k: self._fastlane_claim_sort_key(
                    self._fastlane_claims[k]["slot"]
                ),
            )
            worst = self._fastlane_claims.pop(worst_key)
            self._fastlane_claim_refusals["capacity"] = (
                self._fastlane_claim_refusals.get("capacity", 0) + 1
            )
            log.warning(
                "FASTLANE_CLAIM event=released reason=capacity slot_id=%s model_tag=%s",
                worst["slot"].slot_id, worst["slot"].model_tag,
            )
            self._spawn_bg(self._emit_fastlane_claim_event(
                worst["slot"], "fastlane_claim_released", reason="capacity",
            ))
        now_monotonic = time.monotonic()
        self._fastlane_claims[key] = {
            "slot": slot,
            "reason": reason,
            "registered_at_monotonic": now_monotonic,
            "registered_at_iso": datetime.now(timezone.utc).isoformat(),
            "ttl_deadline_monotonic": now_monotonic + _FASTLANE_CLAIM_TTL_S,
            # Every request of this (client, model) that still waits, claim slot included.
            "waiters": {**carried, slot.slot_id: slot},
        }
        if carried:
            self._repoint_claim_to_best_waiter(self._fastlane_claims[key], force=True)
        log.info(
            "FASTLANE_CLAIM event=registered reason=%s slot_id=%s model_tag=%s",
            reason, slot.slot_id, slot.model_tag,
        )
        self._spawn_bg(self._emit_fastlane_claim_event(slot, "fastlane_claim_registered"))
        self._spawn_bg(self._emit_fastlane_claim_event(slot, "fastlane_admission_pending"))

    @staticmethod
    def _claim_waiter_gone(slot: "Slot") -> "str | None":
        """The release reason if the request itself is gone (client disconnected,
        evicted, or its completion failed or was cancelled), else ``None``. Sync,
        await-free and read-only."""
        if slot.disconnect_event is not None and slot.disconnect_event.is_set():
            return "disconnected"
        if slot.is_evicted:
            return "disconnected"
        fut = slot.completion_future
        if fut is not None and fut.done():
            if fut.cancelled() or fut.exception() is not None:
                return "failed"
        return None

    def _claim_waiter_order(self, slot: "Slot") -> "tuple":
        """Best waiter first: the better (rule_index, rank) key, an unlisted slot
        last, then the one that arrived first."""
        k = self.queue._fastlane_priority_key(slot)
        return (k is None, k or (0, 0), slot.created_at)

    def _note_claim_waiter(self, key: "tuple[str, str]", slot: "Slot") -> None:
        """``slot`` waits for the same (client, model) as an existing claim: record it
        as a waiter. When its key is strictly better than the key of the request the claim
        points at, or that request is gone, the claim goes to the BEST of all the live
        waiters (not simply to ``slot``: when the holder is gone a better waiter may
        still wait). An EQUAL or worse request is only recorded: the claim and its
        priority stay where they are. A claim under a ``parked:`` key takes no
        further waiters. Sync and await-free; the claim count does not change."""
        claim = self._fastlane_claims[key]
        waiters = claim.get("waiters")
        if waiters is None or claim["slot"] is slot or key[0].startswith("parked:"):
            return
        waiters[slot.slot_id] = slot
        current = claim["slot"]
        if self._claim_waiter_gone(current) is not None or self.queue._fastlane_strictly_higher(
            self.queue._fastlane_priority_key(slot), self.queue._fastlane_priority_key(current),
        ):
            self._repoint_claim_to_best_waiter(claim, force=True)

    def _repoint_claim_to_best_waiter(self, claim: dict, force: bool = False) -> bool:
        """Drop the waiters that are gone and, when the request the claim points at is
        gone (or ``force``), point the claim at the best waiter that is left: the
        better ``(rule_index, rank)``, ties to the earlier arrival (see
        ``_claim_waiter_order``). A parked mark on the claim is cleared, and the
        time-to-live then restarts (the claim stands for a request that waits
        for room). Returns False when no waiter is left; the claim then stays as it
        was and reads as dead. Sync, await-free, no lock taken: it only edits the
        claim record."""
        waiters = claim.get("waiters")
        if not waiters:
            return False
        for sid in [sid for sid, w in waiters.items() if self._claim_waiter_gone(w) is not None]:
            del waiters[sid]
        if not waiters:
            return False
        if not force and any(w is claim["slot"] for w in waiters.values()):
            return True
        best = min(waiters.values(), key=self._claim_waiter_order)
        if best is not claim["slot"]:
            claim["slot"] = best
            log.info(
                "FASTLANE_CLAIM event=moved slot_id=%s model_tag=%s",
                best.slot_id, best.model_tag,
            )
        if claim.pop("parked_on", None) is not None:
            claim["ttl_deadline_monotonic"] = time.monotonic() + _FASTLANE_CLAIM_TTL_S
        return True

    def _park_fastlane_claim_locked(self, slot: "Slot", r: "Resident") -> None:
        """CALLER HOLDS _registry_lock. ``slot`` was just put in ``r``'s inbox:
        keep its claim, marked as parked there, until its own turn starts.
        If the dedup key is held by another request of the same client, the
        parked slot registers a claim of its own (keyed by its slot id) and is
        dropped from the waiters of the shared one, so that it is not left
        without a claim when that other claim goes away."""
        key = self._fastlane_claim_key(slot)
        claim = None if key is None else self._fastlane_claims.get(key)
        if key is not None and (claim is None or claim["slot"] is not slot):
            own = None if claim is None else (f"parked:{slot.slot_id}", slot.model_tag)
            self._register_fastlane_claim_locked(slot, "parked_in_inbox", own)
            if claim is not None and claim.get("waiters") is not None:
                # It now holds a claim of its own: it no longer waits under the shared one.
                claim["waiters"].pop(slot.slot_id, None)
            key = self._fastlane_claim_key(slot)
            claim = self._fastlane_claims.get(key)
        if claim is not None and claim["slot"] is slot:
            claim["parked_on"] = r.resident_key

    def _unpark_fastlane_claim(self, slot: "Slot") -> None:
        """``slot`` left a resident's inbox for the queue: its claim is an
        ordinary waiting claim again, so the claim time-to-live runs again
        from now. Sync and await-free, like the release."""
        key = self._fastlane_claim_key(slot)
        claim = None if key is None else self._fastlane_claims.get(key)
        if claim is not None and claim["slot"] is slot and claim.pop("parked_on", None) is not None:
            claim["ttl_deadline_monotonic"] = time.monotonic() + _FASTLANE_CLAIM_TTL_S

    @staticmethod
    def _inbox_holds_slot(r: "Resident", slot: "Slot") -> bool:
        """Is ``slot`` itself (identity) waiting in ``r``'s inbox right now?
        Read-only: scans a snapshot of the inbox's backing deque and consumes
        nothing, so a parked getter and the queue's own bookkeeping are
        untouched. Sync and await-free. A resident without an inbox, or an
        inbox without a backing deque, holds nothing."""
        items = getattr(getattr(r, "inbox", None), "_queue", None)
        return items is not None and any(s is slot for s in tuple(items))

    def _parked_claim_outranks_holder_locked(
        self, r: "Resident", only_slot: "Slot | None" = None,
    ) -> bool:
        """Is a live claim parked in ``r``'s own inbox strictly higher ranked
        (``(rule_index, rank)``) than what ``r`` is serving, i.e. a better
        client, or a better tag of the same client? Such a claim needs
        no room: ``r`` is not unloaded, it just stops waiting for follow-ups
        and admits the parked request at its turn boundary. Pure and
        read-only apart from the liveness call (``_claim_is_live``), which may move
        a claim whose request is gone to the best remaining waiter (a claim record
        edit, never a change of the dict); bounded by the claim registry size.
        ``only_slot`` narrows the question to one parked request that the caller
        has just taken out of ``r``'s inbox itself, so it is not looked for there.

        The claim's mark is only a resident key, and a key can outlive its
        resident (a later resident reuses it). Without ``only_slot`` a claim
        therefore counts only if its request really is in ``r``'s inbox. The
        liveness call can also move a claim to a request that is not parked
        here, so the claim is looked at again after that call: a claim that no
        longer points at a request parked here is not counted."""
        def parked_here(c: dict) -> bool:
            return c.get("parked_on") == r.resident_key and (
                c["slot"] is only_slot if only_slot is not None
                else self._inbox_holds_slot(r, c["slot"])
            )

        parked = [c for c in self._fastlane_claims.values() if parked_here(c)]
        if not parked:
            return False
        holder_key = self._resident_priority_key(r, self._fastlane_table())
        for claim in parked:
            if self._claim_is_live(claim) is not None:
                continue
            # Liveness may have moved the claim to another waiter that is not parked
            # here: its key must not be used, so look at the claim again.
            if not parked_here(claim):
                continue
            claim_key = self.queue._fastlane_priority_key(claim["slot"])
            if claim_key is None:
                continue
            # Full (rule_index, rank) keys: rule_index decides first, so a
            # better tag of the SAME client parked in the inbox outranks a
            # worse-tag holder, and a better tag of another client never
            # outranks a better client's holder.
            if holder_key is None or self.queue._fastlane_strictly_higher(
                claim_key, holder_key,
            ):
                return True
        return False

    def _release_fastlane_claim_locked(self, slot: "Slot", reason: str) -> None:
        """CALLER HOLDS _registry_lock. Release ``slot``'s claim, if any.
        Cadence: once per transition -- a no-op if the
        slot never held a claim (including "was never eligible"). If a
        DIFFERENT slot now owns this dedup key, ``slot`` was only a waiter
        of that claim: it is dropped from the waiters and the claim stays.
        If ``slot`` owns the claim and other requests of the same
        client+model still wait, the claim moves to the best of them and
        is released only when none is left. The released event (and the
        admitted one, for an admission) is emitted for ``slot`` whenever it
        owned the claim, whether the claim goes on or not; a waiter that
        is only dropped emits nothing.

        A release whose reason is "admitted"
        also emits ``fastlane_admitted`` -- the FOURTH of the four lifecycle
        events of the claim lifecycle ("claim registered, admission pending,
        admitted, released"), and the only one that did not exist. Before
        this, "admitted" was a reason STRING on somebody else's event, so a
        consumer had to infer an admission by filtering RELEASE events on a
        free-text field, and the ``fastlane_admission_pending`` opened at
        registration was never closed by anything.

        Emitted HERE, at the one choke point, rather than at the three
        ``(slot, "admitted")`` call sites: three call sites are three
        chances to drift. Emitting it INSIDE the guards above is also what
        makes it symmetric with ``fastlane_admission_pending`` -- both fire
        only for a slot that actually held a claim, so the pair opens and
        closes together and neither can appear without the other.
        """
        key = self._fastlane_claim_key(slot)
        if key is None:
            return
        claim = self._fastlane_claims.get(key)
        if claim is None:
            return
        waiters = claim.get("waiters")
        if waiters is not None:
            waiters.pop(slot.slot_id, None)
        if claim["slot"] is not slot:
            return
        # Other requests of this (client, model) may still wait: the claim then goes on
        # with the best of them instead of being deleted.
        if not (waiters and self._repoint_claim_to_best_waiter(claim)):
            del self._fastlane_claims[key]
        if reason == "admitted":
            log.info(
                "FASTLANE_CLAIM event=admitted slot_id=%s model_tag=%s",
                slot.slot_id, slot.model_tag,
            )
            self._spawn_bg(self._emit_fastlane_claim_event(
                slot, "fastlane_admitted",
            ))
        log.info(
            "FASTLANE_CLAIM event=released reason=%s slot_id=%s model_tag=%s",
            reason, slot.slot_id, slot.model_tag,
        )
        self._spawn_bg(self._emit_fastlane_claim_event(
            slot, "fastlane_claim_released", reason=reason,
        ))

    def _claim_is_live(self, claim: dict) -> "str | None":
        """Liveness check (partial -- see ``fastlane_claims_snapshot``
        for the one sub-check NOT implemented here). Returns the release
        reason if ``claim`` is now dead, else ``None``.

        Checked, in order: claimant ``disconnect_event`` set, claimant
        ``is_evicted``, claimant's ``completion_future`` already done with
        a failure/cancellation (a SUCCESSFUL completion is release-on-
        admission's job -- by the time a future resolves successfully the
        slot has already been routed and its claim already released
        there), the queue closed (``self.queue._closed``), and TTL expiry
        (``ttl_deadline_monotonic``; ★ ``_FASTLANE_CLAIM_TTL_S`` is a
        flagged placeholder, see its own definition), which is not checked
        while the claim is parked in an inbox. When the claimant is
        gone but other requests of that client+model still wait, the claim
        first moves to the best of them, and the checks apply to that one.

        NOT implemented: "claim is unsatisfiable -- model cannot fit even
        with every evictable resident on its target card removed."
        Computing that correctly needs a simulate-every-eviction VRAM
        projection, which this code does not yet build with enough
        confidence for a security-relevant release path (a wrong verdict
        either drops a live claim or leaves a truly-dead one parked);
        left as a known gap rather than guessed at.
        """
        if claim.get("waiters") and self._claim_waiter_gone(claim["slot"]) is not None:
            # The request the claim points at is gone: move to the next-best waiter.
            self._repoint_claim_to_best_waiter(claim)
        slot = claim["slot"]
        gone = self._claim_waiter_gone(slot)
        if gone is not None:
            return gone
        if self.queue._closed:
            return "queue_closed"
        if not claim.get("parked_on") and time.monotonic() >= claim["ttl_deadline_monotonic"]:
            return "ttl_expired"
        return None

    def fastlane_claims_snapshot(self) -> "list[dict]":
        """DATA method -- ``fastlane_census_snapshot``'s own convention:
        no HTTP route lives here, the API layer serializes this. Prunes
        dead claims inline first (the liveness check runs on every re-check):
        sync, lock-free like ``fastlane_census_snapshot`` -- this file's
        asyncio model means a sync function with no ``await`` inside runs
        to completion without another coroutine interleaving, so
        collect-dead-then-delete is race-free without ``_registry_lock``
        (that lock exists for the await points a genuinely async critical
        section can be suspended at; this method has none).

        A claim whose request is gone is not pruned while other requests of
        its client+model still wait: the liveness check first moves it to the
        best of them, and its row then shows that request. A claim with no live
        waiter left, a claim past its time-to-live and every claim once the
        queue is closed are removed.

        Exact redaction shape: explicit dict only;
        ``fastlane`` is either ``{rule_index, rank, label, fastlane_rule}``
        (``label`` resolved LIVE via ``_live_fastlane_label``, not the
        frozen match's own stale ``.label``) or ``None`` for an unlisted
        (floor-only) row; ``thread_id_prefix`` only, never a full
        ``thread_id``; never ``client_meta``, never ``ip``, never
        ``asdict(slot)``/``__dict__``, never ``_identity_dict``.
        """
        dead: "list[tuple[tuple, str]]" = []
        for key, claim in self._fastlane_claims.items():
            reason = self._claim_is_live(claim)
            if reason is not None:
                dead.append((key, reason))
        for key, reason in dead:
            claim = self._fastlane_claims.pop(key, None)
            if claim is None:
                continue
            slot = claim["slot"]
            log.warning(
                "FASTLANE_CLAIM event=released reason=%s slot_id=%s model_tag=%s",
                reason, slot.slot_id, slot.model_tag,
            )
            self._spawn_bg(self._emit_fastlane_claim_event(
                slot, "fastlane_claim_released", reason=reason,
            ))
        rows = []
        # The claim record is "who is
        # waiting, who is the likely eviction target, since when" -- the
        # middle third was missing. Resolved ONCE for the whole snapshot
        # rather than per row: it is a property of the registry's current
        # state, not of any one claim, and re-resolving it per row could
        # hand two rows of the SAME snapshot different victims.
        # ⚠ DISPLAY-ONLY by design: the 'likely victim'
        # field is display-only -- the eviction decision is always the fresh
        # under-lock evaluation, never the displayed name. This
        # value is written into a snapshot row and read by nothing else.
        likely_victim = self._likely_unload_target_model_tag()
        for claim in self._fastlane_claims.values():
            slot = claim["slot"]
            fl = slot.fastlane
            fastlane_view = (
                {
                    "rule_index": fl.rule_index,
                    "rank": fl.rank,
                    "label": self._live_fastlane_label(fl.raw_address),
                    "fastlane_rule": fl.raw_address,
                }
                if fl is not None
                else None
            )
            rows.append({
                "slot_id": slot.slot_id,
                "model_tag": slot.model_tag,
                "thread_id_prefix": (slot.thread_id or "")[:8],
                "fastlane": fastlane_view,
                "reason": claim["reason"],
                "registered_at": claim["registered_at_iso"],
                "waited_s": round(time.monotonic() - claim["registered_at_monotonic"], 1),
                "likely_victim": likely_victim,
            })
        return rows

    def _defer_unroutable(self, slot: Slot, *, evict_pending: bool = False) -> None:
        """MISS -- UNBOUNDED re-queue by design:
        a request that is queued stays queued -- the manager does not
        cancel it on its own, only if
        the client explicitly cancels it. Two regimes, INDEPENDENT
        per-slot counters:
          - busy (evict_pending=False): count-cap full, all residents busy,
            no idle victim -- the model FITS, it is just not this moment's
            turn. 50ms backoff (transient).
          - evict-pending (evict_pending=True): VRAM-over-commit; an
            idle victim is being torn down to free the card, or the blocker
            is still ACTIVE/GRACE. 1s backoff. enqueue_head preserves FIFO.

        There is no cap and no exhaustion any more -- a deferred
        slot is ALWAYS re-registered and re-queued, unconditionally, for as
        long as the client stays connected. The only thing that ever removes
        a slot from this loop is queue.py's own disconnect_event check (set
        by api/chat_completion.py's watch_disconnect, armed on all four
        client entry points -- openai_chat_completions,
        _openai_chat_completions_stream, ollama_chat, post_embeddings) -- a
        client that walks away is dropped because it is actually gone, never
        on a stopwatch. This matches the established rule:
        "a model that FITS but cannot run NOW must be QUEUED, never
        REFUSED." See _legacy_defer_exhaustion_refusal for what this branch
        used to do on exhaustion -- retained for
        reference, not deleted, and no longer called from here under
        any condition.

        This is the single funnel both of
        _route_or_reserve's starvation call sites (count-cap, VRAM) already
        share -- a claim is registered here (not at either call site) so
        both flow through one path with no risk of drifting apart. Reason
        string matches _log_make_room_starved's own vocabulary for the same
        branch, so a claim and its starvation log line correlate by grep."""
        if evict_pending:
            counter_attr = "_vram_defer_count"
            backoff_s = _VRAM_DEFER_BACKOFF_S
            claim_reason = "make_room_starved_vram"
        else:
            counter_attr = "_dispatch_defer_count"
            backoff_s = _DISPATCH_DEFER_BACKOFF_S
            claim_reason = "make_room_starved_count_cap"
        # No reader consults this count -- retained deliberately, NOT
        # dead code: a deferred slot is always
        # re-queued now, so this count is no longer consulted for a
        # decision -- it is the request's own wait-length observability
        # instead (how long has this request been waiting), an
        # observability signal this codebase had never
        # actually shipped. More useful now than before this change, not less.
        n = getattr(slot, counter_attr, 0) + 1
        setattr(slot, counter_attr, n)
        self._register_fastlane_claim_locked(slot, claim_reason)
        self._notify_grace_starvation_candidate(slot)
        self._spawn_bg(self._requeue_after_backoff(slot, backoff_s=backoff_s))

    def _notify_grace_starvation_candidate(self, slot: Slot) -> None:
        """Grace-loop fairness floor: called synchronously, in the
        SAME no-await critical section as the rest of ``_defer_unroutable``
        (caller holds ``_registry_lock``), every time a slot fails to route.

        WHY THIS EXISTS, NOT JUST ``queue.starved_other_model()``: a
        capacity-blocked other-model waiter is popped OUT of BOTH
        ``_staging`` and ``_accept_buf`` for the whole ``_requeue_after_
        backoff`` wait, and a debug trace shows the
        re-enqueue (``enqueue_head``) and the dispatcher's wake-driven
        re-pop land in the SAME event-loop tick -- an independently-timed
        poller (the grace loop's own 0.05s cycle) can therefore go the
        ENTIRE grace window without ever observing the buffer non-empty,
        regardless of backoff length (measured with both the 0.05s busy
        regime and the 1.0s VRAM regime). Recording the fact HERE, where
        it is synchronously and reliably known the instant it happens,
        sidesteps that blind spot entirely: the grace loop reads a plain
        attribute, not a transient buffer.

        Deliberately narrow: only slots already aged past ``max_other_
        model_wait_s`` (the SAME threshold ``_starved_other_model_locked``
        applies) count -- a fresh, not-yet-starved defer must not trip
        this. Every resident currently in an ACTIVE grace window for a
        DIFFERENT model is a candidate; there is no thread/claim identity
        to narrow by here (the starving population is, by definition,
        every OTHER model), matching ``starved_other_model``'s own scope.
        The Fast Lane exclusion (a claim must never
        use this path to shorten a non-victim's grace) is applied where
        this is CONSUMED (``_starvation_breakout_gate``), not here, so
        both entrances share the identical gate.

        ``getattr(..., default=inf)``, not a bare attribute read: several
        pre-existing tests drive ``_defer_unroutable`` with a narrow
        ``FakeQueue`` double that carries only the config fields ITS OWN
        scenario touches (e.g. the deferral reproduction test's, which has no
        Fast Lane / starvation surface at all) -- `inf` makes the age
        check always False, an exact no-op, matching this notification's
        behavior on every caller before this notification existed."""
        max_wait = getattr(self.queue, "max_other_model_wait_s", float("inf"))
        if (time.monotonic() - slot.created_at) <= max_wait:
            return
        for r in self._residents.values():
            if r.in_grace_loop and r.model_tag != slot.model_tag:
                r.starvation_breakout_candidate = slot

    def _legacy_defer_exhaustion_refusal(
        self, slot: Slot, *, evict_pending: bool, max_defers: int,
    ) -> None:
        """UNCALLED as of v0.8.0 (legacy code: nothing in the current dispatch path calls it).
        RETAINED, NOT DELETED, deliberately: dead code is kept in place and marked
        as such in the comments, because it is the legacy path and may be
        useful again later; keeping it costs nothing, and removing it would
        lose the history of how the old exhaustion refusal worked.
        The old behaviour is kept here as a reference
        for anyone who needs the legacy path again.

        WHY unreachable: this was `_defer_unroutable`'s own exhaustion
        branch (`if n > max_defers: ...`) -- the mechanism that converted a
        queued-but-not-yet-routable request into a client-facing 503 after a
        bounded number of retries (60s floor, 1800s/30min ceiling, via
        `_max_vram_defers`/`_max_busy_defers`). The current design removes the
        client-facing refusal entirely: once a request is queued, it stays
        queued, and the manager never cancels it on its own, only when the
        client very specifically cancels it.
        `_defer_unroutable` no longer calls this method under any condition.

        NOT MAINTAINED. Nothing exercises this any more; verify it before
        reattaching a caller -- it will have rotted exactly like any other
        unexercised path.

        WHAT REPLACED IT: nothing -- there is no cap any more. See
        `_defer_unroutable`'s own docstring (manager.py) for the removed
        call site and the disconnect path that is now the only way a slot
        leaves the queue.
        """
        self._release_fastlane_claim_locked(slot, "unroutable_exhausted")
        if evict_pending:
            self._fail_completion_future(
                slot,
                VramOverCommitError(
                    f"no VRAM capacity for model {slot.model_tag!r} after "
                    f"{max_defers} evict-pending defers "
                    f"(~{int(max_defers * _VRAM_DEFER_BACKOFF_S)}s); nothing "
                    f"idle-evictable freed the target card in time",
                    retry_after_s=_VRAM_DEFER_RETRY_AFTER_S,
                ),
            )
        else:
            # Busy-regime exhaustion is transient
            # (all residents busy), not a hard capacity ceiling -- carry the
            # retryable VramOverCommitError class so the API's exception
            # mapping returns 503+Retry-After instead of a non-retryable 500.
            self._fail_completion_future(
                slot,
                VramOverCommitError(
                    f"no capacity for model {slot.model_tag!r} after "
                    f"{max_defers} defers (all residents busy)",
                    retry_after_s=_VRAM_DEFER_RETRY_AFTER_S,
                ),
            )

    async def _wait_for_park_or_timeout(self, backoff_s: float) -> bool:
        """Wake
        early if ANY resident parks to IDLE_EVICTABLE, a grace window lapses, or
        capacity is released by a completed eviction during this wait -- the
        THREE defined decision moments -- else fall back to today's
        exact `backoff_s` backstock (the SAME value the caller already computed
        from `_max_busy_defers()`/`_max_vram_defers()`, unextended).

        Returns True when woken at a decision moment: the request
        "waits to be woken" and this WAKE is the routine advance. Returns False
        when the `backoff_s` backstock elapsed WITHOUT a wake -- a
        LOST-WAKE BACKSTOCK ONLY. The caller (`_requeue_after_backoff`) re-enqueues
        on EITHER outcome so a lost wake can never hang, but the wake (not the
        timer) is the load-bearing admission signal, avoiding a
        decoration on a polling loop. The real eviction decision is still made
        fresh by the next `_route_or_reserve` -> `_lru_idle_unloadable` pass under
        lock, ordered by rank; this wait only ADVERTISES that a decision
        moment occurred.

        `_registry_lock` is held only for the instant needed to enter/exit
        the wait (`Condition.wait()` releases it for the duration of the
        actual waiting and reacquires it just before returning), and is
        fully released when this coroutine returns -- `enqueue_head`
        (which touches `queue._lock`) is only ever called by the caller
        AFTER this returns, so `queue._lock` and `_registry_lock` are never
        held nested, preserving the `queue._lock -> _registry_lock` order
        (see `listed_waiter_model_tags`/`listed_waiter_priority_keys` in
        queue.py — both take `queue._lock`) by never approaching it from the
        other direction.
        """
        async with self._make_room_signal:
            try:
                await asyncio.wait_for(
                    self._make_room_signal.wait(), timeout=backoff_s
                )
            except TimeoutError:
                # LOST-WAKE BACKSTOCK ONLY: no decision-moment wake
                # arrived. The caller re-enqueues on this too, so a lost wake
                # degrades to the previous behaviour and never hangs -- but it
                # is the FALLBACK, not the routine advance.
                return False
        # Woken at a defined decision moment: this WAKE is the
        # routine advance. `_registry_lock` is fully released here (the
        # `async with` above has exited) before the caller touches `queue._lock`
        # in `enqueue_head`, preserving the `queue._lock -> _registry_lock` order
        # (see `listed_waiter_model_tags`/`listed_waiter_priority_keys` in
        # queue.py — both take `queue._lock`) by never approaching it from the
        # other direction.
        return True

    async def _requeue_after_backoff(
        self, slot: Slot, *, backoff_s: float = _DISPATCH_DEFER_BACKOFF_S
    ) -> None:
        """Re-enqueue an unroutable slot at the HEAD after a backoff so the
        dispatcher can't burn its whole defer budget in a sub-second busy-loop
        while residents are transiently busy. Detached, so it MUST fail the slot's
        future on ANY failure (cancel during the sleep at shutdown, or enqueue_head
        raising on a closing queue) rather than silently dropping it — otherwise the
        client hangs until upstream timeout (B4). Mirrors _route_or_reserve's
        except-fails-the-future safety net. backoff_s: 0.05 for the busy path
        (byte-identical to today's hardcoded sleep), _VRAM_DEFER_BACKOFF_S for the
        evict-pending path.

        The wait itself is
        `_wait_for_park_or_timeout`, which now RETURNS whether it was advanced
        by a decision-moment WAKE (`woken=True`, the routine advance)
        or by the `backoff_s` backstock (`woken=False`, a
        LOST-WAKE BACKSTOCK). The slot is re-enqueued at the head in EITHER case
        so a lost wake can never hang, but the wake -- not the 0.05s backstock --
        is the load-bearing admission signal: with a live wake the re-enqueue
        happens promptly even when `backoff_s` is far larger than the
        inter-wake interval.

        This single funnel serves BOTH defer regimes: `_defer_unroutable` with
        `evict_pending=False` (busy 0.05s path) and `evict_pending=True` (the
        1s VRAM path). In both, the wake is the routine advance and the backstock
        is the lost-wake backstock only. See `_wait_for_park_or_timeout` for the
        lock-ordering guarantee (enqueue_head never runs under _registry_lock).
        """
        try:
            woken = await self._wait_for_park_or_timeout(backoff_s)
            if not woken:
                # No decision-moment wake arrived. We STILL re-enqueue
                # (next line) so a lost wake degrades to the previous behaviour
                # and can never hang -- but this is the backstock, NOT the
                # routine advance. Logged at debug so the busy 0.05s path stays
                # quiet in production while the wake-vs-backstock split stays
                # observable in traces.
                log.debug(
                    "fast-lane requeue advanced on backstock (woken=False, "
                    "slot=%s, backoff_s=%.3f) -- the wake is the routine "
                    "advance; see _wait_for_park_or_timeout",
                    slot.slot_id,
                    backoff_s,
                )
            await self.queue.enqueue_head(slot)
        except asyncio.CancelledError:
            self._fail_completion_future(
                slot, RuntimeError("requeue cancelled during shutdown")
            )
            raise
        except Exception as e:  # noqa: BLE001 -- detached path must not swallow
            log.exception("requeue-after-backoff failed for slot %s", slot.slot_id)
            self._fail_completion_future(slot, e)

    def _model_never_fits_known_capacity(
        self, model_tag: "str | None", main_gpu: int, split_mode: str
    ) -> bool:
        """Never-fits check on a fully known capacity (an unknown capacity is
        never treated as never-fits, and the placement is caller-supplied):
        True ONLY when ``model_tag``'s need PROVABLY
        exceeds a FULLY KNOWN empty-box capacity. ``need`` still comes from
        ``_read_model_footprint`` (no new footprint model is introduced),
        but ``main_gpu``/``split_mode`` are now caller-supplied: the RESOLVED
        placement ``_spawn_for_resident`` actually launched with (its own
        ``spawn_flags``, after any auto-place/Fast-Lane-relocation
        override) -- not the manifest's raw values, which can
        differ from what was actually admitted, so a card
        with less room than the manifest implies would silently pass this
        check. Matched against the per-card PHYSICAL totals
        (``_vram_total_mib``), which is populated LAZILY on first need (see
        the ``getattr(self, "_vram_total_mib_fn", ...)`` populate at
        the call site in this file) -- it is not filled once at boot,
        but on first need, as stated above.

        Capacity is "known" only when ``_vram_total_mib`` is populated,
        non-empty, AND every card's total is a positive number. A ``None``,
        empty, zero, or partially-missing reading returns False (UNDECIDED,
        never treated as never-fits) -- an error on
        unknown capacity would end a legitimate caller's request, against
        the rule 'until the caller disconnects'. An UNDECIDED
        result still requeues on the OOM path; it just never fails-once on
        this check.
        """
        capacity = getattr(self, "_vram_total_mib", None)
        if not capacity:  # None or empty list -> capacity entirely unknown
            return False
        if any(not isinstance(c, (int, float)) or isinstance(c, bool) or c <= 0 for c in capacity):
            return False  # any card's total missing/non-positive -> not fully known
        need, _parallel, _manifest_main_gpu, _manifest_split_mode, _sleep_idle_s, _auto_place = (
            self._read_model_footprint(model_tag)
        )
        # Match _vram_budget's exact math (see safety.py), which
        # applies the same rule here:
        # layer, row, AND tensor split modes all span every visible card --
        # not just 'layer' -- per _vram_admits_locked's own docstring
        # ("Layer-split (layer/row/tensor) models are still refuse-blind for
        # co-residence: a layer-split sibling spans every visible GPU").
        # Only split_mode == "none" (tensor-isolated, single-card) is
        # bounded by the SPECIFIC resolved main_gpu's own card, bounds-
        # checked exactly like _vram_budget's own out-of-range fallback.
        if (split_mode or "layer").lower() == "none":
            if 0 <= main_gpu < len(capacity):
                available = capacity[main_gpu]
            else:
                log.warning(
                    "_model_never_fits_known_capacity: split_mode=none "
                    "main_gpu=%s out of range (%d GPU(s) known) -- "
                    "checking GPU0 instead",
                    main_gpu, len(capacity),
                )
                available = capacity[0]
        else:
            available = sum(capacity)
        return need > available

    async def _settle_after_make_room_wake(self, settle_s: float) -> None:
        """After a REAL
        ``_make_room_signal`` wake, swallow any further notifies that
        arrive within ``settle_s`` of that FIRST wake, so a burst of
        near-simultaneous frees collapses to exactly ONE retry attempt
        rather than one per notify. A fixed window measured from the first
        wake, not renewed per swallowed notify. Reuses
        ``_wait_for_park_or_timeout`` for both arms (its own lock-ordering
        guarantee applies unchanged); a wake during the window means
        another real notify arrived (loop, still swallowing); a timeout
        means the window elapsed quietly (return, proceed with the attempt).
        """
        deadline = time.monotonic() + settle_s
        while True:
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                return
            await self._wait_for_park_or_timeout(remaining)

    async def _oom_requeue_wait_then_readmit(
        self, slot: Slot, seed_free_mib: "int | None" = None
    ) -> None:
        """Background companion to an OOM-classified, requeued
        load failure (retry only after something changed,
        at most once per burst, never on a bare timer). Detached
        (``_spawn_bg``'d by the two failure sites), so on ANY unexpected
        exit path it MUST resolve the slot's future rather than let the
        caller hang -- mirrors ``_requeue_after_backoff``'s own discipline.

        Loop: wait on a REAL ``_make_room_signal`` wake
        (``_wait_for_park_or_timeout`` -- see that method for the
        wake-vs-backstock split). A backstock (``woken=False``) timeout-only
        wake makes NO admission attempt of its own for a box WITH a
        resident (a still-not-fitting request is never
        retried on a timer alone) -- it only re-loops to re-check
        disconnect. A REAL wake debounces through
        ``_settle_after_make_room_wake`` (swallowing a burst down to one
        attempt), then this makes exactly ONE re-admission attempt by
        re-enqueuing the slot at the head -- the existing placement code
        (unchanged, re-run fresh by the next admission pass) decides where
        it lands, per the Fast Lane placement rules and the
        placement-on-retry rule.

        Empty-box case: a
        resident-LESS box (system-wide, ``_model_residents()`` empty)
        parked via OOM-requeue never gets a ``_make_room_signal`` wake --
        nothing the manager owns can evict/free FOR it, so every wake this
        companion ever sees on an empty box is a backstock timeout. Waiting
        forever on that alone would break the "until the
        caller disconnects" promise the instant capacity actually frees
        (e.g. an external process exits, or another manager instance's
        resident goes away). On a backstock tick with ZERO residents, take
        ONE fresh off-loop reading (``_vram_budget`` -- the SAME helper
        ``_read_model_footprint``'s own callers already reach, per
        the off-loop convention; explicitly NOT
        ``_vram_admits_locked``: that degrades OPEN
        (returns True, admits) on an empty box with an UNREADABLE probe --
        the exact opposite of "stay parked" -- and its own docstring
        requires ``_registry_lock``, which this detached background loop
        does not hold) and make exactly ONE admission attempt if the need
        now fits AND the reading has STRICTLY GROWN past the immediately
        prior reading THIS companion has taken -- a single reading, even
        one that already fits, is indistinguishable from "just polling" (a
        bare timer), so the FIRST reading of this companion's lifetime only
        ever establishes a baseline, never attempts; an unreadable probe
        (``None``) never attempts and never updates the baseline either. A
        box WITH a resident keeps today's wake-only behavior unchanged --
        this whole check is skipped entirely when ``_model_residents()`` is
        non-empty.

        Seed timing (the baseline is read before this companion exists):
        the baseline above is now
        ``seed_free_mib``, a reading taken by the CALLER
        (``_requeue_on_oom_load_failure``) BEFORE this companion is even
        spawned -- not a fresh reading taken here on companion start, and
        not the loop's first backstock tick either. Memory that frees
        between the failed spawn attempt and the first backstock tick
        (one backstock interval) IS growth since that attempt and must count; a
        reading taken here, inside this task's own first turn, cannot
        reliably precede everything that might observe this slot as
        parked (a fresh-read-on-companion-start design can race a
        post-park probe that swaps the reading, and then lose the
        race depending on timing, so the outcome would not be
        stable). Taking it in the CALLER instead, strictly before
        ``slot.oom_requeue_pending`` flips True and before ``_spawn_bg``
        even creates this task, closes that window by construction: there
        is no external state (test-injected or otherwise) that can be
        observed as "parked" before this reading completes, because
        nothing is parked yet. Still None if that read is itself
        unreadable, or if a resident already existed at that moment (see
        ``_requeue_on_oom_load_failure``) -- same "no baseline yet" rule
        as always, just taken and passed in one step earlier.

        Placement note: this
        reading intentionally uses the MANIFEST's main_gpu/split_mode
        (``_read_model_footprint``), not the RESOLVED placement
        ``_model_never_fits_known_capacity`` uses at the failure branch.
        Unlike that branch -- which reads spawn_flags synchronously from
        the reservation it just tried -- this reading (now taken by
        ``_requeue_on_oom_load_failure`` itself, before ANY companion
        exists) has no live reservation left to read a resolved placement
        from either; obtaining one would mean calling
        ``_resolve_placement_locked`` speculatively, the same disqualifier
        that already ruled out reusing ``_vram_admits_locked`` for this
        path. This reading is a best-effort, off-loop SIGNAL deciding only
        whether to bother re-attempting; the real admission machinery
        still resolves placement correctly, under the lock, once
        re-admitted.

        Disconnect is checked before waiting and again before the final
        re-enqueue: if the caller left, this fails the slot's completion
        future with ``SlotEvictedError`` and clears ``oom_requeue_pending``
        before returning WITHOUT re-enqueuing or touching the Fast Lane
        claim -- a bare ``return`` at either point would
        leave the
        slot's completion future unresolved forever: this slot is no
        longer sitting in ``queue.py``'s own structures once it reached
        this companion (it left the queue via the failed spawn attempt
        that requeued it), so the queue's own eviction scan never sees it
        and never fires the finish; the companion therefore fails
        the future itself.

        The disconnect paths leave the claim alone (a disconnected caller's
        claim is dead: the next claims read moves it to the best other waiting
        request of its client and model, or prunes it when none is left). The claim was
        already un-parked when the slot was handed to this companion, so it
        is an ordinary waiting claim for the whole wait; the un-park call
        just before the re-enqueue is a guard that normally does nothing.
        """
        try:
            _empty_box_last_free_mib: "int | None" = seed_free_mib
            while True:
                if slot.disconnect_event is not None and slot.disconnect_event.is_set():
                    slot.oom_requeue_pending = False
                    self._fail_completion_future(
                        slot,
                        SlotEvictedError(
                            f"slot {slot.slot_id} evicted: disconnected while "
                            "OOM-requeue parked"
                        ),
                    )
                    return
                woken = await self._wait_for_park_or_timeout(_OOM_REQUEUE_POLL_S)
                if not woken:
                    # Empty-box (system-wide) fresh-
                    # VRAM-rise retry -- see this method's own docstring.
                    # Skipped entirely (today's wake-only behavior,
                    # unchanged) when any resident exists anywhere.
                    if not self._model_residents():
                        need, _parallel, foot_main_gpu, foot_split_mode, _sleep_s, _auto = (
                            self._read_model_footprint(slot.model_tag)
                        )
                        free_fit, _min_card, _n_cards = await asyncio.to_thread(
                            _vram_budget, foot_split_mode, foot_main_gpu
                        )
                        if free_fit is not None:
                            if (
                                _empty_box_last_free_mib is not None
                                and free_fit > _empty_box_last_free_mib
                                and free_fit >= need
                            ):
                                break
                            _empty_box_last_free_mib = free_fit
                    continue  # lost-wake backstock: re-check disconnect, no attempt
                await self._settle_after_make_room_wake(_OOM_REQUEUE_SETTLE_S)
                break
            if slot.disconnect_event is not None and slot.disconnect_event.is_set():
                slot.oom_requeue_pending = False
                self._fail_completion_future(
                    slot,
                    SlotEvictedError(
                        f"slot {slot.slot_id} evicted: disconnected while "
                        "OOM-requeue parked"
                    ),
                )
                return
            # The slot goes back to the queue. Its claim is normally already
            # unmarked (un-parked when the slot was handed to this companion),
            # so this call is a guard that does nothing in that case.
            self._unpark_fastlane_claim(slot)
            await self.queue.enqueue_head(slot)
        except asyncio.CancelledError:
            self._fail_completion_future(
                slot, RuntimeError("oom requeue wait cancelled during shutdown")
            )
            raise
        except Exception as e:  # noqa: BLE001 -- detached path must not swallow
            log.exception(
                "OOM requeue wait failed for slot %s", slot.slot_id
            )
            self._fail_completion_future(slot, e)

    async def _requeue_on_oom_load_failure(
        self, slot: Slot, scan: dict, main_gpu: int, split_mode: str,
        resident: "Resident",
    ) -> bool:
        """The shared decision both spawn paths call from inside
        their own ``if not healthy:`` failure branch, AFTER their existing
        cleanup (reap / ``_teardown``) has already run. Returns True when
        the slot was requeued (caller must NOT also call
        ``_fail_completion_future`` -- its own ``return`` right after this
        call handles that); False means "fail once, exactly as before this
        change" and the caller proceeds to its own unchanged failure line.

        Decision, in order:
          1. No ``disconnect_event`` -> False (fails once, unchanged).
          2. ``classify_load_failure(scan)`` != "oom" -> False ("other" AND
             "unknown" both fail once -- an unprovable
             cause never requeues).
          3. ``_model_never_fits_known_capacity`` -> False (a model
             that can never fit, on a KNOWN capacity, fails once even if
             this particular failure was OOM-shaped -- requeuing it would
             wait forever for a change that can never come. An UNKNOWN
             capacity is NOT never-fits -- falls through to requeue).
             Note: ``main_gpu``/``split_mode`` are the
             RESOLVED placement the caller actually just tried to launch
             with (its own ``spawn_flags``), passed through unchanged --
             not re-derived from the manifest here.
          4. Otherwise -> takes the empty-box SEED reading (taken before the companion exists;
             the seed-timing rule -- see
             ``_oom_requeue_wait_then_readmit``'s own docstring for the
             full rationale), sets ``slot.oom_requeue_pending`` (read by
             ``submit_and_wait`` for the timeout exemption), spawns the
             detached retry-wait companion with that seed, returns True.
             No claim is registered or released here: the slot keeps
             whatever Fast Lane claim it already holds. If that claim was
             parked on the failed resident, it is un-parked here, before the
             companion exists, so for the whole wait it is an ordinary
             waiting claim: not marked, able to govern the victim
             designation, its time-to-live re-armed and running. The
             companion's own un-park later is a no-op.

        Now ``async``: the seed reading below is
        off-loop (``asyncio.to_thread``) but must complete BEFORE
        ``slot.oom_requeue_pending`` flips and BEFORE the companion task
        even exists, so nothing (test or production) can ever observe this
        slot as parked before the seed is captured -- this is what makes
        the seed deterministic rather than a race against whatever
        schedules first.

        ``resident`` (needed by the seed reading above):
        the caller's own ``Resident`` for THIS failed attempt -- still
        registered in ``_residents`` (state ``RESERVED_LOADING``, not yet
        torn down; teardown happens in the caller, AFTER this call
        returns) at the moment this runs, since the seed is now taken
        BEFORE that teardown rather than well after it (the old, companion-
        side read ran late enough that teardown had already happened, so
        this never came up before). Excluded by IDENTITY (not model_tag --
        a model_tag can carry more than one resident) from the "is the box
        empty" check below, same precedent as ``_other_active_residents``'s
        own ``r.handle is not handle`` exclusion (its ``.handle`` field
        isn't set yet at ``RESERVED_LOADING``, so that exact check doesn't
        reach here -- object identity does). Without this, a lone spawn's
        OWN about-to-be-torn-down reservation would always make the box
        look "not empty" to itself, permanently skipping the seed for the
        single most common case this whole path exists for.
        """
        if slot.disconnect_event is None:
            return False
        cause = load_verify_log.classify_load_failure(scan)
        if cause != "oom":
            return False
        if self._model_never_fits_known_capacity(slot.model_tag, main_gpu, split_mode):
            return False
        seed_free_mib: "int | None" = None
        if not [r2 for r2 in self._model_residents() if r2 is not resident]:
            _need, _parallel, foot_main_gpu, foot_split_mode, _sleep_s, _auto = (
                self._read_model_footprint(slot.model_tag)
            )
            seed_free_mib, _min_card, _n_cards = await asyncio.to_thread(
                _vram_budget, foot_split_mode, foot_main_gpu
            )
        # From here the slot is in no inbox and goes to the companion, so its
        # claim is an ordinary waiting claim for the whole wait (it can govern,
        # its TTL runs). During the seed read above the failed resident is still
        # registered, so the mark named a live resident; the later un-park is a no-op.
        self._unpark_fastlane_claim(slot)
        slot.oom_requeue_pending = True
        self._spawn_bg(
            self._oom_requeue_wait_then_readmit(slot, seed_free_mib=seed_free_mib)
        )
        return True

    async def _requeue_slots_or_fail(self, slots: "list[Slot]") -> None:
        """Re-enqueue a BATCH of drained inbox slots at the head IN ORDER — meaning
        the batch ends up at the staging head in its ORIGINAL order, oldest first.

        ⛔ THE ITERATION IS REVERSED ON PURPOSE. ``enqueue_head`` does a single
        ``self._staging.appendleft(slot)`` (queue.py), so calling it sequentially
        over ``[oldest…newest]`` lands them ``[newest…oldest]`` — each call inserts
        in FRONT of the previous one. Measured: ``[A,B,C]`` → ``['C','B','A']``.
        Iterating ``reversed(slots)`` restores the documented behaviour: the oldest
        slot is inserted last and therefore ends up first.

        ★ Serialisation and order are two separate properties, and both hold here.
        Serialisation: ONE task awaiting sequentially prevents N tasks racing the
        queue lock and scrambling the order (a fairness bug). Order: iterating
        ``reversed(slots)`` makes the batch land in its original order, oldest
        first, as the docstring's first paragraph states.

        Every slot that can't be re-enqueued — queue closing at shutdown
        (enqueue_head raises) or cancel — has its future FAILED, never dropped (the
        inbox-drain analogue of the _requeue_after_backoff safety net). On cancel,
        the remaining batch is failed too so nothing hangs.
        ⚠ The cancel path slices ``ordered``, NOT ``slots``. Reversing the iteration
        without reversing the slice is a live bug: ``i`` would index the reversed
        sequence while ``slots[i:]`` indexed the original, so a cancel would fail the
        WRONG set — including slots already successfully enqueued. Bind the reversed
        list to a name once and slice that."""
        ordered = list(reversed(slots))
        for i, slot in enumerate(ordered):
            self._unpark_fastlane_claim(slot)
            try:
                await self.queue.enqueue_head(slot)
            except asyncio.CancelledError:
                for s in ordered[i:]:
                    self._fail_completion_future(
                        s, RuntimeError("inbox-drain requeue cancelled during shutdown")
                    )
                raise
            except Exception as e:  # noqa: BLE001 -- detached path must not swallow
                log.exception("inbox-drain requeue failed for slot %s", slot.slot_id)
                self._fail_completion_future(slot, e)

    async def _requeue_slots_tail_or_fail(self, slots: "list[Slot]") -> None:
        """Re-enqueue a BATCH of a DESIGNATED VICTIM's own displaced work at the
        TAIL, in original order. The head path stays for non-victim evictions:
        the helper ``_requeue_slots_or_fail``
        above is the head-path variant and is exactly what non-victim inbox-drain uses. A
        victim's OWN displaced work must not cut back to the front of a line it
        was, by definition, the worst-priority client for; giving it head
        placement would silently undo the whole point of designating it.

        Uses ``queue.enqueue_tail`` (tail-appending), NOT ``enqueue_head`` --
        no iteration-reversal trick needed here, unlike ``_requeue_slots_or_fail``
        above: ``enqueue_tail`` APPENDS, so iterating ``slots`` in their given
        (oldest-first) order already lands them in that same relative order at
        the tail. Reversing it the way the head-requeue sibling must would be
        the actual bug here, not a fix.

        ⚠ NOT ``queue.enqueue`` (confirmed by tracing a real
        driven test):
        plain ``enqueue`` unconditionally re-transitions to STAGED, which is
        illegal on the input this helper actually receives -- every real
        inbox-drained slot IS already STAGED (pop_next pops an already-STAGED
        slot, _route_or_reserve hands it to r.inbox with no transition in
        between). ``queue.enqueue_tail`` exists specifically for this: a
        STAGED-guarded tail-insert that also deliberately drops the
        accept-buffer fallback plain ``enqueue`` has (see its own docstring --
        keeping that fallback would reproduce the identical illegal-transition
        bug one hop downstream, at one of 4+ call sites elsewhere in queue.py
        that assume everything in the accept buffer is genuinely
        ACCEPT_BUFFER).

        ``enqueue_tail`` can raise ``turbohaul.queue.QueueFull`` when staging
        is already at capacity (its documented failure mode), or
        ``QueueClosed`` at shutdown. Every slot that can't be re-enqueued has
        its future FAILED, never dropped -- same detached-path safety net as
        ``_requeue_slots_or_fail`` above.
        """
        for i, slot in enumerate(slots):
            self._unpark_fastlane_claim(slot)
            try:
                await self.queue.enqueue_tail(slot)
            except asyncio.CancelledError:
                for s in slots[i:]:
                    self._fail_completion_future(
                        s, RuntimeError("victim-eviction tail-requeue cancelled during shutdown")
                    )
                raise
            except Exception as e:  # noqa: BLE001 -- detached path must not swallow
                log.exception("victim-eviction tail-requeue failed for slot %s", slot.slot_id)
                self._fail_completion_future(slot, e)

    def _warn_if_reasoning_effort_mismatch(self, r: "Resident", slot: Slot) -> None:
        """First-caller-wins disclosure, log half:
        warns (at most once per distinct resident-instance + requested-value
        pair, same warn-once-and-cap shape as the
        ``warn_if_reasoning_budget_exceeds_ceiling`` in api/chat_completion.py
        -- an independent cache here, not a shared one, since this is a
        different module watching a different condition) when a request
        routed to an ALREADY-WARM resident asks for a ``reasoning_effort``
        that differs from the one locked in at spawn. Pure string compare
        against ``r.reasoning_effort_locked`` -- no manifest re-read, no I/O,
        safe to call on every warm-path hit. Never raises: best-effort
        observability, must not be able to break routing.
        """
        try:
            requested = (slot.client_meta or {}).get("reasoning_effort")
            if requested is None or requested == r.reasoning_effort_locked:
                return
            key = f"{r.resident_key}:{requested}"
            if key in self._reasoning_effort_mismatch_warned:
                return
            self._reasoning_effort_mismatch_warned.pop(key, None)
            self._reasoning_effort_mismatch_warned[key] = None
            while len(self._reasoning_effort_mismatch_warned) > _REASONING_EFFORT_MISMATCH_WARN_CAP:
                self._reasoning_effort_mismatch_warned.pop(
                    next(iter(self._reasoning_effort_mismatch_warned))
                )
            log.warning(
                "reasoning_effort=%r requested for model=%s but this resident's "
                "engine was already spawned with reasoning_effort=%r locked in "
                "(reasoning_budget_override=%s) -- first-caller-wins: "
                "this request gets the LOCKED value, not what it asked for, "
                "until the engine is reloaded",
                requested, r.model_tag, r.reasoning_effort_locked,
                r.reasoning_budget_override,
            )
        except Exception:
            log.debug(
                "reasoning_effort mismatch check failed (ignored)", exc_info=True,
            )

    # ★ Shield removal (retained dead code) --
    # DEAD: no caller remains. Retained, not deleted: this is the
    # legacy path and may be useful again in the future, so it is
    # kept in place and marked in the comments as dead code rather
    # than discarded.
    #
    # WHY dead: the listed-waiter shield clause it fed is gone
    # (a client with queued work that has not started is not
    # protected by that queue; it is protected by its rank, its
    # grace window, its cooldown -- and by nothing else),
    # together with its sole call site (the shielded_tags
    # computation in _route_or_reserve); the eviction decision no longer
    # consumes any carved-out set. NOT MAINTAINED -- do not re-add callers
    # or extend it; the TestShieldCarveoutUnit tests pin its current
    # behaviour and must keep passing while it stays. WHAT REPLACED IT:
    # nothing -- the eviction decision runs on the bare _lru_idle_unloadable
    # filter; the listed_waiter_priority_keys map it consumed survives as
    # the one-turn-guarantee data plane (queue.py).
    def _shield_carveout_tags(
        self,
        slot: "Slot",
        listed_waiter_tags: "set[str]",
        listed_waiter_priority_keys: "dict[str, tuple[int, int]]",
    ) -> "set[str]":
        """Carve OUT of the raw
        listed-waiter shield any tag where THIS claimant (``slot``, the
        request ``_route_or_reserve`` is currently placing) strictly
        outranks the BEST-RANKED QUEUED WAITER actually protecting that
        tag -- compared against the party the shield exists to protect
        (via ``queue.listed_waiter_priority_keys()``), never a resident's
        stale ``idle_client_meta`` holder, which would be the wrong party
        (a resident's tag can
        carry more than one listed client over its lifetime, so its last
        holder and the tag's current best queued waiter are two different
        parties).

        Call-site-local only -- does not touch ``_lru_idle_unloadable``,
        ``listed_waiter_model_tags``, ``_starvation_reason``, or
        ``_is_designated_unload_target_locked``. Those four functions are
        unchanged; this method only decides what SET gets passed to the
        first two at ``_route_or_reserve``'s two real make-room call
        sites, so their existing ``r.model_tag in listed_waiter_tags``
        filters do the actual excluding, unmodified.

        Condition (b) -- a shielded tag's resident must be genuinely
        IDLE_EVICTABLE -- is enforced downstream, unchanged, by
        ``_lru_idle_unloadable``'s own candidate filter (state check,
        active_slot, inflight, staleness); this method edits the TAG SET
        consulted there, never a resident directly, so it does not
        re-check resident state itself.

        Condition (c) -- STRICT MEMBERSHIP, never ``.get()``-then-compare
        (by design): a tag ABSENT
        from ``listed_waiter_priority_keys`` keeps its shield.
        ``listed_waiter_priority_keys()``'s own contract guarantees it
        never maps a tag to ``None`` -- an absent tag and an unresolvable
        value are never the same state, so branching on membership
        (``if tag not in ...: continue``) removes the dangerous
        ``.get()``-then-None-check shape from this code entirely, rather
        than relying on a value check next to it that a later edit could
        silently drop.

        An unresolvable/unlisted claimant (``slot.fastlane`` unset, so
        ``queue._fastlane_priority_key(slot)`` returns ``None``) has no
        priority basis to preempt anyone -- the raw shield stands
        entirely unchanged in that case, never partially carved.

        Nothing to carve with an empty shield set -- returned before even
        resolving the claimant's own key, so a slot with no ``.fastlane``
        support at all (a minimal test double exercising an unrelated path)
        is never touched when there is no listed waiter in play regardless.
        """
        if not listed_waiter_tags:
            return listed_waiter_tags
        claimant_key = self.queue._fastlane_priority_key(slot)
        if claimant_key is None:
            return listed_waiter_tags
        shielded = set(listed_waiter_tags)
        for tag in listed_waiter_tags:
            if tag not in listed_waiter_priority_keys:
                continue  # absent -> membership keeps the shield, never .get()
            if self.queue._fastlane_strictly_higher(
                claimant_key, listed_waiter_priority_keys[tag]
            ):
                shielded.discard(tag)
        return shielded

    def _restore_warm_recue_identity(
        self, idle_client_meta: "dict | None", idle_thread_id: "str | None", slot: Slot,
    ) -> None:
        """Port of _process_slot's guarded
        warm-inherit identity restoration onto the
        LIVE cap>=2 path. _process_slot is UNCALLED (worker_loop's fork is
        unconditionally `>= 1`, config.py declares `ge=1`) and stays that way --
        this is a separate call against an already-tested ALGORITHM, not a move.

        Same guard, same reason: a same-thread re-cue (lost its own
        session_id) or an explicit same-session match onto an idle-parked
        resident may have had its session_id/role/is_curator/... dropped --
        Fast Lane then ranks an unresolved identity to the bottom of the
        lane. Restore those fields from the resident's last
        PARKED occupant -- but never onto a request that already carries its
        OWN distinct identity classification (that would fuse two
        different clients' identities, a worse bug than the one fixed here).

        DATA SOURCE -- deliberately NOT the manager-global self._idle_*
        singleton _process_slot reads: `idle_client_meta`/`idle_thread_id`
        are the caller's Resident.idle_client_meta/.idle_thread_id, the
        per-resident mirror of that exact singleton. Both are stamped from
        `grace_tip` (sourced from the grace tip, not the raw
        anchor slot) inside _drive_resident's
        park block (manager.py), unconditionally, with zero
        `await` between the state flip to IDLE_EVICTABLE and the stamp --
        and _route_or_reserve's own routing decision (this method's callers)
        takes the SAME self._registry_lock that park block runs under, so
        any call here that finds a resident IDLE_EVICTABLE is provably
        observing state written strictly before the lock it needed to
        acquire was released. Never cleared back to None on reclaim
        (grepped) -- exactly the manager-global field's own lifecycle.

        Mutates slot.client_meta in place when it adopts; else a no-op.
        Never touches slot.thread_id, slot.context, or `messages` (the
        outbound source is slot.context, untouched here, same as the
        original -- see test_complete_messages_source.py).
        """
        if not idle_client_meta:
            return
        inc_cm = slot.client_meta if isinstance(slot.client_meta, dict) else {}
        inc_sid = inc_cm.get("session_id")
        idle_sid = (
            idle_client_meta.get("session_id")
            if isinstance(idle_client_meta, dict) else None
        )
        is_recue = (
            not inc_sid
            and bool(slot.thread_id)
            and slot.thread_id == idle_thread_id
        )
        is_same_session = inc_sid is not None and inc_sid == idle_sid
        if not (isinstance(idle_client_meta, dict) and (is_recue or is_same_session)):
            log.info(
                "warm re-cue: KEPT incoming client_meta (incoming "
                "session_id=%s != idle-holder session_id=%s, thread_id=%s != "
                "idle thread_id=%s) — no cross-caller identity clobber "
                "(same guard as the single-slot path)",
                inc_sid, idle_sid, slot.thread_id, idle_thread_id)
            return
        from turbohaul.kv_classify import _class_from_label
        idle_class = _class_from_label(idle_client_meta)
        inc_class = _class_from_label(inc_cm)
        inc_own_role = inc_cm.get("role") if inc_class is None else None
        inc_has_own_identity = inc_class is not None or bool(inc_own_role)
        if inc_has_own_identity and inc_class != idle_class:
            log.info(
                "warm re-cue: REFUSED identity-label copy (incoming "
                "already classified as %s, idle holder is %s, session_id=%s) "
                "— no cross-role clobber",
                inc_class or inc_own_role, idle_class,
                idle_sid if idle_sid is not None else "N/A",
            )
            return
        for k in (
            "session_id", "role", "is_main", "is_sub_agent",
            "is_curator", "is_compression",
        ):
            if k in idle_client_meta:
                inc_cm[k] = idle_client_meta[k]
        slot.client_meta = inc_cm
        log.debug(
            "warm re-cue: restored identity fields (session_id=%s) via "
            "%s", idle_sid if idle_sid is not None else "N/A",
            "re-cue" if is_recue else "same-session",
        )

    async def _route_or_reserve(self, slot: Slot) -> None:
        """ONE atomic _registry_lock critical section: HIT route / MISS+count-cap
        LRU-evict-then-reserve / MISS+VRAM-over-commit evict-idle-then-QUEUE /
        MISS+fits reserve / else bounded-defer. The IDLE_EVICTABLE->ACTIVE flip and
        the inbox.put are CO-LOCATED under the lock (closes the lost-slot race); the
        5s nvidia-smi is scoped to the MISS reserve/fit branches only.

        Make-room is driven by BOTH the model-COUNT cap AND the
        cross-resident VRAM-fit gate — decoupled. Under the count cap, a MISS the
        VRAM gate would refuse (a co-resident fills the target card) no longer
        silently fails: an idle LRU resident is evicted to free the card and the
        slot is QUEUED (the async teardown frees VRAM; the evict-pending backoff
        re-routes once the probe reflects it). Nothing evictable yet (the
        blocker is still ACTIVE/GRACE) -> QUEUE and retry after backoff, by which
        point the blocker may have gone idle-evictable. Under the current design,
        genuine sustained over-commit no longer exhausts
        and 503s -- the backoff is UNBOUNDED, the slot stays QUEUED for as
        long as the client stays connected (see _defer_unroutable's own
        docstring). The only thing that removes a queued slot now is the
        client disconnecting (queue.py's disconnect_event), never a silent
        HTTP 200/500 either way.

        The listed-waiter model_tag snapshot is taken under
        ``queue._lock`` BEFORE this method's own ``_registry_lock`` block --
        lock order ``queue._lock`` -> ``_registry_lock``, never reversed, and
        never an ``await queue._lock`` from inside ``_registry_lock``. This
        means the snapshot can go stale by the time the eviction decision
        runs; that is an accepted, bounded gap rather
        than something this change closes.
        """
        listed_waiter_tags = await self.queue.listed_waiter_model_tags()
        # Side-effect cache for _should_defer_admission -- same snapshot, same
        # staleness already accepted for its existing use two lines up; read the
        # class docstring on _cross_model_defer_hint before touching this line.
        # frozenset, not the plain set listed_waiter_model_tags() returns: this is
        # a SHARED cache read lock-free by other tasks, so it must never be
        # mutable-in-place under them.
        self._cross_model_defer_hint = frozenset(listed_waiter_tags)
        # ═══ WHY THE SYNC CALLS IN THIS BLOCK ARE AWAITED OFF THE LOOP ═══
        #
        # Several helpers called below (_effective_cap, _resolve_placement_locked,
        # _pick_card_for_new_instance, _vram_admits_locked) shell out to nvidia-smi via
        # safety.py's `subprocess.check_output(..., timeout=5)`. Called synchronously from
        # this async method, each probe would block THE ENTIRE EVENT LOOP for up to 5.0s,
        # and this block runs on every resident lifecycle event, so each is awaited via a thread.
        # A blocked loop starves every stream (api/live_stream.py bounds each await to <=1.0s):
        # the FE's SSE stream would emit nothing for several seconds across a model swap, so the
        # browser's EventSource would time out and reconnect. Without the thread hop, such gaps
        # would each start ON a lifecycle event.
        #
        # ⚠ THE LOCK IS NOT RELEASED BY THESE AWAITS. asyncio.Lock is held across an
        # await inside its own `async with` body, so every invariant _registry_lock
        # protects still holds for the whole block, and lock-hold time is the same as with a
        # blocking probe -- the lock stays held across the full probe. ⇒ THIS FREES THE
        # OBSERVERS, NOT THE CONTENDERS: the stream and /ws/state come back; admission
        # throughput is unaffected. Do not read a latency claim into this.
        #
        # ⛔ AND IT WITHDRAWS A PROPERTY NOBODY DESIGNED. With a blocking probe this critical
        # section is atomic with respect to EVERYTHING -- not because of the lock, but
        # because a blocked loop stops the whole process. That stall acts as
        # a de-facto global mutex, unwritten and unowned, for as long as the probe is
        # on the loop. Moving the probe off the loop removes that mutex. The one actor this
        # exposes is the await-free admit path (_priority_admit_from_inbox, which holds
        # NO lock), and it can interleave here. It cannot corrupt
        # anything read in this block -- every read-then-act symbol (r.state,
        # _residents, r.last_active_monotonic, _session_affinity, _pending_reclaim_mib)
        # is written only under _registry_lock, and this block's only inbox contact is
        # two atomic put_nowait calls with no read-then-act. But it IS ordering-visible:
        # which MECHANISM is credited with serving a slot can change.
        #
        # ◊ THREE CACHES ARE WRITTEN ON THE WORKER THREAD, and they are named here
        # because a list covering only what happened to be checked is how a hazard gets missed.
        # _effective_cap and _resolve_placement_locked reach
        # manifest.py's `_manifest_cache`, and `_hybrid_kv_announced` /
        # `_attn_dims_cache` on self. All three are single-key set/add/pop, atomic under
        # the GIL, and none is ever iterated or bulk-cleared in this package -- so a
        # lost check-then-act costs a duplicated parse or a duplicated log line, not
        # corruption. They are NOT "pure read", and this block must not be extended on
        # the assumption that they are.
        #
        # If you add a call in this block that reaches nvidia-smi, a manifest read, or
        # any other blocking syscall, wrap it the same way. The rule is stated in
        # `status_snapshot`'s contract.
        #
        # ⛔ NOT FIXED HERE:
        # _begin_unload_locked (called below) CANNOT be wrapped: it calls _spawn_bg, and
        # asyncio.create_task from a worker thread raises. Its lazy populate of
        # `_vram_total_mib` reaches _read_total_vram_all_mib -> nvidia-smi(timeout=5) ON
        # THE LOOP, so the unload/swap path still has one blocking probe that the
        # awaits above do not remove.
        #
        # ⚠ HOISTING THAT POPULATE to here, off-loop, before the
        # lock, is rejected: the existing code reaches
        # _read_total_vram_all_mib ONLY on an actual unload, so hoisting it would turn a
        # conditional probe into an UNCONDITIONAL nvidia-smi subprocess on every cold
        # admission (0 -> 1 real subprocess launches on a first admission
        # that unloads nothing). Moving a blocking call off the loop is in scope for
        # this block; ADDING one that never ran is not. The residual is stated
        # here instead of being traded for a new cost on the hot path.
        async with self._registry_lock:
            def _route_to(rr: "Resident") -> None:
                # Reclaim an idle instance to ACTIVE + hand the slot to its driver,
                # co-located under the lock — IDENTICAL to the legacy HIT below
                # (the IDLE_EVICTABLE flip + last_active + inbox.put_nowait). Caller
                # returns immediately after.
                # A barriered resident must not receive a new inbox
                # arrival -- it would lose disconnect interception for the whole
                # hold (riders would lose disconnect interception).
                # Defer instead, with the SAME bounded budget the evict-pending
                # regime already gives a genuinely-queued slot.
                if rr.spawn_barrier_active:
                    self._defer_unroutable(slot, evict_pending=True)
                    return
                if rr.state is ResidentState.IDLE_EVICTABLE:
                    _transition_resident_state(rr.state, ResidentState.ACTIVE)
                    rr.state = ResidentState.ACTIVE
                rr.last_active_monotonic = time.monotonic()
                # Restore session_id/role/is_curator/...
                # onto slot.client_meta from whoever rr last parked as, BEFORE
                # rank_client_meta is stamped below -- a guarded same-thread/
                # same-session adoption only, never a cross-client clobber.
                # SYNC HAZARD: this call and its
                # twin in the direct HIT branch below (variable `r`) are
                # byte-identical apart from the local name (`rr` here, `r`
                # there) -- same behavior, two call sites. A future edit to one
                # without the other silently reintroduces the identity-clobber bug on whichever
                # twin was missed. Keep them in sync.
                self._restore_warm_recue_identity(
                    rr.idle_client_meta, rr.idle_thread_id, slot,
                )
                # rank_client_meta names the client of the turn running now, so it
                # is stamped when this slot's own turn starts, not here.
                self._warn_if_reasoning_effort_mismatch(rr, slot)
                if rr.inbox is not None:
                    rr.inbox.put_nowait(slot)
                # The slot waits in rr's inbox: keep its claim until its own turn
                # starts (no-op if it never held one).
                self._park_fastlane_claim_locked(slot, rr)
                # The hand-off is not the end of the
                # wait -- keep the claimant on the queue surface until it is
                # actually served.
                self._note_handed_off_waiting(slot)

            # Multi-instance-per-tag routing. GATED so a tag with at most one live
            # instance and no one-card-per-engine placement falls straight through to
            # the legacy single-instance path below, byte-identically.
            tag = slot.model_tag
            insts = self._instances_for(tag)
            # OFF-LOOP: _effective_cap reads the manifest (disk I/O) and, while a
            # sidecar slot is free, reaches _cards_that_fit -> _card_avail_mib ->
            # nvidia-smi. It runs for every route including the default HIT path:
            # when the box budget is spent it returns before any probe (see its
            # docstring). A thread hop is ~tens of microseconds against the 5.0s
            # block being removed, and the manifest stat leaves the loop with it.
            # The placement answer used below reads the same manifest, so it is
            # computed in this same hop (_route_cap_and_placement), not by a second
            # read on the loop.
            eff_cap, _wants_parallel = await asyncio.to_thread(
                self._route_cap_and_placement, tag
            )
            # Also enter the multi-instance branch when a tag's ONLY live instance
            # is a non-idx0 engine (resident_key != model_tag) -- e.g. idx0 was
            # evicted/died first while idx1 survives and eff_cap collapsed to 1.
            # Without this the legacy HIT (get(model_tag)) misses the live tag#N
            # engine -> spurious 503 / redundant respawn.
            # (any(off-key) subsumes len(insts)>1; kept explicit for readability.)
            # The engine count and the placement path are different questions.
            # eff_cap is an ENGINE-BUDGET number: with a free sidecar slot in the
            # box-wide budget it is above 1 for a one-card-per-engine tag whose
            # model fits a second card; any other tag gets the engines it runs, at
            # least 1. Entering the multi-instance PLACEMENT branch on that number
            # alone sent a single-instance, placement-free manifest down the
            # multi-instance path, where it gained a `--main-gpu` it never had
            # (see the pinned-not-relocated argv byte-identity control test).
            #
            # So the branch is gated on placement intent, not on the budget: only a
            # one-card-per-engine manifest (_wants_one_card_per_engine), or a tag
            # that already runs more than one engine, or a survivor whose only live
            # engine is a non-idx0 key enters it. That includes a cold start of a
            # one-card-per-engine tag, so its first engine is registered with the
            # session's affinity and the next request of the session sticks to it.
            # The branch's spawn step honours a Fast Lane relocation target the
            # same way the single-engine path does. A placement-free or
            # card-spanning manifest, even when the budget admits another engine,
            # keeps the legacy path, where a single engine's placement is resolved
            # as before. The placement answer comes from the cached manifest read
            # inside the worker-thread call above; an unreadable manifest falls back
            # to entering the branch on the cap alone (eff_cap > 1).
            if _wants_parallel or len(insts) > 1 or any(i.resident_key != tag for i in insts):
                # 1. STICKY: keep a session pinned to its engine instance (in-engine
                # slot + port-stable disk KV bin reuse). Re-check the mapped resident
                # is present + not DEAD; a stale/dead mapping is dropped so the session
                # re-homes this tick.
                rk = self._sticky_resident_key(slot, tag)
                if rk:
                    rr = self._residents.get(rk)
                    if rr is not None and rr.state is not ResidentState.DEAD:
                        _route_to(rr)
                        return
                    self._drop_affinity(slot, tag)
                # 2. SPAWN a new instance if under the effective cap AND it fits on a
                # card (preferring a card not already hosting this tag — even
                # 1-per-card split). need/parallel from the resolver; the card + split
                # come from _pick_card_for_new_instance and OVERRIDE the resolver's
                # auto-pick for both the fit-gate and the Resident.
                # The branch must also respect the box-wide budget by its own count,
                # as the single-engine path does (at_count_cap): eff_cap already
                # reflects the budget unless its manifest read failed and it fell
                # back to 1 while this path's own read succeeded. Without the count a
                # cold tag would then start an engine past the budget instead of
                # making room.
                if (
                    len(insts) < eff_cap
                    and len(self._model_residents()) < self.runtime.queue.max_parallel_sidecars
                ):
                    # All three OFF-LOOP -- each reaches nvidia-smi
                    # (via _auto_pick_gpu, _card_avail_mib and _vram_budget
                    # respectively). See the block comment at the top of this method.
                    need, parallel, _mg, _sm, _sleep, _auto, _ = (
                        await asyncio.to_thread(self._resolve_placement_locked, tag)
                    )
                    g, sp = await asyncio.to_thread(
                        self._pick_card_for_new_instance, tag, need
                    )
                    # A Fast Lane relocation chosen for this request decides the
                    # card of a COLD start, exactly as on the single-engine path
                    # below. A tag that already has an engine keeps the picker's
                    # choice, so a second copy never lands on a card that already
                    # hosts one.
                    if slot.fastlane_relocated_main_gpu is not None and not insts:
                        g = slot.fastlane_relocated_main_gpu
                        sp = slot.fastlane_relocated_split_mode
                    if g is not None and await asyncio.to_thread(
                        self._vram_admits_locked, need, parallel, g, sp
                    ):
                        newr = await self._reserve_and_start_locked(
                            slot, main_gpu_override=g, split_mode_override=sp
                        )
                        if newr is not None:
                            self._remember_affinity(
                                tag, self._session_key_for(slot), newr.resident_key
                            )
                        return
                # 3. Cap reached / next instance doesn't fit -> route to the
                # LEAST-LOADED existing instance (records affinity). Requests beyond
                # what serves now QUEUE in that instance's inbox (graceful
                # count-degradation, no OOM, no hard 503).
                if insts:
                    chosen = self._pick_instance_for(slot, tag, insts)
                    if chosen is not None:
                        _route_to(chosen)
                        return
                # 4. No live instance yet AND can't spawn (VRAM over-committed by
                # ANOTHER model) -> fall through to the legacy cold-start /
                # evict-then-defer path UNCHANGED.
                # What that legacy path does about cards: _resolve_placement_locked
                # places the model. For a manifest with split_mode none that is
                # auto-placed (auto_place set, or the fast lane on), _auto_pick_gpu
                # prefers a single card that fits (the most-free one), and returns a
                # layer span across every card only when no single card fits but the
                # cards together do. When the placer does not land on one card, the
                # reclaim-first decision (_reclaim_first_card_locked) runs next: it
                # picks one card that has something to reclaim and fits (keeping the
                # safety floor free, like the placer's own pick) once that card's idle
                # models are counted as free. A layer split is kept only when no
                # single card fits even with that. The make-room step further down
                # then unloads an idle resident on the decided card only (the
                # "fastlane_reclaim_first" branch),
                # and only when the placement does not fit yet (the "if vram_fits"
                # branch returns before it). A card the placer finds free now needs no
                # unload: the decision does not run for it. By contrast
                # _pick_card_for_new_instance (step 2 above) never spans.
            r = self._live_resident_for(slot.model_tag)
            if r is not None:
                # Same guard as _route_to above -- the legacy
                # single-instance HIT is a second, separate site that would
                # otherwise inbox a same-tag arrival onto a barriered resident.
                if r.spawn_barrier_active:
                    self._defer_unroutable(slot, evict_pending=True)
                    return
                # HIT: reclaim from idle + hand to the driver, all under the lock.
                if r.state is ResidentState.IDLE_EVICTABLE:
                    _transition_resident_state(r.state, ResidentState.ACTIVE)
                    r.state = ResidentState.ACTIVE
                r.last_active_monotonic = time.monotonic()
                # Restore session_id/role/is_curator/...
                # onto slot.client_meta from whoever r last parked as, BEFORE
                # rank_client_meta is stamped below -- a guarded same-thread/
                # same-session adoption only, never a cross-client clobber.
                # SYNC HAZARD: this call and its
                # twin in the _route_to closure above (variable `rr`)
                # are byte-identical apart from the local name (`r` here, `rr`
                # there) -- same behavior, two call sites. A future edit to one
                # without the other silently reintroduces the identity-clobber bug on whichever
                # twin was missed. Keep them in sync.
                self._restore_warm_recue_identity(
                    r.idle_client_meta, r.idle_thread_id, slot,
                )
                # rank_client_meta names the client of the turn running now, so it
                # is stamped when this slot's own turn starts, not here.
                self._warn_if_reasoning_effort_mismatch(r, slot)
                if r.inbox is not None:
                    r.inbox.put_nowait(slot)
                # The slot waits in r's inbox: keep its claim until its own turn
                # starts (no-op if it never held one).
                self._park_fastlane_claim_locked(slot, r)
                # The hand-off is not the end of the
                # wait -- keep the claimant on the queue surface until it is
                # actually served.
                self._note_handed_off_waiting(slot)
                return
            cap = self.runtime.queue.max_parallel_sidecars
            at_count_cap = len(self._model_residents()) >= cap
            # Resolve the EFFECTIVE placement (footprint + auto-placer's card) ONCE,
            # under the lock, so the fit check targets the SAME card the reserve will
            # use. This also lets us distinguish a pure model-COUNT
            # cap from a cross-resident VRAM over-commit — they need different make-room
            # paths (in-band reserve vs evict-then-QUEUE).
            # OFF-LOOP -- reaches _auto_pick_gpu -> nvidia-smi.
            (
                need, parallel, main_gpu, split_mode, _sleep_idle_s,
                _auto_place, _auto_picked,
            ) = await asyncio.to_thread(
                self._resolve_placement_locked, slot.model_tag
            )
            # Reclaim-first: for a request the auto-placer decides, when the
            # placer did not land on one card (it returned a layer span, or
            # nothing fit and the manifest pin was kept), look for ONE card
            # that fits once its idle residents are unloaded; only when there is
            # none does today's placement stand. The decision is taken again on
            # every pass, so it is never sticky: the override it sets is cleared
            # as soon as it no longer holds. An override set by the eviction
            # path below (the flag is not set) is left alone.
            # This pass's reclaim-first decision, if there is one.
            choice = None
            reclaim_first_scope = self._reclaim_first_applies(
                slot, _auto_place, _auto_picked, split_mode)
            reclaim_first_due = reclaim_first_scope and not (
                _auto_picked and split_mode == "none")
            if (
                getattr(slot, "fastlane_reclaim_first", False)
                and not reclaim_first_due
            ):
                # The placer now lands on one card by itself (or the request
                # is out of scope): its card stands, so drop our override.
                slot.fastlane_relocated_main_gpu = None
                slot.fastlane_relocated_split_mode = None
                slot.fastlane_reclaim_first = False
            elif reclaim_first_due and (
                slot.fastlane_relocated_main_gpu is None
                or getattr(slot, "fastlane_reclaim_first", False)
            ):
                # The rule table is read here, on the event loop: it can
                # recompile and write a cache, which the worker thread must not.
                fastlane_table = self._fastlane_table()
                choice = await asyncio.to_thread(
                    self._reclaim_first_card_locked, slot, need, parallel,
                    fastlane_table,
                )
                if choice is not None:
                    if not (
                        getattr(slot, "fastlane_reclaim_first", False)
                        and slot.fastlane_relocated_main_gpu == choice.card
                    ):
                        log.info(
                            "reclaim_first claimant=%s card=%s "
                            "reclaimable_mib=%d pending_mib=%d need_mib=%d",
                            slot.model_tag, choice.card,
                            choice.reclaimable_mib, choice.pending_mib, need,
                        )
                    slot.fastlane_relocated_main_gpu = choice.card
                    slot.fastlane_relocated_split_mode = "none"
                    slot.fastlane_reclaim_first = True
                elif getattr(slot, "fastlane_reclaim_first", False):
                    # The decision no longer holds: back to today's placement.
                    slot.fastlane_relocated_main_gpu = None
                    slot.fastlane_relocated_split_mode = None
                    slot.fastlane_reclaim_first = False
            # A prior pass on THIS slot already evicted a
            # cross-card victim for a Fast Lane claim (see the eviction gate below) -- target
            # the freed card on this and every subsequent retry, overriding the
            # manifest's own pin. None (the overwhelming common case) leaves
            # main_gpu/split_mode exactly as _resolve_placement_locked returned.
            if slot.fastlane_relocated_main_gpu is not None:
                main_gpu = slot.fastlane_relocated_main_gpu
                split_mode = slot.fastlane_relocated_split_mode
            # OFF-LOOP -- reaches _vram_budget -> nvidia-smi.
            vram_fits = await asyncio.to_thread(
                self._vram_admits_locked, need, parallel, main_gpu, split_mode
            )
            if at_count_cap and vram_fits:
                # Pure model-COUNT cap (VRAM has room): a registry slot must free.
                # Evicting ANY idle resident frees a count slot synchronously, so the
                # reserve proceeds in-band (VRAM already fits alongside the dying
                # victim) — the original count-cap behavior, preserved.
                if getattr(slot, "fastlane_reclaim_first", False):
                    # The decision pinned a card, so the victim is looked up
                    # for that card while memory has to be freed, otherwise
                    # any idle resident frees the count slot. The claimant is
                    # queued, never reserved in-band.
                    self._unload_on_decided_card_locked(
                        slot, main_gpu, split_mode, choice,
                        "make_room_count_cap", "make_room_starved_count_cap",
                        frees_count_slot=True)
                    return
                victim = self._lru_idle_unloadable()
                if victim is None:
                    attribution = self._starvation_reason()
                    self._log_make_room_starved(
                        slot, "make_room_starved_count_cap", attribution)
                    self._defer_unroutable(slot)
                    return
                self._log_make_room_unload(victim, "make_room_count_cap")
                self._begin_unload_locked(victim)
                await self._reserve_and_start_locked(
                    slot,
                    main_gpu_override=slot.fastlane_relocated_main_gpu,
                    split_mode_override=slot.fastlane_relocated_split_mode,
                )
                return
            if vram_fits:
                if getattr(slot, "fastlane_reclaim_first", False):
                    # A claimant pinned to a card does not start in this arm.
                    # The idle model on its decided card is unloaded (once,
                    # and only while the decision still has memory to free)
                    # and the claimant waits for the next pass. When the card
                    # has room the placer lands it there, the pin is cleared
                    # and the normal start below runs.
                    self._unload_on_decided_card_locked(
                        slot, main_gpu, split_mode, choice,
                        "make_room_vram", "make_room_starved_vram")
                    return
                # under cap + fits, no make-room -- override is a no-op unless a
                # prior pass relocated this slot
                await self._reserve_and_start_locked(
                    slot,
                    main_gpu_override=slot.fastlane_relocated_main_gpu,
                    split_mode_override=slot.fastlane_relocated_split_mode,
                )
                return
            # UNREACHABLE: the guard below needs the
            # manager-level idle holder populated (cap<=1) AND `_route_or_reserve`
            # running (cap>=2). MUTUALLY EXCLUSIVE by construction:
            # `_idle_handle` is written by `_set_idle_holder` only, which is
            # called by `_process_slot` only, which is called by
            # `worker_loop` BELOW the cap fork -- so cap<=1 ONLY.
            # `_route_or_reserve` is called by `_dispatch_loop` only, which
            # is reached from `worker_loop` INSIDE `if cap >= 2:`.
            # RETAINED, NOT DELETED: dead code is kept in place and marked as such.
            # NOT MAINTAINED. Becomes correct if the holder is ever populated at
            # cap>=2 (e.g. a future IDLE_EVICTABLE->manager-level promotion).
            # Insufficient space. If an idle holder is occupying
            # VRAM, tear it down immediately — unload the idle
            # model and its engine at once and load the new model right away.
            # Same-model
            # follow-ups HIT the resident and bypass this gate entirely,
            # so warm-inherit is preserved by construction (negative control).
            # Admission waits on VRAM-CONFIRMED — the evict-then-queue path below
            # retries once the freed VRAM shows up in the probe.
            if self._idle_handle is not None:
                idle_tag = self._idle_model_tag
                idle_tid = self._idle_thread_id or "?"
                log.info(
                    "idle_holder_vram_release reason=insufficient_space "
                    "model_tag=%s thread_id=%s",
                    idle_tag, idle_tid,
                )
                await self._teardown_idle_holder("insufficient_space")
            # Cross-resident VRAM over-commit (WITH or WITHOUT the count cap).
            # NEVER reserve in-band here. _begin_unload_locked frees the
            # victim's VRAM only ASYNC (its detached teardown even contends for THIS
            # _registry_lock), so an in-band reserve's gate would refuse -> 503 while a
            # warm resident was killed. Evict-then-QUEUE instead; the evict-pending
            # backoff re-routes once the freed VRAM shows up in the probe.
            # Only evict if even the teardowns ALREADY in flight
            # (pending-reclaim credited) won't free enough, so N concurrent misses
            # don't each evict a resident. Card-aware victim (no off-card evict).
            # The settle window rate-limits additional evictions for THIS slot.
            # The pending-credit rule governs the eviction DECISION: evict another idle resident
            # ONLY when even the reclaim ALREADY in flight (credit_pending) won't cover
            # the need. projected_fits=False both PROVES a further eviction is necessary
            # AND guarantees it can't over-evict (each eviction credits its reclaim, so
            # the next pass stops the instant enough is pending) — so no fixed settle
            # timer (which would wrongly BLOCK a necessary multi-victim eviction).
            # relocatable=_auto_place credits AGGREGATE pending (the
            # global-LRU eviction scope used for auto_place) so concurrent auto_place
            # misses see each other's in-flight reclaim.
            # OFF-LOOP. This is the branch that reaches
            # _vram_admits_locked's `_read_free_vram_all_mib() or
            # _read_free_vram_all_mib()` flake-retry -- a 10.0s worst case on ONE line,
            # and a plausible cause of multi-second stream gaps.
            # A slot on the reclaim-first card is not relocatable: its card is
            # fixed, and the decision counted that card's own pending credit
            # only, so another card's credit must not hide the unload.
            projected_fits = await asyncio.to_thread(
                self._vram_admits_locked,
                need, parallel, main_gpu, split_mode,
                credit_pending=True,
                relocatable=_auto_place and not getattr(
                    slot, "fastlane_reclaim_first", False))
            if not projected_fits:
                # Card filter: pin the victim to the TARGET card only for a
                # non-auto_place (truly pinned) model. Reaching this quadrant with
                # auto_place=True means _auto_pick_gpu already returned None (no card
                # fits), so main_gpu is merely the manifest FALLBACK pin — freeing ANY
                # card lets the re-route auto-placer relocate the model, so evict
                # global-LRU (main_gpu=None), as the base code did.
                if getattr(slot, "fastlane_reclaim_first", False):
                    # The reclaim-first decision picked this card because it fits
                    # once its idle residents are unloaded, so the victim is
                    # looked up for that card (main_gpu is the override here):
                    # an idle resident on it, or a layer-split one, which spans
                    # every card. A split-none victim on another card would free
                    # nothing for it, and no rank test is applied. None ->
                    # nothing is unloaded on this pass.
                    victim = self._lru_idle_unloadable(
                        main_gpu=main_gpu, split_mode=split_mode)
                elif _auto_place:
                    # The auto_place arm carries the SAME
                    # eviction-rank gate the pinned arm gets below (shared helper,
                    # one rule for any claimant). A LISTED auto_place claimant
                    # that does NOT strictly outrank the global-worst
                    # idle-evictable resident has no rank-based claim on it,
                    # so eviction is limited to its own card (main_gpu)
                    # -- the same narrowing the pinned branch applies. A claim
                    # that DOES outrank still evicts globally and sets no
                    # relocation override: the re-routing auto-placer re-picks
                    # the card on the evict-pending retry --
                    # freeing any card suffices for an auto-placed model.
                    victim = self._fastlane_outrank_unload_target_locked(
                        slot, split_mode)
                    if victim is None:
                        if self.queue._fastlane_priority_key(slot) is None:
                            # No live claim at all: ordinary non-Fast-Lane
                            # capacity eviction -- the original unconditional
                            # global scope, byte-identical to before
                            # (the auto_place unchanged-path test pins
                            # this arm).
                            victim = self._lru_idle_unloadable(
                                split_mode=split_mode)
                        else:
                            # Listed claim that did not outrank the global
                            # candidate: on-card-only scope, same as the
                            # pinned branch below.
                            victim = self._lru_idle_unloadable(
                                main_gpu=main_gpu, split_mode=split_mode)
                else:
                    # A live Fast Lane claim that STRICTLY
                    # OUTRANKS the globally worst-ranked idle-evictable resident
                    # selects that resident even off this claimant's own manifest
                    # card (Fast Lane overrides that selection -- the
                    # same global scope the auto_place arm's outranking claim
                    # gets, now via the shared gate). No live claim, or one
                    # that does not outrank the global candidate, falls through
                    # to today's on-card-only scope unchanged --
                    # ordinary manifest-pinned traffic never gets cross-card
                    # eviction authority it never had, and a claim that can't
                    # win globally can't win on-card either (the global set
                    # strictly contains the on-card one). The gate itself (and
                    # the unlisted-candidate rule it carries) lives
                    # in _fastlane_outrank_unload_target_locked.
                    victim = self._fastlane_outrank_unload_target_locked(
                        slot, split_mode)
                    if victim is not None and victim.main_gpu != main_gpu:
                        # Relocate the claimant onto the card
                        # this eviction frees (wired through the retry
                        # via main_gpu_override/split_mode_override)
                        # -- only when the victim
                        # is actually on a different card, so the
                        # common on-card-already case sets no override
                        # and changes no behaviour.
                        slot.fastlane_relocated_main_gpu = victim.main_gpu
                        # The CLAIMANT's own resolved split_mode, not
                        # the victim's. The relocation moves the claimant onto the
                        # freed CARD; it says nothing about adopting the victim's
                        # split topology, which is a property of the claimant's
                        # own model. Nothing constrained the two to agree:
                        # _fastlane_outrank_unload_target_locked looks the candidate up
                        # with main_gpu=None and _lru_idle_unloadable's
                        # card/split filter is gated on `main_gpu is not None`,
                        # so on the global widening lookup it is skipped
                        # and the victim may be layer-split. Copying it wrote a
                        # foreign topology into the claimant's VRAM gate
                        # and, once argv follows the admitted placement
                        # (_spawn_for_resident), would have spawned a
                        # tensor-isolated model spanning every card (or confined
                        # a card-spanning one to a single card). Idempotent
                        # across retries: the VRAM gate feeds this same value back in.
                        slot.fastlane_relocated_split_mode = split_mode
                    if victim is None:
                        victim = self._lru_idle_unloadable(
                            main_gpu=main_gpu, split_mode=split_mode)
                if victim is not None:
                    self._log_make_room_unload(victim, "make_room_vram")
                    self._begin_unload_locked(victim)
                else:
                    # A request the reclaim-first decision covers looks at every
                    # card (the decided card first), like an auto_place one, so
                    # the attribution covers every card too; any other request
                    # only ever looked at its own card.
                    all_cards = _auto_place or reclaim_first_scope
                    attribution = self._starvation_reason(
                        main_gpu=None if all_cards else main_gpu,
                        split_mode=split_mode)
                    # That value names a protection that no longer exists. With
                    # the all-cards scope it can come back when the decided card
                    # has no idle victim while another card does; the
                    # per-resident list carries the real reason, so do not log it.
                    if attribution.get("why") == (
                        "all candidates protected as listed waiters"
                    ):
                        attribution["why"] = "reason_unknown"
                    attribution["card_scope"] = (
                        "all" if all_cards else f"card{main_gpu}")
                    self._log_make_room_starved(
                        slot, "make_room_starved_vram", attribution)
            self._defer_unroutable(slot, evict_pending=True)
            return

    async def _reserve_and_start_locked(
        self,
        slot: Slot,
        main_gpu_override: "int | None" = None,
        split_mode_override: "str | None" = None,
    ) -> "Resident | None":
        """CALLER HOLDS _registry_lock. Read the model footprint, run the
        cross-resident VRAM gate, alloc a port, insert a RESERVED_LOADING
        placeholder (reserving its budget against concurrent reserves), and start
        its driver. The slow spawn+health happen OUTSIDE the lock inside the driver
        (the placeholder already reserves the budget).

        When ``main_gpu_override`` / ``split_mode_override`` are
        given (spawning a tag's Nth engine onto a specific card picked by
        _pick_card_for_new_instance), they REPLACE _resolve_placement_locked's
        auto-picked card for BOTH the Resident's main_gpu/split_mode AND the
        _vram_admits_locked gate (need/parallel/sleep_idle still come from the
        resolver). Returns the created Resident (so the caller can read resident_key for
        the affinity map) or None if the VRAM gate deferred (requeued) the slot --
        it is no longer a refusal, see the gate's
        own comment below. The legacy _route_or_reserve callers pass no overrides and
        ignore the return -> byte-identical."""
        # OFF-LOOP -- reaches _auto_pick_gpu -> nvidia-smi. This
        # method is async and CALLER HOLDS _registry_lock, so the await keeps the lock
        # (see _route_or_reserve's block comment) and only frees the loop.
        need, parallel, main_gpu, split_mode, sleep_idle_s, _auto_place, _auto_picked = (
            await asyncio.to_thread(self._resolve_placement_locked, slot.model_tag)
        )
        # Record PROVENANCE alongside the value. Both the argv build
        # and the spawn safety gate need to know whether this resident's
        # placement came from the manifest verbatim or was overridden here;
        # manifest.auto_place is no longer a complete test for that (see
        # Resident.placement_overridden).
        placement_overridden = (
            main_gpu_override is not None
            or split_mode_override is not None
            # The resolver's own auto-pick is a THIRD producer of a
            # changed placement and set no bit, so both consumers kept the
            # MANIFEST's card while this method reserved and gated the RESOLVED
            # one -- the same hazard, for a new producer.
            or _auto_picked
        )
        if main_gpu_override is not None:
            main_gpu = main_gpu_override
        if split_mode_override is not None:
            split_mode = split_mode_override
        # OFF-LOOP -- reaches _vram_budget -> nvidia-smi.
        if not await asyncio.to_thread(
            self._vram_admits_locked, need, parallel, main_gpu, split_mode
        ):
            # REQUEUE, not refuse (a slot that cannot be admitted yet must wait).
            # The request is not cancelled: it is
            # requeued, and if VRAM is not free yet it simply waits a moment.
            # This is the narrow residual case
            # (a count-cap in-band reserve whose freed card
            # has not yet released VRAM, or a probe that flipped the card
            # between the pre-check and here) -- a race against the settle
            # window (a short interval), not a hard capacity ceiling.
            # Safe to requeue here specifically BECAUSE of two mechanisms in the
            # teardown path: the first is
            # the post-teardown wake (a _make_room_signal notify, see
            # _unload_teardown) at the VRAM-CONFIRMED teardown seam, and
            # the second is the predicate that keeps that wake
            # reachable on split-card models.
            # _defer_unroutable's own requeue path (_requeue_after_backoff /
            # _wait_for_park_or_timeout) listens on that exact signal -- so a
            # slot parked here now gets woken the instant the card actually
            # clears, not just on its own backoff tick. Without those two
            # mechanisms, requeuing here could park a request nothing
            # would ever wake.
            # Both mechanisms are required for this requeue to be safe.
            # Reuses _defer_unroutable's own funnel ("the
            # single funnel... so both flow through one path with no risk of
            # drifting apart") rather than a bespoke requeue -- evict_pending
            # is the semantically correct regime: an eviction was already
            # begun for this reserve attempt, we are waiting on ITS teardown
            # to actually clear, which is exactly what that regime's 1s
            # backoff + post-teardown wake already exist for. _defer_unroutable is
            # synchronous (no await) and already called from other
            # _registry_lock-held contexts (_route_or_reserve) -- calling it
            # here introduces no new await and no new lock acquisition.
            log.info(
                "cross-resident VRAM gate deferred (not refused) spawn for %s "
                "(need=%dMiB parallel=%d gpu=%d split=%s) -- requeued, "
                "awaiting VRAM-confirmed teardown wake",
                slot.model_tag, need, parallel, main_gpu, split_mode,
            )
            self._defer_unroutable(slot, evict_pending=True)
            return
        port = self._alloc_port()
        # Resolve the FIRST caller's reasoning_effort
        # against this model's manifest reasoning_budget, ONCE, here at
        # reservation -- identical hazard/shape to main_gpu/split_mode above.
        # `slot` is the request that triggered this reservation (as the
        # docstring below confirms _drive_resident awaits this exact
        # slot first out of r.inbox), so this genuinely is the first caller,
        # not an arbitrary one. Local/deferred import: manager.py already
        # imports from api/chat_completion.py this way in five other places
        # (_COMMON_FORWARDED_KNOBS, _strip_thinking_all x3, wrap_reasoning_
        # think) -- reusing that channel, not inventing a new one. Degrades
        # to None (no override) on a manifest read failure here, same
        # degrade-open posture _read_model_footprint already has for a
        # missing manifest -- this is a best-effort override, not a gate.
        from turbohaul.api.chat_completion import resolve_reasoning_budget_for_spawn
        reasoning_budget_override = None
        _requested_effort_key = (slot.client_meta or {}).get("reasoning_effort")
        try:
            # OFF-LOOP. The UNCACHED read_manifest -- stat +
            # read_text + yaml.safe_load + a full pydantic validate -- ran on the
            # event loop under _registry_lock. Same hazard class as the probes and
            # named explicitly by the rule this method's block comment adds; it is
            # easy to overlook.
            _rm = await asyncio.to_thread(
                read_manifest, self.boot.storage.manifests_path, slot.model_tag
            )
            _rb = (_rm.llama_server_flags or {}).get("reasoning_budget", 0)
            reasoning_budget_override = resolve_reasoning_budget_for_spawn(
                _requested_effort_key, _rb,
            )
        except Exception:
            log.debug(
                "reasoning_budget_override resolution failed for %s (ignored, "
                "spawning with manifest's own reasoning_budget unmodified)",
                slot.model_tag, exc_info=True,
            )
        # One clock read, shared by both stamps
        # below -- last_active_monotonic (drifts forward on every later
        # ACTIVE transition) and reserved_at_monotonic (never touched again
        # after this line) must agree on the exact admission instant, not
        # read two independent monotonic() calls a few cycles apart.
        _reserved_at = time.monotonic()
        r = Resident(
            model_tag=slot.model_tag,
            port=port,
            state=ResidentState.RESERVED_LOADING,
            reserved_need_mib=need,
            parallel=parallel,
            main_gpu=main_gpu,
            split_mode=split_mode,
            placement_overridden=placement_overridden,
            reasoning_budget_override=reasoning_budget_override,
            reasoning_effort_locked=(
                _requested_effort_key if reasoning_budget_override is not None else None
            ),
            sleep_idle_seconds=sleep_idle_s,
            last_active_monotonic=_reserved_at,
            reserved_at_monotonic=_reserved_at,
            # Reserve is this resident's FIRST turn -- stamp the
            # triggering slot's client now, so claim-driven designation can
            # resolve it even before it has ever parked (idle_client_meta
            # stays None until then).
            rank_client_meta=slot.client_meta,
            grace=GraceTimer(
                grace_seconds=self.runtime.queue.grace_seconds,
                max_extensions=self.runtime.queue.max_grace_extensions,
            ),
            idle=IdleHotTimer(
                idle_seconds=self.runtime.queue.idle_hot_load_seconds
            ),
            inbox=asyncio.Queue(),
        )
        r.inbox.put_nowait(slot)  # the slot that triggered the reservation
        # Key by resident_key. instance_idx == 0 => resident_key
        # == model_tag (NO suffix) so the default single-instance case is stored,
        # read (get(model_tag)) and deleted (del [model_tag]) byte-identically to
        # before; the Nth (N>=1) engine of a multi-instance tag gets model_tag#N.
        # "Next free idx" (not a bare count) fills the lowest free ordinal so a
        # surviving higher-index sibling is never overwritten after a lower-index
        # instance is evicted/died and deregistered.
        existing_keys = {ex.resident_key for ex in self._instances_for(slot.model_tag)}
        idx = 0
        while (slot.model_tag if idx == 0 else f"{slot.model_tag}#{idx}") in existing_keys:
            idx += 1
        rk = slot.model_tag if idx == 0 else f"{slot.model_tag}#{idx}"
        r.instance_idx = idx
        r.resident_key = rk
        self._residents[rk] = r
        r.driver_task = asyncio.create_task(self._drive_resident(r))
        r.driver_task.add_done_callback(
            lambda t, rr=r: self._on_driver_done(rr, t)
        )
        # The slot waits in the new engine's inbox while it spawns: keep its
        # claim until its own turn starts (it may still be handed to another
        # engine if this one is refused).
        self._park_fastlane_claim_locked(slot, r)
        # This is the LONGEST of the three invisible
        # windows -- the claimant now waits out a whole cold spawn plus the
        # health probe before its first token, with no row on any surface.
        self._note_handed_off_waiting(slot)
        return r

    def _legacy_reserve_vram_gate_refusal(
        self, slot: Slot, *, need: int, parallel: int, main_gpu: int,
        split_mode: str,
    ) -> None:
        """UNCALLED as of v0.8.0.
        RETAINED, NOT DELETED: dead code is kept in place and marked as such
        (see `_legacy_defer_exhaustion_refusal`'s docstring for the
        reasoning -- same reasoning, applied here a second time).

        WHY unreachable: this was `_reserve_and_start_locked`'s own
        "LAST-RESORT refuse" -- the narrow residual case where the
        cross-resident VRAM gate still refuses at reserve time (a count-cap
        in-band reserve whose freed card has not yet released VRAM, or a
        probe that flipped the card between the pre-check and here).
        Rule: a request is not cancelled but requeued;
        if VRAM is not free yet it simply waits a moment, so this refusal is
        no longer wanted. `_reserve_and_
        start_locked` no longer calls this method under any condition --
        it calls `_defer_unroutable(slot, evict_pending=True)` instead.

        NOT MAINTAINED. Nothing exercises this any more; verify it before
        reattaching a caller.

        WHAT REPLACED IT: `_defer_unroutable(slot, evict_pending=True)`,
        called directly from `_reserve_and_start_locked` (manager.py) --
        made safe by two teardown-path mechanisms (the post-teardown
        wake at the VRAM-confirmed teardown seam, and the
        predicate that keeps that wake reachable on split-card models).
        """
        log.warning(
            "cross-resident VRAM gate refused spawn for %s "
            "(need=%dMiB parallel=%d gpu=%d split=%s)",
            slot.model_tag, need, parallel, main_gpu, split_mode,
        )
        self._fail_completion_future(
            slot,
            VramOverCommitError(
                f"cross-resident VRAM gate refused {slot.model_tag!r}: "
                f"need {need} MiB would over-commit GPU {main_gpu}",
                retry_after_s=_VRAM_DEFER_RETRY_AFTER_S,
            ),
        )
        # The slot's future is about to fail -- release any
        # pending claim rather than leave it for the next snapshot sweep.
        self._release_fastlane_claim_locked(slot, "unroutable_exhausted")

    def _attn_kv_dims_for(self, m: "object") -> "object | None":
        """Parsed GGUF attention dims for the dimension-aware KV-fit
        estimate, or None to fall back to the legacy file-size + hybrid_kv_ratio
        path (byte-identical). GGUF parsing is now ATTEMPTED for every model
        with a resolvable blob -- a manifest-field gate no longer blocks the
        attempt outright (that field is optional and rarely set
        in practice).

        The RESULT is USED (returned non-None) when EITHER:
          (a) the GGUF's dims include at least one actually-derivable SWA
              layer (n_swa_layers > 0) -- detected from the file itself, no
              architecture name involved. A window value being present is
              NOT enough on its own: some archs advertise
              attention.sliding_window with no derivable interval, landing
              n_swa_layers at 0 via the conservative all-layers-grow
              fallback, which would gain nothing from the dims-based path
              while still switching the estimate off the legacy one, or
          (b) the manifest explicitly sets its `arch` field to ANY non-empty
              value -- not tested against a specific name, only that the
              operator opted this model in via per-model config. Preserved
              so the ONE existing model that already opts into the
              dims-based path today (via that field) keeps getting it;
              dropping it would have been a silent regression for that
              model, not byte-identical to today.
        Every other model -- including one whose shape parses cleanly, e.g.
        an explicit-interval hybrid with no manifest field set -- returns
        None so the caller takes the legacy path, unchanged. Widening the
        dims-based estimate itself to those models is a deliberate,
        deferred follow-up, not this change.

        Returns None on ANY parse failure (missing blob, malformed header,
        unusable dims) or when neither (a) nor (b) holds. Parsed at most
        once per content-addressed blob sha regardless of whether it turns
        out to be used (cached; the sha is immutable so it never re-parses),
        keeping the GGUF read off the hot spawn path."""
        sha = getattr(m, "gguf_blob_sha256", "") or ""
        if not sha:
            return None
        if sha in self._attn_dims_cache:
            dims = self._attn_dims_cache[sha]
        else:
            dims = None
            try:
                path = (
                    self.boot.storage.blob_store_path
                    / "sha256"
                    / sha[:2]
                    / sha
                )
                dims = read_kv_dims(path)
            except Exception:
                dims = None
            # Positive-cache only. A successful parse of an immutable
            # content-addressed sha is deterministic → cache it permanently. A None
            # (transient: blob still materializing / locked) is NOT cached, so a later
            # spawn re-parses once the blob is complete rather than being pinned to the
            # legacy under-count for the manager's whole lifetime. This caches the RAW
            # parse (used or not) so the filter below never forces a re-parse of an
            # otherwise-successfully-parsed unused-today model on every call.
            if dims is not None:
                self._attn_dims_cache[sha] = dims
        is_sliding = dims is not None and getattr(dims, "n_swa_layers", 0) > 0
        manifest_opts_in = bool(getattr(m, "arch", "") or "")
        used = dims is not None and (is_sliding or manifest_opts_in)
        log.debug(
            "attn dims decision: model=%s sha=%s usable=%s n_swa_layers=%s "
            "manifest_opts_in=%s -> %s",
            getattr(m, "model_tag", "?"), sha[:12],
            dims is not None, getattr(dims, "n_swa_layers", None),
            manifest_opts_in, "dims-based" if used else "legacy",
        )
        return dims if used else None

    def _expert_layout_for(self, m: "object") -> "object | None":
        """Exact per-block MoE expert-tensor byte layout for the
        additive moe_ram_fit gate, or None on any parse failure / missing
        blob / failed closure assertion (caller then skips the RAM-fit gate
        for this spawn -- expert_offloaded_mib stays 0, a pure no-op,
        byte-identical to not having this gate). Same immutable-sha
        positive-cache pattern as ``_attn_kv_dims_for``, off the hot spawn
        path."""
        sha = getattr(m, "gguf_blob_sha256", "") or ""
        if not sha:
            return None
        if sha in self._expert_layout_cache:
            return self._expert_layout_cache[sha]
        layout = None
        try:
            path = (
                self.boot.storage.blob_store_path
                / "sha256"
                / sha[:2]
                / sha
            )
            layout = read_expert_layout(path)
        except Exception:
            layout = None
        if layout is not None:
            self._expert_layout_cache[sha] = layout
        return layout

    def _expert_offloaded_mib_for(self, m: "object") -> int:
        """MiB of MoE expert weights that land in host RAM under
        this manifest's ``--n-cpu-moe`` setting, or 0 when cpu_moe offload
        is not configured / the layout can't be derived (moe_ram_fit gate
        no-ops in both cases, matching the existing cpu_moe VRAM branch's
        own fail-open-to-legacy posture)."""
        flags = getattr(m, "llama_server_flags", None) or {}
        n_cpu_moe = int(flags.get("n_cpu_moe", 0) or 0)
        if n_cpu_moe <= 0:
            return 0
        layout = self._expert_layout_for(m)
        if layout is None:
            return 0
        offloaded_bytes, _resident_bytes = split_expert_bytes(layout, n_cpu_moe)
        return offloaded_bytes // (1024 * 1024)

    def _announce_hybrid_kv(
        self, model_tag: "str | None", ratio: float, where: str
    ) -> None:
        """Announce an active hybrid-KV discount ONCE per model.

        The ratio is a static manifest property, so restating it on every spawn
        and every slot adds no information after the first time - it only makes
        the line easy to stop reading. A ratio of 1.0 is the default (no
        discount) and is never announced.
        """
        if ratio >= 1.0 or not model_tag or model_tag in self._hybrid_kv_announced:
            return
        self._hybrid_kv_announced.add(model_tag)
        log.info(
            "hybrid KV discount active (%s): model=%s hybrid_kv_ratio=%.2f "
            "(SSM layers excluded from the per-token KV estimate)",
            where, model_tag, ratio,
        )

    def _resolve_placement_locked(
        self, model_tag: "str | None"
    ) -> "tuple[int, int, int, str, int, bool]":
        """CALLER HOLDS _registry_lock. Resolve the EFFECTIVE placement for
        model_tag: the manifest footprint, then (for auto_place split='none'
        models) the smart auto-placer's card/split override. SINGLE source of
        truth for 'which card + how much VRAM' so the dispatcher's pre-reserve
        VRAM-fit check (_route_or_reserve) and the reserve itself
        (_reserve_and_start_locked) always target the SAME card.

        Smart GPU auto-placer. Override the manifest's pinned main_gpu
        with the least-loaded fitting card (or a layer-split fallback) BEFORE the
        cross-resident gate runs, so the gate checks (and the Resident records) the
        card we're actually about to use. None from _auto_pick_gpu -> keep the
        manifest's original main_gpu/split_mode: simultaneously the documented
        "probe unreadable -> degrade to manifest pin" behavior AND correct when
        nothing fits at all (an unpicked pin that doesn't fit anywhere still gets
        refused by the _vram_admits_locked over-commit gate, same as today).
        """
        need, parallel, main_gpu, split_mode, sleep_idle_s, auto_place = (
            self._read_model_footprint(model_tag)
        )
        # Rule: the manifest expresses a preference; it
        # does not constrain preemption. TWO REGIMES, both real: with Fast
        # Lane enabled, auto-placement is FORCED regardless of the manifest's
        # own auto_place flag -- a manifest can no longer veto it. With Fast
        # Lane disabled, auto_place alone still governs, unchanged from
        # before. auto_place itself is not dead code: it is the SOLE
        # governing input in the fastlane-disabled regime and is still read
        # from the manifest and returned verbatim below either way.
        # REPORT whether the auto-pick was applied, so the caller can
        # record PROVENANCE. `auto_place` below is the MANIFEST's flag returned
        # verbatim and cannot distinguish "the manifest asked for auto-placement"
        # from "Fast Lane forced it" -- exactly what the two
        # `placement_overridden` consumers need to know. NOT a comparison of
        # resolved-vs-manifest values: that shape is rejected (it
        # breaks the mid-window fresh-read contract). This reports what
        # this function DID, which only this function knows.
        placement_auto_picked = False
        if (auto_place or self._fastlane_enabled()) and split_mode == "none":
            auto_gpu, auto_split = self._auto_pick_gpu(need)
            if auto_gpu is not None:
                main_gpu, split_mode = auto_gpu, auto_split
                placement_auto_picked = True
        return (need, parallel, main_gpu, split_mode, sleep_idle_s, auto_place,
                placement_auto_picked)

    def _read_model_footprint(
        self, model_tag: "str | None"
    ) -> "tuple[int, int, int, str, int, bool]":
        """(reserved_need_mib, parallel, main_gpu, split_mode, sleep_idle_seconds,
        auto_place) from the manifest. Sync file read; the dispatcher calls it
        under the lock so the placeholder's reserved budget is exact. Missing
        manifest -> (0,1,0,'layer',0,False) = degrade-open for the footprint (the
        per-spawn all_safety_gates still runs in the driver). sleep_idle_seconds=0
        means 'use global default' — the driver falls back to
        runtime.queue.idle_hot_load_seconds. auto_place is the
        manifest's opt-in smart-placer flag (see _auto_pick_gpu / the caller's
        wiring in _reserve_and_start_locked)."""
        try:
            m = read_manifest(self.boot.storage.manifests_path, model_tag)
        except FileNotFoundError:
            return 0, 1, 0, "layer", 0, False
        flags = m.llama_server_flags or {}
        gguf_mib = int((m.gguf_size_bytes or 0) // (1024 * 1024))
        ctx = int(flags.get("ctx_size") or m.context_size or 0)
        kv_quant = flags.get("cache_type_k") or "f16"
        kv_quant_v = flags.get("cache_type_v") or kv_quant
        # hybrid_kv_ratio: the manifest's model property for hybrid models
        # (attention mixed with state-space or sliding-window layers). Those
        # layers hold a bounded, non-growing state, so only the attention
        # fraction contributes to per-token KV growth.
        # The field IS the model property, so it is read directly - an arch
        # string is not a reliable proxy for which models are hybrid. Any model
        # that does not set it gets the 1.0 default (count every layer) and is
        # sized exactly as before. The manifest validator clamps to [0.0, 1.0].
        # See docs/HYBRID_KV_RATIO.md.
        hybrid_kv = m.hybrid_kv_ratio
        self._announce_hybrid_kv(model_tag, hybrid_kv, "footprint")
        # The RESERVATION footprint must use the SAME dimension-aware /
        # measured-override KV estimate as the per-spawn gate — otherwise the
        # cross-resident over-commit gate (_vram_admits_locked, which sums this
        # reserved_need over RESERVED_LOADING siblings not yet visible to
        # nvidia-smi) under-reserves a booting sibling ~4x and admits a
        # co-resident against phantom headroom. Same cached helper; non-qwen35 /
        # parse-failure → None → legacy path → byte-identical for existing models.
        madims = self._attn_kv_dims_for(m)
        mkbpt = getattr(m, "kv_bytes_per_token", None)
        # MTP / draft-head detection: this is the same predicate
        # _engine_fingerprint uses for n_rs_seq
        # -- one manifest field, read the same way everywhere.
        # SPEC_TYPES_NEEDING_RS_SEQ mirrors the engine's need_n_rs_seq(); today
        # D-Flash/D-Spark are standalone draft models (own GGUF, not a bundled
        # head), so nextn_predict_layers stays unset on the target's own GGUF
        # and this term stays inert for them below -- widening m_mtp here is
        # correct and forward-compatible, not yet behavior-changing for the
        # byte-size estimate. The .strip().lower() coercion is redundant
        # against read_manifest()'s own closed-set re-validation on every load
        # (case-mismatch can't reach here from a validly-read manifest) but
        # IS load-bearing for absence: spec_type is simply unset for every
        # non-speculative model, which the enum validator never touches.
        m_mtp = str(flags.get("spec_type", "") or "").strip().lower() in SPEC_TYPES_NEEDING_RS_SEQ
        kv_mib = estimate_kv_cache_mib(
            ctx, m.gguf_size_bytes or 0, kv_quant, kv_quant_v, hybrid_kv,
            attn_dims=madims, kv_bytes_per_token=mkbpt,
            mtp_draft_active=m_mtp)
        parallel = max(1, int(flags.get("parallel", 1) or 1))
        # par_extra: the marginal per-slot compute floor for parallel>1, ON TOP of
        # the model footprint (the red-team's fix: reserve the FULL body+KV, not
        # just the compute floor).
        par_extra = (parallel - 1) * PER_SLOT_COMPUTE_FLOOR_MIB
        expected_vram_mib = int((m.expected_vram_bytes or 0) // (1024 * 1024))
        # cpu_moe / n_cpu_moe offload expert weights to HOST RAM, so the gguf+kv
        # heuristic (which counts EVERY weight as GPU-resident) grossly over-reserves an
        # expert-offload model and wrong-refuses a co-resident that actually fits
        # (live-E2E 2026-06-25: 35b n-cpu-moe @500K reserved 29.9GiB vs a proven
        # 19.4GiB). For those configs the operator's MEASURED expected_vram_bytes is the
        # only accurate footprint -> trust it. Normal models keep the conservative
        # max(declared, gguf+kv). The driver's per-spawn all_safety_gates re-checks LIVE
        # free VRAM before the sidecar binds either way.
        cpu_moe = bool(
            flags.get("cpu_moe") or int(flags.get("n_cpu_moe", 0) or 0) > 0
        )
        if cpu_moe and expected_vram_mib > 0:
            need = expected_vram_mib + par_extra
        else:
            need = max(expected_vram_mib, gguf_mib + kv_mib) + par_extra
        main_gpu = int(flags.get("main_gpu", 0) or 0)
        split_mode = str(flags.get("split_mode", "layer") or "layer")
        sleep_idle_s = int(flags.get("sleep_idle_seconds") or 0)
        auto_place = bool(m.auto_place)
        return need, parallel, main_gpu, split_mode, sleep_idle_s, auto_place

    def _vram_admits_locked(
        self, need: int, parallel: int, main_gpu: int, split_mode: str,
        credit_pending: bool = False, relocatable: bool = False,
        reclaim_mib_by_card: "dict[int, int] | None" = None,
    ) -> bool:
        """CALLER HOLDS _registry_lock. Cross-resident over-commit gate.

        ``reclaim_mib_by_card`` (optional): VRAM an unload that has NOT
        happened yet would free, per card. It is added to that card's free
        figure (split none: the target card only; any other split: the sum).
        None or empty leaves every result exactly as before.

        Per-card VRAM accounting for split_mode='none' co-residence.
        Multiple tensor-isolated (split_mode='none') models may share a single GPU
        as long as the per-card VRAM budget permits — the nvidia-smi probe reads
        live free VRAM on the target card, and the reserve term subtracts
        RESERVED_LOADING siblings whose weights are not yet reflected in the probe.
        ACTIVE/GRACE/IDLE_EVICTABLE siblings are already loaded and thus already
        absent from the free reading; subtracting them would double-count.

        Layer-split (layer/row/tensor) models are still refuse-blind for co-residence:
        a layer-split sibling spans every visible GPU, so per-card budgeting cannot
        guarantee the incoming model has enough on its target card.

        The FIRST resident (no sibling) admits regardless of split_mode — it keeps
        the legacy degrade-open(parallel:1)/refuse-blind(parallel>1) doctrine via
        the per-spawn all_safety_gates in the driver.
        """
        siblings = self._model_residents()
        new_split = (split_mode or "layer").lower()

        # Aggregate-scope credit helper, shared by the
        # probe-unavailable fallback below AND the normal per-card/aggregate
        # math further down, so the two paths can never disagree about WHICH
        # cards' pending reclaim counts toward this request.
        def _scoped_credit() -> int:
            if not (credit_pending and self._pending_reclaim_mib):
                return 0
            if relocatable or new_split != "none":
                return sum(self._pending_reclaim_mib.values())
            return self._pending_reclaim_mib.get(main_gpu, 0)

        if siblings:
            # Co-residence requires incoming model to be tensor-isolated (split=none).
            # Structural refusals -- crediting VRAM cannot change them (a
            # layer-split incoming model still cannot co-reside no matter how
            # much VRAM frees up), so these stay ahead of any credit logic.
            if new_split != "none":
                return False
            for r in siblings:
                # Every existing sibling must also be tensor-isolated — a
                # layer/row/tensor-split sibling occupies all cards, so per-card
                # budgeting cannot guarantee safe co-residence.
                if (r.split_mode or "layer").lower() != "none":
                    return False
        free_fit, _min_card, _n = _vram_budget(split_mode, main_gpu)
        if free_fit is None:
            # nvidia-smi unreadable.
            if siblings:
                # The eviction-DECISION gate must not
                # ignore VRAM already pledged by in-flight teardowns just
                # because the probe itself stalled -- blindly refusing here
                # starts a per-tick eviction storm (each stalled tick
                # independently concludes "not enough" and evicts yet another
                # idle resident, past what the credit accounting says is
                # needed). Fallback: if the KNOWN credit ALONE already covers
                # `need`, admit -- we deliberately do NOT try to substitute a
                # guess for the unreadable free-VRAM term, only ever add the
                # already-credited amount, so this can never be less
                # conservative than the normal (probe-available) path.
                if _scoped_credit() >= need:
                    return True
                return False  # co-residence without a probe = refuse-blind
            return True  # lone spawn -> driver's all_safety_gates owns the doctrine
        # Reserve ONLY still-booting (not-yet-in-probe) siblings on THIS card (B1).
        reserve = 0
        for r in siblings:
            if r.state is ResidentState.RESERVED_LOADING and r.main_gpu == main_gpu:
                reserve += r.reserved_need_mib
        # For the EVICT DECISION only (credit_pending=True), add VRAM
        # already pledged-to-free by in-flight teardowns so the over-commit branch
        # stops evicting once enough reclaim is in flight. NEVER credited for the
        # actual reserve (credit_pending stays False there) — we must not spawn onto
        # VRAM a teardown has not yet physically released. Per-card for split='none';
        # aggregated for a layer/row/tensor spawn (matches _vram_budget's budget).
        #
        # A RELOCATABLE auto_place model is still a
        # SINGLE-card pin once placed -- it can land on any ELIGIBLE card, but
        # its footprint can never be assembled by summing unrelated cards'
        # pending reclaim together (8000 pending on card0 + 8000 on card1
        # cannot satisfy a 12000 need on either one alone). Check each card's
        # OWN (free + its own pending credit) individually; admit if ANY
        # single card could reach `need` once its own in-flight reclaim
        # lands. The plain aggregate sum (used below for a genuine
        # layer/row/tensor spawn, which DOES span every card at once) stays
        # unchanged for that case.
        if relocatable and new_split == "none" and credit_pending and self._pending_reclaim_mib:
            # This SECOND, independent nvidia-smi read
            # (the FIRST already happened above, inside _vram_budget, and
            # succeeded -- free_fit is not None or we would not be here) can
            # itself flake to None/empty on a transient probe hiccup, which
            # would otherwise over-refuse a request that the just-succeeded
            # primary read already showed room for. One retry of the SAME
            # primary probe, short-circuited so it costs nothing beyond the
            # single call on the (overwhelmingly common) non-flake path.
            vals = _read_free_vram_all_mib() or _read_free_vram_all_mib() or []
            for g, free_g in enumerate(vals):
                reserve_g = sum(
                    r.reserved_need_mib for r in siblings
                    if r.state is ResidentState.RESERVED_LOADING and r.main_gpu == g
                )
                credit_g = self._pending_reclaim_mib.get(g, 0)
                if (
                    free_g - reserve_g + credit_g
                    + (reclaim_mib_by_card or {}).get(g, 0)
                ) >= need:
                    return True
            return False
        credit = _scoped_credit()
        if reclaim_mib_by_card:
            if new_split == "none":
                credit += reclaim_mib_by_card.get(main_gpu, 0)
            else:
                credit += sum(reclaim_mib_by_card.values())
        return (free_fit - reserve + credit) >= need

    def _auto_pick_gpu(self, need_mib: int) -> "tuple[int | None, str]":
        """CALLER HOLDS _registry_lock. Smart GPU auto-placer for
        manifest.auto_place models (split_mode='none' at the manifest). Spreads
        small models evenly across visible GPUs instead of piling everything on
        the manifest's main_gpu default (0).

        Mirrors _vram_admits_locked's per-card reserve accounting (RESERVED_LOADING
        siblings on that card are subtracted; ACTIVE/GRACE/IDLE_EVICTABLE siblings
        are already loaded and thus already reflected in the live nvidia-smi
        reading, so they are NOT subtracted again here — same doctrine, no
        double-count).

        Returns (chosen_gpu, split_mode):
          - A card fits (free[g] - RESERVED_LOADING-siblings-on-g -
            safety_min_free_vram_mib >= need_mib): the MOST-FREE such card,
            ("none",). Picking most-free (not first-fit) is what spreads load —
            as one card fills, the other becomes the most-free pick next time.
          - No single card fits, but the aggregate (each card's free minus the
            floor, summed) does: (0, "layer") — split THIS model across every
            card. (The pre-existing cross-resident co-residence gate in
            _vram_admits_locked still refuse-blinds a layer-split spawn against
            any tensor-isolated siblings — unchanged, out of scope here.)
          - Nothing fits, or the nvidia-smi probe is unavailable: (None, "none").
            The caller's contract on None is to NOT override main_gpu/split_mode
            — keep the manifest's original pin. That is simultaneously the
            documented "probe unreadable -> degrade to manifest pin" behavior,
            and still correctly refuses via the existing _vram_admits_locked
            over-commit gate when nothing genuinely fits anywhere (if it doesn't
            fit in aggregate across every card, it can't fit on one specific
            card either).
        """
        vals = _read_free_vram_all_mib()
        if not vals:
            return None, "none"
        floor = self.runtime.queue.safety_min_free_vram_mib
        siblings = self._model_residents()
        reserved_by_gpu: dict[int, int] = {}
        # Unlike _vram_admits_locked, this sum doesn't filter siblings by
        # split_mode=='none' before reserving them per-card. Safe because a
        # layer-split resident can only ever be admitted with ZERO siblings
        # (the existing cross-resident co-residence gate refuses any
        # layer+none mix) -- so a layer sibling and a 'none' sibling can never
        # coexist in self._residents today. If that co-residence gate is ever
        # relaxed, this loop would need the same split_mode=='none' filter.
        for r in siblings:
            if r.state is ResidentState.RESERVED_LOADING:
                reserved_by_gpu[r.main_gpu] = (
                    reserved_by_gpu.get(r.main_gpu, 0) + r.reserved_need_mib
                )
        avail = [
            vals[g] - reserved_by_gpu.get(g, 0) - floor
            for g in range(len(vals))
        ]
        candidates = [g for g in range(len(vals)) if avail[g] >= need_mib]
        if candidates:
            chosen = max(candidates, key=lambda g: avail[g])
            return chosen, "none"
        if sum(vals) - floor * len(vals) >= need_mib:
            return 0, "layer"
        return None, "none"

    def _log_multi_engine_idle_dead_classification(
        self, handle: "SidecarHandle", model_tag: str
    ) -> None:
        """Cap>=2 twin: the cap<=1 dead-idle sweep (worker_loop)
        only ever runs when
        ``max_parallel_sidecars <= 1`` — ``worker_loop`` branches straight into
        ``_dispatch_loop`` above that, so the whole classification feature
        was dead code on any cap>=2 deployment. This is the cap>=2 analog: called from
        both exactly-once teardown-claim sites that can discover a resident's
        handle already dead with nothing left to reap (``_unload_teardown`` and
        ``_drive_resident``'s own ``finally``) — previously silent fallthroughs.

        Attribution only — changes NOTHING about teardown/recovery/bin-strike
        accounting (callers still reach this in the exact same branch shape
        they always had; this only adds a log call). Best-effort, never raises.
        Reuses the SAME ``IDLE_DEAD_CLASSIFY`` log line name and field set as
        the cap<=1 site (manager.py's worker_loop) so every existing grep/tool
        keyed on that line works identically at either cap — deliberately NOT
        a new line name.
        """
        try:
            _death_class = load_verify_log.classify_idle_dead_holder(
                getattr(handle, "engine_log_path", None),
            )
            log.warning(
                "IDLE_DEAD_CLASSIFY class=%s port=%s model=%s pid=%s "
                "reason=%s matched=%r",
                _death_class.get("death_class"),
                getattr(handle, "port", None),
                model_tag,
                getattr(handle, "pid", None),
                _death_class.get("reason"),
                _death_class.get("matched_line"),
            )
        except Exception:
            log.debug(
                "cap>=2 idle-dead classification failed (best-effort)",
                exc_info=True,
            )

    def _begin_unload_locked(self, r: "Resident") -> None:
        """CALLER HOLDS _registry_lock. LRU-evict (or driver-death reap): drain any
        inbox slots back to the queue, mark DEAD, deregister from _residents (so
        capacity frees + dispatcher stops routing), then teardown the captured
        handle on a DETACHED task (keyed off the captured ref, not the dict entry).

        B3: the inbox drain happens BEFORE the DEAD early-return — a driver that
        already died via its own finally set DEAD without draining (or only partly),
        and this reaper path is the only other drain site, so an already-DEAD
        resident must still surrender its queued slots. The queue hand-off is
        one-shot, so re-draining an already-empty inbox is a harmless no-op."""
        # Drain unstarted inbox slots back to the main queue (not lost) — EVERY call.
        # This method is sync (under _registry_lock) so it can't await; collect the
        # slots IN ORDER and hand them to ONE ordered bg re-enqueue task (not one
        # task per slot, which would race the queue lock and scramble FIFO).
        if r.inbox is not None and not r.inbox.empty():
            drained: list[Slot] = []
            while not r.inbox.empty():
                try:
                    drained.append(r.inbox.get_nowait())
                except asyncio.QueueEmpty:
                    break
            if drained:
                self._spawn_bg(self._requeue_slots_or_fail(drained))
        if r.state is ResidentState.DEAD:
            return
        _transition_resident_state(r.state, ResidentState.DEAD)
        r.state = ResidentState.DEAD
        self._record_staleness_unload(r)  # re-arm this identity's clock
        if self._residents.get(r.resident_key) is r:  # re-key by resident_key
            # Remember WHICH model was on the card, immediately before the
            # registry entry is destroyed. Otherwise the UI just shows the old model name
            # until the VRAM drops. After this `del` the tag is UNRECOVERABLE -- captured
            # here or not at all.
            # DELIBERATELY NOT a field on __init__: tests that build the manager with __new__
            # (to dodge the sqlite boot DB) break whenever __init__ grows -- the documented
            # _handed_off_prune_at fixture rot. getattr with a default cannot rot them.
            self._last_unloaded = {
                "model_tag": getattr(r, "model_tag", None),
                "main_gpu": getattr(r, "main_gpu", None),
            }
            del self._residents[r.resident_key]
        # `/status`'s published eviction counter counts client-disconnect QUEUE-SLOT
        # evictions (the two `slot.is_evicted`
        # sites elsewhere in this file) -- a real MAKE_ROOM_EVICTION never touches
        # those sites, so without the hook below the counter would stay at 0 through a
        # real eviction. This is the single choke point EVERY resident-death path
        # (make-room VRAM, make-room count-cap, designated-victim idle-timeout, self
        # idle-timeout, driver-death reap) already funnels through, so hooking it
        # here counts all of them uniformly, INCLUDING A DRIVER CRASH-REAP -- a
        # known, accepted, and DELIBERATE property of this design,
        # not an oversight: five call sites patched individually would drift the
        # moment a sixth is added, and a crash-reap is itself a resident death the
        # counter should not hide either. If the dashboard ever needs "deliberate"
        # split from "crash", that is a separate, operator-facing follow-up -- do
        # not infer a reason field here.
        #
        # getattr default, same convention this function already uses a few lines
        # below for `_vram_total_mib`: a __new__-harnessed test manager (bypasses
        # __init__ entirely) has neither attribute at all, so this degrades to a
        # fresh 0-based count on that object rather than raising AttributeError --
        # confirmed necessary, not speculative: a harness of that kind
        # would otherwise raise here.
        self._unload_count = getattr(self, "_unload_count", 0) + 1
        self._last_unloaded_at_iso = datetime.now(timezone.utc).isoformat()
        # Prune the per-model
        # identity ONLY when this resident is the LAST live resident of its
        # model_tag. Under multi-instance routing one tag can hold several live
        # residents (distinct resident_keys), so the old model_tag-keyed `is r`
        # guard no longer identifies "the" owner; popping on the FIRST instance's
        # death would delete a still-serving sibling's identity (the stale-reap
        # race an earlier guard closed, re-opened by the re-key). Mirrors live_generations.pop.
        if not any(
            x.model_tag == r.model_tag for x in self._model_residents()
        ):
            self._last_request_identity_by_model.pop(r.model_tag, None)
        # Drop this instance's session->engine affinity entries
        # right after deregister so a later same-session request re-homes to a live
        # instance instead of routing to this dead one (no-op for a default tag: its
        # sessions may map to model_tag; the sticky-lookup re-check + _drop_affinity
        # is the belt-and-suspenders).
        self._purge_affinity_for(r)
        # Credit this victim's VRAM as "pending reclaim" on its card so
        # the over-commit make-room path (which runs BEFORE the async teardown frees
        # the card) won't evict ANOTHER resident for VRAM already on its way out.
        # Balanced 1:1 by the decrement in _unload_teardown's finally (which this call
        # spawns just below) — leak-proof and underflow-safe.
        teardown_task = self._spawn_bg(self._unload_teardown(r))
        if r.reserved_need_mib > 0:
            r.reclaim_credited_mib = r.reserved_need_mib
            new_total = (
                self._pending_reclaim_mib.get(r.main_gpu, 0) + r.reserved_need_mib
            )
            self._pending_reclaim_mib[r.main_gpu] = new_total
            # Stamp/overwrite this card's latest
            # credit-raise instant -- see _pending_reclaim_raised_at's own
            # comment in __init__ for why LATEST, not earliest.
            self._pending_reclaim_raised_at[r.main_gpu] = time.monotonic()
            # A card can never legitimately owe more VRAM
            # than it physically holds -- once accumulation crosses
            # capacity the reconciler's release predicate becomes
            # unsatisfiable in every possible world state (a credit that kept
            # growing far past the card's physical capacity was never
            # released). Catch it HERE, at the increment that first makes
            # it impossible, rather than downstream. getattr with a None
            # default: a __new__-harnessed test manager (bypasses __init__
            # entirely) and a boot where nvidia-smi was unavailable both
            # leave this attribute absent/None -- either way "cannot
            # verify", never license to reset, same absence-of-evidence
            # philosophy the reconciler itself uses below. Loud + auto-reset
            # by design: log the numbers, then the credit snaps back to 0
            # immediately -- clamping to capacity instead would still need
            # a near-total-capacity single-window drop to ever clear,
            # so it does not fix stuck-forever, it only moves the
            # threshold.
            #
            # Lazy populate on first use (see __init__): a __new__-harnessed
            # test manager has neither attribute at all, so getattr degrades
            # both reads to None -- no populate is attempted, no crash.
            if getattr(self, "_vram_total_mib", None) is None:
                populate_fn = getattr(self, "_vram_total_mib_fn", None)
                if populate_fn is not None:
                    self._vram_total_mib = populate_fn()
            capacity = getattr(self, "_vram_total_mib", None)
            if (
                capacity is not None
                and r.main_gpu < len(capacity)
                and new_total > capacity[r.main_gpu]
            ):
                log.error(
                    "pending-reclaim credit for card %s "
                    "grew to %d MiB, exceeding its %d MiB physical capacity "
                    "-- auto-resetting to 0 rather than leaving an "
                    "arithmetically unsatisfiable reconcile predicate stuck "
                    "forever",
                    r.main_gpu, new_total, capacity[r.main_gpu],
                )
                self._pending_reclaim_mib[r.main_gpu] = 0
            # Register the task that OWNS this credit's
            # eventual decrement. Only when credited (matches
            # reclaim_credited_mib's own "0 for a non-make-room teardown"
            # no-op) -- an uncredited teardown on the same card must never
            # block _reconcile_orphaned_vram_credit from touching a
            # DIFFERENT resident's genuinely orphaned credit.
            self._register_card_release_task(r.main_gpu, teardown_task)

    async def _reap_multi_engine_orphans(self, reason: str) -> dict:
        """Cap>=2 twin of the cap<=1 post-teardown orphan reap
        (_teardown). Runs the SAME two calls with the SAME
        argument shapes after a cap>=2 resident teardown, because the kill
        chain (drained_sigterm -> killpg on the sidecar's own session) cannot
        reach Tom's Fork setsid-detached helpers (see manager.py and
        subprocess_mgr.py) and nothing else on the cap>=2 path walks
        /proc during the manager's lifetime.

        Conservative by construction — no new kill authority is introduced:
          * boot_orphan_reaper reaps ONLY on a durable (pid, port, starttime)
            identity match;
          * intra_lifetime_orphan_scan touches only llama-servers in the
            managed port range whose pid is NOT in the live set;
          * both protected sets are _live_handle_pids() — the cap>=2-aware
            union of every resident's live handle + idle handle + booting pid
            (manager.py) — so co-resident sidecars and
            still-booting siblings are preserved.
        Best-effort: EACH stage has its own try/except Exception and this
        method never raises out of a teardown (both call sites are detached-
        task teardown paths where a raised exception would mask the in-flight
        one). Returns the combined result for logging/future audit surfacing.
        """
        result: dict = {"reaped": 0, "intra_reaped": 0}
        # DURABLE PROOF: read recorded engine identities so the reaper only
        # touches proven Turbohaul-owned engines (same as _teardown).
        # A read failure degrades to report-only (empty set) —
        # never a teardown failure.
        ids: set = set()
        try:
            with state_db_session(self.boot.storage.state_db_path) as _c:
                ids = known_engine_identities(_c)
        except Exception:
            pass
        try:
            reap_result = boot_orphan_reaper(
                port_base=self.boot.runtime.default_port_base,
                # Preserve every LIVE sidecar (co-residents + booting
                # siblings). _live_handle_pids is the cap>=2-aware union
                # (manager.py) — the same set the cap<=1 call site
                # passes.
                known_pids=self._live_handle_pids(),
                known_engine_identities=ids,
            )
            result["reaped"] = reap_result.get("reaped", 0)
        except Exception:
            log.exception(
                "post-teardown orphan reap failed (best-effort) [%s]", reason,
            )
        try:
            il_result = intra_lifetime_orphan_scan(
                port_base=self.boot.runtime.default_port_base,
                known_handle_pids=self._live_handle_pids(),
            )
            result["intra_reaped"] = il_result.get("reaped", 0)
            if il_result.get("reaped", 0) > 0:
                log.warning(
                    "intra-lifetime reap caught orphans post-teardown [%s]: %s",
                    reason, il_result,
                )
        except Exception:
            log.exception(
                "intra-lifetime orphan scan failed (best-effort) [%s]", reason,
            )
        if result["reaped"] > 0 or result["intra_reaped"] > 0:
            log.warning(
                "cap>=2 post-teardown orphan reap [%s]: boot_reaper_reaped=%d "
                "intra_reaped=%d", reason, result["reaped"], result["intra_reaped"],
            )
        return result

    async def _unload_teardown(self, r: "Resident") -> None:
        """Detached: claim torn_down (exactly-once vs the driver finally) then
        teardown r's live handle off the hot path. B2: if r is still RESERVED_LOADING
        (sidecar spawned but handle not yet published) the handle is None and
        ``booting_pid`` is the ONLY reference to the live process — reap by pid so
        an LRU/death teardown of a booting resident can't leak it.

        Trigger KV cache save BEFORE SIGTERM with the resident's
        idle_thread_id (mirrors _teardown_idle_holder for cap<=1). The C++ engine
        checks for thread_id during save — empty thread_id returns do_it=False.

        The pending-reclaim credit is dropped on VRAM-CONFIRMED,
        not on process-reap — process-reaped only means SIGTERM
        landed, not that the CUDA context (and its VRAM) actually released yet;
        the residual window between the two used to leave the over-commit
        make-room path crediting VRAM that was not actually free yet.
        """
        # This task OWNS the pending-reclaim decrement, paired 1:1 with
        # the _begin_unload_locked increment that spawned it. Capture the amount now;
        # the finally drops it EXACTLY ONCE — leak-proof even on the torn_down
        # early-return (a concurrent driver-finally reap) and even if a reap raises.
        # reclaim_credited_mib is 0 for a non-make-room teardown, so this is a no-op
        # there (underflow-safe).
        reclaim_mib = getattr(r, "reclaim_credited_mib", 0)
        reclaim_card = r.main_gpu
        model_tag = r.model_tag  # Capture before try/finally so the
        # audit seam in finally always has it (torn_down early-return drops out
        # before model_tag would be reassigned inside the lock).
        # Snapshot taken BEFORE SIGTERM (while the victim is still
        # fully resident) so the post-verify delta reflects what THIS teardown
        # actually freed, not decay already underway by the time verify polls.
        # None when there's nothing to reclaim, or nvidia-smi is unavailable.
        pre_teardown_used_mib = (
            await asyncio.to_thread(self._gpu_used_mib, device_index=reclaim_card)
            if reclaim_mib else None
        )
        try:
            async with self._registry_lock:
                if r.torn_down:
                    return
                r.torn_down = True
                handle = r.handle
                model_tag = r.model_tag
                idle_thread_id = r.idle_thread_id
                r.handle = None
                booting_pid = r.booting_pid
                r.booting_pid = None
            # SWAP-CLEAR (cap>=2): a resident sidecar is being
            # torn down (LRU-evict / driver-death). Invalidate the completion-cache so
            # a cached answer can never survive a resident swap. Cleared OUTSIDE the
            # registry lock (the cache is not registry-lock-protected — same no-lock,
            # single-loop discipline as the submit_and_wait / _process_slot accesses).
            self._completion_cache_clear("evict_teardown")
            # Trigger KV cache save BEFORE SIGTERM.
            # The C++ engine checks for thread_id during save — empty thread_id
            # returns do_it=False. Now we have the thread_id from idle entry,
            # so the save can succeed and the cache will be fresh on resume.
            # Use _save_slot_kv instead of a bolt-on POST.
            if handle is not None and handle.is_alive() and idle_thread_id:
                try:
                    # For a single-stream resident (parallel==1), write
                    # a CLEAN pre-generation bin FIRST (mirrors cap<=1 _teardown_idle_holder);
                    # the plain _save_slot_kv below then no-ops on the clean-present
                    # guard. Best restore fidelity (zero post-<think> divergence). Requires
                    # idle_client_meta["messages"] (the flush needs it); self-guards + best-effort.
                    if int(getattr(handle, "parallel", 1) or 1) == 1:
                        await self._flush_clean_kv_at_unload(
                            handle, model_tag, idle_thread_id,
                            r.idle_admission_ctx_len, r.idle_client_meta,
                        )
                    saved = await self._save_slot_kv(
                        handle.port,
                        model_tag,
                        r.active_slot,
                        thread_id_override=idle_thread_id,
                        admission_ctx_len_override=r.idle_admission_ctx_len,
                        # Same raw-keying bug as the singleton seam —
                        # the _idle_thread_id fallback compares against the SINGLETON
                        # holder's field, never this resident's; without the explicit
                        # meta the save keys on raw thread_id (duplicate bin) and
                        # T-GUARD has no prior meta to calibrate against.
                        client_meta_override=r.idle_client_meta,
                    )
                    # Success must not be reported when the save did not occur.
                    # Rationale: a result of True means the save really happened.
                    # _save_slot_kv's SPEC-V2 contract:
                    # True iff a bin+meta pair was fully persisted; False/None
                    # are the non-raising refusals (dirty tip / disposable
                    # / no populated slots / unsafe tag), each already logged
                    # at its own source with its own reason. Claim "saved"
                    # only on True; the refusal reason
                    # is NOT duplicated here — only the success claim is
                    # withheld, plus an honest DEBUG correlation line.
                    if saved:
                        log.info(
                            "resident KV cache saved before teardown "
                            "(thread_id=%s, model_tag=%s)",
                            idle_thread_id[:8] if idle_thread_id else "none",
                            model_tag,
                        )
                    else:
                        log.debug(
                            "resident KV cache save not confirmed before "
                            "teardown (result=%r; refusal reason, if any, "
                            "logged at source) model_tag=%s",
                            saved, model_tag,
                        )
                except Exception:
                    log.warning(
                        "resident KV cache save failed (best-effort): model_tag=%r",
                        model_tag,
                        exc_info=True,
                    )
            if handle is not None and handle.is_alive():
                await self._reap_resident_handle(handle)
            elif handle is not None:
                # Handle exists but is already dead — nothing to
                # reap, but attribute it before falling through (previously
                # silent). cap>=2 twin of the cap<=1 worker_loop sweep.
                self._log_multi_engine_idle_dead_classification(handle, model_tag)
            elif booting_pid is not None:
                await self._reap_booting_pid(booting_pid)
            # Cap>=2 twin of the cap<=1 post-teardown orphan
            # reap (_teardown). Every stage inside is
            # individually try/except-guarded — this never raises out of the
            # detached teardown task. See _reap_multi_engine_orphans.
            await self._reap_multi_engine_orphans("evict_teardown")
        finally:
            if reclaim_mib:
                # The victim's process is reaped, but reaped != VRAM
                # actually released (residual CUDA context, which lingers
                # after the kill). Confirm on THIS card (not GPU 0
                # unconditionally) before trusting the credit is real.
                cleared_ok, measured_delta = True, reclaim_mib
                try:
                    # settle_floor_s intentionally NOT overridden --
                    # this call gates the capacity-released notify below (a waiting
                    # claimant genuinely benefits from the default 5.0s floor
                    # + faster post-floor polling; see verify_vram_cleared's
                    # own docstring).
                    cleared_ok, current_used_mib = await self._vram_verify(
                        expected_drop_mib=reclaim_mib, timeout_s=30.0,
                        device_index=reclaim_card,
                    )
                    if (
                        pre_teardown_used_mib is not None
                        and current_used_mib is not None
                    ):
                        measured_delta = max(
                            0, pre_teardown_used_mib - current_used_mib
                        )
                    # else: no probe data on one or both ends (nvidia-smi
                    # unavailable) — trust the kill, same dev-tolerance
                    # philosophy verify_vram_cleared itself already applies.
                except Exception:
                    log.warning(
                        "VRAM-clear verify raised for model_tag=%r card=%s "
                        "(best-effort, trusting the kill)",
                        r.model_tag, reclaim_card, exc_info=True,
                    )
                # Confirmed-cleared: trust the ≥90%-drop verdict, release this
                # victim's FULL credited share. Timed out: release only the
                # MEASURED delta — the un-freed remainder stays credited so the
                # over-commit gate keeps refusing to admit into VRAM that has not
                # actually freed yet (the credit keeps an honest value).
                dec = reclaim_mib if cleared_ok else min(measured_delta, reclaim_mib)
                if not cleared_ok:
                    log.warning(
                        "VRAM not confirmed cleared after 30s for model_tag=%r on "
                        "card %s (credited %d MiB, measured drop %d MiB) -- "
                        "reconciling credit to the measured delta, not clearing it",
                        r.model_tag, reclaim_card, reclaim_mib, dec,
                    )
                async with self._registry_lock:
                    self._pending_reclaim_mib[reclaim_card] = max(
                        0, self._pending_reclaim_mib.get(reclaim_card, 0) - dec
                    )
                    r.reclaim_credited_mib = 0
                    # VRAM-over-commit regime:
                    # THIS is the real "capacity released by a completed
                    # eviction" moment for a VRAM-credited eviction --
                    # _begin_unload_locked's own credit_pending=True credit
                    # is deliberately NEVER used for the actual
                    # admission check (credit_pending stays False there,
                    # per _vram_admits_locked's own comment: "we must not spawn onto VRAM
                    # a teardown has not yet physically released"), so a
                    # waiter woken any earlier would re-check into a
                    # guaranteed-false admission. `dec` is the amount THIS
                    # call actually confirmed free -- only notify when it is
                    # nonzero, so a still-unconfirmed remainder (the
                    # not-cleared_ok branch measuring 0 freed so far) does
                    # not spend a wake on nothing having changed. Same idiom
                    # as the three existing sites: still
                    # under `_registry_lock`, no new await between the write
                    # above and this notify. Deliberately UNCONDITIONAL on
                    # eviction reason: this
                    # fires for every VRAM-credited teardown regardless of
                    # which of `_begin_unload_locked`'s six call sites started
                    # it, including count-cap and the three sites
                    # that already notify at eviction time -- provably inert
                    # there (an extra wake only ever triggers
                    # one more correct, fresh re-check under lock).
                    if dec:
                        # Wake the dispatch loop alongside
                        # the make-room signal so staging re-admitted the moment
                        # VRA-credit confirms released -- not on the 1800s TTL
                        # expiry fallback, which stalls while there are 0
                        # residents. _dispatch_wake is an asyncio.Event (no lock),
                        # so set() is safe under _registry_lock and idempotent.
                        self._dispatch_wake.set()
                        self._make_room_signal.notify_all()
                # Stuck-credit handling: dec < reclaim_mib
                # means an honest but un-freed remainder is still credited --
                # with nothing else re-checking it, a residual window that
                # outlasts the 30s verify budget (the class of failure this
                # one-shot re-verify targets) leaves it stuck until a manager restart, permanently
                # blocking the make-room path for this card. One bounded,
                # ONE-SHOT delayed re-verify at grace_seconds -- not a retry
                # loop, not a daemon, no new persistent state -- gives a
                # genuinely-late clear a second chance without polling forever.
                if not cleared_ok and dec < reclaim_mib:
                    # Register the SAME way the teardown
                    # task itself is registered (no await between releasing
                    # the lock above and this registration, so there is no
                    # window where the remainder's credit exists with no
                    # task claiming it -- see _register_card_release_task).
                    late_task = self._spawn_bg(self._late_vram_reconcile(
                        r.model_tag, reclaim_card, reclaim_mib - dec,
                    ))
                    self._register_card_release_task(reclaim_card, late_task)

            # Audit-write for cap>=2 resident teardown. Ports the
            # cap<=1 _teardown audit event (manager.py) onto the
            # DETACHED _unload_teardown task so operator dashboards see
            # engine-kill events even when no active turn is present (idle-
            # evicted or driver-death-reaped residents). Fires AFTER the handle
            # is reaped + VRAM credit reconciled so it reflects the final
            # state. Via the audit pool (audit_db_session, sync-only).
            #
            # GAPS (documented; not closed here):
            # - sigterm_status / sigterm_ok: unavailable. _reap_resident_handle
            #   calls _sigterm but discards its (ok, status) return under a
            #   broad try/except. Making it return those values would change a
            #   shared-function contract for one audit field -- the
            #   orphan-reap additions to _unload_teardown are where a real
            #   sigterm result + orphan count will eventually surface here.
            # - post_teardown_orphans_reaped: 0 (placeholder) for the same gap.
            # - reason: _unload_teardown takes no reason param; recorded as the
            #   generic seam label "evict_teardown" (make-room-vram, make-room-
            #   count-cap, idle-timeout, and driver-death-reap all funnel here).
            slot_id = r.active_slot.slot_id if r.active_slot is not None else None

            def _audit_unload_teardown() -> None:
                with audit_db_session(self.boot.storage.state_db_path) as audit_conn:
                    record_audit_event(
                        audit_conn, "teardown", {
                            "reason": "evict_teardown",
                            "model_tag": model_tag,
                            "sigterm_status": None,
                            "sigterm_ok": None,
                            "post_teardown_orphans_reaped": 0,
                        },
                        slot_id=slot_id,
                    )

            # await asyncio.to_thread(_audit_unload_teardown) in the finally block
            # of a DETACHED task: if this raises (e.g. boot.storage is a
            # SimpleNamespace fixture without state_db_path), it masks the
            # in-flight exception and becomes an unhandled task exception.
            # Wrap in try/except matching every other best-effort step in
            # this function.
            try:
                await asyncio.to_thread(_audit_unload_teardown)
            except Exception:
                log.exception(
                    "evict-teardown audit write failed (best-effort)"
                )

    async def _late_vram_reconcile(
        self, model_tag: str, card: int, remainder_mib: int,
    ) -> None:
        """Detached, ONE-SHOT follow-up to
        _unload_teardown's timeout branch. Waits ``grace_seconds`` (the same
        window a re-routed request already tolerates) then re-checks whether
        the still-credited ``remainder_mib`` has since actually freed. Fires
        at most once per teardown — no loop, no re-scheduling on its own
        failure, no new persistent state. If the card never clears, the
        remainder stays credited (still correctly preventing an over-commit
        admit) until an operator restarts the manager or the card frees
        later via some other path that happens to re-probe it.

        That "some other path" is
        _reconcile_orphaned_vram_credit — a periodic sweep for a card whose
        credit is stuck with NO live releaser task (neither this method nor
        _unload_teardown has one in flight). It is a distinct SECOND releaser
        of the same counter; both are registered into ``_card_release_tasks``
        at spawn time specifically so they can never pay out for the same
        reclaim (see ``_register_card_release_task``).
        """
        grace_s = self.runtime.queue.grace_seconds
        await asyncio.sleep(grace_s)
        try:
            # settle_floor_s=0.0 deliberately, DESPITE this call
            # also gating a capacity-released notify -- unlike _unload_teardown's own
            # verify, this one only runs after _unload_teardown's own
            # floor+30s window has ALREADY timed out, plus this function's
            # own `grace_s` sleep just above. Any genuine settle-lag window
            # is long over by the time this samples for the first time; a
            # fresh floor here would skip zero real guaranteed-misses and
            # only add pure latency on top of an already-complete settle.
            cleared_ok, _current = await self._vram_verify(
                expected_drop_mib=remainder_mib, timeout_s=30.0,
                device_index=card, settle_floor_s=0.0,
            )
        except Exception:
            cleared_ok = False
            log.warning(
                "late VRAM re-verify raised for model_tag=%r card=%s "
                "(treating as still-unreconciled)", model_tag, card,
                exc_info=True,
            )
        if cleared_ok:
            async with self._registry_lock:
                self._pending_reclaim_mib[card] = max(
                    0, self._pending_reclaim_mib.get(card, 0) - remainder_mib
                )
                # Same capacity-released wake as _unload_teardown's own
                # confirm site -- this IS that same moment for the
                # slow/timed-out sub-case (the initial 30s verify missed the
                # window, this one-shot grace-delayed re-check just
                # confirmed it). remainder_mib is guaranteed nonzero here by
                # the caller's own gating (_unload_teardown only spawns this
                # task when `dec < reclaim_mib`), so no zero-check is needed.
                # Same idiom: still under `_registry_lock`, no new await
                # before the notify.
                # Also wake dispatch loop -- same reasoning
                # as _unload_teardown's notify site.
                self._dispatch_wake.set()
                self._make_room_signal.notify_all()
            log.info(
                "late VRAM clear confirmed; releasing remaining credit "
                "(model_tag=%r card=%s remainder=%d MiB)",
                model_tag, card, remainder_mib,
            )
        else:
            log.warning(
                "credit still unreconciled after %ds -- requires restart or "
                "late clear (model_tag=%r card=%s remainder=%d MiB)",
                int(grace_s) + 30, model_tag, card, remainder_mib,
            )

    async def _reconcile_orphaned_vram_credit(self) -> None:
        """Periodic sweep, piggybacked on
        _periodic_terminal_park_sweep's own loop tick (reuses
        background_sweep_interval_s -- here is why: unlike the
        KV-cache-GC piggyback on the same loop, which needed its own slower
        _KV_GC_MIN_INTERVAL_S throttle because a scandir is expensive even
        when idle, this sweep's common case is a cheap O(cards) dict check
        with zero real VRAM reads, so no separate throttle is warranted).

        Finds a card whose ``_pending_reclaim_mib`` is stuck non-zero with NO
        live releaser task (see ``_register_card_release_task`` for why a
        task reference, not a counter, is the right observable -- a counter
        dropped in the same ``finally`` that drops the credit is orphaned by
        the identical event that orphans the credit).

        Verification compares the card's CURRENT absolute
        free VRAM (capacity minus a fresh used-MiB reading) directly against
        the credited amount, replacing the delta-vs-pre-teardown-baseline
        comparison this reconciler used before. The old comparison mixed
        units -- a SINGLE-teardown snapshot (``_unload_teardown`` overwrote
        it on every teardown) against a MULTI-teardown ACCUMULATED credit
        -- and could stay wrong even once the card had genuinely, fully
        cleared. The absolute comparison eliminates that mismatch by
        construction: it needs no memory of when any teardown started, only
        what the card holds right now. Still does NOT call
        ``_vram_verify``/``verify_vram_cleared`` -- that function needs to
        WITNESS a live drop during its own call window and can never
        confirm VRAM that already settled before this sweep got around to
        checking (confirmed empirically).

        Requires ``_vram_total_mib`` (per-card physical capacity, populated
        once at boot -- see ``__init__``). A missing capacity reading (or a
        missing VRAM-used reading) means "cannot verify" -- the credit is
        KEPT, never released on an absence of evidence, same as before.

        Snapshot-then-recheck straddles the VRAM read (never under the
        lock) so a card that gains a NEW legitimate
        credit while this sweep is running is never touched: this only
        commits a release when, immediately before writing, the task set is
        STILL empty AND the counter STILL equals what was snapshotted before
        the read. Either check failing means something else touched this
        card in the interim -- skip it this tick, defer to the next.
        """
        async with self._registry_lock:
            candidates = {
                card: mib
                for card, mib in self._pending_reclaim_mib.items()
                if mib > 0 and not self._card_release_tasks.get(card)
            }
            # Release from an event the registry
            # already recorded, no VRAM witness needed -- if a live resident
            # on this card was ADMITTED after the credit's latest raise,
            # this card is no longer over-committed for admission purposes
            # (a resident smaller than the credited amount can be admitted
            # into a genuinely-free remainder without the full credited
            # amount having returned -- see the release-log wording below
            # for the corrected, observation-only claim). Entirely
            # additive: the absolute-VRAM branch below is untouched, and a
            # card with no qualifying resident falls through to it exactly
            # as before. Read and write both happen inside this ONE lock
            # hold (no unlock window in between, unlike the VRAM-witness
            # path below, which straddles a blocking read for a real
            # reason that does not apply here) -- so no snapshot-then-
            # recheck is needed: nothing can race a write between two
            # statements that never release the lock.
            # KNOWN LIMIT, not an oversight: this
            # filters on `r.main_gpu == card` only. A layer/tensor-split
            # resident spans every card, so admitting one after the raise
            # does NOT satisfy this clause for a non-main card of that
            # resident -- the result is a MISSED release on that card
            # (falls through to the absolute-VRAM-witness path below,
            # unchanged), never a WRONG one; this branch only ever narrows
            # candidates, it never releases a credit the VRAM path would
            # have kept.
            for card in list(candidates):
                raised_at = self._pending_reclaim_raised_at.get(card)
                if raised_at is None:
                    continue
                if any(
                    r.main_gpu == card and r.reserved_at_monotonic > raised_at
                    for r in self._model_residents()
                ):
                    released_mib = candidates.pop(card)
                    self._pending_reclaim_mib[card] = 0
                    # Worded as the OBSERVATION, not the inference:
                    # a resident smaller than the credited
                    # amount can be admitted into a genuinely-free remainder
                    # without the FULL credited amount having returned, so
                    # releasing the credit is still right (this card is no
                    # longer over-committed for admission purposes) but
                    # asserting the full amount "demonstrably returned" would
                    # overstate what was actually observed -- and this line
                    # will be read as evidence by whoever next debugs a
                    # stranded credit.
                    log.warning(
                        "pending-reclaim credit for card "
                        "%s (%d MiB) released on registry evidence -- a "
                        "resident admitted after the credit was raised now "
                        "occupies the card", card, released_mib,
                    )
        # Batched VRAM read. Instead of calling
        # self._gpu_used_mib per card in the loop below (each a blocking
        # nvidia-smi subprocess), read all candidate cards in a single
        # asyncio.to_thread hop to avoid serializing N thread hops. The
        # to_thread is guarded by a non-empty candidates check: when the
        # candidates dict is empty (the common no-work tick), we must NOT
        # yield to the event loop -- a spurious yield here lets concurrent
        # _unload_teardown tasks advance mid-reconcile, breaking the
        # double-payout guard's "skip cards with live release tasks" invariant.
        _SENTINEL = object()
        def _read_all_gpu_used_mib(cards):
            out = {}
            for c in cards:
                try:
                    out[c] = self._gpu_used_mib(device_index=c)
                except Exception:
                    out[c] = _SENTINEL  # raised — caller logs "raised"
                # None is kept as None (nvidia-smi unavailable)
            return out

        if candidates:
            vram_by_card = await asyncio.to_thread(
                _read_all_gpu_used_mib, list(candidates)
            )
        else:
            vram_by_card = {}

        for card, snapshot_mib in candidates.items():
            current = vram_by_card[card]
            if current is _SENTINEL:
                log.warning(
                    "VRAM read raised while reconciling card %s "
                    "(best-effort, keeping credit)", card, exc_info=True,
                )
                continue
            if current is None:
                log.warning(
                    "VRAM read unavailable while reconciling "
                    "card %s -- keeping credit (cannot confirm the drop)",
                    card,
                )
                continue
            capacity = getattr(self, "_vram_total_mib", None)
            if capacity is None or card >= len(capacity):
                log.warning(
                    "card %s has %d MiB stuck "
                    "pending-reclaim credit with no live releaser task and "
                    "no known card capacity to verify against -- keeping "
                    "credit (cannot confirm the drop from absence of "
                    "evidence)",
                    card, snapshot_mib,
                )
                continue
            free_now = capacity[card] - current
            cleared = free_now >= 0.9 * snapshot_mib
            async with self._registry_lock:
                if (
                    self._card_release_tasks.get(card)
                    or self._pending_reclaim_mib.get(card, 0) != snapshot_mib
                ):
                    log.info(
                        "card %s changed while reconciling (a "
                        "new release task registered or the credit was "
                        "already touched) -- skipping this tick, deferring "
                        "to the next", card,
                    )
                    continue
                if cleared:
                    self._pending_reclaim_mib[card] = 0
                    log.warning(
                        "orphaned VRAM credit released for card "
                        "%s (%d MiB) -- the owning teardown task died "
                        "before its finally's decrement ran; verified "
                        "genuinely free (measured free %d MiB of %d "
                        "credited)", card, snapshot_mib, free_now,
                        snapshot_mib,
                    )
                else:
                    log.warning(
                        "card %s has %d MiB stuck pending-reclaim "
                        "credit with no live releaser task, but VRAM does "
                        "not appear free yet (measured free %d MiB) -- "
                        "keeping credit", card, snapshot_mib, free_now,
                    )

    async def _reap_booting_pid(self, pid: int) -> None:
        """SIGTERM-then-REAP a sidecar that spawned but whose handle was never
        published (driver cancelled/failed mid ``_wait_healthy``). ``booting_pid`` is
        the only reference to that process — and ``_live_handle_pids`` actively
        PROTECTS it from the orphan reaper — so without this it leaks VRAM+PID forever
        (B2). The sidecar is OUR child (same-process spawn at cap>=2), so we MUST
        ``waitpid`` it or it lingers as a ZOMBIE/defunct entry that keeps the PID
        allocated (P1e fast-follow #1). Bounded: WNOHANG-poll for a grace window,
        escalate to SIGKILL, final blocking reap. Best-effort, off the event loop (the
        sleeps run in the worker thread, never blocking the loop).

        PID-RECYCLE GUARD (PL pre-cutover polish #4): a child that exits becomes a
        zombie holding its PID until reaped — but a COMPETING reaper (the lost
        ``SidecarHandle``'s ``Popen`` being GC-reaped by CPython after the cancel
        unwinds its frame) can reap it first, freeing the PID for the OS to recycle to
        an UNRELATED process. So before EVERY signal we re-confirm pid is still our
        ALIVE child via ``waitpid(WNOHANG)``: ``ChildProcessError`` (ECHILD) => not
        ours / already reaped => STOP (never signal a recycled pid); ``(pid, _)`` =>
        ours, just exited => reaped here => done; ``(0, 0)`` => ours, alive => safe to
        signal. This narrows the recycle window to the microseconds between the check
        and the kill (the standard best-effort bound for raw-pid reaping)."""
        def _own_live_child() -> bool:
            """True iff pid is our ALIVE child (safe to signal). False if it is gone,
            already reaped (zombie collected here), or no longer ours (ECHILD)."""
            try:
                wpid, _ = os.waitpid(pid, os.WNOHANG)
            except (ChildProcessError, ProcessLookupError):
                return False  # not ours / already reaped -> do NOT signal a recycled pid
            return wpid == 0  # 0 = still running; pid = exited+reaped just now (done)

        def _term_and_reap() -> None:
            if not _own_live_child():
                return
            try:
                os.kill(pid, signal.SIGTERM)
            except ProcessLookupError:
                return
            for _ in range(30):  # ~3s grace for SIGTERM, re-checking ownership each iter
                if not _own_live_child():
                    return  # exited (reaped) or no longer ours
                time.sleep(0.1)
            if not _own_live_child():
                return
            try:
                os.kill(pid, signal.SIGKILL)
            except ProcessLookupError:
                return
            with contextlib.suppress(ChildProcessError, ProcessLookupError, OSError):
                os.waitpid(pid, 0)  # final blocking reap of the SIGKILL'd child
        try:
            await asyncio.to_thread(_term_and_reap)
        except Exception:
            log.exception("booting_pid reap failed (best-effort) pid=%d", pid)
        finally:
            # A booting sidecar never reached a served turn, so it never had
            # slot identity to key a KV save on -- there is nothing to save,
            # but the kill itself was previously unannounced.
            _log_kv_save_decline(
                KV_DECLINE_NO_SLOT_IDENTITY, call_site="reap_booting_pid")

    async def _reap_resident_handle(self, handle) -> None:
        """Drained-SIGTERM a resident's handle via the DI _sigterm seam (consistent
        with the legacy _teardown; async + non-blocking + mockable). Best-effort.
        NOTE: No KV save here — this is a safety-net reap without slot identity.
        The proper save happens in _teardown_idle_holder / _teardown WITH the slot."""
        try:
            await self._sigterm(
                handle,
                drained_window_s=float(
                    self.runtime.queue.drained_sigterm_window_active_s
                ),
                is_active=False,
                cold_window_s=float(
                    self.runtime.queue.drained_sigterm_window_cold_s
                ),
            )
        except Exception:
            log.exception("resident handle reap failed (best-effort)")
        finally:
            # No slot identity is available on this path (see docstring) --
            # the proper save happens in _teardown_idle_holder / _teardown
            # WITH the slot. Kill still happened; say so plainly.
            _log_kv_save_decline(
                KV_DECLINE_NO_SLOT_IDENTITY, thread_id=getattr(handle, "thread_id", "") or "",
                call_site="reap_resident_handle")

    def _on_driver_done(self, r: "Resident", task: "asyncio.Task") -> None:
        """done_callback (SYNC — cannot await): schedule the supervisor reaper on
        EVERY driver exit, including CANCELLED. B2: a driver cancelled during
        RESERVED_LOADING leaves a live sidecar (handle still None, ``booting_pid``
        set) — bailing on ``task.cancelled()`` meant the reaper never ran and the
        process leaked. The driver finally already reaps + claims torn_down, so the
        reaper is exactly-once-safe (it no-ops when torn_down is already set) and
        only ADDS the failed-future / booting_pid safety net on the cancel path.
        Normal completion (idle-evict self-teardown) likewise no-ops."""
        cancelled = task.cancelled()
        exc = None if cancelled else task.exception()
        if cancelled:
            log.warning("driver for %s cancelled — scheduling reap", r.model_tag)
        elif exc is not None:
            log.warning("driver for %s died: %r — scheduling reap", r.model_tag, exc)
        self._spawn_bg(self._reap_dead_resident(r, exc))

    async def _reap_dead_resident(
        self, r: "Resident", exc: "BaseException | None" = None
    ) -> None:
        """Supervisor reaper: fail every pending future the dead driver owned
        (active_slot + ALL inflight riders) + unblock streaming routes, then
        mark DEAD + deregister + teardown (exactly-once via torn_down).

        ``exc`` is the driver's own typed exception (e.g.
        SidecarUnavailableError / SidecarTimeoutError), captured by
        _on_driver_done and threaded through here so the route's typed
        except-clauses can match it. Keyed on ``exc is None`` -- NOT on
        whether the driver task was cancelled -- because _on_driver_done's
        own ``exc = None if cancelled else task.exception()`` also yields
        None on ordinary successful completion (idle-evict self-teardown);
        collapsing that case into "treat as cancelled" would be wrong, but
        both share the same real requirement here: there is no real fault
        to attribute, so the pending-future fallback stays the generic
        RuntimeError rather than manufacturing a typed one.

        Design note: the SAME
        typed exception is given to active_slot and every inflight rider.
        This is not a misattribution -- the exception describes WHY THE
        DRIVER DIED, not what happened to any one request, and that fact is
        equally true and equally actionable (503 + Retry-After) for a rider
        that never got dispatched as for the slot that was mid-request. One
        accepted asymmetry: SidecarTimeoutError literally claims a timeout
        occurred, and a queued rider never entered a wait that could time
        out -- its true failure mode is "never got the chance," not "timed
        out." The route only branches on TYPE (-> 504), and 504 still reads
        to a client as "backend unresponsive, retry," which remains true of
        the resident even where it is not literally true of that one queued
        request. Accepted as-is; not addressed with new per-slot machinery.
        """
        # Always fail the pending futures (the driver abandoned them on death);
        # teardown stays exactly-once via the torn_down claim in _begin_unload_locked.
        async with self._registry_lock:
            pend = [r.active_slot, *list(r.inflight)]
        for s in pend:
            if s is None:
                continue
            if s.completion_future is not None and not s.completion_future.done():
                fail_exc = (
                    exc
                    if exc is not None
                    else RuntimeError(f"resident {r.model_tag!r} driver died")
                )
                self._fail_completion_future(s, fail_exc)
            ev = getattr(s, "stream_done_event", None)
            if ev is not None and not ev.is_set():
                ev.set()
        async with self._registry_lock:
            self._begin_unload_locked(r)

    def _idle_window_seconds(self, keep_alive_s: "int | None", default: int) -> int:
        """Per-resident idle-hot window from the latest keep_alive intent (mirrors
        the cap<=1 grace->idle math: None->default, <0->KEEP_ALIVE_MAX_S cap,
        else min(keep,cap); 0 disables idle)."""
        if keep_alive_s is None:
            return default
        if keep_alive_s < 0:
            return KEEP_ALIVE_MAX_S
        return min(keep_alive_s, KEEP_ALIVE_MAX_S)

    async def _same_model_residency_floor(
        self, r: "Resident", idle_window: int,
    ) -> "int | float":
        """The LIVE-path port of the same-model residency floor.

        Returns the idle window `_drive_resident` should actually use. When the
        client's keep_alive would tear this resident down NOW (``idle_window <=
        0``) but the NEXT queued request is for the SAME model, hold it warm for
        the bounded ``_SAME_MODEL_QUEUED_HOLD_S`` instead, so that request
        warm-inherits rather than paying a full teardown + respawn.

        Priority fairness GOVERNS: hold ONLY IF no strictly-higher-
        ranked client is already waiting. Holding warm OCCUPIES CAPACITY, so a
        lower-ranked same-model request must never keep a resident from a
        higher-ranked waiter -- "a lower-ranked client is not admitted ahead of a
        higher-ranked client that is already waiting". The holder compared
        against is ``r.grace_tip``, NOT the raw anchor slot, per the
        grace_tip discipline the caller already applies to every idle
        stash field for this same reason.

        ⚠ CALLER MUST HOLD NO LOCK. Both peeks take ``queue._lock``, and the
        established order is ``queue._lock -> _registry_lock``, never reversed
        and never an ``await queue._lock`` from inside ``_registry_lock``. The
        legacy copy of this floor (in the dead ``_process_slot``) was safe only
        because ``worker_loop`` held no lock where it sat; that argument does NOT
        survive the move onto this path, which is why this is an awaited helper
        called BEFORE the caller's ``_registry_lock`` block rather than an inline
        check inside it.

        Holding does NOT pin: the caller parks the resident IDLE_EVICTABLE with a
        real deadline, so ``_lru_idle_unloadable`` can still evict it for a
        higher-ranked waiter that arrives after this peek. That is what keeps the
        unavoidable peek staleness benign rather than a fairness hole.

        ⚠ KNOWN, CONSUMED LIMITATION:
        ``has_strictly_higher_priority_waiting`` scans ``queue._staging`` ONLY,
        never ``_accept_buf``, so a higher-ranked waiter sitting in the acceptance
        buffer yields False -- the PERMISSIVE answer -- and this floor holds while
        it waits. SCOPE is the OVERFLOW regime, not ordinary load: there is
        exactly ONE ``_accept_buf`` producer (``queue.enqueue``) and it is reached
        only once ``_staging`` is at ``staging_max`` (default 100). What makes it
        worth pinning is not its frequency but that the blind spot is specific to
        this one predicate -- its neighbour ``_has_listed_waiter_for_locked`` scans
        both buffers, and two other scans cover both buffers as well.
        Widening it is out of scope here; this floor only consumes the predicate
        and does not redefine it. A strict xfail in the live-path residency-floor
        test pins the gap so it
        cannot be closed silently.

        Best-effort: any peek failure returns ``idle_window`` untouched, so a
        queue hiccup can only cost a warm hold, never wrongly retain a resident.
        """
        if idle_window > 0 or r.model_tag is None:
            return idle_window
        holder = r.grace_tip
        if holder is None:
            return idle_window
        try:
            if await self.queue.head_model_tag() != r.model_tag:
                return idle_window
            if await self.queue.has_strictly_higher_priority_waiting(holder):
                log.info(
                    "same-model residency floor declined for %s: a strictly "
                    "higher-priority client is already waiting",
                    r.model_tag,
                )
                return idle_window
        except Exception:
            log.exception(
                "same-model residency floor peek failed (best-effort); "
                "leaving idle_window=%r unchanged", idle_window,
            )
            return idle_window
        log.info(
            "same-model residency floor: holding %s warm for %.0fs -- the next "
            "queued request is the same model and nothing outranks it",
            r.model_tag, _SAME_MODEL_QUEUED_HOLD_S,
        )
        return _SAME_MODEL_QUEUED_HOLD_S

    async def _spawn_for_resident(
        self, r: "Resident", slot: Slot
    ) -> "SidecarHandle | None":
        """Spawn r's sidecar OUTSIDE _registry_lock (the placeholder already
        reserved the budget). Per-spawn host safety gate (per-model), spawn,
        capture booting_pid under the lock (closes the reaper window), health-wait,
        then publish r.handle + state=ACTIVE under the lock. On failure: fail the
        slot future and return None (the finally/supervisor reaps the resident).

        ``spawn_flags`` is pre-bound to ``{}`` before the
        try -- a manifest gone missing between reserve and spawn (the
        pre-existing ``except FileNotFoundError`` below, degrade-open,
        unchanged) means ``spawn_flags`` is never assigned by the normal
        line just inside the try, but the failure branch further down now
        reads ``spawn_flags.get(...)`` unconditionally. An empty dict's
        ``.get(key, default)`` returns exactly the SAME degrade-open
        defaults ``_read_model_footprint`` already uses for a missing
        manifest (``main_gpu=0``, ``split_mode='layer'``) -- not a new
        behavior, just keeping the existing one from crashing."""
        argv: list[str] = []
        is_mlx = False
        spawn_flags: dict = {}
        try:
            manifest = read_manifest(self.boot.storage.manifests_path, slot.model_tag)
            is_mlx = manifest.is_mlx()
            if is_mlx:
                # MLX: no GGUF blob, no auto-placer (unified memory, no
                # per-card placement), no slot-save KV. Build argv from the MLX
                # closed allowlist (validated again at spawn time in mlx_spawn).
                argv = mlx_flags_to_argv(manifest.mlx_server_flags)
            else:
                spawn_flags = manifest.llama_server_flags
                # The reservation-time auto-placer may have overridden
                # main_gpu/split_mode on r (see _reserve_and_start_locked /
                # _auto_pick_gpu) — those are the ACTUAL admitted/reserved values.
                # Re-deriving argv from the raw manifest flags alone would spawn on
                # the manifest's original main_gpu, silently ignoring the
                # auto-placement decision (and defeating the whole feature — the
                # cross-resident gate would have checked one card while the process
                # binds another).
                # Override when the placement was OVERRIDDEN, not merely
                # when the manifest opted into auto-placement. manifest.auto_place
                # is NOT a complete test for an override: the
                # auto-placer is not the only thing that can move a resident off
                # its manifest card. The cross-card relocation sets
                # main_gpu_override EXCLUSIVELY on the arm the manifest.auto_place proxy excludes --
                # it is only ever set in the non-auto_place branch of
                # _route_or_reserve, whose guard is the exact complement of
                # this one -- so a test on manifest.auto_place alone would keep the
                # relocated card from reaching argv by construction: the manager
                # would gate card X while the process bound card Y.
                # The guarantee: argv reflects the placement the cross-resident VRAM
                # gate actually admitted, and the manifest's own main_gpu/split_mode
                # govern argv IF AND ONLY IF nothing overrode them.
                # Byte-identity is owed to UN-OVERRIDDEN spawns, not to
                # non-auto_place spawns; those are different sets
                # whenever a relocation override is in play.
                # Same scope as
                # reasoning_budget_override's own claim below.
                manifest_split = str(
                    spawn_flags.get("split_mode", "layer") or "layer"
                )
                if (manifest.auto_place and manifest_split == "none") or (
                    r.placement_overridden
                ):
                    spawn_flags = {
                        **spawn_flags,
                        "main_gpu": r.main_gpu,
                        "split_mode": r.split_mode,
                    }
                # Identical hazard/shape to the
                # main_gpu/split_mode override just above -- the reservation-time
                # resolution (_reserve_and_start_locked) already decided what the
                # FIRST caller's reasoning_effort resolves to against this
                # manifest's own reasoning_budget; r.reasoning_budget_override is
                # the ACTUAL admitted value. Re-deriving argv from the raw
                # manifest flags alone would spawn with the manifest's
                # UNMODIFIED reasoning_budget, silently ignoring what the first
                # caller asked for. None (no reasoning_effort asked, or nothing
                # to take a fraction of) leaves the manifest's own value
                # untouched -- the non-reasoning_effort path stays byte-identical.
                if r.reasoning_budget_override is not None:
                    spawn_flags = {
                        **spawn_flags,
                        "reasoning_budget": r.reasoning_budget_override,
                    }
                argv = flags_to_argv(spawn_flags)
                gguf_path = (
                    self.boot.storage.blob_store_path
                    / "sha256"
                    / manifest.gguf_blob_sha256[:2]
                    / manifest.gguf_blob_sha256
                )
                # Vision projector (mmproj): resolve the CONTENT-ADDRESSED blob and
                # inject --mmproj. Manager-derived path only; the raw path-bearing
                # `mmproj` flag stays in DENIED_FLAGS (no arbitrary file).
                if manifest.mmproj_blob_sha256:
                    argv += ["--mmproj", str(
                        self.boot.storage.blob_store_path
                        / "sha256"
                        / manifest.mmproj_blob_sha256[:2]
                        / manifest.mmproj_blob_sha256
                    )]
                # Standalone draft model (D-Flash/D-Spark): same
                # content-addressed pattern as mmproj above -- resolve the blob and
                # inject --spec-draft-model (engine/.../common/arg.cpp, aliases
                # -md/--model-draft). Manager-derived path only; the raw path/repo-
                # bearing spec_draft_model/spec_draft_hf_repo flags are NOT
                # allowlisted (see manifest.py's field comment + suffix guard).
                # Gated on spec_type too, not
                # the hash alone -- the engine's has_dft() keys purely on the draft
                # path being non-empty and never consults spec_type, so a hash-only
                # manifest (spec_type omitted, or draft-mtp, which uses a bundled
                # head and never needs a standalone drafter) would otherwise load a
                # full second, entirely unbudgeted model at the target's full
                # ctx_size -- an authorable availability hazard. Logged, not
                # silently dropped, when the hash is set but spec_type doesn't
                # qualify.
                _spec_type_for_draft = str(spawn_flags.get("spec_type", "") or "").strip().lower()
                if manifest.spec_draft_gguf_blob_sha256:
                    if _spec_type_for_draft in SPEC_TYPES_WITH_STANDALONE_DRAFT_MODEL:
                        argv += ["--spec-draft-model", str(
                            self.boot.storage.blob_store_path
                            / "sha256"
                            / manifest.spec_draft_gguf_blob_sha256[:2]
                            / manifest.spec_draft_gguf_blob_sha256
                        )]
                    else:
                        log.warning(
                            "spec_draft_gguf_blob_sha256 set (%s...) but "
                            "spec_type=%r does not use a standalone draft model "
                            "-- ignored, no --spec-draft-model injected; "
                            "model_tag=%s",
                            manifest.spec_draft_gguf_blob_sha256[:12],
                            _spec_type_for_draft or None, manifest.model_tag,
                        )
                        # This manager-detected downgrade (config
                        # never even reaches the engine) is the SAME informational
                        # category as the engine-detected one -- surface it on
                        # the same channel so the user sees it too, not just the
                        # log. arch is unknown here (no GGUF read at this point,
                        # never fabricated); component="draft" reuses the engine's own
                        # vocabulary since this IS specifically the draft-model
                        # injection path.
                        spec_downgrade_log.log_spec_downgrade(
                            model_tag=manifest.model_tag, source="manager_config",
                            component="draft", reason_code="spec_type_mismatch",
                            detail=(
                                f"spec_draft_gguf_blob_sha256 set but "
                                f"spec_type={_spec_type_for_draft or None!r} does "
                                "not use a standalone draft model"
                            ),
                        )
        except FileNotFoundError:
            gguf_path = self.boot.storage.blob_store_path / "missing.gguf"
        # Per-model host safety gate (RAM/IO/load + the per-spawn VRAM/KV gate). The
        # CROSS-resident over-commit gate already ran under the lock at reserve.
        # For MLX, expected_vram_bytes is 0 (unified memory), so the VRAM pre-check
        # is a no-op and RAM/IO gates still apply.
        if self.runtime.queue.safety_enabled:
            # TOCTOU baseline. r.spawn_barrier_active
            # only flips True under the lock below, AFTER this gate's own await
            # points -- a same-tag rider's _route_or_reserve can run to completion
            # (sees spawn_barrier_active still False, gets inboxed normally) in
            # that window. Snapshot the inbox depth NOW, before the first await,
            # so any items beyond this count once we reach the lock are provably
            # this window's own arrivals, not pre-existing legitimate queuing.
            pre_gate_inbox_n = r.inbox.qsize() if r.inbox is not None else 0
            failed = await self._run_spawn_safety_gate(r, slot)
            if failed:
                # Spawn reclaim barrier. Entry predicate, both halves
                # required: (i) STRUCTURAL CLASS -- every failed gate must be
                # classified blocked_on="vram" (a bare kill switch AND a fail-
                # closed default for any unclassified/future gate); (ii)
                # POSITIVE EVIDENCE -- a live release task already tearing down
                # VRAM on the exact card(s) this refusal names. Absence of
                # EITHER half is terminal on the first gate run, byte-identical
                # to today, just with the failing gate name/detail now also on
                # the audit trail.
                msm, mmg = self._spawn_gate_placement(r, slot)
                budget = self.runtime.queue.spawn_reclaim_wait_max_s
                eligible = budget > 0.0 and all(
                    g.blocked_on == "vram" for g in failed
                )
                watch: set = set()
                cards: list[int] = []
                pledged_mib = 0
                if eligible:
                    # The split-card COUNT is a
                    # fresh nvidia-smi read (safety.py, subprocess.check_output,
                    # 5s timeout) -- OFF-LOOP and BEFORE the lock, matching the
                    # established convention (every
                    # loop-side nvidia-smi call is wrapped in
                    # asyncio.to_thread, never a bare sync call under a lock).
                    # Only needed on the split (non-"none") arm; a single-GPU
                    # pin never reads it. _spawn_barrier_watch_locked itself
                    # must do ZERO I/O -- it takes the count, not the probe.
                    split_card_count = 0
                    if (msm or "layer").lower() != "none":
                        split_card_count = len(
                            await asyncio.to_thread(_read_free_vram_all_mib) or []
                        )
                    async with self._registry_lock:
                        watch, cards, pledged_mib = self._spawn_barrier_watch_locked(
                            msm, mmg, split_card_count,
                        )
                        if watch:
                            r.spawn_barrier_active = True
                            # Close the TOCTOU
                            # window now, still under this SAME lock (every
                            # r.inbox.put_nowait site -- _route_to, the legacy
                            # single-instance HIT -- also takes this lock first,
                            # so nothing can put concurrently with this drain,
                            # and _drive_resident does not start pulling from
                            # r.inbox until AFTER _spawn_for_resident returns --
                            # no consumer races this either). FIFO: anything
                            # beyond pre_gate_inbox_n arrived DURING the gate's
                            # own await window and must go through the SAME
                            # _defer_unroutable funnel the other defer paths already use
                            # (called unchanged) instead of sitting in an
                            # inbox that loses disconnect interception for the
                            # whole barrier hold. Pre-existing riders (within
                            # the baseline) are put back untouched, in order --
                            # this drain only ever touches the TAIL.
                            if r.inbox is not None:
                                total = r.inbox.qsize()
                                if total > pre_gate_inbox_n:
                                    drained = [
                                        r.inbox.get_nowait() for _ in range(total)
                                    ]
                                    for kept in drained[:pre_gate_inbox_n]:
                                        r.inbox.put_nowait(kept)
                                    for rider in drained[pre_gate_inbox_n:]:
                                        self._defer_unroutable(
                                            rider, evict_pending=True,
                                        )
                if watch:
                    proceed = await self._await_reclaim_barrier(
                        r, slot, failed, msm, mmg, watch, cards, pledged_mib,
                    )
                    if not proceed:
                        return None
                    # else: a re-gate came back clean -- fall through to spawn
                    # below, byte-identical to a first-try clean gate.
                else:
                    # TODAY'S BEHAVIOUR, unchanged: terminal on the first gate
                    # run. Now also audited (this path previously logged but
                    # never emitted an audit event).
                    detail = "; ".join(f"{g.name}: {g.detail}" for g in failed)
                    await self._audit_async(slot, "safety_gate_refused")
                    await self._audit_event_only_async(
                        slot.slot_id, "safety_gate_detail",
                        {"failed": [
                            {"name": g.name, "detail": g.detail} for g in failed
                        ]},
                    )
                    await self._fail_or_reroute_refused_spawn(
                        r, slot, RuntimeError(f"safety gates refused spawn: {detail}")
                    )
                    return None
        prior_port, prior_pid = slot.port, slot.pid
        try:
            if is_mlx:
                handle = mlx_spawn(
                    r.port,
                    slot.model_tag,
                    manifest.model_repo,
                    manifest.model_path,
                    manifest.mlx_server_flags,
                    python_binary=self.boot.runtime.mlx_python_binary,
                )
            else:
                handle = self._spawn(
                    self.boot.runtime.llama_server_binary,
                    gguf_path,
                    r.port,
                    slot.model_tag,
                    argv,
                    binary_fd=self._binary_fd,
                )
            # A fresh sidecar on this port invalidates any earlier probe-recorded
            # think-free count for it (different process, possibly different
            # model) -- drop the stale entry per the register's documented
            # invariant.
            self._clean_prefill_tokens.pop(handle.port, None)
            # Same for the poisoned-chain register: a fresh engine has no memory of
            # the old slot's poison.
            self._poisoned_chain_fps.pop(handle.port, None)
            async with self._registry_lock:
                r.booting_pid = handle.pid  # in the reaper union before handle is set
            slot.port = handle.port
            slot.pid = handle.pid
            # DURABLE IDENTITY: record (pid, port, starttime) so boot_orphan_reaper
            # can prove ownership after a crash and reject PID reuse. Best-effort.
            self._record_engine_identity(slot)
        except Exception as exc:
            # The engine could not be started, or something between starting it and
            # recording it raised. If the tag has another live engine the request
            # goes there and this driver ends normally (its cleanup runs as on any
            # other early return, including the reap of a booting pid already
            # recorded); with none, the exception escapes unchanged.
            if not await self._fail_or_reroute_refused_spawn(r, slot, None):
                raise
            # The request now belongs to another engine: drop the dead engine's
            # identifiers from it, back to what it carried before this attempt.
            slot.port, slot.pid = prior_port, prior_pid
            log.warning(
                "starting an extra engine for %s raised %s; routed the request to "
                "the running engine", slot.model_tag, type(exc).__name__,
            )
            return None
        # This IS the re-admission moment for a previously
        # OOM-requeued slot (a fresh spawn/health attempt is starting) --
        # clear the flag here so submit_and_wait's timeout_s exemption does
        # not apply while THIS attempt is in flight (the flag is cleared
        # on admission). Re-set again below if THIS attempt also OOMs.
        slot.oom_requeue_pending = False
        healthy = await self._wait_healthy(
            r.port, self.runtime.queue.loading_health_timeout_s,
            is_alive=handle.is_alive,
        )
        if not healthy:
            # This path had ZERO engine-log-for-errors
            # observability previously; this adds the SAME scan the
            # single-slot cold path already runs, so an OOM
            # load failure here can be classified at all. Sits beside the
            # existing spec-downgrade scan below (a different signature,
            # unaffected, still only runs on the healthy branch).
            _errs = load_verify_log.scan_engine_log_for_errors(
                getattr(handle, "engine_log_path", None),
            )
            # An OOM-classified failure with a live disconnect
            # signal goes back in the queue instead of failing (decision logic:
            # see _requeue_on_oom_load_failure for the full rules). Every
            # other case below is byte-identical to before this check was added.
            # Pass the RESOLVED spawn_flags placement
            # (post auto-place/Fast Lane relocation override, same values
            # argv was built from) into the never-fits check,
            # not the manifest's raw main_gpu/split_mode.
            _requeued = await self._requeue_on_oom_load_failure(
                slot,
                _errs,
                int(spawn_flags.get("main_gpu", 0) or 0),
                str(spawn_flags.get("split_mode", "layer") or "layer"),
                r,
            )
            if not _requeued:
                await self._fail_or_reroute_refused_spawn(
                    r, slot, RuntimeError("loading-fail-health-timeout")
                )
            # Reap the spawned-but-unhealthy sidecar + clear booting_pid, else it
            # lingers in _live_handle_pids (so the orphan reaper SKIPS it) =
            # permanent PID+VRAM leak. Mirrors the cap<=1 path's _teardown here.
            # Unconditional either way -- this dead spawn attempt is
            # cleaned up whether the slot was failed or requeued; only the
            # slot's own fate (above) differs.
            async with self._registry_lock:
                r.booting_pid = None
            if handle.is_alive():
                await self._reap_resident_handle(handle)
            return None
        # The resident-driver spawn path (cap>=2) would otherwise have
        # ZERO load-verify-style engine-log observability
        # (scan_engine_log_for_errors has exactly one other call site in this
        # file, in the single-slot cold path _process_slot, and this function
        # is not it). The scan is placed here,
        # right after the SAME health confirmation _process_slot's own scan
        # sits after, so a model spawned via cap>=2 gets the same
        # SPEC_DOWNGRADED visibility as the single-slot cold path, not just
        # the one already-instrumented call site.
        _spec_dg = spec_downgrade_log.scan_engine_log_for_spec_downgrade(
            getattr(handle, "engine_log_path", None),
        )
        if _spec_dg.get("spec_downgraded"):
            spec_downgrade_log.log_spec_downgrade(
                model_tag=slot.model_tag, source="engine_log",
                arch=_spec_dg.get("arch"), component=_spec_dg.get("component"),
                reason_code=_spec_dg.get("reason"), detail=_spec_dg.get("detail"),
            )
        # Best-effort KV restore after a healthy (re)spawn so the next same-thread
        # request reuses the slot KV (prefix-match) instead of re-prefilling.
        # MLX has no slot-save KV cache (unified memory, no /slot-save-path), so
        # skip it there.
        if not is_mlx:
            _expected_tokens = await self._restore_slot_kv(r.port, r.model_tag, slot)
            # This resident-driver restore is the SAME disk-restore
            # mechanism as the cold single-slot site above (a session return IS the cold
            # path), and without this call it would emit no LOAD_VERIFY record at all.
            # trigger="session-return" distinguishes it from the single-slot cold
            # path's trigger="spawn" in the ring.
            try:
                # Pass the engine's own restore-response token count
                # (if _restore_slot_kv_inner captured one) as the actual_n_past
                # override -- verify_kv_restored skips its own racy /slots re-GET
                # entirely when this is provided. None here (no count captured) falls
                # through to today's GET-based behavior unchanged.
                _actual_n_past = (getattr(self, "_kv_restore_actual_tokens", {}) or {}).pop(r.port, None)
                _kv = await load_verify_log.verify_kv_restored(
                    handle, 0, _expected_tokens, actual_n_past=_actual_n_past,
                )
                # Derived from the SAME verdict already computed above, mirroring
                # the model_load site's "ok" if healthy else "failed" pattern --
                # True is the only pass; None (never established) reads as
                # "unverified", not "ok" (log_load_verify enforces this same rule
                # structurally too, so a future regression here still can't ship
                # a passing status alongside a non-True verdict).
                _kv_restore_ok = _kv.get("kv_restore_ok")
                load_verify_log.log_load_verify(
                    event="kv_restore", trigger="session-return",
                    model_tag=r.model_tag, port=r.port,
                    pid=getattr(handle, "pid", None),
                    # process_alive is the SAME read verify_kv_restored just took
                    # (engine liveness at the instant of the /slots read), not a
                    # hardcoded assumption.
                    # health_200/model_resident have no kv_restore-
                    # path equivalent read of their own here either (this is the
                    # third site with this exact pattern; the other two sites
                    # hardcode True for them instead of reading them).
                    # None:
                    # genuinely not measured on THIS record.
                    process_alive=_kv.get("process_alive"), health_200=None, model_resident=None,
                    kv_expected_tokens=_kv.get("kv_expected_tokens"),
                    kv_actual_n_past=_kv.get("kv_actual_n_past"),
                    kv_restore_ok=_kv_restore_ok,
                    restore_attempted=_kv.get("restore_attempted"),
                    kv_expected_reason=_kv.get("kv_expected_reason"),
                    kv_actual_reason=_kv.get("kv_actual_reason"),
                    retry_count=0,
                    final_status=(
                        "ok" if _kv_restore_ok is True
                        else "unverified" if _kv_restore_ok is None
                        else "failed"
                    ),
                    reason=_kv.get("reason"),
                    source=_kv.get("source"),
                    slots_http_status=_kv.get("slots_http_status"),
                    slot_id_found=_kv.get("slot_id_found"),
                    session_id=(slot.client_meta or {}).get("session_id") if isinstance(slot.client_meta, dict) else None,
                )
            except Exception:
                log.debug("LOAD_VERIFY kv_restore (session-return) emit failed (best-effort)", exc_info=True)
        async with self._registry_lock:
            r.handle = handle
            r.booting_pid = None
            _transition_resident_state(r.state, ResidentState.ACTIVE)
            r.state = ResidentState.ACTIVE
            r.spawn_seq += 1  # live-monitor: new active handle on this resident
            # This turn's client, not whoever r served before
            # it last parked (idle_client_meta) -- covers the respawn-after-
            # eviction case, not just the initial reserve.
            r.rank_client_meta = slot.client_meta
        return handle

    def _occupied_vram_mib(
        self, main_gpu: int, exclude_model_tag: "str | None" = None,
    ) -> int:
        """VRAM reserved by still-booting SIBLINGS on the SAME card as the
        incoming spawn. Genuinely mirrors
        _vram_admits_locked's reserve loop (RESERVED_LOADING AND
        main_gpu match, nothing else) so the safety.py gates can budget
        against EFFECTIVE free = nvidia-smi minus this hold, without
        double-counting an already-loaded sibling.

        An ACTIVE/GRACE/IDLE_EVICTABLE sibling is NOT charged here: its VRAM
        is already absent from the live nvidia-smi free reading (see the
        safety-gate VRAM math), so charging it again would be the
        exact double-count. A RESERVED_LOADING sibling on a
        DIFFERENT card is also not charged -- its weights aren't landing on
        THIS card. Zero when no same-card still-loading sibling exists
        (including the common case of no other resident at all).

        exclude_model_tag: pass the CALLER's own slot.model_tag when this is
        invoked as a POST-reservation re-check (_run_spawn_safety_gate) --
        by that point the caller's own Resident is already inserted into
        self._residents as RESERVED_LOADING on this same card (reservation
        happens in _reserve_and_start_locked, before the re-check runs), so
        without excluding it here a spawn would charge its OWN reservation
        against itself. _vram_admits_locked never needed this: it runs
        BEFORE insertion, so a resident-to-be can never appear in its own
        siblings list by construction -- this function is called from a
        later point in the lifecycle where that ordering guarantee no
        longer holds, so the exclusion has to be explicit instead."""
        return sum(
            r.reserved_need_mib
            for r in self._model_residents()
            if r.state is ResidentState.RESERVED_LOADING
            and r.main_gpu == main_gpu
            and r.model_tag != exclude_model_tag
        )

    async def _run_spawn_safety_gate(
        self, r: "Resident", slot: Slot
    ) -> "list[GateResult]":
        """Run all_safety_gates for slot.model_tag exactly as the cap<=1 path does
        (manifest-derived params, FRESH read — same as before this change). Returns
        the FAILED GateResults (empty list == all-pass); the caller
        reads GateResult.blocked_on off them to decide whether a spawn-reclaim
        barrier wait is even eligible. Logged on any refusal, as on that path —
        audit emission lives at the call site, since a refusal
        may or may not be terminal depending on the barrier's own decision.

        split_mode/main_gpu default to this fresh read (byte-identical
        to the earlier behavior, including picking up a manifest edited/deleted in the
        reserve->spawn window — the driver runs as a separate asyncio task, so
        that window is real). ONLY when this fresh read shows auto_place=True and
        its own split_mode=='none' do we substitute r.main_gpu/r.split_mode — the
        reservation's settled auto-placed values — so the gate checks the SAME
        card the cross-resident gate already admitted against. Mirrors
        _spawn_for_resident's argv-override condition exactly, so the gate and
        the actual spawn command always agree with each other.
        That condition is the DISJUNCTION with
        r.placement_overridden (a Fast Lane relocation overrides placement
        on the non-auto_place arm, which the auto_place test excludes by
        construction). The mirror is preserved deliberately — both sites move
        together, because widening only the argv side would leave this
        gate budgeting the manifest card while the process binds the relocated
        one, inverting the very mismatch being fixed. An earlier
        version of this method used r.main_gpu/r.split_mode unconditionally,
        which was wrong for auto_place=False: it gated on the RESERVATION-time
        manifest read instead of a fresh one, silently diverging from historical
        behavior if the manifest changed in that window."""
        mv = mc = mg = 0
        mq = "f16"
        mqv = "f16"
        mnk = False
        mp = 1
        msm = "layer"
        mmg = 0
        mcm = False
        mhkr = 1.0
        madims = None
        mkbpt = None
        mexpmib = 0
        m_ts = None
        m_mtp = False
        try:
            m = read_manifest(self.boot.storage.manifests_path, slot.model_tag)
            mv = m.expected_vram_bytes or 0
            m_ts = m.llama_server_flags.get("tensor_split")
            mg = m.gguf_size_bytes or 0
            mc = m.llama_server_flags.get("ctx_size") or m.context_size or 0
            mq = m.llama_server_flags.get("cache_type_k") or "f16"
            mqv = m.llama_server_flags.get("cache_type_v") or mq
            mnk = bool(m.llama_server_flags.get("no_kv_offload", False))
            mp = int(m.llama_server_flags.get("parallel", 1) or 1)
            msm = str(m.llama_server_flags.get("split_mode", "layer") or "layer")
            mmg = int(m.llama_server_flags.get("main_gpu", 0) or 0)
            mcm = bool(
                m.llama_server_flags.get("cpu_moe")
                or int(m.llama_server_flags.get("n_cpu_moe", 0) or 0) > 0
            )
            # hybrid_kv_ratio: manifest model property for hybrid models
            # (see _read_model_footprint for the rationale; same field,
            # same [0.0, 1.0] validator).
            mhkr = m.hybrid_kv_ratio
            self._announce_hybrid_kv(slot.model_tag, mhkr, "spawn gate")
            # Dimension-aware KV dims (cached) + measured override.
            madims = self._attn_kv_dims_for(m)
            mkbpt = getattr(m, "kv_bytes_per_token", None)
            # Speculative-decoding recurrent-state flag:
            # same predicate _read_model_footprint and _engine_fingerprint
            # already use -- one manifest field, read the same
            # way everywhere. See _read_model_footprint's comment for why
            # SPEC_TYPES_NEEDING_RS_SEQ is the right set here and why the
            # coercion stays despite read_manifest()'s own re-validation.
            m_mtp = (
                str(m.llama_server_flags.get("spec_type", "") or "").strip().lower()
                in SPEC_TYPES_NEEDING_RS_SEQ
            )
            # Exact offloaded MoE expert bytes (0 if not configured
            # or underiveable -- moe_ram_fit gate no-ops in that case).
            mexpmib = self._expert_offloaded_mib_for(m)
            # Must stay the EXACT disjunction _spawn_for_resident
            # uses -- this method's own docstring promises the gate and the
            # spawn command always agree with each other, so widening one
            # without the other would not fix the mismatch, only invert it
            # (gate on the manifest card, process on the relocated one).
            if (m.auto_place and msm == "none") or r.placement_overridden:
                msm = r.split_mode
                mmg = r.main_gpu
        except FileNotFoundError:
            mv = 0
            mexpmib = 0
        gates = await asyncio.to_thread(all_safety_gates,
            min_free_ram_mib=self.runtime.queue.safety_min_free_ram_mib,
            min_free_vram_mib=self.runtime.queue.safety_min_free_vram_mib,
            max_cpu_busy_percent=self.runtime.queue.safety_max_cpu_busy_percent,
            max_iowait_percent=self.runtime.queue.safety_max_iowait_percent,
            manifest_expected_vram_bytes=mv,
            cpu_util_sample_window_s=self.runtime.queue.safety_cpu_util_sample_window_s,
            iowait_sample_window_s=self.runtime.queue.safety_iowait_sample_window_s,
            ctx_size=mc, gguf_size_bytes=mg, kv_cache_quant=mq,
            kv_cache_quant_v=mqv,
            no_kv_offload=mnk, parallel=mp, split_mode=msm, main_gpu=mmg,
            cpu_moe_offload=mcm,
            hybrid_kv_ratio=mhkr,
            attn_dims=madims,
            kv_bytes_per_token=mkbpt,
            mtp_draft_active=m_mtp,
            expert_offloaded_mib=mexpmib,
            # Budget against EFFECTIVE free = nvidia-smi minus VRAM
            # held by a same-card still-loading sibling. mmg reflects any
            # auto-place override from above, so this charges the SAME card
            # the spawn will land on. exclude_model_tag=slot.model_tag: r
            # (this spawn) is ALREADY in self._residents as RESERVED_LOADING
            # by this point (inserted at reservation, before this re-check
            # runs) -- without excluding it, a spawn would charge its own
            # reservation against itself.
            occupied_vram_mib=self._occupied_vram_mib(
                main_gpu=mmg, exclude_model_tag=slot.model_tag,
            ),
            tensor_split=m_ts,
        )
        failed = [g for g in gates if not g.ok]
        if failed:
            detail = "; ".join(f"{g.name}: {g.detail}" for g in failed)
            log.warning(
                "safety gates refused spawn for %s: %s",
                slot.slot_id, detail,
            )
        return failed

    async def _fail_or_reroute_refused_spawn(
        self, r: "Resident", slot: Slot, exc: "Exception | None",
    ) -> bool:
        """Engine ``r``, started for ``slot``, was refused by a host safety gate,
        could not be started, or failed to load. If the tag already has another
        live or still-loading engine, ``r`` was only an extra copy: hand the request to
        that engine instead of failing it, so a busy host does not turn a request that
        engine can serve into an error. With no other such engine (a cold start)
        there is nothing to fall back to and the request fails with ``exc``, as
        always. Returns True when the request was handed over; with ``exc=None`` a
        request that could not be handed over is left untouched for the caller to
        deal with (returns False).

        An engine in a reclaim barrier wait, or one without an inbox, is not a
        candidate; if it is the only other engine the request fails as before.

        The hand-off mirrors ``_route_to`` in ``_route_or_reserve``; keep the two in
        sync."""
        async with self._registry_lock:
            others = [
                i for i in self._instances_for(slot.model_tag)
                if i is not r and i.state is not ResidentState.DEAD
                and not i.spawn_barrier_active and i.inbox is not None
            ]
            chosen = self._pick_instance_for(slot, slot.model_tag, others)
            if chosen is not None:
                log.info(
                    "second engine for %s did not start; routing the "
                    "request to the running engine %s",
                    slot.model_tag, chosen.resident_key,
                )
                if chosen.state is ResidentState.IDLE_EVICTABLE:
                    _transition_resident_state(chosen.state, ResidentState.ACTIVE)
                    chosen.state = ResidentState.ACTIVE
                chosen.last_active_monotonic = time.monotonic()
                self._restore_warm_recue_identity(
                    chosen.idle_client_meta, chosen.idle_thread_id, slot,
                )
                self._warn_if_reasoning_effort_mismatch(chosen, slot)
                chosen.inbox.put_nowait(slot)
                # Right after the enqueue: from here the slot belongs to ``chosen``,
                # so the driver's orphan check must never fail it.
                r.rerouted_slot = slot
                self._park_fastlane_claim_locked(slot, chosen)
                self._note_handed_off_waiting(slot)
                return True
        if exc is not None:
            self._fail_completion_future(slot, exc)
        return False

    def _spawn_gate_placement(self, r: "Resident", slot: Slot) -> "tuple[str, int]":
        """Fresh split_mode/main_gpu for slot's spawn gate -- the SAME two
        inputs _run_spawn_safety_gate itself derives (a manifest read + the
        auto_place-OR-placement_overridden override, mirrored here
        verbatim), which is the ONLY thing the reclaim barrier
        needs from the gate to scope its watch set correctly.

        Deliberately NEVER r.main_gpu/r.split_mode directly: those are the
        RESERVATION-time values, and _run_spawn_safety_gate's own docstring
        explains why a manifest edited in the reserve->spawn window can make
        them differ from what the gate that JUST refused actually checked --
        watching the wrong card would silently defeat the barrier.

        A second, independent read_manifest() call rather than threading a
        return value out of _run_spawn_safety_gate: that function's contract
        is `-> list[GateResult]`, a shape this barrier leaves alone, and it only
        runs on the refusal path (rare, not the hot spawn path) -- so the
        extra read is cheap and keeps that function's internals untouched.
        Disclosed here rather than silently duplicated: a manifest editable
        mid-window means these two reads are not provably identical, only
        extremely likely to be (same file, same instant, no lock protects
        either read) -- an accepted, narrow risk, not a claim of atomicity.

        The mirrored condition is
        the DISJUNCTION `(m.auto_place and msm == "none") or
        r.placement_overridden`, not the narrower `auto_place`-only test this
        helper could otherwise use --
        a Fast Lane relocation overrides placement on the non-
        auto_place arm, which the auto_place-only test excludes by
        construction. Both sites (_run_spawn_safety_gate's own copy and this
        one) must move together, or the gate and this barrier would disagree
        about which card a relocated claimant is actually on.
        """
        msm, mmg = "layer", 0
        try:
            m = read_manifest(self.boot.storage.manifests_path, slot.model_tag)
            msm = str(m.llama_server_flags.get("split_mode", "layer") or "layer")
            mmg = int(m.llama_server_flags.get("main_gpu", 0) or 0)
            if (m.auto_place and msm == "none") or r.placement_overridden:
                msm = r.split_mode
                mmg = r.main_gpu
        except FileNotFoundError:
            pass
        return msm, mmg

    def _spawn_barrier_watch_locked(
        self, msm: str, mmg: int, split_card_count: int,
    ) -> "tuple[set, list[int], int]":
        """CALLER HOLDS _registry_lock. Positive-evidence probe for the
        reclaim barrier: the live asyncio.Tasks already tearing down
        VRAM on the card(s) this spawn's gate just refused against, scoped
        EXACTLY as safety._vram_budget scopes its own free-VRAM read --
        {mmg} only when msm == 'none' (single-GPU pin), every visible card
        otherwise. Deliberately NO else-fallback to "all cards" when mmg
        itself has zero tasks: a single-GPU pin must watch ONLY its own
        card, or a release on an unrelated card would wake a barrier it
        can't actually help.

        This method does ZERO I/O. Calling
        _read_free_vram_all_mib() here (a
        synchronous nvidia-smi, safety.py, 5s timeout) directly under
        _registry_lock, on the event loop -- would be exactly the pattern
        the no-blocking-I/O-under-lock rule exists to forbid.
        split_card_count is that same read's LENGTH, taken by the caller via
        `await asyncio.to_thread(_read_free_vram_all_mib)` BEFORE acquiring
        the lock; this method only consumes the count.

        Returns (watch, cards, pledged_mib): watch is the snapshot itself
        (the caller must not re-scan _card_release_tasks after this --
        that is what makes it a WAIT, not a poll); cards is the scoped list
        (for the audit event); pledged_mib is the sum of
        _pending_reclaim_mib already credited across those cards, at THIS
        instant -- also audit-only, never a control input (the only
        sufficiency proof is the re-run gate).
        """
        if (msm or "layer").lower() == "none":
            cards = [mmg]
        else:
            cards = list(range(split_card_count))
        watch: set = set()
        for c in cards:
            watch |= set(self._card_release_tasks.get(c, ()))
        pledged_mib = sum(self._pending_reclaim_mib.get(c, 0) for c in cards)
        return watch, cards, pledged_mib

    async def _await_reclaim_barrier(
        self, r: "Resident", slot: Slot, failed: "list[GateResult]",
        msm: str, mmg: int, watch: set, cards: "list[int]", pledged_mib: int,
    ) -> bool:
        """CALLER HOLDS NOTHING (the wait itself must not hold _registry_lock
        for up to spawn_reclaim_wait_max_s). Waits on `watch` -- the ENTRY
        snapshot, never re-scanned (a reclaim that starts mid-wait is never
        chased) -- re-running the FULL _run_spawn_safety_gate on every
        watched-task completion or every _SPAWN_RECLAIM_REGATE_TICK_S,
        whichever comes first, until either a re-gate comes back clean or an
        absolute deadline computed ONCE at entry is reached.

        Returns True once a re-gate comes back clean (caller proceeds to
        spawn, byte-identical to a clean first gate run). Returns False once
        this method has ALREADY handled a terminal outcome itself (client
        disconnect -> _handle_unloaded_slot; resident died; deadline reached
        with no VRAM evidence left) -- caller returns None without any
        further action. Whole body in try/finally: r.spawn_barrier_active is
        cleared under _registry_lock on every exit path, never left set.
        """
        budget = self.runtime.queue.spawn_reclaim_wait_max_s
        deadline = time.monotonic() + budget
        started = time.monotonic()
        regates = 0
        outcome = "unknown"
        try:
            while True:
                if slot.disconnect_event is not None and slot.disconnect_event.is_set():
                    outcome = "disconnected"
                    self._handle_unloaded_slot(slot)
                    return False
                if r.state is ResidentState.DEAD:
                    outcome = "resident_dead"
                    self._fail_completion_future(
                        slot,
                        RuntimeError(
                            f"resident for {slot.model_tag!r} died while "
                            "awaiting the spawn reclaim barrier"
                        ),
                    )
                    return False
                # Shrink-only, never re-populated from a fresh scan.
                watch = {t for t in watch if not t.done()}
                if not watch:
                    # No evidence left in flight -- absence of proof is
                    # terminal, immediately. Waiting out the rest of the
                    # budget with nothing that could change the reading
                    # would be hope-polling, which this design exists
                    # specifically to not do.
                    outcome = "no_evidence_remaining"
                    break
                remaining = deadline - time.monotonic()
                if remaining <= 0.0:
                    outcome = "deadline"
                    break
                tick = min(_SPAWN_RECLAIM_REGATE_TICK_S, remaining)
                await asyncio.wait(watch, timeout=tick)
                regates += 1
                failed = await self._run_spawn_safety_gate(r, slot)
                if not failed:
                    outcome = "cleared"
                    return True
            detail = "; ".join(f"{g.name}: {g.detail}" for g in failed)
            await self._audit_async(slot, "safety_gate_refused")
            await self._audit_event_only_async(
                slot.slot_id, "safety_gate_detail",
                {"failed": [{"name": g.name, "detail": g.detail} for g in failed]},
            )
            await self._fail_or_reroute_refused_spawn(
                r, slot, RuntimeError(f"safety gates refused spawn: {detail}")
            )
            return False
        finally:
            async with self._registry_lock:
                r.spawn_barrier_active = False
            await self._audit_event_only_async(
                slot.slot_id, "spawn_reclaim_wait",
                {
                    "cards": cards, "pledged_mib": pledged_mib,
                    "watched": len(watch), "waited_s": time.monotonic() - started,
                    "regates": regates, "outcome": outcome,
                },
            )

    def _should_defer_admission(self, r: "Resident") -> bool:
        """Cheap, lock-free hint -- is it possibly worth pausing before r
        self-admits from its own inbox, to give a CROSS-MODEL priority claim a
        real chance to land? Reads ``self._cross_model_defer_hint``, the same
        ``listed_waiter_model_tags()`` snapshot ``_route_or_reserve`` already
        computes under ``queue._lock`` each time it runs --
        staleness accepted the identical way that snapshot's own existing use
        already is. Never awaits, never needs to be RIGHT about who is
        waiting -- only whether opening a window is worth it; the actual
        eviction/swap decision always stays with the properly-locked
        ``_lru_idle_unloadable``/``_route_or_reserve`` path, which has a fresh
        view when it acts.

        True only when the hint names a model_tag OTHER than r's own -- a
        same-model listed waiter is already served optimally by
        ``_priority_admit_from_inbox``'s own priority-aware selection within
        r.inbox, so deferring for that case would help nobody and would only
        cost r's own backlog a bounded delay for free.
        """
        return bool(self._cross_model_defer_hint - {r.model_tag})

    async def _defer_admission_window(self, r: "Resident") -> bool:
        """Bounded, self-terminating wait giving an external eviction/swap
        a real, checkable chance to claim r before it self-admits its own
        backlog -- closes the determinism gap a bare single yield would leave
        (whether the dispatcher's own hot loop wins that one tick is
        otherwise scheduler-order-dependent, not guaranteed). Never calls
        ``_priority_admit_from_inbox`` and never awaits ``queue._lock`` --
        the await-free constraint on that function is untouched; this is a
        different code path entirely, reached ONLY when
        ``_should_defer_admission`` already said it might be worth it.

        Checks ``r.state`` each interval, nothing else -- the only question
        this loop answers is "did someone else already win," never "who."
        Returns True the instant ``r.state`` flips to ``DEAD`` (claimed
        externally, same DEAD-check convention this driver already uses
        elsewhere); False once the bounded budget
        (``_DEFER_ADMISSION_RETRIES`` x ``_DEFER_ADMISSION_INTERVAL_S``) is
        exhausted with no claim -- at which point the caller falls back to
        normal self-admission, unconditionally.

        This budget is the anti-starvation guarantee for the INCUMBENT
        resident's own backlog -- it is NOT the separate guarantee (which gives a
        repeatedly-EVICTED waiter at least one turn; opposite direction,
        different victim) and does not replace the evicted-waiter guarantee,
        which the deferral depends on.
        """
        for _ in range(_DEFER_ADMISSION_RETRIES):
            await asyncio.sleep(_DEFER_ADMISSION_INTERVAL_S)
            if r.state is ResidentState.DEAD:
                return True
        return False

    async def _maybe_defer_admission(self, r: "Resident") -> bool:
        """The SINGLE decision point ``_drive_resident``'s retry loop calls
        into before self-admitting from ``r.inbox`` -- combines
        ``_should_defer_admission``'s cheap hint check with
        ``_defer_admission_window``'s bounded wait so the COMBINATION itself
        is directly testable, not just its two halves in isolation. A wiring
        bug (e.g. entering the wait unconditionally, ignoring the hint) would
        not be caught by testing the two halves separately -- this method is
        that seam.

        Returns True ONLY when r was genuinely claimed externally during an
        actually-opened wait -- the caller must stop, not self-admit. Returns
        False in every other case: inbox empty, hint says no cross-model
        claim is worth opening a window for, or the bounded budget was
        genuinely spent with nobody claiming it -- the caller proceeds to
        normal self-admission unconditionally in all of these, INCLUDING the
        budget-exhausted case, which is precisely the anti-starvation
        guarantee for the incumbent's own backlog (see
        ``_defer_admission_window``'s own docstring: it is NOT the evicted-waiter guarantee and does not
        replace it).
        """
        if r.inbox.empty():
            return False
        if not self._should_defer_admission(r):
            return False
        return await self._defer_admission_window(r)

    def _priority_admit_from_inbox(
        self, r: "Resident", *, already_drained: "tuple[Slot, ...]" = ()
    ) -> "Slot | None":
        """Shared await-free drain/select/admit/restore for r.inbox.
        Used at all three admit-grab sites -- fan-out top-up (_admit_from_inbox,
        below) and the driver's idle-wake/idle-timeout grabs (_drive_resident).

        Drains every slot currently queued, via the public get_nowait()/
        put_nowait() API only (never r.inbox._queue -- bypasses the queue's own
        _unfinished_tasks/_getters bookkeeping and can strand a parked getter).
        Fail-completes any evicted rider found in the drain instead of
        restoring it: under plain FIFO an evicted rider always eventually
        reaches the front and is discarded there; under priority-select a
        low-priority evicted rider would otherwise be drained, not selected,
        and restored every pass -- never collected under sustained
        higher-priority traffic (by design). Mirrors
        the pre-existing evicted-rider guard this replaces at the fan-out
        sites (previously duplicated in several places).

        Selects the single best-priority survivor by
        (key is None, key or (0, 0), created_at) where
        key = self.queue._fastlane_priority_key(slot) -- listed beats
        unlisted absolutely, listed-vs-listed by ascending (rule_index,
        rank), ties/unlisted by created_at ascending. Restores every other
        survivor to the inbox via put_nowait, in the SAME order they were
        drained -- never head-inserted or re-sorted, which would reintroduce
        the ordering inversion fixed separately.

        Returns the admitted slot, or None if nothing was admittable (inbox
        was empty, or every drained slot was evicted). The whole body is ONE
        synchronous block, no `await` anywhere -- an await wedged between the
        scan and the admit would let a concurrent put or fan-out
        re-entry interleave and double-admit.

        Parameter ``already_drained``: slots the caller has
        ALREADY taken out of r.inbox and wants ranked alongside whatever is
        still queued. They are PREPENDED to the drain list rather than
        ``put_nowait``-ed back.

        ⚠ TWO DISTINCT REASONS, kept apart because they are easy to
        conflate (a single sentence covering both gets it wrong about which
        half does the work, and a prepend->append change would then go
        unnoticed):

        (a) SELECTION is position-INDEPENDENT. ``_admit_key`` ends in
            ``created_at``, so a slot that arrived later loses on the KEY
            wherever it sits in the list -- list order does NOT decide the
            winner. The ONE exception is an exact ``created_at`` tie: ``min``
            is stable and returns the first minimum in list order, so
            prepending makes the woken slot win that tie, which is right
            because it was handed over first. No production producer can build
            that tie (every live slot goes through ``Slot.new()`` ->
            ``time.monotonic()``); only a test can.

        (b) RESTORE order IS position-DEPENDENT, and this is what the
            prepend actually protects. Non-winners go back in drain order, so
            appending would put the woken slot back BEHIND entries that
            arrived after it -- the ordering inversion the restore rule
            above exists to prevent.

        Sole caller: ``_rank_admit_woken``. Default ``()`` leaves all three
        pre-existing call sites byte-identical in behaviour.
        """
        drained: list[Slot] = list(already_drained)
        while True:
            try:
                drained.append(r.inbox.get_nowait())
            except asyncio.QueueEmpty:
                break
        live: list[Slot] = []
        for s in drained:
            # Same flag the queue's pop paths set: a parked request whose client
            # is gone is dropped here, with its claim, and never served.
            if s.disconnect_event is not None and s.disconnect_event.is_set():
                s.is_evicted = True
            if s.is_evicted:
                self._release_fastlane_claim_locked(s, "disconnected")
                self._fail_completion_future(
                    s, SlotEvictedError(f"slot {s.slot_id} evicted")
                )
            else:
                live.append(s)
        if not live:
            return None

        def _admit_key(s: "Slot") -> "tuple[bool, tuple[int, int], float]":
            key = self.queue._fastlane_priority_key(s)
            return (key is None, key or (0, 0), s.created_at)

        winner = min(live, key=_admit_key)
        for s in live:
            if s is not winner:
                r.inbox.put_nowait(s)
        return winner

    def _rank_admit_woken(self, r: "Resident", woken: "Slot") -> "Slot | None":
        """Rank the slot a PARKED ``r.inbox.get()`` just
        handed us against anything else already queued, instead of serving it
        purely because it happened to arrive first.

        ⛔ AWAIT-FREE BY DESIGN -- this is the load-bearing property, not an
        implementation convenience. An await between "which slot is best" and
        "admit it" lets a concurrent ``put_nowait`` interleave and DOUBLE-ADMIT;
        that is the race ``_priority_admit_from_inbox``'s synchrony exists to
        prevent. Saying merely "it must not block" invites a wrapper
        or a ``queue._lock`` held across this region, which would remove the
        symptom and REOPEN that race. The whole region is synchronous on
        purpose. The one legitimate suspension point -- the ``wait_for`` that
        produced ``woken`` -- happens at the CALL SITE, strictly before this
        helper is entered.

        Takes no lock and reads no queue state: the rank data lives ON THE SLOT,
        and ``queue._fastlane_priority_key`` is a three-line pure function that
        is merely namespaced on the queue as the single source of truth for the
        ORDERING. The two rank-aware siblings three lines from the call site
        already work this way.

        ⛔ ALWAYS RETURNS A SLOT, NEVER ``None`` -- and that is a CONTROL-FLOW
        requirement, not a stylistic one. The caller must always ``break`` to
        the OUTER loop. ``r.state = ResidentState.IDLE_EVICTABLE`` is assigned
        in exactly ONE place in this file, inside that outer loop; every
        producer flips ``IDLE_EVICTABLE -> ACTIVE`` under ``_registry_lock``
        BEFORE putting into the inbox. So any return that sent the caller back
        round the INNER loop instead would leave the resident wedged in ACTIVE
        with an empty inbox: never idle-unloading, never an LRU make-room
        victim, holding its registry and VRAM slot indefinitely. Returning None here
        would leave the resident ACTIVE with 0 idle-unloads instead of DEAD with 1.

        ⇒ Consequence, deliberate: an evicted rider handed to a parked driver is
        SERVED here -- this path does NOT reap it the
        way ``_priority_admit_from_inbox`` reaps riders it drains itself. Reaping
        it here would require a control-flow change to the four-part park
        cluster rather than a local fix, and risks the wedge described
        above. Pinned by
        ``test_evicted_woken_rider_is_still_served_this_path_does_not_reap``.
        """
        if woken.is_evicted:
            return woken
        if woken.disconnect_event is not None and woken.disconnect_event.is_set():
            # The client left while the slot was handed to this parked driver. Drop
            # it if anything else is admittable; if not, a slot must still be
            # returned (see above), so it is served as an evicted woken slot is.
            woken.is_evicted = True
            self._release_fastlane_claim_locked(woken, "disconnected")
            admitted = self._priority_admit_from_inbox(r)
            if admitted is None:
                return woken
            self._fail_completion_future(
                woken, SlotEvictedError(f"slot {woken.slot_id} evicted")
            )
            return admitted
        admitted = self._priority_admit_from_inbox(r, already_drained=(woken,))
        # Cannot fire: ``woken`` is live above, so it is always a candidate and
        # a winner always exists. Present so "never returns None" holds by
        # construction rather than by argument.
        return woken if admitted is None else admitted

    async def _save_holder_kv_at_swap(self, r: "Resident", handle, tip: Slot) -> None:
        """Same-resident swap: persist the KV of the holder's last turn (``tip``)
        before a higher-ranked request takes the engine, with the same
        unconditional slot save the unload path uses. Best-effort: a failure
        is logged loudly and the swap goes ahead."""
        if handle is None or not handle.is_alive() or not tip.thread_id:
            return
        try:
            saved = await self._save_slot_kv(
                handle.port, r.model_tag, None,
                thread_id_override=tip.thread_id,
                admission_ctx_len_override=tip.admission_ctx_len,
                client_meta_override=tip.client_meta,
            )
            log.info(
                "resident KV cache saved at same-resident swap: model_tag=%s "
                "thread_id=%s confirmed=%s",
                r.model_tag, tip.thread_id[:8], bool(saved),
            )
        except Exception:
            log.warning(
                "resident KV cache save failed at same-resident swap "
                "(best-effort): model_tag=%r thread_id=%s",
                r.model_tag, tip.thread_id[:8], exc_info=True,
            )

    async def _drive_resident(self, r: "Resident") -> None:
        """Long-lived per-resident driver (cap>=2). Spawns r's sidecar once, then
        serves slots from r.inbox through ACTIVE->GRACE, parking in IDLE_EVICTABLE
        between requests until idle expiry / eviction / death. SOLE writer of r.*
        lock-free in ACTIVE; takes _registry_lock only for the idle<->active<->dead
        transitions the dispatcher also touches."""
        handle = None
        slot = None  # bound before the first await so the finally can fail it
        # The last slot whose turn this driver began (it became active_slot),
        # and whether the engine is up. Together they tell the finally which
        # slot, if any, was taken out of the inbox but never started.
        began_slot = None
        engine_up = False
        try:
            slot = await r.inbox.get()  # the reservation's first slot
            handle = await self._spawn_for_resident(r, slot)
            if handle is None:
                return
            engine_up = True
            # Per-model idle timeout: read from the manifest's sleep_idle_seconds
            # (threaded through Resident.sleep_idle_seconds). -1 = pin/keep-warm
            # (never idle-unload), 0 = fall back to global default, N>0 = that
            # model's idle timeout in seconds. This is what evicts the 35b sub-agent
            # model too early (Bug C: global 120s was used for everything).
            if r.sleep_idle_seconds == -1:
                per_model_idle = KEEP_ALIVE_MAX_S  # pin-warm, never idle-unload
            elif r.sleep_idle_seconds > 0:
                per_model_idle = r.sleep_idle_seconds
            else:
                per_model_idle = self.runtime.queue.idle_hot_load_seconds
            while not self._stop_event.is_set():
                # A parked, higher-ranked request is about to take this engine from
                # the holder of the last turn: save the holder's KV first. Decided
                # here, with no await before the decision; the claim is released
                # below, once the turn starts.
                swap_tip = (
                    r.grace_tip
                    if r.grace_tip is not None and r.grace_tip is not slot
                    and self._parked_claim_outranks_holder_locked(r, only_slot=slot)
                    else None
                )
                if swap_tip is not None:
                    # The save can take a long time and the request is already out
                    # of the inbox, so nothing else would show the resident as
                    # busy: mark it taken by this request now, under the lock
                    # (state, active request and the rank stamp, as the turn-start
                    # block below does), or a make-room pass could pick it as the
                    # victim and the request would be lost. The claim stays
                    # registered until the turn really starts.
                    async with self._registry_lock:
                        if r.state is ResidentState.DEAD:
                            break
                        _transition_resident_state(r.state, ResidentState.ACTIVE)
                        r.state = ResidentState.ACTIVE
                        r.active_slot = slot
                        began_slot = slot  # its turn has begun
                        r.rank_client_meta = slot.client_meta
                    try:
                        await self._save_holder_kv_at_swap(r, handle, swap_tip)
                    except BaseException:
                        # Cancelled (or failed) before the turn started: the slot
                        # now counts as started, so the exit path will not hand it
                        # back and nothing else would release its claim.
                        async with self._registry_lock:
                            self._release_fastlane_claim_locked(slot, "swap_aborted")
                        raise
                async with self._registry_lock:
                    if r.state is ResidentState.DEAD:
                        if swap_tip is not None:
                            # Died during the save: same reason, same release.
                            self._release_fastlane_claim_locked(slot, "swap_aborted")
                        break
                    _transition_resident_state(r.state, ResidentState.ACTIVE)
                    r.state = ResidentState.ACTIVE
                    r.active_slot = slot
                    began_slot = slot  # its turn has begun
                    # The slot's own turn starts now: its claim (if it waited in
                    # the inbox) is released here.
                    self._release_fastlane_claim_locked(slot, "admitted")
                    # Reset the KV-identity tip to the new anchor at
                    # the top of every turn -- same site/reasoning as
                    # rank_client_meta just below (r is reused across many
                    # turns; a stale tip from an earlier turn must never
                    # survive into this one).
                    r.grace_tip = slot
                    r.last_active_monotonic = time.monotonic()
                    # This turn's client -- the driver reuses r
                    # across many slots over its lifetime, so this is the
                    # site that must catch a DIFFERENT client on a later turn.
                    r.rank_client_meta = slot.client_meta
                    # A config change should take effect at
                    # the next turn of the model: PUT /api/config only ever
                    # refreshed self.grace/self.idle (the manager-level
                    # timers _process_slot reads) — never a per-Resident
                    # r.grace/r.idle, snapshotted once at Resident
                    # construction and otherwise never touched. Refresh the
                    # CONFIG values only (grace_seconds/max_extensions/
                    # idle_seconds) here, every turn — never touches
                    # _started_at/extension_count/thread_id/model_tag, so a
                    # timer already mid-window is unaffected until its next
                    # start()/restart_for_followup().
                    if r.grace is not None:
                        r.grace.grace_seconds = self.runtime.queue.grace_seconds
                        r.grace.max_extensions = self.runtime.queue.max_grace_extensions
                    if r.idle is not None:
                        r.idle.idle_seconds = self.runtime.queue.idle_hot_load_seconds
                await self._serve_on_resident(r, slot, handle)
                # The anchor slot's turn is now KNOWN complete (the await
                # above cannot have returned otherwise) -- spend any staleness
                # grant held by this slot's client now, never earlier.
                self._spend_staleness_grant_if_completed(slot)
                idle_window = self._idle_window_seconds(
                    r.latest_keep_alive_s, per_model_idle
                )
                # The same-model residency floor, ported onto
                # this live path. Guarded to the keep_alive=0 / immediate-
                # teardown edge (the only case the floor ever covered) and
                # called HERE, before the `_registry_lock` block below, because
                # the helper takes `queue._lock` and the established order is
                # `queue._lock -> _registry_lock`, never reversed.
                if idle_window <= 0:
                    idle_window = await self._same_model_residency_floor(
                        r, idle_window,
                    )
                async with self._registry_lock:
                    if r.state is ResidentState.DEAD:
                        break
                    r.active_slot = None
                    r.last_active_monotonic = time.monotonic()
                    # Idle-unload half: `idle_window`
                    # (`_idle_window_seconds`, above) is computed purely from
                    # `r.latest_keep_alive_s` / per-model config -- zero Fast
                    # Lane awareness -- so a designated victim only reached
                    # this immediate-evict branch by coincidence (an explicit
                    # keep_alive=0). `_is_designated_unload_target_locked(r)` is the
                    # SAME predicate the grace-strip gate above
                    # already trusts -- reused
                    # here, not re-implemented, exactly the "already
                    # victim-aware" branch this file's own
                    # comment describes a few lines down (the inbox-drain-to-
                    # tail special case). No `queue._staging` check added on
                    # top of it: a live
                    # outranking claim is the correct "waiting" signal here,
                    # not literal staging residency -- `_defer_unroutable`
                    # registers a claim and re-queues the slot on a
                    # BACKGROUND TASK after a real backoff, so a genuinely
                    # outranking claimant is routinely live-but-unstaged for
                    # whole seconds at a time; existing
                    # tests construct their victim scenario
                    # the same way
                    # and would fail under a staging-based check.
                    if (
                        idle_window <= 0 and not self._parked_claim_outranks_holder_locked(r)
                    ) or self._is_designated_unload_target_locked(r):
                        # Capture thread_id for KV save on immediate eviction
                        # Source from grace_tip, NOT the raw anchor `slot` --
                        # a grace-window ACTIVE_MATCH follow-up may have landed newer
                        # content in the engine's KV since `slot` was admitted; see the
                        # grace_tip field comment on Resident for the full contract.
                        r.idle_thread_id = r.grace_tip.thread_id if r.grace_tip else None
                        # Stash idle client_meta + admission ctx-len for a
                        # restorable teardown bin. The parallel==1 gate was REMOVED
                        # here: _save_slot_kv_inner now keys each engine slot on
                        # its OWN thread_id when >1 slot is populated, so the
                        # override is safe to stash unconditionally. Do NOT re-add the
                        # parallel==1 gate — it would silently skip the stash for
                        # parallel>=2 residents and reintroduce the no-save-on-idle bug.
                        r.idle_client_meta = r.grace_tip.client_meta if r.grace_tip else None
                        r.idle_admission_ctx_len = r.grace_tip.admission_ctx_len if r.grace_tip else 0
                        # A DESIGNATED VICTIM's
                        # own inbox backlog must not cut back to the front of the line
                        # it was, by definition, the worst-priority client for --
                        # the head path stays for non-victim evictions
                        # (non-victims keep the old behaviour). Re-checks
                        # `_is_designated_unload_target_locked(r)` FRESH here, right at
                        # teardown (already under `_registry_lock`) rather than
                        # carrying forward whatever `_serve_on_resident`'s own
                        # check decided moments earlier -- matches the Fast Lane rule (a victim chosen
                        # fresh at each lifecycle transition, never a carried-forward
                        # name). Pre-drains the inbox into `_requeue_slots_tail_or_
                        # fail` ONLY for a victim, in the SAME order/one-bg-task shape
                        # `_begin_unload_locked` itself already uses for the non-victim
                        # case below it -- `_begin_unload_locked`
                        # is UNCHANGED, still the sole eviction entry point for every
                        # OTHER call site (VRAM credit, DEAD deregister,
                        # `_unload_teardown` spawn), and its own inbox drain becomes a
                        # harmless no-op here since the inbox is already empty by the
                        # time it runs (its own docstring: "re-draining an already-
                        # empty inbox is a harmless no-op").
                        if self._is_designated_unload_target_locked(r) and r.inbox is not None and not r.inbox.empty():
                            drained: list[Slot] = []
                            while not r.inbox.empty():
                                try:
                                    drained.append(r.inbox.get_nowait())
                                except asyncio.QueueEmpty:
                                    break
                            if drained:
                                self._spawn_bg(self._requeue_slots_tail_or_fail(drained))
                        self._begin_unload_locked(r)
                        # The designated victim's own
                        # turn just released capacity with no immediate
                        # claimant (unlike _route_or_reserve's make-room
                        # evictions, which the SAME call immediately
                        # re-occupies for the request that triggered them) --
                        # this is the third decision moment. Wake any
                        # coroutine parked in `_wait_for_park_or_timeout`,
                        # still under this SAME `_registry_lock` this block
                        # already holds -- same idiom as the park notify a
                        # few lines below and the grace-lapse notify in
                        # `_serve_on_resident`. `_begin_unload_locked` itself
                        # stays untouched (no notify is added inside it:
                        # that logic is settled); every wake site is
                        # named in TestNotifyCallSitesAreTheNamedSet.
                        # Wake the dispatch loop alongside the make-room signal
                        self._dispatch_wake.set()
                        self._make_room_signal.notify_all()
                        break
                    _transition_resident_state(r.state, ResidentState.IDLE_EVICTABLE)
                    r.state = ResidentState.IDLE_EVICTABLE
                    # r just became a make-room candidate --
                    # the ONLY site in the file where that happens. Wake any
                    # coroutine currently parked in a make-room retry's
                    # `_wait_for_park_or_timeout`, still under the SAME
                    # `_registry_lock` this block already holds -- no new await,
                    # no new suspension point. This never hands r to a specific
                    # waiter: every wake just re-triggers the existing, unmodified
                    # `_route_or_reserve` -> `_lru_idle_unloadable` decision, fresh,
                    # under lock -- so the staleness exclusion and the priority
                    # ordering in `_resident_unload_priority_key` are always
                    # re-checked, never bypassed.
                    # Wake the dispatch loop alongside the make-room signal
                    self._dispatch_wake.set()
                    self._make_room_signal.notify_all()
                    r.idle_expires_at = time.monotonic() + idle_window
                    # Capture thread_id for KV cache save on idle teardown
                    # Source from grace_tip, NOT the raw anchor `slot` --
                    # see the immediate-evict site above / the grace_tip field
                    # comment on Resident for the full contract.
                    r.idle_thread_id = r.grace_tip.thread_id if r.grace_tip else None
                    # Stash idle client_meta + admission ctx-len for a
                    # restorable teardown bin. The parallel==1 gate was REMOVED
                    # here: _save_slot_kv_inner now keys each engine slot on
                    # its OWN thread_id when >1 slot is populated, so the
                    # override is safe to stash unconditionally. Do NOT re-add the
                    # parallel==1 gate — it would silently skip the stash for
                    # parallel>=2 residents and reintroduce the no-save-on-idle bug.
                    r.idle_client_meta = r.grace_tip.client_meta if r.grace_tip else None
                    r.idle_admission_ctx_len = r.grace_tip.admission_ctx_len if r.grace_tip else 0
                # A synchronous priority-select
                # attempt first -- if the inbox already has something at
                # wake, admit the best-priority rider instead of the oldest.
                # This is the original empty()-then-branch shape, fused
                # into one call: _priority_admit_from_inbox does its own
                # drain (which IS the emptiness check) with no await
                # anywhere in it, so there is no window between "checked
                # empty" and "acted" for anything to land in -- asyncio only
                # yields at an await that actually suspends, and there isn't
                # one between this call and the branch below. When it
                # returns None (inbox was empty, or every drained slot was
                # evicted) the existing blocking wait is unchanged,
                # byte-for-byte. Calling the helper first, rather than
                # gating on r.inbox.empty() first (the literal form),
                # is necessary rather than cosmetic: once evicted riders are
                # discarded instead of restored, "non-empty" no longer
                # implies "will yield an admittable slot" -- an inbox
                # holding ONLY an evicted rider is non-empty by .empty() but
                # the helper correctly drains it to nothing.
                #
                # Wrapped in a retry loop for one narrow case:
                # the locked re-check can find NOTHING admittable
                # (drained-and-discarded an evicted rider) while r.state has
                # ALREADY flipped away from IDLE_EVICTABLE -- e.g. a
                # concurrent HIT-route put lands in the
                # race window between this coroutine's TimeoutError and it
                # acquiring _registry_lock, atomically flipping state to
                # ACTIVE and putting a slot that turns out to be evicted.
                # That state change is real (a HIT-route DID target this
                # resident) but nothing is left to serve from it --
                # falling through with the OLD `slot` still bound would
                # re-serve an already-completed slot at the top of the
                # outer loop (an invalid FSM transition at best). Retrying
                # re-enters the wait/admit cycle cleanly instead.
                # Give a cross-model priority claim a real, bounded chance to
                # land BEFORE this resident self-admits its own backlog. See
                # _maybe_defer_admission for the full contract (never needs to be
                # right about WHO is waiting, bounded so the incumbent's own
                # backlog can never starve) -- ONE call, not the two pieces
                # inlined here, so the combination itself stays directly
                # testable rather than only its halves.
                if await self._maybe_defer_admission(r):
                    break  # claimed while deferring -- the outer loop's own
                           # DEAD check (top of this while) terminates cleanly.
                while True:
                    admitted = self._priority_admit_from_inbox(r)
                    if admitted is not None:
                        slot = admitted
                        break
                    try:
                        woken = await asyncio.wait_for(
                            r.inbox.get(), timeout=idle_window
                        )
                        # A parked getter is handed whatever
                        # was put FIRST, so serving it directly admitted on
                        # ARRIVAL order -- the failure being avoided. Rank it against
                        # anything else already queued. Sync, no lock, no queue
                        # scan: the await above is the only suspension point.
                        # ALWAYS returns a slot, so this arm still always breaks
                        # to the outer loop -- see the helper on why returning
                        # None here would wedge the resident.
                        slot = self._rank_admit_woken(r, woken)
                        break
                    except TimeoutError:
                        async with self._registry_lock:
                            admitted = self._priority_admit_from_inbox(r)
                            if admitted is not None:
                                slot = admitted
                                break
                            if r.state is ResidentState.IDLE_EVICTABLE:
                                self._begin_unload_locked(r)
                                # Self-idle-unload
                                # eviction also releases capacity with no
                                # immediate claimant -- same third moment,
                                # same notify, same lock already held here.
                                # Wake the dispatch loop alongside the make-room signal
                                self._dispatch_wake.set()
                                self._make_room_signal.notify_all()
                                break
                            if r.state is ResidentState.DEAD:
                                # falls through safely: the outer loop's own
                                # DEAD check (before slot is ever touched)
                                # handles it -- nothing to do here.
                                break
                            if self._stop_event.is_set():
                                # let the outer while's own condition catch
                                # the stop on the next iteration.
                                break
                            # state changed to something else under us (see
                            # the paragraph above):
                            # the only state still reachable here is ACTIVE
                            # (the branches above took IDLE_EVICTABLE and
                            # DEAD, stop_event broke out; GRACE has zero
                            # assignment sites in this file).
                            # ACTIVE in THIS handler with no admit means a
                            # producer flipped IDLE_EVICTABLE -> ACTIVE
                            # under the lock (the producer path)
                            # and its put drained as an
                            # evicted rider. Without this flip the branch just
                            # re-parks and spins: the resident never
                            # re-reaches the idle flip (outer loop
                            # only), so it wedges ACTIVE with an empty
                            # inbox -- invisible to _lru_idle_unloadable
                            # and make-room (the
                            # MAKE_ROOM_STARVED storm). The flip mirrors
                            # the outer-loop flip under this SAME lock; the guard
                            # call is the state machine's own invariant
                            # check (never raises), exactly as at the outer flip.
                            # Then `continue` -- NOT `break`: a
                            # break
                            # would land the outer top holding this turn's
                            # STALE slot, and the real _serve_on_resident
                            # ends with transition(slot, POPPED) -- so its
                            # first transition(slot, ACTIVE) on the re-serve
                            # raises InvalidTransition (fsm.py), uncaught
                            # here (only CancelledError is caught) and
                            # kills the driver task. `continue` re-enters
                            # the inner loop (no _maybe_defer_
                            # admission re-run -- that sits before it),
                            # re-parks in get(); on the next idle-window
                            # timeout the IDLE_EVICTABLE branch above
                            # unloads -> DEAD -> the outer loop's
                            # own DEAD check exits before any
                            # re-serve. In the meantime the resident is a
                            # make-room candidate -- the wedge is broken.
                            # The stale-slot re-serve hazard is documented
                            # above (why this branch is safe
                            # as written, and why it stays `continue`-shaped).
                            _transition_resident_state(r.state, ResidentState.IDLE_EVICTABLE)
                            r.state = ResidentState.IDLE_EVICTABLE
                            continue
        except asyncio.CancelledError:
            raise
        finally:
            # EXACTLY-ONCE teardown claim (vs _unload_teardown). Whoever claims
            # torn_down owns the FULL cleanup: reap the live process (handle OR the
            # still-booting pid — B2), drain unstarted inbox riders back to the queue
            # (B3), and fail the anchor slot if it died before the serve loop owned it.
            booting_pid = None
            pending_slots: list[Slot] = []
            async with self._registry_lock:
                claim = not r.torn_down
                if (
                    engine_up
                    and slot is not None
                    and slot is not began_slot
                    and slot is not r.active_slot
                ):
                    # The driver took this slot out of the inbox but its turn
                    # never began, so nothing else owns it: hand it back to the
                    # queue so it is served later like any other drained
                    # follow-up (it is failed only if the queue is closing or
                    # the hand-back is cancelled). Exactly one path hands it
                    # back: when this exit owns the teardown it is re-queued
                    # ahead of the inbox riders below; when the detached
                    # teardown owns it, as a detached task.
                    if claim:
                        pending_slots.append(slot)
                    else:
                        self._spawn_bg(self._requeue_slots_or_fail([slot]))
                    slot = None  # handed back: the orphan check below must not fail it too
                if claim:
                    r.torn_down = True
                    handle = r.handle
                    r.handle = None
                    booting_pid = r.booting_pid
                    r.booting_pid = None
                    if r.inbox is not None:
                        while not r.inbox.empty():
                            try:
                                pending_slots.append(r.inbox.get_nowait())
                            except asyncio.QueueEmpty:
                                break
                    if self._residents.get(r.resident_key) is r:  # re-key
                        _transition_resident_state(r.state, ResidentState.DEAD)
                        r.state = ResidentState.DEAD
                        # Remember WHICH model was on the card, immediately before the
                        # registry entry is destroyed, so a status view can still name it
                        # until the VRAM drops. After this `del` the tag is UNRECOVERABLE -- captured
                        # here or not at all.
                        # DELIBERATELY NOT a field on __init__: tests that build the manager with __new__
                        # (to dodge the sqlite boot DB) break whenever __init__ grows -- the documented
                        # _handed_off_prune_at fixture rot. getattr with a default cannot rot them.
                        self._last_unloaded = {
                            "model_tag": getattr(r, "model_tag", None),
                            "main_gpu": getattr(r, "main_gpu", None),
                        }
                        del self._residents[r.resident_key]
                        # Ported to the resident_key re-keying: see the
                        # identical guard in the reap path above — prune the per-model
                        # identity only when NO other live resident holds this tag, so
                        # a multi-instance sibling's identity survives this instance's
                        # death (the `is r` guard above protects the registry slot only).
                        if not any(
                            x.model_tag == r.model_tag
                            for x in self._model_residents()
                        ):
                            self._last_request_identity_by_model.pop(r.model_tag, None)
                        # Purge this instance's session
                        # affinity on the driver-finally deregister too (mirrors
                        # _begin_unload_locked; under _registry_lock here) so a stale entry
                        # can't mis-route a session to a later-reused idx. Self-heals via
                        # the sticky DEAD re-check + LRU otherwise, but purge is correct.
                        self._purge_affinity_for(r)
                    # A driver that exits (engine death, cancel or normal end)
                    # has just released its capacity: wake any claimant parked
                    # on the make-room signal so it re-evaluates fresh now
                    # instead of waiting for its retry timer.
                    self._dispatch_wake.set()
                    self._make_room_signal.notify_all()
            if claim:
                # Capture thread_id for KV save before teardown
                idle_thread_id = r.idle_thread_id
                model_tag = r.model_tag
                if handle is not None and handle.is_alive() and idle_thread_id:
                    try:
                        # Single-stream resident -> clean flush first
                        # (mirrors the cap<=1 path); the plain save below no-ops on the
                        # clean-present guard. Requires the idle-meta stash; self-guards + best-effort.
                        if int(getattr(handle, "parallel", 1) or 1) == 1:
                            await self._flush_clean_kv_at_unload(
                                handle, model_tag, idle_thread_id,
                                r.idle_admission_ctx_len, r.idle_client_meta,
                            )
                        # Use _save_slot_kv instead of a bolt-on POST.
                        # The idle holder teardown already saved KV, but this is a
                        # separate path (resident teardown) so we also save.
                        saved = await self._save_slot_kv(
                            handle.port,
                            model_tag,
                            r.active_slot,
                            thread_id_override=idle_thread_id,
                            admission_ctx_len_override=r.idle_admission_ctx_len,
                            # See the evict_teardown site — explicit
                            # meta keeps the identity keying + arms T-GUARD here.
                            client_meta_override=r.idle_client_meta,
                        )
                        # Twin of the
                        # _unload_teardown fix: claim
                        # "saved" only on the SPEC-V2 confirmed-save True;
                        # False/None are non-raising refusals already logged
                        # at their own source.
                        if saved:
                            log.info(
                                "resident KV cache saved before teardown "
                                "(thread_id=%s, model_tag=%s)",
                                idle_thread_id[:8] if idle_thread_id else "none",
                                model_tag,
                            )
                        else:
                            log.debug(
                                "resident KV cache save not confirmed before "
                                "teardown (result=%r; refusal reason, if any, "
                                "logged at source) model_tag=%s",
                                saved, model_tag,
                            )
                    except Exception:
                        log.warning(
                            "resident KV cache save failed (best-effort): model_tag=%r",
                            model_tag,
                            exc_info=True,
                        )
                if handle is not None and handle.is_alive():
                    await self._reap_resident_handle(handle)
                elif handle is not None:
                    # Handle exists but is already dead — nothing
                    # to reap, but attribute it before falling through
                    # (previously silent). cap>=2 twin of the cap<=1
                    # worker_loop sweep; same shared helper as _unload_teardown
                    # so the two capture-sites cannot drift apart.
                    self._log_multi_engine_idle_dead_classification(handle, model_tag)
                elif booting_pid is not None:
                    await self._reap_booting_pid(booting_pid)  # B2: handle never set
                # This is the cap>=2 twin of the cap<=1 post-teardown
                # orphan reap (_teardown). Every stage inside is
                # individually try/except-guarded — this never raises out of
                # this finally (an exception here would mask the in-flight
                # one). See _reap_multi_engine_orphans.
                await self._reap_multi_engine_orphans("driver_finally")
                # Re-queue inbox riders that never started — another resident serves
                # (or fail their future if the queue is closing at shutdown). Async
                # context here (lock released), so await the ordered batch directly
                # to preserve FIFO among the riders.
                await self._requeue_slots_or_fail(pending_slots)
                # Fail the anchor slot if it died before the serve loop took
                # ownership (cancel/spawn-fail during RESERVED_LOADING) — the
                # supervisor's active_slot/inflight sweep can't see it then.
                # _spawn_for_resident already fails it on the health-timeout path,
                # so the done() guard in _fail_completion_future keeps this idempotent.
                if (
                    slot is not None
                    and slot is not r.active_slot
                    and slot is not r.rerouted_slot
                    and slot not in r.inflight
                ):
                    # A served slot clears active_slot on completion and leaves
                    # inflight, so those two checks alone are not enough to tell
                    # "never served" from "already served" - failing the latter
                    # raced the serve path and handed the caller a spurious
                    # error. Ask the state, and fail anything the serve path does
                    # not own, so an unrecognised state produces a visible error
                    # rather than a future nobody resolves.
                    should_fail, unexpected = _orphan_slot_disposition(slot.state)
                    if unexpected:
                        log.warning(
                            "orphaned slot in unrecognised state at driver "
                            "teardown: model_tag=%r slot_state=%s - failing it so "
                            "the caller is not left waiting; the slot-state table "
                            "in _orphan_slot_disposition needs updating",
                            r.model_tag, slot.state.value,
                        )
                    # An OOM-requeued slot is legitimately still
                    # unserved when its driver task exits -- its future is
                    # owned by the detached retry-wait companion
                    # (_oom_requeue_wait_then_readmit), not orphaned. Without
                    # this check, this safety net races that companion: the
                    # slot may transiently be observed in STAGED (already
                    # re-enqueued) or its old POPPED/LOADING_FAIL state
                    # before the requeue completes, and this net would fail a
                    # request the whole point of the OOM requeue is to keep alive.
                    # Once re-admitted (the flag is cleared there), THIS
                    # check no longer applies and a genuinely-orphaned
                    # re-attempt fails exactly as before.
                    if should_fail and getattr(slot, "oom_requeue_pending", False):
                        should_fail = False
                    if should_fail:
                        self._fail_completion_future(
                            slot,
                            RuntimeError(
                                f"resident {r.model_tag!r} driver exited before serve"
                            ),
                        )

    async def _starvation_breakout_candidate(self, slot: Slot) -> "Slot | None":
        """``queue.starved_other_model()`` gated so a
        Fast Lane CLAIM can never use the ordinary starvation breakout to
        shorten a NON-VICTIM's grace -- only an ordinary
        (non-listed) FIFO waiter still breaks grace via this path (the
        fairness floor, deliberately unchanged).

        Single source of truth for BOTH grace loops (``_serve_on_resident``
        "Loop A" and ``_process_slot`` "Loop B") -- two separate entrances
        to one decision can drift apart, so
        routing both call sites through one function means
        there is only one entrance to get right, not two to keep in sync.

        DELIBERATELY DOES NOT CHECK ``_is_designated_unload_target_locked`` -- the
        victim clause of the Fast Lane rule (for a resident that is NOT the
        designated victim) is absent here by REASONING, not by omission:
        at Loop A, this candidate is only ever consulted inside the
        ``skip_grace`` ``else`` branch, so the caller already knows
        ``r`` is not the victim on every iteration that reaches here -- a
        second ``_is_designated_unload_target_locked`` call would be a redundant
        ``_registry_lock`` acquisition proving nothing new. At Loop B
        (``_process_slot``, the single-sidecar/legacy ``worker_loop``
        path), ``_is_designated_unload_target_locked`` is structurally incapable
        of returning True for it at all: that predicate's selection step
        (``_is_worst_ranked_loaded_locked``) iterates
        ``self._model_residents()``, which explicitly EXCLUDES the legacy
        singleton (``_SINGLETON_RESIDENT_KEY``) that Loop B operates under
        -- calling it here would be a vacuous gate (always False, always
        "not victim") dressed up as real victim-selection machinery. So in BOTH loops a
        victim can never reach this function in the first place, and
        gating unconditionally on "is the candidate itself a claim" is
        exactly equivalent to gating on "is the candidate a claim AND this
        resident is not the victim" -- there is no case where the omitted
        clause would have changed the answer.
        """
        starved = await self.queue.starved_other_model(slot.model_tag)
        return self._starvation_breakout_gate(starved)

    def _starvation_breakout_gate(self, starved: "Slot | None") -> "Slot | None":
        """The pure (no-await) half of ``_starvation_breakout_candidate``'s
        Fast Lane gate, split out so a caller that already has a
        candidate in hand -- either the buffer-scan result above, or
        ``Resident.starvation_breakout_candidate`` (notified synchronously
        by ``_defer_unroutable``, see that field's own docstring) -- can
        apply the identical Fast Lane exclusion without re-querying the
        queue."""
        if starved is None or starved.fastlane is not None:
            return None
        return starved

    async def _legacy_ip_grace_match(self, slot: Slot, r: "Resident", _shared) -> Slot | None:
        """UNCALLED as of v0.8.0: no live call site remains.
        RETAINED,
        NOT DELETED, per this codebase's convention for retained dead code:
        dead code is marked in the comments as dead code but
        is kept in place rather than deleted, because it is the
        legacy path and may be useful again in the future; it is
        never to be removed.
        (see `_legacy_defer_exhaustion_refusal` for the same
        convention.)

        WHY unreachable: this was the client-ADDRESS grace-window fallback
        (a stable-identity fix, ported onto the atomic chokepoint by a
        later change) -- the two-gate sequence (`grace_ip_match_eligible` then
        `queue.drain_inbox_and_staging_match_ip`) that ran in
        `_serve_on_resident`'s grace loop whenever `pop_matched_thread`
        missed. It is FAIL-OPEN BY CONSTRUCTION
        (`grace_ip_match_eligible`'s own docstring: "a DENYLIST... an address
        that is shared but unlisted is matched, silently, with no error and
        no log" -- "a wrong match corrupts a live conversation's KV cache").
        It was retired in favour of a FAIL-SAFE content-derived match
        on `admission_hash_chain` (see the live call site, just above this
        method's sibling `_legacy_fastlane_grace_breakout`, for the
        replacement) precisely because the two paths have opposite failure
        directions and a two-step migration would leave a window where the
        fail-open one is still the last word whenever it fires.
        The swap is therefore made atomically.

        ⚠ WHY THE IP PATH IS KEPT: it is the address-based match, with its
        `via=pop_matched_ip` + `via=pop_matched_ip_inbox` telemetry labels
        for the two admission paths it used. It stays in place as the legacy
        path under the retained-dead-code convention above, so it can be
        reattached if ever needed, even though it has no call site now.
        Retirement is not "this branch never ran"; it is "this branch
        should not be the one running here even when it works" -- the
        content-derived replacement covers that same population (see
        the content-derived-match tests for the driven-traffic proof it does).

        NOT MAINTAINED. Nothing exercises this any more; verify it before
        reattaching a caller -- `grace_ip_match_eligible` and
        `parse_shared_addresses` (both in slot.py) are themselves untouched
        and still importable, only this orchestration lost its call site.

        WHAT REPLACED IT: `queue.drain_inbox_and_staging_match_hash_chain`,
        called from `_serve_on_resident`'s grace loop immediately above where
        this method's old call site used to sit (manager.py, same function).
        The `QUEUE_ADMITTED_NO_PICK` telemetry `via=` labels this produced
        (`pop_matched_ip`, `pop_matched_ip_inbox`) are replaced there by
        `pop_matched_hash_chain` / `pop_matched_hash_chain_inbox`.

        `pop_matched_ip` (queue.py) is a SEPARATE, older, already-dead artifact of
        the same IP mechanism, superseded independently of this retirement
        and long before it. Out of scope here:
        not marked and not touched.
        """
        _ip = (slot.client_meta or {}).get("ip")
        from turbohaul.slot import grace_ip_match_eligible

        matched = None
        _ip_grace_eligible = grace_ip_match_eligible(_ip, _shared)
        if _ip_grace_eligible:
            _sink = {}
            matched = await self.queue.drain_inbox_and_staging_match_ip(
                _ip, slot.model_tag, slot.grace_started_at,
                inbox=r.inbox,
                decline_sink=_sink,
            )
        return matched

    async def _legacy_fastlane_grace_breakout(self, slot: Slot) -> bool:
        """UNCALLED as of v0.8.0 (legacy path, retained for reference).
        RETAINED, NOT DELETED, per this codebase's convention for retained dead code
        (see `_legacy_defer_exhaustion_refusal`'s docstring for the rationale
        behind that convention).

        WHY unreachable: this was the in-loop Fast Lane breakout, at
        the TOP of `_serve_on_resident`'s grace wait ("Loop A"). It ended a
        client's grace early whenever a strictly higher-priority Fast Lane
        request was waiting. That loop is entered ONLY in the `else` of
        `skip_grace = self._is_designated_unload_target_locked(r)`, so every client
        it could ever fire for was, by definition, NOT the designated victim
        -- and a non-victim must not be evicted for the waiting
        request: its grace counts down fully. Only the designated victim
        is affected: that earlier breakout is scoped to the victim, not
        deleted. The victim case is still handled via `skip_grace`,
        which is untouched.

        There is no surviving caller and there cannot be one in this loop: a
        victim never reaches this branch, so any re-added call site here
        would fire only for non-victims -- the exact defect again.

        NOT MAINTAINED. Nothing exercises this any more; verify it before
        reattaching a caller. NOTE FOR A REATTACHER: the `break` was the
        CALLER's, not this method's -- the original site read
        `if <this predicate>: <audit+log>; break`, so restoring the audit
        line alone would not restore the behaviour.

        WHAT REPLACED IT: NOTHING -- and that is deliberate, not an omission.
        The admission this used to force early now happens through the natural
        lapse: the grace window simply counts down and the loop's
        existing `while time.monotonic() < deadline` expires, at which point
        the non-victim becomes the eviction target and the waiting claim is
        admitted. No replacement mechanism was added anywhere, because the
        natural lapse already was the mechanism.

        Loop B (`_process_slot`) still has its own copy of this check and
        KEEPS it -- deprecated cap<=1 path, out of scope
        here. The two grace loops diverge at this point on purpose.
        """
        if (
            self._fastlane_pop_kwarg() is not None
            and await self.queue.has_strictly_higher_priority_waiting(slot)
        ):
            await self._audit_async(slot, "grace_fastlane_breakout")
            log.info(
                "grace_fastlane_breakout slot=%s model=%s",
                slot.slot_id,
                slot.model_tag,
            )
            return True
        return False

    async def _serve_on_resident(
        self, r: "Resident", slot: Slot, handle
    ) -> None:
        """Serve one anchor slot on r's warm handle: ACTIVE (parallel fan-out /
        streaming / non-streaming complete) -> drain -> GRACE (ACTIVE_MATCH warm
        reuse within the grace window). Writes r.* directly (sole-writer). Does NOT
        handle idle handoff (the driver loop owns IDLE_EVICTABLE)."""
        n_parallel = max(1, getattr(handle, "parallel", 1))
        if slot.state is SlotState.STAGED:
            transition(slot, SlotState.LOADING)
        transition(slot, SlotState.ACTIVE)
        self._mark_slot_active(slot)
        await self._audit_async(slot, "active")

        # Telemetry (parity with the single-slot path): slot assign +
        # prefill start. Same relative placement as _process_slot's own
        # slot-assign block (after the ACTIVE transition + _mark_slot_active, before
        # the fan-out/stream/non-stream branch) and the SAME single shared
        # try/except -- not two separate guards -- so a failing on_slot_assign
        # still suppresses on_prefill_start exactly as it does on the cap<=1
        # path today (byte-for-byte guard shape, not just "some guard").
        try:
            self._telemetry.on_slot_assign(slot)
            self._telemetry.on_prefill_start(slot)
        except Exception:
            pass

        r.latest_keep_alive_s = (slot.client_meta or {}).get("keep_alive_s")
        is_streaming = (
            isinstance(slot.client_meta, dict)
            and bool(slot.client_meta.get("stream", False))
            and slot.stream_ready_event is not None
            and slot.stream_done_event is not None
        )
        if n_parallel > 1:
            slot.engine_op = "prefill"
            await self._fan_out_on_resident(r, slot, handle, n_parallel)
        elif is_streaming:
            slot.engine_op = "stream"
            slot.stream_handle = handle
            # True engine handoff, cold/anchor streaming arm.
            try:
                self._telemetry.on_turn_dispatch(slot)
            except Exception:
                pass
            slot.stream_ready_event.set()
            try:
                await asyncio.wait_for(slot.stream_done_event.wait(), timeout=_STREAM_TIMEOUT_S)
            except asyncio.CancelledError:
                self._log_kv_reuse_outcome(slot, handle, wait_state="cancelled")
                raise
            except TimeoutError:
                log.warning("streaming slot %s exceeded 3600s", slot.slot_id)
                self._log_kv_reuse_outcome(slot, handle, wait_state="timeout")
            else:
                _forced = slot.stream_done_forced_reason
                self._log_kv_reuse_outcome(
                    slot, handle,
                    wait_state="forced" if _forced else "completed",
                    reason=_forced,
                )
            if slot.completion_future is not None and not slot.completion_future.done():
                slot.completion_future.set_result({"_streamed": True})
        else:
            slot.engine_op = "prefill"
            # Capture a clean-prefix KV (pre-generation) so the
            # next cold restore reuses instead of CLEAR+reprefill. No-op unless
            # single-series + large ctx + no equal/larger clean bin already saved.
            await self._probe_and_save_clean_kv(handle, slot)
            slot.engine_op = "decode"
            # True engine handoff, cold/anchor non-streaming arm --
            # AFTER the KV probe/save above, never before (see on_turn_dispatch
            # docstring: firing earlier folds probe/save latency into PREFILL).
            try:
                self._telemetry.on_turn_dispatch(slot)
            except Exception:
                pass
            result = await self._complete_fn(slot, handle)
            if slot.completion_future is not None and not slot.completion_future.done():
                slot.completion_future.set_result(result)
            # Completion-cache WRITE site, ported from
            # _process_slot's own write site (same call, same args, same
            # place relative to set_result). No-op unless this slot is a
            # cache leader; only a real dict result is cached.
            self._completion_cache_store(slot, result)
        # GRACE + ACTIVE_MATCH warm reuse within the grace window (per-resident).
        slot.engine_op = "idle"

        # THE GRACE ENTRY ITSELF IS GATED, not just the wait.
        #
        # Rationale. A designated victim must not enter GRACE at all, so this
        # check sits ABOVE the grace entry. Placed below it, a designated victim
        # would transition into SlotState.GRACE, stamp grace_started_at, start
        # the resident's GraceTimer and emit `grace_enter` -- and only then
        # decline to WAIT. Entering is what is forbidden, not just waiting: the
        # designated victim gets no grace timer and no idle-unload countdown, and
        # both are surrendered the instant it is designated. Honouring that
        # requires that no grace state is ever entered for the victim, which in
        # turn requires a legal direct ACTIVE->POPPED transition in the FSM
        # table (without one, GRACE would be a structurally required waypoint).
        # fsm.py provides that transition, and this check depends on it.
        # The wait loop below is reached only by a resident that is not the victim.
        #
        # SURRENDERED, NOT PAUSED. The victim's turn ends with no GRACE state,
        # no grace_started_at, no GraceTimer window and no `grace_enter` event;
        # `grace_designated_victim_skip` is now the ONLY grace-family event on
        # its slot. It leaves ACTIVE -> POPPED directly at the tail of this
        # function. The idle-unload half of this behaviour was already implemented at
        # _drive_resident's own immediate-evict branch and is untouched here.
        #
        # RESTORATION IS A NEGATIVE REQUIREMENT, AND IT IS SATISFIED
        # BY THIS SHAPE. A spared victim returns to normal operation
        # (the normal path), and its grace timer and idle-unload countdown restart at
        # that moment. Nothing is carried over because nothing is remembered:
        # `_is_designated_unload_target_locked` is pure, read-only and claim-gated, so
        # once the claim is served this predicate simply answers False and the
        # resident takes the ordinary path below with a FULL fresh window --
        # never a remainder. That is the intended design:
        # in that scenario the victim is spared while still MID-TURN, so its
        # grace clock never started and there is no remainder to compute
        # against; and a partial window would be exactly the continuing cost
        # that the victim rule excludes. ⛔ DO NOT add a "was designated" flag, a
        # paused-clock remainder, or any carried-forward designation state to
        # make restoration explicit -- that state would BREAK the rule, which
        # forbids carrying a designation forward from an earlier
        # decision. The victim-enters-no-grace test pins this.
        #
        # ONE evaluation, not two. The victim is chosen fresh at each
        # decision MOMENT; the entry and the wait are ONE moment, so they must
        # read one boolean. Two live evaluations could disagree and leave a slot
        # half-entered into a window nothing would ever close.
        #
        # Deliberately simple: this reuses
        # `_is_designated_unload_target_locked` as-is (no new selection logic, no
        # second place that could drift).
        #
        # The in-loop `grace_fastlane_breakout` check does not run inside the
        # wait below. It asked a REQUEST-scoped question -- does a higher-priority
        # WAITER exist for this holder -- and the answer must never end a
        # NON-victim's grace: only the designated victim loses its grace.
        # The wait below is entered only when this resident is NOT the
        # designated victim, so every resident that reaches it is a non-victim
        # and keeps its full grace window. Keeping the check inside the wait
        # would shorten the window of exactly those residents, so it was
        # removed from the wait. The check is RETAINED, uncalled, at
        # `_legacy_fastlane_grace_breakout`, which documents why it is
        # unreachable and what to read before reattaching a caller. Whether this
        # resident is the designated victim is decided separately, by the
        # designation-scoped check described next.
        #
        # The DESIGNATION-scoped question -- is THIS resident the worst of
        # all currently loaded -- is untouched and still decides
        # `skip_grace`: the earlier breakout still holds for the DESIGNATED VICTIM,
        # which is where it now applies exclusively. No new eviction call
        # site: this evicts nothing, it lets the resident reach the existing
        # IDLE_EVICTABLE park point sooner, where `_lru_idle_unloadable` /
        # `_route_or_reserve` still make the real decision, fresh.
        async with self._registry_lock:
            # A higher-ranked request parked in r's own inbox also ends the wait
            # for follow-ups: it is admitted next, on r, with no unload.
            skip_grace = (
                self._is_designated_unload_target_locked(r)
                or self._parked_claim_outranks_holder_locked(r)
            )
        if skip_grace:
            await self._audit_async(slot, "grace_designated_victim_skip")
            log.info(
                "grace_designated_victim_skip slot=%s model=%s resident=%s",
                slot.slot_id, slot.model_tag, r.resident_key,
            )
            # The turn genuinely completed, so the completion hook
            # still fires -- but labelled for what actually happened. Emitting
            # reason="grace_enter" for a slot that provably never entered grace
            # would rebuild, in the telemetry surface, the exact falsehood the
            # audit surface avoids.
            try:
                self._telemetry.on_completion(slot, "grace_designated_victim_skip")
            except Exception:
                pass
        else:
            transition(slot, SlotState.GRACE)
            slot.grace_started_at = time.monotonic()
            r.grace.start(slot.thread_id, slot.model_tag)
            # The grace window is LIVE -- covers both idle grace
            # and any ACTIVE_MATCH follow-up served within it. _resident_phase
            # uses this flag to gate the countdown display.
            r.in_grace_loop = True
            # A FRESH grace window must not inherit a candidate
            # notified during some earlier window on this same resident.
            r.starvation_breakout_candidate = None
            await self._audit_async(slot, "grace_enter")

            # Telemetry (parity with the single-slot path):
            # completion. Same relative placement as _process_slot's own
            # completion hook (right after its own anchor ACTIVE->GRACE audit
            # event), its OWN separate try/except (not merged with the
            # assign/prefill guard above), and fired ONLY for this anchor
            # `slot` -- _process_slot has exactly ONE call site for this hook,
            # so a grace-window ACTIVE_MATCH-promoted `matched` follow-up below
            # (its own transition(matched, GRACE)) does NOT get its own
            # on_completion call either; doing so would emit MORE telemetry
            # than the cap<=1 path ever does for the equivalent scenario, which
            # is new behaviour, not parity. This call sits INSIDE the
            # non-victim branch, with the victim's own labelled call above:
            # still exactly one on_completion per anchor turn, either way.
            try:
                self._telemetry.on_completion(slot, "grace_enter")
            except Exception:
                pass

            deadline = time.monotonic() + self.runtime.queue.grace_seconds
            # ── Inter-turn wait fix, hoisted OUT of the poll loop ──
            # The loop below polls every 50 ms for the whole grace window (~1200
            # iterations at grace_seconds=60), and this value is loop-invariant, so it
            # is parsed ONCE here.
            #
            # ⚠ parse_shared_addresses is NOT optional. The config field is a bare
            # pydantic ``str`` (comma-separated, default ""); passing it RAW makes the
            # guard iterate CHARACTERS, so no entry can ever equal a full address and
            # the denylist silently matches NOTHING. The "" default short-circuits, so
            # the defect is invisible until an operator configures the list -- i.e.
            # exactly when the guard is meant to start working. For example:
            # eligible("192.0.2.1", raw) -> True (!) vs eligible(.., parse(raw)) -> False.
            #
            # ⚠ THIS IS LOOP A (`_serve_on_resident`), THE cap>=2 PATH, AND IT IS THE
            # ONLY SITE THAT GETS THIS. `worker_loop` returns into `_dispatch_loop()`
            # when max_parallel_sidecars >= 2, so Loop B (`_process_slot`) is the
            # deprecated cap<=1 path and is unreachable in normal deployments. It also
            # does not NEED this: the stable content-derived identity in
            # api/chat_completion.py is gated ON at ``max_parallel_sidecars <= 1``, so
            # on that path thread_id does not churn and pop_matched_thread already
            # hits. Wiring Loop B would be inert code guarding a solved problem.
            # client_has_outstanding_work stays imported and
            # UNCALLED (FORBIDDEN: wire it in, in any form -- it counts the
            # request it is deciding about, so it refuses in exactly the case
            # it exists for). observe_for_grace_match
            # is a pre-existing unused import, out of scope here.
            from turbohaul.api.chat_completion import client_has_outstanding_work
            from turbohaul.slot import observe_for_grace_match

            while time.monotonic() < deadline and not self._stop_event.is_set():
                # ── RE-CHECK DESIGNATION EACH ITERATION ───────
                # The Fast Lane rule -- a victim's grace is surrendered
                # the instant it is designated, not at turn-end. The entry-time
                # `skip_grace` check above is evaluated ONCE; a resident that
                # enters grace as a NON-victim and is designated 5s later then
                # sits the FULL window. Without this re-check a
                # registered higher-priority claim would wait out the full
                # grace window.
                #
                # THE NON-VICTIM RULE IS PRESERVED BY CONSTRUCTION: this fires only when THIS
                # resident is NOW the designated target. It never fires merely
                # because a higher-priority request is waiting -- that was
                # the old breakout, which hit non-victims and is correctly
                # gone (only the designated victim loses its grace).
                #
                # LOCK DISCIPLINE MATCHES THE ENTRY-TIME CHECK ABOVE -- compute
                # under the lock, RELEASE, then act. `_audit_async` is an
                # `asyncio.to_thread` hop; holding the global
                # `_registry_lock` across it would stall every other resident's
                # registry work for the duration.
                async with self._registry_lock:
                    designated_mid_grace = (
                        self._is_designated_unload_target_locked(r)
                        or self._parked_claim_outranks_holder_locked(r)
                    )
                if designated_mid_grace:
                    # A DISTINCT EVENT, NOT `grace_designated_victim_skip`.
                    # That key means "no GRACE state, no
                    # grace_started_at, no GraceTimer window and no grace_enter
                    # event -- the ONLY grace-family event on its slot". THIS
                    # slot has all four. Reusing the key would put a provable
                    # falsehood on the audit surface, and would emit `grace_enter`
                    # and a "never entered grace" event for one slot -- two
                    # states that have always been mutually exclusive.
                    await self._audit_async(
                        slot, "grace_designated_unload_target_break"
                    )
                    log.info(
                        "grace_designated_unload_target_break slot=%s model=%s "
                        "resident=%s (designated mid-window, surrendering grace)",
                        slot.slot_id, slot.model_tag, r.resident_key,
                    )
                    # ⛔ NO on_completion HERE. The `else` branch this loop lives
                    # in ALREADY fired `on_completion(slot, "grace_enter")`, as shown
                    # above, and the invariant stated there is
                    # "exactly one on_completion per anchor turn, either way".
                    # A second call double-counts completion telemetry and emits
                    # MORE than the cap<=1 path ever does -- which that same
                    # comment names as "new behaviour, not parity".
                    break
                # The earlier in-loop Fast Lane breakout
                # USED TO SIT HERE, at the top of the iteration. It is GONE
                # from this loop -- not narrowed, ENDED. This loop body is
                # reached only in the `else` of `skip_grace` above, so every
                # resident reaching it is BY DEFINITION not the designated
                # victim, and such a client is not evicted for
                # the waiting request -- its grace counts down fully.
                # Only the designated victim loses its grace.
                # The code is RETAINED, uncalled, at
                # `_legacy_fastlane_grace_breakout` -- read its 5-part
                # marker before reattaching anything here.
                # DIVERGENCE, deliberate: Loop B (`_process_slot`) KEEPS its
                # copy of this check. Loop B is the deprecated cap<=1 path
                # (retained as-is) and is deliberately not touched, so
                # the two grace loops now differ here on purpose. Do not
                # "tidy" them back together.
                # ⚠ `_is_designated_unload_target_locked()` is False when the `else` is
                # taken, but it is NOT permanently False inside this branch: designation
                # can arrive at any point during the grace window, which can last the
                # full grace period. An entry-only check would say nothing about the
                # rest of the window, so the same gate is re-checked at the top of this
                # loop. It is scoped to THIS resident only, which keeps the non-victim
                # rule intact. Do not conclude from the `else` that the predicate cannot
                # change inside this branch: the top of this loop re-evaluates it on
                # every iteration for exactly that reason.
                # What must NOT come back is the old breakout on "someone
                # higher-priority is waiting" -- that hit NON-victims. The
                # retained copy at `_legacy_fastlane_grace_breakout` stays
                # uncalled; read its 5-part marker before reattaching anything.
                # A request routed to this resident's inbox never sits in
                # staging; hand the inbox over so a better-ranked request of
                # the same client waiting there is weighed against the
                # follow-up. With nothing in the inbox the call is unchanged.
                if r.inbox is not None and not r.inbox.empty():
                    matched = await self.queue.pop_matched_thread(
                        slot.thread_id, slot.model_tag, inbox=r.inbox
                    )
                else:
                    matched = await self.queue.pop_matched_thread(
                        slot.thread_id, slot.model_tag
                    )
                # ── STABLE IDENTITY WITHOUT A CLIENT session_id ──────
                # thread_id is derived by hashing request CONTENT, so it churns on
                # every turn; pop_matched_thread therefore misses, the request is
                # enqueued at the TAIL, and it waits out the rest of this grace
                # window (the wait equals grace_seconds minus the client gap).
                # Falling back to the client's ADDRESS gives a stable
                # key -- but an address is a far blunter identity than a thread, so
                # it is allowed only behind two gates that must BOTH pass:
                #
                #   grace_ip_match_eligible     is this address usable at
                #       all -- not blank/None/non-string, and not a KNOWN shared
                #       gateway that several containers egress through.
                #   client_has_outstanding_work is this client ALONE right
                #       now? One address is shared by every sub-agent of a
                #       parallel fan-out; matching on it while siblings are live
                #       would fuse two conversations onto one KV cache.
                #
                # ⛔ THE GUARD LIST IS CLOSED AT EXACTLY THESE TWO.
                # In particular NOT `ssrf_guard.is_blocked_ip` -- it denies PRIVATE
                # ranges, which is every address a private-network client has (so every
                # such client is blocked and only public addresses pass), so it would
                # make this fix 100% inert while passing any test written with
                # public-looking IPs. And NOT a cap test: `_effective_cap(tag) >= 2`
                # is False whenever the host budget is spent or only one card
                # fits, inert the same way. Concurrency -- not the cap -- is what separates "my own
                # next turn" from "my sibling".
                #
                # ⚠ THE OBSERVATION IS TAKEN HERE, AFTER the await above, never at
                # the top of the loop: pop_matched_thread is `async` and takes the
                # queue lock, so it is a real suspension point. A sibling arriving
                # during it is invisible to an earlier snapshot, and the gate would
                # then read SOLITARY while a sibling exists -- the permissive
                # direction, and precisely the fusion this guard exists to prevent.
                #
                # ⚠ Every failure path here resolves to "concurrent" (refuse). A
                # wrong refusal costs one slow turn, which is today's status quo; a
                # wrong match corrupts a live conversation's KV cache.
                # The client-ADDRESS fallback that used to run
                # here is RETIRED -- retained, unreachable, at
                # `_legacy_ip_grace_match` (read its 5-part marker before
                # reattaching anything). It is replaced by a CONTENT-DERIVED
                # identity match: the completing slot's own admission_hash_chain,
                # via kv_policy._is_prefix_match (the same primitive the KV
                # restore gate uses -- not re-implemented), against every
                # staged/inbox candidate for this model. A growing conversation
                # EXTENDS its chain, so the anchor's chain stays a genuine
                # PREFIX of a real follow-up's chain even though the derived
                # thread_id above churns -- the reason this can succeed where
                # pop_matched_thread just failed. Empty/absent chain -> no
                # match, fail-safe (kv_policy._is_prefix_match rejects an
                # empty saved_chain outright), same posture the retired path
                # held via its denylist.
                #
                # ⚠ REPLACES A LIVE CONSUMER-FACING LABEL, NOT A DEAD ONE:
                # `QUEUE_ADMITTED_NO_PICK via=pop_matched_ip`
                # and `via=pop_matched_ip_inbox` (both frequently emitted
                # labels) stop emitting; `via=pop_matched_hash_chain` and
                # `via=pop_matched_hash_chain_inbox` take their place. Any log
                # analysis keyed on the old via= values goes quiet from this
                # point forward.
                _anchor_chain = getattr(slot, "admission_hash_chain", None) or []
                if matched is None and _anchor_chain:
                    matched = await self.queue.drain_inbox_and_staging_match_hash_chain(
                        _anchor_chain, slot.model_tag, slot.grace_started_at,
                        inbox=r.inbox,
                    )
                if matched is not None:
                    matched.port = handle.port
                    matched.pid = handle.pid
                    r.active_slot = matched
                    # Release the staging_arrival claim for the matched
                    # follow-up. pop_matched_thread dequeues from the queue but
                    # the claim registered at staging-arrival
                    # is never released here, causing a claim held until the 1800 s TTL.
                    async with self._registry_lock:
                        self._release_fastlane_claim_locked(matched, "admitted")
                    # Actively serving a follow-up -- FREEZE
                    # the grace countdown. GraceTimer.pause() stores the remaining_s()
                    # in _paused_remaining, NOT touching _started_at (which
                    # _grace_active_exclusions reads for victim protection).
                    if r.grace is not None:
                        r.grace.pause()
                    completed_ok = True  # gates the grace_tip advance below
                    try:
                        transition(matched, SlotState.ACTIVE_MATCH)
                        transition(matched, SlotState.ACTIVE)
                        # The SIXTH per-turn site for the
                        # tools check, and the only one not reached via
                        # _mark_slot_active. A grace-window follow-up promoted here
                        # is a genuine new TURN (it came off the queue via
                        # pop_matched_thread above), but this branch never calls
                        # _mark_slot_active -- unlike _process_slot's own equivalent,
                        # so the seam does not reach it.
                        # Placed ABOVE the m_stream/else split on purpose: both arms
                        # are per-turn, and the streaming arm below never called the
                        # KV probe, so it had NO tools check at all before this.
                        # ⛔ Adding _mark_slot_active(matched) here instead would be
                        # tidier and is DELIBERATELY NOT DONE: it would newly stamp
                        # started_active_at and fire _fastlane_census_mark_served on
                        # a path that does neither today -- a behaviour change well
                        # outside an observability fix. That asymmetry between the
                        # two grace loops is out of scope for this path.
                        self._check_thread_tools_fingerprint(matched)
                        # Omission must not cancel an explicit intent
                        # (last-EXPLICIT-writer-wins).
                        ka = (matched.client_meta or {}).get("keep_alive_s")
                        if ka is not None:
                            r.latest_keep_alive_s = ka
                        m_stream = (
                            isinstance(matched.client_meta, dict)
                            and matched.client_meta.get("stream", False)
                            and matched.stream_ready_event is not None
                            and matched.stream_done_event is not None
                        )
                        if m_stream:
                            matched.stream_handle = handle
                            # True engine handoff, warm ACTIVE_MATCH
                            # streaming arm -- the silent case (grace-window
                            # follow-up on the same handle, no on_prefill_start
                            # here today).
                            try:
                                self._telemetry.on_turn_dispatch(matched)
                            except Exception:
                                pass
                            matched.stream_ready_event.set()
                            matched.engine_op = "stream"
                            try:
                                await asyncio.wait_for(
                                    matched.stream_done_event.wait(), timeout=_STREAM_TIMEOUT_S
                                )
                            except asyncio.CancelledError:
                                self._log_kv_reuse_outcome(matched, handle, wait_state="cancelled")
                                raise
                            except TimeoutError:
                                self._log_kv_reuse_outcome(matched, handle, wait_state="timeout")
                            else:
                                _forced = matched.stream_done_forced_reason
                                self._log_kv_reuse_outcome(
                                    matched, handle,
                                    wait_state="forced" if _forced else "completed",
                                    reason=_forced,
                                )
                            if matched.completion_future is not None and not matched.completion_future.done():
                                matched.completion_future.set_result({"_streamed": True})
                        else:
                            matched.engine_op = "prefill"
                            await self._probe_and_save_clean_kv(handle, matched)
                            matched.engine_op = "decode"
                            # True engine handoff, warm ACTIVE_MATCH
                            # non-streaming arm -- AFTER the KV probe/save above,
                            # same reasoning as the cold arm's own placement.
                            try:
                                self._telemetry.on_turn_dispatch(matched)
                            except Exception:
                                pass
                            res = await self._complete_fn(matched, handle)
                            if matched.completion_future is not None and not matched.completion_future.done():
                                matched.completion_future.set_result(res)
                    except asyncio.CancelledError:
                        raise
                    except Exception as e:  # noqa: BLE001 -- per-slot isolation
                        completed_ok = False
                        self._fail_completion_future(matched, e)
                        log.exception("active_match completion failed %s", matched.slot_id)
                    transition(matched, SlotState.GRACE)
                    # Port of the single-slot path's own two gates (not just the bare
                    # pointer swap): a failed follow-up never actually landed
                    # content on the engine (same reasoning as the single-slot path, mirrored
                    # here); a curator/sub-agent/compression follow-up can share
                    # the anchor's own thread_id (pop_matched_thread has no role
                    # awareness) but must never overwrite the tip -- either would
                    # corrupt the parked identity, the second case turning a
                    # stale-but-present main bin into no bin at all at teardown.
                    # Same _bin_role gate Loop B uses.
                    if completed_ok and _bin_role(matched.client_meta) in (None, "main"):
                        r.grace_tip = matched
                        # The resident's latest turn is now this follow-up: its rank
                        # follows it, like the tip, for designation and for eviction.
                        r.rank_client_meta = matched.client_meta
                    if r.grace.restart_for_followup():
                        deadline = time.monotonic() + self.runtime.queue.grace_seconds
                    # Follow-up completed -- RESUME the grace
                    # countdown (the tip pointer was already advanced above for
                    # main-class matches that landed content).
                    if r.grace is not None:
                        r.grace.resume()
                    transition(matched, SlotState.POPPED)
                    # Parity with _process_slot's own copy of this
                    # branch -- mark_slot_ended below writes ONLY to
                    # the slots table's end_reason column, never audit_events
                    # (a documented limitation), so a caller that
                    # reads a follow-up's completion off its audit trail (as
                    # opposed to polling slot.state, the documented
                    # workaround) saw nothing here. Adds ONLY the
                    # audit line, deliberately NOT `_mark_slot_active` (its
                    # other side effects -- started_active_at stamping,
                    # _fastlane_census_mark_served -- stay the known
                    # asymmetry the comment above already names).
                    await self._audit_async(
                        matched,
                        "active_match_completed" if completed_ok
                        else "active_match_failed_terminal",
                    )
                    with state_db_session(self.boot.storage.state_db_path) as conn:
                        mark_slot_ended(conn, matched.slot_id, "active_match_completed")
                    r.active_slot = slot
                    continue
                # Gated -- a Fast Lane CLAIM cannot use
                # this path to shorten a non-victim's grace (see the
                # helper's own docstring for why no victim check is needed).
                # Checks BOTH sources that can answer "is there a
                # starved other-model candidate right now" -- r.starvation_
                # breakout_candidate (notified synchronously by
                # _defer_unroutable the instant a routing attempt for an
                # aged other-model slot fails while THIS resident is in
                # grace; see that field's own docstring for the
                # buffer-visibility blind spot this covers) is checked
                # first (no await), falling through to the original
                # _starvation_breakout_candidate buffer scan for a starved
                # waiter _dispatch_loop has not attempted yet (a real case
                # the notification alone does not cover, since it only
                # fires on an actual failed routing attempt). Both funnel
                # through the identical gate either way.
                _starved_notified = self._starvation_breakout_gate(
                    r.starvation_breakout_candidate
                )
                if _starved_notified is None:
                    _starved_notified = await self._starvation_breakout_candidate(slot)
                if _starved_notified is not None:
                    await self._audit_async(slot, "grace_starvation_breakout")
                    log.info(
                        "grace_starvation_breakout slot=%s model=%s",
                        slot.slot_id,
                        slot.model_tag,
                    )
                    break
                await asyncio.sleep(0.05)
            # Wake any coroutine
            # parked in _wait_for_park_or_timeout the instant this
            # resident's grace ends (natural lapse OR either existing
            # break above) -- not yet IDLE_EVICTABLE (that transition is
            # the OUTER loop's job, below), so this is a pure latency
            # optimization on the SAME object every other notify site
            # already uses, matching _wait_for_park_or_timeout's own
            # documented "a lost wake just falls back to the existing
            # timeout, never a correctness dependency" contract. Needs its
            # OWN lock: this loop awaits repeatedly, so _registry_lock is
            # never held across it (fsm.py's transition() itself is a
            # pure, lock-free, synchronous function) -- notify_all() on an
            # unacquired Condition's lock raises RuntimeError.
            async with self._registry_lock:
                # Wake dispatch loop alongside make-room signal
                self._dispatch_wake.set()
                self._make_room_signal.notify_all()
                # Grace loop EXITING (natural lapse /
                # starvation breakout / empty inbox). The grace window is no
                # longer live -- clear the flag _resident_phase gates the
                # countdown display on.
                r.in_grace_loop = False
                # No grace window live -- nothing should read this
                # stale reference until the NEXT grace_enter resets it.
                r.starvation_breakout_candidate = None
        transition(slot, SlotState.POPPED)
        assert not r.inflight, "Design #1 invariant: riders drain before GRACE exit"

    async def _fan_out_on_resident(
        self, r: "Resident", anchor: Slot, handle, n_parallel: int
    ) -> None:
        """Per-resident CONTINUOUS concurrent serve, up to ``n_parallel`` in-flight,
        riding ``r.inflight`` (IN-PLACE -- never rebind).

        LAYER-2 (per-model parallelism): same-model requests are routed by the
        dispatcher to THIS resident's ``r.inbox`` (model-pure), NOT left in the global
        staging queue -- so riders are pulled from ``r.inbox`` and the pipe is kept full
        up to ``n_parallel`` WHILE any slot is still generating, so a request arriving
        mid-burst joins immediately (llama-server ``--parallel N`` serves them). Each
        slot runs its own stream/non-stream completion, so a mixed-mode burst is fine.
        Drains every in-flight slot before returning so GRACE/teardown stays safe
        (Design #1 invariant: ``r.inflight`` empty on exit)."""
        r.inflight[:] = []
        tasks: dict[asyncio.Task, Slot] = {}

        def _launch(s: Slot) -> None:
            # A rider never passes the driver's per-turn entry: its own turn
            # starts here (sync and await-free, like the release itself).
            self._release_fastlane_claim_locked(s, "admitted")
            s.stream_handle = handle
            r.inflight.append(s)
            s_stream = (
                isinstance(s.client_meta, dict)
                and bool(s.client_meta.get("stream", False))
                and s.stream_ready_event is not None
                and s.stream_done_event is not None
            )
            if s_stream:
                s.stream_ready_event.set()
                t = asyncio.create_task(self._await_streamed_slot(s))
            else:
                t = asyncio.create_task(self._complete_one_slot(s, handle))
            tasks[t] = s

        def _admit_from_inbox() -> None:
            # Pull queued same-model riders (r.inbox is model-pure: the dispatcher only
            # routes THIS resident's model here) up to n_parallel concurrent in-flight.
            # Priority-selected via the shared drain/select/admit/restore
            # helper. The is_evicted check that used to live in this loop is now the
            # helper's job (it fail-completes evicted riders during its own drain and
            # never returns one), shared identically across all three admit-grab sites.
            while len(tasks) < n_parallel:
                extra = self._priority_admit_from_inbox(r)
                if extra is None:
                    break
                _launch(extra)

        try:
            _launch(anchor)
            _admit_from_inbox()
            while tasks:
                done, _pending = await asyncio.wait(
                    set(tasks), return_when=asyncio.FIRST_COMPLETED
                )
                for t in done:
                    s = tasks.pop(t)
                    if s in r.inflight:
                        r.inflight.remove(s)
                    exc = t.exception()
                    if exc is not None:
                        self._fail_completion_future(s, exc)
                # Keep the pipe full: admit any riders that arrived mid-burst.
                _admit_from_inbox()
        finally:
            # Driver cancelled / unexpected raise mid-burst: cancel the still-running
            # per-slot tasks and fail their futures so no client hangs and no task is
            # orphaned. Normal exit leaves ``tasks`` empty -> no-op.
            if tasks:
                for t, s in list(tasks.items()):
                    t.cancel()
                    self._fail_completion_future(
                        s, RuntimeError(f"resident {r.model_tag!r} fan-out interrupted")
                    )
            r.inflight.clear()

    async def _complete_one_slot(self, s: Slot, handle) -> None:
        """Serve one NON-streaming slot on the shared handle + resolve its future."""
        try:
            res = await self._complete_fn(s, handle)
            if s.completion_future is not None and not s.completion_future.done():
                s.completion_future.set_result(res)
        except asyncio.CancelledError:
            raise
        except Exception as e:  # noqa: BLE001 -- per-slot isolation
            self._fail_completion_future(s, e)

    async def _await_streamed_slot(self, s: Slot) -> None:
        """Wait for a STREAMING slot's HTTP handler to finish, then resolve its future."""
        _had_event = s.stream_done_event is not None
        try:
            if _had_event:
                await asyncio.wait_for(s.stream_done_event.wait(), timeout=_STREAM_TIMEOUT_S)
        except asyncio.CancelledError:
            if _had_event:
                self._log_kv_reuse_outcome(s, s.stream_handle, wait_state="cancelled")
            raise
        except TimeoutError:
            self._log_kv_reuse_outcome(s, s.stream_handle, wait_state="timeout")
        else:
            if _had_event:
                _forced = s.stream_done_forced_reason
                self._log_kv_reuse_outcome(
                    s, s.stream_handle,
                    wait_state="forced" if _forced else "completed",
                    reason=_forced,
                )
        if s.completion_future is not None and not s.completion_future.done():
            s.completion_future.set_result({"_streamed": True})

    async def _fan_out_and_drain(
        self, anchor: Slot, handle, n_parallel: int,
    ) -> None:
        """Per-model concurrent dispatch (Design #1): serve up to ``n_parallel``
        same-model STREAMING requests concurrently on ONE shared sidecar.

        Reached ONLY from the ACTIVE branch when the active model's manifest
        declares parallel>1 (``n_parallel == handle.parallel``). parallel:1
        models never enter here -- they take the verbatim serial block, which
        stays byte-identical to today.

        Shape: a ONE-SHOT fan-out (admit up to ``n_parallel - 1`` extra riders
        from the queue exactly once -- never continuously refilling, so it
        cannot livelock the model swap) followed by a per-rider DRAIN barrier.
        Returns only when EVERY rider's route has genuinely finished its stream
        (``self._inflight`` empty), so the caller can safely advance
        ACTIVE->GRACE and (later) tear the sidecar down.

        Single-mutator discipline preserved: worker_loop is the sole writer of
        ``self._inflight``; routes only ever set their OWN
        ``slot.stream_done_event``. No lock, and the drain waiter tasks are
        owned + awaited here (cancelled on every exit), never detached.
        """
        # The anchor's mode decides the whole fan-out: STREAMING riders are
        # served by their own HTTP route (stream_ready/stream_done events);
        # NON-STREAMING riders by concurrent manager-owned _complete_fn calls.
        # AI harness sub-agents are non-streaming, so the non-streaming path is the
        # one that matters in practice. Riders must match the anchor's mode
        # (the admit loop enforces it; mixed-mode riders go back to the queue).
        anchor_streaming = bool(
            isinstance(anchor.client_meta, dict)
            and anchor.client_meta.get("stream", False)
        )
        # (1) The anchor is rider 0 -- already ACTIVE on `handle`.
        # MUTATE IN PLACE, never rebind self._inflight. The lone
        # resident's ``inflight`` is the SAME list object (Resident(inflight=
        # self._inflight)); rebinding would orphan that view. ``[:] =`` keeps the
        # one canonical list so r.inflight never diverges (P1d reads r.inflight).
        self._inflight[:] = [anchor]
        anchor.stream_handle = handle
        if anchor_streaming and anchor.stream_ready_event is not None:
            anchor.stream_ready_event.set()
        keep_alives: list[int | None] = [
            (anchor.client_meta or {}).get("keep_alive_s")
        ]

        # (2) ONE-SHOT admit loop: pull up to n_parallel-1 MORE same-model
        # streaming riders and attach them to the SAME sidecar handle.
        while len(self._inflight) < n_parallel:
            extra = await self.queue.pop_next(
                warm_model_tag=anchor.model_tag, fastlane_policy=self._fastlane_pop_kwarg(),
                # Without grace_active, this call shape (warm_model_tag=
                # anchor's own tag) would steal a DIFFERENT
                # resident's grace-held follow-up via the starvation
                # fallback once it ages past max_other_model_wait_s -- the
                # same guarantee violation _dispatch_loop's own call would otherwise
                # have, just reached through the fan-out rider path instead.
                grace_active=await self._grace_active_exclusions(),
            )
            if extra is None:
                break  # queue has no more admissible riders right now
            extra_streaming = (
                isinstance(extra.client_meta, dict)
                and bool(extra.client_meta.get("stream", False))
            )
            if (
                extra.model_tag != anchor.model_tag
                or extra_streaming != anchor_streaming
            ):
                # Wrong model OR a different streaming-mode than the anchor: not
                # a rider for THIS fan-out. Push it back to the HEAD (the serial
                # path / next fan-out handles it) and stop -- this is one-shot.
                await self.queue.enqueue_head(extra)
                break
            if extra.is_evicted:
                # Client disconnected before admit -> do NOT burn a slot on it.
                self._fail_completion_future(
                    extra,
                    SlotEvictedError("client disconnected before fan-out admit"),
                )
                await self._audit_async(extra, "evicted_pre_fanout")
                continue
            # Promote the rider onto the shared sidecar. Drift-guard mirrors the
            # ACTIVE_MATCH promotion: if the slot's state drifted, reset its pid
            # to None FIRST (so _force_cold can NEVER sigterm the shared sidecar)
            # then cold-park it and drop it from the batch.
            # ⚠ SAFETY SEQUENCE MIRRORED in _admit_nonstreaming_riders (the
            # continuous-admit refill). Keep the pid=None-BEFORE-_force_cold
            # ordering identical in BOTH sites if you ever touch one.
            extra.port = handle.port
            extra.pid = handle.pid
            try:
                transition(extra, SlotState.LOADING)
                transition(extra, SlotState.ACTIVE)
            except InvalidTransition as drift_err:
                log.warning(
                    "fan-out rider %s state drift (%s) -- dropping; %s",
                    extra.slot_id, extra.state.value, drift_err,
                )
                extra.pid = None  # MUST precede _force_cold: never reap shared sidecar
                self._fail_completion_future(extra, drift_err)
                await self._force_cold(
                    extra, f"fanout_rider_drift:{extra.state.value}"
                )
                continue
            self._mark_slot_active(extra)
            extra.stream_handle = handle
            # Append to the rider set BEFORE signalling ready, so any observer
            # that sees the route unblock also sees the slot in self._inflight
            # (consistent state; keeps the drain-before-swap invariant exact).
            self._inflight.append(extra)
            keep_alives.append((extra.client_meta or {}).get("keep_alive_s"))
            await self._audit_async(extra, "fanout_rider_active")
            if anchor_streaming and extra.stream_ready_event is not None:
                extra.stream_ready_event.set()

        # keep_alive aggregate = MAX across riders (deterministic; the longest
        # warm-hold any rider asked for wins). Mirrors the serial anchor capture.
        _ka = [k for k in keep_alives if k is not None]
        self._set_latest_keep_alive(max(_ka) if _ka else None)

        # (3) DISPATCH + DRAIN, branched on the anchor's mode. Non-streaming
        # riders (AI harness sub-agents) are served by concurrent manager-owned
        # _complete_fn calls; streaming riders by their own routes (the barrier
        # below). Every admitted rider matches the anchor's mode.
        if not anchor_streaming:
            await self._drain_nonstreaming_riders(anchor, handle, n_parallel)
            return

        # (3-stream) DRAIN BARRIER. Each rider's route sets its OWN stream_done_event in
        # its finally (normal end, client-disconnect CancelledError, typed httpx
        # error, OR the route's own STREAM_TIMEOUT_S). We wait on the GENUINE
        # done-event -- never force-removing a rider while its route's httpx may
        # still be open (red-team must-fix: teardown gates on real route close,
        # not an accounting flag). A per-rider 3600s safety cap matches the
        # serial path's wait_for; on a cap, ONLY that rider is cooperatively
        # unwound -- siblings keep streaming. Returns when self._inflight is [].
        # Keyed by slot_id (Slot is a non-frozen dataclass and thus unhashable,
        # so it cannot be a dict key directly).
        waiters: dict[str, asyncio.Task] = {}
        for s in self._inflight:
            assert s.stream_done_event is not None
            waiters[s.slot_id] = asyncio.create_task(
                asyncio.wait_for(s.stream_done_event.wait(), timeout=_STREAM_TIMEOUT_S)
            )
        # asyncio.wait(..., FIRST_COMPLETED) can return several riders DONE in
        # one batch; the loop below processes them one at a time and can be
        # cancelled mid-batch (e.g. during _force_cold's await for an earlier
        # rider) before reaching a LATER rider that already finished. Track
        # which slot_ids were actually logged here so the finally sweep below
        # can tell "never reached, still needs its outcome reported" apart
        # from "already reported, just not yet removed from self._inflight" --
        # without this, a rider whose event is genuinely already set at that
        # point (either case looks identical from the event alone) would
        # either be silently skipped (never reached) or logged twice (already
        # reported).
        _logged_slot_ids: set[str] = set()
        try:
            pending = set(waiters.values())
            while pending:
                done, pending = await asyncio.wait(
                    pending, return_when=asyncio.FIRST_COMPLETED,
                )
                for s in list(self._inflight):
                    w = waiters[s.slot_id]
                    if w not in done:
                        continue
                    # Distinguish a genuine stream_done from the 3600s cap.
                    if not w.cancelled() and isinstance(
                        w.exception(), asyncio.TimeoutError
                    ):
                        log.warning(
                            "fan-out rider %s hit 3600s drain cap; cooperative "
                            "unwind (siblings unaffected)", s.slot_id,
                        )
                        if (
                            s.stream_done_event is not None
                            and not s.stream_done_event.is_set()
                        ):
                            # Stamped even though this site reports "timeout"
                            # (not "forced") below: this IS one of the three
                            # force-set paths the field's own docstring names,
                            # and a later reader of stream_done_forced_reason
                            # alone (not this log line) must still see that
                            # the event didn't come from the route.
                            s.stream_done_forced_reason = "fanout_drain_cap"
                            s.stream_done_event.set()
                        self._log_kv_reuse_outcome(s, handle, wait_state="timeout")
                    elif w.cancelled():
                        self._log_kv_reuse_outcome(s, handle, wait_state="cancelled")
                    else:
                        _forced = s.stream_done_forced_reason
                        self._log_kv_reuse_outcome(
                            s, handle,
                            wait_state="forced" if _forced else "completed",
                            reason=_forced,
                        )
                    _logged_slot_ids.add(s.slot_id)
                    if (
                        s.completion_future is not None
                        and not s.completion_future.done()
                    ):
                        s.completion_future.set_result({"_streamed": True})
                    if s is not anchor:
                        # Rider terminal cleanup: the ANCHOR continues through
                        # _process_slot's normal GRACE/teardown flow, but a rider
                        # is done the instant its own route closes. Decouple it
                        # from the shared sidecar (pid=None so _force_cold can
                        # never reap the handle) and walk it to COLD so no zombie
                        # ACTIVE slot lingers.
                        s.pid = None
                        await self._force_cold(s, "fanout_rider_drained")
                    self._inflight.remove(s)
        finally:
            # On NORMAL completion self._inflight is already empty. On an
            # exception/cancel mid-drain it may still hold live riders -- set
            # their stream_done_event so their routes unwind (a truncated stream
            # when the sidecar is later reaped on the error path is acceptable
            # degraded behaviour, never a hang or zombie).
            for s in self._inflight:
                if s.slot_id in _logged_slot_ids:
                    # Already reported in the main loop above; the unwind that
                    # brought us here landed after the log call but before
                    # self._inflight.remove(s) (e.g. mid-_force_cold). Do not
                    # report it a second time.
                    continue
                if (
                    s.stream_done_event is not None
                    and not s.stream_done_event.is_set()
                ):
                    s.stream_done_forced_reason = "fanout_drain_unwind"
                    s.stream_done_event.set()
                # A rider whose event is ALREADY set here never got a turn in
                # the main loop above (the unwind hit before its entry was
                # reached, even though asyncio.wait's FIRST_COMPLETED batch
                # already resolved it) -- still owed exactly one outcome line.
                _forced = s.stream_done_forced_reason
                self._log_kv_reuse_outcome(
                    s, handle,
                    wait_state="forced" if _forced else "completed",
                    reason=_forced,
                )
            # No orphaned waiters: cancel + await every still-pending task.
            for w in waiters.values():
                if not w.done():
                    w.cancel()
                    with contextlib.suppress(asyncio.CancelledError, Exception):
                        await w
            self._inflight.clear()  # P1c: in-place, keep r.inflight alias canonical

    async def _admit_nonstreaming_riders(
        self, anchor: Slot, handle, n_parallel: int,
    ) -> list[Slot]:
        """Admit MORE same-model NON-streaming riders onto
        the shared sidecar, up to ``n_parallel`` total in-flight. Returns the
        slots newly promoted (each appended to ``self._inflight`` and ACTIVE on
        ``handle``); ``[]`` when none are admissible right now.

        Mirrors the one-shot admit promotion in ``_fan_out_and_drain`` (same
        drift-guard, evicted-skip, audit) but is called REPEATEDLY by the drain
        so a rider that arrives mid-burst joins the free ``--parallel`` slot
        immediately instead of waiting out the anchor (fixes the 4.5s/9.1s
        serialization the one-shot admit left when req2 hadn't yet reached the
        queue at anchor launch).

        Single-mutator preserved: runs in the worker_loop task -- the sole
        writer of ``self._inflight``. A wrong-model OR streaming pop is pushed
        back to the queue HEAD and STOPS the refill; that same force-FIFO-head
        path is how the queue lets a starved OTHER-model request (e.g. the main
        27b, after ``max_other_model_wait_s``) break the same-model batch so the
        model can still swap back -- so this can never livelock the swap.
        """
        admitted: list[Slot] = []
        while len(self._inflight) < n_parallel:
            extra = await self.queue.pop_next(
                warm_model_tag=anchor.model_tag, fastlane_policy=self._fastlane_pop_kwarg(),
                # Without grace_active, this call shape (warm_model_tag=
                # anchor's own tag) would steal a DIFFERENT
                # resident's grace-held follow-up via the starvation
                # fallback once it ages past max_other_model_wait_s -- the
                # same guarantee violation _dispatch_loop's own call would otherwise
                # have, just reached through the fan-out rider path instead.
                grace_active=await self._grace_active_exclusions(),
            )
            if extra is None:
                break  # nothing queued for this model right now
            extra_streaming = (
                isinstance(extra.client_meta, dict)
                and bool(extra.client_meta.get("stream", False))
            )
            if extra.model_tag != anchor.model_tag or extra_streaming:
                # Not a rider for THIS non-streaming fan-out: push back to HEAD
                # (the next worker_loop pop / fresh fan-out / model swap handles
                # it) and STOP -- one bounded refill, never a queue busy-spin.
                await self.queue.enqueue_head(extra)
                break
            if extra.is_evicted:
                self._fail_completion_future(
                    extra,
                    SlotEvictedError("client disconnected before fan-out admit"),
                )
                await self._audit_async(extra, "evicted_pre_fanout")
                continue
            # Promote onto the shared sidecar (identical to the one-shot path).
            extra.port = handle.port
            extra.pid = handle.pid
            try:
                transition(extra, SlotState.LOADING)
                transition(extra, SlotState.ACTIVE)
            except InvalidTransition as drift_err:
                log.warning(
                    "fan-out refill rider %s state drift (%s) -- dropping; %s",
                    extra.slot_id, extra.state.value, drift_err,
                )
                extra.pid = None  # MUST precede _force_cold: never reap shared sidecar
                self._fail_completion_future(extra, drift_err)
                await self._force_cold(
                    extra, f"fanout_rider_drift:{extra.state.value}"
                )
                continue
            self._mark_slot_active(extra)
            extra.stream_handle = handle
            self._inflight.append(extra)
            await self._audit_async(extra, "fanout_rider_active")
            admitted.append(extra)
        return admitted

    async def _drain_nonstreaming_riders(
        self, anchor: Slot, handle, n_parallel: int,
    ) -> None:
        """Non-streaming concurrent dispatch (Design #1): fire ``_complete_fn``
        for EVERY rider at once -- each is its own httpx POST to the sidecar's
        ``--parallel`` slots, so the engine serves them concurrently via
        continuous batching. Await all, resolve each ``completion_future`` with
        its result (or fail ONLY that rider on a typed sidecar error -- siblings
        keep going), terminal-clean the riders, and clear ``self._inflight``.
        Returns only when every rider has completed (drain-before-swap holds).
        This is the path AI harness sub-agents take (they call non-streaming).

        While draining, keep the sidecar's ``--parallel``
        slots full by admitting same-model riders that arrive mid-burst -- the
        loop wakes on a completion OR a short poll (``_FANOUT_ADMIT_POLL_S``),
        then refills up to ``n_parallel`` via ``_admit_nonstreaming_riders``. So
        N sub-agents fired ~together run ``n_parallel``-at-a-time (the rest
        queue) instead of serializing, while the queue's same-model batch cap
        still lets the model swap back.
        """
        # One concurrent completion task per rider, keyed by slot_id (Slot is a
        # non-frozen dataclass and thus unhashable).
        ctasks: dict[str, asyncio.Task] = {
            s.slot_id: asyncio.create_task(self._complete_fn(s, handle))
            for s in self._inflight
        }
        try:
            # Admit any same-model riders ALREADY queued at drain start. Covers
            # the one-shot admit race: req2 reaches the queue micro-seconds after
            # the anchor's one-shot admit ran, so it would otherwise idle a free
            # slot until the anchor finished.
            for s in await self._admit_nonstreaming_riders(
                anchor, handle, n_parallel
            ):
                ctasks[s.slot_id] = asyncio.create_task(
                    self._complete_fn(s, handle)
                )
            pending = set(ctasks.values())
            while pending:
                done, pending = await asyncio.wait(
                    pending,
                    timeout=_FANOUT_ADMIT_POLL_S,
                    return_when=asyncio.FIRST_COMPLETED,
                )
                for s in list(self._inflight):
                    t = ctasks[s.slot_id]
                    if t not in done:
                        continue
                    if t.cancelled():
                        pass  # cancelled on teardown; future handled in finally
                    elif t.exception() is not None:
                        # A typed sidecar error fails ONLY this rider's caller.
                        self._fail_completion_future(s, t.exception())
                    else:
                        result = t.result()
                        if (
                            s.completion_future is not None
                            and not s.completion_future.done()
                        ):
                            s.completion_future.set_result(result)
                    if s is not anchor:
                        # Rider terminal cleanup (the anchor continues through
                        # _process_slot's GRACE/teardown). Decouple from the
                        # shared sidecar (pid=None) and walk to COLD.
                        s.pid = None
                        await self._force_cold(s, "fanout_rider_drained")
                    self._inflight.remove(s)
                # Refill any slot freed this tick (and admit a mid-burst arrival
                # that landed while a slot was free) up to n_parallel.
                for s in await self._admit_nonstreaming_riders(
                    anchor, handle, n_parallel
                ):
                    t = asyncio.create_task(self._complete_fn(s, handle))
                    ctasks[s.slot_id] = t
                    pending.add(t)
        finally:
            # Cancel + await any still-pending task; fail any unresolved rider
            # future so no caller hangs. Clear the rider set.
            for s in list(self._inflight):
                t = ctasks.get(s.slot_id)
                if t is not None and not t.done():
                    t.cancel()
                    with contextlib.suppress(asyncio.CancelledError, Exception):
                        await t
                if (
                    s.completion_future is not None
                    and not s.completion_future.done()
                ):
                    self._fail_completion_future(
                        s, RuntimeError("fan-out drain aborted"),
                    )
            self._inflight.clear()  # P1c: in-place, keep r.inflight alias canonical

    async def _process_slot(self, slot: Slot) -> None:
        """UNCALLED as of v0.8.0 (legacy path, retained for reference).
        RETAINED, NOT DELETED, per this codebase's convention for retained dead code
        (see `_legacy_defer_exhaustion_refusal`'s docstring for the rationale
        behind that convention).

        WHY unreachable: ``worker_loop`` (its sole caller) now routes ALL
        traffic to ``_dispatch_loop`` unconditionally — the fork that used
        to call this method was flipped from ``>= 2`` to ``>= 1``.
        ``_process_slot`` WAS the only driver at cap<=1
        and the cap<=1 body of ``worker_loop`` never runs any more.

        NOT MAINTAINED. Nothing exercises this any more; verify it before
        reattaching a caller -- it will have rotted exactly like any other
        unexercised path.

        WHAT REPLACED IT: ``_dispatch_loop`` -> ``_serve_on_resident``,
        the per-resident driver. All call sites that previously routed
        through ``_process_slot`` now route through the cap>=2 dispatcher.

        Loop A (``_serve_on_resident``) and Loop B (this method) diverged
        on grace-loop discipline; the live path uses Loop A exclusively."""
        self._set_active_slot(slot)
        # Clear cross-slot keep_alive leakage. A previous slot's
        # ACTIVE_MATCH chain may have left a value here even though that
        # slot's grace→idle consumed it; defensive reset keeps the invariant
        # "value reflects this anchor cycle only" honest.
        self._set_latest_keep_alive(None)

        try:
            # Build backend argv from manifest if available; tolerate missing
            # manifest for testing convenience.
            argv: list[str] = []
            manifest_is_mlx = False
            manifest_found = True
            try:
                manifest = read_manifest(self.boot.storage.manifests_path, slot.model_tag)
                manifest_is_mlx = manifest.is_mlx()
                if manifest_is_mlx:
                    # MLX: no GGUF blob. Build argv from the MLX closed allowlist.
                    argv = mlx_flags_to_argv(manifest.mlx_server_flags)
                else:
                    argv = flags_to_argv(manifest.llama_server_flags)
                    gguf_path = (
                        self.boot.storage.blob_store_path
                        / "sha256"
                        / manifest.gguf_blob_sha256[:2]
                        / manifest.gguf_blob_sha256
                    )
                    # Vision projector (mmproj): resolve the CONTENT-ADDRESSED blob and
                    # inject --mmproj. Manager-derived path only; the raw path-bearing
                    # `mmproj` flag stays in DENIED_FLAGS (no arbitrary file).
                    if manifest.mmproj_blob_sha256:
                        argv += ["--mmproj", str(
                            self.boot.storage.blob_store_path
                            / "sha256"
                            / manifest.mmproj_blob_sha256[:2]
                            / manifest.mmproj_blob_sha256
                        )]
                    # Standalone draft model (D-Flash/D-Spark): same
                    # content-addressed pattern as mmproj above -- see the other
                    # call site for the full rationale. Gated
                    # on spec_type too, not the hash alone -- see the other call
                    # site's comment for why. Logged, not silently dropped, when
                    # ignored.
                    _spec_type_for_draft = str(
                        manifest.llama_server_flags.get("spec_type", "") or ""
                    ).strip().lower()
                    if manifest.spec_draft_gguf_blob_sha256:
                        if _spec_type_for_draft in SPEC_TYPES_WITH_STANDALONE_DRAFT_MODEL:
                            argv += ["--spec-draft-model", str(
                                self.boot.storage.blob_store_path
                                / "sha256"
                                / manifest.spec_draft_gguf_blob_sha256[:2]
                                / manifest.spec_draft_gguf_blob_sha256
                            )]
                        else:
                            log.warning(
                                "spec_draft_gguf_blob_sha256 set (%s...) but "
                                "spec_type=%r does not use a standalone draft "
                                "model -- ignored, no --spec-draft-model "
                                "injected; model_tag=%s",
                                manifest.spec_draft_gguf_blob_sha256[:12],
                                _spec_type_for_draft or None, manifest.model_tag,
                            )
                            # See the other call site's comment
                            # for the full rationale.
                            spec_downgrade_log.log_spec_downgrade(
                                model_tag=manifest.model_tag, source="manager_config",
                                component="draft", reason_code="spec_type_mismatch",
                                detail=(
                                    f"spec_draft_gguf_blob_sha256 set but "
                                    f"spec_type={_spec_type_for_draft or None!r} "
                                    "does not use a standalone draft model"
                                ),
                            )
            except FileNotFoundError:
                manifest_found = False
                gguf_path = self.boot.storage.blob_store_path / "missing.gguf"

            # Pre-validate the
            # manifest BEFORE the teardown_idle_holder branch when a warm
            # holder for a DIFFERENT model is at risk. A bogus model_tag
            # with no manifest used to fall into the "different model"
            # path and tear down the warm holder, then the spawn would
            # inevitably hang in LOADING (missing.gguf) and health-check
            # timeout. The warm hold was lost for nothing.
            # Now: if manifest is missing AND an idle holder exists for a
            # DIFFERENT model, bail fast (LOADING -> LOADING_FAIL -> POPPED)
            # WITHOUT touching self._idle_handle. Otherwise (no holder OR
            # same-model holder which we would inherit anyway) fall through
            # to the legacy missing.gguf -> spawn-then-LOADING_FAIL path so
            # existing tests that rely on the manifest-missing tolerance
            # continue to work.
            holder_at_risk = (
                not manifest_found
                and self._idle_handle is not None
                and self._idle_model_tag != slot.model_tag
            )
            if holder_at_risk:
                transition(slot, SlotState.LOADING)
                await self._audit_async(slot, "stage_to_loading")
                transition(slot, SlotState.LOADING_FAIL)
                await self._audit_async(slot, "manifest_not_found")
                transition(slot, SlotState.POPPED)
                _mfn_conn = open_state_db(self.boot.storage.state_db_path)
                try:
                    mark_slot_ended(
                        _mfn_conn, slot.slot_id, "manifest_not_found",
                    )
                finally:
                    _mfn_conn.close()
                self._fail_completion_future(
                    slot,
                    RuntimeError(
                        f"model_tag {slot.model_tag!r} has no manifest "
                        f"(idle holder for {self._idle_model_tag!r} preserved)"
                    ),
                )
                return

            # P1a: allocate the listen port from the resident registry instead
            # of hard-coding default_port_base. At MAX_PARALLEL_SIDECARS == 1
            # this returns default_port_base (11500) verbatim -- behaviour is
            # byte-for-byte identical to the deployed manager; the indirection
            # is what lets a Phase-1 second sidecar land on the next free port.
            port = self._alloc_port()

            # STAGED → LOADING
            transition(slot, SlotState.LOADING)
            # Stamp the field so the consumer in the finally block
            # has a real value to read. Only this call site (not the
            # manifest-not-found bail above) is the real load path.
            slot.started_loading_at = time.monotonic()
            await self._audit_async(slot, "stage_to_loading")

            # Warm-inherit path. If the previous slot left
            # a warm sidecar holding the same model_tag and the idle
            # window has not expired, reuse the handle and skip spawn +
            # health-wait (sidecar is already healthy by construction).
            # Capture idle_handle in a local var BEFORE the check to
            # avoid TOCTOU — another coroutine could change _idle_handle
            # between the check and the warm_inherit block.
            _idle_h = self._idle_handle
            _idle_mt = self._idle_model_tag
            _idle_exp = self._idle_expires_at
            _idle_client_meta = self._idle_client_meta
            _idle_tid = self._idle_thread_id
            # RC (stuck-handle root fix) Bug A: NEVER warm-inherit a DEAD idle handle.
            # If the idle-hot holder's llama-server died (silent crash / OOM / premature
            # unload), reusing it strands every request on a dead pid with no re-spawn
            # (observed: `active_handle_pid=X alive=False idle_match=True` looping for 10+
            # min, main never reloads). Gating on is_alive() drops a dead handle into the
            # `else` branch, which tears down the dead holder (_teardown_idle_holder: clears
            # + skips flush on a dead pid) and does a safety-checked FRESH spawn = recovery.
            warm_inherit = (
                _idle_h is not None
                and _idle_mt == slot.model_tag
                and _idle_exp is not None
                and time.monotonic() < _idle_exp
                and _idle_h.is_alive()
            )
            if (
                not warm_inherit
                and _idle_h is not None
                and _idle_mt == slot.model_tag
                and _idle_exp is not None
                and time.monotonic() < _idle_exp
                and not _idle_h.is_alive()
            ):
                log.warning(
                    "Idle-hot holder DEAD (pid=%s, model=%s) within window — clearing + "
                    "cold-spawning fresh (RC stuck-handle Bug A dead-handle recovery)",
                    getattr(_idle_h, "pid", None), slot.model_tag)
            if warm_inherit:
                handle = _idle_h
                self._clear_idle_holder()
                slot.port = handle.port
                slot.pid = handle.pid
                # DURABLE IDENTITY: record (pid, port, starttime) so
                # boot_orphan_reaper can prove ownership after a crash and
                # reject PID reuse. Best-effort.
                self._record_engine_identity(slot)
                self._set_active_handle(handle)
                self._bump_spawn_seq()  # live-monitor: mark new active handle + mirror to active resident (sole writer = worker_loop)
                await self._audit_async(slot, "idle_hot_inherit")
                # Restore identity fields alongside thread_id (keeps session_id and the
                # KV cache bin aligned). Restore the
                # idle-holder identity ONLY when the INCOMING request is the SAME session,
                # or is a genuine same-thread continuation that lost its session_id (a
                # tool-call re-cue). A DIFFERENT, unrelated session-less caller that merely
                # happens to warm-inherit this idle sidecar (curator/sub-agent <-> main
                # handoff) MUST keep ITS OWN complete client_meta (Slot.new already set it)
                # — adopting swaps session_id/role onto the wrong identity => wrong KV-bin
                # ownership (main returns after a sub-agent and can't find its own bin:
                # "reloaded but no context") AND a per-role save-gate misreads the role.
                # thread_id already stays the incoming's, so ONLY client_meta was inconsistent.
                #
                # A brand-new caller and a genuine re-cue are BOTH session-less at this
                # point, so absence alone cannot distinguish them (an OR clause in this
                # narrowing predicate can only broaden what it admits). A re-cue reuses the
                # SAME thread — that positive signal is what actually distinguishes it.
                #
                # Only identity/classification fields transfer, never request-scoped ones:
                # messages never lived here (the request-scoped outbound source is
                # slot.context, untouched by this block), and turn0_meta/save_kv/
                # context_size/ip describe THIS request, not the caller's identity — ip in
                # particular must not transfer, or a session-less caller would inherit the
                # idle holder's origin as if it were its own.
                if _idle_client_meta:
                    _inc_cm = slot.client_meta if isinstance(slot.client_meta, dict) else {}
                    _inc_sid = _inc_cm.get("session_id")
                    _idle_sid = (_idle_client_meta.get("session_id")
                                 if isinstance(_idle_client_meta, dict) else None)
                    _is_recue = (
                        not _inc_sid
                        and bool(slot.thread_id)
                        and slot.thread_id == _idle_tid
                    )
                    _is_same_session = _inc_sid is not None and _inc_sid == _idle_sid
                    if isinstance(_idle_client_meta, dict) and (_is_recue or _is_same_session):
                        # Guard against label-copy-without-messages poisoning:
                        # the labels are copied but the messages never are.
                        # _is_recue/_is_same_session only prove
                        # the incoming request shares the idle holder's
                        # thread/session — NOT that it is the SAME ROLE. A
                        # curator can legitimately share session_id with its
                        # parent main session (spawned "for" that session),
                        # or reach the re-cue branch via the same
                        # lost-session_id mechanism a genuine tool-call
                        # continuation uses. Blindly copying role/is_main/
                        # is_curator/... onto an incoming request that
                        # ALREADY carries its own distinct classification
                        # overwrites a correct label with a wrong one — this
                        # block's own docstring above says it exists to
                        # prevent exactly that ("adopting swaps session_id/
                        # role onto the wrong identity"), so this guard
                        # checks the incoming's own classification
                        # before overwriting it. "messages" is never in the
                        # copied-field list (never was — request-scoped, not
                        # identity), so a curator's own real transcript
                        # always survives untouched under whatever labels
                        # land on it — meaning a poisoned copy here produces
                        # a client_meta with BORROWED main labels over the
                        # curator's OWN real messages, which the
                        # last_main_client_meta refresh (elsewhere in this
                        # module, gated on _disp_role resolving to None/"main")
                        # would then trust as main's own — mislabeled
                        # transcript captured under main's identity, exactly
                        # the poisoning this guard exists to prevent.
                        from turbohaul.kv_classify import _class_from_label
                        _idle_class = _class_from_label(_idle_client_meta)
                        _inc_class = _class_from_label(_inc_cm)
                        _inc_own_role = _inc_cm.get("role") if _inc_class is None else None
                        _inc_has_own_identity = _inc_class is not None or bool(_inc_own_role)
                        if _inc_has_own_identity and _inc_class != _idle_class:
                            log.info(
                                "Idle-hot warm-inherit: REFUSED identity-label copy "
                                "(incoming already classified as %s, idle holder is %s, "
                                "session_id=%s) — no cross-role clobber",
                                _inc_class or _inc_own_role, _idle_class,
                                _idle_sid if _idle_sid is not None else "N/A",
                            )
                        else:
                            for _k in (
                                "session_id", "role", "is_main", "is_sub_agent",
                                "is_curator", "is_compression",
                            ):
                                if _k in _idle_client_meta:
                                    _inc_cm[_k] = _idle_client_meta[_k]
                            slot.client_meta = _inc_cm
                            log.debug(
                                "Idle-hot warm-inherit: restored identity fields (session_id=%s) "
                                "via %s", _idle_sid if _idle_sid is not None else "N/A",
                                "re-cue" if _is_recue else "same-session",
                            )
                    else:
                        log.info(
                            "Idle-hot warm-inherit: KEPT incoming client_meta (incoming "
                            "session_id=%s != idle-holder session_id=%s, thread_id=%s != "
                            "idle thread_id=%s) — no cross-caller identity clobber "
                            "(identity-restore guard)", _inc_sid, _idle_sid, slot.thread_id, _idle_tid)
                # Skip spawn + health wait; jump straight to LOADING -> ACTIVE.
                healthy = True
            else:
                # Different model OR no idle holder. If a stale holder
                # exists for a different model, tear it down before
                # spawning new -- immediate switch.
                if self._idle_handle is not None:
                    await self._teardown_idle_holder("model_swap")
                # Safety guardrails: pre-spawn host checks
                # (VRAM headroom + RAM + CPU load + IO wait). Refuse here
                # rather than spawning into an OOM / IO-stuck host.
                if self.runtime.queue.safety_enabled:
                    manifest_vram = 0
                    manifest_ctx = 0
                    manifest_gguf_bytes = 0
                    manifest_expert_mib = 0
                    manifest_kv_quant = "f16"
                    manifest_kv_quant_v = "f16"
                    manifest_no_kv_offload = False
                    manifest_parallel = 1
                    manifest_split_mode = "layer"
                    manifest_main_gpu = 0
                    manifest_cpu_moe = False
                    manifest_hybrid_kv = 1.0
                    manifest_attn_dims = None
                    manifest_kv_bpt = None
                    manifest_tensor_split = None
                    try:
                        m_for_vram = read_manifest(
                            self.boot.storage.manifests_path,
                            slot.model_tag,
                        )
                        manifest_vram = m_for_vram.expected_vram_bytes or 0
                        manifest_tensor_split = m_for_vram.llama_server_flags.get(
                            "tensor_split"
                        )
                        manifest_gguf_bytes = m_for_vram.gguf_size_bytes or 0
                        # ctx_size: prefer llama_server_flags.ctx_size (what
                        # actually gets passed to llama-server CLI); fall
                        # back to manifest.context_size.
                        manifest_ctx = (
                            m_for_vram.llama_server_flags.get("ctx_size")
                            or m_for_vram.context_size
                            or 0
                        )
                        # KV quant: K half scaled by cache_type_k, V half by
                        # cache_type_v (V used to be ignored, so a
                        # K=f16 + V=turbo3 config was over-counted as full-f16).
                        manifest_kv_quant = (
                            m_for_vram.llama_server_flags.get("cache_type_k")
                            or "f16"
                        )
                        manifest_kv_quant_v = (
                            m_for_vram.llama_server_flags.get("cache_type_v")
                            or manifest_kv_quant
                        )
                        # --no-kv-offload: KV in host RAM, so the kv_cache_fit
                        # gate must NOT count it against VRAM (it re-checks RAM).
                        manifest_no_kv_offload = bool(
                            m_for_vram.llama_server_flags.get("no_kv_offload", False)
                        )
                        # parallel: extra concurrent llama.cpp slots add a flat
                        # per-slot compute floor to the VRAM gate (safety.py).
                        manifest_parallel = int(
                            m_for_vram.llama_server_flags.get("parallel", 1) or 1
                        )
                        # GPU placement (per-model manifest flags): split_mode
                        # drives the VRAM gate's aggregate-vs-single-card budget;
                        # main_gpu picks the card for split_mode:none. Absent ->
                        # "layer" = llama.cpp default (aggregate across all GPUs).
                        manifest_split_mode = str(
                            m_for_vram.llama_server_flags.get("split_mode", "layer")
                            or "layer"
                        )
                        manifest_main_gpu = int(
                            m_for_vram.llama_server_flags.get("main_gpu", 0) or 0
                        )
                        manifest_is_mlx = m_for_vram.is_mlx()
                        # cpu_moe / n_cpu_moe offload experts to RAM -> the closed-form
                        # body=gguf over-counts; the cpu-moe gate branch trusts the
                        # manifest's measured expected_vram for those configs (parity
                        # with the cap>=2 driver path).
                        manifest_cpu_moe = bool(
                            m_for_vram.llama_server_flags.get("cpu_moe")
                            or int(
                                m_for_vram.llama_server_flags.get("n_cpu_moe", 0) or 0
                            )
                            > 0
                        )
                        # hybrid_kv_ratio: manifest model property for hybrid models
                        # (same field + validator as the other gate sites;
                        # default 1.0 = byte-identical to today).
                        manifest_hybrid_kv = m_for_vram.hybrid_kv_ratio
                        self._announce_hybrid_kv(
                            slot.model_tag, manifest_hybrid_kv, "spawn safety gate"
                        )
                        # Dimension-aware KV dims (cached) + override.
                        manifest_attn_dims = self._attn_kv_dims_for(m_for_vram)
                        manifest_kv_bpt = getattr(
                            m_for_vram, "kv_bytes_per_token", None
                        )
                        # Exact offloaded MoE expert bytes (0 if not
                        # configured or underiveable -- gate no-ops then).
                        manifest_expert_mib = self._expert_offloaded_mib_for(
                            m_for_vram
                        )
                    except FileNotFoundError:
                        manifest_vram = 0
                    gates = await asyncio.to_thread(all_safety_gates,
                        min_free_ram_mib=self.runtime.queue.safety_min_free_ram_mib,
                        min_free_vram_mib=self.runtime.queue.safety_min_free_vram_mib,
                        max_cpu_busy_percent=self.runtime.queue.safety_max_cpu_busy_percent,
                        max_iowait_percent=self.runtime.queue.safety_max_iowait_percent,
                        manifest_expected_vram_bytes=manifest_vram,
                        cpu_util_sample_window_s=self.runtime.queue.safety_cpu_util_sample_window_s,
                        iowait_sample_window_s=self.runtime.queue.safety_iowait_sample_window_s,
                        ctx_size=manifest_ctx,
                        gguf_size_bytes=manifest_gguf_bytes,
                        kv_cache_quant=manifest_kv_quant,
                        kv_cache_quant_v=manifest_kv_quant_v,
                        no_kv_offload=manifest_no_kv_offload,
                        parallel=manifest_parallel,
                        split_mode=manifest_split_mode,
                        main_gpu=manifest_main_gpu,
                        cpu_moe_offload=manifest_cpu_moe,
                        hybrid_kv_ratio=manifest_hybrid_kv,
                        attn_dims=manifest_attn_dims,
                        kv_bytes_per_token=manifest_kv_bpt,
                        expert_offloaded_mib=manifest_expert_mib,
                        # Same-card occupied-vram budget as
                        # the spawn gate. exclude_model_tag: this cap<=1 path
                        # never inserts a self-entry into self._residents
                        # before this point (confirmed: the only insertion
                        # site is _reserve_and_start_locked, the cap>=2
                        # dispatcher path) so this is a no-op today -- passed
                        # anyway for the same correctness reason as the
                        # spawn-gate call site, not because of a known bug here.
                        occupied_vram_mib=self._occupied_vram_mib(
                            main_gpu=manifest_main_gpu,
                            exclude_model_tag=slot.model_tag,
                        ),
                        tensor_split=manifest_tensor_split,
                    )
                    failed = [g for g in gates if not g.ok]
                    if failed:
                        # Build a single error message + emit audit detail.
                        detail = "; ".join(
                            f"{g.name}: {g.detail}" for g in failed
                        )
                        log.warning(
                            "safety gates refused spawn for slot %s: %s",
                            slot.slot_id, detail,
                        )
                        transition(slot, SlotState.LOADING_FAIL)
                        await self._audit_async(slot, "safety_gate_refused")
                        await self._audit_event_only_async(
                            slot.slot_id,
                            "safety_gate_detail",
                            {"failed": [
                                {"name": g.name, "detail": g.detail}
                                for g in failed
                            ]},
                        )
                        transition(slot, SlotState.POPPED)
                        # No sidecar spawned; _teardown is a no-op + audit-only.
                        # Just mark slot ended + fail caller future.
                        _sg_conn = open_state_db(
                            self.boot.storage.state_db_path
                        )
                        try:
                            mark_slot_ended(
                                _sg_conn, slot.slot_id, "safety_gate_refused",
                            )
                        finally:
                            _sg_conn.close()
                        self._fail_completion_future(
                            slot,
                            RuntimeError(
                                f"safety gates refused spawn: {detail}",
                            ),
                        )
                        return
                handle: SidecarHandle
                if manifest_is_mlx:
                    handle = mlx_spawn(
                        port,
                        slot.model_tag,
                        manifest.model_repo if manifest_found else "",
                        manifest.model_path if manifest_found else "",
                        manifest.mlx_server_flags if manifest_found else {},
                        python_binary=self.boot.runtime.mlx_python_binary,
                    )
                else:
                    handle = self._spawn(
                        self.boot.runtime.llama_server_binary,
                        gguf_path,
                        port,
                        slot.model_tag,
                        argv,
                        binary_fd=self._binary_fd,
                    )
                # A fresh sidecar on this port invalidates
                # any earlier probe-recorded think-free count for it (the ordinary
                # cold-spawn path) — drop the stale entry per the register's
                # documented invariant.
                self._clean_prefill_tokens.pop(handle.port, None)
                self._poisoned_chain_fps.pop(handle.port, None)  # fresh engine (ordinary cold-spawn path)
                slot.port = handle.port
                slot.pid = handle.pid
                # DURABLE IDENTITY: this is the ORDINARY cold-spawn path — the
                # only one taken at max_parallel_sidecars=1. Without this the
                # identity table stays empty on a default deployment, and the
                # reaper (which refuses to kill anything it cannot prove it
                # owns) reaps nothing at all. The two other engine-creating
                # paths record at their own spawn; the remaining pid
                # assignments attach an ALREADY-recorded handle to a second
                # slot and must not record again.
                self._record_engine_identity(slot)
                self._set_active_handle(handle)
                self._bump_spawn_seq()  # live-monitor: mark new active handle + mirror to active resident (sole writer = worker_loop)
                # LOADING → ACTIVE (or LOADING_FAIL → POPPED)
                healthy = await self._wait_healthy(
                    port, self.runtime.queue.loading_health_timeout_s,
                    is_alive=handle.is_alive,
                )
                # Load verification: verify the MODEL actually loaded after the
                # (swap/cold) spawn + emit a LOAD_VERIFY record. Observability ONLY —
                # never alters the decode path (helpers are read-only + never-raise;
                # belt-wrapped anyway). The bounded verify+RETRY loop is the follow-up
                # behavior step once these records show the real failure modes.
                try:
                    _mv = await load_verify_log.verify_model_resident(
                        handle, mlx=manifest_is_mlx
                    )
                    # The identity instrument -- verify_model_resident
                    # above proves *A* model is up (health_200 and n_ctx>0); it can
                    # never say WHICH one. verify_model_identity reads the engine's
                    # OWN answer (GET /props' model_path, falling back to the
                    # engine's own logged "loading model '<path>'" line) and
                    # compares it to gguf_path, the path actually requested.
                    _identity = await load_verify_log.verify_model_identity(
                        handle, gguf_path,
                        engine_log_path=getattr(handle, "engine_log_path", None),
                    )
                    # Engine log check: does the engine's own log for THIS spawn
                    # contain any E-level line (e.g. the CUDA OOM class of error
                    # that silently degraded a load to no-pipeline-parallelism
                    # while everything else still read "ok"). Log-file read
                    # only, no network cost -- runs regardless of `healthy` so a
                    # failed load's own explanation is visible too.
                    _errs = load_verify_log.scan_engine_log_for_errors(
                        getattr(handle, "engine_log_path", None),
                    )
                    # Same file, same read, a second independent
                    # signature (the SPEC_DOWNGRADED tag) -- mirrors how
                    # classify_idle_dead_holder reads its own signature out of
                    # the exact same engine_log_path scan_engine_log_for_errors
                    # already reads. Only logged when a downgrade was actually
                    # found -- this is an event record, not a per-spawn no-op.
                    _spec_dg = spec_downgrade_log.scan_engine_log_for_spec_downgrade(
                        getattr(handle, "engine_log_path", None),
                    )
                    if _spec_dg.get("spec_downgraded"):
                        spec_downgrade_log.log_spec_downgrade(
                            model_tag=slot.model_tag, source="engine_log",
                            arch=_spec_dg.get("arch"),
                            component=_spec_dg.get("component"),
                            reason_code=_spec_dg.get("reason"),
                            detail=_spec_dg.get("detail"),
                        )
                    load_verify_log.log_load_verify(
                        event="model_load", trigger="spawn",
                        model_tag=slot.model_tag, port=port,
                        pid=getattr(handle, "pid", None),
                        process_alive=_mv.get("process_alive"),
                        health_200=_mv.get("health_200") if _mv.get("health_200") is not None else bool(healthy),
                        model_resident=_mv.get("model_resident"),
                        identity_verified=_identity.get("identity_verified"),
                        identity_source=_identity.get("identity_source"),
                        identity_reason=_identity.get("identity_reason"),
                        served_model_path=_identity.get("served_model_path"),
                        expected_model_path=_identity.get("expected_model_path"),
                        retry_count=0,
                        # final_status stays scoped to
                        # EXACTLY what it always measured -- process alive +
                        # /health answered -- unchanged logic, unchanged values.
                        # It is deliberately NOT downgraded by identity_verified
                        # or engine_errors_detected below; those are their OWN
                        # fields precisely so a legitimately health-clean load
                        # (e.g. one that hit a recovered warning) is never made
                        # to read worse than reality, the mirror image of
                        # not relaxing an existing check.
                        final_status="ok" if healthy else "failed",
                        reason=None if healthy else "health-timeout",
                        engine_errors_detected=_errs.get("engine_errors_detected"),
                        engine_error_lines=_errs.get("engine_error_lines"),
                        session_id=(slot.client_meta or {}).get("session_id") if isinstance(slot.client_meta, dict) else None,
                    )
                except Exception:
                    log.debug("LOAD_VERIFY model_load emit failed (best-effort)", exc_info=True)
                # Cold-spawn only: best-effort KV restore after fresh sidecar passes health.
                if healthy:
                    _expected_tokens = await self._restore_slot_kv(port, slot.model_tag, slot)
                    # Record the engine's ACTUAL post-restore n_past
                    # (the manager previously TRUSTED the restore POST 200 — "engine
                    # determines actual n_past" — with no check). expected_tokens is
                    # now the winning bin's OWN saved token count (real, not hardcoded;
                    # None only when no restore was attempted), so kv_restore_ok is a
                    # real actual>=expected comparison, not "did I read a number".
                    try:
                        # Same actual_n_past override as the other
                        # two verify_kv_restored call sites -- see that comment
                        # (manager.py, resident-driver restore site) for the full
                        # rationale. None here (no engine-reported count captured)
                        # falls through to today's GET-based verification unchanged.
                        _actual_n_past = (getattr(self, "_kv_restore_actual_tokens", {}) or {}).pop(port, None)
                        _kv = await load_verify_log.verify_kv_restored(
                            handle, 0, _expected_tokens, actual_n_past=_actual_n_past,
                        )
                        # Derived from the SAME verdict already computed above,
                        # mirroring the model_load site's "ok" if healthy else
                        # "failed" pattern -- True is the only pass; None
                        # (never established) reads as "unverified", not "ok"
                        # (log_load_verify enforces this same rule structurally
                        # too, so a future regression here still can't ship a
                        # passing status alongside a non-True verdict).
                        _kv_restore_ok = _kv.get("kv_restore_ok")
                        load_verify_log.log_load_verify(
                            event="kv_restore", trigger="spawn",
                            model_tag=slot.model_tag, port=port,
                            pid=getattr(handle, "pid", None),
                            # process_alive is the SAME read verify_kv_restored
                            # just took (engine liveness at the instant of the
                            # /slots read), not a hardcoded assumption.
                            # health_200/model_resident have no
                            # kv_restore-path equivalent read of their own -- they
                            # used to be hardcoded True literals here, which reads
                            # as a SECOND independent measurement when it was
                            # really the paired model_load record's own reading,
                            # counted twice. None: genuinely not measured on THIS
                            # record (see the model_load record emitted moments
                            # earlier for that).
                            process_alive=_kv.get("process_alive"), health_200=None, model_resident=None,
                            kv_expected_tokens=_kv.get("kv_expected_tokens"),
                            kv_actual_n_past=_kv.get("kv_actual_n_past"),
                            kv_restore_ok=_kv_restore_ok,
                            restore_attempted=_kv.get("restore_attempted"),
                            kv_expected_reason=_kv.get("kv_expected_reason"),
                            kv_actual_reason=_kv.get("kv_actual_reason"),
                            retry_count=0,
                            final_status=(
                                "ok" if _kv_restore_ok is True
                                else "unverified" if _kv_restore_ok is None
                                else "failed"
                            ),
                            reason=_kv.get("reason"),
                            source=_kv.get("source"),
                            slots_http_status=_kv.get("slots_http_status"),
                            slot_id_found=_kv.get("slot_id_found"),
                            session_id=(slot.client_meta or {}).get("session_id") if isinstance(slot.client_meta, dict) else None,
                        )
                    except Exception:
                        log.debug("LOAD_VERIFY kv_restore emit failed (best-effort)", exc_info=True)
            if not healthy:
                transition(slot, SlotState.LOADING_FAIL)
                await self._audit_async(slot, "loading_fail_health_timeout")
                transition(slot, SlotState.POPPED)
                await self._teardown(slot, "loading-fail-health-timeout")
                self._fail_completion_future(slot, RuntimeError("loading-fail-health-timeout"))
                return

            # Per-model concurrent-dispatch admission cap (Design #1). Pinned on
            # the handle at spawn from the actual --parallel argv, so it is
            # drift-proof vs a fresh manifest read across a warm-inherit reuse
            # cycle. NOTE: the cap is handle.parallel DIRECTLY -- NOT
            # max_parallel_sidecars (that config is the separate multi-PROCESS
            # stub, default 1; clamping to it would disable fan-out entirely).
            # For parallel:1 models this is 1, so the serial path below is taken
            # verbatim and byte-identical to today.
            n_parallel = max(1, getattr(handle, "parallel", 1))

            transition(slot, SlotState.ACTIVE)
            self._mark_slot_active(slot)
            await self._audit_async(slot, "active")
            # Capture anchor's keep_alive intent for grace→idle decision.
            self._set_latest_keep_alive((slot.client_meta or {}).get("keep_alive_s"))

            # Telemetry — slot assign + prefill start
            try:
                self._telemetry.on_slot_assign(slot)
                self._telemetry.on_prefill_start(slot)
            except Exception:
                pass

            # Capture a clean-prefix KV (pre-generation) via a
            # prefill-only probe BEFORE the real request generates, so the next cold
            # restore reuses instead of CLEAR+reprefill. Placed here (after ACTIVE +
            # restore, before the streaming/non-streaming branch) so it fires for BOTH
            # streaming and non-streaming requests on the live _process_slot path. The
            # real request below then warm-reuses this prefill (no double prefill).
            # No-op unless single-series + large ctx + no equal/larger clean bin exists.
            await self._probe_and_save_clean_kv(handle, slot)

            # Branch on streaming mode.
            #
            # Non-streaming (existing): await self._complete_fn(slot, handle) to
            # post chat-completion, set completion_future, advance to GRACE.
            #
            # Streaming: client_meta["stream"] is True AND submit_for_streaming()
            # pre-armed slot.stream_ready_event + slot.stream_done_event. We
            # SKIP _complete_fn (the route owns the httpx streaming connection).
            # Instead: hand the SidecarHandle to the route via slot.stream_handle,
            # signal stream_ready_event so the route can open its httpx.stream(),
            # then BLOCK here on stream_done_event until the route reports the
            # stream has finished (normal close, client disconnect, or error).
            # Slot stays in ACTIVE the entire time so ACTIVE_MATCH cannot promote
            # a second submission against the same sidecar (a design review
            # critical catch — single-slot invariant preserved).
            is_streaming = (
                isinstance(slot.client_meta, dict)
                and bool(slot.client_meta.get("stream", False))
                and slot.stream_ready_event is not None
                and slot.stream_done_event is not None
            )
            # Classifier: the hash chain the engine's warm KV holds after the
            # most recent decode on THIS handle (= that request's prompt + generated
            # <think> turn). Feeds the NO-DOWNGRADE gate before each grace follow-up
            # decode. [] = unknown (fan-out/streaming/noop) -> gate never forces
            # (safe). Local to this anchor cycle = scoped exactly to the warm slot's
            # grace lifetime (lifecycle-accurate; no cross-cycle staleness).
            warm_chain: list[str] = []
            if n_parallel > 1:
                # Design #1: concurrent fan-out. Serve up to n_parallel
                # same-model riders (streaming OR non-streaming) on this ONE
                # shared sidecar, then drain them all before advancing to GRACE.
                # Reached ONLY for parallel:N models; parallel:1 falls to the
                # verbatim serial block below (byte-identical to today).
                await self._fan_out_and_drain(slot, handle, n_parallel)
            elif is_streaming:
                # Hand the sidecar handle to the route, signal ready.
                slot.stream_handle = handle
                slot.stream_ready_event.set()
                # Wait for the route to finish streaming. Stream timeout is
                # bounded — same default as non-streaming complete_fn — but
                # very long in practice (1h+ for slow-thinking models on big
                # context). If the route never signals, worker_loop unblocks
                # via timeout and proceeds to GRACE (slot already drained).
                try:
                    await asyncio.wait_for(
                        slot.stream_done_event.wait(),
                        timeout=_STREAM_TIMEOUT_S,  # 1 hour cap; routes typically signal in seconds
                    )
                except asyncio.CancelledError:
                    self._log_kv_reuse_outcome(slot, handle, wait_state="cancelled")
                    raise
                except asyncio.TimeoutError:
                    log.warning(
                        "streaming slot %s exceeded 3600s waiting for stream_done_event; "
                        "advancing to GRACE anyway",
                        slot.slot_id,
                    )
                    self._log_kv_reuse_outcome(slot, handle, wait_state="timeout")
                else:
                    _forced = slot.stream_done_forced_reason
                    self._log_kv_reuse_outcome(
                        slot, handle,
                        wait_state="forced" if _forced else "completed",
                        reason=_forced,
                    )
                # Resolve the completion_future so any caller awaiting the
                # slot (e.g. tests or programmatic await) is unblocked.
                if (
                    slot.completion_future is not None
                    and not slot.completion_future.done()
                ):
                    slot.completion_future.set_result({"_streamed": True})
                # The route stashed the streamed generated text on the slot
                # before signaling done -> record what the engine's warm KV now holds
                # (anchor prompt + generated <think> turn) for the first grace
                # follow-up's no-downgrade gate. Same as the non-streaming anchor.
                warm_chain = self._engine_view_chain(slot, None)
                # Shadow byte-match self-check (DORMANT, obs-only): stash this
                # streamed anchor turn's think-free assistant hash for next-turn compare.
                self._record_shadow_bytematch_probe(slot, None)
                # Shadow-reprefill (SAVE-side; INERT unless
                # TURBOHAUL_SHADOW_REPREFILL). Fired AFTER set_result above -> zero
                # added response TTFT. Persists the think-free end-of-turn-N state
                # under a DISTINCT .shadow bin; restore path UNCHANGED (PL's step).
                await self._shadow_reprefill_and_save(handle, slot, None)
            else:
                # Non-streaming path (existing behaviour, unchanged).
                # Completion (the default is a noop; the httpx forward replaces it when wired)
                result = await self._complete_fn(slot, handle)
                if slot.completion_future is not None and not slot.completion_future.done():
                    slot.completion_future.set_result(result)
                # Completion-cache WRITE site. Cache this non-streaming result +
                # resolve the leader's single-flight future so a byte-identical retry
                # replays instantly. No-op unless the slot is a cache leader (its
                # submit_and_wait stashed completion_cache_key). Runs on the single
                # worker_loop, between set_result and the next await, so it stays
                # atomic vs the leader's submit_and_wait finally (no double-resolve).
                self._completion_cache_store(slot, result)
                # Record what the engine's warm KV now holds (anchor prompt +
                # generated <think> turn) so the first grace follow-up's no-downgrade
                # gate can compare against it.
                warm_chain = self._engine_view_chain(slot, result)
                # Shadow byte-match self-check (DORMANT, obs-only): stash this
                # non-streamed anchor turn's think-free assistant hash for next-turn compare.
                self._record_shadow_bytematch_probe(slot, result)
                # Shadow-reprefill (SAVE-side; INERT unless
                # TURBOHAUL_SHADOW_REPREFILL). Fired AFTER set_result above -> zero
                # added response TTFT. Persists the think-free end-of-turn-N state
                # under a DISTINCT .shadow bin; restore path UNCHANGED (PL's step).
                await self._shadow_reprefill_and_save(handle, slot, result)

            # Drain-before-swap hard gate (Design #1): every fan-out rider must
            # have finished before the anchor advances to GRACE / the sidecar is
            # torn down. _fan_out_and_drain returns only when self._inflight is
            # empty; for parallel:1 it is never populated, so this is a no-op.
            assert not self._inflight, (
                "Design #1 invariant: riders must drain before ACTIVE->GRACE"
            )
            # A completed serve proves the engine is healthy
            # again — drop the ENGINE STALLED banner (replace-only; sole writer =
            # worker_loop, same task as the strike site, so no write-write race).
            if getattr(self, "_engine_stall", None) is not None:
                log.info("ENGINE STALL cleared — serve completed OK (slot=%s thread=%s)",
                         slot.slot_id, (slot.thread_id or "?")[:40])
                self._engine_stall = None
            # ACTIVE → GRACE
            transition(slot, SlotState.GRACE)
            slot.grace_started_at = time.monotonic()
            self.grace.start(slot.thread_id, slot.model_tag)
            await self._audit_async(slot, "grace_enter")

            # Telemetry — completion
            try:
                self._telemetry.on_completion(slot, "grace_enter")
            except Exception:
                pass

            # Wait for grace window OR promote a matched staging slot via
            # ACTIVE_MATCH (warm-slot reuse). Per the slot FSM; this transition
            # cascades same-(thread_id, model_tag) follow-up requests through
            # the warm llama-server without re-spawn.
            # This transition is fully wired.
            deadline = time.monotonic() + self.runtime.queue.grace_seconds
            # The identity later handed to idle-hot-enter (below)
            # must be whichever Slot's content is ACTUALLY live in the
            # engine's KV right now AND is main-class -- the anchor `slot`
            # until a main-class `matched` completes, the last such `matched`
            # after that. `slot` itself is deliberately never reassigned (it
            # remains "the GRACE driver" for teardown bookkeeping, see the
            # note below), so a separate tip pointer is required:
            # _grace_tip holds the anchor ⟺ no MAIN-CLASS follow-up on this
            # thread has completed yet this grace cycle; it holds the last
            # completed main-class `matched` otherwise. Updated only on the
            # success path AND only when main-class (search "_grace_tip =
            # matched" below) -- a drifted/cancelled/failed follow-up never
            # actually landed content on the engine, and a disposable
            # (curator/sub-agent/compression) follow-up CAN share this exact
            # thread_id (pop_matched_thread has no role awareness) but must
            # never overwrite the tip -- either would corrupt the parked
            # identity, the second case turning a stale-but-present main bin
            # into no bin at all.
            _grace_tip = slot
            while time.monotonic() < deadline and not self._stop_event.is_set():
                # Fast Lane must
                # outrank the grace period. Checked at the TOP of the
                # iteration, BEFORE pop_matched_thread -- deliberately NOT
                # placed alongside the starved_other_model check further
                # down, which only runs on the `matched is None`
                # fallthrough (after `continue`). A same-thread follow-up
                # would always win the race if this lived there, so the
                # rule would silently never fire on the one iteration it
                # exists for. Do not "tidy" this next to the other check
                # without re-reading this comment.
                if (
                    self._fastlane_pop_kwarg() is not None
                    and await self.queue.has_strictly_higher_priority_waiting(slot)
                ):
                    await self._audit_async(slot, "grace_fastlane_breakout")
                    log.info(
                        "grace_fastlane_breakout slot=%s model=%s",
                        slot.slot_id,
                        slot.model_tag,
                    )
                    break
                # Atomic find + remove in one lock acquire
                matched = await self.queue.pop_matched_thread(
                    slot.thread_id, slot.model_tag
                )
                if matched is not None:
                    matched.port = handle.port
                    matched.pid = handle.pid
                    self._set_active_slot(matched)
                    # Release the staging_arrival claim for the matched
                    # follow-up (same fix as Loop A). pop_matched_thread dequeues
                    # from the queue but the claim registered at staging-arrival
                    # is never released here.
                    async with self._registry_lock:
                        self._release_fastlane_claim_locked(matched, "admitted")
                    # State-drift guard. If matched.state
                    # drifted between find_matched_thread + here (concurrent
                    # reconcile, retry path, etc.), transition raises
                    # InvalidTransition which would crash worker_loop. Wrap
                    # the promotion + park-on-drift instead of propagate.
                    try:
                        transition(matched, SlotState.ACTIVE_MATCH)
                        await self._audit_async(matched, "active_match_promoted")
                        transition(matched, SlotState.ACTIVE)
                        # Each matched-follow-up's keep_alive overrides
                        # the anchor's for the next grace→idle calculation. Mirrors
                        # Ollama "timer resets on request receipt" rule.
                        # An omission must not cancel an explicit intent
                        # (last-EXPLICIT-writer-wins) -- a client's per-turn
                        # background fork can omit keep_alive and race the main
                        # turn.
                        ka = (matched.client_meta or {}).get("keep_alive_s")
                        if ka is not None:
                            self._set_latest_keep_alive(ka)
                    except InvalidTransition as drift_err:
                        log.warning(
                            "active_match state drift: slot %s in %s — terminal-park; %s",
                            matched.slot_id, matched.state.value, drift_err,
                        )
                        self._fail_completion_future(matched, drift_err)
                        await self._force_cold(
                            matched,
                            f"active_match_state_drift:{matched.state.value}",
                        )
                        self._set_active_slot(slot)
                        continue
                    self._mark_slot_active(matched)
                    completed_ok = True
                    # Round 8 fix: streaming-path warm-reuse. When a streaming submit lands on an
                    # already-active matched slot, the HTTP route owns the upstream connection via
                    # stream_handle. Worker MUST NOT call _complete_fn (would open a 2nd sidecar
                    # connection and violate the single-slot invariant). Hand
                    # off via stream_ready_event and block on stream_done_event until route drains.
                    # Prior bug: this branch unconditionally called _complete_fn → matched slot's
                    # stream_ready_event was never set → route's SLOT_READY_TIMEOUT_S fired at 600s
                    # every turn ≥ 2 of an AI harness multi-tool-call agent loop.
                    matched_is_streaming = bool(
                        isinstance(matched.client_meta, dict)
                        and matched.client_meta.get("stream", False)
                    )
                    try:
                        if matched_is_streaming:
                            # Events are armed in submit() before
                            # enqueue, so they SHOULD always exist here. This
                            # defensive guard handles the never-hit case where
                            # they are somehow still None (e.g. non-streaming
                            # submit that set stream flag in client_meta). Fail
                            # cleanly WITHOUT opening a 2nd sidecar connection.
                            if (
                                matched.stream_ready_event is None
                                or matched.stream_done_event is None
                            ):
                                log.warning(
                                    "active_match streaming slot %s events None "
                                    "(should not happen) — failing promotion cleanly",
                                    matched.slot_id,
                                )
                                self._fail_completion_future(
                                    matched,
                                    RuntimeError("streaming events not armed"),
                                )
                                continue
                            # THE STREAMING warm grace follow-up.
                            # The engine's KV holds the anchor's just-generated <think>
                            # turn (warm_chain); the incoming user turn is think-
                            # stripped. Force-restore the pinned clean bin BEFORE we
                            # signal the route to open its stream, so the engine's next
                            # get_common_prefix runs against the clean prefix (strict
                            # extension, no CLEAR). Same no-downgrade gate + safe-degrade
                            # as the non-streaming path.
                            # Log-only divergence capture on WARM streaming path.
                            inc_div_chain = getattr(matched, "admission_hash_chain", []) or []
                            inc_div_msg = (getattr(matched, "client_meta", None) or {}).get("messages") or []
                            self._log_serve_divergence(matched, inc_div_chain, inc_div_msg, handle.port)
                            # Durable manager: reload-before-serve on WARM streaming path.
                            # When TURBOHAUL_DURABLE_RING=ON, if the physically-resident (role,session)
                            # does NOT match the incoming request's (role,session), RELOAD the matching
                            # ring state so engine residency matches the request head. THEN proceed with
                            # existing warm path (_maybe_force_clean_restore). Fires ONLY on explicit
                            # residency mismatch (old_tag SET and != ring_key); old_tag=None -> skip (safe).
                            # ORDER: read old_tag -> decide/do reload -> THEN advance tag = current request's key
                            if _durable_ring_enabled():
                                inc_chain_stream = getattr(matched, "admission_hash_chain", []) or []
                                inc_messages_stream = (getattr(matched, "client_meta", None) or {}).get("messages") or []
                                reloaded, ring_key = await self._reload_matching_state_before_serve(
                                    handle.port, matched.model_tag, matched, inc_chain_stream, inc_messages_stream
                                )
                                if reloaded:
                                    log.info("DURABLE_RING warm reload: streaming path reloaded key=%s before _maybe_force_clean_restore", ring_key)
                                # Advance resident tag to current request's key (regardless of reload)
                                # so subsequent requests see this as the resident
                                if ring_key:
                                    # multi-instance: attributes to instance-0; resident_state_tag is INERT observe-only
                                    resident = self._residents.get(matched.model_tag)
                                    if resident:
                                        resident.resident_state_tag = ring_key
                            await self._maybe_force_clean_restore(
                                handle.port, matched.model_tag, matched, warm_chain,
                            )
                            # Scale-up: the clean bin must keep growing with the conversation, so
                            # re-save/extend the clean bin on the per-turn WARM
                            # path. Keep-warm (the configured window
                            # `QueueConfig.idle_hot_load_seconds`, not a constant)
                            # removed the eviction saves the clean re-save used to ride, so the bin
                            # stopped growing while the incoming context grew (a forced restore then
                            # reprocessed a growing tail and got slower
                            # over time). Decouple it: fire the same pre-generation
                            # clean probe as the _process_slot path
                            # (2913) so the clean bin grows with the conversation; the
                            # existing throttle bounds the actual re-save to every
                            # LAGREDUCER_MIN_GROWTH_TURNS. Pre-stream so the decode warm-
                            # reuses the probe's prefill (no double prefill).
                            await self._probe_and_save_clean_kv(handle, matched)
                            matched.stream_handle = handle
                            matched.stream_ready_event.set()
                            try:
                                await asyncio.wait_for(
                                    matched.stream_done_event.wait(),
                                    timeout=_STREAM_TIMEOUT_S,
                                )
                            except asyncio.TimeoutError:
                                log.warning(
                                    "active_match streaming slot %s exceeded 3600s waiting for stream_done_event",
                                    matched.slot_id,
                                )
                                self._log_kv_reuse_outcome(matched, handle, wait_state="timeout")
                            else:
                                _forced = matched.stream_done_forced_reason
                                self._log_kv_reuse_outcome(
                                    matched, handle,
                                    wait_state="forced" if _forced else "completed",
                                    reason=_forced,
                                )
                            if matched.completion_future is not None and not matched.completion_future.done():
                                matched.completion_future.set_result({"_streamed": True})
                            # Refresh warm_chain from the route-stashed streamed
                            # text (prompt + generated <think> turn) for the NEXT grace
                            # follow-up's gate. [] if the route couldn't reconstruct it
                            # (parse-miss/tool-call) -> next gate safe-degrades.
                            warm_chain = self._engine_view_chain(matched, None)
                            # Shadow byte-match self-check (DORMANT, obs-only).
                            self._record_shadow_bytematch_probe(matched, None)
                            # Shadow-reprefill (SAVE-side; INERT
                            # unless TURBOHAUL_SHADOW_REPREFILL). AFTER set_result ->
                            # zero added TTFT; DISTINCT .shadow bin; restore UNCHANGED.
                            await self._shadow_reprefill_and_save(handle, matched, None)
                        else:
                            # Classifier: this is THE warm grace follow-up. The
                            # engine's KV holds the anchor's just-generated <think>
                            # turn (warm_chain); the incoming user turn is think-
                            # stripped. Force-restore the pinned clean bin BEFORE the
                            # decode when (and only when) the no-downgrade gate says
                            # it improves reuse — so get_common_prefix runs against
                            # the clean prefix (strict extension, no CLEAR).
                            # Log-only divergence capture on WARM non-streaming path.
                            inc_div_chain = getattr(matched, "admission_hash_chain", []) or []
                            inc_div_msg = (getattr(matched, "client_meta", None) or {}).get("messages") or []
                            self._log_serve_divergence(matched, inc_div_chain, inc_div_msg, handle.port)
                            # Durable manager: reload-before-serve on WARM non-streaming path.
                            # When TURBOHAUL_DURABLE_RING=ON, if the physically-resident (role,session)
                            # does NOT match the incoming request's (role,session), RELOAD the matching
                            # ring state so engine residency matches the request head. THEN proceed with
                            # existing warm path (_maybe_force_clean_restore). Fires ONLY on explicit
                            # residency mismatch (old_tag SET and != ring_key); old_tag=None -> skip (safe).
                            # ORDER: read old_tag -> decide/do reload -> THEN advance tag = current request's key
                            if _durable_ring_enabled():
                                inc_chain_nonstream = getattr(matched, "admission_hash_chain", []) or []
                                inc_messages_nonstream = (getattr(matched, "client_meta", None) or {}).get("messages") or []
                                reloaded, ring_key = await self._reload_matching_state_before_serve(
                                    handle.port, matched.model_tag, matched, inc_chain_nonstream, inc_messages_nonstream
                                )
                                if reloaded:
                                    log.info("DURABLE_RING warm reload: non-streaming path reloaded key=%s before _maybe_force_clean_restore", ring_key)
                                # Advance resident tag to current request's key (regardless of reload)
                                # so subsequent requests see this as the resident
                                if ring_key:
                                    # multi-instance: attributes to instance-0; resident_state_tag is INERT observe-only
                                    resident = self._residents.get(matched.model_tag)
                                    if resident:
                                        resident.resident_state_tag = ring_key
                            await self._maybe_force_clean_restore(
                                handle.port, matched.model_tag, matched, warm_chain,
                            )
                            # Re-save/extend the clean bin on the
                            # per-turn warm path (see streaming site above for rationale).
                            # Pre-decode so _complete_fn warm-reuses the probe's prefill.
                            await self._probe_and_save_clean_kv(handle, matched)
                            result2 = await self._complete_fn(matched, handle)
                            if (
                                matched.completion_future is not None
                                and not matched.completion_future.done()
                            ):
                                matched.completion_future.set_result(result2)
                            # Completion-cache WRITE site for the warm grace
                            # follow-up (its own submit_and_wait was the leader for
                            # this turn's key) — a follow-up turn that times out then
                            # retries also replays instantly. Same guard/atomicity as
                            # the anchor WRITE above.
                            self._completion_cache_store(matched, result2)
                            # Refresh warm_chain to what the engine now holds
                            # after THIS follow-up's decode (its prompt + generated
                            # <think> turn), for the next grace follow-up's gate.
                            warm_chain = self._engine_view_chain(matched, result2)
                            # Shadow byte-match self-check (DORMANT, obs-only).
                            self._record_shadow_bytematch_probe(matched, result2)
                            # Shadow-reprefill (SAVE-side; INERT
                            # unless TURBOHAUL_SHADOW_REPREFILL). AFTER set_result ->
                            # zero added TTFT; DISTINCT .shadow bin; restore UNCHANGED.
                            await self._shadow_reprefill_and_save(handle, matched, result2)
                    except asyncio.CancelledError:
                        # Cooperatively unwind route's blocking httpx call
                        # by signaling stream_done before terminal-park (avoids zombie
                        # route + dead slot drift).
                        if (
                            matched_is_streaming
                            and matched.stream_done_event is not None
                            and not matched.stream_done_event.is_set()
                        ):
                            matched.stream_done_forced_reason = "active_match_cancelled"
                            matched.stream_done_event.set()
                            self._log_kv_reuse_outcome(
                                matched, handle, wait_state="cancelled")
                        # Cancellation mid-ACTIVE_MATCH
                        # must terminal-park the matched slot so it does not
                        # rot as a zombie ACTIVE row in state.sqlite, then
                        # re-raise so worker_loop's teardown runs cleanly.
                        self._fail_completion_future(
                            matched,
                            asyncio.CancelledError("shutdown during active_match"),
                        )
                        try:
                            transition(matched, SlotState.POPPED)
                        except InvalidTransition:
                            pass
                        await self._audit_async(matched, "active_match_cancelled")
                        try:
                            _am_conn = open_state_db(
                                self.boot.storage.state_db_path
                            )
                            try:
                                mark_slot_ended(
                                    _am_conn,
                                    matched.slot_id,
                                    "active_match_cancelled",
                                )
                            finally:
                                _am_conn.close()
                        except Exception:
                            log.exception(
                                "active_match cleanup mark_slot_ended failed for %s",
                                matched.slot_id,
                            )
                        raise
                    except Exception as e:  # noqa: BLE001 -- per-slot isolation
                        completed_ok = False
                        self._fail_completion_future(matched, e)
                        log.exception(
                            "active_match completion failed for slot %s",
                            matched.slot_id,
                        )
                    # On completion failure, skip grace pretense
                    # — go ACTIVE → GRACE → POPPED + mark failed, keep state
                    # machine honest. (transition validates each hop.)
                    transition(matched, SlotState.GRACE)
                    if completed_ok:
                        # The matched slot's content just actually landed on
                        # the engine -- it becomes the freshest live identity
                        # on this thread ONLY when it is main-class. A
                        # curator/sub-agent/compression follow-up can share
                        # the anchor's own thread_id -- pop_matched_thread
                        # matches on thread_id+model_tag alone, no role
                        # awareness (see the displacement-seam comment in _probe_and_save_clean_kv, "a
                        # grace-loop match on a shared thread_id (curator
                        # sharing main's thread_id...)") -- and parking a
                        # disposable identity's client_meta would later make
                        # _seam_flush_allowed decline the unload-seam flush
                        # ENTIRELY: a stale-but-present main bin would become
                        # NO bin at all. Gated via _bin_role, the same
                        # main-class resolve point the displacement-seam save and
                        # _seam_flush_allowed already use -- not a new inline
                        # is_curator/is_main check.
                        if _bin_role(matched.client_meta) in (None, "main"):
                            _grace_tip = matched
                        await self._audit_async(matched, "active_match_to_grace")
                        if self.grace.restart_for_followup():
                            # Also bump per-slot extension_count
                            # (was always 0 in sqlite — only GraceTimer's was).
                            matched.extension_count = self.grace.extension_count
                            deadline = time.monotonic() + self.runtime.queue.grace_seconds
                            await self._audit_event_only_async(
                                matched.slot_id,
                                "grace_extended_via_active_match",
                                {"extension_count": self.grace.extension_count},
                            )
                    else:
                        await self._audit_async(matched, "active_match_failed")
                    # Matched slot's request is done; its
                    # sidecar was the anchor's warm process (reused, not its own).
                    # Anchor `slot` remains the GRACE driver until grace expiry.
                    transition(matched, SlotState.POPPED)
                    await self._audit_async(matched, "active_match_completed" if completed_ok else "active_match_failed_terminal")
                    _am_conn = open_state_db(self.boot.storage.state_db_path)
                    try:
                        mark_slot_ended(
                            _am_conn,
                            matched.slot_id,
                            "active_match_completed" if completed_ok else "active_match_failed",
                        )
                    finally:
                        _am_conn.close()
                    self._set_active_slot(slot)  # anchor for teardown bookkeeping
                    continue
                # Gated -- a Fast Lane CLAIM cannot use
                # this path to shorten a non-victim's grace (see the
                # helper's own docstring for why no victim check is needed).
                if await self._starvation_breakout_candidate(slot) is not None:
                    await self._audit_async(slot, "grace_starvation_breakout")
                    log.info(
                        "grace_starvation_breakout slot=%s model=%s",
                        slot.slot_id,
                        slot.model_tag,
                    )
                    break
                await asyncio.sleep(0.05)

            # GRACE → POPPED (slot lifecycle ends here)
            transition(slot, SlotState.POPPED)
            # Hold the sidecar in idle for follow-up reuse
            # by any same-model_tag request inside idle_hot_load_seconds.
            # When idle_seconds == 0 (test default), this is equivalent to
            # immediate teardown -- preserves "grace-expired" reason on the
            # mark_slot_ended audit (backward-compat with existing tests).
            #
            # Keep-alive handling (fully automatic):
            # honor the latest request's keep_alive intent as IDLE_HOT extension.
            # `_latest_keep_alive_s` was set on the anchor's ACTIVE and refreshed
            # on each ACTIVE_MATCH promotion — so it reflects the most recent
            # request that touched the warm slot (Ollama timer-resets-on-receipt
            # semantics). After consumption it's cleared so a stale value can't
            # leak into the next anchor cycle.
            keep_alive_s = self._latest_keep_alive_s
            default_idle = self.runtime.queue.idle_hot_load_seconds
            if keep_alive_s is None:
                idle_seconds = default_idle
            elif keep_alive_s < 0:
                # Ollama -1 = "pin until VRAM pressure"; we cap at KEEP_ALIVE_MAX_S
                # (never indefinite on single-GPU).
                idle_seconds = KEEP_ALIVE_MAX_S
            else:
                # 0 falls through this expression cleanly → idle disabled.
                idle_seconds = min(keep_alive_s, KEEP_ALIVE_MAX_S)
            ka_clamped = (
                keep_alive_s is not None
                and keep_alive_s >= 0
                and keep_alive_s > KEEP_ALIVE_MAX_S
            )
            # Consumed — clear before any further decisions so the next anchor
            # starts cleanly (defense-in-depth on top of _process_slot reset).
            self._set_latest_keep_alive(None)
            # Same-model residency — cheap insurance floor: even when the
            # client's keep_alive would unload the model NOW (idle_seconds <= 0),
            # keep it warm if the NEXT queued request is the SAME model (by
            # intent). The queued same-model request then warm-inherits on the next
            # worker tick instead of paying teardown + respawn. Single-slot-safe:
            # only the resident model is ever held, and only for a bounded window
            # (_SAME_MODEL_QUEUED_HOLD_S) that still idle-expires if the queued
            # request vanishes before it is popped. head_model_tag() is a pure,
            # non-destructive peek — no queue mutation, no reentrancy (worker_loop
            # holds no queue lock here). The real swap-churn fix is the queue-side
            # affinity narrowing in pop_next; this only covers the keep_alive=0 edge.
            #
            # ── DEAD-CODE MARKER ──────────────────
            # (1) UNCALLED as of v0.8.0. This floor is unreachable at EVERY legal
            #     cap: `worker_loop` returns `self._dispatch_loop()` whenever
            #     `max_parallel_sidecars >= 1`, and `config.py`'s field pins that
            #     value with `ge=1`, so the condition is unconditionally true and
            #     `_process_slot` — this whole method — is never entered.
            # (2) RETAINED, NOT DELETED, per this codebase's convention for retained
            #     dead code (see `_legacy_defer_exhaustion_refusal`'s docstring for the
            #     rationale).
            # (3) WHY unreachable: see (1). Note additionally that the handle this
            #     block gates on is doubly dead — `self._active_handle` is only ever
            #     assigned a REAL handle from inside `_process_slot` itself; every
            #     live writer (`_teardown`, `_force_cold`) passes None. So even if
            #     this branch were reached, `_active_handle is not None` would be
            #     false on any live path.
            # (4) NOT MAINTAINED. Nothing exercises this any more; verify it before
            #     reattaching a caller — it will have rotted like any other
            #     unexercised path.
            # (5) WHAT REPLACED IT: `_same_model_residency_floor` (this file),
            #     called from `_drive_resident`'s post-turn idle decision. The port
            #     is NOT a copy of this body, and a future reattacher must not treat
            #     it as one:
            #       • it gates on `r.grace_tip`, never `_active_handle` (see (3));
            #       • it adds the rank condition
            #         (`queue.has_strictly_higher_priority_waiting`) that this
            #         version lacks — holding warm occupies capacity, so a
            #         lower-ranked same-model request must not keep a resident from
            #         a higher-ranked waiter;
            #       • ⛔ the "no reentrancy (worker_loop holds no queue lock here)"
            #         safety argument above DOES NOT TRANSFER. `_drive_resident`
            #         makes its idle decision under `_registry_lock`, and these
            #         peeks take `queue._lock`; the order is
            #         `queue._lock -> _registry_lock`, never reversed. The live port
            #         is therefore called BEFORE that lock is taken. Anyone porting
            #         this block anywhere else must re-derive that argument rather
            #         than inheriting this comment's.
            # ──────────────────────────────────────────────────────────────────
            if idle_seconds <= 0 and self._active_handle is not None:
                try:
                    same_model_queued = (
                        await self.queue.head_model_tag() == slot.model_tag
                    )
                except Exception:
                    log.exception("head_model_tag peek failed (best-effort)")
                    same_model_queued = False
                if same_model_queued:
                    idle_seconds = _SAME_MODEL_QUEUED_HOLD_S
            if idle_seconds > 0 and self._active_handle is not None:
                # Hand off the active handle to the manager-level idle holder.
                # Pass thread_id so idle teardown can save KV cache.
                # Pass admission_ctx_len so KV save uses admission-time context length.
                # T3: pass client_meta so warm-inherit path can restore session_id (fixes KV cache bin mismatch).
                # Source every field from _grace_tip, NOT the anchor
                # `slot` -- a conversation that grew across one or more
                # ACTIVE_MATCH follow-ups must park (and later unload-seam-
                # flush) the LAST-served turn count, not the first. thread_id/
                # model_tag are unaffected in practice (pop_matched_thread only
                # ever matches the anchor's own thread_id+model_tag), but
                # client_meta/admission_ctx_len are exactly the fields that
                # were going stale.
                self._set_idle_holder(
                    self._active_handle,
                    _grace_tip.model_tag,
                    time.monotonic() + idle_seconds,
                    _grace_tip.thread_id,
                    _grace_tip.admission_ctx_len,
                    _grace_tip.client_meta,
                )
                await self._audit_event_only_async(
                    slot.slot_id,
                    "idle_hot_enter",
                    {
                        "model_tag": slot.model_tag,
                        "idle_seconds": idle_seconds,
                        # Audit: visibility into when
                        # client keep_alive overrode the default + when the cap fired.
                        "keep_alive_requested": keep_alive_s,
                        "keep_alive_clamped": ka_clamped,
                    },
                )
                # Mark the slot ended at the state.sqlite layer -- the slot
                # is done; only the model stays warm. Audit reason names the
                # warm-hold so post-hoc audits can see the difference vs.
                # plain grace-expired teardown.
                _ih_conn = open_state_db(self.boot.storage.state_db_path)
                try:
                    mark_slot_ended(
                        _ih_conn, slot.slot_id, "grace-expired-held-idle"
                    )
                finally:
                    _ih_conn.close()
            else:
                # idle disabled (idle_seconds=0) or no handle -- immediate teardown.
                await self._teardown(slot, "grace-expired")
                self.idle.start(slot.model_tag)
                await self._audit_event_only_async(
                    slot.slot_id,
                    "idle_hot_enter",
                    {"model_tag": slot.model_tag},
                )
        finally:
            # Cancellation-unwind safety net:
            # If unwind reaches here with a live handle, the IDLE_HOT
            # entry did NOT complete (most often CancelledError during
            # shutdown or mid-_complete_fn). MUST teardown the handle,
            # not just drop the reference, or llama-server orphans with
            # the full model in VRAM and no parent reference anywhere.
            #
            # Design notes for this safety net:
            # 1. Diagnostic log at entry — surfaces leak path under repro.
            # 2. Do NOT null _active_handle until sigterm SUCCEEDS. If the
            #    sigterm helper raises (drained_sigterm internal failure,
            #    process already dead/zombie, etc.) leaving _active_handle
            #    set lets worker_loop's per-slot exception handler
            #    (see worker_loop) fire its safety-net _teardown(). Otherwise
            #    the null-before-success ordering bypassed that safety net.
            handle_to_reap = self._active_handle
            self._set_active_slot(None)
            log.warning(
                "process_slot finally reached: slot=%s active_handle_pid=%s alive=%s idle_match=%s",
                getattr(slot, "slot_id", "?"),
                getattr(handle_to_reap, "pid", None) if handle_to_reap is not None else None,
                handle_to_reap.is_alive() if handle_to_reap is not None else False,
                handle_to_reap is self._idle_handle if handle_to_reap is not None else False,
            )
            # Skip defensive sigterm if the handle was promoted to the
            # IDLE_HOT holder — that promotion is by design; killing it
            # would defeat the warm-hold purpose.
            # Removed is_alive() gate — TOCTOU: process could die
            # between the check and _sigterm, causing the sigterm to be
            # skipped entirely. _sigterm handles a dead process gracefully;
            # the safety-net _teardown in worker_loop catches any missed reaps.
            if (
                handle_to_reap is not None
                and handle_to_reap is not self._idle_handle
            ):
                # This is a cancellation-unwind safety net: it kills whatever
                # handle survives past the try/finally without ever routing
                # through the KV-save chokepoint (no slot-matched identity to
                # save against is available here by construction of this
                # path). Previously silent; now explicit.
                _log_kv_save_decline(
                    KV_DECLINE_CANCELLATION_UNWIND_NO_SAVE,
                    thread_id=getattr(slot, "thread_id", "") or "",
                    call_site="process_slot_cancellation_unwind")
                sigterm_ok = False
                try:
                    await asyncio.shield(
                        self._sigterm(
                            handle_to_reap,
                            drained_window_s=float(
                                self.runtime.queue.drained_sigterm_window_active_s
                            ),
                            is_active=False,
                            cold_window_s=float(
                                self.runtime.queue.drained_sigterm_window_cold_s
                            ),
                        )
                    )
                    sigterm_ok = True
                except Exception:
                    log.exception(
                        "cancellation-unwind teardown FAILED — leaving "
                        "_active_handle set so worker_loop safety-net can retry"
                    )
                if sigterm_ok:
                    self._set_active_handle(None)
                # else: keep _active_handle so worker_loop's except handler
                # (which calls _teardown with reason="worker-uncaught-exception")
                # has a second chance to reap. If that ALSO fails, the
                # intra_lifetime_orphan_scan on the next /ensure tick is
                # the final safety net (singleton.py).
            else:
                # Handle absent or promoted to idle_holder — safe to null.
                self._set_active_handle(None)

    async def _teardown(self, slot: Slot, reason: str) -> None:
        """Drained SIGTERM the process group → VRAM verify → orphan reap → audit."""
        if self._active_handle is not None:
            if self._active_handle.is_alive():
                # SPEC-V2 REWORK R3b: unload-time clean flush (grace-expired with
                # idle disabled / failure teardowns). Real slot available -> call
                # the probe directly. Best-effort; sequenced BEFORE _sigterm.
                # reason is this function's own already-in-scope parameter
                # ("grace-expired" / "worker-uncaught-exception" /
                # "loading-fail-health-timeout") -- reused as _seam_tag exactly
                # like the displacement-seam caller does, so the firing
                # chokepoint's trigger= stops collapsing this whole function's
                # teardowns into the generic "unload_seam" label.
                await self._probe_and_save_clean_kv(
                    self._active_handle, slot, save_to_disk=True,
                    _seam_tag=reason)
                # Unload-seam persist: mirror the idle-holder teardown's
                # RAM->SSD persist — grace-expired-no-idle / failure teardowns are
                # unload moments too. Keyed by the (session,role[,fp8])
                # _bin_identity string, NOT the raw thread_id; chain source
                # mirrors _save_slot_kv's slot path (admission_hash_chain, falling
                # back to _prefix_hash_chain(client_meta messages) like the flush
                # shim) so the persisted filenames match what was saved.
                _p_cm = getattr(slot, "client_meta", None)
                _p_chain = getattr(slot, "admission_hash_chain", None)
                if not _p_chain:
                    _p_msgs = (_p_cm or {}).get("messages")
                    _p_chain = _prefix_hash_chain(_p_msgs) if _p_msgs else None
                await asyncio.to_thread(
                    self._persist_clean_bin_to_ssd, slot.model_tag or "",
                    _bin_identity(getattr(slot, "thread_id", "") or "", _p_cm, _p_chain),
                    self._active_handle.port, trigger=reason,
                )
                await self._save_slot_kv(self._active_handle.port, slot.model_tag, slot)
            else:
                # A dead handle holds no live VRAM to save -- legitimate
                # no-op, but previously silent about why.
                _log_kv_save_decline(
                    KV_DECLINE_HANDLE_NOT_ALIVE,
                    thread_id=getattr(slot, "thread_id", "") or "",
                    call_site="teardown")
            ok, status = await self._sigterm(
                self._active_handle,
                drained_window_s=float(self.runtime.queue.drained_sigterm_window_active_s),
                is_active=False,
                cold_window_s=float(self.runtime.queue.drained_sigterm_window_cold_s),
            )
            # Dynamic expected_drop_mib derived from manifest
            # expected_vram_bytes. Was hardcoded 1024 MiB — let a 921 MiB
            # drop "verify clear" while a 17 GiB model is still resident.
            expected_drop_mib = self._compute_expected_drop_mib(slot.model_tag)
            # The return was previously ignored -- a stuck
            # CUDA context went silently unnoticed. Log-only (no credit to
            # reconcile on this legacy singleton path).
            # settle_floor_s=0.0 deliberately -- this cap<=1 path is
            # `await`ed in-line by worker_loop itself (the dispatch fork:
            # cap>=2 returns into _dispatch_loop before reaching
            # this code, so `_make_room_signal` never has a waiter parked
            # behind this call). The result above is log-only and gates no
            # re-admission, so a settle floor here has no faster-notice
            # benefit to offset its cost -- it would be pure added latency on
            # worker_loop's own next pop_next() for every teardown in cap<=1.
            _cleared_ok, _current_used_mib = await self._vram_verify(
                expected_drop_mib=expected_drop_mib, timeout_s=30.0,
                settle_floor_s=0.0,
            )
            if not _cleared_ok:
                log.warning(
                    "VRAM not confirmed cleared after 30s during teardown for "
                    "model_tag=%r (expected drop %d MiB, current used %s MiB)",
                    slot.model_tag, expected_drop_mib, _current_used_mib,
                )
            # Scan for grandchild orphans left behind by
            # Tom's Fork setsid-detach (killpg never reached them) and
            # reap before the next slot needs the port + VRAM. ~50ms
            # /proc walk; cheap to run on every teardown.
            orphan_reaped = 0
            # DURABLE PROOF: read recorded engine identities so the reaper
            # only touches proven Turbohaul-owned engines. Conservative —
            # a foreign llama-server is never reaped here either.
            _teardown_ids: set = set()
            try:
                with state_db_session(self.boot.storage.state_db_path) as _c:
                    _teardown_ids = known_engine_identities(_c)
            except Exception:
                pass
            try:
                orphan_reap_result = boot_orphan_reaper(
                    port_base=self.boot.runtime.default_port_base,
                    # Preserve every LIVE sidecar. A co-resident engine is
                    # recorded at spawn exactly like the one being torn down,
                    # so the durable-identity gate alone cannot tell them
                    # apart — it proves ownership, not staleness. Without
                    # this set a healthy sibling is SIGTERMed during another
                    # resident's teardown. Same set the intra-lifetime scan
                    # below already uses; at cap<=1 it is empty, so this is a
                    # no-op there.
                    known_pids=self._live_handle_pids(),
                    known_engine_identities=_teardown_ids,
                )
                orphan_reaped = orphan_reap_result.get("reaped", 0)
            except Exception:
                log.exception(
                    "post-teardown orphan reap failed (best-effort)"
                )
            # Intra-lifetime port-bound reaper. Catches
            # orphans whose parent IS still the running manager (PPid !=
            # 1 so boot_orphan_reaper misses them) — e.g. handle dropped
            # without sigterm via lost reference or finally-clear bug.
            try:
                live_pids = self._live_handle_pids()
                il_result = intra_lifetime_orphan_scan(
                    port_base=self.boot.runtime.default_port_base,
                    known_handle_pids=live_pids,
                )
                if il_result.get("reaped", 0) > 0:
                    log.warning(
                        "intra-lifetime reap caught orphans post-teardown: %s",
                        il_result,
                    )
            except Exception:
                log.exception(
                    "intra-lifetime orphan scan failed (best-effort)"
                )
            # Slot-write stays on state_db_session; audit-write goes
            # through the pool wrapped in asyncio.to_thread (sync-only).
            with state_db_session(self.boot.storage.state_db_path) as conn:
                mark_slot_ended(conn, slot.slot_id, reason)

            def _audit_teardown() -> None:
                with audit_db_session(self.boot.storage.state_db_path) as audit_conn:
                    record_audit_event(
                        audit_conn,
                        "teardown",
                        {
                            "reason": reason,
                            "sigterm_status": status,
                            "sigterm_ok": ok,
                            "post_teardown_orphans_reaped": orphan_reaped,
                        },
                        slot_id=slot.slot_id,
                    )

            await asyncio.to_thread(_audit_teardown)
            # Clear _active_handle after
            # successful teardown so the outer finally's defensive sigterm
            # net does not double-fire on normal flow. Owner contract:
            # "if you called _teardown you have handed off the handle."
            self._set_active_handle(None)
            # Completion-cache SWAP-CLEAR (cap<=1): the active sidecar that
            # produced any cached completions is gone -> invalidate them so a later
            # fresh spawn of the same model can NEVER serve an answer from the dead
            # engine instance (results are engine/build-specific).
            self._completion_cache_clear("teardown")

    async def _teardown_idle_holder(self, reason: str, *,
                                     expires_at: float | None = None) -> None:
        """Tear down the manager-level idle handle.

        Called when:
        - a slot for a DIFFERENT model_tag arrives (immediate switch path), or
        - the idle timer expires in the worker_loop, or
        - the idle holder is found dead between requests (proactive sweep), or
        - shutdown.

        expires_at: the caller's OWN pre-null deadline, when the caller has
        one to give. The idle_expired/idle_dead call sites in worker_loop
        call self._set_idle_expires_at(None) BEFORE scheduling this coroutine
        (debounces a concurrent re-arm racing the same tick), so by the time
        this function runs, self._idle_expires_at already reads None on
        exactly those two paths -- reading the field directly here would
        silently produce a None deadline on the one reason (idle_expired)
        this field exists to describe. Those callers already hold the value
        in a local before nulling it, so they pass it through here instead.
        model_swap/shutdown don't null it first -- they pass nothing, and
        the field is read directly below, same as always.
        """
        if self._idle_handle is None:
            return
        held = self._idle_handle
        # Capture aliveness at ENTRY — the flush/sigterm below
        # mutate it, and the VRAM-verify at the tail must know whether a drop is
        # even expected (a DEAD holder freed its VRAM at death; expecting a drop
        # burns the full 30s poll + logs a false "not cleared").
        _held_was_alive = held.is_alive()
        model_tag = self._idle_model_tag
        idle_thread_id = self._idle_thread_id
        idle_admission_ctx_len = self._idle_admission_ctx_len
        idle_client_meta = self._idle_client_meta  # SPEC-V2 REWORK R3: capture BEFORE clear (flush needs messages)
        # Prefer the caller's pre-null value (see the expires_at parameter
        # doc above); fall back to reading the field directly for
        # model_swap/shutdown, which don't null it first. Either way this
        # must run BEFORE _clear_idle_holder() -- that call wipes
        # _idle_expires_at to None too.
        _idle_expires_at = expires_at if expires_at is not None else self._idle_expires_at
        # deadline_delta_s is deliberately NOT elapsed idle time. Elapsed
        # would be idle_seconds-minus-remaining, and idle_seconds is
        # live-mutable runtime config -- it can change while a timer is
        # already running, and any window spanning that change would
        # silently misreport. Seconds relative to the deadline this holder
        # was ACTUALLY armed with can't be invalidated that way: ~0 on a
        # natural idle_expired wakeup, negative (time still on the clock)
        # when model_swap/shutdown cuts it short. Do not "simplify" this
        # into elapsed time.
        _deadline_delta_s = (
            round(time.monotonic() - _idle_expires_at, 1)
            if _idle_expires_at is not None else None
        )
        log.info(
            "IDLE_TEARDOWN reason=%s model_tag=%s thread_hash=%s alive=%s "
            "deadline_delta_s=%s",
            # thread_hash is deliberately UNTRUNCATED, unlike the disposable-stash warning
            # a few lines below it in this same function -- this is the only
            # field that joins this line to the KV_SAVE_FIRING line the same
            # teardown produces moments later, and that line's thread_hash
            # is untruncated too; a mismatched truncation would silently
            # break the join on any thread_id longer than the cut.
            reason, model_tag or "", idle_thread_id or "?",
            _held_was_alive, _deadline_delta_s)
        self._clear_idle_holder()
        # A disposable-owned idle stash never flushes/persists
        # at the seam — kills the junk 35b bins (live receipts 16:02:36Z: owner-
        # mismatch dances on sess:*:sub-agent:* and agent-ip-*-auto-* bins).
        # Single resolve point: _seam_flush_allowed. Skipping HERE (not only at
        # the save) also skips the wasted strip-probe FULL PREFILL of a
        # disposable transcript + the Option C SSD copy + the direct
        # _save_slot_kv + the shadow swap-save. Belt AND enforcement:
        # _save_slot_kv_inner re-checks the same predicate.
        _flush_ok, _idle_role = _seam_flush_allowed(idle_thread_id or "", idle_client_meta)
        if held.is_alive() and not _flush_ok:
            _p_msgs_d2 = (idle_client_meta or {}).get("messages")
            log.warning(
                "unload-seam KV flush SKIPPED (D2 disposable-owned stash): role=%s "
                "thread=%s identity=%s — no bin written/persisted",
                _idle_role, (idle_thread_id or "?")[:60],
                _bin_identity(idle_thread_id or "", idle_client_meta,
                              _prefix_hash_chain(_p_msgs_d2) if _p_msgs_d2 else None))
            _log_kv_save_decline(
                KV_DECLINE_DISPOSABLE_ROLE_SAVE_OFF, thread_id=idle_thread_id or "",
                role=_idle_role, call_site="teardown_idle_holder")
        elif not held.is_alive():
            # A dead holder freed its VRAM at death -- legitimate no-op, but
            # the reason is logged explicitly (see _held_was_alive above, which
            # already exists for the same reason on the VRAM-verify path).
            _log_kv_save_decline(
                KV_DECLINE_HANDLE_NOT_ALIVE, thread_id=idle_thread_id or "",
                call_site="teardown_idle_holder")
        # Reroute KV save through _save_slot_kv with overrides.
        # This replaces the bolt-on POST that sent {"thread_id": ...} directly.
        # _save_slot_kv will POST {"filename": "..."} to the engine (correct API)
        # and write metadata with prompt_len = idle_admission_ctx_len.
        if held.is_alive() and _flush_ok:
            # Disk-at-unload: THIS is the disk-write
            # moment — grace expiry + swap ("model_swap"), idle/full-timer expiry
            # ("idle_expired"), and "shutdown" all land here. The flush MUST be
            # the strip-probe force_clean form (the VRAM tail holds the just-
            # generated with-<think> turn; a plain action=save would either be
            # skipped by the clean-present guard or persist polluted state).
            # Sequenced BEFORE _sigterm below — the engine must be alive to serve
            # apply-template + prefill + action=save.
            await self._flush_clean_kv_at_unload(
                held, model_tag or "", idle_thread_id or "",
                idle_admission_ctx_len, idle_client_meta,
                # reason is this function's own already-in-scope parameter --
                # reused as _seam_tag exactly like the displacement-seam
                # caller does below, so the firing chokepoint's trigger= stops
                # collapsing idle_expired / model_swap / shutdown into one
                # generic label.
                _seam_tag=reason,
            )
            # Option C: THE SINGLE SSD WRITE PER SESSION. Copy the final
            # clean bin (+ .ckpt sidecar + meta) from the tmpfs SLOT_SAVE_DIR to the
            # SSD SLOT_PERSIST_DIR so a controlled swap/idle warm-reloads from SSD.
            # A hard container restart legitimately loses the RAM bin (recompute
            # fresh, by design). Best-effort; never blocks teardown. Bins are keyed
            # by the (session,role[,fp8]) _bin_identity string, NOT the raw
            # thread_id — mirror the flush shim's derivation exactly (chain =
            # _prefix_hash_chain(stashed idle messages)) so the persisted
            # filenames match what _save_slot_kv just wrote.
            # The SSD copy is
            # cold storage — it belongs on idle_expired/shutdown, NOT on a
            # live model_swap (by design the only time it goes to disk is
            # the warm idle timeout). _flush_clean_kv_at_unload above stays
            # UNCONDITIONAL for every reason (it's the only writer of main's
            # RAM clean bin — a design invariant;
            # skipping it would contradict that invariant). This gate
            # touches ONLY the SSD write below; _save_slot_kv and
            # _shadow_save_at_swap after it are also untouched.
            if reason != "model_swap":
                _p_msgs = (idle_client_meta or {}).get("messages")
                await asyncio.to_thread(
                    self._persist_clean_bin_to_ssd, model_tag or "",
                    _bin_identity(idle_thread_id or "", idle_client_meta,
                                  _prefix_hash_chain(_p_msgs) if _p_msgs else None),
                    getattr(held, "port", None), trigger=reason,
                )
            await self._save_slot_kv(
                held.port,
                model_tag,
                self._active_slot,
                thread_id_override=idle_thread_id,
                admission_ctx_len_override=idle_admission_ctx_len,
                client_meta_override=idle_client_meta,
            )
            # Freshness: while the outgoing sidecar is still
            # ALIVE with its KV populated (BEFORE _sigterm), re-save a FRESH think-free
            # shadow of the outgoing model at the swap seam. INERT unless SHADOW_REPREFILL;
            # no-downgrade + identity-matched inside (never overwrites a fresher per-turn
            # shadow, never a different thread) -> best-effort belt, safe if it no-ops.
            await self._shadow_save_at_swap(held, model_tag, idle_thread_id or "")
        ok, status = await self._sigterm(
            held,
            drained_window_s=float(
                self.runtime.queue.drained_sigterm_window_active_s
            ),
            is_active=False,
            cold_window_s=float(
                self.runtime.queue.drained_sigterm_window_cold_s
            ),
        )
        # Dynamic expected_drop_mib for idle holder teardown.
        # A holder that was DEAD at teardown entry already
        # released its VRAM — expect a 0 drop so the verify returns on the first
        # poll instead of burning 30s on the recovery path.
        expected_drop_mib = (
            self._compute_expected_drop_mib(model_tag or "")
            if _held_was_alive else 0
        )
        # The return is checked -- a stuck CUDA
        # context must not go silently unnoticed. Log-only (no credit to reconcile on
        # this legacy singleton path).
        # settle_floor_s=0.0 deliberately -- same reasoning as
        # _teardown's own call above. This is `await`ed directly, in-line, by
        # the SAME coroutine that's about to spawn the next model (model_swap)
        # or is worker_loop's own idle sweep -- never a task parked on
        # `_make_room_signal`. A floor here is pure added latency with no
        # waiting claimant to notify faster.
        _cleared_ok, _current_used_mib = await self._vram_verify(
            expected_drop_mib=expected_drop_mib, timeout_s=30.0,
            settle_floor_s=0.0,
        )
        if not _cleared_ok:
            log.warning(
                "VRAM not confirmed cleared after 30s during idle-holder "
                "teardown for model_tag=%r (expected drop %d MiB, current used "
                "%s MiB)",
                model_tag, expected_drop_mib, _current_used_mib,
            )
        try:
            _idle_ids: set = set()
            try:
                with state_db_session(self.boot.storage.state_db_path) as _c:
                    _idle_ids = known_engine_identities(_c)
            except Exception:
                pass
            boot_orphan_reaper(
                port_base=self.boot.runtime.default_port_base,
                # Preserve every LIVE sidecar — see the teardown reaper above.
                known_pids=self._live_handle_pids(),
                known_engine_identities=_idle_ids,
            )
        except Exception:
            log.exception(
                "idle-holder orphan reap failed (best-effort)"
            )
        # Intra-lifetime port-bound reaper here too.
        try:
            live_pids = self._live_handle_pids()
            intra_lifetime_orphan_scan(
                port_base=self.boot.runtime.default_port_base,
                known_handle_pids=live_pids,
            )
        except Exception:
            log.exception(
                "intra-lifetime orphan scan failed (best-effort)"
            )
        # Dirty-tip describes a LIVE engine's VRAM; this
        # engine is now gone — drop the flag with it (flag lifecycle = engine
        # lifecycle; closes FP F2 stale-flag lost parking).
        _p = getattr(held, "port", None)
        if _p is not None and (getattr(self, "_kv_dirty_tail", {}) or {}).get(_p) is not None:
            _dt = dict(self._kv_dirty_tail)
            _dt.pop(_p, None)
            self._kv_dirty_tail = _dt
            log.info("KV dirty-tip DROPPED (engine teardown): port=%s", _p)
        # Audit-only write via pool, wrapped to_thread (sync-only).
        def _audit_idle_holder() -> None:
            with audit_db_session(self.boot.storage.state_db_path) as audit_conn:
                record_audit_event(
                    audit_conn,
                    "teardown_idle_holder",
                    {
                        "reason": reason,
                        "model_tag": model_tag,
                        "sigterm_status": status,
                        "sigterm_ok": ok,
                    },
                )

        await asyncio.to_thread(_audit_idle_holder)
        # SWAP-CLEAR (cap<=1): the idle-held sidecar (the
        # formerly-active model kept warm) is now torn down -> its cached
        # completions are stale (that engine instance is gone). This path does NOT
        # go through _teardown, so clear here too, else a later fresh spawn of the
        # same model could serve a dead-engine answer.
        self._completion_cache_clear("teardown_idle_holder")
        # A model SWAP just happened — this teardown fires on the
        # "different model_tag arrives" switch path (see docstring). Fire a throttled,
        # best-effort fingerprint purge so a reloaded / re-quantized / rebuilt
        # engine's now-stale bins are reclaimed PROMPTLY (not only at the next sweep
        # tick). Fire-and-forget on a bg task (parked in _bg_tasks -> drained at
        # shutdown) + OFF the request path; skipped once _stop_event is set so it
        # never races the shutdown-path call. STRICTLY a file sweep — it never
        # touches the restore decision.
        if not self._stop_event.is_set():
            self._spawn_bg(
                asyncio.to_thread(self._maybe_purge_mismatched_bins, "swap")
            )

    # ============================================================
    # Prefix-containment KV restore
    # ============================================================

    @staticmethod
    def _turn_hash(role: str, content) -> str:
        """Deterministic hash of a single conversation turn (full SHA-256)."""
        if isinstance(content, list):
            content = json.dumps(content, sort_keys=True, separators=(',', ':'))
        raw = f"{role}\x00{content}"
        return hashlib.sha256(raw.encode("utf-8", errors="replace")).hexdigest()

    @staticmethod
    def _thread_hash(thread_id: str) -> str:
        """Safe filename component from thread_id."""
        if not thread_id:
            return "nothread"
        return hashlib.sha256(thread_id.encode("utf-8")).hexdigest()[:16]

    @staticmethod
    def _kv_save_fn(model_tag: str, sid: int, thread_hash: str) -> str:
        return f"{model_tag}.{thread_hash}.slot{sid}.bin"

    @staticmethod
    def _kv_meta_fn(model_tag: str, sid: int, thread_hash: str) -> str:
        return f"{model_tag}.{thread_hash}.slot{sid}.json"

    async def _render_strip_prefill_probe(
        self, port: int, model_tag: str, messages: list, meta: dict,
        *, read_timeout_s: float,
    ) -> bool:
        """SAVE-ONLY: prefill the warm slot with the
        HISTORICAL-form prompt so the saved KV byte-matches the harness's future
        think-stripped resend of the covered turns (=> the restore MATCHES+REUSES instead
        of hitting a position-drifted prefix and CLEARing).

        Replaces the plain messages ``/v1/chat/completions`` n_predict=0 probe with:
          1. ``/apply-template`` renders {messages (+ the crit1 tool preamble)} into the
             EXACT prompt string the engine would prefix — INCLUDING the
             ``<think>...</think>\\n\\n`` scaffold the template emits position-based for the
             covered tool turns (those after last_query_index) that drift.
          2. :func:`_strip_think_scaffold` removes every such scaffold, so the prompt equals
             the render those SAME turns get once they fall BEFORE last_query_index next
             resend (historical position -> no scaffold).
          3. native ``/completion`` prefills that raw prompt (n_predict=0, cache_prompt) so
             the warm slot holds the historical-form KV -> the CALLER saves THAT.

        SAVE-ONLY / never-generates: only the two n_predict=0 save probes call this and
        n_predict is HARD-SET to 0, so a live-generation request can never be routed here
        or stripped. Tool knobs are carried verbatim (same _KV_PROBE_TOOL_KNOBS the plain
        probe used) so the rendered tools preamble byte-matches a tools-bearing live
        request (crit1 parity); a tools-less request -> knobs all None -> unchanged.

        Best-effort: returns True iff both engine calls succeeded; False (never raises) on
        any apply-template / completion failure so the caller simply skips the save,
        exactly as the plain probe returns on a failed POST.

        read_timeout_s is deliberately REQUIRED, no default. An earlier change
        bounded two of the three call sites to 180.0 (they sit on the swap
        critical path, where a stall blocks a model swap) but left this
        function's own default at 900.0 -- the third call site
        (_shadow_reprefill_and_save) inherited it silently and the earlier "fix"
        claim was false for that site. A shared default across call sites
        doing structurally different work is not evidence the value transfers
        (that third site is a full reprefill, not a swap-blocking probe -- see
        its own docstring), so instead of picking one number for everyone,
        every call site must now say what it means to wait, explicitly."""
        apply_payload: dict = {"messages": messages, "add_generation_prompt": False}
        for _k in _KV_PROBE_TOOL_KNOBS:
            _v = (meta or {}).get(_k)
            if _v is not None:
                apply_payload[_k] = _v
        base = f"http://127.0.0.1:{port}"
        try:
            async with httpx.AsyncClient(
                timeout=httpx.Timeout(connect=2.0, read=read_timeout_s, write=30.0, pool=2.0)
            ) as client:
                r = await client.post(f"{base}/apply-template", json=apply_payload)
                r.raise_for_status()
                rendered = (r.json() or {}).get("prompt")
                if not isinstance(rendered, str) or not rendered:
                    log.debug("Fix B: /apply-template returned no prompt (best-effort skip)")
                    return False
                stripped = _strip_think_scaffold(rendered, apply_payload.get("messages"))
                # Strip trailing UNCLOSED generation primer
                # on tool-call turns. The Qwen template emits an open `think` block
                # (no closing `</think>`) when a tool-call turn is CURRENT. The save
                # probe renders at SAVE time (turn is current -> open primer), but the
                # future resend renders HISTORICAL (turn is past -> no primer). If the
                # open primer survives into the saved KV bin, it diverges mid-prefix
                # vs the resend -> n_rs_seq=2 wall -> CLEAR. Strip it HERE so the
                # clean bin ends at the tool_result boundary = true byte-prefix.
                stripped = re.sub(
                    r"(<\|im_start\|>assistant\n)(?:<think>\n)?\s*\Z",
                    r"\1",
                    stripped
                )
                # BYTE-TAIL GATE (load-bearing for the forced warm
                # restore): the clean bin is only a safe force-restore target while
                # its tail is a true byte-prefix of the resend. If a trailing
                # <think> primer SURVIVED the strip (template change / CRLF /
                # multi-token preamble), saving it would arm a mid-prefix divergence
                # > n_rs_seq=2 -> full recurrent CLEAR on the next forced restore =
                # WORSE than native reuse. Refuse the save; the older good bin stays
                # and the warm path degrades safely (warm-no-clean-bin / not-prefix).
                if re.search(r"<think>\s*\Z", stripped):
                    self._kv_s0_tail_fail = getattr(self, "_kv_s0_tail_fail", 0) + 1
                    log.warning(
                        "byte-tail gate: unstripped <think> primer at render tail; "
                        "refusing clean-KV save (count=%d) tail=%r",
                        self._kv_s0_tail_fail, stripped[-64:],
                    )
                    return False
                # n_predict HARD-SET to 0: this path only ever prefills, never generates.
                cr = await client.post(
                    f"{base}/completion",
                    json={"prompt": stripped, "n_predict": 0, "cache_prompt": True},
                )
                cr.raise_for_status()
                # The reply carries tokens_evaluated: the engine's own token count for
                # the exact string just prefilled -- i.e. the clean, think-stripped form
                # the client will re-send. That is precisely the boundary a save must
                # stop at, and it is the only place that number exists. The slot's
                # current prompt length is NOT the same thing: it also covers whatever
                # was generated after this render, which the client will never send back.
                # tokens_evaluated is the FULL prompt count, not the newly-processed
                # delta -- cache_prompt changes how much work is done, not what is
                # reported -- so it stays correct on a warm slot.
                try:
                    _te = (cr.json() or {}).get("tokens_evaluated")
                    if isinstance(_te, int) and _te > 0:
                        # Keyed by port: one slot per engine in this deployment.
                        # The count is BOUND to the
                        # probed context's turn-hash fingerprint so the save
                        # side can verify the evidence is for the context it is
                        # about to save (arm="strip" = the historical-form
                        # /apply-template render of THIS function's messages).
                        _fp_strip = _chain_fp(_prefix_hash_chain(messages))
                        self._clean_prefill_tokens[port] = CleanPrefillEvidence(
                            count=_te, chain_fp=_fp_strip, arm="strip")
                        # A fresh probe re-proves the context — a poison
                        # retirement for this exact chain no longer applies.
                        _pf = self._poisoned_chain_fps.get(port)
                        if _pf and _fp_strip in _pf:
                            _pf.discard(_fp_strip)
                        log.info("CLEAN_PREFILL_TOKENS port=%d tokens_evaluated=%d", port, _te)
                    else:
                        # Unknown must be loud and must not masquerade as a value: drop
                        # any stale entry so a later save falls back explicitly rather
                        # than capping against a previous render's boundary.
                        self._clean_prefill_tokens.pop(port, None)
                        log.warning("CLEAN_PREFILL_TOKENS port=%d MISSING tokens_evaluated=%r", port, _te)
                except Exception:
                    self._clean_prefill_tokens.pop(port, None)
                    log.warning("CLEAN_PREFILL_TOKENS port=%d unparseable probe response", port)
            return True
        except Exception:
            # The probe failed -> it cannot have
            # recorded fresh evidence; drop any stale entry per the register's
            # documented invariant (a probe removes the entry whenever it
            # cannot obtain a fresh count).
            self._clean_prefill_tokens.pop(port, None)
            log.debug("Fix B render+strip+prefill probe failed (best-effort)", exc_info=True)
            return False

    def _kvcache_scan_cache_invalidate(self) -> None:
        """Invalidate the SLOT_SAVE_DIR scan cache.

        Call this AFTER EVERY write/delete/rename in SLOT_SAVE_DIR so the next
        scan will re-read the directory. Directory mtime can be unreliable
        (coarse resolution, same-second writes), so we double-invalidate:
        set _kvcache_dir_mtime to None AND clear the cached dicts.
        """
        self._kvcache_dir_mtime = None
        self._kvcache_clean_bins.clear()
        self._kvcache_shadow_bins.clear()
        # Every RAM-tier write/delete/rename ends a "gap" for
        # whatever key it touched — clear the whole latch rather than tracking
        # which key changed, so a legitimately-cleared bin is never stuck
        # behind a stale attempted-flag from before the write happened.
        self._kvcache_hydrate_attempted.clear()

    def _hydrate_ram_from_persist(self, save_dir: str, persist_dir: str) -> None:
        """Option C: hydrate the tmpfs SLOT_SAVE_DIR from the SSD persist
        archive (direction-reversed mirror of _persist_clean_bin_to_ssd). For each
        *.bin / *.json / *.bin.ckpt in persist_dir, copy into save_dir ONLY when
        the RAM copy is ABSENT (RAM always wins while present — it is per-turn
        fresh; SSD is only ever written FROM RAM so it can never be fresher than
        an existing RAM file).
        Atomic via .tmp + os.replace (same filesystem) so a concurrent reader never
        sees a partial. Idempotent + best-effort: never raises; a missing persist
        dir is a no-op (hard restart = recompute fresh, by design)."""
        import shutil
        try:
            if not os.path.isdir(persist_dir):
                return
            copied = 0
            for fn in os.listdir(persist_dir):
                if not (fn.endswith(".bin") or fn.endswith(".json")
                        or fn.endswith(".bin.ckpt")):
                    continue
                src = os.path.join(persist_dir, fn)
                dst = os.path.join(save_dir, fn)
                try:
                    # ROOT-CAUSE FIX: NEVER overwrite an existing
                    # RAM copy. Mid-session the RAM pair is per-turn FRESH while
                    # the SSD archive lags at last-unload/swap state (and may be
                    # R-COMP stale-marked); the size-difference "repair" clobbered
                    # the fresh post-compression anchor back to the stale pair on
                    # EVERY scan (found=None -> native-reuse pinned at the
                    # compression boundary, ~18k reprefill/turn). Saves are atomic
                    # (.tmp+os.replace) so an existing dst is always complete;
                    # SSD is only ever written FROM RAM, so it can never be
                    # fresher than an existing RAM file. Absent-only IS the
                    # documented one-time-per-gap intent.
                    if os.path.exists(dst):
                        continue
                    # Belt: never hydrate ANY member of a stale-marked
                    # triplet (R-COMP marked it dead) — the meta would be skipped
                    # by the finder anyway, and the bin+ckpt are multi-GB dead
                    # weight in the exact tmpfs that ENOSPC'd. Sibling json is
                    # derived per member; missing/corrupt json falls through to
                    # copy (pre-belt behavior).
                    if fn.endswith(".bin.ckpt"):
                        _meta_fn = fn[:-len(".bin.ckpt")] + ".json"
                    elif fn.endswith(".bin"):
                        _meta_fn = fn[:-len(".bin")] + ".json"
                    else:
                        _meta_fn = fn
                    try:
                        with open(os.path.join(persist_dir, _meta_fn)) as _hf:
                            if json.load(_hf).get("stale"):
                                continue
                    except Exception:
                        pass
                    os.makedirs(save_dir, exist_ok=True)
                    tmp = dst + ".tmp"
                    shutil.copy2(src, tmp)
                    os.replace(tmp, dst)
                    copied += 1
                except OSError:
                    log.debug("Option C hydrate: copy failed for %s (best-effort)",
                              fn, exc_info=True)
            if copied:
                log.info("Option C: hydrated %d file(s) SSD persist -> RAM kvcache",
                         copied)
        except Exception:
            log.debug("Option C RAM hydrate best-effort failed", exc_info=True)

    def _hydrate_ram_from_persist_for_key(
        self, save_dir: str, persist_dir: str, key: tuple,
    ) -> None:
        """Gap-triggered, key-scoped hydrate.

        Unlike _hydrate_ram_from_persist (a full-directory sweep that runs
        unconditionally on every scan — the actual defect), this only touches
        persist_dir when the caller already knows RAM does not currently
        satisfy `key`, and even then at most once per RAM-empty gap: the
        self._kvcache_hydrate_attempted latch, cleared by
        _kvcache_scan_cache_invalidate (the same chokepoint every RAM-tier
        write/delete/rename already calls — see that method's docstring). The
        latch can therefore never outlive the RAM-empty condition it exists to
        short-circuit, and can never permanently suppress a bin that a later
        real save legitimately un-stales (the stale-mark is cleared by
        _persist_clean_bin_to_ssd_by_hash overwriting the same deterministic
        filename — that overwrite is itself a SLOT_SAVE_DIR write, so it
        already clears this latch via the same invalidation path).

        Copies the FULL triplet (.bin/.json/.bin.ckpt) for every basename
        matching this key's (model_tag, thread_hash, port) pattern — a .bin
        without its .json is invisible to _scan_kvcache_if_stale's loop (it
        only iterates .json files), and without .bin.ckpt the engine-state
        sidecar silently goes missing. Same per-file stale-check and atomic
        tmp+replace as _hydrate_ram_from_persist, just filtered to this key
        instead of the whole directory. Best-effort; never raises."""
        model_tag, th, port = key
        _prefix = f"{model_tag}."
        _mid = f".p{port}.{th}."
        # Every exit from this function now logs
        # exactly ONE KV_HYDRATE summary line -- the disk tier was write-only
        # with no hydrate log lines at all, despite SSD
        # writes, and that silence let it go unnoticed. "matched" counts
        # persist_dir entries whose FILENAME matched this key before any
        # per-file disposition is applied, so a reader can tell "nothing on
        # disk for this key" (matched=0) apart from "something was on disk
        # but every candidate was skipped" (matched>0, copied=0) without
        # reading source.
        try:
            # Fast path: RAM already has SOMETHING for this key -- a hit must
            # never touch persist_dir. Scoped listdir of save_dir (tmpfs, cheap)
            # rather than trusting the (possibly stale-relative-to-this-call)
            # scan cache dicts.
            for fn in os.listdir(save_dir):
                if fn.startswith(_prefix) and _mid in fn:
                    log.info(
                        "KV_HYDRATE key=%s reason=ram-already-present "
                        "ram_file=%s matched=0 copied=0", key, fn)
                    return
        except OSError as e:
            log.info(
                "KV_HYDRATE key=%s reason=save-dir-list-failed error=%r "
                "matched=0 copied=0", key, e)
            return

        if key in self._kvcache_hydrate_attempted:
            log.info(
                "KV_HYDRATE key=%s reason=latch-already-attempted-this-gap "
                "matched=0 copied=0", key)
            return  # already resolved this key for the current RAM-empty gap
        self._kvcache_hydrate_attempted[key] = True

        try:
            if not os.path.isdir(persist_dir):
                log.info(
                    "KV_HYDRATE key=%s reason=persist-dir-absent path=%s "
                    "matched=0 copied=0", key, persist_dir)
                return
            import shutil
            matched = 0
            copied = 0
            skipped_ram_present = 0
            skipped_stale = 0
            skipped_copy_failed = 0
            for fn in os.listdir(persist_dir):
                if not (fn.startswith(_prefix) and _mid in fn):
                    continue
                if not (fn.endswith(".bin") or fn.endswith(".json")
                        or fn.endswith(".bin.ckpt")):
                    continue
                matched += 1
                src = os.path.join(persist_dir, fn)
                dst = os.path.join(save_dir, fn)
                try:
                    if os.path.exists(dst):
                        skipped_ram_present += 1
                        continue
                    if fn.endswith(".bin.ckpt"):
                        _meta_fn = fn[:-len(".bin.ckpt")] + ".json"
                    elif fn.endswith(".bin"):
                        _meta_fn = fn[:-len(".bin")] + ".json"
                    else:
                        _meta_fn = fn
                    try:
                        with open(os.path.join(persist_dir, _meta_fn)) as _hf:
                            if json.load(_hf).get("stale"):
                                skipped_stale += 1
                                continue
                    except Exception:
                        pass
                    os.makedirs(save_dir, exist_ok=True)
                    tmp = dst + ".tmp"
                    shutil.copy2(src, tmp)
                    os.replace(tmp, dst)
                    copied += 1
                except OSError:
                    skipped_copy_failed += 1
                    log.debug(
                        "Option C key-scoped hydrate: copy failed for %s "
                        "(best-effort)", fn, exc_info=True)
            log.info(
                "KV_HYDRATE key=%s matched=%d copied=%d "
                "skipped_ram_present=%d skipped_stale=%d skipped_copy_failed=%d"
                "%s",
                key, matched, copied, skipped_ram_present, skipped_stale,
                skipped_copy_failed,
                " reason=zero-persist-files-match-key-pattern" if matched == 0 else "",
            )
        except Exception:
            # Logged as a warning, not log.debug (silent by default).
            # A best-effort catch that swallows at debug level is
            # exactly the shape of silence this logging exists to close: an
            # exception here means the hydrate attempt is UNOBSERVABLE
            # unless someone already has debug logging on, which is not the
            # default.
            log.warning(
                "KV_HYDRATE key=%s reason=exception matched=? copied=? "
                "(best-effort failed)", key, exc_info=True)

    def _scan_kvcache_if_stale(self, requested_key: tuple | None = None) -> tuple[
        dict[tuple, tuple[int, str, list, int, int, int] | None],
        dict[tuple, tuple[int, str, list, int] | None],
    ]:
        """Scan SLOT_SAVE_DIR and return (clean_bins, shadow_bins) dicts.

        Returns cached dicts if the directory mtime has not changed since the
        last scan. If stale or missing, re-scans the directory, populates both
        dicts, updates the mtime, and returns the fresh dicts.

        clean_bins maps (model_tag, thread_hash, port) ->
        (chain_len, bin_fn, chain, sid, prompt_len, prompt_tokens) or None if no
        matching bin found for that key. prompt_len is a CHARACTER count
        (compute_ctx_len); prompt_tokens is a TOKEN count (engine-reported at
        save time, meta "prompt_tokens") -- do not confuse the two, they differ
        by roughly 3x on real prompts.

        shadow_bins maps (model_tag, thread_hash, port) -> (chain_len, bin_fn, chain, sid)
        or None if no matching bin found for that key.

        requested_key: None (default) is BYTE-IDENTICAL to
        pre-fix behavior — the full unconditional persist-dir sweep runs on
        every call, exactly as before. When a caller passes its own
        (model_tag, thread_hash, port) key (all 3 call sites already compute
        this immediately after the call — see _find_clean_bin/_find_shadow_bin
        and the anchor lookup in _probe_and_save_clean_kv), hydrate becomes
        gap-triggered and key-scoped instead: a RAM hit for that key never
        touches persist_dir at all, and a genuine RAM-empty gap hydrates that
        key's full triplet at most once until RAM is repopulated by any means.
        See _hydrate_ram_from_persist_for_key.
        """
        from turbohaul.subprocess_mgr import SLOT_SAVE_DIR, SLOT_PERSIST_DIR
        if requested_key is None:
            # Option C: hydrate the tmpfs from the SSD persist archive
            # when a controlled swap/idle emptied RAM but the SSD copy survives.
            # This unconditional sweep is now the requested_key=None
            # fallback ONLY — every real call site passes its key instead (see
            # docstring above).
            if _ram_reanchor_enabled():
                try:
                    self._hydrate_ram_from_persist(SLOT_SAVE_DIR, SLOT_PERSIST_DIR)
                except Exception:
                    log.debug("Option C RAM hydrate best-effort failed", exc_info=True)
        else:
            self._hydrate_ram_from_persist_for_key(
                SLOT_SAVE_DIR, SLOT_PERSIST_DIR, requested_key)
        try:
            dir_mtime = os.path.getmtime(SLOT_SAVE_DIR)
        except OSError:
            dir_mtime = None
        if dir_mtime == self._kvcache_dir_mtime:
            return self._kvcache_clean_bins, self._kvcache_shadow_bins
        # Stale or missing — re-scan
        self._kvcache_clean_bins.clear()
        self._kvcache_shadow_bins.clear()
        try:
            for fn in os.listdir(SLOT_SAVE_DIR):
                if not fn.endswith(".json"):
                    continue
                # Parse sidecar meta
                try:
                    with open(os.path.join(SLOT_SAVE_DIR, fn)) as f:
                        m = json.load(f)
                except (OSError, ValueError):
                    continue
                model_tag = m.get("model_tag") or fn.split(".")[0]
                thread_hash = m.get("thread_hash")
                port = m.get("port")
                if not (model_tag and thread_hash and port):
                    continue
                key = (model_tag, thread_hash, port)
                chain = m.get("hash_chain") or []
                sid = int(m.get("slot_id", 0) or 0)
                chain_len = len(chain)
                prompt_len = int(m.get("prompt_len", 0) or 0)
                prompt_tokens = int(m.get("prompt_tokens", 0) or 0)
                bin_fn = fn[:-5] + ".bin"
                _bin_path = os.path.join(SLOT_SAVE_DIR, bin_fn)
                if not os.path.exists(_bin_path):
                    continue
                # SPEC-V2 consistency stamp: meta claims the byte-size of the bin it
                # was written for; mismatch => treat the pair as absent (skip).
                _claim = m.get("bin_bytes")
                if _claim is not None:
                    try:
                        if os.path.getsize(_bin_path) != int(_claim):
                            continue
                    except (OSError, ValueError):
                        continue
                # Check if clean_prefix meta is present (R-COMP: a stale-marked
                # sidecar — compression re-delivery — is treated as absent so
                # _find_clean_bin / probe pre-check / warm gate never see the
                # pre-compression anchor).
                if m.get("clean_prefix") and not m.get("stale"):
                    # Store (chain_len, bin_fn, chain, sid, prompt_len, prompt_tokens)
                    if key not in self._kvcache_clean_bins:
                        self._kvcache_clean_bins[key] = (chain_len, bin_fn, chain, sid, prompt_len, prompt_tokens)
                    elif chain_len > self._kvcache_clean_bins[key][0]:
                        self._kvcache_clean_bins[key] = (chain_len, bin_fn, chain, sid, prompt_len, prompt_tokens)
                # Check if shadow meta is present
                if m.get("shadow"):
                    if key not in self._kvcache_shadow_bins:
                        self._kvcache_shadow_bins[key] = (chain_len, bin_fn, chain, sid)
                    elif chain_len > self._kvcache_shadow_bins[key][0]:
                        self._kvcache_shadow_bins[key] = (chain_len, bin_fn, chain, sid)
        except (FileNotFoundError, OSError):
            pass
        self._kvcache_dir_mtime = dir_mtime
        return self._kvcache_clean_bins, self._kvcache_shadow_bins

    async def _probe_and_save_clean_kv(self, handle, slot, *, save_to_disk: bool = False, _seam_tag: str | None = None) -> None:
        """Option A: persist a CLEAN-PREFIX KV (no generated
        <think> tail) so a cold restore REUSES instead of CLEAR+reprefill. On the
        qwen MTP hybrid recurrent ctx (n_rs_seq=2) the generated tail CANNOT be
        trimmed post-hoc (seq_rm aborts/corrupts), so the clean prefix must be
        captured BEFORE generation: fire a prefill-only probe (n_predict=0) DIRECT
        to the sidecar (bypasses admission/curator/restore recursion), then save.
        Best-effort, single-series only. Saves before the turn generates.

        _seam_tag is None for every per-turn-probe caller (their
        logging is byte-unchanged). The displacement seam passes
        _seam_tag="displacement" so every silent no-op decline below ALSO
        emits a distinguishable log line — an inert displacement-seam fire must never
        look identical to a working one. The two save_to_disk=True teardown
        callers (_teardown_idle_holder's unload seam, and _teardown)
        now pass their own `reason` as _seam_tag too, for the same reason —
        see the FIRING trigger= at the bottom of this function.
        """
        _MIN_CTX_LEN = 40000  # chars (~13k tok): only clean-save substantial contexts
        _primary_verdict_emitted = False  # set True by every explicit primary-verdict emit below
        tid = ""  # pre-bound so the finally-backstop below always has a value
        try:
            _mp = int(getattr(self.runtime.queue, "max_parallel_sidecars", 1) or 1)
            _hp = int(max(1, getattr(handle, "parallel", 1)))
            # OBSERVED concurrency at save time (0 == no
            # other ACTIVE sidecar) — computed once, before the gate below.
            _other_active = self._other_active_residents(handle)
            # Role for the gate's decline line — same derivation as
            # _tip_role further down (admission_role wins, else client_meta).
            # The role is included so every decline is
            # distinguishable by role in the log.
            _gate_adm_role = getattr(slot, "admission_role", "__unset__")
            _gate_role = (
                _gate_adm_role if _gate_adm_role != "__unset__"
                else _bin_role(getattr(slot, "client_meta", None) or {}))
            tid = getattr(slot, "thread_id", "") or ""
            inc_len = int(getattr(slot, "admission_ctx_len", 0) or 0)
            # ==== Tools-check history, kept short because the check has LEFT ====
            # The tools check was once hoisted to here, above both
            # of this method's early `return`s, because the single-series gate
            # was returning first and silencing it in ordinary multi-model
            # operation. It was then taken out of this method
            # altogether -- see the note below. Nothing about the tools check is
            # decided here any more; only the two save gates are.
            # The first gate below (`_clean_prefix_save_enabled`) is
            # UNREACHABLE IN PRODUCTION -- that attribute is never assigned
            # anywhere in src/ (only in tests), so the getattr default keeps it
            # True. It is cleared here anyway because clearing both costs the
            # same as clearing one; no live second bug was fixed by doing so.
            # ✅ NOTE -- the tools check also covers the
            # streaming and fan-out arms of _serve_on_resident, so streaming on a
            # warm resident is not blind to a tools change; it runs from the
            # per-turn seam described just below.
            # The tools check no longer lives in this method at all. It was extracted
            # to _check_thread_tools_fingerprint (a pure, zero-I/O method) and is now
            # reached from the PER-TURN seam instead of the KV-save path: from
            # _mark_slot_active (covering all the per-turn call sites) plus one
            # direct call at _serve_on_resident's matched promotion. Every per-turn
            # path is covered, streaming and fan-out included.
            # It never belonged here: this method performs real I/O (a direct
            # sidecar prefill POST and a multi-GB KV write) and the check is a dict
            # lookup, a hash and a log. It lived here only because this method
            # "already runs on every live per-turn probe" -- a convenience, never a
            # semantic fit.
            client_meta = slot.client_meta or {}
            if not getattr(self, "_clean_prefix_save_enabled", True):
                if _seam_tag:
                    log.info(
                        "clean-prefix save DECLINED (%s): _clean_prefix_save_enabled=False; thread=%s",
                        _seam_tag, (tid or "?")[:40])
                _primary_verdict_emitted = _log_kv_save_decline(
                    KV_DECLINE_SAVE_DISABLED, thread_id=tid,
                    call_site="probe_and_save_clean_kv")
                return
            # single-series only: no concurrent eviction between probe, save, real req.
            # The gate keys off
            # OBSERVED concurrency, not the static cap. cap >= 2 with every
            # other resident idle IS effectively single-series -> the save
            # proceeds (KV restore stays GREEN regardless of the
            # parallel-sidecar setting; repro: sub-agent turns
            # cold-prefilling every turn under max_parallel_sidecars=2).
            # Another sidecar actually ACTIVE -> concurrent series during the
            # window (the FSM can promote an idle sibling mid-window too), so
            # the single-series clean-bin invariant does not hold -> decline.
            # _hp stays hard: intra-engine parallel contexts displace
            # regardless of what the other sidecars are doing. Why proceeding
            # at observed=0 is SAFE: see the _other_active_residents docstring
            # (busy-never-evicted + non-overlapping co-resident VRAM
            # invariants).
            if _other_active or _hp != 1:
                # Warn when the single-series
                # gate silently self-disables clean-save on a SUBSTANTIAL ctx —
                # otherwise operators are blind to why NO clean bin was saved
                # (=> every cold restore/wave-return goes FRESH). The text reports
                # the OBSERVED count that actually tripped the gate (a combined
                # "max_parallel_sidecars=2, handle.parallel=1 != 1" message would read as if
                # BOTH failed when only the cap did).
                if tid and inc_len >= _MIN_CTX_LEN:
                    log.warning("clean-prefix save SKIPPED: single-series gate (OBSERVED %d other ACTIVE sidecar(s); cap=%d, handle.parallel=%s) on a %d-char ctx -> no clean bin saved; cold restore/wave-return will FRESH for thread=%s", _other_active, _mp, _hp, inc_len, (tid or "?")[:12])
                if _seam_tag:
                    log.info(
                        "clean-prefix save DECLINED (%s): single-series gate (OBSERVED %d other ACTIVE sidecar(s); cap=%d, handle.parallel=%s); thread=%s",
                        _seam_tag, _other_active, _mp, _hp, (tid or "?")[:40])
                _primary_verdict_emitted = _log_kv_save_decline(
                    KV_DECLINE_SINGLE_SERIES_GATE, thread_id=tid, role=_norm_tip_role(_gate_role),
                    call_site="probe_and_save_clean_kv")
                return
            port = handle.port
            # Hoisted ahead of the min-ctx-bar check below (was
            # originally computed after it, alongside model_tag) so the displacement-seam save —
            # and the tip_role sentinel correction it requires (described
            # below) — can run before this call has any
            # chance to return early. None of these four reads has a side
            # effect and nothing mutates client_meta in between, so hoisting
            # is safe; the original later assignments are removed, not
            # duplicated.
            _disp_role = _bin_role(client_meta)
            _adm_role = getattr(slot, "admission_role", "__unset__")
            _tip_role = _adm_role if _adm_role != "__unset__" else _disp_role
            # Displacement-seam save — evaluated HERE, BEFORE the min-ctx-bar check
            # below, deliberately: that bar (and the "no messages" check
            # further down) gate whether the CURRENT slot's OWN content is
            # worth saving. They say nothing about whether a DIFFERENT
            # (outgoing) identity's ALREADY-stashed content should be saved
            # — a short/context-light curator turn must still be able to
            # trigger a save of main's much larger outgoing state. Moved
            # inside this chokepoint (not left at caller sites) by design:
            # there are seven call sites into this method — two
            # dispatcher-level warm-inherit blocks plus five in-grace-loop
            # matched-continuation calls (both _serve_on_resident and
            # _process_slot) — and a caller-side hook only ever covered the
            # two dispatcher sites. A grace-loop match on a shared thread_id
            # (curator sharing main's thread_id — pop_matched_thread has no
            # role awareness) reaches this SAME point without ever passing
            # through a dispatcher boundary, so evaluating it here covers
            # all seven roads by construction instead of by caller-side
            # wiring. It reads
            # last_main_thread_id/last_main_client_meta, NOT
            # the current occupant's own thread_id/client_meta — those two
            # fields are deliberately CARRIED FORWARD through every
            # disposable stamp (see below), never overwritten by one, so a
            # SECOND (or Nth) disposable visitor displacing a FIRST one
            # still finds the last real main identity here even if the
            # first displacement's save silently declined/failed. Without
            # this, one bad attempt would permanently and undetectably lose
            # the ability to ever save that main thread's clean KV again —
            # confirmed empirically.
            _is_disposable_gated = (
                not save_to_disk and bool(tid) and _disp_role not in (None, "main")
                and not _role_save_enabled(_disp_role, client_meta)
            )
            _displacement_save_fired = False  # set True only if the displacement-seam recursive save below actually ran
            if _is_disposable_gated:
                _old_disp = self._kv_vram_anchor.get(port)
                _displaced_client_meta = _old_disp.get("last_main_client_meta") if _old_disp else None
                _displacement_allowed, _displaced_role, _incoming_kv_class = _displacement_save_allowed(
                    _displaced_client_meta, client_meta)
                if _displaced_client_meta and _displaced_role in (None, "main"):
                    from turbohaul.kv_classify import CLASS_COMPRESSION as _COMPRESSION_CLASS
                    _displaced_session_id = _displaced_client_meta.get("session_id") if isinstance(_displaced_client_meta, dict) else None
                    _displaced_thread_id = _old_disp.get("last_main_thread_id") or ""
                    # Subject pairing fix:
                    # thread_id/prompt_len/client_meta
                    # below all correctly travel as the OUTGOING (main)
                    # subject via last_main_* — model_tag did NOT, and was
                    # silently read from _old_disp.get("model_tag") instead
                    # (the CURRENT OCCUPANT's tag, i.e. the incoming
                    # visitor's own, once the visitor's own turn has reached
                    # its own stamp). kv_policy.kv_save_fn keys the bin
                    # filename on model_tag FIRST
                    # (f"{model_tag}.p{port}.{thread_hash}.slot{sid}.bin"),
                    # so firing with the wrong tag on a cross-model
                    # displacement — the exact case this logic exists to
                    # fix — saves main's transcript under a filename main's
                    # own restore will never look under: the save appears to
                    # succeed (logs FIRING) and is permanently unreachable.
                    # _flush_clean_kv_at_unload's own guard does NOT catch
                    # this — it only declines on an EMPTY model_tag, and
                    # _old_disp.get("model_tag") is normally non-empty (the
                    # visitor's own). last_main_model_tag is the same-
                    # carried-forward sibling of last_main_thread_id/
                    # last_main_client_meta/last_main_prompt_len, refreshed
                    # at the identical sites, for the identical reason.
                    _displaced_model_tag = _old_disp.get("last_main_model_tag") or ""
                    # Displacement-seam prompt_len pairing:
                    # `_old_disp.get(
                    # "prompt_len")` is overwritten by EVERY stamp on this
                    # port, main's own or a disposable visitor's own — unlike
                    # last_main_thread_id/last_main_client_meta, it is NOT
                    # carried forward. Reading it here pairs main's REAL
                    # identity (correctly sourced from last_main_*) with
                    # WHATEVER a later disposable visitor's own full stamp
                    # last wrote for prompt_len — main's own length only
                    # survives as long as no OTHER disposable visitor's own
                    # stamp has landed since. last_main_prompt_len is the
                    # same-carried-forward sibling of last_main_thread_id/
                    # last_main_client_meta, refreshed at the identical two
                    # sites, for the identical reason.
                    _displaced_prompt_len = _old_disp.get("last_main_prompt_len") or 0
                    if _incoming_kv_class == _COMPRESSION_CLASS:
                        log.info(
                            "displacement-seam save SKIPPED (is_compression excluded): "
                            "outgoing thread=%s session_id=%s(null=%s) model=%s",
                            _displaced_thread_id[:40], _displaced_session_id, _displaced_session_id is None,
                            _old_disp.get("model_tag"))
                        _log_kv_save_decline(
                            KV_DECLINE_DISPLACEMENT_COMPRESSION_EXCLUDED,
                            thread_id=_displaced_thread_id, role=_displaced_role,
                            call_site="displacement_seam")
                    elif _displacement_allowed:
                        # Stale-anchor guard: _kv_vram_anchor is
                        # never popped on engine teardown, so a last_main_*
                        # stamp can outlive the engine that produced it — a
                        # respawn on the same port (e.g. after a wave-return)
                        # can load a DIFFERENT model entirely. Comparing
                        # against the LIVE handle's own model_tag (not just
                        # "did the visitor's model differ from main's")
                        # catches both the cross-model-visitor cause AND the
                        # stale-anchor-outlived-the-engine cause with one
                        # check. A silent skip here would be exactly the
                        # failure shape this whole fix exists to eliminate —
                        # named and logged distinguishably, same as every
                        # other decline in this chokepoint.
                        if _displaced_model_tag != handle.model_tag:
                            log.info(
                                "displacement-seam save SKIPPED (last_main STALE: model "
                                "changed %s -> %s); thread=%s",
                                _displaced_model_tag, handle.model_tag, _displaced_thread_id[:40])
                            _log_kv_save_decline(
                                KV_DECLINE_DISPLACEMENT_STALE_MODEL,
                                thread_id=_displaced_thread_id, role=_displaced_role,
                                call_site="displacement_seam")
                        else:
                            log.info(
                                "displacement-seam save FIRING: outgoing thread=%s "
                                "session_id=%s(null=%s) role=%s model=%s <- incoming %s",
                                _displaced_thread_id[:40], _displaced_session_id, _displaced_session_id is None,
                                _displaced_role, _displaced_model_tag, _incoming_kv_class)
                            # PROVISIONAL pre-announcement, not the
                            # authoritative record -- the real save (real
                            # bin_id) fires moments later at
                            # probe_and_save_clean_kv via _seam_tag=
                            # "displacement" below. trigger= here shares NO
                            # substring with "displacement" (a variant
                            # named "displacement_provisional" would collide, since a plain
                            # `grep -c trigger=displacement` still matches --
                            # a substring collision defeats the exact point
                            # of relabeling it). The authoritative counting
                            # key is still call_site=probe_and_save_clean_kv,
                            # not any trigger= string match.
                            _log_kv_save_firing(
                                bin_id="pending-recursive-save",
                                thread_id=_displaced_thread_id, role=_displaced_role,
                                n_tokens="unavailable", nbytes="unavailable",
                                trigger="seam_preflight", tier="RAM",
                                call_site="displacement_seam")
                            # Awaited to completion HERE, before this function
                            # returns and control goes back to the caller, which
                            # only THEN serves the incoming visitor's own turn
                            # (_complete_fn) — structurally guarantees the save
                            # finishes before any displacing token prefills,
                            # regardless of which of the seven roads got here.
                            # The probe re-renders the OUTGOING identity's own
                            # stashed transcript from scratch (cache_prompt=True
                            # prefill), so it is correct even if the engine's
                            # CURRENT VRAM no longer matches that transcript —
                            # it does not trust ambient VRAM state, only the
                            # stashed messages. This call's OWN entry guards
                            # (min-ctx bar etc) apply against the OUTGOING
                            # identity's OWN admission_ctx_len — never the
                            # incoming visitor's.
                            await self._flush_clean_kv_at_unload(
                                handle, _displaced_model_tag, _displaced_thread_id,
                                _displaced_prompt_len, _displaced_client_meta,
                                _seam_tag="displacement")
                            _displacement_save_fired = True
                else:
                    # No last-known main identity to displace (no prior main
                    # turn on this port yet, or the carried-forward record
                    # doesn't resolve to a main-class role) -- the displacement-seam save had
                    # nothing to act on. The decline is logged explicitly.
                    _log_kv_save_decline(
                        KV_DECLINE_DISPLACEMENT_NO_MAIN_IDENTITY,
                        thread_id=(_old_disp.get("last_main_thread_id") if _old_disp else "") or "",
                        role=_disp_role, call_site="displacement_seam")
            # Fix for tip_role staleness after a displacement-seam save (explained
            # below): the
            # recursive save just above (when it ran) stamped this port's
            # anchor with tip_role="main" — correct AT THAT INSTANT, the
            # probe really did just re-prefill main's own content onto the
            # engine. But THIS call's own turn (the short/foreign visitor
            # that triggered the displacement-seam save) is served on this SAME engine right
            # after this function returns, which overwrites the VRAM tip
            # with the visitor's own content. The tip_role machinery
            # lives entirely AFTER the min-ctx-bar return below — so if
            # THIS call is about to hit that return (or the "no messages"
            # return just past it) without ever reaching ITS OWN tip_role
            # stamp further down, nothing would ever correct the now-stale
            # "main" claim: a LATER main-claiming caller's _vram_ours check
            # would read a coherent-looking tip_role=main and wrongly
            # natively-reuse VRAM that actually holds the visitor's state.
            # Scoped to ONLY the two early-return points between here and
            # this call's own stamp (not applied unconditionally) — a call
            # that goes on to reach its own full stamp a few lines down
            # corrects tip_role itself, by construction, with byte-identical
            # wording/behavior to before this fix; only the genuinely-
            # silent gap gets touched. _bin_role returns None for genuinely
            # unlabeled traffic and _norm_tip_role(None) normalizes to
            # "main", so writing a plain None here would silently re-create
            # the exact same bug — stamp the literal "unlabeled" sentinel
            # instead whenever this call's own _tip_role isn't positively
            # known; _norm_tip_role passes any non-None/non-"main" string
            # through unchanged, so "unlabeled" reads as a clean mismatch
            # against any later main claim. Do NOT touch _norm_tip_role or
            # _vram_ours themselves — the fix stays entirely on the write
            # side, here.
            if not tid or inc_len < _MIN_CTX_LEN:
                if _displacement_save_fired:
                    _anchor_after_displacement_save = self._kv_vram_anchor.get(port)
                    if _anchor_after_displacement_save is not None:
                        self._kv_vram_anchor[port] = {
                            **_anchor_after_displacement_save,
                            "tip_role": _tip_role if _tip_role is not None else "unlabeled",
                        }
                if _seam_tag:
                    _log_cm = getattr(slot, "client_meta", None) or {}
                    _log_sid = _log_cm.get("session_id") if isinstance(_log_cm, dict) else None
                    log.info(
                        "clean-prefix save DECLINED (%s): min-ctx bar (ctx_len=%d < %d chars); "
                        "displaced thread=%s session_id=%s(null=%s)",
                        _seam_tag, inc_len, _MIN_CTX_LEN, (tid or "?")[:40], _log_sid, _log_sid is None)
                _primary_verdict_emitted = _log_kv_save_decline(
                    KV_DECLINE_BELOW_MIN_CTX, thread_id=tid, role=_tip_role,
                    call_site="probe_and_save_clean_kv")
                return
            model_tag = slot.model_tag
            messages = client_meta.get("messages")
            if not messages:
                if _displacement_save_fired:
                    _anchor_after_displacement_save = self._kv_vram_anchor.get(port)
                    if _anchor_after_displacement_save is not None:
                        self._kv_vram_anchor[port] = {
                            **_anchor_after_displacement_save,
                            "tip_role": _tip_role if _tip_role is not None else "unlabeled",
                        }
                _primary_verdict_emitted = _log_kv_save_decline(
                    KV_DECLINE_NO_MESSAGES, thread_id=tid, role=_tip_role,
                    call_site="probe_and_save_clean_kv")
                return
            from turbohaul.subprocess_mgr import SLOT_SAVE_DIR
            # SPEC-V2 WAVE A: bin key = (session_id, role[, fp8]) from harness
            # labels; raw thread_id when session_id absent OR role unlabeled
            # (never default to main).
            _id_chain = _prefix_hash_chain(messages)
            th = self._thread_hash(_bin_identity(tid, client_meta, _id_chain))
            # Curator/compression/sub-agent KV is
            # DISPOSABLE per-role (toggle ONLY via the harness/front-end client_meta["save_kv"];
            # NO env vars; main always saves). When a disposable role's save is OFF, skip its PER-TURN save
            # (no bin accumulates) but STILL park the OUTGOING main identity (ownership-transfer,
            # same fire-and-forget path as the main flow) + stamp the anchor. Main's OWN save
            # (role=main -> _disp_role None) is UNTOUCHED. Main restores on return via
            # its OWN disk bin (identity owner-match in _restore_slot_kv_inner), NOT this anchor;
            # the stamp only keeps _vram_ours honest so main safe-degrades to disk/native, never
            # a wrong reuse. NOTE: `not save_to_disk` — NEVER gate the unload/
            # disk-flush seam (save_to_disk=True), so a disposable last-holder cannot suppress
            # main's SSD persist (FM-UNLOAD). Zero-change while the per-role default stays SAVE.
            # Per-port DIRTY-TIP tracker. A non-main role's
            # serve EXTENDS the shared VRAM tip past main's canonical chain, and
            # the MTP hybrid-recurrent ctx cannot trim that tail post-hoc (see
            # docstring above: seq_rm aborts). Track it at THIS single role-
            # resolve point so the unload seam knows the tip is a SUPERSET of the
            # canonical render before trusting a prefix-hit prefill + action=save.
            # Role source = ADMISSION stamp (survives the warm-inherit clobber,
            # PIN#1); fallback = _disp_role for shim/legacy slots. SET on every
            # disposable turn (save_kv toggle irrelevant: the tip is foreign
            # either way); CLEARED on every main/unlabeled turn (the engine
            # reprocessed from the divergence point -> tip canonical again).
            # pid-stamped so a respawned engine on a reused port never inherits a
            # stale flag. Replace-only dict writes (lock-free readers). Per-turn
            # only (`not save_to_disk`) so the seam's own main-labeled shim can
            # never self-clear before the remediation below runs. (_disp_role/
            # _adm_role/_tip_role are computed once, hoisted above the min-ctx
            # bar — see the comment there — not re-derived here.)
            if not save_to_disk:
                if _tip_role not in (None, "main"):
                    _dt = dict(getattr(self, "_kv_dirty_tail", {}) or {})
                    _dt[port] = {"role": _tip_role,
                                 "pid": getattr(handle, "pid", None),
                                 "thread": tid, "ts": time.time()}
                    self._kv_dirty_tail = _dt
                    log.info("KV dirty-tip SET: port=%s role=%s thread=%s "
                             "(foreign tokens now on shared VRAM tip)",
                             port, _tip_role, (tid or "?")[:40])
                elif (getattr(self, "_kv_dirty_tail", {}) or {}).get(port) is not None:
                    _dt = dict(self._kv_dirty_tail)
                    _dt.pop(port, None)
                    self._kv_dirty_tail = _dt
                    log.info("KV dirty-tip CLEARED: port=%s thread=%s "
                             "(main serve reprocessed the tip)", port, (tid or "?")[:40])
            if (not save_to_disk and _disp_role not in (None, "main")
                    and not _role_save_enabled(_disp_role, client_meta)):
                _old_disp = self._kv_vram_anchor.get(port)
                if (_old_disp and _old_disp.get("thread_hash")
                        and _old_disp.get("thread_hash") != th
                        and _old_disp.get("model_tag")):
                    self._spawn_bg(asyncio.to_thread(
                        self._persist_clean_bin_to_ssd_by_hash,
                        _old_disp.get("model_tag") or "", _old_disp.get("thread_hash") or "",
                        port, trigger="ownership_transfer"))
                _old_disp_tip_role = _old_disp.get("tip_role") if _old_disp else None
                self._kv_vram_anchor[port] = {
                    "thread_hash": th, "model_tag": model_tag,
                    "pid": getattr(handle, "pid", None), "chain": list(_id_chain),
                    "prompt_len": inc_len, "stamp": time.time(),
                    # The role this stamp actually
                    # belongs to, written synchronously with thread_hash so
                    # _maybe_force_clean_restore's _vram_ours check can
                    # compare it against the CURRENT caller's own zero-lag
                    # admission_role -- closing the thread_hash-collision
                    # bug (a same-session curator can hash identically to
                    # main via _bin_identity's raw-thread_id fallback) on
                    # the FIRST touch, unlike _kv_dirty_tail above (which
                    # only gets SET by this SAME turn's own write, one step
                    # too late for _maybe_force_clean_restore's read of it,
                    # which always runs first in the grace-loop matched path).
                    # _norm_tip_role: canonicalized (None/"main" -> "main")
                    # so a harness that's inconsistent about sending an
                    # explicit is_main label across turns never spuriously
                    # reads as a role mismatch on genuinely-main-to-main
                    # reuse.
                    "tip_role": _norm_tip_role(_tip_role),
                    # CARRY FORWARD whatever last-known main
                    # identity _old_disp held (None if there wasn't one) —
                    # this disposable stamp must never be the thing that
                    # erases it; only a genuine main-class turn (the
                    # per-turn-OFF park below) refreshes these three fields.
                    # last_main_prompt_len/last_main_model_tag (added for subject
                    # pairing) are carried-forward siblings of the other two —
                    # see the displacement-seam note above for why plain "prompt_len"/"model_tag"
                    # are unsafe to read for this (subject-pairing bug).
                    "last_main_thread_id": _old_disp.get("last_main_thread_id") if _old_disp else None,
                    "last_main_client_meta": _old_disp.get("last_main_client_meta") if _old_disp else None,
                    "last_main_prompt_len": _old_disp.get("last_main_prompt_len") if _old_disp else None,
                    "last_main_model_tag": _old_disp.get("last_main_model_tag") if _old_disp else None,
                }
                log.info(
                    "clean-prefix save GATED (disposable role=%s, per-role save OFF) "
                    "— no bin saved, outgoing %s parked; thread=%s",
                    _disp_role,
                    _norm_tip_role(_old_disp_tip_role),
                    (tid or "?")[:40])
                _primary_verdict_emitted = _log_kv_save_decline(
                    KV_DECLINE_DISPOSABLE_ROLE_SAVE_OFF, thread_id=tid,
                    role=_disp_role, call_site="probe_and_save_clean_kv")
                return
            # Save timing (design requirement: "KV save should happen
            # right before the main model is unloaded NOT at the time of sub agent
            # spawn in the cue"): MAIN's per-turn clean-save is OFF — the single KV
            # writer is the unload seam (save_to_disk=True via _flush_clean_kv_at_unload,
            # which re-renders the historical transcript = clean by construction; its
            # "clean bin present" skip-guard now finds none, so it RUNS at unload).
            # AUTOPSY (wf_2fff2359): the poisoned bin was created by per-turn probe
            # saves capturing post-curator/post-rewind engine state as clean=True —
            # this closes that window. Park + anchor stamp preserved (mirrors the
            # disposable gate above) so _vram_ours stays honest; warm tool-call reuse
            # (the deal-killer fix) is native-VRAM and never depended on these saves.
            if not save_to_disk:
                _old_m = self._kv_vram_anchor.get(port)
                if (_old_m and _old_m.get("thread_hash")
                        and _old_m.get("thread_hash") != th
                        and _old_m.get("model_tag")):
                    self._spawn_bg(asyncio.to_thread(
                        self._persist_clean_bin_to_ssd_by_hash,
                        _old_m.get("model_tag") or "", _old_m.get("thread_hash") or "",
                        port, trigger="ownership_transfer"))
                self._kv_vram_anchor[port] = {
                    "thread_hash": th, "model_tag": model_tag,
                    "pid": getattr(handle, "pid", None), "chain": list(_id_chain),
                    "prompt_len": inc_len, "stamp": time.time(),
                    # See the disposable-gate stamp
                    # above for why this field exists (and why it's
                    # normalized via _norm_tip_role).
                    "tip_role": _norm_tip_role(_tip_role),
                    # This IS the refresh point — a genuine
                    # main-class turn always resets last_main_* to ITS OWN
                    # current identity, superseding whatever a chain of
                    # prior disposable stamps carried forward. inc_len here
                    # IS main's own true prompt_len (this branch only ever
                    # runs when _disp_role is None/"main", excluded above).
                    "last_main_thread_id": tid,
                    "last_main_client_meta": client_meta,
                    "last_main_prompt_len": inc_len,
                    "last_main_model_tag": model_tag,
                }
                # NOTE: this stamp is no longer coupled to a prefill+
                # save, so the Wave-K natural-skip proof (anchor.chain == bin.chain
                # => byte-match) has lost its provenance. _warm_natural_skip_enabled
                # ships default OFF; if that env is ever flipped, re-derive the proof
                # before trusting the skip.
                log.debug(
                    "per-turn clean-save OFF (unload-seam-only) — anchor "
                    "stamped; thread=%s", (tid or "?")[:40])
                _primary_verdict_emitted = _log_kv_save_decline(
                    KV_DECLINE_UNLOAD_SEAM_ONLY, thread_id=tid, role=_tip_role,
                    call_site="probe_and_save_clean_kv")
                return
            # SEAM REMEDIATION — save_to_disk=True (unload/
            # teardown seam). If a disposable role extended this port's tip, the
            # strip-probe's cache_prompt prefill of the SHORTER canonical render is
            # a pure prefix-hit: the engine reuses and CANNOT trim the foreign
            # tail, so action=save would persist tip-tokens > canonical-chain
            # tokens (bin != stamped hash_chain = the wave-return strict-extension
            # abort common.cpp:1498 x3 -> 3-strikes -> fresh slow-load, live
            # 2026-07-10 16:05-16:09Z). Fix: ERASE the whole sequence (whole-seq
            # rm is legal on the recurrent ctx; only mid-seq trims abort), then
            # the UNCHANGED strip-probe below FULL-reprefills the canonical render
            # onto the empty slot -> bin == chain by construction. One-time seam
            # cost only when a disposable rode main's VRAM. Erase failure -> flag
            # stays -> _save_slot_kv_inner refuses EVERY save on this port
            # (previous good bin kept; wave-return pays a delta reprefill instead
            # of a poisoned restore).
            _dirty = (getattr(self, "_kv_dirty_tail", {}) or {}).get(port)
            if _dirty and _dirty.get("pid") not in (None, getattr(handle, "pid", None)):
                # F2: stale record from a previous engine on a reused port — POP it
                _dt = dict(self._kv_dirty_tail)
                _dt.pop(port, None)
                self._kv_dirty_tail = _dt
                log.info("KV dirty-tip DROPPED (stale pid, engine respawned): port=%s", port)
                _dirty = None
            if _dirty:
                # F3: no remediation when the seam identity ITSELF is disposable —
                # its save is refused at the chokepoint anyway; flag drops via
                # stale-pop / engine-teardown pop.
                _flush_ok_seam, _seam_role = _seam_flush_allowed(tid, client_meta)
                if not _flush_ok_seam:
                    log.info("dirty-tip remediation SKIPPED (seam identity disposable "
                             "role=%s) — saves refused by chokepoint; port=%s",
                             _seam_role, port)
                    _dirty = None
            # Lag-reducer THROTTLE. Source the incoming clean-
            # prefix turn count from the SAME structured messages the probe below
            # prefills, so it matches the n_context_turns the force_clean save will
            # stamp (_save_slot_kv derives its hash_chain from these same admission
            # messages when slot.context is empty).
            inc_turns = len(_id_chain)
            # Never force a save on a degenerate empty chain (0 turns). Belt
            # for a future/edge messages value that is truthy but yields no chain (the
            # `if not messages` guard above already covers the empty-list case).
            if inc_turns <= 0:
                _primary_verdict_emitted = _log_kv_save_decline(
                    KV_DECLINE_ZERO_TURN_CHAIN, thread_id=tid, role=_tip_role,
                    call_site="probe_and_save_clean_kv")
                return
            # Skip if we already hold a clean bin for this thread whose prefix >= current
            # (never-overwrite-with-smaller belt), else remember the anchor's grown turn
            # count (longest clean chain) so the throttle can bound the re-save cadence.
            saved_clean_turns = None
            saved_clean_prompt_len = None
            try:
                # Use the scan cache — no O(N) listdir loop.
                # Pass the already-known key so hydrate is
                # gap-triggered/scoped, not an unconditional full sweep.
                key = (model_tag, th, port)
                clean_bins, _ = self._scan_kvcache_if_stale(requested_key=key)
                best = clean_bins.get(key)
                if best is not None:
                    # best = (chain_len, bin_fn, chain, sid, prompt_len)
                    # PL v3 defense-in-depth: recheck bin exists before trusting cache
                    # (closes same-mtime-tick window where GC invalidated but cache
                    # wasn't refreshed yet, and finders' exists-recheck doesn't cover
                    # this direct cache read).
                    bin_fn = best[1]
                    if not os.path.exists(os.path.join(SLOT_SAVE_DIR, bin_fn)):
                        self._kvcache_scan_cache_invalidate()
                        best = None
                    else:
                        saved_clean_prompt_len = best[4]
                        # Length alone is a proxy
                        # for freshness, not freshness itself. A strictly-larger saved
                        # bin (>) is unambiguous -- always keep it, no question to ask.
                        # But the old `>=` also silently discarded every EXACTLY-EQUAL
                        # incoming save, even when its content genuinely differed (an
                        # edited/regenerated turn can hold total character length
                        # constant while changing what was said) -- this can happen on a
                        # real main thread (equal lengths, different content). `best[2]`/`_id_chain`
                        # are the saved/incoming SHA256 rolling content-hash chains
                        # (_prefix_hash_chain) -- ALREADY computed for both sides
                        # (best[2] read from the saved bin's own sidecar meta above;
                        # _id_chain computed earlier this same call for th/_bin_identity)
                        # -- nothing new invented, in the spirit of finding the
                        # authoritative value already sitting unread. Equal chains mean
                        # the content is (SHA256-strength) provably byte-identical, so
                        # overwriting would be pure wasted SSD I/O -- exactly the cost
                        # the throttle below exists to bound -- so keep declining.
                        # Diverging chains at EQUAL length mean the incoming is
                        # genuinely fresher (not merely longer), so let it through.
                        # Unlike the smaller-incoming case (a shorter
                        # incoming could be a genuinely different, coincidentally
                        # shorter conversation on the same thread_id -- chain
                        # divergence alone couldn't prove compression-vs-truncation
                        # there), an EQUAL-length incoming carries no such ambiguity:
                        # this thread's true current state is what's arriving now
                        # either way, so chain divergence alone is sufficient proof
                        # here, no admission-label gate needed.
                        _content_identical = (
                            saved_clean_prompt_len == inc_len and best[2] == _id_chain)
                        if saved_clean_prompt_len > inc_len or _content_identical:
                            if _seam_tag:
                                log.info(
                                    "clean-prefix save DECLINED (%s): never-overwrite-with-smaller "
                                    "(existing bin ctx_len=%d >= incoming=%d%s); thread=%s",
                                    _seam_tag, saved_clean_prompt_len, inc_len,
                                    ", content IDENTICAL" if _content_identical else "",
                                    (tid or "?")[:40])
                            _primary_verdict_emitted = _log_kv_save_decline(
                                KV_DECLINE_NEVER_OVERWRITE_SMALLER, thread_id=tid,
                                role=_tip_role, call_site="probe_and_save_clean_kv")
                            return  # never-overwrite-with-smaller belt
                        if saved_clean_prompt_len == inc_len:
                            log.info(
                                "clean-prefix save ALLOWED (equal-length, "
                                "content DIFFERS): existing bin ctx_len=%d == "
                                "incoming=%d but content hash-chain diverges; thread=%s",
                                saved_clean_prompt_len, inc_len, (tid or "?")[:40])
                        saved_clean_turns = best[0]
            except Exception:
                log.debug("clean-prefix pre-check failed (best-effort)", exc_info=True)
            # THROTTLE: a clean anchor already exists -> re-save (multi-GB) ONLY when the
            # clean-prefix chain grew by >= LAGREDUCER_MIN_GROWTH_TURNS turns. Re-saving
            # every +1 turn burns the request critical path; too rarely widens the
            # sawtooth lag. This bounds the lag to ~MIN_GROWTH_TURNS turns.
            _min_growth = 1 if save_to_disk else self.LAGREDUCER_MIN_GROWTH_TURNS
            if (saved_clean_turns is not None
                    and (inc_turns - saved_clean_turns) < _min_growth):
                log.debug(
                    "clean-prefix save THROTTLED: incoming_turns=%d saved n_context_turns=%d "
                    "(growth < %d) thread_hash=%s",
                    inc_turns, saved_clean_turns, self.LAGREDUCER_MIN_GROWTH_TURNS, th)
                if _seam_tag:
                    log.info(
                        "clean-prefix save DECLINED (%s): zero-growth throttle "
                        "(incoming_turns=%d saved_turns=%d growth<%d); thread=%s",
                        _seam_tag, inc_turns, saved_clean_turns,
                        self.LAGREDUCER_MIN_GROWTH_TURNS, (tid or "?")[:40])
                _primary_verdict_emitted = _log_kv_save_decline(
                    KV_DECLINE_ZERO_GROWTH_THROTTLE, thread_id=tid,
                    role=_tip_role, call_site="probe_and_save_clean_kv")
                return
            if _dirty:
                log.warning(
                    "unload-seam DIRTY TIP: port=%s foreign role=%s (via thread=%s) — "
                    "erase + full canonical reprefill before save; identity=%s thread_hash=%s",
                    port, _dirty.get("role"), str(_dirty.get("thread"))[:40],
                    _bin_identity(tid, client_meta, _id_chain), th)
                _erased = False
                _probe_ok = False
                _populated_count = None
                _slots_payload = None
                try:
                    async with httpx.AsyncClient(
                        timeout=httpx.Timeout(connect=2.0, read=60.0, write=10.0, pool=2.0)
                    ) as _ec:
                        _sl = await _ec.get(f"http://127.0.0.1:{port}/slots")
                        _sl.raise_for_status()
                        _slots_payload = _sl.json() or []
                        _probe_ok = True
                        # "populated" now means EITHER signal
                        # is nonzero, not just n_prompt_tokens. The raw in-memory token-
                        # vector length (n_prompt_tokens) can read 0 while the engine
                        # still holds foreign resident KV cells -- two call sites in
                        # server-context.cpp (LoRA-adapter-change at :2099, failed
                        # SLOT_RESTORE at :3043) clear the token vector WITHOUT clearing
                        # KV. n_prompt_tokens_cache (already serialized on this same
                        # /slots response, server-context.cpp:1043) is a second,
                        # independently tracked signal untouched by either bad path --
                        # it is zeroed ONLY by reset()/release() (server-context.cpp:703),
                        # the same place that performs the correctly-paired KV clear.
                        # See _classify_dirty_tip_probe's docstring for the full case
                        # table this feeds.
                        _pop = [s for s in _slots_payload
                                if ((s.get("n_prompt_tokens") or 0) > 0
                                    or (s.get("n_prompt_tokens_cache") or 0) > 0)
                                and s.get("id") is not None]
                        _populated_count = len(_pop)
                        if _populated_count == 1:
                            _er = await _ec.post(
                                f"http://127.0.0.1:{port}/slots/{int(_pop[0]['id'])}?action=erase")
                            _er.raise_for_status()
                            _erased = True
                except Exception:
                    log.warning(
                        "dirty-tip probe/erase raised (probe_ok=%s before the raise) — "
                        "treating as UNKNOWN state, port=%s thread_hash=%s",
                        _probe_ok, port, th, exc_info=True)

                _proceed, _case = _classify_dirty_tip_probe(
                    _probe_ok, _populated_count, _erased)

                if _case == "zero_populated":
                    _slots_summary = [
                        {"id": s.get("id"),
                         "n_prompt_tokens": s.get("n_prompt_tokens"),
                         "n_prompt_tokens_cache": s.get("n_prompt_tokens_cache"),
                         "is_processing": s.get("is_processing")}
                        for s in (_slots_payload or [])
                    ]
                    log.info(
                        "dirty-tip PROCEED-ON-ZERO: port=%s populated_slots=0 (probe OK, "
                        "n_prompt_tokens AND n_prompt_tokens_cache both zero on every "
                        "slot) — assuming tip already left with the COLD slot, no erase "
                        "target exists, proceeding WITHOUT erase; slots_summary=%s "
                        "identity=%s thread_hash=%s",
                        port, _slots_summary,
                        _bin_identity(tid, client_meta, _id_chain), th)

                if not _proceed:
                    log.warning(
                        "dirty-tip erase FAILED (%s) — unload-seam save REFUSED, "
                        "previous bin kept (port=%s probe_ok=%s populated_slots=%s "
                        "identity=%s thread_hash=%s)",
                        _case, port, _probe_ok, _populated_count,
                        _bin_identity(tid, client_meta, _id_chain), th)
                    _primary_verdict_emitted = _log_kv_save_decline(
                        KV_DECLINE_DIRTY_TIP_ERASE_FAILED, thread_id=tid,
                        role=_tip_role, call_site="probe_and_save_clean_kv")
                    return
                _dt = dict(self._kv_dirty_tail)
                _dt.pop(port, None)
                self._kv_dirty_tail = _dt
                log.info(
                    "dirty-tip %s: port=%s — canonical %d-turn chain will FULL-"
                    "reprefill (one-time seam cost) thread_hash=%s",
                    "ERASED" if _case == "single_erased" else "CLEARED (nothing to erase)",
                    port, len(_id_chain), th)
                # Before paying for the full cold reprefill below,
                # see whether an already-existing clean snapshot can serve via a
                # restore instead. Scoped strictly to this dirty-tip branch — the
                # ordinary (non-dirty) seam flush never reaches this code and is
                # byte-unchanged. Reuses _restore_slot_kv verbatim (the SAME
                # bin_bytes / owner-identity / hash-chain-PREFIX validation every
                # other restore in this file goes through — see
                # _restore_slot_kv_inner — not a new, narrower
                # check invented for this one site). The result is independently
                # VERIFIED against the engine's own actual post-restore
                # n_prompt_tokens (load_verify_log.verify_kv_restored) before being
                # trusted — mirrors the cold-spawn restore call site's own already-
                # established pattern rather than trusting a
                # bare POST 200. An unverified, short, or missing restore falls
                # through to the existing full reprefill below, UNCHANGED — this
                # can only ever REDUCE cost, never skip a save the branch above
                # didn't already decide was needed, and it never touches the erase
                # itself.
                _restored_n = None
                try:
                    _restored_n = await self._restore_slot_kv(port, model_tag, slot)
                except Exception:
                    log.debug(
                        "dirty-tip remediation restore attempt failed (best-effort); "
                        "falling back to full reprefill (port=%s)", port, exc_info=True)
                if _restored_n:
                    try:
                        # Same actual_n_past override as the other
                        # two verify_kv_restored call sites -- see the resident-
                        # driver restore site's comment for the full rationale.
                        # This is the call site this override was introduced for:
                        # de-racing it is what lets this site's own INFO line start
                        # reading RESTORED instead of UNVERIFIED (actual=None).
                        _actual_n_past = (getattr(self, "_kv_restore_actual_tokens", {}) or {}).pop(port, None)
                        _restore_verify = await load_verify_log.verify_kv_restored(
                            handle, 0, _restored_n, actual_n_past=_actual_n_past)
                    except Exception:
                        log.debug(
                            "dirty-tip remediation restore verification failed "
                            "(best-effort); falling back to full reprefill (port=%s)",
                            port, exc_info=True)
                        _restore_verify = {"kv_restore_ok": None}
                    if _restore_verify.get("kv_restore_ok") is True:
                        log.info(
                            "dirty-tip remediation: RESTORED existing verified clean "
                            "snapshot instead of cold reprefill (port=%s expected=%s "
                            "actual=%s) — dirty-tip mitigation",
                            port, _restored_n, _restore_verify.get("kv_actual_n_past"))
                        return
                    log.info(
                        "dirty-tip remediation: restore attempted but UNVERIFIED "
                        "(expected=%s actual=%s ok=%s) — falling back to full "
                        "reprefill (port=%s)",
                        _restored_n, _restore_verify.get("kv_actual_n_past"),
                        _restore_verify.get("kv_restore_ok"), port)
                else:
                    # Promoted from DEBUG to INFO. At DEBUG, "the
                    # remediation branch never ran" and "it ran and found no
                    # snapshot" were indistinguishable in production logs --
                    # operators could lose real time on exactly this ambiguity
                    # when verifying this remediation. Same fix as the spawn
                    # observer: an expected-but-empty outcome still needs to
                    # be visible, not just its two non-empty siblings above.
                    log.info(
                        "dirty-tip remediation: no snapshot available to restore, "
                        "falling back to full reprefill (port=%s)", port)
            if self._covered_scaffold_strip_enabled():
                # Prefill the HISTORICAL-form prompt (render
                # -> strip the covered-turn <think>...</think>\n\n scaffolds -> /completion)
                # so the saved clean bin byte-matches the harness's future think-stripped
                # resend of those covered turns. A failed engine call returns False -> skip
                # the save, exactly as the plain probe returns on a failed POST.
                # This call is on the model-swap critical path
                # (awaited before _sigterm, same as the already-bounded
                # recovery reprefill) -- bound it to 180s so it can't stall
                # the swap the way an unbounded 900s read could.
                if not await self._render_strip_prefill_probe(
                    port, model_tag, messages, client_meta, read_timeout_s=180.0
                ):
                    _primary_verdict_emitted = _log_kv_save_decline(
                        KV_DECLINE_STRIP_PROBE_FAILED, thread_id=tid,
                        role=_tip_role, call_site="probe_and_save_clean_kv")
                    # The erase already ran and popped the
                    # flag (required so the save chokepoint below wouldn't
                    # refuse itself) -- this probe failure means no confirmed
                    # save followed, so re-arm before returning rather than
                    # leaving the port unprotected until the next foreign visit.
                    self._kv_dirty_tail = _rearm_dirty_tip_on_incomplete_remediation(
                        self._kv_dirty_tail, port, _dirty)
                    return
            else:
                # Flag OFF -> pre-Fix-B behavior, byte-identical to today: plain messages
                # /v1/chat/completions n_predict=0 probe.
                payload = {
                    "model": model_tag,
                    "messages": messages,
                    "stream": False,
                    "n_predict": 0,
                    "max_tokens": 0,
                    "cache_prompt": True,
                }
                # crit1: carry the live request's tool preamble (verbatim from client_meta)
                # so the saved clean bin's front-of-prompt byte-matches a tools-bearing
                # request; None when the request has no tools -> payload unchanged.
                for _k in _KV_PROBE_TOOL_KNOBS:
                    _v = client_meta.get(_k)
                    if _v is not None:
                        payload[_k] = _v
                url = f"http://127.0.0.1:{port}/v1/chat/completions"
                # Same critical-path bound as the covered-strip branch
                # above -- this probe is also awaited before the swap's
                # _sigterm, so it must not inherit the 900s read default.
                try:
                    async with httpx.AsyncClient(
                        timeout=httpx.Timeout(connect=2.0, read=180.0, write=30.0, pool=2.0)
                    ) as client:
                        _pp = await client.post(url, json=payload)
                        # A non-2xx probe must DECLINE the save,
                        # not fall through to it. The old silence let a 4xx'd
                        # prefill proceed to a fallback-cap save whose clean
                        # stamp then rode on unverified VRAM — the exact
                        # post-generation bin the evict-return path restores
                        # and discards.
                        _pp.raise_for_status()
                        # Record the probe's own usage as the clean-render
                        # evidence the save side's strict stamp requires
                        # (mirrors the strip-probe's tokens_evaluated
                        # recording): set if int>0 else pop+warn, so an
                        # unparseable answer never masquerades as a boundary.
                        try:
                            _pt = ((_pp.json() or {}).get("usage") or {}).get("prompt_tokens")
                        except Exception:
                            _pt = None
                        if isinstance(_pt, int) and _pt > 0:
                            # Bind the count to the
                            # probed context's turn-hash fingerprint. _id_chain
                            # = _prefix_hash_chain(messages) was computed at
                            # the top of this SAME save call (probe and save
                            # share one context — no re-render, no new value).
                            _fp_plain = _chain_fp(_id_chain)
                            self._clean_prefill_tokens[port] = CleanPrefillEvidence(
                                count=_pt, chain_fp=_fp_plain, arm="plain")
                            # A fresh probe re-proves the context — a
                            # poison retirement for this exact chain no longer
                            # applies.
                            _pf = self._poisoned_chain_fps.get(port)
                            if _pf and _fp_plain in _pf:
                                _pf.discard(_fp_plain)
                            log.info("CLEAN_PREFILL_TOKENS port=%d prompt_tokens=%d (plain probe)", port, _pt)
                        else:
                            self._clean_prefill_tokens.pop(port, None)
                            log.warning("CLEAN_PREFILL_TOKENS port=%d MISSING prompt_tokens=%r (plain probe)", port, _pt)
                except _HTTPX_HTTP_STATUS_ERROR as _hs:
                    log.warning(
                        "clean-prefix probe POST HTTP %s — DECLINING clean save "
                        "(no confirmed prefill; previous bin kept); thread=%s",
                        _hs.response.status_code, (tid or "?")[:40])
                    # A failed probe -> no fresh evidence;
                    # drop any stale entry per the register's documented invariant.
                    self._clean_prefill_tokens.pop(port, None)
                    _primary_verdict_emitted = _log_kv_save_decline(
                        KV_DECLINE_PROBE_POST_FAILED, thread_id=tid,
                        role=_tip_role, call_site="probe_and_save_clean_kv")
                    self._kv_dirty_tail = _rearm_dirty_tip_on_incomplete_remediation(
                        self._kv_dirty_tail, port, _dirty)
                    return
                except Exception:
                    log.warning("clean-prefix probe POST failed (best-effort) — DECLINING clean save (previous bin kept)", exc_info=True)
                    # A failed probe -> no fresh evidence;
                    # drop any stale entry per the register's documented invariant.
                    self._clean_prefill_tokens.pop(port, None)
                    _primary_verdict_emitted = _log_kv_save_decline(
                        KV_DECLINE_PROBE_POST_FAILED, thread_id=tid,
                        role=_tip_role, call_site="probe_and_save_clean_kv")
                    # See the matching comment on the
                    # STRIP_PROBE_FAILED return just above -- same reasoning,
                    # same re-arm, this is the plain-probe sibling branch.
                    self._kv_dirty_tail = _rearm_dirty_tip_on_incomplete_remediation(
                        self._kv_dirty_tail, port, _dirty)
                    return
            # Slot now holds the clean prefix [prompt (+<=1 uncommitted tok)].
            # Per-turn RAM re-anchor (Option C): the probe's concurrent
            # n_predict:0 prefill CANNOT occupy the --parallel 1 slot (it is
            # cancelled unlaunched), so it never re-anchors the engine restore-base
            # (frozen@130514 -> growing reprefill). Restore Phase-1's proven
            # round-trip, but to the tmpfs SLOT_SAVE_DIR (RAM, zero SSD wear):
            # action=save the clean prefix, then action=restore it -> the restore
            # SYNCHRONOUSLY re-materializes the slot from the clean state and
            # re-commits the engine's restorable checkpoint at the GROWN clean
            # position, so the NEXT turn's get_common_prefix strict-extends
            # (delta-only) instead of diverging at the with-<think> boundary.
            #
            # Tier rule (ownership transfer): another
            # identity takes the slot => the OUTGOING agent's RAM copy goes to
            # SSD. BEFORE the anchor record is overwritten with the NEW identity,
            # schedule a best-effort background persist of the OLD identity's
            # bins (RAM->SSD, keyed by the anchor's already-hashed thread_hash).
            # Off the request critical path (_spawn_bg + to_thread); never blocks.
            _old = self._kv_vram_anchor.get(port)
            if (_old and _old.get("thread_hash") and _old.get("thread_hash") != th
                    and _old.get("model_tag")):
                self._spawn_bg(asyncio.to_thread(
                    self._persist_clean_bin_to_ssd_by_hash,
                    _old.get("model_tag") or "", _old.get("thread_hash") or "",
                    port, trigger="ownership_transfer"))
            self._kv_vram_anchor[port] = {
                "thread_hash": th,
                "model_tag": model_tag,
                "pid": getattr(handle, "pid", None),
                "chain": list(_id_chain),
                "prompt_len": inc_len,
                "stamp": time.time(),
                # See the disposable-gate stamp above
                # for why this field exists (and why it's normalized via
                # _norm_tip_role). Rolled back below alongside everything
                # else on an unconfirmed save (the whole dict, including
                # this field, is restored verbatim from `_old`).
                "tip_role": _norm_tip_role(_tip_role),
                # This save_to_disk=True path is reached ONLY
                # via the unload seam (_seam_flush_allowed-gated, main-ish) or the displacement seam
                # (_displacement_save_allowed-confirmed main-class) — the
                # identity being saved here IS the main identity by
                # construction of both callers, so refresh last_main_* to
                # match (rolled back below alongside everything else on an
                # unconfirmed save, same as the other fields).
                "last_main_thread_id": tid,
                "last_main_client_meta": client_meta,
                "last_main_prompt_len": inc_len,
                "last_main_model_tag": model_tag,
            }
            # Per-turn RAM save (SLOT_SAVE_DIR is tmpfs). force_clean=True keeps the
            # existing (session,role[,fp8]) keying, never-overwrite-with-smaller
            # belt, never-demote invariant, and confirmed-save logging INTACT.
            _saved = await self._save_slot_kv(port, model_tag, slot, force_clean=True)
            if not _saved:
                # SPEC-V2 consistency stamp: NEVER log saved/GREW on an unconfirmed
                # save — the pre-Phase-1 era unconditionally logged GREW 29..49 while
                # the on-disk meta was honest at 25 (the '49-turn meta' misreport).
                # ROLL BACK the optimistic anchor stamp —
                # leaving it AHEAD of the on-disk bin makes the
                # skip-redundant-restore chain check miss on every later turn
                # (anchor chain != disk chain), permanently re-arming the
                # restore->M-RoPE-crash path this wave exists to end.
                if _old is not None:
                    self._kv_vram_anchor[port] = _old
                else:
                    self._kv_vram_anchor.pop(port, None)
                log.warning("clean-prefix KV save NOT CONFIRMED (thread=%s, ctx_len=%d) — anchor rolled back to pre-stamp value", tid[:12], inc_len)
                _primary_verdict_emitted = _log_kv_save_decline(
                    KV_DECLINE_SAVE_NOT_CONFIRMED, thread_id=tid,
                    role=_tip_role, call_site="probe_and_save_clean_kv")
                # Same reasoning as the two probe-failure
                # returns above -- the erase's own promise (a fresh confirmed
                # save) was not kept, so re-arm before returning rather than
                # leaving this port unprotected until the next foreign visit.
                self._kv_dirty_tail = _rearm_dirty_tip_on_incomplete_remediation(
                    self._kv_dirty_tail, port, _dirty)
                return
            log.info("clean-prefix KV saved (thread=%s, ctx_len=%d)", tid[:12], inc_len)
            # bin_id is derived, not read back from the save: single-series
            # mode is a hard precondition of this function (checked above,
            # before this point is ever reachable), so slot id 0 is not a
            # guess. n_tokens/bytes are genuinely not available here --
            # _save_slot_kv_inner computes them but does not return them,
            # and this function's own contract is observability-only, so
            # widening that widely-shared function's return shape is out of
            # scope for this change.
            # this is the AUTHORITATIVE firing (real bin_id, confirmed save)
            # -- _seam_tag now carries the real reason from every
            # save_to_disk=True caller (idle-teardown, the active-slot
            # _teardown, and the displacement seam); "unload_seam" survives only
            # as the fallback for a caller that passes none. For the
            # displacement caller specifically, this line's trigger reads
            # plain "displacement" (the displacement seam's own pre-announcement above uses
            # the unrelated "seam_preflight" -- no shared substring) -- this
            # is the one to count.
            _primary_verdict_emitted = _log_kv_save_firing(
                bin_id=kv_save_fn(model_tag, 0, th, port),
                thread_id=tid, role=_norm_tip_role(_tip_role),
                n_tokens="unavailable", nbytes="unavailable",
                trigger=((_seam_tag or "unload_seam") if save_to_disk else "per_turn_probe"),
                # this call only ever fires after _save_slot_kv
                # (SLOT_SAVE_DIR/tmpfs) succeeds above -- never after an SSD
                # write, which is a separate function/tier.
                tier="RAM",
                call_site="probe_and_save_clean_kv")
            # OBSERVABILITY (reuse existing n_context_turns; NO new clean_turns
            # field per PL). Surface the clean-bin growth so the sawtooth lag is
            # measurable from logs. n_context_turns == incoming_turns here by
            # construction (both = len(_prefix_hash_chain(messages)) = the chain the save
            # just stamped); `was` is the prior anchor (None on first clean save).
            log.info(
                "clean-bin GREW: n_context_turns=%d (was %s) incoming_turns=%d thread_hash=%s",
                inc_turns,
                ("none" if saved_clean_turns is None else saved_clean_turns),
                inc_turns, th)
        except Exception:
            log.debug("clean-prefix probe+save best-effort failed", exc_info=True)
        finally:
            # Structural backstop: whatever road got here -- a return this
            # edit missed, or one a future change adds -- the primary
            # verdict is never silently skipped. Only fires when nothing
            # above already emitted one for this call.
            if not _primary_verdict_emitted:
                _log_kv_save_decline(
                    KV_DECLINE_UNVERIFIED_EXIT, thread_id=tid,
                    call_site="probe_and_save_clean_kv")

    async def _flush_clean_kv_at_unload(
        self, handle, model_tag: str, thread_id: str,
        admission_ctx_len: int, client_meta: dict | None,
        *, _seam_tag: str | None = None,
    ) -> None:
        """Unload-time DISK flush of the
        clean KV. Reuses _probe_and_save_clean_kv(save_to_disk=True) so the flush
        is the SAME proven strip-probe (render think-stripped -> S0 gate ->
        prefill -> force_clean save) and inherits every guard (min-ctx, identity
        keying incl. the sub-agent fp8 chain, never-overwrite-with-smaller,
        zero-growth dedupe, confirmed-save logging). The idle holder has no live
        Slot object at this seam, so a SimpleNamespace shim carries the stashed
        idle identity fields. admission_hash_chain is recomputed from the stashed
        messages — the SAME derivation the probe/save use — so the (session,
        role[, fp8]) bin identity matches the per-turn key exactly. Best-effort;
        the engine handle must still be alive (call BEFORE _sigterm).

        This is also the displacement-seam writer — its
        caller passes _seam_tag="displacement" so the same chokepoint's no-op
        declines log distinguishably at THAT seam. The original unload-seam
        caller (_teardown_idle_holder) now passes its own `reason`
        ("idle_expired"/"model_swap"/"shutdown") as _seam_tag too, so its
        firing/decline logging is labeled by the real teardown reason instead
        of staying generic. One save function, two doors; still no new
        writer -- both doors now identify themselves."""
        try:
            messages = (client_meta or {}).get("messages")
            if not model_tag or not thread_id or not messages:
                if _seam_tag:
                    log.info(
                        "clean-prefix save DECLINED (%s): missing model_tag/thread_id/messages "
                        "for the outgoing identity; thread=%s model=%s",
                        _seam_tag, (thread_id or "?")[:40], model_tag or "?")
                return
            shim = SimpleNamespace(
                thread_id=thread_id,
                model_tag=model_tag,
                admission_ctx_len=admission_ctx_len,
                admission_hash_chain=_prefix_hash_chain(messages),
                client_meta=client_meta,
                context=None,
                prompt="",
                port=getattr(handle, "port", None),
                pid=getattr(handle, "pid", None),
            )
            await self._probe_and_save_clean_kv(handle, shim, save_to_disk=True, _seam_tag=_seam_tag)
        except Exception:
            log.debug("unload-time clean KV flush best-effort failed", exc_info=True)

    def _persist_clean_bin_to_ssd(self, model_tag: str, thread_id: str, port, *, trigger: str) -> None:
        """UNFINISHED (disk-tier architecture): the disk-tier
        save path is in its current state, marked in the code as
        unfinished. The architecture does not depend on it being complete
        (it is neither repaired nor removed here), and the marker
        stays in place so its status is visible to a reader of the code.
        Companion marker: _persist_clean_bin_to_ssd_by_hash (the SSD copy
        body of this same path).

        Option C: copy the tmpfs clean bin (+.ckpt+meta) to the SSD
        persist dir at unload. The ONLY SSD write per session. shutil.copy2
        preserves mtime; atomic via .tmp+os.replace so a reader never sees a
        partial. Best-effort — any error leaves the RAM bin as the live source and
        simply forgoes cross-restart durability (safe).

        ``thread_id`` MUST be the (session,role[,fp8]) ``_bin_identity`` string,
        NOT the raw thread_id — _save_slot_kv keyed the filenames on
        _thread_hash(_bin_identity(...)), so hashing anything else here would
        filter for filenames that were never written.

        ``trigger`` is REQUIRED (no default) — see
        _persist_clean_bin_to_ssd_by_hash's docstring for the full enumeration
        of what values reach this and why the requirement is unconditional."""
        try:
            if not (model_tag and thread_id and port):
                return
            self._persist_clean_bin_to_ssd_by_hash(
                model_tag, self._thread_hash(thread_id), port, trigger=trigger)
        except Exception:
            log.debug("Option C RAM->SSD persist best-effort failed", exc_info=True)

    def _record_bin_death_strike(self, port: "int | None") -> None:
        """Attribute a dead engine to the bin its port
        last restored; 3 strikes -> auto-quarantine the triplet (both tiers)
        so the next load goes FRESH instead of looping.

        Extracted VERBATIM from worker_loop's cap<=1
        inline block (the only caller before this extraction) -- pure move, zero
        behaviour change. `port` replaces the inline reads of
        `self._idle_handle.port` so this is callable from any dead-engine
        detection site, not just the cap<=1 idle-holder sweep -- the cap>=2
        idle-liveness sweep is the second caller. `_bin_death_
        strikes` stays keyed by bin filename (never by port/resident/model)
        and `_quarantine_bin_triplet` stays pure filesystem work on that
        filename -- neither needed to change for a second caller to exist."""
        try:
            _bfn = getattr(self, "_last_restored_bin", {}).get(port)
            if _bfn:
                _st = getattr(self, "_bin_death_strikes", {})
                _st[_bfn] = _st.get(_bfn, 0) + 1
                self._bin_death_strikes = _st
                log.warning("bin death-strike %d/3: %s", _st[_bfn], _bfn)
                log.warning(
                    "ENGINE STALLED — restore-implicated death, "
                    "retry %d/3 (bin=%s)", _st[_bfn], _bfn)
                # FE-visible stall banner.
                # REPLACE-ONLY — always assign a fresh dict so the
                # lock-free status_snapshot reader can never see a
                # half-written record. Lazily created; read via
                # getattr. Never written from a to_thread body.
                self._engine_stall = {
                    "active": True,
                    "attempt": _st[_bfn],
                    "max": 3,
                    "bin": _bfn,
                    "ts": datetime.now(timezone.utc).isoformat(),
                }
                # One blame per restore — clear the
                # attribution so unrelated later deaths (fresh loads,
                # OOM) can never strike a long-dead restore's bin.
                self._last_restored_bin.pop(port, None)
                if _st[_bfn] >= 3:
                    log.error(
                        "BIN 3-STRIKES — AUTO-QUARANTINE %s (implicated in "
                        "%d deaths; by design): next load goes FRESH",
                        _bfn, _st[_bfn])
                    self._spawn_bg(asyncio.to_thread(
                        self._quarantine_bin_triplet, _bfn))
        except Exception:
            log.debug("bin strike accounting failed (best-effort)", exc_info=True)

    def _quarantine_bin_triplet(self, bin_fn: str) -> None:
        """3-strikes design: move a repeat-offender bin's
        triplet (.bin/.bin.ckpt/.json) out of BOTH tiers into kv_quarantine so the
        next load goes FRESH (the manual 2026-07-10 loop-break, automated). The
        evidence is preserved for autopsy, never deleted. Sync + best-effort —
        runs via _spawn_bg/to_thread off the hot path."""
        import shutil
        from turbohaul.subprocess_mgr import SLOT_SAVE_DIR, SLOT_PERSIST_DIR
        qdir = "/var/lib/turbohaul/kv_quarantine"
        base = bin_fn[:-4] if bin_fn.endswith(".bin") else bin_fn
        try:
            os.makedirs(qdir, exist_ok=True)
        except Exception:
            log.exception("quarantine dir create failed")
            return
        moved = 0
        for d in (SLOT_SAVE_DIR, SLOT_PERSIST_DIR):
            for suf in (".bin", ".bin.ckpt", ".json"):
                src = os.path.join(d, base + suf)
                if os.path.exists(src):
                    try:
                        shutil.move(src, os.path.join(qdir, base + suf))
                        moved += 1
                    except Exception:
                        log.exception("quarantine move failed: %s", src)
        self._kvcache_scan_cache_invalidate()
        log.error("QUARANTINED %d files for %s -> %s", moved, base, qdir)

    def _persist_clean_bin_to_ssd_by_hash(self, model_tag: str, th: str, port, *, trigger: str) -> None:
        """UNFINISHED (disk-tier architecture): the disk-tier
        save path ships in its current state, marked in the code as
        unfinished. It is NOT required to be complete for that architecture
        to be satisfied, and it is NOT to be silently repaired or silently
        removed -- its status must stay visible to a reader of the code.
        Companion marker: _persist_clean_bin_to_ssd (the wrapper entry of
        this same path).

        Option C (+ tier rule — ownership transfer): same
        as _persist_clean_bin_to_ssd but takes the ALREADY-HASHED thread hash.
        The _kv_vram_anchor record stores thread_hash (not the identity string),
        so the ownership-transfer seam can only key by hash. Best-effort; never
        raises.

        The persisted-bin log line carries a trigger label,
        so idle_expired and shutdown persists (and everything else that
        reaches this function) are told apart — the same "did it run,
        or run and find nothing" ambiguity is avoided on the spawn-env
        observer, here on the persist path instead. ``trigger`` is REQUIRED
        (no default, same reasoning as read_timeout_s: a 6th call site
        that forgets to say why it's here fails loudly, not silently).

        Every real call site, enumerated (not assumed to be only the obvious two --
        re-derive this list yourself before trusting it, since a quick
        caller survey can easily miss some):
        ``_teardown`` (reasons: worker-uncaught-exception,
        loading-fail-health-timeout, grace-expired — all three reach this
        unconditionally whenever the active handle is alive);
        ``_teardown_idle_holder`` (reasons: idle_expired, shutdown, insufficient_space — but NOT all of that function's own reasons: model_swap is explicitly excluded
        by its own ``if reason != "model_swap":`` guard, and idle_dead never
        reaches here at all because the SSD persist requires
        ``held.is_alive()``, which is false by definition for a holder found
        already dead); and three ownership-transfer sites inside
        ``_probe_and_save_clean_kv`` (a disposable-role park, a per-turn
        identity displacement, and the post-save anchor overwrite) — these
        three are the SAME conceptual event (an old, different identity is
        being evicted from the VRAM anchor before a new one claims the port)
        occurring at three different points in that function's control flow,
        not three distinct triggers, so all three pass the single label
        "ownership_transfer" rather than three near-identical strings a
        reader would have to learn are synonyms."""
        import shutil
        from turbohaul.subprocess_mgr import SLOT_SAVE_DIR, SLOT_PERSIST_DIR
        try:
            if not (model_tag and th and port):
                return
            os.makedirs(SLOT_PERSIST_DIR, exist_ok=True)
            copied = 0
            bin_copied_fn = None
            for fn in os.listdir(SLOT_SAVE_DIR):
                # only THIS identity's bin/ckpt/meta (session,role keyed filename)
                if not (fn.startswith(f"{model_tag}.")
                        and f".p{port}.{th}." in fn):
                    continue
                if fn.endswith(".tmp"):
                    continue  # never persist a mid-write temp
                src = os.path.join(SLOT_SAVE_DIR, fn)
                dst = os.path.join(SLOT_PERSIST_DIR, fn)
                tmp = dst + ".tmp"
                shutil.copy2(src, tmp)
                os.replace(tmp, dst)
                copied += 1
                # the triplet is .bin / .bin.ckpt / .json -- only ".bin" is
                # the actual KV bin a later hydrate reads; a sidecar-only
                # copy (e.g. a lone .json, or a .bin still mid-write and
                # skipped above as .tmp) is not a save, and the firing below
                # must not claim one happened.
                if fn.endswith(".bin"):
                    bin_copied_fn = fn
            if copied:
                log.info(
                    "Option C: clean bin persisted RAM->SSD trigger=%s "
                    "(%d file(s), thread_hash=%s, port=%s)",
                    trigger, copied, th[:12], port)
                if bin_copied_fn:
                    # this function is the sole writer of NEW bin/ckpt/meta
                    # content into the SSD tier -- but not the sole writer of
                    # SLOT_PERSIST_DIR full stop: _stale_mark_persist_sidecar
                    # (below) mutates an EXISTING sidecar's stale flag in
                    # place and emits no firing line, so a KV_SAVE_FIRING-only
                    # audit sees the last real copy here, not the most recent
                    # stale-mark. bin_id is the ACTUAL filename this loop just
                    # copied, not a reconstruction -- kv_save_fn's derivation
                    # happens to match it in the normal single-series case,
                    # but naming what was verified beats naming what was
                    # merely expected. trigger is deliberately the
                    # operation's own name, not the upstream idle/swap/
                    # shutdown/displacement/failure reason -- that reason
                    # isn't reachable here without changing this function's
                    # signature and its five call sites, which is beyond the
                    # scope of this change.
                    _log_kv_save_firing(
                        bin_id=bin_copied_fn,
                        thread_id=th, role="unavailable",
                        n_tokens="unavailable", nbytes="unavailable",
                        trigger="ssd_persist", tier="SSD",
                        call_site="persist_clean_bin_to_ssd_by_hash")
        except Exception:
            log.debug("Option C RAM->SSD persist best-effort failed", exc_info=True)

    def _shadow_lock_for(self, port: int, thread_hash: str) -> "asyncio.Lock":
        """Per-(port, thread_hash) shadow save-in-flight lock (see __init__). Creates
        it on first use. Opportunistically prunes UNHELD locks past the cap so the
        dict cannot leak across many distinct threads — a currently-HELD lock is
        never evicted (the single-series inline await holds at most one at a time)."""
        key = (port, thread_hash)
        locks = self._shadow_reprefill_locks
        lock = locks.get(key)
        if lock is None:
            if len(locks) >= _SHADOW_BYTEMATCH_CAP:
                for k in [k for k, lk in locks.items() if not lk.locked()]:
                    del locks[k]
            lock = locks.setdefault(key, asyncio.Lock())
        return lock

    async def _shadow_reprefill_and_save(self, handle, slot, result) -> None:
        """Option A (SAVE-side): after a MAIN generation, advance the warm
        slot to the THINK-FREE end-of-turn-N state and persist it under a DISTINCT
        `.shadow` bin, so a LATER restore (PL's SEPARATE restore-preference step)
        strict-extends instead of CLEAR+reprefilling.

        The qwen MTP hybrid recurrent ctx (n_rs_seq=2) bakes the generated <think>
        into the saved KV and CANNOT be trimmed post-hoc (seq_rm aborts/corrupts);
        the harness resends history think-STRIPPED next turn, so the saved state
        diverges at the generated <think> -> do_reset -> against-3 CLEAR. Fix: fire a
        prefill-only probe (n_predict=0) of the think-free history against the current
        warm slot — the LCP diverges at the just-generated <think> so the engine
        do_resets and fully reprefills the think-free prefix — then save THAT.

        Fired at the 4 post-completion hooks (streaming/non-streaming x anchor/active-
        match) AFTER the client already has the answer (set_result) => ZERO added
        response TTFT. ``result`` is the completion dict (non-streaming) or None
        (streaming; the with-<think> answer then comes from slot.streamed_assistant_
        text) — the SAME source the byte-match self-check + _engine_view_chain use.

        SAVE-ONLY, defense-in-depth:
        - INERT unless env TURBOHAUL_SHADOW_REPREFILL (ships off).
        - single-series gate ONLY (mirrors _probe_and_save_clean_kv): no concurrent
          eviction/fan-out between the reprefill, the save, and the next request.
        - DISTINCT `.shadow` bin + `shadow:true` meta: the clean_prefix anchor is left
          COMPLETELY intact (never routed through the never-demote clean path; a
          mispredicted shadow can never overwrite/demote the proven anchor).
        - the restore gate is NOT touched — the shadow bin is WRITTEN, not
          consumed here.
        - best-effort: NEVER raises into _process_slot, never delays the response."""
        try:
            if not _shadow_reprefill_enabled():
                return
            # OFF-PATH: single-series only (same gate _probe_and_save_clean_kv
            # uses — OBSERVED concurrency, not the static
            # cap; kept in lockstep so this inert path never diverges).
            _hp = int(max(1, getattr(handle, "parallel", 1)))
            if self._other_active_residents(handle) or _hp != 1:
                return
            tid = getattr(slot, "thread_id", "") or ""
            if not tid:
                return
            c = self._shadow_reprefill_counts
            # --- GUARDS (mirror _record_shadow_bytematch_probe EXACTLY): fire only on a
            #     positively-reconstructable, think-bearing, non-empty text turn. ------
            if result is None:
                # STREAMING: the SSE route stashed the merged <think> text on the slot.
                with_think = getattr(slot, "streamed_assistant_text", None)
            else:
                # NON-STREAMING: None => tool-call / noop / empty (not reconstructable).
                gen = self._generated_assistant_msg(result)
                if gen is None:
                    c["skipped_toolcall"] = c.get("skipped_toolcall", 0) + 1
                    log.info("SHADOW_SAVE th=%s model=%s slot=%s outcome=skipped:toolcall",
                             self._thread_hash(tid), getattr(slot, "model_tag", ""),
                             getattr(slot, "slot_id", None))
                    return
                with_think = gen.get("content")
            if not isinstance(with_think, str) or not with_think:
                c["skipped_empty"] = c.get("skipped_empty", 0) + 1
                log.info("SHADOW_SAVE th=%s model=%s slot=%s outcome=skipped:empty",
                         self._thread_hash(tid), getattr(slot, "model_tag", ""),
                         getattr(slot, "slot_id", None))
                return
            if "</think>" not in with_think:
                # Freshness: a no-think turn is ALREADY
                # think-free -> it is a VALID (and often the FRESHEST) shadow, especially
                # the last main turn before a model swap. Do NOT skip it: _strip_thinking_
                # all is a whitespace-only no-op here, so the save still yields the correct
                # think-free end-of-turn-N state that the harness will resend. (The tool-
                # call / empty / empty-after-strip / no-messages guards STILL skip below —
                # only the </think>-required gate is relaxed.) Count for observability.
                c["no_think_saved"] = c.get("no_think_saved", 0) + 1
            # Mirror the harness's remove-ALL think-strip so the shadow prefix byte-
            # matches the harness's think-stripped resend next turn (shadow_bytematch =
            # MATCH) — including multi-block / pre-<think> content, where the old
            # rsplit-last _strip_thinking_wrapper diverged (thinkstrip-
            # multiblock). Lazy import avoids a manager<->api cycle.
            from turbohaul.api.chat_completion import _strip_thinking_all
            think_free = _strip_thinking_all(with_think)
            if not think_free:
                c["skipped_empty"] = c.get("skipped_empty", 0) + 1
                log.info("SHADOW_SAVE th=%s model=%s slot=%s outcome=skipped:empty_after_strip",
                         self._thread_hash(tid), getattr(slot, "model_tag", ""),
                         getattr(slot, "slot_id", None))
                return
            # messages = the harness's OWN bytes for turns 1..N + the predicted think-
            # free assistant-N (== exactly what the harness resends next turn, minus
            # the not-yet-known user turn N+1).
            base_msgs = (getattr(slot, "client_meta", None) or {}).get("messages")
            if not base_msgs:
                c["skipped_no_messages"] = c.get("skipped_no_messages", 0) + 1
                log.info("SHADOW_SAVE th=%s model=%s slot=%s outcome=skipped:no_messages",
                         self._thread_hash(tid), getattr(slot, "model_tag", ""),
                         getattr(slot, "slot_id", None))
                return
            messages = list(base_msgs) + [{"role": "assistant", "content": think_free}]

            model_tag = slot.model_tag
            port = handle.port
            # Record the freshest think-free shadow
            # SOURCE for the model-swap teardown belt (_shadow_save_at_swap). Set BEFORE
            # the reprefill/save POST so a silently-failed save here can still be recovered
            # at the swap seam. Manager-level (not on the slot) so it tracks the LATEST
            # turn across anchor + grace-follow-up (active-match) slots — the outgoing slot
            # object is nulled at _process_slot finally, so a per-slot ref would go stale.
            # Keyed by identity so the teardown never re-saves a DIFFERENT thread's source.
            _ls_key = (tid, model_tag)
            if len(self._last_shadow_src) >= 64 and _ls_key not in self._last_shadow_src:
                self._last_shadow_src.popitem(last=False)
            self._last_shadow_src[_ls_key] = {
                "thread_id": tid, "model_tag": model_tag, "port": port,
                "messages": messages,
            }
            # move_to_end so the bounded
            # evict-oldest is TRUE LRU-by-use — a re-saving thread must not sit at
            # position 0 and get popitem(last=False)-evicted while actively fresh.
            self._last_shadow_src.move_to_end(_ls_key)
            # Shadow diagnostics (INSTRUMENTATION-ONLY): also stash the think-free
            # recon PER (thread_id, model_tag) so SHADOW_BYTEPARITY on a swap-back reads
            # THIS thread's source instead of a clobbering intervening save's. Bounded
            # (evict-oldest); best-effort; does NOT touch _last_shadow_src or any logic.
            try:
                _bpk = self._byteparity_recon_by_key
                if len(_bpk) >= 64 and (tid, model_tag) not in _bpk:
                    _bpk.pop(next(iter(_bpk)))
                _bpk[(tid, model_tag)] = think_free
            except Exception:
                pass
            th = self._thread_hash(tid)
            # Serialise the whole shadow WORK for THIS (port, thread) vs the series so a
            # save can't overlap the next turn reading a half-written shadow bin.
            async with self._shadow_lock_for(port, th):
                # 1. n_predict=0 SHADOW-PREFILL of the think-free messages against the
                #    current warm slot (Option A). SAME POST mechanism / params /
                #    timeouts as _probe_and_save_clean_kv's clean probe.
                _sh_meta = getattr(slot, "client_meta", None) or {}
                if self._covered_scaffold_strip_enabled():
                    # Render the shadow messages -> strip the
                    # covered-turn <think>...</think>\n\n scaffolds -> /completion prefill, so
                    # the .shadow bin byte-matches the harness's future think-stripped resend
                    # (including the empty scaffold the template emits for the appended
                    # think-free turn N in its still-current position). A failed engine call
                    # -> skip the save, exactly as the plain probe returns on a failed POST.
                    # This is a FULL reprefill (see this method's own docstring
                    # header), not a routine probe -- fired AFTER set_result (zero added
                    # response TTFT), so a stall here never blocks a live request the way
                    # the swap-critical-path sites below do. 900.0s kept deliberately, not
                    # inherited: prefill durations can have a long tail, so the
                    # bound has to allow for the slow end -- and
                    # a full reprefill skews toward the
                    # slow/large-context end of that distribution, not a random draw from it,
                    # so 900 is closer to right than a shorter bound would be, not an oversight.
                    if not await self._render_strip_prefill_probe(
                        port, model_tag, messages, _sh_meta, read_timeout_s=900.0
                    ):
                        c["reprefill_post_failed"] = c.get("reprefill_post_failed", 0) + 1
                        log.info("SHADOW_SAVE th=%s model=%s slot=%s outcome=post_failed turns=%d",
                                 th, model_tag, getattr(slot, "slot_id", None), len(messages))
                        return
                else:
                    # Flag OFF -> pre-Fix-B behavior, byte-identical to today.
                    payload = {
                        "model": model_tag,
                        "messages": messages,
                        "stream": False,
                        "n_predict": 0,
                        "max_tokens": 0,
                        "cache_prompt": True,
                    }
                    # crit1: same tool-preamble parity as the clean probe — the shadow bin
                    # must also match a tools-bearing request's front-of-prompt (else the
                    # cold/forced restore of the shadow CLEARs on every tool turn).
                    for _k in _KV_PROBE_TOOL_KNOBS:
                        _v = _sh_meta.get(_k)
                        if _v is not None:
                            payload[_k] = _v
                    url = f"http://127.0.0.1:{port}/v1/chat/completions"
                    try:
                        async with httpx.AsyncClient(
                            timeout=httpx.Timeout(connect=2.0, read=900.0, write=30.0, pool=2.0)
                        ) as client:
                            await client.post(url, json=payload)
                    except Exception:
                        c["reprefill_post_failed"] = c.get("reprefill_post_failed", 0) + 1
                        log.debug("shadow reprefill POST failed (best-effort)", exc_info=True)
                        log.info("SHADOW_SAVE th=%s model=%s slot=%s outcome=post_failed turns=%d",
                                 th, model_tag, getattr(slot, "slot_id", None), len(messages))
                        return
                # 2. SAVE the now-think-free slot under the DISTINCT .shadow marker.
                if await self._save_shadow_slot_kv(port, model_tag, tid, messages):
                    c["saved"] = c.get("saved", 0) + 1
                    log.info("shadow-reprefill KV saved (thread=%s, turns=%d)",
                             tid[:12], len(messages))
                    # Shadow diagnostics: per-call SAVED outcome — think_free_hash is
                    # computed here in the OFF-hot-path save code (this whole method runs
                    # AFTER set_result), NEVER on the response TTFT path. path/size ride
                    # the SHADOW_SAVE write=ok line inside _save_shadow_slot_kv.
                    log.info(
                        "SHADOW_SAVE th=%s model=%s slot=%s outcome=saved turns=%d "
                        "think_free_len=%d think_free_hash=%s",
                        th, model_tag, getattr(slot, "slot_id", None), len(messages),
                        len(think_free), _fnv1a_64(think_free))
        except Exception:
            log.debug("shadow reprefill+save best-effort failed", exc_info=True)

    async def _shadow_save_at_swap(self, handle, model_tag: str, thread_id: str) -> None:
        """Re-save a FRESH think-free shadow of
        the OUTGOING slot at the model-swap teardown seam — as close to SIGTERM as
        possible so swap-back strict-extends the byte-matching think-free [1..N] state
        instead of a fresh full prefill.

        WHY read the manager field, not the slot (a real finding): at
        _teardown_idle_holder the outgoing slot OBJECT is already gone (POPPED ->
        _set_active_slot(None) in _process_slot's finally), and the idle holder retains
        only handle/model_tag/thread_id/ctx_len — NOT client_meta.messages. So this reads
        the manager-level ``_last_shadow_src`` (the freshest think-free ``messages``
        recorded by the last per-turn _shadow_reprefill_and_save — which also correctly
        tracks the LATEST grace-follow-up turn, not the stale anchor slot).

        SAFE by construction (constraints #2 + #5):
        - INERT unless TURBOHAUL_SHADOW_REPREFILL (same SAVE gate as the per-turn hook).
        - identity-matched: only re-saves the source recorded for THIS outgoing
          (thread_id, model_tag) — never guesses / never cross-thread.
        - NO-DOWNGRADE: if a shadow with an EQUAL-OR-LONGER chain already exists (the
          per-turn hook already saved the freshest, or a later grace turn extended it),
          it does NOTHING — a stale/shorter source can NEVER overwrite a fresher shadow.
          So it only ADDS value when the last per-turn save POST silently failed
          (existing shadow shorter/absent), recovering it right at the swap seam.
        - single-bin overwrite via _save_shadow_slot_kv's os.replace (constraint #5, NO
          ring); serialized under the same per-(port,thread) shadow lock.
        - best-effort: never raises into teardown; in the COMMON case the no-downgrade
          check short-circuits BEFORE any reprefill POST, so it adds ZERO swap latency
          (a reprefill only runs in the rare failed-save recovery).

        Reuses the exact reprefill(n_predict=0)+save mechanism as _shadow_reprefill_and_
        save, so a bin it writes is byte-identical to what the per-turn path would."""
        try:
            if not _shadow_reprefill_enabled():
                return
            src = self._last_shadow_src.get((thread_id, model_tag))
            if not src:
                return  # no fresh source for THIS outgoing thread -> skip (never guess)
            messages = src.get("messages")
            if not messages:
                return
            port = handle.port
            new_len = len(_prefix_hash_chain(messages))
            if new_len <= 0:
                return
            c = self._shadow_reprefill_counts
            log.info("SHADOW_SAVE swapbelt=fired th=%s model=%s new_len=%d",
                     self._thread_hash(thread_id), model_tag, new_len)
            # NO-DOWNGRADE: never overwrite an equal-or-longer existing shadow (protects
            # the freshest per-turn shadow; a stale/same-length source is refused here).
            existing = self._find_shadow_bin(port, model_tag, thread_id)
            if existing is not None and len(existing[1]) >= new_len:
                c["swap_skip_have_fresher"] = c.get("swap_skip_have_fresher", 0) + 1
                log.info("SHADOW_SAVE swapbelt=short_circuit_have_fresher th=%s model=%s "
                         "existing_len=%d new_len=%d",
                         self._thread_hash(thread_id), model_tag, len(existing[1]), new_len)
                return
            th = self._thread_hash(thread_id)
            async with self._shadow_lock_for(port, th):
                # reprefill the think-free messages (n_predict=0) so the engine slot holds
                # the think-free state, then SAVE — SAME mechanism/params as the per-turn
                # hook. Reached only when the per-turn save is missing/shorter (rare).
                # This recovery reprefill is AWAITED before the swap's
                # _sigterm, so an unbounded read (900s) could STALL the model swap. Bound it
                # to 180s (a healthy think-free reprefill is ~158s) so the worst-case teardown
                # block stays far below 900s; a slow reprefill times out -> best-effort give-up.
                if self._covered_scaffold_strip_enabled():
                    # The swap-seam recovery re-saves the SAME
                    # think-free messages, so it MUST render+strip identically to the per-turn
                    # _shadow_reprefill_and_save above — else this recovery bin would carry the
                    # covered-turn scaffold Fix B removes and become a position-drifted restore
                    # target (breaking this method's "byte-identical to the per-turn path"
                    # contract). No client_meta at the swap seam (the slot object is gone), so
                    # no tool-knob source -> renders tools-less, matching the pre-Fix-B swap
                    # payload (which also omitted _KV_PROBE_TOOL_KNOBS). Bounded to 180s.
                    if not await self._render_strip_prefill_probe(
                        port, model_tag, messages, {}, read_timeout_s=180.0
                    ):
                        c["swap_reprefill_post_failed"] = c.get("swap_reprefill_post_failed", 0) + 1
                        log.info("SHADOW_SAVE swapbelt=post_failed th=%s model=%s new_len=%d",
                                 th, model_tag, new_len)
                        return
                else:
                    # Flag OFF -> pre-Fix-B behavior, byte-identical to today.
                    payload = {
                        "model": model_tag, "messages": messages, "stream": False,
                        "n_predict": 0, "max_tokens": 0, "cache_prompt": True,
                    }
                    url = f"http://127.0.0.1:{port}/v1/chat/completions"
                    try:
                        async with httpx.AsyncClient(
                            timeout=httpx.Timeout(connect=2.0, read=180.0, write=30.0, pool=2.0)
                        ) as client:
                            await client.post(url, json=payload)
                    except Exception:
                        c["swap_reprefill_post_failed"] = c.get("swap_reprefill_post_failed", 0) + 1
                        log.debug("swap-seam shadow reprefill POST failed (best-effort)", exc_info=True)
                        log.info("SHADOW_SAVE swapbelt=post_failed th=%s model=%s new_len=%d",
                                 th, model_tag, new_len)
                        return
                if await self._save_shadow_slot_kv(port, model_tag, thread_id, messages):
                    c["swap_saved"] = c.get("swap_saved", 0) + 1
                    log.info("swap-seam shadow KV re-saved (thread=%s, turns=%d)",
                             (thread_id or "")[:12], len(messages))
                    log.info("SHADOW_SAVE swapbelt=resaved th=%s model=%s new_len=%d turns=%d",
                             th, model_tag, new_len, len(messages))
        except Exception:
            log.debug("swap-seam shadow save best-effort failed", exc_info=True)

    async def _save_shadow_slot_kv(
        self, port: int, model_tag: str, thread_id: str, messages: list
    ) -> bool:
        """Atomic tmp+os.replace persist of the CURRENT (think-free) slot KV under the
        DISTINCT `.shadow` bin + a `shadow:true` meta sidecar carrying the think-free
        hash_chain / fingerprint. Deliberately does NOT reuse _save_slot_kv: the
        shadow bin must NEVER route through the clean_prefix never-demote/skip path —
        it is a SEPARATE artifact from the anchor, so a mispredicted shadow can never
        overwrite or demote the proven clean_prefix anchor. Requires exactly ONE
        populated slot (the single-series invariant) so the save maps unambiguously to
        this thread; anything else -> skip (never guess). Returns True iff a shadow bin
        was written. Best-effort; never raises."""
        if '/' in model_tag or '\\' in model_tag or '..' in model_tag:
            log.warning("shadow KV: refusing model_tag with unsafe path chars: %r", model_tag)
            return False
        from turbohaul.subprocess_mgr import SLOT_SAVE_DIR
        th = self._thread_hash(thread_id)
        # think-free hash_chain (SAME chokepoint + shape as the clean/normal save);
        # an empty chain is unrestorable -> never write a degenerate shadow bin.
        hash_chain = _prefix_hash_chain(messages)
        if not hash_chain:
            return False
        prompt_len_val = compute_ctx_len(messages)
        _fp = self._engine_fingerprint(model_tag)
        try:
            async with httpx.AsyncClient(
                timeout=httpx.Timeout(connect=1.0, read=120.0, write=120.0, pool=1.0)
            ) as client:
                resp = await client.get(f"http://127.0.0.1:{port}/slots")
                resp.raise_for_status()
                slots_data = resp.json()
                populated = [s for s in slots_data
                             if (s.get("n_prompt_tokens") or 0) > 0 and s.get("id") is not None]
                if len(populated) != 1:
                    # ambiguous (co-resident / none) — do NOT guess which slot is ours.
                    log.debug("shadow KV save skip: %d populated slots (want exactly 1)",
                              len(populated))
                    return False
                s = populated[0]
                sid = int(s["id"])
                n_prompt_tokens = s.get("n_prompt_tokens") or 0
                os.makedirs(SLOT_SAVE_DIR, exist_ok=True)
                bin_fn = _kv_shadow_save_fn(model_tag, sid, th, port)
                tmp_path = os.path.join(SLOT_SAVE_DIR, f"{bin_fn}.tmp")
                final_path = os.path.join(SLOT_SAVE_DIR, bin_fn)
                # Engine save to temp, then atomic rename (a reader sees the old bin or
                # the fully-written new one, never a partial).
                save_resp = await client.post(
                    f"http://127.0.0.1:{port}/slots/{sid}?action=save",
                    json={"filename": f"{bin_fn}.tmp"},
                )
                save_resp.raise_for_status()
                os.replace(tmp_path, final_path)
                # Finalize the .ckpt ladder sidecar (bin FIRST, this best-effort).
                _finalize_ckpt_sidecar(tmp_path, final_path, bin_fn)
                # Invalidate scan cache after writing a bin/sidecar in SLOT_SAVE_DIR.
                self._kvcache_scan_cache_invalidate()
                meta = {
                    "thread_id": thread_id,
                    "thread_hash": th,
                    "prompt_tokens": n_prompt_tokens,
                    "prompt_len": prompt_len_val,
                    "n_context_turns": len(hash_chain),
                    "hash_chain": hash_chain,
                    "prompt_hash": "",
                    "model_tag": model_tag,
                    "slot_id": sid,
                    "port": port,
                    # DISTINCT MARKER: NOT a clean anchor. clean_prefix=False keeps it
                    # invisible to _find_clean_bin / the GC clean-pin / the clean-save
                    # skip+never-demote checks (all gate on clean_prefix); shadow=True
                    # tags it for PL's separate restore-preference step.
                    "clean_prefix": False,
                    "shadow": True,
                    # WIN 4 fingerprint (SAME as clean/normal save) so a stale shadow
                    # bin from a different build/model/ctx is purged, never restored.
                    "gguf_sha256": _fp.get("gguf_sha256"),
                    "engine_build_id": _fp.get("engine_build_id"),
                    "n_ctx": _fp.get("n_ctx"),
                    "n_rs_seq": _fp.get("n_rs_seq"),
                    "fp_gen": _fp.get("fp_gen"),
                }
                meta_fn = _kv_shadow_meta_fn(model_tag, sid, th, port)
                meta_tmp = os.path.join(SLOT_SAVE_DIR, f"{meta_fn}.tmp")
                meta_path = os.path.join(SLOT_SAVE_DIR, meta_fn)
                with open(meta_tmp, "w") as f:
                    json.dump(meta, f)
                os.replace(meta_tmp, meta_path)
                # Invalidate scan cache after writing a bin/sidecar in SLOT_SAVE_DIR.
                self._kvcache_scan_cache_invalidate()
                log.info("shadow KV saved: %s (turns=%d, tokens=%d)",
                         bin_fn, len(hash_chain), n_prompt_tokens)
                # Shadow diagnostics: the actual write result — path + on-disk byte
                # size (candidate (a) distinguisher: WAS a shadow bin written, and how
                # big). Off the hot path (this method runs from the post-set_result
                # save code). getsize best-effort so it can never fault the save.
                try:
                    _bin_size = os.path.getsize(final_path)
                except OSError:
                    _bin_size = -1
                log.info("SHADOW_SAVE write=ok th=%s model=%s path=%s size=%d turns=%d tokens=%d",
                         th, model_tag, bin_fn, _bin_size, len(hash_chain), n_prompt_tokens)
                return True
        except Exception:
            log.debug("shadow KV save best-effort failed for %s", model_tag, exc_info=True)
            log.info("SHADOW_SAVE write=fail th=%s model=%s", th, model_tag)
            return False

    async def _save_slot_kv(
        self, port: int, model_tag: str, slot=None, *,
        thread_id_override: str | None = None,
        admission_ctx_len_override: int | None = None,
        force_clean: bool = False,
        client_meta_override: dict | None = None,
    ) -> bool:
        """The engine_op badge is scoped to the op —
        set on entry, ALWAYS reset in the finally (ReadTimeout/4xx/early-return
        included), or /status advertises kv_save forever on the worker_loop
        path (a display lie of the class Waves D/E killed)."""
        if slot is not None:
            slot.engine_op = "kv_save"
        try:
            return await self._save_slot_kv_inner(
                port, model_tag, slot,
                thread_id_override=thread_id_override,
                admission_ctx_len_override=admission_ctx_len_override,
                force_clean=force_clean,
                client_meta_override=client_meta_override,
            )
        finally:
            if slot is not None:
                slot.engine_op = "idle"

    async def _save_slot_kv_inner(
        self, port: int, model_tag: str, slot=None, *,
        thread_id_override: str | None = None,
        admission_ctx_len_override: int | None = None,
        force_clean: bool = False,
        client_meta_override: dict | None = None,
    ) -> bool:
        """Best-effort persist KV + metadata sidecar before sidecar reaped.
        SPEC-V2: returns True iff at least ONE slot's bin+meta pair was fully
        persisted (engine save 2xx + atomic bin rename + meta rename).
        Uses resolve_kv() chokepoint for decision + provenance logging.

        Args:
            thread_id_override: If set, use this thread_id instead of slot.thread_id.
                Used by idle-holder teardown to save with the original thread_id.
            admission_ctx_len_override: If set, use this for prompt_len in metadata
                instead of computing from slot.context/prompt. Used by idle-holder
                teardown to preserve the admission-time context length.
        """
        if '/' in model_tag or '\\' in model_tag or '..' in model_tag:
            log.warning("slot KV: refusing model_tag with unsafe path chars: %r", model_tag)
            return
        # ENFORCEMENT CHOKEPOINT. This is the SINGLE funnel
        # for every engine /slots?action=save (probe force_clean, idle-teardown
        # direct, _teardown, resident teardowns). (D1) Never save while this
        # port's VRAM tip holds foreign non-main tokens: the bin would be a
        # superset of the stamped hash_chain — an internally inconsistent triplet
        # that PASSES the restore prefix gate and aborts the engine at strict
        # extension. Remediation (erase + canonical reprefill) lives in the probe
        # seam path and clears the flag before calling us. (D2) Never save a
        # disposable-owned identity (single resolve point _seam_flush_allowed).
        # False = unconfirmed save, same contract as every other refusal.
        _dirty = (getattr(self, "_kv_dirty_tail", {}) or {}).get(port)
        _eff_tid = (thread_id_override if thread_id_override is not None
                    else (getattr(slot, "thread_id", "") if slot else "")) or ""
        if _dirty:
            log.warning(
                "slot KV save REFUSED (dirty tip): port=%s foreign role=%s (via "
                "thread=%s) would poison bin for thread_id=%s — previous bin kept",
                port, _dirty.get("role"), str(_dirty.get("thread"))[:40],
                (_eff_tid or "?")[:60])
            return False
        _eff_meta = (client_meta_override if client_meta_override is not None
                     else (getattr(slot, "client_meta", None) if slot else None))
        _allowed, _save_role = _seam_flush_allowed(_eff_tid, _eff_meta)
        if not _allowed:
            log.warning(
                "slot KV save REFUSED (D2 disposable identity): role=%s thread=%s "
                "— no bin written", _save_role, (_eff_tid or "?")[:60])
            return False
        from turbohaul.subprocess_mgr import SLOT_SAVE_DIR
        try:
            # A short read timeout can starve a multi-GB engine action=save mid-decode
            # (chronic 'slot KV save failed' -> frozen anchor + .tmp orphan leak).
            async with httpx.AsyncClient(timeout=httpx.Timeout(connect=1.0, read=120.0, write=120.0, pool=1.0)) as client:
                resp = await client.get(f"http://127.0.0.1:{port}/slots")
                resp.raise_for_status()
                slots_data = resp.json()
                # Save ALL populated slots (each keyed by its own identity)
                populated = [s for s in slots_data if (s.get("n_prompt_tokens") or 0) > 0 and s.get("id") is not None]
                if not populated:
                    log.debug("slot KV save: no populated slots")
                    return
                # Only stamp clean_prefix when exactly ONE slot is
                # populated (unambiguous single-thread mapping) to avoid mis-marking a
                # co-resident thread's polluted KV as clean.
                _eff_force_clean = bool(force_clean) and len(populated) == 1
                # Compute the loaded engine's build/model/ctx
                # fingerprint ONCE per save (not per slot). Sources are already
                # known to the manager (manifest gguf sha + boot.runtime binary sha
                # + manifest ctx/parallel) — this NEVER hashes the multi-GB gguf
                # (it uses the manifest's precomputed gguf_blob_sha256). Stamped
                # into each slot's meta below + compared by _purge_mismatched_bins.
                _fp = self._engine_fingerprint(model_tag)
                saved_any = False  # SPEC-V2: confirmed-save signal (A10 return)
                for s in populated:
                    sid = int(s["id"])
                    n_prompt_tokens = s.get("n_prompt_tokens") or 0
                    # Caller override (idle_holder's thread_id) is ONLY
                    # safe when exactly ONE slot is populated — with >1 co-resident
                    # slot the override would mis-key every engine slot under one
                    # identity, producing a wrong-conversation bin on restore.
                    _use_override = thread_id_override is not None and len(populated) == 1
                    if _use_override:
                        thread_id = thread_id_override
                    elif thread_id_override is not None:
                        # multi-slot: override suppressed, key each engine slot on
                        # its OWN thread_id from the /slots response
                        thread_id = s.get("thread_id", "") or (getattr(slot, "thread_id", "") if slot else "")
                    else:
                        thread_id = getattr(slot, "thread_id", "") if slot else ""
                    # SPEC-V2 WAVE A: key the bin on the (session_id, role[, fp8])
                    # identity. Idle-holder teardown (slot=None) falls back to the
                    # manager-held idle client_meta ONLY when the override tid IS the
                    # idle holder's tid — any other slot=None
                    # caller keys on the raw thread_id (today's behavior).
                    if client_meta_override is not None and _use_override:
                        # _teardown_idle_holder clears
                        # self._idle_thread_id BEFORE the flush/save block, so the
                        # elif below can never match at that seam — the save fell
                        # to RAW thread_id keying, wrote a ~10GB duplicate bin
                        # (defeating the clean-present skip), exhausted the tmpfs
                        # and caused the 22:30Z ENOSPC truncation. The teardown
                        # now passes its stashed idle meta explicitly; explicit
                        # caller intent outranks whatever _active_slot holds.
                        _cm = client_meta_override
                        _p_msgs = (client_meta_override or {}).get("messages")
                        _idc = _prefix_hash_chain(_p_msgs) if _p_msgs else None
                    elif slot is not None:
                        _cm = getattr(slot, "client_meta", None)
                        _idc = getattr(slot, "admission_hash_chain", None)
                        # multi-slot + override suppressed — suppress
                        # the active slot's client_meta too so each engine slot
                        # keys on raw thread_id (not a co-resident's session bin).
                        if thread_id_override is not None and not _use_override:
                            _cm, _idc = None, None
                    elif thread_id and thread_id == self._idle_thread_id:
                        _cm = self._idle_client_meta
                        _idc = None
                    else:
                        # cap>=2 here gives (None,None) — same as if
                        # the branch had matched. Benign; no behaviour difference.
                        _cm, _idc = None, None
                    bin_ident = _bin_identity(thread_id, _cm, _idc)
                    thread_hash = self._thread_hash(bin_ident)
                    # A teardown/normal save (NOT force_clean) must
                    # NOT overwrite an existing clean-prefix bin with a post-generation
                    # (think-polluted) KV. Only the explicit probe-save (force_clean)
                    # may (over)write clean bins. Skip this slot if a clean bin exists.
                    if not force_clean:
                        _has_clean = False
                        try:
                            for _fn in os.listdir(SLOT_SAVE_DIR):
                                if (_fn.startswith(f"{model_tag}.") and _fn.endswith(".json")
                                        and f".p{port}.{thread_hash}." in _fn):
                                    with open(os.path.join(SLOT_SAVE_DIR, _fn)) as _mf:
                                        if json.load(_mf).get("clean_prefix"):
                                            _has_clean = True
                                            break
                        except Exception:
                            pass
                        if _has_clean:
                            log.info("slot KV save skip: clean_prefix bin present (thread_hash=%s)",
                                     thread_hash)
                            continue
                    # NEVER-DEMOTE invariant (critical safety). A
                    # force_clean save that resolved to _eff_force_clean=False (i.e.
                    # len(populated) != 1) would stamp clean_prefix=False below and
                    # OVERWRITE the anchor bin -> demote clean_prefix True->False.
                    # _find_clean_bin + the GC pin then lose the anchor, the restore
                    # classifier disarms, and EVERY request goes FRESH (worse than the
                    # sawtooth lag). Abort THIS slot's save when a clean anchor already
                    # exists for this (model_tag, thread_hash, port). (The force_clean=
                    # False path is already covered by the skip guard above; this closes
                    # the force_clean=True-but-multi-slot hole.)
                    if force_clean and not _eff_force_clean:
                        _demote_clean = False
                        try:
                            for _fn in os.listdir(SLOT_SAVE_DIR):
                                if (_fn.startswith(f"{model_tag}.") and _fn.endswith(".json")
                                        and f".p{port}.{thread_hash}." in _fn):
                                    with open(os.path.join(SLOT_SAVE_DIR, _fn)) as _mf:
                                        if json.load(_mf).get("clean_prefix"):
                                            _demote_clean = True
                                            break
                        except Exception:
                            pass
                        if _demote_clean:
                            log.warning("clean-bin re-save ABORTED (never-demote): would lower "
                                        "clean_prefix True->False for thread_hash=%s", thread_hash)
                            continue
                    # Curator save-gate. When the curator
                    # reuse-main route is active, a curator turn must NOT save/overwrite
                    # a bin (it rides on main's anchor; saving would poison it). Gate is
                    # flag-gated + label-gated -> inert with the flag off or labels absent.
                    if _curator_reuse_main_active():
                        from turbohaul.kv_classify import POLICIES, _class_from_label
                        _labels = (getattr(slot, "client_meta", None) or {}) if slot else {}
                        _lc = _class_from_label(_labels)
                        if _lc is not None and not POLICIES[_lc].save_ok:
                            log.info("slot KV save skip: curator route save_ok=False (thread_hash=%s)", thread_hash)
                            continue
                    # Policy decision
                    decision = resolve_kv("save", {
                        "thread_id": bin_ident,
                        "model_tag": model_tag,
                        "slot_id": sid,
                        "port": port,
                    }, {
                        "saved_tokens": n_prompt_tokens,
                    })
                    log.info("slot KV save decision: %s", decision)
                    if not decision.do_it:
                        continue
                    # Per-slot try/except: one bad slot doesn't kill the others
                    try:
                        bin_fn = kv_save_fn(model_tag, sid, thread_hash, port)
                        # Atomic save: write temp then rename
                        tmp_path = os.path.join(SLOT_SAVE_DIR, f"{bin_fn}.tmp")
                        final_path = os.path.join(SLOT_SAVE_DIR, bin_fn)
                        os.makedirs(SLOT_SAVE_DIR, exist_ok=True)
                        # a later phase T-GUARD (ENOSPC truncation, proven
                        # 22:30Z): a full tmpfs let the engine short-write a
                        # 1.17GB bin for a 198k-token state and still return
                        # 200; the truncated bin then overwrote the good SSD
                        # copy. Expected size is self-calibrated from THIS
                        # thread's previous meta (bytes scale ~linearly with
                        # tokens for a given model; no absolute floor — unit
                        # tests legitimately save tiny bins). No prior meta ->
                        # no estimate -> guards skip (first-save residual
                        # accepted).
                        _exp_bytes = None
                        try:
                            _old_meta_p = os.path.join(
                                SLOT_SAVE_DIR, kv_meta_fn(model_tag, sid, thread_hash, port))
                            if os.path.exists(_old_meta_p):
                                with open(_old_meta_p) as _omf:
                                    _om = json.load(_omf)
                                _ob, _ot = _om.get("bin_bytes"), _om.get("prompt_tokens")
                                if _ob and _ot and n_prompt_tokens:
                                    _exp_bytes = float(_ob) * (float(n_prompt_tokens) / float(_ot))
                        except Exception:
                            _exp_bytes = None
                        if _exp_bytes:
                            try:
                                _st = os.statvfs(SLOT_SAVE_DIR)
                                _avail = _st.f_bavail * _st.f_frsize
                            except OSError:
                                _avail = None
                            if _avail is not None and _avail < _exp_bytes * 1.05:
                                log.error(
                                    "slot KV save SKIPPED (T-GUARD pre-flight): avail=%d < need~%d "
                                    "for %s — keeping previous intact bin",
                                    _avail, int(_exp_bytes * 1.05), bin_fn)
                                continue
                        # ONE decision, one place, with its source recorded. A save must
                        # stop where the client's next request will stop, and the only
                        # number that means that is the token count of the clean prompt
                        # actually rendered and prefilled for this engine. The slot's own
                        # prompt length is a different quantity: it also covers what was
                        # generated after that render, which the client strips before
                        # sending it back, so capping there leaves a surplus the restore
                        # cannot reconcile. Prefer the render's count; fall back to the
                        # slot's only when no clean boundary is known, and say which was
                        # used -- a cap whose provenance is invisible is a cap nobody can
                        # debug when the restore later disagrees with it.
                        _clean_tok = self._clean_prefill_tokens.get(port)
                        _gate_on = _clean_stamp_evidence_gate_enabled()
                        # The save side resolves the
                        # save-context turn-hash fingerprint from the SAME
                        # messages source the meta build below uses
                        # (slot.client_meta["messages"], then the _cm override)
                        # with the IDENTICAL _chain_fp derivation the probe
                        # writers bound their evidence with — a coherent seam
                        # compares equal by construction.
                        _save_ctx_msgs = ((getattr(slot, "client_meta", None) or {}).get("messages")
                                          or (_cm or {}).get("messages"))
                        _save_fp = _chain_fp(_prefix_hash_chain(_save_ctx_msgs)) if _save_ctx_msgs else ""
                        if _clean_tok is not None:
                            _cap, _cap_src = _clean_tok.count, "clean_prefill"
                        else:
                            _cap, _cap_src = n_prompt_tokens, "slot_n_prompt_tokens"
                        # A clean stamp is a claim that this
                        # bin ends at a clean turn boundary FOR THE CONTEXT BEING
                        # SAVED. ONE decision, single-lever kill-switch
                        # semantics — TURBOHAUL_CLEAN_STAMP_EVIDENCE_GATE=0
                        # short-circuits the ENTIRE evidence gate (existence +
                        # extent + context + poison checks) back to the pre-fix stamp behaviour:
                        #   lever OFF            -> clean on whatever cap is
                        #       available (evidence count if present, else the
                        #       slot fallback), loud per save.
                        #   lever ON, no evidence -> DECLINE the whole save
                        #       (NO bin written; previous bin kept).
                        #   lever ON, evidence    -> extent congruence (slot
                        #       live count vs the recorded render count, within
                        #       _CLEAN_STAMP_EVIDENCE_EPS) AND context
                        #       binding (evidence chain_fp == save-context fp)
                        #       AND poison guard (save fp not retired as
                        #       reuse-zero poison). A mismatch DECLINES THE
                        #       STAMP ONLY — the save proceeds as a NON-CLEAN
                        #       bin on the slot fallback cap (never the
                        #       whole-save skip of NO_PROBE_EVIDENCE).
                        # The slot's n_prompt_tokens ALSO covers what was
                        # generated after the clean boundary (the think-stripped
                        # resend never contains it) — that is the poison bin of
                        # a post-generation dump; the ordinary save path is unaffected (it
                        # never stamps clean).
                        if not _eff_force_clean:
                            _clean_stamp = False
                        elif not _gate_on:
                            # Ops kill-switch (TURBOHAUL_CLEAN_STAMP_EVIDENCE_GATE=0):
                            # pre-fix stamp behaviour restored — clean on
                            # whatever cap is available — loud per save so the
                            # risk taken is visible in the logs.
                            log.warning(
                                "CLEAN_STAMP_EVIDENCE_GATE disabled — force_clean "
                                "save STAMPED CLEAN on the %s cap "
                                "(pre-fix risk re-enabled, operator "
                                "override; port=%s slot=%d)",
                                _cap_src, port, sid)
                            _clean_stamp = True
                        elif _clean_tok is None:
                            log.warning(
                                "clean-prefix save DECLINED (no probe evidence): "
                                "force_clean save without a recorded clean-prefill "
                                "token count would stamp clean_prefix=True on a "
                                "post-generation slot dump — NO bin written; "
                                "previous bin kept (port=%s slot=%d "
                                "n_prompt_tokens=%s thread_hash=%s)",
                                port, sid, n_prompt_tokens, thread_hash)
                            _log_kv_save_decline(
                                KV_DECLINE_NO_PROBE_EVIDENCE, thread_id=_eff_tid,
                                call_site="save_slot_kv_inner")
                            continue
                        else:
                            # Extent congruence — the recorded render count
                            # must match the slot's live count (single-series
                            # gate: both are MTP-draft-free, same tokenization
                            # of the same context; EPS covers edge noise).
                            _evidence_extent_mismatch = abs(n_prompt_tokens - _clean_tok.count) > _CLEAN_STAMP_EVIDENCE_EPS
                            # Context binding — the evidence must have been
                            # recorded for THIS context's turn-hash chain.
                            _evidence_chain_mismatch = _clean_tok.chain_fp != _save_fp
                            if _evidence_extent_mismatch or _evidence_chain_mismatch:
                                log.warning(
                                    "clean-prefix STAMP declined (evidence mismatch): "
                                    "force_clean save proceeds NON-CLEAN on the slot "
                                    "cap — extent_mismatch=%s chain_mismatch=%s "
                                    "evidence_count=%d slot_n_prompt_tokens=%d "
                                    "port=%s slot=%d thread_hash=%s",
                                    _evidence_extent_mismatch, _evidence_chain_mismatch, _clean_tok.count, n_prompt_tokens,
                                    port, sid, thread_hash)
                                _log_kv_save_decline(
                                    KV_DECLINE_EVIDENCE_MISMATCH, thread_id=_eff_tid,
                                    call_site="save_slot_kv_inner")
                                _clean_stamp = False
                                _cap, _cap_src = n_prompt_tokens, "slot_n_prompt_tokens"
                            elif _save_fp and _save_fp in (self._poisoned_chain_fps.get(port) or ()):
                                # Poison guard (anti-churn): this exact context's clean bin
                                # already proved poison (reused-to-zero on the
                                # engine's own heartbeat) and was retired — do
                                # not re-stamp it. A fresh probe re-recording
                                # evidence for this context discards the fp.
                                log.warning(
                                    "clean-prefix STAMP declined (poison re-probe): "
                                    "this context's clean bin already proved poison "
                                    "(reused-to-zero) — force_clean save proceeds "
                                    "NON-CLEAN on the slot cap "
                                    "(port=%s slot=%d thread_hash=%s)",
                                    port, sid, thread_hash)
                                _log_kv_save_decline(
                                    KV_DECLINE_POISON_REPROBE, thread_id=_eff_tid,
                                    call_site="save_slot_kv_inner")
                                _clean_stamp = False
                                _cap, _cap_src = n_prompt_tokens, "slot_n_prompt_tokens"
                            else:
                                _clean_stamp = True
                        # Trigger engine save to temp file first
                        # Cap the write at n_prompt_tokens (read from THIS
                        # slot's own /slots GET above, engine-reported, never
                        # re-derived/hardcoded here). action=save persists
                        # every populated KV cell regardless of the slot's
                        # current logical prompt length; a shorter prefill
                        # (e.g. the clean-prefix strip-probe) only overwrites
                        # cells up to the new length, so cells beyond it can
                        # still hold a longer prior generation's tokens. The
                        # engine already supports capping the write at exactly
                        # save_token_limit tokens (server-side, independent of
                        # physical cell population) -- wire it so every save
                        # persists what the engine itself currently considers
                        # the prompt, not whatever is physically left in VRAM.
                        save_resp = await client.post(
                            f"http://127.0.0.1:{port}/slots/{sid}?action=save",
                            json={
                                "filename": f"{bin_fn}.tmp",
                                "save_token_limit": _cap,
                            },
                        )
                        save_resp.raise_for_status()
                        # The engine reports back what it ACTUALLY wrote: n_saved is the
                        # effective (post-cap) token count and n_written the byte count.
                        # Without this the save is unobservable -- a limit that the engine
                        # silently ignored and a limit that was honoured look identical from
                        # here, and the only remaining evidence is the next restore's stale
                        # value, by which point the cause is two steps away. Log what was
                        # asked for beside what came back so the two can never be confused.
                        try:
                            _sv = save_resp.json()
                            _n_saved = _sv.get("n_saved")
                            log.info(
                                "KV_SAVE_ACK limit_sent=%s src=%s slot_n_prompt_tokens=%s "
                                "n_saved=%s n_written=%s honoured=%s bin=%s "
                                "probed_chain_fp=%s probed_arm=%s evidence_delta=%s",
                                _cap, _cap_src, n_prompt_tokens, _n_saved,
                                _sv.get("n_written"),
                                "unknown" if _n_saved is None else (_n_saved == _cap),
                                bin_fn,
                                (_clean_tok.chain_fp if _clean_tok is not None else None),
                                (_clean_tok.arm if _clean_tok is not None else None),
                                ((n_prompt_tokens - _clean_tok.count) if _clean_tok is not None else None),
                            )
                        except Exception:
                            log.info("KV_SAVE_ACK limit_sent=%s src=%s n_saved=unparseable bin=%s",
                                     _cap, _cap_src, bin_fn)
                        if _exp_bytes:
                            try:
                                _new_bytes = os.path.getsize(tmp_path)
                            except OSError:
                                _new_bytes = None
                            if _new_bytes is not None and _new_bytes < 0.5 * _exp_bytes:
                                log.error(
                                    "slot KV save REJECTED (T-GUARD): %s bytes=%d expected~%d "
                                    "— truncated write (ENOSPC?); previous bin kept",
                                    bin_fn, _new_bytes, int(_exp_bytes))
                                # The engine also writes a .tmp.ckpt ladder
                                # sidecar (finalized only on success) — remove the
                                # twin too or the reject leaks tmpfs space exactly
                                # when space is already critical.
                                for _orph in (tmp_path, tmp_path + ".ckpt"):
                                    try:
                                        os.remove(_orph)
                                    except OSError:
                                        pass
                                continue
                        # PAIR-GUARD: the .ckpt ladder sidecar must
                        # land WITH the bin (KV contract: the pair moves together). A
                        # full tmpfs let a bin land while its ckpt silently truncated
                        # or vanished (live pair: bin@07:54 vs ckpt@07:45) — restored
                        # ladders then break and every rollback collapses to an
                        # ancient checkpoint or pos 0. Reject the PAIR unless the tmp
                        # ckpt is plausibly sized (>=10%% of bin; observed 0.5-2.2x).
                        # A model that never produces ckpts (no prior final ckpt and
                        # no tmp ckpt) passes untouched.
                        if _ckpt_sidecar_enabled():
                            try:
                                _ck_bytes = os.path.getsize(tmp_path + ".ckpt")
                            except OSError:
                                _ck_bytes = None
                            try:
                                _bin_bytes_now = os.path.getsize(tmp_path)
                            except OSError:
                                _bin_bytes_now = None
                            _ck_expected = os.path.exists(final_path + ".ckpt")
                            _ck_bad = (
                                (_ck_bytes is None and _ck_expected)
                                or (_ck_bytes is not None and _bin_bytes_now
                                    and _ck_bytes < 0.10 * _bin_bytes_now)
                            )
                            if _ck_bad:
                                log.error(
                                    "slot KV save REJECTED (PAIR-GUARD): %s ckpt_bytes=%s "
                                    "bin_bytes=%s — ckpt sidecar missing/truncated (ENOSPC?); "
                                    "previous pair kept", bin_fn, _ck_bytes, _bin_bytes_now)
                                for _orph in (tmp_path, tmp_path + ".ckpt"):
                                    try:
                                        os.remove(_orph)
                                    except OSError:
                                        pass
                                continue
                        # Atomic rename (overwrite if exists)
                        os.replace(tmp_path, final_path)
                        # Invalidate the scan cache after the .bin write
                        self._kvcache_scan_cache_invalidate()
                        # Finalize the .ckpt ladder sidecar (bin FIRST, this best-effort).
                        _finalize_ckpt_sidecar(tmp_path, final_path, bin_fn)
                        # Write metadata sidecar (atomic: temp + replace)
                        context = getattr(slot, "context", None) if slot else None
                        prompt = getattr(slot, "prompt", "") if slot else ""
                        # Fall back to the admission messages when
                        # slot.context is empty, so a >=40k save persists a REAL prefix-
                        # comparable chain (not [] which is permanently unrestorable —
                        # _is_prefix_match rejects an empty saved_chain). Same source +
                        # shape as admission_hash_chain / _engine_view_chain (:3839).
                        _ctx_src = context
                        if not _ctx_src and slot is not None:
                            _ctx_src = (getattr(slot, "client_meta", None) or {}).get("messages")
                        # Honor client_meta_override on the slot=None
                        # teardown path (_cm resolved above from client_meta_override at
                        # an earlier point). Without this the teardown bin's hash_chain is [] ->
                        # _is_prefix_match rejects -> restore-diverged-fresh -> cold
                        # 250k re-prefill. _cm is populated above; this step makes the chain use it.
                        if not _ctx_src:
                            _ctx_src = (_cm or {}).get("messages")
                        hash_chain = _prefix_hash_chain(_ctx_src) if _ctx_src else []
                        context_for_len = _ctx_src if _ctx_src else None
                        # saved_len uses the SAME chokepoint as the
                        # admission incoming_len (kv_policy.compute_ctx_len) so the
                        # two are always comparable. Fallback to len(prompt) only when
                        # no structured context was captured.
                        # Use admission_ctx_len_override if provided.
                        if admission_ctx_len_override is not None:
                            prompt_len_val = admission_ctx_len_override
                        else:
                            prompt_len_val = compute_ctx_len(context_for_len) if context_for_len else len(prompt)
                        # Guard on _ctx_src (the effective chain source)
                        # so the raw-prompt hash is only stamped when NEITHER context NOR
                        # admission messages produced a chain.
                        prompt_hash = hashlib.sha256(prompt.encode("utf-8", errors="replace")).hexdigest() if (not _ctx_src and prompt) else ""
                        meta = {
                            # SPEC-V2 WAVE A: owner identity = (session,role[,fp8])
                            # string — the byte-locked resolve_kv restore owner
                            # string-compare therefore keys on session+role. Raw tid
                            # preserved for diagnostics.
                            "thread_id": bin_ident,
                            "raw_thread_id": thread_id,
                            "session_id": (_cm or {}).get("session_id"),
                            "role": _bin_role(_cm),
                            # SPEC-V2 consistency stamp: byte-truth of the bin this
                            # meta was written for (bin os.replace succeeded above).
                            "bin_bytes": os.path.getsize(final_path),
                            "bin_mtime": os.path.getmtime(final_path),
                            "thread_hash": thread_hash,
                            "prompt_tokens": n_prompt_tokens,
                            "prompt_len": prompt_len_val,
                            "n_context_turns": len(hash_chain),
                            "hash_chain": hash_chain,
                            "prompt_hash": prompt_hash,
                            "model_tag": model_tag,
                            "slot_id": sid,
                            "port": port,
                            "clean_prefix": _clean_stamp,
                            # The probe evidence this
                            # stamp was based on — rides the bin sidecar so a
                            # restore can attribute the stamp without re-reading
                            # the save logs. The three fields are None when the
                            # stamp was not honoured (non-clean bin) or when no
                            # probe evidence was present (fallback-cap bin).
                            "probed_chain_fp": (_clean_tok.chain_fp
                                                if (_clean_stamp and _clean_tok is not None) else None),
                            "probed_arm": (_clean_tok.arm
                                           if (_clean_stamp and _clean_tok is not None) else None),
                            "evidence_delta": ((n_prompt_tokens - _clean_tok.count)
                                               if _clean_tok is not None else None),
                            # Which cap arm produced this bin —
                            # "clean_prefill" (probe-recorded render boundary)
                            # or "slot_n_prompt_tokens" (engine-reported slot
                            # prompt length, the fallback arm). Ops: correlate
                            # which arm a restored bin came from without
                            # re-reading the save logs.
                            "bin_provenance": _cap_src,
                            # The tools
                            # fingerprint this thread rendered with AT SAVE TIME
                            # (reuses _tools_fingerprint). Read back by
                            # _cold_restore_bin_tools_fingerprint at restore time
                            # and compared against the incoming request's CURRENT
                            # fingerprint — the chain hash above stays blind to
                            # `tools` by design (kv_policy.py untouched, see the
                            # documented design decision), so this field is the
                            # ONLY place a tools-driven divergence is recorded.
                            # None for a genuinely toolless save (indistinguishable
                            # via .get() from an old bin missing the key entirely
                            # — deliberately: both cases must fail OPEN at restore).
                            "tools_fingerprint": _tools_fingerprint((_cm or {}).get("tools")),
                            # Build/model/ctx fingerprint so a
                            # bin can never be silently restored into a different
                            # engine build / model / ctx (= garbage KV). Sourced
                            # once per save from the loaded engine — see
                            # _engine_fingerprint; NO multi-GB gguf hashing.
                            "gguf_sha256": _fp.get("gguf_sha256"),
                            "engine_build_id": _fp.get("engine_build_id"),
                            "n_ctx": _fp.get("n_ctx"),
                            "n_rs_seq": _fp.get("n_rs_seq"),
                            "fp_gen": _fp.get("fp_gen"),
                        }
                        meta_fn = kv_meta_fn(model_tag, sid, thread_hash, port)
                        meta_tmp = os.path.join(SLOT_SAVE_DIR, f"{meta_fn}.tmp")
                        meta_path = os.path.join(SLOT_SAVE_DIR, meta_fn)
                        with open(meta_tmp, "w") as f:
                            json.dump(meta, f)
                        os.replace(meta_tmp, meta_path)
                        saved_any = True  # SPEC-V2: bin+meta both durably on disk
                        # Invalidate the scan cache after the .json sidecar write
                        self._kvcache_scan_cache_invalidate()
                        log.info("slot KV saved: %s (reason: %s)", bin_fn, decision.reason)
                        # Durable manager: INERT ring store + residency tag + LOG would-be reload.
                        # Reads client_meta labels (role, session_id) from slot to key the per-(role,session) ring.
                        # ZERO behavior change when TURBOHAUL_DURABLE_RING=OFF (default); just observability.
                        if _durable_ring_enabled() and slot is not None:
                            try:
                                ring_key = _durable_ring_key(getattr(slot, "client_meta", None))
                                if ring_key:
                                    ring_entry = {
                                        "bin_fn": bin_fn,
                                        "meta_fn": meta_fn,
                                        "thread_id": thread_id,
                                        "model_tag": model_tag,
                                        "port": port,
                                        "slot_id": sid,
                                        "clean_prefix": _clean_stamp,
                                        "n_context_turns": len(hash_chain),
                                        "hash_chain": hash_chain,
                                        "prompt_len": prompt_len_val,
                                        "saved_tokens": n_prompt_tokens,  # token count for restore saved_n (units match default path)
                                        "prompt_hash": prompt_hash,
                                        "saved_at": time.time(),
                                    }
                                    # Ring: last-3, newest-overrides-oldest (prepend + cap)
                                    ring_list = self._durable_ring_index.get(ring_key, [])
                                    ring_list.insert(0, ring_entry)
                                    if len(ring_list) > 3:
                                        ring_list.pop()  # evict oldest
                                    self._durable_ring_index[ring_key] = ring_list
                                    self._durable_ring_counts["ring_write"] = self._durable_ring_counts.get("ring_write", 0) + 1
                                    log.info("DURABLE_RING write: key=%s ring_len=%d entry=bin=%s clean=%s turns=%d",
                                             ring_key, len(ring_list), bin_fn, _clean_stamp, len(hash_chain))
                            except Exception:
                                log.debug("DURABLE_RING ring-store best-effort failed", exc_info=True)
                    except Exception as e:
                        log.warning("slot KV save failed for slot %d: %r", sid, e, exc_info=True)
                        continue
            return saved_any
        except Exception:
            log.debug("slot KV save best-effort failed for %s", model_tag, exc_info=True)
            return False

    # === CLASSIFIER: warm-path forced clean restore ==========
    # The pinned clean bin is BOTH the classifier anchor AND the warm-path restore
    # source. On a warm grace follow-up the engine's in-memory KV holds the just-
    # generated turn WITH <think>; the incoming user turn is think-STRIPPED, so the
    # engine's native LCP diverges at the first <think> -> minimal reuse OR a full
    # CLEAR. Forcing an `action=restore` of the think-free clean bin BEFORE the
    # follow-up decodes makes the engine's next get_common_prefix run against the
    # clean prefix -> strict extension (stale <= 0), no CLEAR (verified in testing). The
    # NO-DOWNGRADE gate fires the force ONLY when it improves reuse (never regresses
    # a true continuation whose warm state is an equal-or-longer valid prefix).

    def _find_clean_bin(self, port: int, model_tag: str, thread_id: str):
        """Locate the pinned clean_prefix bin for (model_tag, thread_id, port).

        Returns (bin_filename, saved_chain, sid, prompt_len, prompt_tokens) for
        the LONGEST clean chain, or None. Uses the scan cache — no O(N) listdir
        loop. Best-effort — any FS/JSON error yields None (no force).

        prompt_len is a CHARACTER count (compute_ctx_len) -- pre-existing,
        load-bearing elsewhere (the never-overwrite-with-smaller belt above,
        the subject-pairing gate) and unchanged in meaning or position here.
        prompt_tokens is a TOKEN count (meta "prompt_tokens", engine-reported
        at save time) -- newly surfaced for the anti-rewind compare, which
        needs a token count, not a character count: an earlier version of this
        compare used prompt_len directly and was off by the char/token ratio
        (~3x on real prompts), a unit mismatch that made the guard fire far
        less than it should have. Never conflate the two.
        """
        th = self._thread_hash(thread_id or "")
        key = (model_tag, th, port)
        try:
            # Pass the already-known key so hydrate is
            # gap-triggered/scoped, not an unconditional full sweep.
            clean_bins, _ = self._scan_kvcache_if_stale(requested_key=key)
        except Exception:
            return None
        best = clean_bins.get(key)
        if best is None:
            return None
        # Defensive os.path.exists — cache may be stale between
        # invalidation sites (race between delete → next lookup). If the bin
        # vanished, invalidate + return None so the caller falls through.
        from turbohaul.subprocess_mgr import SLOT_SAVE_DIR
        _, bin_fn, _chain, _sid = best[1], best[1], best[2], best[3]
        if not os.path.exists(os.path.join(SLOT_SAVE_DIR, bin_fn)):
            self._kvcache_scan_cache_invalidate()
            return None
        # best = (chain_len, bin_fn, chain, sid, prompt_len, prompt_tokens)
        return best[1], best[2], best[3], best[4], best[5]

    def _find_shadow_bin(self, port: int, model_tag: str, thread_id: str):
        """Locate the think-free `.shadow` bin for (model_tag,
        thread_id, port) — the SAVE-side artifact step (c) wrote (turns 1..N + the
        think-free assistant-N).

        Returns (bin_filename, saved_chain, sid) for the LONGEST shadow chain, or
        None. Uses the scan cache — no O(N) listdir loop. Mirrors _find_clean_bin's
        file layout EXACTLY, differing ONLY in the marker it matches: `.shadow.json`
        metas carrying `shadow:true` (vs the clean anchor's `clean_prefix:true`).
        The shadow bin is a SEPARATE artifact from the clean anchor, so the two
        finders never cross: `.shadow` metas have clean_prefix=False (invisible to
        _find_clean_bin), and a normal clean/meta never ends in `.shadow.json`.
        Best-effort — any FS/JSON error yields None so the caller falls through to
        EXACTLY today's clean-anchor path."""
        th = self._thread_hash(thread_id or "")
        key = (model_tag, th, port)
        try:
            # Pass the already-known key so hydrate is
            # gap-triggered/scoped, not an unconditional full sweep.
            _, shadow_bins = self._scan_kvcache_if_stale(requested_key=key)
        except Exception:
            return None
        best = shadow_bins.get(key)
        if best is None:
            return None
        # Defensive os.path.exists — cache may be stale between
        # invalidation sites (race between delete → next lookup).
        from turbohaul.subprocess_mgr import SLOT_SAVE_DIR
        _, bin_fn, _chain, _sid = best[1], best[1], best[2], best[3]
        if not os.path.exists(os.path.join(SLOT_SAVE_DIR, bin_fn)):
            self._kvcache_scan_cache_invalidate()
            return None
        # best = (chain_len, bin_fn, chain, sid)
        return best[1], best[2], best[3]

    @staticmethod
    def _generated_assistant_msg(result) -> "dict | None":
        """Reconstruct the assistant turn the engine's warm KV now holds from a
        completion result, so the warm-state hash chain can be rebuilt.

        The engine's KV holds the FULL generation INCLUDING the <think> block; the
        client received (and the harness stores in history) reasoning merged inline
        as ``<think>...</think>{content}`` (mirrors chat_completion._merge_reasoning_
        into_content). Returns {'role':'assistant','content': <with-think>} or None.

        Returns None (caller SAFE-DEGRADES = no forced restore, no regression) when:
        - result is the noop/None default_complete or a streamed placeholder;
        - the turn is a TOOL CALL (content often null, tool_calls carry the payload,
          and _prefix_hash_chain hashes role+content only) — its history form cannot
          be reconstructed to hash-match, so we must not risk a false divergence;
        - content is empty. Only a positively-reconstructable text turn arms force."""
        if not isinstance(result, dict):
            return None
        choices = result.get("choices")
        if not isinstance(choices, list) or not choices:
            return None
        c0 = choices[0]
        msg = c0.get("message") if isinstance(c0, dict) else None
        if not isinstance(msg, dict):
            return None
        if msg.get("tool_calls"):
            return None  # tool-call continuation -> safe-degrade (see docstring)
        content = msg.get("content")
        if content is None:
            content = ""
        reasoning = msg.get("reasoning_content")
        if reasoning and isinstance(content, str) and "<think>" not in content:
            # SINGLE-SOURCE wrap (the exact _merge_reasoning_into_
            # content newline form) so this reconstruction byte-matches what the harness
            # stores/resends -> _strip_thinking_all(this) == the harness's think-strip.
            # The old no-newline `<think>{reasoning}</think>{content}` form diverged on
            # multi-block / stray-`</think>` content. Lazy import avoids a manager<->api
            # cycle (same pattern as the _strip_thinking_all import below).
            from turbohaul.api.chat_completion import wrap_reasoning_think
            content = wrap_reasoning_think(reasoning, content)
        if not content:
            return None
        return {"role": "assistant", "content": content}

    def _engine_view_chain(self, slot, result) -> list[str]:
        """Hash chain of what the engine's warm KV holds after a decode =
        prompt messages + the generated assistant turn (with <think>).

        Two sources for the generated turn:
        - NON-streaming: parse it out of the completion ``result`` dict.
        - STREAMING: the SSE route accumulated the generated text onto
          ``slot.streamed_assistant_text`` (content + reasoning merged as <think>...)
          before signaling stream_done; use it when ``result`` yields nothing.

        Returns [] (= 'warm state UNKNOWN' -> the gate will NOT force, safe) when
        the generated turn can't be positively reconstructed (noop/tool-call/parse
        miss). A known chain arms the no-downgrade comparison for the next turn."""
        gen = self._generated_assistant_msg(result)
        if gen is None:
            # STREAMING path: the route stashed the accumulated generated text.
            streamed = getattr(slot, "streamed_assistant_text", None)
            if streamed:
                gen = {"role": "assistant", "content": streamed}
        if gen is None:
            return []
        msgs = (getattr(slot, "client_meta", None) or {}).get("messages")
        if not msgs:
            msgs = getattr(slot, "context", None)
        if not msgs:
            return []
        return _prefix_hash_chain(list(msgs) + [gen])

    def _classify_event(self, clean_chain, inc_chain, warm_chain) -> str:
        """Map the chain relationships to the 4 event types (+ guard-skip).

        - guard-skip : no incoming chain (can't classify).
        - sub-agent  : no clean anchor for this identity (distinct/first-seen thread
                       — nonce sub-agents land here until they save their own
                       anchor; classified independently, never cross-restored).
        - compression: clean anchor exists but is NOT a prefix of incoming (an early
                       turn was rewritten/summarized).
        - continuation: clean ⊑ incoming AND the warm state is an equal-or-longer
                       valid prefix (true continuation — native warm reuse wins).
        - user-message: clean ⊑ incoming but the warm state diverges (the think-strip
                       follow-up — the forced clean restore fires here).

        Unified: delegates to kv_classify.classify_event (single source of truth —
        that pure function is byte-identical to the logic that lived here, and the
        golden suite pins classify_event == _classify_event across the matrix)."""
        from turbohaul.kv_classify import classify_event
        return classify_event(clean_chain, inc_chain, warm_chain)

    def _emit_classifier_decision(self, decision: dict) -> None:
        """P5 observability: structured log + manager metric per restore-relevant
        request. PROVES 'Turbohaul determines each event' (which event + whether it
        forced the clean restore). Counts by event_type; keeps the last decision."""
        et = decision.get("event_type", "guard-skip")
        self._kv_classifier_counts[et] = self._kv_classifier_counts.get(et, 0) + 1
        if decision.get("forced_clean_restore"):
            self._kv_classifier_forced += 1
        self._kv_classifier_last = decision
        log.info("classifier decision: %s", decision)
        # Observability: the classifier's own INPUTS, not just its
        # answer -- "saved_chain is None" (=> a sub-agent/no-anchor verdict)
        # must be visible as the CAUSE in the line, not inferred by a human
        # reading two separate log statements. Only present on decisions
        # that actually ran the classifier (_classify_event call sites stamp
        # these fields onto `decision`); guard-skip/no-incoming-chain exits
        # never reach a classify call, so they have nothing to report here.
        # shape_verdict/role are deliberately TWO SEPARATE fields, not a
        # rename of event_type's value: event_type is a live lookup key
        # (EVENT_TO_CLASS -> POLICIES -> save_ok) with call sites that bypass
        # the constants via hardcoded literals -- changing the VALUE would
        # silently move a save decision. shape_verdict mirrors event_type's
        # current value unchanged; role is the requester's own resolved
        # role, independently sourced, so a reader can never mistake one
        # for the other.
        if "shape_verdict" in decision:
            # Measurement addition: the chain hash is
            # cumulative (H_i = SHA256(H_{i-1} || role_i || content_i)), so
            # "warm_chain is not a prefix of inc_chain" is ONE signal for
            # both an early divergence and a late one -- observationally
            # identical from resolved_from alone. warm_vs_inc/clean_vs_inc
            # divergence indices settle which candidate actually shares
            # more with the incoming request, independent of which one this
            # call ultimately forces. Turn counts alongside (warm/clean/
            # inc_turns) so "which is longer" doesn't have to be inferred
            # from the indices. shared_prefix tokens is an honest null: the
            # chains are hash-lists (no size info), and _find_clean_bin's
            # own return shape carries no token count either (see the
            # restored_tokens asymmetry note) -- deriving one here would
            # need a live engine query, out of scope for a measurement-only
            # change. Zero decision impact: purely additional fields on the
            # same dict the chokepoint already logs; warm_covers/
            # would_force/force/the qwen gate are untouched.
            log.info(
                "WARM_CLASSIFY saved_chain_fp=%s inc_chain_fp=%s warm_chain_fp=%s "
                "shape_verdict=%s role=%s resolved_from=%s "
                "warm_vs_inc_divergence_index=%s clean_vs_inc_divergence_index=%s "
                "warm_turns=%s clean_turns=%s inc_turns=%s "
                "shared_prefix_tokens=unavailable",
                decision.get("saved_chain_fp"), decision.get("inc_chain_fp"),
                decision.get("warm_chain_fp"), decision.get("shape_verdict"),
                decision.get("role"), decision.get("resolved_from"),
                decision.get("warm_vs_inc_divergence_index"),
                decision.get("clean_vs_inc_divergence_index"),
                decision.get("warm_turns"), decision.get("clean_turns"),
                decision.get("inc_turns"),
            )
        # Observability: the KV-reuse number operators watch,
        # emitted on EVERY restore decision -- not just
        # the ones that happened to fire a restore. incoming_turns/
        # common_prefix_turns/clean_bin_id are present on every decision
        # dict built anywhere in this file (both the warm and cold restore
        # paths default them even before any branch runs), so this fires
        # unconditionally rather than needing every call site touched.
         # common_prefix_turn_pct is a TURN-based common-prefix ratio, not
        # token-based -- the manager never tokenizes the incoming request
        # itself (only the engine does, downstream), so requested_tokens/
        # recomputed_tokens are honest explicit nulls rather than a
        # mixed-unit guess; a real per-bin TOKEN count (restored_tokens) is
        # used where the chokepoint has one, from the bin's own saved
        # metadata. Named explicitly as a TURN ratio (not reuse_pct) so it
        # can never be misread as token-based reuse. The per-bin TOKEN count
        # (restored_tokens) is present on the RESTORE decision paths (from the
        # bin's saved metadata at save time) but NOT on the warm-path classify
        # decision (the classify measures chain prefix, not tokens). The
        # KV_REUSE line — the operator's grep target for "is reuse working?" —
        # fires ONLY from restore decisions that carry a token count; the
        # classify decision's prefix estimate fires on its own line
        # (KV_CLASSIFY) so the operator never gleans "no reuse" from a
        # classify-path unavailable (the previous behaviour reported
        # unavailable on nearly every classify-path call).
        _req_turns = decision.get("incoming_turns") or 0
        _restored_turns = decision.get("common_prefix_turns") or 0
        _common_prefix_turn_pct = (
            round(100.0 * _restored_turns / _req_turns, 1) if _req_turns > 0 else None
        )
        _restored_tokens = decision.get("restored_tokens")
        if _restored_tokens is not None:
            # Restore decision paths: the bin's own token count — the reuse
            # number the operator searches for. restored_tokens=0 is a real
            # zero (restore path chose fresh / failed), not a missing-data null.
            log.info(
                "KV_REUSE restored_tokens=%s reused_turns=%s requested_tokens=%s "
                "recomputed_tokens=%s common_prefix_turn_pct=%s bin_id=%s "
                "thread_hash=%s",
                _restored_tokens,
                _restored_turns,
                "unavailable", "unavailable", _common_prefix_turn_pct,
                decision.get("clean_bin_id"), decision.get("thread_hash"),
            )
        else:
            # Warm-path classify decision: estimates the warm chain's prefix
            # match in turns (the classify path never tokenizes). The 0% on a
            # classify decision means "no warm-path prefix match" (the engine
            # may still reuse from the cold bin restore — that outcome's tokens
            # appear in the KV_REUSE line emitted by the restore decision, not
            # here).
            log.info(
                "KV_CLASSIFY reused_turns=%s requested_turns=%s "
                "common_prefix_turn_pct=%s thread_hash=%s",
                _restored_turns, _req_turns, _common_prefix_turn_pct,
                decision.get("thread_hash"),
            )

    # ============================================================
    # Observability, part 2: the engine's own reuse outcome. KV_REUSE (above)
    # fires at DECISION time and reports what the manager offered -- it can
    # never know what the engine actually kept, because the engine's own
    # counter (n_prompt_tokens_cache, surfaced by the live poller) is only
    # populated once generation has actually run. This is the companion line,
    # fired once per request from the single point each completion path
    # already knows the generation is over: the non-streaming _complete_fn
    # wrapper, and each of the streaming paths' stream_done_event resolution.
    # One shared chokepoint (same discipline as _log_kv_save_firing), never
    # inline logging at the call sites themselves.
    # ============================================================
    def _log_kv_reuse_outcome(
        self, slot: "Slot", handle, *, wait_state: str, reason: str | None = None,
    ) -> None:
        """Report the engine's real reuse figure for one request, or say
        exactly why it can't be trusted.

        wait_state:
          "completed" -- the generation genuinely ran to completion; attempt
                         the real join against the live poller's own sample.
          "forced"    -- the manager force-ended a streaming wait to unwind a
                         cancelled/truncated stream (see Slot.stream_done_-
                         forced_reason); no trustworthy figure exists.
          "timeout"   -- the wait itself hit _STREAM_TIMEOUT_S; state unknown.
          "cancelled" -- the completion task was cancelled before finishing.
          "exception" -- the engine call raised before finishing.

        A reuse figure is NEVER printed for any state other than "completed",
        and even then only once the poller's own generation_id is proven to
        be the SAME generation this slot dispatched (recomputed from the
        exact (pid, spawn_seq, slot_id) tuple the poller itself hashes to
        build that id) -- never assumed from "whatever is currently live".
        """
        _slot_id = getattr(slot, "slot_id", None)
        # Route through the SAME identity transform the decision-time KV_REUSE
        # line uses (_bin_identity), not raw thread_id. The decision-time
        # emitters hash _bin_identity(thread_id, client_meta, chain), which
        # becomes sess:{session_id}:{role} whenever the client sends a
        # session_id (the normal case, not an edge case) -- hashing raw
        # thread_id here instead means the two thread_hash fields would never
        # match for the same session-scoped request. slot_id already joins
        # correctly on its own (write-once, no transform on either side) but
        # does not give the cross-turn continuity view thread_hash is for.
        _tid = _bin_identity(
            getattr(slot, "thread_id", "") or "",
            getattr(slot, "client_meta", None),
            getattr(slot, "admission_hash_chain", None))
        _thread_hash = self._thread_hash(_tid)
        if wait_state != "completed":
            log.info(
                "KV_REUSE_OUTCOME slot_id=%s thread_hash=%s wait_state=%s "
                "engine_reused_tokens=unavailable reason=%s",
                _slot_id, _thread_hash, wait_state, reason or wait_state,
            )
            return
        _pid = getattr(handle, "pid", None) if handle is not None else None
        if _slot_id is None or _pid is None:
            log.info(
                "KV_REUSE_OUTCOME slot_id=%s thread_hash=%s wait_state=completed "
                "engine_reused_tokens=unavailable reason=%s",
                _slot_id, _thread_hash,
                "no_slot_id" if _slot_id is None else "no_handle",
            )
            return
        _expected_gen_id = compute_generation_id(
            _pid, self._spawn_seq_for_model(slot.model_tag), _slot_id)
        _heartbeat = self.live_generations.get(slot.model_tag) or self.live_generation or {}
        if _heartbeat.get("generation_id") != _expected_gen_id:
            log.info(
                "KV_REUSE_OUTCOME slot_id=%s thread_hash=%s wait_state=completed "
                "engine_reused_tokens=unavailable reason=no_matching_sample",
                _slot_id, _thread_hash,
            )
            return
        _n_cache = _heartbeat.get("n_prompt_cache")
        # POISON-BIN RETIREMENT. A completed generation
        # whose engine heartbeat reports reused-to-zero on a CLEAN-STAMPED
        # restored bin is the reuse=0 signature of a poisoned bin — the bin
        # restored but the engine found nothing to reuse (a post-generation
        # dump stamped clean). Retire it on BOTH tiers (stale-mark, never
        # delete), drop it from the durable-ring mirror, and poison its
        # context fp so the save gate does not re-stamp the same bin.
        # Best-effort (never raises); the retirement is attributable in the
        # RETAINED KV_REUSE_OUTCOME line below (bin_retired= poison_chain_fp=).
        _fired = False
        _bfn = ""
        _fp = ""
        if (isinstance(_n_cache, (int, float)) and not isinstance(_n_cache, bool)
                and _n_cache == 0):
            try:
                _port = getattr(handle, "port", None) if handle is not None else None
                _bfn = getattr(self, "_last_restored_bin", {}).get(_port) if _port is not None else None
                if _bfn:
                    from turbohaul.subprocess_mgr import SLOT_SAVE_DIR
                    _meta_p = os.path.join(SLOT_SAVE_DIR, str(_bfn)[:-4] + ".json")
                    _is_clean = False
                    if os.path.exists(_meta_p):
                        with open(_meta_p) as _mf:
                            _meta = json.load(_mf)
                        _is_clean = bool(_meta.get("clean_prefix")) or \
                            _meta.get("bin_provenance") == "clean_prefill"
                    if _is_clean:
                        _fp = _chain_fp(_meta.get("hash_chain"))
                        self._stale_mark_save_sidecar(str(_bfn)[:-4] + ".json", "reuse_zero")
                        self._stale_mark_persist_sidecar(str(_bfn)[:-4] + ".json", "reuse_zero")
                        self._kvcache_scan_cache_invalidate()
                        # Ring: keep the in-memory index a mirror of on-disk
                        # truth — the bin is stale on both tiers now, so its
                        # ring entry must not offer it up again.
                        try:
                            _rkey = _durable_ring_key(getattr(slot, "client_meta", None))
                            if _rkey and _rkey in self._durable_ring_index:
                                _rl = [e for e in self._durable_ring_index[_rkey]
                                       if e.get("bin_fn") != _bfn]
                                if len(_rl) != len(self._durable_ring_index[_rkey]):
                                    self._durable_ring_index[_rkey] = _rl
                        except Exception:
                            pass  # ring mirror is inert-by-default anyway
                        if _fp and _port is not None:
                            self._poisoned_chain_fps.setdefault(_port, set()).add(_fp)
                        _fired = True
            except Exception:
                log.warning("poison-bin retirement best-effort failed "
                            "(port=%s bin=%s)", _port, _bfn, exc_info=True)
        if _fired:
            log.info(
                "KV_REUSE_OUTCOME slot_id=%s thread_hash=%s wait_state=completed "
                "engine_reused_tokens=%s bin_retired=%s poison_chain_fp=%s",
                _slot_id, _thread_hash, _n_cache, _bfn, _fp)
        else:
            log.info(
                "KV_REUSE_OUTCOME slot_id=%s thread_hash=%s wait_state=completed "
                "engine_reused_tokens=%s",
                _slot_id, _thread_hash,
                _n_cache if _n_cache is not None else "unavailable",
            )

    # ============================================================
    # Shadow byte-match self-check (DORMANT — observability ONLY)
    # ============================================================
    # De-risks the shadow-reprefill feature by MEASURING its single load-bearing
    # assumption: that the manager's THINK-FREE assistant-turn content byte-matches
    # what the AI harness resends (think-STRIPPED) next turn. Reuse is decided on
    # a turn-hash chain, so if the manager's strip != the harness's strip the saved
    # state silently won't reuse. This pair only reads, hashes, logs, and counts — it
    # writes NO KV, touches NO restore/admission/routing/save decision, and never
    # raises into the hot path (both methods are self-protecting best-effort).

    def _record_shadow_bytematch_probe(self, slot, result) -> None:
        """Stash turn N's THINK-FREE assistant hash for the next-turn compare.

        Called at the 4 main-generation completion points (streaming + non-streaming,
        anchor + active-match), mirroring the ``_engine_view_chain`` calls. ``result``
        is the completion dict on the non-streaming path and ``None`` on the streaming
        path (then the route-stashed ``slot.streamed_assistant_text`` carries the
        with-<think> answer, same source ``_engine_view_chain`` uses).

        Records a ``skipped_*`` count and returns (no stash) when there is nothing
        probe-able: a tool-call/noop turn (non-streaming ``_generated_assistant_msg``
        -> None => skipped_toolcall), content lacking a ``</think>`` block
        (skipped_no_think), or an empty think-free strip / absent streamed text
        (skipped_empty). Best-effort: any exception is swallowed (never raises).
        """
        try:
            c = self._shadow_bytematch_counts
            # 1. Recover the full WITH-<think> assistant content (mirror _engine_view_chain).
            if result is None:
                # STREAMING: the SSE route stashed the merged <think> text on the slot.
                content = getattr(slot, "streamed_assistant_text", None)
            else:
                # NON-STREAMING: reconstruct from the completion dict. None => tool-call /
                # noop / empty => not a positively-reconstructable text turn -> safe skip.
                gen = self._generated_assistant_msg(result)
                if gen is None:
                    c["skipped_toolcall"] = c.get("skipped_toolcall", 0) + 1
                    return
                content = gen.get("content")
            if not isinstance(content, str) or not content:
                # streaming parse-miss / tool-call stream / empty answer -> nothing to probe
                c["skipped_empty"] = c.get("skipped_empty", 0) + 1
                return
            if "</think>" not in content:
                c["skipped_no_think"] = c.get("skipped_no_think", 0) + 1
                return
            # Mirror the harness's remove-ALL think-strip so the manager side hashes
            # EXACTLY what the harness would resend — including multi-block / pre-<think>
            # content, where the old rsplit-last diverged (multi-block think-strip;
            # 2/11 live MISMATCH). SAME strip fn the shadow-save uses, so this probe measures
            # exactly what the save produces. Lazy import avoids any manager<->api import
            # cycle (idiomatic here, cf. the QueueClosed / SLOT_SAVE_DIR local imports).
            from turbohaul.api.chat_completion import _strip_thinking_all
            think_free = _strip_thinking_all(content)
            if not think_free:
                c["skipped_empty"] = c.get("skipped_empty", 0) + 1
                return
            th = self._thread_hash(getattr(slot, "thread_id", "") or "")
            probe = self._shadow_bytematch_probe
            # pop-then-set so a re-stashed active thread moves to most-recent (true
            # write-LRU eviction below; never evicts a thread that just wrote).
            probe.pop(th, None)
            probe[th] = {
                "assistant_hash": self._turn_hash("assistant", think_free),
                "sample": think_free[:120],
            }
            # Bounded FIFO: evict oldest write(s) so the stash can never leak.
            while len(probe) > _SHADOW_BYTEMATCH_CAP:
                probe.pop(next(iter(probe)))
        except Exception:
            log.debug("shadow_bytematch record best-effort failed", exc_info=True)

    def _compare_shadow_bytematch_probe(self, thread_id, context, client_meta) -> None:
        """On turn N+1 admission, compare the harness's resent (think-stripped)
        assistant-N turn against turn N's stashed think-free hash.

        The incoming assistant-N turn = the LAST ``role == 'assistant'`` message in the
        resent history (the harness appends the new user turn AFTER it, so the most-
        recent assistant turn is exactly the one we generated last turn; tool-call turns
        never stash, so they can't leave a stale probe). Both sides are hashed with
        ``_turn_hash('assistant', ...)`` — a STANDALONE single-turn hash (NOT the rolling
        ``_prefix_hash_chain``), so hash-equality == byte-equality of the two strips.
        Logs match/mismatch (+ samples on mismatch to diagnose the byte-delta), counts
        it, and pops the probe (consumed).

        DORMANT: changes NO decision (``submit`` already enqueued the slot above).
        Best-effort; never raises into ``submit``.
        """
        try:
            probe = self._shadow_bytematch_probe
            if not probe:
                return
            th = self._thread_hash(thread_id or "")
            stash = probe.get(th)
            if stash is None:
                return
            # Incoming messages: client_meta["messages"] else context (mirror _engine_view_chain).
            msgs = None
            if isinstance(client_meta, dict):
                msgs = client_meta.get("messages")
            if not msgs:
                msgs = context
            if not msgs:
                return
            inc_content = None
            for m in reversed(msgs):
                if isinstance(m, dict) and m.get("role") == "assistant":
                    inc_content = m.get("content")
                    break
            if inc_content is None:
                return  # no assistant turn resent yet — leave the stash for a later turn
            inc_h = self._turn_hash("assistant", inc_content)
            c = self._shadow_bytematch_counts
            if inc_h == stash.get("assistant_hash"):
                c["match"] = c.get("match", 0) + 1
                log.info("shadow_bytematch MATCH thread=%s", th)
            else:
                c["mismatch"] = c.get("mismatch", 0) + 1
                inc_sample = inc_content if isinstance(inc_content, str) else str(inc_content)
                log.info(
                    "shadow_bytematch MISMATCH thread=%s saved=%s inc=%s "
                    "saved_sample=%r inc_sample=%r",
                    th, stash.get("assistant_hash"), inc_h,
                    stash.get("sample"), inc_sample[:120],
                )
            probe.pop(th, None)  # consumed
        except Exception:
            log.debug("shadow_bytematch compare best-effort failed", exc_info=True)

    @staticmethod
    def _is_qwen_family(model_tag: str) -> bool:
        """The turn-hash⊑ → engine-token-prefix equivalence that makes the
        forced clean-restore SAFE was proven ONLY on the qwen MTP family (divergence
        lands at the primer boundary, stale=1, one token off the n_rs_seq=2 CLEAR
        threshold). A different template/tokenizer (longer primer, multi-token think
        preamble, date/counter in the system render) could keep the turn-hash valid
        while pushing token divergence > 2 → CLEAR. The physics belt guards turn-
        COUNT, not the token prefix, so it can't catch that class. So the force path
        is gated to qwen explicitly; any other family safe-degrades to no-force."""
        m = (model_tag or "").lower()
        return "qwen" in m or "qwq" in m

    def _reset_clean_bin(self, port: int, model_tag: str, thread_id: str, bin_fn: str, requester_is_labeled_main: bool = False) -> None:
        """After a COMPRESSION event (clean anchor no longer a
        prefix of the incoming context), drop the stale clean bin (+ its clean-prefix
        .json sidecar) for this thread so the next turn's scale-up probe re-anchors a
        fresh clean bin at the new compressed baseline. Best-effort; never raises into
        the decode path. Does NOT touch the restore gate — it only removes a
        file the gate already refuses to restore.

        BEFORE removing each RAM-tier sidecar, stale-marks its
        SLOT_PERSIST_DIR counterpart (see _stale_mark_persist_sidecar) so
        _hydrate_ram_from_persist does not copy the byte-identical file straight
        back from SSD on the very next scan — the RAM-delete/SSD-resurrect loop
        this function used to cause on its own."""
        from turbohaul.subprocess_mgr import SLOT_SAVE_DIR
        th = self._thread_hash(thread_id)
        # Safety belt: a bin stamped role=main may only be reset
        # by a requester whose OWN role came from an explicit is_main label —
        # never a defaulted or chain-inferred identity. Legacy metas without a
        # role stamp pass through unchanged (one-time migration window).
        try:
            with open(os.path.join(SLOT_SAVE_DIR, bin_fn[:-4] + ".json")) as _af:
                _am = json.load(_af)
            if _am.get("role") == "main" and not requester_is_labeled_main:
                log.warning(
                    "clean-bin RESET REFUSED: anchor role=main but requester role is "
                    "not label-derived main (bin=%s thread=%s)", bin_fn, (thread_id or "?")[:16])
                return
        except FileNotFoundError:
            pass
        except Exception:
            log.debug("clean-bin reset: anchor meta read skipped", exc_info=True)
        removed = 0
        try:
            try:
                # Stale-mark the persist-tier counterpart BEFORE removing
                # the RAM .bin's own meta, so a hydrate that races this reset still
                # sees the stamp in time.
                self._stale_mark_persist_sidecar(bin_fn[:-4] + ".json", "reset_clean_bin")
                os.remove(os.path.join(SLOT_SAVE_DIR, bin_fn))
                # Invalidate the scan cache after the bin delete
                self._kvcache_scan_cache_invalidate()
                removed += 1
            except FileNotFoundError:
                pass
            for fn in list(os.listdir(SLOT_SAVE_DIR)):
                if not (fn.startswith(f"{model_tag}.") and fn.endswith(".json")
                        and f".p{port}.{th}." in fn):
                    continue
                try:
                    with open(os.path.join(SLOT_SAVE_DIR, fn)) as f:
                        m = json.load(f)
                    # SPEC-V2 WAVE A belts (RED-HAT MODS 1+2): only reset sidecars
                    # whose STAMPED owner identity equals the requester's (an
                    # interleaved variant can never delete main's anchor — the
                    # turn-52 residual — even if hashes ever collide); and a sidecar
                    # stamped role=main may only be reset by a label-derived main.
                    if m.get("clean_prefix") and m.get("thread_id", "") == thread_id:
                        if m.get("role") == "main" and not requester_is_labeled_main:
                            log.warning("clean-bin RESET REFUSED (sidecar role=main, requester not labeled main): %s", fn)
                        else:
                            # Same stale-mark, BEFORE removal, keyed by
                            # this exact filename — covers every identity this loop
                            # can match (main, sub_agent, curator, legacy), not just
                            # main, since matching is unchanged from above.
                            self._stale_mark_persist_sidecar(fn, "reset_clean_bin")
                            os.remove(os.path.join(SLOT_SAVE_DIR, fn))
                            removed += 1
                except FileNotFoundError:
                    pass
                except Exception:
                    log.debug("clean-bin reset: sidecar read/remove skipped", exc_info=True)
            log.info(
                "clean-bin RESET (compression): dropped %d file(s) anchor=%s thread=%s",
                removed, bin_fn, (thread_id or "?")[:12])
        except Exception:
            log.debug("clean-bin reset best-effort failed", exc_info=True)

    @staticmethod
    def _stale_mark_sidecar_in(tier_dir: str, meta_fn: str, reason: str) -> bool:
        """The shared atomic stale-stamp writer
        for one tier directory. Stamps `stale`/`stale_reason`/`stale_at` into
        `tier_dir/meta_fn` (tmp + os.replace) if the file exists and is not
        already stale. Best-effort, non-raising (missing file -> False)."""
        fpath = os.path.join(tier_dir, meta_fn)
        try:
            with open(fpath) as f:
                m = json.load(f)
            if m.get("stale"):
                return False
            m["stale"] = True
            m["stale_reason"] = reason
            m["stale_at"] = time.time()
            tmp = fpath + ".stale.tmp"
            with open(tmp, "w") as f:
                json.dump(m, f)
            os.replace(tmp, fpath)
            return True
        except FileNotFoundError:
            return False
        except Exception:
            log.debug("stale-mark skipped for %s/%s", tier_dir, meta_fn, exc_info=True)
            return False

    def _stale_mark_persist_sidecar(self, meta_fn: str, reason: str) -> bool:
        """Stamp stale:true into the SLOT_PERSIST_DIR file named
        `meta_fn` — the SSD-tier counterpart of a SLOT_SAVE_DIR sidecar
        `_reset_clean_bin` is about to remove. `_hydrate_ram_from_persist`'s
        stale check reads `persist_dir` (SLOT_PERSIST_DIR), NOT `save_dir`
        (SLOT_SAVE_DIR) — the two are different directories — so a stamp
        written only to the RAM tier (as `_mark_main_bin_stale_for_session`
        does, matched by main-only session identity) has no effect on hydrate
        and does nothing to stop the resurrect. This helper writes the SAME
        stamp shape (`stale`/`stale_reason`/`stale_at`, atomic tmp+replace) to
        the correct tier, matched by the exact filename the caller already
        matched in SLOT_SAVE_DIR — covers every identity `_reset_clean_bin`
        can remove (main, sub_agent, curator, legacy), not main-only.

        Best-effort, non-raising: a bin never persisted to SSD has no
        SLOT_PERSIST_DIR counterpart — silent no-op, nothing to protect from
        resurrection since there is nothing on SSD to resurrect FROM. Cleared
        automatically on the next real save: _persist_clean_bin_to_ssd_by_hash
        copy2's the (unstale) RAM meta over this exact filename, overwriting
        the stale stamp — the same deterministic-filename clear path
        _mark_main_bin_stale_for_session's own docstring already relies on.

        Returns True if a stamp was written, False otherwise (no-op or
        already stale)."""
        from turbohaul.subprocess_mgr import SLOT_PERSIST_DIR
        return self._stale_mark_sidecar_in(SLOT_PERSIST_DIR, meta_fn, reason)

    def _stale_mark_save_sidecar(self, meta_fn: str, reason: str) -> bool:
        """RAM-tier counterpart of
        _stale_mark_persist_sidecar — same atomic stale-stamp shape
        (`stale`/`stale_reason`/`stale_at`, tmp + os.replace) into the
        SLOT_SAVE_DIR sidecar named `meta_fn`. Best-effort, non-raising;
        returns True if a stamp was written."""
        from turbohaul.subprocess_mgr import SLOT_SAVE_DIR
        return self._stale_mark_sidecar_in(SLOT_SAVE_DIR, meta_fn, reason)

    def _mark_main_bin_stale_for_session(self, session_id: str, reason: str = "is_compression") -> int:
        """Compression handling (by design: compression re-delivers, so Turbohaul just
        re-computes the session's is_main fresh next time). NON-DESTRUCTIVE:
        stamp stale:true into every clean_prefix sidecar whose STAMPED owner
        identity is exactly sess:<session_id>:main (atomic tmp+replace). Scan /
        find / cold-restore treat a stale meta as ABSENT; the bin stays on disk
        (crash-safe, no delete race) and the NEXT confirmed main force_clean
        save overwrites the same deterministic filename, clearing the marker.
        _reset_clean_bin's main-guard is deliberately untouched. Returns
        sidecars marked; best-effort, never raises."""
        from turbohaul.subprocess_mgr import SLOT_SAVE_DIR
        marked = 0
        try:
            ident = f"sess:{session_id}:main"
            for fn in list(os.listdir(SLOT_SAVE_DIR)):
                if not fn.endswith(".json"):
                    continue
                fpath = os.path.join(SLOT_SAVE_DIR, fn)
                try:
                    with open(fpath) as f:
                        m = json.load(f)
                    if not (m.get("clean_prefix") and not m.get("stale")
                            and m.get("thread_id") == ident):
                        continue
                    m["stale"] = True
                    m["stale_reason"] = reason
                    m["stale_at"] = time.time()
                    tmp = fpath + ".stale.tmp"
                    with open(tmp, "w") as f:
                        json.dump(m, f)
                    os.replace(tmp, fpath)
                    marked += 1
                except (OSError, ValueError):
                    continue
            if marked:
                self._kvcache_scan_cache_invalidate()
                # Drop any live VRAM anchor for the main identity too, so the R2
                # gate can never skip-force on the pre-compression state.
                th = self._thread_hash(ident)
                for _p, _rec in list((getattr(self, "_kv_vram_anchor", None) or {}).items()):
                    if _rec.get("thread_hash") == th:
                        self._kv_vram_anchor.pop(_p, None)
                log.info("R-COMP: marked %d main clean sidecar(s) STALE for session=%s (%s)",
                         marked, str(session_id)[:16], reason)
        except Exception:
            log.debug("R-COMP stale-mark best-effort failed", exc_info=True)
        return marked

    def _covered_scaffold_strip_enabled(self) -> bool:
        """True IFF the SAVE-probe reasoning-scaffold strip is active.

        DEFAULT ON: the two SAVE probes prefill the HISTORICAL-form prompt (engine
        ``/apply-template`` render -> strip ``<think>...</think>\\n\\n`` -> engine
        ``/completion`` prefill n_predict=0) so the saved KV byte-matches the
        harness's FUTURE think-stripped resend of the covered turns -> the
        cold/forced restore MATCHES+REUSES instead of hitting a position-drifted
        prefix and CLEARing.

        OFF: pre-strip behavior — the plain messages ``/v1/chat/completions``
        n_predict=0 probe, byte-identical to today.

        SAVE-side ONLY: the two live-generation sites (_build_stream_payload /
        _complete) are UNTOUCHED (they already render covered turns historical via
        the engine's position logic). kv_policy is UNTOUCHED: the strip acts on the
        rendered PROMPT, never on the role/content inputs to _prefix_hash_chain, so
        the saved meta's hash_chain is identical with the flag on or off (the strip
        is hash-chain-invariant)."""
        return self.runtime.kv.covered_scaffold_strip

    def _warm_force_clean_restore_enabled(self) -> bool:
        """True IFF the WARM-path forced clean-bin restore is active.

        DEFAULT ON: when OFF, the warm grace follow-up decodes on the engine's
        native in-RAM get_common_prefix reuse — the forced DISK restore
        (_maybe_force_clean_restore, wired at the 2 warm sites) is SKIPPED. This
        gives FULL in-RAM KV reuse for follow-up tool calls + same-model
        continuations: warm_covers is structurally ~always False (warm_chain is
        WITH-<think>; the harness resends think-STRIPPED), so forcing the restore
        on every warm follow-up would otherwise byte-mismatch -> engine CLEAR ->
        full reprefill. ON (1/true/yes/on): re-enable the forced restore (emergency
        A/B rollback). Does NOT affect the COLD swap-back / wave-return
        (_restore_slot_kv), which legitimately needs the disk restore and is
        UNTOUCHED."""
        # DEFAULT ON is safe because the clean bin is now a TRUE byte-prefix of the
        # harness's think-free resend (add_generation_prompt=False + trailing-primer
        # strip in _render_strip_prefill_probe), so forcing its restore on the warm
        # follow-up strict-extends the cached prefix instead of letting native
        # in-VRAM reuse re-diverge at the assistant-turn boundary. Safety coupling:
        # force-restore is HARD-OFF whenever the covered-scaffold strip is disabled
        # (unstripped saves must never be force-restored). Ops kill-switches (no
        # container recreate needed):
        #   hot:  touch /var/lib/turbohaul/.warm_force_clean_off
        #   env:  TURBOHAUL_WARM_FORCE_CLEAN_RESTORE=0
        if os.path.exists("/var/lib/turbohaul/.warm_force_clean_off"):
            return False
        if not self._covered_scaffold_strip_enabled():
            return False
        v = os.environ.get("TURBOHAUL_WARM_FORCE_CLEAN_RESTORE", "").strip().lower()
        if v in ("0", "false", "no", "off"):
            return False
        return True

    async def _live_slot_token_position(self, port: int, sid) -> int | None:
        """Anti-rewind check: current token count resident in engine slot
        `sid` on `port`, read via a direct ``GET /slots`` at decision time --
        the same field + match-by-id idiom already used by
        ``load_verify_log.verify_kv_restored`` (``n_prompt_tokens``, matched on
        ``sl.get("id") == slot_id``) and the inline ``/slots`` reads elsewhere
        in this file. Deliberately NOT the manager's ~1Hz poller-cache
        attribute (its idle-state token count is a hardcoded 0) -- see
        the poller-cache behaviour described in this module's comments. Best-effort: None on any
        failure/timeout/missing-slot; the caller treats None as "unknown,
        don't decline" so a probe failure degrades to today's behavior, never
        a false anti-rewind skip."""
        try:
            async with httpx.AsyncClient(timeout=2.0) as client:
                resp = await client.get(f"http://127.0.0.1:{port}/slots")
                if resp.status_code != 200:
                    return None
                slots = resp.json()
        except Exception:
            return None
        if not isinstance(slots, list):
            return None
        match = next(
            (s for s in slots if isinstance(s, dict) and s.get("id") == sid), None
        )
        if match is None:
            return None
        tok = match.get("n_prompt_tokens")
        return tok if isinstance(tok, int) else None

    async def _maybe_force_clean_restore(
        self, port: int, model_tag: str, slot, warm_chain: list[str]
    ) -> dict:
        """Warm-path forced clean-bin restore + NO-DOWNGRADE gate.

        Runs BEFORE a warm grace follow-up decodes. Gate:
            force = (clean ⊑ incoming) AND warm_state_known AND NOT warm_covers
        where warm_covers = (warm ⊑ incoming) AND len(warm) >= len(clean).

        - clean ⊑ incoming : the think-free clean bin is a valid prefix -> restoring
          it yields a guaranteed strict-extension reuse (physics belt: _is_prefix_
          match rejects a clean bin LONGER than incoming, so we never restore a bin
          the engine would CLEAR).
        - warm_covers      : the engine's current warm KV already gives an equal-or-
          longer valid prefix (a TRUE continuation — no think divergence). Forcing
          the shorter clean bin here would restore LESS + reprefill recent turns =
          REGRESSION, so we DO NOT force. Native warm reuse wins.
        - warm_state_known : if the warm chain is unknown ([] — noop/streamed/tool
          call), we DO NOT force (safe-degrade to today's behavior; no regression).

        Only when clean is valid AND the warm state is KNOWN to diverge do we POST
        `action=restore` of the clean bin into the engine slot. Best-effort; never
        raises into the decode path. Returns the observability decision dict."""
        inc_chain = getattr(slot, "admission_hash_chain", []) or []
        tid = getattr(slot, "thread_id", "") or ""
        # SPEC-V2 WAVE A: every bin lookup/reset in this method keys on the
        # (session_id, role[, fp8]) identity (raw tid when unlabeled/no session).
        tid = _bin_identity(tid, getattr(slot, "client_meta", None), inc_chain)
        # The incoming turns (client_meta["messages"], 1:1 aligned
        # with inc_chain — both derived from the same admission messages) for the
        # tool-opaque tail guard below. Absent (streamed submit w/o messages) -> []
        # -> guard inert (safe-degrade to today's force behavior).
        inc_messages = (getattr(slot, "client_meta", None) or {}).get("messages") or []
        decision = {
            "event_type": "guard-skip",
            "action": "fresh",
            "resolved_from": "warm-no-incoming-chain",
            "clean_bin_id": None,
            "common_prefix_turns": 0,
            "incoming_turns": len(inc_chain),
            "forced_clean_restore": False,
            # Set once, unconditionally, so every branch below (return
            # or fall-through) carries it into the KV_REUSE line emitted by
            # _emit_classifier_decision's shared finally.
            "thread_hash": self._thread_hash(tid),
            # slot_id: the per-request correlation key the outcome-time join
            # needs (see _log_kv_reuse_outcome) -- getattr-guarded per the
            # same defensive idiom this function already uses for every other
            # slot field, not because slot can be None here (it can't: the
            # caller always passes a live Slot).
            "slot_id": getattr(slot, "slot_id", None),
        }
        try:
            # WARM forced clean-bin restore is DEFAULT OFF.
            # Short-circuit BEFORE any restore POST (equivalent to gating the 2 warm
            # callers, but unit-testable + observable): the warm grace follow-up decodes
            # on the engine's native in-RAM get_common_prefix reuse (clean v0.5.8 parity).
            # warm_covers was structurally ~always False (warm_chain is WITH-<think>; the
            # harness resends think-STRIPPED) -> the force fired every warm follow-up ->
            # byte-mismatch -> engine CLEAR -> full reprefill (~16k of ~50k). The COLD
            # swap-back / wave-return (_restore_slot_kv) is a SEPARATE path, NOT gated by
            # this flag. ON (emergency A/B rollback) re-enables the force below (the crit3
            # tool-tail guard, shadow-restore-preference + no-downgrade gate all preserved).
            # The `finally` still emits this decision so /status reflects the gate.
            if not self._warm_force_clean_restore_enabled():
                decision["action"] = "fresh"
                decision["resolved_from"] = "warm-force-gated-native-reuse"
                decision["forced_clean_restore"] = False
                return decision
            if not inc_chain or not tid:
                return decision
            found = self._find_clean_bin(port, model_tag, tid)
            # SPEC-V2 REWORK R2: live in-VRAM anchor overlay. With per-turn disk
            # saves gone the disk bin LAGS until unload; the classifier anchor and
            # the force decision ride the in-memory chain whenever the VRAM state
            # provably belongs to THIS identity on THIS live sidecar (identity
            # hash + model_tag + pid all match — a respawn/foreign takeover fails
            # the pid/identity compare and falls through to today's disk logic).
            _mem = (getattr(self, "_kv_vram_anchor", None) or {}).get(port) or {}
            # thread_hash alone can COLLIDE across two
            # different identities sharing the same session — _bin_identity
            # (above, this same tid derivation) falls back to the RAW
            # thread_id whenever session_id/role-label/chain aren't ALL
            # present, and the "curator reuse-main" design deliberately
            # sends the curator's thread_id = main's thread_id, so a
            # same-session curator can hash IDENTICALLY to main (this occurs in
            # practice: both share one hash at a single timestamp).
            # model_tag/pid don't discriminate either — a curator riding
            # main's warm slot by design shares both. _kv_dirty_tail was
            # considered as the extra signal but REJECTED: it is only SET
            # by THIS SAME turn's own _probe_and_save_clean_kv call, which
            # in the grace-loop matched path always runs AFTER this read
            # (streaming and non-streaming alike — confirmed by
            # direct trace) — so on the FIRST foreign touch the flag is
            # still whatever the PREVIOUS (main) occupant left it as
            # (cleared), and the collision sails through unblocked. Fixed
            # instead with a ZERO-LAG comparison: _cur_tip_role is derived
            # from THIS call's own slot, available synchronously, no
            # dependency on any write that hasn't happened yet — compared
            # against tip_role, stamped on the anchor at the SAME instant
            # thread_hash/chain already are (see _probe_and_save_clean_kv's
            # three anchor-write sites), so a same-session curator with a
            # colliding hash still fails this conjunct because the anchor's
            # last-written tip_role reflects main's own prior write, not
            # the curator's current one.
            _cur_adm_role = getattr(slot, "admission_role", "__unset__")
            _cur_tip_role = _norm_tip_role(
                _cur_adm_role if _cur_adm_role != "__unset__"
                else _bin_role(getattr(slot, "client_meta", None))
            )
            _vram_ours = (
                _mem.get("model_tag") == model_tag
                and _mem.get("thread_hash") == self._thread_hash(tid)
                and _mem.get("pid") is not None
                and _mem.get("pid") == getattr(slot, "pid", None)
                and _norm_tip_role(_mem.get("tip_role")) == _cur_tip_role
            )
            _mem_chain = list(_mem.get("chain") or []) if _vram_ours else []
            if found is None:
                decision["event_type"] = self._classify_event(
                    _mem_chain or None, inc_chain, warm_chain)
                decision["saved_chain_fp"] = _chain_fp(_mem_chain or None)
                decision["inc_chain_fp"] = _chain_fp(inc_chain)
                decision["warm_chain_fp"] = _chain_fp(warm_chain or None)
                decision["shape_verdict"] = decision["event_type"]
                decision["role"] = _cur_tip_role
                # Measurement: no disk clean bin exists on
                # this branch (found is None) -- clean_vs_inc/clean_turns
                # stay None (no candidate to compare), not 0 (0 would claim
                # a real empty bin existed).
                decision["warm_vs_inc_divergence_index"] = _chain_divergence_index(
                    warm_chain, inc_chain)
                decision["clean_vs_inc_divergence_index"] = None
                decision["warm_turns"] = len(warm_chain) if warm_chain else None
                decision["clean_turns"] = None
                decision["inc_turns"] = len(inc_chain)
                decision["resolved_from"] = (
                    "warm-vram-anchor-native-reuse" if _mem_chain
                    else "warm-no-clean-bin")
                if _mem_chain:
                    _mc = 0
                    for a, b in zip(_mem_chain, inc_chain, strict=False):
                        if a != b:
                            break
                        _mc += 1
                    decision["common_prefix_turns"] = _mc
                return decision
            bin_fn, clean_chain, sid, _bin_prompt_len, bin_tokens = found
            # No bin-mtime-vs-process-spawn check is applied
            # here, deliberately. The threat model such a check would address --
            # "a bin whose mtime predates the CURRENT engine process's spawn ...
            # was written by a PRIOR process that happened to reuse this port /
            # thread identity (a respawn after crash/redeploy)" -- does not
            # survive scrutiny against what the surrounding code already
            # guarantees: (1) `_find_clean_bin` (a few lines above) is already
            # scoped by `_thread_hash(thread_id)` -- a bin from a genuinely
            # different identity is never even a lookup candidate, so cross-
            # identity contamination isn't reachable here regardless of
            # timing; (2) every bin write in this file goes through an atomic
            # tmp+os.replace (see `_save_slot_kv_inner`, `_save_shadow_slot_kv`,
            # etc.) so a bin on disk is always either fully absent or fully
            # complete -- a crash mid-write cannot leave a partial/corrupt bin
            # for that check to be catching; (3) `clean_chain ⊑ inc_chain` is
            # verified immediately below via the SAME content-hash chain
            # hardened against tool_calls -- a bin whose content doesn't
            # actually match the incoming request is already rejected there,
            # on CONTENT, not on a wall-clock proxy for content. What that check
            # would actually do, given all three of those already hold, is
            # decline the single most common flow this whole mechanism exists
            # to serve -- bins are written ONLY at engine unload
            # (`_save_slot_kv_inner`), never per-turn, so a session that
            # idled out and is resuming on a freshly spawned engine is
            # UNCONDITIONALLY older than that engine's spawn_wall, every time,
            # with no exception anywhere in such a check for "same session,
            # process recycled" vs "genuinely a different world." No bin-
            # identity signal available at this decision site closes that gap
            # without ALSO reintroducing it for the ordinary case (mtime is
            # the only wall-clock-comparable field a bin carries at all, and
            # the only alternative -- stamping a fresh identity/generation
            # marker into every future bin at save time -- would still leave
            # every bin already on disk unprotected AND unrestorable on
            # rollout, a one-time-migration cost the existing design already
            # avoids). The anti-rewind check below is the real,
            # load-bearing anti-rewind protection.
            # Anti-rewind check: ABSOLUTE ANTI-REWIND. Never force-restore
            # a bin whose token count is less than the live warm slot's CURRENT
            # position. live_slot_tokens is read via a direct /slots GET at
            # decision time (matching the verify_kv_restored / manager.py
            # inline-/slots idiom already used elsewhere in this file) -- NOT
            # mgr.live_generation, whose idle-state n_prompt_tokens is a
            # hardcoded 0 (an artifact of the poller cache): a 0 makes
            # `bin_tokens < live_slot_tokens` always False, so the guard would
            # silently never fire in exactly the between-tool-calls window this
            # fix exists for. None (probe failed / slot not found) never
            # declines -- safe-degrade to today's behavior, never a false skip.
            #
            # UNITS: bin_tokens and _live_slot_tokens are both TOKEN counts
            # (meta "prompt_tokens" and /slots "n_prompt_tokens" respectively).
            # NEVER compare either against _bin_prompt_len above, or against
            # admission_ctx_len/compute_ctx_len anywhere else in this file --
            # those are CHARACTER counts, ~3x larger on real prompts, and
            # comparing a character count against a token count here is the
            # exact bug this comment exists to keep from recurring: it makes
            # the guard fire far less often than it should, while looking
            # correct at every level of review short of checking the value.
            #
            # Missing or zero prompt_tokens (older bins predating the field,
            # or a save-path edge case) -> None -> fail-open, never decline.
            if not bin_tokens:
                bin_tokens = None
            _live_slot_tokens = await self._live_slot_token_position(port, sid)
            if (
                _live_slot_tokens is not None
                and bin_tokens is not None
                and bin_tokens < _live_slot_tokens
            ):
                decision["event_type"] = self._classify_event(
                    clean_chain, inc_chain, warm_chain)
                decision["resolved_from"] = "anti-rewind-token-skip"
                decision["clean_bin_id"] = bin_fn
                return decision
            # SPEC-V2 REWORK R2 (staleness gate): NEVER force-restore a disk bin
            # that is staler than the live VRAM state — restoring it would REWIND
            # the slot and throw away the per-turn probe prefill (forbidden by
            # the restore rules). Skip the force IFF the VRAM anchor is OURS, still a
            # valid prefix of the incoming chain, AND at least as long as the
            # disk chain. Same identity => native reuse + the per-turn probe
            # handles the think-tail deltas; foreign/empty VRAM falls through to
            # the disk-restore machinery below unchanged.
            # Option C: when per-turn RAM re-anchor is active, the RAM
            # clean bin IS the fresh state and the restore is REQUIRED to re-commit
            # the engine base (the VRAM tail is think-polluted post-generation and
            # will diverge natively). Do NOT skip the force in that mode.
            if (not _ram_reanchor_enabled()
                    and _mem_chain
                    and _is_prefix_match(_mem_chain, inc_chain)
                    and len(_mem_chain) >= len(clean_chain)):
                decision["event_type"] = self._classify_event(
                    _mem_chain, inc_chain, warm_chain)
                decision["saved_chain_fp"] = _chain_fp(_mem_chain)
                decision["inc_chain_fp"] = _chain_fp(inc_chain)
                decision["warm_chain_fp"] = _chain_fp(warm_chain or None)
                decision["shape_verdict"] = decision["event_type"]
                decision["role"] = _cur_tip_role
                decision["clean_bin_id"] = bin_fn
                # Measurement: the disk clean_chain WAS found
                # (bin_fn/clean_chain/sid, above) even though this branch
                # skips forcing it in favor of the fresher VRAM state -- both
                # candidates are real here.
                decision["warm_vs_inc_divergence_index"] = _chain_divergence_index(
                    warm_chain, inc_chain)
                decision["clean_vs_inc_divergence_index"] = _chain_divergence_index(
                    clean_chain, inc_chain)
                decision["warm_turns"] = len(warm_chain) if warm_chain else None
                decision["clean_turns"] = len(clean_chain)
                decision["inc_turns"] = len(inc_chain)
                _mc = 0
                for a, b in zip(_mem_chain, inc_chain, strict=False):
                    if a != b:
                        break
                    _mc += 1
                decision["common_prefix_turns"] = _mc
                decision["resolved_from"] = "warm-vram-fresher-skip"
                return decision
            clean_valid = _is_prefix_match(clean_chain, inc_chain)
            warm_known = bool(warm_chain)
            warm_covers = (
                warm_known
                and _is_prefix_match(warm_chain, inc_chain)
                and len(warm_chain) >= len(clean_chain)
            )
            # The gate would fire on prefix-validity + warm divergence...
            would_force = clean_valid and warm_known and not warm_covers
            # ...but F2 gates the actual force to the qwen MTP family only.
            qwen_ok = self._is_qwen_family(model_tag)
            force = would_force and qwen_ok
            # common prefix depth (turns) for observability
            common = 0
            for a, b in zip(clean_chain, inc_chain, strict=False):
                if a != b:
                    break
                common += 1
            decision["event_type"] = self._classify_event(clean_chain, inc_chain, warm_chain)
            decision["saved_chain_fp"] = _chain_fp(clean_chain)
            decision["inc_chain_fp"] = _chain_fp(inc_chain)
            decision["warm_chain_fp"] = _chain_fp(warm_chain or None)
            decision["shape_verdict"] = decision["event_type"]
            decision["role"] = _cur_tip_role
            decision["clean_bin_id"] = bin_fn
            # Measurement: the actual force decision (would_
            # force/force/qwen_ok, just above -- READ, not touched) weighs
            # clean vs warm as competing restore candidates; this is the one
            # site where both chains are always real bins/known state, not
            # a stand-in. Read-only measurement of already-computed
            # clean_chain/warm_chain/inc_chain -- does not influence
            # would_force/force/qwen_ok, which are computed above this line
            # and never read back from `decision`.
            decision["warm_vs_inc_divergence_index"] = _chain_divergence_index(
                warm_chain, inc_chain)
            decision["clean_vs_inc_divergence_index"] = _chain_divergence_index(
                clean_chain, inc_chain)
            decision["warm_turns"] = len(warm_chain) if warm_chain else None
            decision["clean_turns"] = len(clean_chain)
            decision["inc_turns"] = len(inc_chain)
            decision["common_prefix_turns"] = common
            # forced_clean_restore stays False until a 2xx restore POST (F5).
            decision["forced_clean_restore"] = False
            if would_force and not qwen_ok:
                # would force, but the model family is out of the proven-safe scope
                decision["resolved_from"] = "warm-non-qwen-skip"
            elif not clean_valid:
                decision["resolved_from"] = "warm-clean-not-prefix"
                # (per the "go back down after a
                # compression event" design): clean anchor is NOT a prefix of incoming ==
                # compression (an early turn was summarized/rewritten). The stale
                # longer/diverged bin can never validly restore now (the physics belt
                # already refuses it) and would keep every turn FRESH. RESET it so the
                # next turn's SCALEUP probe re-anchors a fresh clean bin at the NEW
                # compressed baseline. Best-effort; the restore-gate logic
                # UNTOUCHED (this only removes a file the gate already rejects).
                # Guard: turn-0 divergence (common == 0) is a thread-id
                # COLLISION (two conversations coalesced onto one key), NOT compression.
                # Resetting there would delete/re-save the shared anchor on every
                # interleave (GB-scale churn). Reset only on a real mid-thread rewrite.
                if decision.get("event_type") == "compression" and common > 0:
                    # Prove the requester's role came from an
                    # explicit is_main LABEL (not default, not literal, not inference)
                    # before the reset may touch a main-role bin.
                    from turbohaul.kv_classify import _class_from_label, CLASS_MAIN
                    self._reset_clean_bin(
                        port, model_tag, tid, bin_fn,
                        requester_is_labeled_main=(
                            _class_from_label(getattr(slot, "client_meta", None) or {}) == CLASS_MAIN))
            elif warm_covers:
                decision["resolved_from"] = "warm-native-reuse-longer"
            elif not force:
                decision["resolved_from"] = "warm-state-unknown-safe"
            # --- crit3: TOOL-tail restore SKIP (Option A) ---------------
            # The force gate above trusts the chain-prefix match, but _prefix_hash_
            # chain is BLIND to tool turns (assistant tool_calls / role=="tool" / null
            # content). If the divergent tail beyond `common` is tool-opaque, the
            # harness re-serializes that region nondeterministically -> forcing the
            # clean/shadow bin would POST token-stale KV -> engine stale>n_rs_seq
            # CLEAR -> full reprefill (a REGRESSION vs native warm reuse). Safe-
            # degrade: DON'T force -> the engine's own get_common_prefix checkpoint
            # reuse runs. Only skips the FORCE; a TEXT/think-strip tail (hash-
            # verifiable, no tool turn beyond common) STILL forces + still gets the
            # crit2 shadow-restore-preference. Flag-gated (default ON) for A/B
            # rollback. Runs AFTER the resolved_from chain so its distinct reason is
            # not overwritten, and BEFORE the `if force:` restore block so the POST
            # (clean AND the shadow-preferred target inside it) is fully gated.
            if (force and _tooltail_restore_skip_enabled()
                    and _divergent_tail_is_tool_opaque(
                        inc_messages, common,
                        scan_covered=_tooltail_scan_covered_enabled())):
                force = False
                self._kv_tooltail_skip_counts["warm"] = (
                    self._kv_tooltail_skip_counts.get("warm", 0) + 1)
                decision["resolved_from"] = "warm-tooltail-skip"
                log.info(
                    "crit3 warm TOOL-tail restore SKIP: divergent tail "
                    "beyond common=%d is tool-opaque (hash-invisible) -> NOT forcing "
                    "clean/shadow restore; safe-degrade to engine native reuse "
                    "(thread=%s, incoming_turns=%d, clean_bin=%s)",
                    common, tid[:12], len(inc_chain), bin_fn,
                )
            # --- STALE-tail restore SKIP -------------------------------------------
            # The force gate above trusts the chain-prefix match, but does not ask
            # whether the RESIDENT warm state has MORE turns than the INCOMING request
            # itself represents. When it does, restoring the shorter clean bin leaves
            # the surplus warm KV resident; the engine's trim budget for that surplus
            # is small and fixed, and any multi-turn surplus exceeds it -> engine
            # CLEAR + full reprefill, worse than the divergence the restore was meant
            # to avoid. Compared against inc_chain, NOT clean_chain: a clean bin can
            # legitimately trail a healthy conversation by several turns (that is what
            # restoring it is for) -- warm exceeding the INCOMING turn count is what
            # `_is_prefix_match` (kv_policy) structurally refuses outright, so
            # `warm_turns > inc_turns` can only mean the surplus does not belong to
            # this conversation's own trajectory. Turn-count proxy (see
            # _staletail_restore_skip_enabled): the manager has no token-level
            # staleness figure here, so any such surplus is treated as unsafe
            # regardless of size. Flag-gated (default ON -- decline-only, cannot
            # corrupt state). Runs AFTER the tool-tail skip (both may fire
            # independently; only the first to flip `force` sets `resolved_from`) and
            # BEFORE the `if force:` restore block so the POST is fully gated either
            # way.
            if (force and _staletail_restore_skip_enabled()
                    and len(warm_chain) > len(inc_chain)):
                force = False
                self._kv_staletail_skip_counts["warm"] = (
                    self._kv_staletail_skip_counts.get("warm", 0) + 1)
                decision["resolved_from"] = "warm-staletail-skip"
                log.info(
                    "warm STALE-tail restore SKIP: warm_turns=%d > incoming_turns=%d "
                    "(resident state has more turns than the current request) -> NOT "
                    "forcing clean/shadow restore; safe-degrade to engine native "
                    "reuse (thread=%s, clean_turns=%d, clean_bin=%s)",
                    len(warm_chain), len(inc_chain), tid[:12], len(clean_chain), bin_fn,
                )
            if force:
                # F5: only count the forced restore AFTER the engine ACKs it (2xx).
                # A 500'd restore leaves the decode on the polluted warm KV, so the
                # metric must NOT claim a clean restore that never landed.
                decision["action"] = "restore"
                # --- SHADOW-BIN RESTORE-PREFERENCE (flag-gated) ---
                # The gate ABOVE is UNCHANGED and alone decides WHETHER to force + which
                # CLEAN anchor (bin_fn/clean_chain/sid). Here we ONLY upgrade the restore
                # TARGET: when TURBOHAUL_SHADOW_RESTORE_PREFER is ON, prefer the think-free
                # `.shadow` bin (turns 1..N + think-free assistant-N, saved by step c) over
                # the shorter clean anchor (turns 1..N) IFF the shadow bin passes the SAME
                # prefix-validity bar the clean path uses (_is_prefix_match vs inc_chain)
                # AND is at least as long (no-downgrade — mirrors warm_covers' >= rule so a
                # preference can only ever GROW the reused prefix, never shrink it). A
                # longer valid prefix => the next decode STRICT-EXTENDS the think-free state
                # (it skips reprefilling assistant-N) instead of the against-3 collapse.
                # A shadow that is stale / not a prefix / shorter is NOT preferred -> we
                # fall through to EXACTLY today's clean anchor. Flag OFF => this whole block
                # is skipped and r_* stay the clean values => the restore is byte-identical
                # to today.
                #
                # CORRECTNESS BACKSTOP (why the preference is safe): the engine's
                # get_common_prefix is authoritative on the next decode — even a wrongly-
                # preferred shadow bin only makes the engine find the REAL common prefix and
                # reprefill the divergent tail (a REPREFILL, never a wrong answer; identical
                # safety to today's clean restore). Do NOT bypass or alter that behavior; it
                # is what lets this stay a pure WHICH-VALID-BIN preference.
                r_bin, r_sid, r_chain, r_kind = bin_fn, sid, clean_chain, "clean"
                # candidates: every bin this decision actually looked at,
                # not just the one it picked -- the clean anchor is always
                # a candidate; the shadow bin joins the list only when the
                # preference lookup below actually ran.
                _candidates = [{"bin": bin_fn, "turns": len(clean_chain)}]
                if _shadow_restore_prefer_enabled():
                    try:
                        _sh = self._find_shadow_bin(port, model_tag, tid)
                        if _sh is not None:
                            _candidates.append({"bin": _sh[0], "turns": len(_sh[1])})
                        if (_sh is not None
                                and _is_prefix_match(_sh[1], inc_chain)
                                and len(_sh[1]) >= len(clean_chain)):
                            r_bin, r_chain, r_sid, r_kind = _sh[0], _sh[1], _sh[2], "shadow"
                            self._kv_shadow_restore_counts["preferred"] = (
                                self._kv_shadow_restore_counts.get("preferred", 0) + 1)
                        else:
                            self._kv_shadow_restore_counts["clean_fallback"] = (
                                self._kv_shadow_restore_counts.get("clean_fallback", 0) + 1)
                            if _sh is not None:
                                log.info(
                                    "shadow restore-preference: shadow bin present but NOT "
                                    "preferred (shadow_turns=%d, clean_turns=%d, prefix=%s) "
                                    "-> using clean anchor for thread=%s",
                                    len(_sh[1]), len(clean_chain),
                                    _is_prefix_match(_sh[1], inc_chain), tid[:12])
                    except Exception:
                        log.debug("shadow restore-preference lookup failed (best-effort); "
                                  "using clean anchor", exc_info=True)
                # SKIP-REDUNDANT-RESTORE: when the engine's natural
                # slot state IS already this thread's clean anchor (the per-turn
                # clean-prefix save is taken FROM the natural state and stamps
                # _kv_vram_anchor with the exact saved chain), re-POSTing
                # action=restore is a content no-op but arms the engine's
                # restored-slot handling — and a chat serve on a restored slot
                # deterministically fails M-RoPE batch init (X<Y) -> 500 ->
                # prompt_clear -> FULL reprefill (100-160s/turn; 2026-07-09
                # receipts: serve tasks 746/1523/2523 canceled, 777/1531/2555 full
                # clears). Chain equality proves the natural state matches the bin
                # byte-for-byte at save time; any OTHER identity's confirmed save
                # overwrites the anchor, so a NEEDED restore is never skipped. An
                # engine relaunch leaves a stale anchor -> the skip serves on an
                # empty slot -> one full native reprefill (the cost the crash path
                # already paid, minus the 500).
                # The skip is only VALID when the natural state
                # equals the RESEND byte-for-byte. For a thinking model whose harness
                # drops reasoning on resent turns, the natural state carries generated
                # <think> the resend lacks, so the stripped clean bin (NOT natural) is
                # what matches -> default OFF -> fall through to forced-clean-restore.
                _anch = self._kv_vram_anchor.get(port) or {}
                if (_warm_natural_skip_enabled()
                        and r_kind == "clean"
                        and _anch.get("model_tag") == model_tag
                        and list(_anch.get("chain") or []) == list(clean_chain)):
                    decision["forced_clean_restore"] = False
                    decision["clean_bin_id"] = bin_fn
                    decision["resolved_from"] = "warm-anchor-natural-skip"
                    log.info(
                        "the classifier warm-path restore SKIPPED (natural state == clean anchor): "
                        "%s (engine_slot=%d, thread=%s, clean_turns=%d <= incoming_turns=%d)",
                        bin_fn, sid, tid[:12], len(clean_chain), len(inc_chain))
                    return decision
                posted_ok = False
                try:
                    async with httpx.AsyncClient(
                        timeout=httpx.Timeout(connect=2.0, read=120.0, write=10.0, pool=1.0)
                    ) as client:
                        resp = await client.post(
                            f"http://127.0.0.1:{port}/slots/{r_sid}?action=restore",
                            json={"filename": r_bin},
                        )
                        resp.raise_for_status()
                    posted_ok = True
                except Exception:
                    log.warning(
                        "the classifier forced clean restore POST failed: %s (engine_slot=%d, thread=%s)",
                        r_bin, r_sid, tid[:12], exc_info=True,
                    )
                if posted_ok:
                    decision["forced_clean_restore"] = True
                    decision["clean_bin_id"] = r_bin  # reflect what actually restored
                    # Observability: the fields that would have made
                    # the discarded-warm-slot regression self-announcing.
                    # warm_slot_turns/discarded_turns come from warm_chain,
                    # this function's own parameter -- real, not guessed.
                    # warm_slot_tokens/discarded_tokens are explicit nulls:
                    # warm_chain carries per-turn HASHES, never a char/token
                    # count, so no token-level size is derivable at this
                    # point without an additional live /slots query -- a
                    # judgment call to not add on this path, flagged rather
                    # than silently approximated.
                    decision["chosen_bin"] = r_bin
                    decision["chosen_turns"] = len(r_chain)
                    decision["warm_slot_turns"] = len(warm_chain)
                    decision["warm_slot_tokens"] = "unavailable"
                    decision["discarded_turns"] = len(warm_chain)
                    decision["discarded_tokens"] = "unavailable"
                    decision["candidates"] = _candidates
                    decision["rule_name"] = "FORCE_CLEAN_WARM_DIVERGES_QWEN_FAMILY"
                    if r_kind == "shadow":
                        decision["resolved_from"] = "warm-force-shadow-restore"
                        log.info(
                            "warm-path forced SHADOW restore: %s (engine_slot=%d, "
                            "thread=%s, shadow_turns=%d <= incoming_turns=%d; clean anchor "
                            "%s had %d turns; warm_slot_turns=%d discarded_turns=%d "
                            "discarded_tokens=%s rule=%s)",
                            r_bin, r_sid, tid, len(r_chain), len(inc_chain),
                            bin_fn, len(clean_chain),
                            len(warm_chain), len(warm_chain),
                            decision["discarded_tokens"], decision["rule_name"],
                        )
                    else:
                        decision["resolved_from"] = "warm-force-clean-restore"
                        log.info(
                            "warm-path forced clean restore: %s (engine_slot=%d, thread=%s, "
                            "clean_turns=%d <= incoming_turns=%d; warm_slot_turns=%d "
                            "discarded_turns=%d discarded_tokens=%s rule=%s)",
                            r_bin, r_sid, tid, len(r_chain), len(inc_chain),
                            len(warm_chain), len(warm_chain),
                            decision["discarded_tokens"], decision["rule_name"],
                        )
                else:
                    # attempted-but-failed: metric stays truthful (not counted)
                    decision["resolved_from"] = "warm-force-restore-failed"
            return decision
        except Exception:
            log.debug("the classifier warm-path force restore best-effort failed", exc_info=True)
            return decision
        finally:
            self._emit_classifier_decision(decision)

    def _log_kv_restore_diag(self, *, thread_hash: str, model_tag: str, slot_id,
                             chosen: str, resolved_from: str, clean_bin_present: bool,
                             shadow_bin_present: bool, common_prefix_turns: int,
                             incoming_turns: int, restore_bin,
                             saved_chain: list | None = None,
                             incoming_chain: list | None = None) -> None:
        """shadow-diag: one grep-able ``KV_RESTORE`` line per cold restore
        decision + bump the /status shadow_diag ``restores`` counter, correlatable to
        the engine's per-task outcome line via {thread_hash, model_tag, restore_bin}.
        Snapshots the ceiling-GC memory-pressure state (total/over_cap from the last
        GC pass) so a forcing-full restore is joinable to KV pressure at that instant.
        INSTRUMENTATION ONLY — reads state, derives the divergence index from the
        supplied chains (via the pure _first_divergent_turn_index), emits a line,
        never changes a decision; best-effort (never raises). Off the response
        hot path (spawn/swap-back)."""
        try:
            self._shadow_diag_counts["restores"][chosen] = (
                self._shadow_diag_counts["restores"].get(chosen, 0) + 1)
            snap = self._last_kvgc_snapshot or {}
            # When both turn-hash chains are in scope, report the
            # TRUE first-diverging turn index (the pure helper) — the exit
            # sites pass a hardcoded common_prefix_turns (often 0) even when
            # the chains say otherwise. Chains absent -> keep the passed
            # value. The engine's own get_common_prefix stays the final
            # byte-level authority.
            if saved_chain is not None and incoming_chain is not None:
                _div_pos = _first_divergent_turn_index(saved_chain, incoming_chain)
            else:
                _div_pos = common_prefix_turns
            # The winning bin's own save provenance (which cap arm
            # wrote it) — best-effort sidecar read; "unknown" for bins that
            # predate the field or whose meta is already gone.
            _bin_prov = "unknown"
            _probed_fp = "-"
            _probed_arm = "-"
            _ev_delta = "-"
            if restore_bin:
                try:
                    from turbohaul.subprocess_mgr import SLOT_SAVE_DIR as _ssd
                    _prov_p = os.path.join(_ssd, str(restore_bin)[:-4] + ".json")
                    if os.path.exists(_prov_p):
                        _prov_meta = json.load(open(_prov_p))
                        _bp = _prov_meta.get("bin_provenance")
                        if _bp:
                            _bin_prov = _bp
                        # The save-side evidence binding
                        # for this bin (absent on older bins -> "-", the
                        # line stays parseable; existing fields never move).
                        if _prov_meta.get("probed_chain_fp"):
                            _probed_fp = str(_prov_meta["probed_chain_fp"])
                        if _prov_meta.get("probed_arm"):
                            _probed_arm = str(_prov_meta["probed_arm"])
                        if _prov_meta.get("evidence_delta") is not None:
                            _ev_delta = str(_prov_meta["evidence_delta"])
                except Exception:
                    pass
            log.info(
                "KV_RESTORE th=%s model=%s slot=%s chosen=%s resolved_from=%s "
                "clean_bin_present=%s shadow_bin_present=%s common_prefix_turns=%d "
                "divergence_pos=%d incoming_turns=%d restore_bin=%s "
                "bin_provenance=%s kv_total_bytes=%d kv_over_cap=%d "
                "probed_chain_fp=%s probed_arm=%s evidence_delta=%s",
                thread_hash, model_tag, slot_id, chosen, resolved_from,
                clean_bin_present, shadow_bin_present, common_prefix_turns,
                _div_pos, incoming_turns, restore_bin, _bin_prov,
                snap.get("total_bytes", -1), snap.get("over_cap", -1),
                _probed_fp, _probed_arm, _ev_delta,
            )
        except Exception:
            log.debug("KV_RESTORE diag log best-effort failed", exc_info=True)

    def _log_shadow_byteparity(self, *, thread_id: str, thread_hash: str,
                               model_tag: str, inc_messages: list) -> None:
        """shadow-diag refinement (the load-bearing one): when a
        ``.shadow`` bin is in play, compare the manager's RECONSTRUCTED think-free
        assistant render (from the per-(thread,model) shadow-diag recon store, so it
        survives intervening saves of other threads on a swap-back)
        against the harness's INCOMING resend of that same turn (from
        ``inc_messages``) — {len, FNV hash, match bool, first-diverging byte offset}.

        A ``first_diff_offset >= 0`` points straight at candidate (d)
        saved-but-BYTE-DIVERGES (the reconstructed merges reasoning_content+content
        into ONE <think> block vs the harness's interleaved multi-block) versus (c)
        wrong-bin (where the shadow simply was not selected). Both sides pass through
        the SAME ``_strip_thinking_all`` the shadow SAVE uses, so this measures
        exactly what the save produced. INSTRUMENTATION ONLY: no engine call, no raw
        content logged (lengths + FNV + offset only), best-effort (never raises),
        off the response hot path."""
        try:
            from turbohaul.api.chat_completion import _strip_thinking_all
            bp = self._shadow_diag_counts["byteparity"]
            # recon = the think-free assistant turn the manager SAVED into the shadow,
            # read from the per-(thread_id, model_tag) shadow-diag store so it is CLOBBER-
            # PROOF across intervening shadow saves of OTHER threads. On a swap-back
            # (27b saved -> 35b sub-agent saves -> 27b restore) the single-global
            # _last_shadow_src would already hold the 35b source, blinding (d); this
            # per-key store keeps 27b's. Pure instrumentation — _last_shadow_src + the
            # swap-belt are untouched. None -> no reconstruct source recorded.
            recon = self._byteparity_recon_by_key.get((thread_id, model_tag))
            # resend = the harness's resent assistant-N turn (already think-stripped).
            resend = None
            for m in reversed(inc_messages or []):
                if isinstance(m, dict) and m.get("role") == "assistant":
                    resend = m.get("content")
                    break
            if not isinstance(recon, str) or not isinstance(resend, str):
                bp["no_recon_src"] = bp.get("no_recon_src", 0) + 1
                log.info(
                    "SHADOW_BYTEPARITY th=%s model=%s recon_len=-1 resend_len=%d "
                    "match=na first_diff_offset=-1 note=no-reconstruct-source",
                    thread_hash, model_tag,
                    len(resend) if isinstance(resend, str) else -1)
                return
            recon_tf = _strip_thinking_all(recon)
            resend_tf = _strip_thinking_all(resend)
            fdo = _first_diff_offset(recon_tf, resend_tf)
            match = fdo == -1
            key = "match" if match else "diverge"
            bp[key] = bp.get(key, 0) + 1
            log.info(
                "SHADOW_BYTEPARITY th=%s model=%s recon_len=%d recon_hash=%s "
                "resend_len=%d resend_hash=%s match=%s first_diff_offset=%d",
                thread_hash, model_tag, len(recon_tf), _fnv1a_64(recon_tf),
                len(resend_tf), _fnv1a_64(resend_tf), match, fdo,
            )
        except Exception:
            log.debug("SHADOW_BYTEPARITY diag best-effort failed", exc_info=True)

    @staticmethod
    def _divergence_dump_write(debug_file: str, entry: dict, *, max_bytes: int | None = None) -> None:
        """Single chokepoint for every divergence-capture JSONL append (Case A,
        the tool-opaque extended byte-diff, and the benign length-mismatch
        record in _log_serve_divergence / _dump_apply_template_byte_diff all
        route through here) -- same one-write-path discipline as the other
        instruments built in this module.

        Creates the parent directory if it does not already exist. A write
        failure here is not a degraded mode: this facility exists solely to
        produce this file, so a write that fails IS the feature failing.
        ERROR, always, with the traceback -- never debug, never a silent
        swallow. An instrument that announces a capture at INFO while the
        capture itself silently fails is exactly the class of defect this
        rule exists to eliminate everywhere else.

        max_bytes: when set, and the target already meets or exceeds this
        size BEFORE the append, the current file is rolled aside to a single
        ".1" backup (overwriting any prior one) and a fresh file started.
        Only the benign, high-volume record passes this -- the valuable
        capture file passes None and is never capped, appended forever, by
        design.
        """
        try:
            _dir = os.path.dirname(debug_file)
            if _dir:
                os.makedirs(_dir, exist_ok=True)
            if max_bytes is not None:
                try:
                    if os.path.getsize(debug_file) >= max_bytes:
                        os.replace(debug_file, debug_file + ".1")
                except FileNotFoundError:
                    pass  # nothing written yet -- no roll needed
            with open(debug_file, "a") as f:
                f.write(json.dumps(entry, ensure_ascii=False) + "\n")
            log.info("DIVERGENCE_DUMP: entry written to %s", debug_file)
        except Exception:
            log.error(
                "DIVERGENCE_DUMP: write to %s FAILED -- the capture facility is "
                "enabled and believes it captured this event, but nothing was "
                "written to disk",
                debug_file, exc_info=True,
            )

    def _log_serve_divergence(self, matched, incoming_chain: list, incoming_messages: list, port: int) -> None:
            """Log-only divergence capture for prompt-determinism debugging.

            Called from BOTH the warm-serve path (ACTIVE_MATCH grace-window
            follow-up) and the cold-restore path (first request after a full
            unload) -- the divergence this facility exists to catch can occur
            on either. self._divergence_prev is keyed by (thread_id, model_tag)
            only, not by which path served the turn, so the rolling history it
            compares against is continuous across both.

            GATED OFF by default (TURBOHAUL_DIVERGENCE_DEBUG != '1' → instant return).
            When opted in: stash previous-turn chain + messages in self._divergence_prev,
            diff incoming vs previous element-by-element, and — ONLY when divergence is
            detected (Case A) or length-mismatch — dump to disk (never on healthy turns).

            The disk record is split into two files by value, not rotated: Case A and
            the extended tool-opaque byte-diff below are the rare, diagnostically
            valuable records this facility exists to produce, and go to
            _DIVERGENCE_CAPTURE_FILE, appended forever, never capped. length_mismatch
            is the high-volume benign case (turn count changed, common prefix still
            matched) and goes to the separate _DIVERGENCE_BENIGN_FILE, so its volume
            can never put the valuable file at risk.

            Case A: chains differ at turn K → divergence in role or content (both hashed).
            Neutral (was 'Case B'): chains identical → log only, no file write (may be
              healthy reuse or Case-B; confirm requires cross-ref engine log for THIS turn
              restored pos_min vs prompt tokens).
            length_mismatch: turn count changed but common prefix matched.

            Extended confirm-capture (tool-opaque divergence only): when Case A divergence
            occurs at a tool-opaque turn (assistant+tool_calls or role=tool), dump both
            the /apply-template render of the FULL incoming prompt AND the clean-bin's
            saved render (via /apply-template on clean_messages slice), byte-diff them,
            and log first differing offset + snippets. This isolates whether the bug is:
            - MATCH → native-reuse is the bug, force clean-restore on tool-call turns
            - DIFFER → apply-template/strip render is non-deterministic, fix the render

            Never-raises: all errors swallowed except the dump write itself, which is
            loud on failure (see _divergence_dump_write) -- this facility exists solely
            to produce that file, so a failed write is total failure of the feature, not
            a degraded mode, and must never be swallowed at debug level.
            """
            # Gate: opt-in debug only (never fires in production).
            if os.environ.get("TURBOHAUL_DIVERGENCE_DEBUG", "") != "1":
                return
            # Second gate: deployed sentinel file (PL controls when capture runs).
            import pathlib
            if not pathlib.Path("/var/lib/turbohaul/.divergence_debug").exists():
                return
            try:
                thread_id = getattr(matched, "thread_id", "") or ""
                model_tag = getattr(matched, "model_tag", "") or ""
                key = (thread_id, model_tag)
                prev = self._divergence_prev.get(key)
                prev_chain = prev["chain"] if prev else None
                prev_messages = prev["messages"] if prev else None

                if prev_chain is None:
                    log.info("DIVERGENCE_DUMP: first observed serve for thread=%s model=%s, stashing initial state", thread_id, model_tag)
                    self._divergence_prev[key] = {"chain": list(incoming_chain), "messages": list(incoming_messages)}
                    return

                # Diff chains element-by-element
                min_len = min(len(prev_chain), len(incoming_chain))
                first_divergent_turn = -1
                for i in range(min_len):
                    if prev_chain[i] != incoming_chain[i]:
                        first_divergent_turn = i
                        break

                if first_divergent_turn >= 0:
                    # Case A: divergence in role or content (both hashed)
                    prev_msg = prev_messages[first_divergent_turn] if first_divergent_turn < len(prev_messages) else {}
                    inc_msg = incoming_messages[first_divergent_turn] if first_divergent_turn < len(incoming_messages) else {}
                    def _scan_think(content):
                        return "think" in repr(content) if content else False
                    log.info(
                        "DIVERGENCE_DUMP: case=A thread=%s model=%s first_divergent_turn=%d "
                        "prev_role=%s incoming_role=%s prev_tool_calls=%s incoming_tool_calls=%s "
                        "prev_think=%s incoming_think=%s "
                        "prev_content=%s incoming_content=%s "
                        "prev_chain=%s incoming_chain=%s",
                        thread_id, model_tag, first_divergent_turn,
                        prev_msg.get("role", "?"), inc_msg.get("role", "?"),
                        repr(prev_msg.get("tool_calls"))[:200] if prev_msg.get("tool_calls") else "None",
                        repr(inc_msg.get("tool_calls"))[:200] if inc_msg.get("tool_calls") else "None",
                        _scan_think(prev_msg.get("content")), _scan_think(inc_msg.get("content")),
                        repr(prev_msg.get("content", ""))[:400], repr(inc_msg.get("content", ""))[:400],
                        prev_chain[first_divergent_turn][:16], incoming_chain[first_divergent_turn][:16]
                    )
                    # Dump full messages (ONLY when divergence detected — not every
                    # turn) to the rare/valuable capture file, never rotated.
                    self._divergence_dump_write(_DIVERGENCE_CAPTURE_FILE, {
                        "ts": datetime.now().isoformat(sep=" ", timespec="seconds"),
                        "thread_id": thread_id,
                        "model_tag": model_tag,
                        "first_divergent_turn": first_divergent_turn,
                        "turns": len(incoming_chain),
                        "incoming_chain": incoming_chain,
                        "incoming_messages": incoming_messages,
                        "prev_chain": prev_chain,
                        "prev_messages": prev_messages,
                    })

                elif len(prev_chain) != len(incoming_chain):
                    # Length mismatch: turn count changed but common prefix matched.
                    log.info(
                        "DIVERGENCE_DUMP: case=length_mismatch thread=%s model=%s turns_prev=%d turns_incoming=%d",
                        thread_id, model_tag, len(prev_chain), len(incoming_chain)
                    )
                    # Benign, high-volume case -- its own file, separate from the
                    # valuable Case-A capture above, so its volume can never put
                    # a rare divergence record at risk. Capped: losing this one
                    # costs nothing, and it carries full message content on
                    # every entry, so it must not grow unbounded if left on.
                    self._divergence_dump_write(_DIVERGENCE_BENIGN_FILE, {
                        "ts": datetime.now().isoformat(sep=" ", timespec="seconds"),
                        "thread_id": thread_id,
                        "model_tag": model_tag,
                        "case": "length_mismatch",
                        "turns_prev": len(prev_chain),
                        "turns_incoming": len(incoming_chain),
                        "incoming_messages": incoming_messages,
                        "prev_messages": prev_messages,
                    }, max_bytes=_DIVERGENCE_BENIGN_MAX_BYTES)

                else:
                    # Neutral: chains identical. May be healthy reuse or Case-B (unhashed field
                    # divergence). Confirm Case-B requires cross-ref engine log: restored pos_min
                    # vs prompt tokens on THIS turn. Log only, no file write (would spam on healthy).
                    log.info(
                        "DIVERGENCE_DUMP: chains_identical=True thread=%s model=%s turns=%d "
                        "(Case-B confirm requires cross-ref engine log restored pos_min for this turn)",
                        thread_id, model_tag, len(incoming_chain)
                    )

                # EXTENDED CONFIRM-CAPTURE (B4): decoupled from case=A gate.
                # Fire on ALL branches whenever incoming has a tool-opaque tail
                # beyond the clean-bin prefix (sub-hash divergence, invisible to
                # _prefix_hash_chain). Uses the canonical helper.
                try:
                    if port:
                        slot_meta = getattr(matched, "client_meta", None) or {}
                        found = self._find_clean_bin(port, model_tag, thread_id)
                        if found:
                            _bin_fn, clean_chain, _sid, _prompt_len, _prompt_tokens = found
                            clean_len = len(clean_chain)
                            if clean_len > 0 and clean_len <= len(incoming_messages):
                                if _divergent_tail_is_tool_opaque(incoming_messages, clean_len):
                                    # Find the last tool-opaque turn index in the tail for logging
                                    tail_idx = -1
                                    for i in range(clean_len, len(incoming_messages)):
                                        if _turn_is_tool_opaque(incoming_messages[i]):
                                            tail_idx = i
                                    self._spawn_bg(self._dump_apply_template_byte_diff(
                                        port, model_tag, thread_id, incoming_messages, incoming_chain, tail_idx, slot_meta
                                    ))
                except Exception:
                    log.debug("EXTENDED_CAPTURE: tool-opaque tail check best-effort failed", exc_info=True)

                # Stash current state for next turn (keyed by identity, survives Slot replacement).
                self._divergence_prev[key] = {"chain": list(incoming_chain), "messages": list(incoming_messages)}

            except Exception:
                log.debug("DIVERGENCE_DUMP: logging best-effort failed", exc_info=True)

    async def _dump_apply_template_byte_diff(self, port: int, model_tag: str, thread_id: str,
                                             incoming_messages: list, incoming_chain: list,
                                             divergent_turn: int, meta: dict) -> None:
            """Extended confirm-capture: byte-diff /apply-template render of FULL
            incoming prompt vs clean-bin slice on tool-opaque divergence turn.

            When clean ⊑ incoming, the clean bin's messages = incoming_messages[:len(clean_chain)].
            We render both via /apply-template (same tool knobs, same strip) and diff the
            resulting prompts. If they MATCH → native-reuse is the bug (force clean-restore).
            If they DIFFER → apply-template/strip is non-deterministic (fix the render).

            Log-only, gated, never-raises.
            """
            try:
                # Find the clean bin for this (thread, model, port)
                found = self._find_clean_bin(port, model_tag, thread_id)
                if not found:
                    return
                _bin_fn, clean_chain, _sid, _prompt_len, _prompt_tokens = found
                clean_len = len(clean_chain)
                if clean_len == 0 or clean_len > len(incoming_messages):
                    return

                # Build meta with tool knobs (same as _render_and_prefill_clean_kv)
                meta = meta or {}
                apply_meta = {}
                for _k in _KV_PROBE_TOOL_KNOBS:
                    _v = meta.get(_k)
                    if _v is not None:
                        apply_meta[_k] = _v

                base = f"http://127.0.0.1:{port}"
                import httpx

                async def _render_via_apply_template(messages_subset: list) -> str | None:
                    payload = {"messages": messages_subset}
                    payload.update(apply_meta)
                    try:
                        async with httpx.AsyncClient(timeout=httpx.Timeout(connect=2.0, read=30.0, write=10.0, pool=1.0)) as client:
                            r = await client.post(f"{base}/apply-template", json=payload)
                            r.raise_for_status()
                            rendered = (r.json() or {}).get("prompt")
                            if not isinstance(rendered, str) or not rendered:
                                return None
                            return _strip_think_scaffold(rendered, messages_subset)
                    except Exception:
                        return None

                # Full incoming render
                full_render = await _render_via_apply_template(incoming_messages)
                if full_render is None:
                    return

                # Clean-bin slice render (first clean_len messages)
                clean_messages = incoming_messages[:clean_len]
                clean_render = await _render_via_apply_template(clean_messages)
                if clean_render is None:
                    return

                # Byte-diff
                if full_render == clean_render:
                    log.info(
                        "EXTENDED_CAPTURE: MATCH — /apply-template(full) == /apply-template(clean_slice) "
                        "thread=%s model=%s divergent_turn=%d clean_len=%d full_len=%d "
                        "=> native-reuse is the bug (force clean-restore on tool-call turns)",
                        thread_id, model_tag, divergent_turn, clean_len, len(incoming_messages)
                    )
                else:
                    # Find first differing byte
                    first_diff = -1
                    min_len = min(len(full_render), len(clean_render))
                    for i in range(min_len):
                        if full_render[i] != clean_render[i]:
                            first_diff = i
                            break
                    if first_diff == -1 and len(full_render) != len(clean_render):
                        first_diff = min_len

                    # Log snippets around first diff (repr to expose whitespace)
                    snippet_full = repr(full_render[max(0, first_diff-80):first_diff+80])
                    snippet_clean = repr(clean_render[max(0, first_diff-80):first_diff+80])
                    log.info(
                        "EXTENDED_CAPTURE: DIFFER — /apply-template(full) != /apply-template(clean_slice) "
                        "thread=%s model=%s divergent_turn=%d clean_len=%d full_len=%d "
                        "first_diff=%d full_snippet=%s clean_snippet=%s "
                        "=> apply-template/strip render is non-deterministic (fix the render)",
                        thread_id, model_tag, divergent_turn, clean_len, len(incoming_messages),
                        first_diff, snippet_full, snippet_clean
                    )

                    # Also dump full renders for offline byte-diff -- this is the
                    # extended confirm-capture, the same rare/valuable category as
                    # Case A above, so it goes to the same never-rotated file.
                    self._divergence_dump_write(_DIVERGENCE_CAPTURE_FILE, {
                        "ts": datetime.now().isoformat(sep=" ", timespec="seconds"),
                        "thread_id": thread_id,
                        "model_tag": model_tag,
                        "case": "extended_capture_tool_opaque",
                        "divergent_turn": divergent_turn,
                        "clean_len": clean_len,
                        "full_len": len(incoming_messages),
                        "first_diff": first_diff,
                        "full_render": full_render,
                        "clean_render": clean_render,
                    })

            except Exception:
                log.debug("EXTENDED_CAPTURE: outer best-effort failed", exc_info=True)

    @staticmethod
    def _cold_restore_bin_token_count(bin_fn: str) -> "int | None":
        """Best-effort read of a restore candidate's OWN recorded
        token count from its `.json` sidecar (mirrors the exact meta-read
        pattern `_restore_slot_kv_inner` already uses to build the `restore`
        candidate list). Needed because a `.shadow` bin's token count is never
        threaded through `_find_shadow_bin`'s 3-tuple return — `saved_n` from
        the clean-anchor selection is the WRONG count once the shadow-
        preference block has overridden `r_bin` to a shadow bin. Returns None
        (never raises) on any I/O/parse error or if the field is absent —
        the caller treats None as fail-open, same as every other best-effort
        read on this path."""
        from turbohaul.subprocess_mgr import SLOT_SAVE_DIR
        try:
            jpath = os.path.join(SLOT_SAVE_DIR, bin_fn[:-4] + ".json")
            with open(jpath) as f:
                meta = json.load(f)
            n = meta.get("prompt_tokens")
            return int(n) if n is not None else None
        except Exception:
            return None

    @staticmethod
    def _cold_restore_bin_tools_fingerprint(bin_fn: str) -> "str | None":
        """Best-effort read of a
        restore candidate's OWN recorded tools fingerprint from its `.json`
        sidecar (mirrors `_cold_restore_bin_token_count` exactly, same
        rationale: the field is never threaded through the `restore` 5-tuple
        or the shadow-preference override, so it must be re-read for
        whichever bin `r_bin` ends up pointing at). Returns None (never
        raises) on ANY I/O/parse/type error OR if the field is simply absent
        (an old, pre-fingerprint bin) — this is deliberate and load-
        bearing: the caller's `_classify_tools_fingerprint_restore_guard`
        treats None as fail-open, so a decode failure on a legacy bin must
        degrade to "no evidence", never surface as a hard failure that would
        turn a fail-open into a crash."""
        from turbohaul.subprocess_mgr import SLOT_SAVE_DIR
        try:
            jpath = os.path.join(SLOT_SAVE_DIR, bin_fn[:-4] + ".json")
            with open(jpath) as f:
                meta = json.load(f)
            fp = meta.get("tools_fingerprint")
            return str(fp) if fp is not None else None
        except Exception:
            return None

    async def _cold_restore_incoming_token_count(
            self, port: int, messages: list, client_meta: "dict | None") -> "int | None":
        """Live, real TOKEN count for what the
        INCOMING request actually renders to, via the exact `/apply-template`
        idiom `_render_strip_prefill_probe` already uses (same
        `_KV_PROBE_TOOL_KNOBS` forwarding, so a tools-bearing request tokenizes
        the tools preamble too — the documented gap this guard exists partly
        to catch: "`tools` is NOT in the hash chain... this changes ONLY
        prefill rendering"), followed by `/tokenize` — NOT `/completion`,
        deliberately: `/tokenize` only runs the tokenizer (server-context.cpp
        `post_tokenize`, stateless, no KV/slot interaction), so this probe
        never mutates the freshly-spawned engine's slot the way an
        `n_predict=0` `/completion` prefill would — the ACCEPT case (this
        guard's overwhelming majority outcome) must not pay for a wasted
        prefill it is about to immediately discard via the restore POST.
        Best-effort: returns None (never raises) on any connect/timeout/
        non-200/malformed-response failure, or if messages is falsy — callers
        treat None as fail-open, exactly the same contract as every other
        best-effort probe on this path."""
        if not messages:
            return None
        apply_payload: dict = {"messages": messages, "add_generation_prompt": False}
        for _k in _KV_PROBE_TOOL_KNOBS:
            _v = (client_meta or {}).get(_k)
            if _v is not None:
                apply_payload[_k] = _v
        base = f"http://127.0.0.1:{port}"
        try:
            async with httpx.AsyncClient(
                timeout=httpx.Timeout(connect=2.0, read=30.0, write=10.0, pool=1.0)
            ) as client:
                ar = await client.post(f"{base}/apply-template", json=apply_payload)
                ar.raise_for_status()
                rendered = (ar.json() or {}).get("prompt")
                if not isinstance(rendered, str) or not rendered:
                    return None
                tr = await client.post(f"{base}/tokenize", json={"content": rendered})
                tr.raise_for_status()
                tokens = (tr.json() or {}).get("tokens")
                if not isinstance(tokens, list):
                    return None
                return len(tokens)
        except Exception:
            log.debug("cold restore size guard: incoming-tokenize probe failed "
                      "(best-effort, fail-open)", exc_info=True)
            return None

    async def _restore_slot_kv(self, port: int, model_tag: str, slot=None) -> int | None:
        """engine_op scoped to the op (see
        _save_slot_kv) — set on entry, reset in the finally on every exit.

        Returns the winning bin's own saved token count
        (``saved_n``, the ``meta["prompt_tokens"]`` this restore attempted to
        land) when a restore was actually attempted, else ``None`` — for the
        caller to thread as ``verify_kv_restored``'s real ``expected_tokens``
        instead of a hardcoded ``None``.
        """
        if slot is not None:
            slot.engine_op = "kv_restore"
        try:
            return await self._restore_slot_kv_inner(port, model_tag, slot)
        finally:
            if slot is not None:
                slot.engine_op = "idle"

    async def _restore_slot_kv_inner(self, port: int, model_tag: str, slot=None) -> int | None:
        """KV restore using resolve_kv() chokepoint for decision + provenance."""
        if slot is None:
            return
        if '/' in model_tag or '\\' in model_tag or '..' in model_tag:
            log.warning("slot KV: refusing model_tag with unsafe path chars: %r", model_tag)
            return
        from turbohaul.subprocess_mgr import SLOT_SAVE_DIR, SLOT_PERSIST_DIR
        try:
            if not os.path.isdir(SLOT_SAVE_DIR):
                return
            # Incoming identity — SPEC-V2 WAVE A: (session_id, role[, fp8]) via
            # _bin_identity; flows into resolve_kv owner-match + the diag hash, so
            # the whole cold path keys on the session bin. Raw-tid fallback (no
            # session_id OR unlabeled role) = today's behavior byte-for-byte.
            inc_tid = _bin_identity(
                getattr(slot, "thread_id", ""),
                getattr(slot, "client_meta", None),
                getattr(slot, "admission_hash_chain", None))
            # Computed once, reused at every _emit_classifier_decision
            # call below (same value _log_kv_restore_diag already computes
            # per-site) so the KV_REUSE line can join a decision to a thread.
            _th_reuse = self._thread_hash(inc_tid or "")
            # Use admission-recorded context size (NOT slot.context at spawn)
            inc_len = getattr(slot, "admission_ctx_len", 0)
            # Classifier: admission-recorded incoming turn-hash chain — the prefix-validity
            # gate compares this against each bin's saved hash_chain. Absent (older
            # submit path / monolithic client) -> [] -> gate SKIPS (fail-safe).
            inc_chain = getattr(slot, "admission_hash_chain", []) or []
            # crit3: incoming turns (client_meta["messages"], 1:1 aligned
            # with inc_chain) for the tool-opaque tail guard before the POST below.
            # Absent -> [] -> guard inert (safe-degrade to today's restore).
            inc_messages = (getattr(slot, "client_meta", None) or {}).get("messages") or []
            # Divergence capture on the COLD-RESTORE path -- the first request
            # after a full unload is exactly where the open question
            # lives (a cold restore that clears when it shouldn't). The WARM
            # grace-window follow-up uses this facility too; same
            # chokepoint, same (thread_id, model_tag)-keyed rolling history, so
            # the comparison is continuous whichever path served the last turn.
            self._log_serve_divergence(slot, inc_chain, inc_messages, port)
            # Observability: same role-resolution shape the
            # warm path already uses for its own WARM_CLASSIFY role field —
            # admission stamp first, falling back to the label read.
            _cold_adm_role = getattr(slot, "admission_role", "__unset__")
            _cold_role = _norm_tip_role(
                _cold_adm_role if _cold_adm_role != "__unset__"
                else _bin_role(getattr(slot, "client_meta", None))
            )

            # Hydrate first: the cold path's own bin-
            # discovery below reads SLOT_SAVE_DIR (RAM/tmpfs) ONLY -- it never
            # calls the disk->RAM hydrate mechanism at all, on either of the
            # two hydrate functions, from this function or anywhere in its
            # call chain (by search: _scan_kvcache_if_stale, the only caller of
            # both hydrate functions, is invoked from exactly 3 sites, none
            # inside this function). _hydrate_ram_from_persist_for_key itself
            # works correctly (verified directly) --
            # without this call THIS path never reaches it. A container
            # restart empties the tmpfs RAM tier every time (SLOT_SAVE_DIR is
            # tmpfs by design); every complete, valid triplet already on the
            # SSD persist tier for THIS identity would otherwise be invisible to
            # every cold restore, unconditionally, which is exactly the
            # failure mode (resolved_from=restore-no-bins
            # despite valid persisted triplets). It is called with the SAME
            # (model_tag, thread_hash, port) key _find_clean_bin computes for
            # this exact identity elsewhere in this file, using the same
            # _bin_identity()->_thread_hash() derivation already computed
            # above as _th_reuse -- not a new identity scheme.
            self._hydrate_ram_from_persist_for_key(
                SLOT_SAVE_DIR, SLOT_PERSIST_DIR, (model_tag, _th_reuse, port))

            files = os.listdir(SLOT_SAVE_DIR)
            bins = [fn for fn in files if fn.startswith(f"{model_tag}.") and fn.endswith(".bin")]
            if not bins:
                # Classifier: no saved bin for this model at all -> a first-seen identity
                # (or a distinct sub-agent nonce) with no anchor yet. FRESH.
                self._emit_classifier_decision({
                    "event_type": "sub-agent", "action": "fresh",
                    "resolved_from": "restore-no-bins", "clean_bin_id": None,
                    "common_prefix_turns": 0, "incoming_turns": len(inc_chain),
                    "forced_clean_restore": False, "thread_hash": _th_reuse,
                    "restored_tokens": 0,
                    "slot_id": getattr(slot, "slot_id", None),
                })
                self._log_kv_restore_diag(
                    thread_hash=self._thread_hash(inc_tid or ""), model_tag=model_tag,
                    slot_id=getattr(slot, "slot_id", None), chosen="fresh",
                    resolved_from="restore-no-bins", clean_bin_present=False,
                    shadow_bin_present=False, common_prefix_turns=0,
                    incoming_turns=len(inc_chain), restore_bin=None)
                return

            # Classifier cold-path observability accumulators (see emit after the loop).
            owned_seen = False    # any bin for THIS identity (owner ok)
            diverged_seen = False  # any owned bin that was NOT a valid prefix
            restore = []
            for bin_fn in bins:
                inner = bin_fn[len(f"{model_tag}."):-4]
                dot = inner.find(".slot")
                if dot < 0:
                    continue
                f_th = inner[:dot]
                sid_str = inner[dot+5:]
                if not sid_str.isdigit():
                    continue
                sid = int(sid_str)
                # Meta file is always the bin file with .json extension (round-trip-safe)
                jpath = os.path.join(SLOT_SAVE_DIR, bin_fn[:-4] + ".json")
                meta = None
                if os.path.exists(jpath):
                    try:
                        with open(jpath) as f:
                            meta = json.load(f)
                    except Exception:
                        pass
                if meta is None:
                    continue
                # SPEC-V2 consistency stamp: reject a candidate whose bin bytes don't
                # match what the meta was stamped against (absent field => no check).
                _claim = meta.get("bin_bytes")
                if _claim is not None:
                    try:
                        if os.path.getsize(os.path.join(SLOT_SAVE_DIR, bin_fn)) != int(_claim):
                            continue
                    except (OSError, ValueError):
                        continue

                # R-COMP: a stale-marked sidecar (labeled is_compression
                # arrived for this session) is ABSENT — the next is_main turn
                # recomputes fresh instead of restoring the pre-compression copy
                # (even where it would still prefix-match).
                if meta.get("stale"):
                    continue
                # Owner validation: restore must validate against SAVED file's owner
                saved_tid = meta.get("thread_id", "")
                saved_tokens = meta.get("prompt_tokens", 0)
                saved_len = meta.get("prompt_len", 0)
                saved_chain = meta.get("hash_chain", [])
                saved_ph = meta.get("prompt_hash", "")
                saved_clean = bool(meta.get("clean_prefix", False))

                # Compute cache age for timing-gap guard
                try:
                    cache_age = time.time() - os.path.getmtime(os.path.join(SLOT_SAVE_DIR, bin_fn))
                except OSError:
                    cache_age = float("inf")

                # Policy decision (admission-size based, no hash gates)
                decision = resolve_kv("restore", {
                    "thread_id": inc_tid,
                    "model_tag": model_tag,
                    "slot_id": sid,
                    "port": port,
                }, {
                    "saved_tokens": saved_tokens,
                    "saved_len": saved_len,
                    "incoming_len": inc_len,
                    "cache_age_s": cache_age,
                    "saved_thread_id": saved_tid,
                    # Classifier: prefix-validity inputs (replaces the length compaction gate).
                    "saved_chain": saved_chain,
                    "incoming_chain": inc_chain,
                })
                log.info("slot KV restore decision: %s (saved_tid='%s')", decision, saved_tid)
                # Observability: resolve_kv()'s KVDecision is
                # an immutable 4-field dataclass (do_it/action/reason/
                # resolved_from, see kv_policy.py) -- its __repr__ (rendered
                # above by %s) does not carry saved_chain/incoming_chain, so a
                # DIVERGED refusal gives no way to tell a real early-turn
                # rewrite from a wrongly-refused pure append. Not fixed by
                # changing __repr__ (other call sites render KVDecision and
                # must not shift under them) -- emitted here instead, where
                # the chains are still local variables, one line per
                # candidate bin evaluated. divergence_index is a distinct,
                # separately-named field: this loop's own common_prefix_turns
                # equivalent does not exist here (the field of that name used
                # elsewhere on this cold-restore path is a hardcoded 0 on the
                # no-bins/no-valid-restore exit sites, computed nowhere near
                # this loop -- reusing it would silently inherit that
                # ambiguity into a real number).
                log.info(
                    "WARM_CLASSIFY saved_chain_fp=%s inc_chain_fp=%s "
                    "divergence_index=%s saved_len=%s incoming_len=%s "
                    "shape_verdict=%s role=%s resolved_from=%s",
                    _chain_fp(saved_chain), _chain_fp(inc_chain),
                    _chain_divergence_index(saved_chain, inc_chain),
                    saved_len, inc_len,
                    "restore" if decision.do_it else "skip",
                    _cold_role, decision.resolved_from,
                )
                # Classifier: bucket this bin's outcome for the cold-path event emit.
                rf = decision.resolved_from
                if rf != "restore-owner-mismatch":
                    owned_seen = True
                if rf in ("restore-diverged-fresh", "restore-physics-belt-saved-longer"):
                    diverged_seen = True
                if decision.do_it:
                    restore.append((sid, bin_fn, saved_tokens, saved_clean, saved_chain))
            if not restore:
                # Classifier: bins existed but none is a valid prefix. If an owned bin
                # diverged -> COMPRESSION (harness rewrote an early turn). Else the
                # bins belong to other identities -> SUB-AGENT (own-anchor, no cross-
                # restore). Either way: FRESH.
                if diverged_seen:
                    et, rf = "compression", "restore-diverged-fresh"
                elif owned_seen:
                    et, rf = "compression", "restore-guard-skip"
                else:
                    et, rf = "sub-agent", "restore-no-anchor-for-identity"
                self._emit_classifier_decision({
                    "event_type": et, "action": "fresh", "resolved_from": rf,
                    "clean_bin_id": None, "common_prefix_turns": 0,
                    "incoming_turns": len(inc_chain), "forced_clean_restore": False,
                    "thread_hash": _th_reuse, "restored_tokens": 0,
                    "slot_id": getattr(slot, "slot_id", None),
                })
                # _find_shadow_bin is documented never-raises (FS/JSON errors -> None);
                # already inside this method's outer best-effort try.
                _sh_present = self._find_shadow_bin(port, model_tag, inc_tid) is not None
                self._log_kv_restore_diag(
                    thread_hash=self._thread_hash(inc_tid or ""), model_tag=model_tag,
                    slot_id=getattr(slot, "slot_id", None), chosen="fresh",
                    resolved_from=rf, clean_bin_present=owned_seen,
                    shadow_bin_present=_sh_present, common_prefix_turns=0,
                    incoming_turns=len(inc_chain), restore_bin=None)
                return
            # Restore ONLY the single best bin.
            # Restoring multiple mismatched bins under one identity produced +27038 stale -> CLEAR.
            # Option A: PREFER a clean_prefix bin (no generated <think> tail) over a
            # possibly-larger polluted one — a leftover polluted bin would otherwise win on token
            # count and re-introduce the stale>n_rs_seq CLEAR. Tie-break by largest token count.
            restore.sort(key=lambda r: (r[3], r[2]), reverse=True)
            sid, bin_fn, saved_n, _clean, win_chain = restore[0]
            # --- P2 (DURABLE MANAGER B): ring-aware COLD restore (flag-gated) ---
            # When TURBOHAUL_DURABLE_RING=ON, select the newest matching (role,session) ring bin
            # that is a VALID PREFIX of inc_chain (same gate as default path), via _select_ring_bin.
            # Cold/swap-back family ONLY. Default-OFF = byte-identical.
            # Option A: OVERRIDE the default-selection winner BEFORE the cold-path preference so the ring bin
            # flows through the whole pipeline. Keep default sid (target slot for POST); only override
            # bin_fn, saved_n, _clean, win_chain from ring. Shadow-preference block then operates on
            # the ring's chain (ring vs shadow precedence: shadow of ring bin still wins for strict-extension).
            if _durable_ring_enabled() and slot is not None:
                try:
                    ring_key = _durable_ring_key(getattr(slot, "client_meta", None))
                    ring = self._durable_ring_index.get(ring_key, []) if ring_key else []
                    if ring_key and ring:
                        # Select ring entry that matches model_tag + non-empty chain + valid PREFIX of inc_chain
                        ring_entry = _select_ring_bin(ring, inc_chain, model_tag)
                        if ring_entry:
                            ring_bin_fn = ring_entry.get("bin_fn")
                            ring_meta_fn = ring_entry.get("meta_fn")
                            ring_clean = bool(ring_entry.get("clean_prefix", False))
                            ring_chain = ring_entry.get("hash_chain", [])
                            # Use saved_tokens for token count consistency with default path (prompt_len is turn count)
                            ring_saved_n = ring_entry.get("saved_tokens", ring_entry.get("prompt_len", 0))
                            # Validate ring bin exists on disk and matches this model_tag
                            from turbohaul.subprocess_mgr import SLOT_SAVE_DIR
                            ring_bin_path = os.path.join(SLOT_SAVE_DIR, ring_bin_fn) if ring_bin_fn else None
                            ring_meta_path = os.path.join(SLOT_SAVE_DIR, ring_meta_fn) if ring_meta_fn else None
                            if (ring_bin_path and ring_meta_path and
                                os.path.exists(ring_bin_path) and os.path.exists(ring_meta_path)):
                                # OVERRIDE the default-selection winner (keep default sid = target slot for POST)
                                bin_fn = ring_bin_fn
                                saved_n = ring_saved_n
                                _clean = ring_clean
                                win_chain = ring_chain
                                log.info("DURABLE_RING cold restore: ring bin overrides default key=%s bin=%s clean=%s turns=%d",
                                         ring_key, ring_bin_fn, ring_clean, len(ring_chain))
                        else:
                            log.info("DURABLE_RING cold restore: no ring entry passes prefix gate for key=%s -> keep default",
                                     ring_key)
                except Exception:
                    log.debug("DURABLE_RING cold restore ring lookup failed (best-effort); using default selection", exc_info=True)
            # --- COLD-path SHADOW restore-preference -------
            # The clean/normal selection ABOVE is UNCHANGED and alone decides the winning
            # clean anchor (sid/bin_fn/win_chain). Here we ONLY upgrade the restore TARGET
            # on the COLD (wave-return / swap-back) path: prefer the byte-matching think-
            # free `.shadow` bin over the winning clean anchor IFF it passes the SAME
            # prefix-validity bar the clean path uses (_is_prefix_match vs inc_chain).
            # COLD-FRESHNESS (Option A, PL-greenlit): NO length/no-downgrade condition
            # on cold — a valid-prefix think-free shadow that is SHORTER than the clean
            # STILL WINS (rationale at the gate below). A valid prefix => the next
            # decode STRICT-EXTENDS the think-free state (skips reprefilling the <think>
            # tail), reprefilling ONLY the appended/missing tail.
            #
            # DISTINCT GATE (_shadow_cold_restore_enabled == TURBOHAUL_SHADOW_COLD_RESTORE,
            # default ON when SHADOW_REPREFILL=1) — NOT the WARM _shadow_restore_prefer_
            # enabled() (held 0): the warm seam wants native reuse, the cold swap-back has
            # NO warm KV so it wants the shadow. The `.shadow` bin is found via
            # _find_shadow_bin (its OWN `.shadow.json` matcher) so the numeric-sid
            # `.isdigit()` parse for normal bins above is UNTOUCHED — the `.shadow` bypass
            # is scoped to the shadow-marker lookup only (constraint #3).
            #
            # UPGRADE-ONLY / never worse than today (constraint #2): a missing / non-
            # prefix / stale shadow -> keep EXACTLY the clean anchor chosen above (a
            # SHORTER valid shadow is now PREFERRED on cold, see freshness rationale).
            # And the engine's get_common_prefix stays the FINAL authority on the
            # next decode — even a wrongly-preferred shadow only makes the engine reprefill
            # the divergent tail (a REPREFILL, never a wrong answer), identical safety to
            # the clean restore.
            #
            # ENGINE-LIMIT CAVEAT (honest — NOT a fix miss): restoring the think-free
            # [1..N] shadow lets the MAIN history reuse, but the qwen MTP recurrent ctx
            # (n_rs_seq=2) can only rewind so far — if the appended sub-result TAIL exceeds
            # n_rs_seq=2 the engine CLEARs regardless, and swap-back prompt_eval == full
            # context. That is the recurrent-rewind LIMIT (the operator's "only the extra sub-
            # context slow-loads" boundary), not this hunk failing. SUCCESS = engine log
            # "strict extension", prompt_eval == sub-result TAIL tokens; recurrent-limit =
            # engine log "CLEAR"/do_reset, full prefill. The manager restores the RIGHT
            # bin; the rewind depth is the engine's.
            r_bin, r_sid, r_chain, r_kind = bin_fn, sid, win_chain, "clean"
            # --- crit3: COLD-path TOOL-tail restore SKIP (Option A) ------
            # GUARD FIRST — BEFORE the shadow-preference below — against the winning
            # CLEAN anchor's common depth (win_chain: the deterministic think-free
            # prefix; same `common` semantics as the warm seam). _prefix_hash_chain is
            # BLIND to tool turns (assistant tool_calls / role=="tool" / null content),
            # so if the divergent tail beyond that common prefix is tool-opaque, the
            # harness re-serializes that region nondeterministically -> restoring ANY
            # bin here (the clean anchor OR the cold-wire shadow below — its tool turns
            # are EQUALLY hash-invisible, constraint #3) would POST token-stale KV ->
            # engine stale>n_rs_seq CLEAR -> full reprefill. SKIP the whole restore ->
            # the re-spawned slot stays un-restored -> fresh prefill / engine native
            # checkpoint (safe-degrade). Returning here gates BOTH POSTs. A TEXT/think
            # tail (no tool turn beyond common) falls THROUGH to the freshness gate and
            # still restores, so crit2's cold shadow reuse stays intact. Flag-gated
            # (default ON). Gating on win_chain (not the post-preference target) makes
            # the skip decision independent of which bin the freshness gate picks.
            if _tooltail_restore_skip_enabled():
                _common_tt = 0
                for a, b in zip(win_chain or [], inc_chain, strict=False):
                    if a != b:
                        break
                    _common_tt += 1
                if _divergent_tail_is_tool_opaque(
                        inc_messages, _common_tt,
                        scan_covered=_tooltail_scan_covered_enabled()):
                    self._kv_tooltail_skip_counts["cold"] = (
                        self._kv_tooltail_skip_counts.get("cold", 0) + 1)
                    log.info(
                        "crit3 cold TOOL-tail restore SKIP: divergent tail "
                        "beyond common=%d is tool-opaque -> NOT restoring %s; safe-"
                        "degrade to fresh prefill (thread=%s, incoming_turns=%d)",
                        _common_tt, bin_fn, (inc_tid or "")[:12], len(inc_chain),
                    )
                    self._emit_classifier_decision({
                        "event_type": "guard-skip", "action": "fresh",
                        "resolved_from": "cold-tooltail-skip", "clean_bin_id": bin_fn,
                        "common_prefix_turns": _common_tt,
                        "incoming_turns": len(inc_chain),
                        "forced_clean_restore": False, "thread_hash": _th_reuse,
                        "restored_tokens": 0,
                        "slot_id": getattr(slot, "slot_id", None),
                    })
                    _sh_present_tt = (
                        self._find_shadow_bin(port, model_tag, inc_tid) is not None)
                    self._log_kv_restore_diag(
                        thread_hash=self._thread_hash(inc_tid or ""),
                        model_tag=model_tag, slot_id=getattr(slot, "slot_id", None),
                        chosen="fresh", resolved_from="cold-tooltail-skip",
                        clean_bin_present=True, shadow_bin_present=_sh_present_tt,
                        common_prefix_turns=_common_tt,
                        incoming_turns=len(inc_chain), restore_bin=bin_fn,
                        saved_chain=r_chain, incoming_chain=inc_chain)
                    return
            # --- COLD-FRESHNESS (Option A; distinct from crit3
            # above — this is the crit2 ROOT). On a NON-tool tail, prefer a valid-PREFIX
            # think-free `.shadow` over the winning clean anchor REGARDLESS OF LENGTH: a
            # SHORTER valid shadow STILL WINS on cold. Its missing tail just reprefills
            # (small, bounded seq_rm), whereas the with-<think> clean coin-flips a FULL
            # ~81k CLEAR (the generated <think> tail > n_rs_seq=2). Think-free-
            # correctness beats raw length on cold. The `>= len(clean)` no-downgrade was
            # a WARM-path heuristic (prefer the longer valid bin when a warm KV already
            # holds a continuation) mis-applied to cold — the cold swap-back has NO warm
            # KV, so freshness is what matters, not length. KEPT: _is_prefix_match
            # (valid-prefix ONLY), the owner/model/port scoping via _find_shadow_bin,
            # clean-fallback when there is NO valid-prefix shadow, and the engine
            # get_common_prefix backstop (FINAL authority — a wrongly-preferred shadow
            # only costs a reprefill, never a wrong answer). The WARM path's no-
            # downgrade (_maybe_force_clean_restore) is UNTOUCHED.
            if _shadow_cold_restore_enabled():
                try:
                    _sh = self._find_shadow_bin(port, model_tag, inc_tid)
                    # Drop the length no-downgrade ONLY when the winning anchor is a
                    # WITH-<think> (polluted) bin (_clean == False) -> any valid-prefix shadow beats
                    # its think-tail coin-flip regardless of length. If the anchor is a THINK-FREE
                    # clean_prefix bin (_clean == True) that is LONGER, KEEP the length-guard: the
                    # longer clean strict-extends, whereas a shorter shadow would reprefill the gap
                    # for nothing (latency regression). So: prefer shadow iff valid-prefix AND
                    # (anchor is polluted OR shadow is not shorter than the clean).
                    if (_sh is not None and _is_prefix_match(_sh[1], inc_chain)
                            and (not _clean or len(_sh[1]) >= len(win_chain or []))):
                        r_bin, r_chain, r_sid, r_kind = _sh[0], _sh[1], _sh[2], "shadow"
                        self._kv_shadow_restore_counts["cold_preferred"] = (
                            self._kv_shadow_restore_counts.get("cold_preferred", 0) + 1)
                    else:
                        self._kv_shadow_restore_counts["cold_clean_fallback"] = (
                            self._kv_shadow_restore_counts.get("cold_clean_fallback", 0) + 1)
                        if _sh is not None:
                            log.info(
                                "cold shadow restore-preference: shadow present but NOT "
                                "a valid prefix (shadow_turns=%d, clean_turns=%d) -> "
                                "clean anchor for thread=%s",
                                len(_sh[1]), len(win_chain or []), (inc_tid or "")[:12])
                except Exception:
                    log.debug("cold shadow restore-preference lookup failed (best-effort); "
                              "using clean anchor", exc_info=True)
            # --- COLD-path
            # SIZE decline. Gated AFTER the shadow-preference block above so it
            # evaluates the FINAL chosen bin (r_bin/r_kind), not the pre-
            # preference clean anchor. See _classify_cold_restore_size and
            # _cold_restore_size_guard_enabled for the full written rationale,
            # including why a WITH-THINK (polluted) bin is deliberately OUT OF
            # SCOPE (avoid a check that fires on the ordinary
            # healthy case, not the rare bad one). Fails OPEN on any unknown —
            # a declined-by-mistake cold restore is a full reprefill, the exact
            # cost this guard exists to remove.
            if _cold_restore_size_guard_enabled():
                _cr_bin_tokens = (
                    saved_n if r_kind == "clean"
                    else self._cold_restore_bin_token_count(r_bin))
                _cr_inc_tokens = await self._cold_restore_incoming_token_count(
                    port, inc_messages, getattr(slot, "client_meta", None))
                if _cr_inc_tokens is None:
                    # The live tokenize probe fails OPEN (None) —
                    # the hole that let a post-generation bin through this
                    # guard (the restore verified byte-perfect and the engine
                    # still reused nothing). Fall back to the engine's own
                    # recorded think-free render count for this port — the
                    # same evidence the save side caps with — so the guard
                    # can still see a bin that overshoots the render the
                    # client will actually resend. Decline only when a
                    # concrete number exists; with neither source known we
                    # still fail open, exactly as before.
                    _cr_rec = self._clean_prefill_tokens.get(port)
                    if _cr_rec:
                        _cr_inc_tokens = _cr_rec.count  # the register holds CleanPrefillEvidence
                _cr_proceed, _cr_case = _classify_cold_restore_size(
                    r_kind, _clean, _cr_bin_tokens, _cr_inc_tokens,
                    _COLD_RESTORE_SIZE_MARGIN_TOKENS)
                if not _cr_proceed:
                    log.warning(
                        "cold-restore SIZE DECLINE (%s): candidate %s "
                        "(kind=%s) has %s tokens, incoming request renders to "
                        "only %s (margin=%d) -- bin cannot be covered by what's "
                        "being asked for; declining rather than restore-then-"
                        "CLEAR; thread=%s",
                        _cr_case, r_bin, r_kind, _cr_bin_tokens, _cr_inc_tokens,
                        _COLD_RESTORE_SIZE_MARGIN_TOKENS, (inc_tid or "")[:12],
                    )
                    self._kv_cold_size_decline_count = (
                        getattr(self, "_kv_cold_size_decline_count", 0) + 1)
                    self._emit_classifier_decision({
                        "event_type": "guard-skip", "action": "fresh",
                        "resolved_from": "cold-size-decline", "clean_bin_id": r_bin,
                        "common_prefix_turns": 0, "incoming_turns": len(inc_chain),
                        "forced_clean_restore": False, "thread_hash": _th_reuse,
                        "restored_tokens": 0,
                        "slot_id": getattr(slot, "slot_id", None),
                    })
                    _sh_present_sz = (
                        self._find_shadow_bin(port, model_tag, inc_tid) is not None)
                    self._log_kv_restore_diag(
                        thread_hash=self._thread_hash(inc_tid or ""),
                        model_tag=model_tag, slot_id=getattr(slot, "slot_id", None),
                        chosen="fresh", resolved_from="cold-size-decline",
                        clean_bin_present=True, shadow_bin_present=_sh_present_sz,
                        common_prefix_turns=0, incoming_turns=len(inc_chain),
                        restore_bin=r_bin,
                        saved_chain=r_chain, incoming_chain=inc_chain)
                    return
            # --- COLD-path
            # TOOLS-FINGERPRINT decline. Gated AFTER the shadow-preference AND
            # size-guard blocks above, same ordering rationale the size guard
            # documents: evaluate the FINAL chosen bin (r_bin/r_kind), not an
            # earlier candidate the shadow-preference block may have replaced.
            # See _cold_restore_tools_fingerprint_guard_enabled for the full
            # written rationale (why this and not a kv_policy.py hash change).
            # Fails OPEN when the bin has no recorded fingerprint (an old,
            # pre-fingerprint bin, or a genuinely toolless save — .get()
            # cannot and need not distinguish the two, both must proceed) and
            # when it matches (a thread whose tools never changed pays
            # nothing, old bin or new). Declines only a POSITIVELY RECORDED
            # mismatch: kv_policy.py's chain hash cannot see this divergence
            # by design, so this is the one place it gets caught.
            # NOTE: shadow bins never carry this field (_save_shadow_slot_kv
            # does not receive client_meta/tools) — a shadow-preferred
            # candidate always fails open here, unchanged from prior
            # behavior for that sub-path; out of scope here.
            if _cold_restore_tools_fingerprint_guard_enabled():
                _tf_bin = self._cold_restore_bin_tools_fingerprint(r_bin)
                _tf_inc = _tools_fingerprint(
                    (getattr(slot, "client_meta", None) or {}).get("tools"))
                _tf_proceed, _tf_case = _classify_tools_fingerprint_restore_guard(
                    _tf_bin, _tf_inc)
                if not _tf_proceed:
                    log.warning(
                        "cold-restore TOOLS FINGERPRINT DECLINE (%s): "
                        "candidate %s (kind=%s) was saved with tools_fingerprint="
                        "%s, incoming request currently renders tools to %s -- "
                        "the chain hash cannot see this divergence, "
                        "declining rather than restore-onto-an-already-diverged "
                        "prompt; thread=%s",
                        _tf_case, r_bin, r_kind, (_tf_bin or "none")[:12],
                        (_tf_inc or "none")[:12], (inc_tid or "")[:12],
                    )
                    self._kv_cold_tools_fp_decline_count = (
                        getattr(self, "_kv_cold_tools_fp_decline_count", 0) + 1)
                    self._emit_classifier_decision({
                        "event_type": "guard-skip", "action": "fresh",
                        "resolved_from": "cold-tools-fingerprint-decline",
                        "clean_bin_id": r_bin,
                        "common_prefix_turns": 0, "incoming_turns": len(inc_chain),
                        "forced_clean_restore": False, "thread_hash": _th_reuse,
                        "restored_tokens": 0,
                        "slot_id": getattr(slot, "slot_id", None),
                    })
                    _sh_present_tf = (
                        self._find_shadow_bin(port, model_tag, inc_tid) is not None)
                    self._log_kv_restore_diag(
                        thread_hash=self._thread_hash(inc_tid or ""),
                        model_tag=model_tag, slot_id=getattr(slot, "slot_id", None),
                        chosen="fresh", resolved_from="cold-tools-fingerprint-decline",
                        clean_bin_present=True, shadow_bin_present=_sh_present_tf,
                        common_prefix_turns=0, incoming_turns=len(inc_chain),
                        restore_bin=r_bin,
                        saved_chain=r_chain, incoming_chain=inc_chain)
                    return
            # F5: status-check the restore POST so the metric is truthful — a 500'd
            # restore leaves the slot un-restored (fresh prefill), NOT a continuation.
            # Caught locally so the truthful (failed) decision still emits below.
            #
            # Clear any stale actual-token-count left over from a
            # PRIOR restore on this same port BEFORE attempting this one -- so a
            # failed POST below leaves nothing for a caller to (wrongly) read back,
            # rather than silently reusing an older successful value.
            _actual_tokens_cleared = dict(getattr(self, "_kv_restore_actual_tokens", {}) or {})
            _actual_tokens_cleared.pop(port, None)
            self._kv_restore_actual_tokens = _actual_tokens_cleared
            restore_ok = False
            try:
                async with httpx.AsyncClient(timeout=httpx.Timeout(connect=2.0, read=120.0, write=10.0, pool=1.0)) as client:
                    resp = await client.post(f"http://127.0.0.1:{port}/slots/{r_sid}?action=restore", json={"filename": r_bin})
                    resp.raise_for_status()
                restore_ok = True
                # The engine's own action=restore response already
                # carries the REAL restored count under "n_restored"
                # (server-task.cpp's server_task_result_slot_save_load::to_json(),
                # set from llama_state_seq_load_file's own output param -- confirmed
                # by reading the engine source, not assumed) -- synchronously, in
                # THIS response, with no separate read and no race window. Capturing
                # it here lets every caller pass it straight to verify_kv_restored's
                # existing actual_n_past override instead of racing a follow-up
                # GET /slots against the engine's own async KV-state settling (the
                # documented cause of a stale read: n_prompt_tokens read back as None
                # in exactly this window). Best-effort: a response that doesn't
                # parse or doesn't carry the field just leaves nothing to read,
                # falling through to today's GET-based verification unchanged.
                try:
                    _n_restored = resp.json().get("n_restored")
                except Exception:
                    _n_restored = None
                if isinstance(_n_restored, int):
                    _actual_tokens_updated = dict(getattr(self, "_kv_restore_actual_tokens", {}) or {})
                    _actual_tokens_updated[port] = _n_restored
                    self._kv_restore_actual_tokens = _actual_tokens_updated
                # B3: truthful — this is the restore POST; actual reuse is decided by the engine's
                # get_common_prefix on next decode (engine logs "strict extension" reuse vs "CLEAR").
                log.info("slot KV restore POSTed: %s (kind=%s, saved ~%d tokens; engine determines actual n_past)", r_bin, r_kind, saved_n)
                # 3-strikes policy: remember which bin this
                # port last restored so a subsequent dead-holder detection can
                # attribute the death and auto-quarantine a repeat offender.
                try:
                    if not hasattr(self, "_last_restored_bin"):
                        self._last_restored_bin = {}
                        self._bin_death_strikes = {}
                    self._last_restored_bin[port] = r_bin
                except Exception:
                    pass
                # P1 (DURABLE MANAGER B): residency tag update + would-be reload log at cold restore.
                if _durable_ring_enabled() and slot is not None:
                    try:
                        ring_key = _durable_ring_key(getattr(slot, "client_meta", None))
                        # multi-instance: attributes to instance-0; resident_state_tag is INERT observe-only
                        resident = self._residents.get(model_tag)
                        if ring_key and resident:
                            old_tag = resident.resident_state_tag
                            resident.resident_state_tag = ring_key
                            # Would-reload check (logs if we WOULD reload when resident_tag != request_tag)
                            # Fires ONLY when old_tag is SET and differs (skip None) — consistent with warm sites
                            if old_tag and old_tag != ring_key:
                                self._durable_ring_counts["would_reload"] = self._durable_ring_counts.get("would_reload", 0) + 1
                                log.info("DURABLE_RING would_reload (site=cold): key=%s resident_old_tag=%s new_tag=%s ring_len=%d",
                                         ring_key, old_tag, ring_key, len(self._durable_ring_index.get(ring_key, [])))
                    except Exception:
                        log.debug("DURABLE_RING residency tag update best-effort failed (site=cold)", exc_info=True)
            except Exception:
                log.warning("slot KV restore POST failed: %s (engine_slot=%d)", r_bin, r_sid, exc_info=True)
            # Classifier: a cold/swap-back restore that extends a saved prefix = a
            # CONTINUATION reuse (the incoming extends persisted context). warm_chain
            # is unknown on a fresh spawn, so classify vs the RESTORED bin's chain.
            _common = 0
            for a, b in zip(r_chain or [], inc_chain, strict=False):
                if a != b:
                    break
                _common += 1
            # Wave-return IS the cold path. When the restore POST landed
            # and the restored bin is think-free (the clean_prefix anchor OR a `.shadow`
            # bin), this cold restore = a wave-return. Tag it distinctly + bump the cold
            # counter. event_type stays "continuation" so the events dict + forced counter
            # are UNCHANGED (no double-count: _emit_classifier_decision counts by
            # event_type / forced_clean_restore, never by resolved_from). shadow vs clean
            # are MUTUALLY EXCLUSIVE (one restored bin) so wave_return bumps exactly once.
            # Separate/additional to forced (WARM-only).
            _cold_shadow = bool(restore_ok and r_kind == "shadow")
            _cold_clean = bool(restore_ok and _clean and not _cold_shadow)
            if _cold_shadow or _cold_clean:
                self._kv_classifier_wave_return += 1
            _resolved_from = ("wave-return-shadow-restore" if _cold_shadow
                              else ("wave-return-clean-restore" if _cold_clean
                                    else ("restore-prefix-valid" if restore_ok
                                          else "restore-post-failed")))
            self._emit_classifier_decision({
                "event_type": "continuation" if restore_ok else "guard-skip",
                "action": "restore" if restore_ok else "fresh",
                "resolved_from": _resolved_from,
                "clean_bin_id": r_bin,
                "common_prefix_turns": _common, "incoming_turns": len(inc_chain),
                "forced_clean_restore": False, "thread_hash": _th_reuse,
                # saved_n is the bin's own recorded n_prompt_tokens (a real
                # engine-reported token count from save time) -- the one
                # site in this whole restore path where an actual TOKEN
                # count (not a char-length proxy) is cheaply available.
                "restored_tokens": saved_n if restore_ok else 0,
                "slot_id": getattr(slot, "slot_id", None),
            })
            # shadow-diag: name the cold-restore choice (candidate c/d) +
            # correlate to KV pressure. chosen distinguishes a think-free shadow, a
            # think-free clean anchor, a with-<think> clean bin, or fresh (post-fail).
            if not restore_ok:
                _chosen = "fresh"
            elif r_kind == "shadow":
                _chosen = "chose_shadow"
            elif _clean:
                _chosen = "chose_clean"
            else:
                _chosen = "chose_clean_withthink"
            # _find_shadow_bin is documented never-raises; inside the outer best-effort try.
            _shadow_present = self._find_shadow_bin(port, model_tag, inc_tid) is not None
            self._log_kv_restore_diag(
                thread_hash=self._thread_hash(inc_tid or ""), model_tag=model_tag,
                slot_id=getattr(slot, "slot_id", None), chosen=_chosen,
                resolved_from=_resolved_from, clean_bin_present=bool(_clean),
                shadow_bin_present=_shadow_present, common_prefix_turns=_common,
                incoming_turns=len(inc_chain), restore_bin=r_bin,
                saved_chain=r_chain, incoming_chain=inc_chain)
            # PL KEY REFINEMENT: when a `.shadow` bin is in play, byte-compare the
            # manager's reconstructed think-free render vs the harness resend region
            # so candidate (d) saved-but-DIVERGES is observable vs (c) wrong-bin.
            if _shadow_present:
                self._log_shadow_byteparity(
                    thread_id=inc_tid, thread_hash=self._thread_hash(inc_tid or ""),
                    model_tag=model_tag, inc_messages=inc_messages)
            # The winning bin's OWN saved token count (saved_n),
            # for the caller to thread into verify_kv_restored as a real
            # expected_tokens — but ONLY when a restore was actually attempted
            # against it (restore_ok False means the POST failed, so saved_n is
            # still what we EXPECTED, not what landed; None means no bin was ever
            # chosen and there is nothing to expect).
            return saved_n
        except Exception:
            log.debug("slot KV restore best-effort failed for %s", model_tag, exc_info=True)
            return None

    async def _reload_matching_state_before_serve(
        self, port: int, model_tag: str, slot, inc_chain: list, inc_messages: list | None = None
    ) -> tuple[bool, tuple[str, str] | None]:
        """P3 (DURABLE MANAGER B): reload-before-serve on the WARM path.
        
        When TURBOHAUL_DURABLE_RING=ON, BEFORE serving a WARM follow-up, if the
        physically-resident (role,session) does NOT match the incoming request's
        (role,session), RELOAD the matching ring state so the engine residency
        matches the request head — THEN proceed with the existing warm path.
        
        CRITICAL: Only fires on RESIDENCY-TAG MISMATCH (old_tag is SET and != ring_key).
        If old_tag == ring_key (resident already matches), do NOTHING (let existing
        warm path run untouched). If old_tag is None (unknown resident), skip - safe default to avoid
        spurious CLEAR).
        
        Returns (reloaded: bool, ring_key: tuple[str,str] | None).
        Caller MUST advance resident_state_tag to ring_key after this call if ring_key is set.
        """
        if not _durable_ring_enabled():
            return (False, None)
        try:
            ring_key = _durable_ring_key(getattr(slot, "client_meta", None))
            # multi-instance: attributes to instance-0; resident_state_tag is INERT observe-only
            resident = self._residents.get(model_tag)
            old_tag = getattr(resident, "resident_state_tag", None) if resident else None
            
            # ONLY fire on explicit mismatch (old_tag SET and != ring_key)
            # old_tag is None -> skip (unknown resident; safe default avoids spurious CLEAR)
            if not ring_key or not old_tag or old_tag == ring_key:
                return (False, ring_key)
            
            ring = self._durable_ring_index.get(ring_key, [])
            if not ring:
                return (False, ring_key)
            
            # Select ring entry that matches model_tag + non-empty chain + valid PREFIX of inc_chain
            ring_entry = _select_ring_bin(ring, inc_chain, model_tag)
            if not ring_entry:
                log.debug("DURABLE_RING warm reload: no ring entry passes prefix gate for key=%s", ring_key)
                return (False, ring_key)
            
            ring_bin_fn = ring_entry.get("bin_fn")
            ring_meta_fn = ring_entry.get("meta_fn")
            ring_chain = ring_entry.get("hash_chain", [])
            ring_clean = bool(ring_entry.get("clean_prefix", False))
            
            # Validate ring bin exists on disk
            from turbohaul.subprocess_mgr import SLOT_SAVE_DIR
            ring_bin_path = os.path.join(SLOT_SAVE_DIR, ring_bin_fn) if ring_bin_fn else None
            ring_meta_path = os.path.join(SLOT_SAVE_DIR, ring_meta_fn) if ring_meta_fn else None
            if not (ring_bin_path and ring_meta_path and os.path.exists(ring_bin_path) and os.path.exists(ring_meta_path)):
                log.debug("DURABLE_RING warm reload: ring bin/meta not found on disk for key=%s", ring_key)
                return (False, ring_key)
            
            # TOOL-OPAQUE-TAIL GUARD (mirrors COLD path): if divergent tail is tool-opaque,
            # skip reload to avoid engine CLEAR (hash validates prefix but byte-diverges on tool turns)
            if inc_messages is not None:
                from turbohaul.kv_classify import _is_prefix_match
                # Find common prefix length between ring_chain and inc_chain
                common = 0
                for a, b in zip(ring_chain, inc_chain, strict=False):
                    if a != b:
                        break
                    common += 1
                if common < len(ring_chain):
                    # There IS a divergent tail beyond common prefix
                    from turbohaul.kv_classify import _divergent_tail_is_tool_opaque
                    if _divergent_tail_is_tool_opaque(inc_messages, common):
                        log.info("DURABLE_RING warm reload: tool-opaque tail beyond common=%d -> SKIP reload for key=%s", common, ring_key)
                        return (False, ring_key)
            
            # Perform the restore POST (same mechanism as cold path)
            try:
                async with httpx.AsyncClient(timeout=httpx.Timeout(connect=2.0, read=120.0, write=10.0, pool=1.0)) as client:
                    # Use slot_id from slot (target slot for POST)
                    sid = getattr(slot, "slot_id", None)
                    if sid is None:
                        return (False, ring_key)
                    resp = await client.post(
                        f"http://127.0.0.1:{port}/slots/{sid}?action=restore",
                        json={"filename": ring_bin_fn}
                    )
                    resp.raise_for_status()
                
                # Update residency tag (caller will also advance after this returns)
                resident.resident_state_tag = ring_key
                log.info("DURABLE_RING warm reload: key=%s bin=%s clean=%s turns=%d -> resident updated",
                         ring_key, ring_bin_fn, ring_clean, len(ring_chain))
                return (True, ring_key)
                
            except Exception:
                log.debug("DURABLE_RING warm reload: restore POST failed for key=%s", ring_key, exc_info=True)
                return (False, ring_key)
                
        except Exception:
            log.debug("DURABLE_RING warm reload best-effort failed", exc_info=True)
            return (False, None)

    def _live_protected_thread_hashes(self) -> set[str]:
        """thread_hash set whose KV ``.bin`` + sidecar MUST NOT be GC-evicted:
        the active slot, every in-flight slot, the idle-held thread, and every
        resident's idle thread (grep ``_active_slot`` / ``_idle_thread_id``).

        Resolves cap-awarely. At cap>=2, self._active_slot and
        self._inflight are PERMANENTLY unwritten (only written inside
        _process_slot / _fan_out_and_drain, which are never reached again
        after the cap fork at worker_loop). The live per-resident
        active_slot / inflight are maintained by _drive_resident /
        _serve_on_resident.

        Protecting the whole live thread (not just its clean anchor) covers the
        constraint "never evict a clean_prefix bin belonging to a live thread"
        AND its non-clean bins. The set is transient — a thread drops out once it
        goes idle/dead, so this cannot leak unboundedly. Best-effort: never
        raises; an empty/unknown thread_id is skipped (``nothread`` is never
        protected, so it cannot silently defeat the ceiling).
        """
        hashes: set[str] = set()
        try:
            def _add(tid: str | None, cm: dict | None = None, chain: list | None = None) -> None:
                # SPEC-V2 WAVE A: protect BOTH the (session,role) identity hash and
                # the raw thread_id hash (legacy bins during the one-time migration).
                if tid:
                    hashes.add(self._thread_hash(tid))
                ident = _bin_identity(tid or "", cm, chain)
                if ident and ident != (tid or ""):
                    hashes.add(self._thread_hash(ident))
            # Resolve cap-awarely (template: _resolve_top_level_active_slot).
            # At cap>=2, self._active_slot is PERMANENTLY unwritten. Scan the
            # per-resident active_slot / inflight that _drive_resident maintains.
            residents = self._model_residents()
            if residents:
                for r in residents:
                    active = r.active_slot
                    _add(getattr(active, "thread_id", None) if active is not None else None,
                         getattr(active, "client_meta", None) if active is not None else None,
                         getattr(active, "admission_hash_chain", None) if active is not None else None)
                    for s in list(r.inflight):
                        _add(getattr(s, "thread_id", None), getattr(s, "client_meta", None),
                             getattr(s, "admission_hash_chain", None))
            else:
                # cap<=1: legacy singleton (byte-identical to the earlier cap-unaware behaviour)
                active = self._active_slot
                _add(getattr(active, "thread_id", None) if active is not None else None,
                     getattr(active, "client_meta", None) if active is not None else None,
                     getattr(active, "admission_hash_chain", None) if active is not None else None)
                for s in list(self._inflight):
                    _add(getattr(s, "thread_id", None), getattr(s, "client_meta", None),
                         getattr(s, "admission_hash_chain", None))
            _add(self._idle_thread_id, self._idle_client_meta)
            for r in list(self._residents.values()):
                _add(getattr(r, "idle_thread_id", None), getattr(r, "idle_client_meta", None))
        except Exception:
            log.debug("live protected thread-hash scan failed (best-effort)", exc_info=True)
        return hashes

    def _persist_kvcache_snapshot(self) -> dict:
        """Best-effort snapshot of the persist KV cache directory (SSD) for FE display.

        Returns {total_bytes, cap_bytes, file_count, headroom_bytes, over_cap: bool}.
        Uses the runtime config `persist.max_bytes` (default 40 GiB). All I/O is
        synchronous + best-effort; an error returns zeros (FE shows '—').
        """
        try:
            from turbohaul.subprocess_mgr import SLOT_PERSIST_DIR
            if not os.path.isdir(SLOT_PERSIST_DIR):
                return {
                    "total_bytes": 0,
                    "cap_bytes": int(self.runtime.persist.max_bytes),
                    "file_count": 0,
                    "headroom_bytes": int(self.runtime.persist.max_bytes),
                    "over_cap": False,
                }
            cap = int(self.runtime.persist.max_bytes)
            total = 0
            count = 0
            for fn in os.listdir(SLOT_PERSIST_DIR):
                if not fn.endswith(".bin"):
                    continue
                fpath = os.path.join(SLOT_PERSIST_DIR, fn)
                try:
                    st = os.stat(fpath)
                except OSError:
                    continue
                total += st.st_size
                count += 1
            headroom = cap - total if cap > 0 else 0
            return {
                "total_bytes": total,
                "cap_bytes": cap,
                "file_count": count,
                "headroom_bytes": max(0, headroom),
                "over_cap": cap > 0 and total > cap,
            }
        except Exception:
            log.debug("persist KV cache snapshot best-effort failed", exc_info=True)
            return {
                "total_bytes": 0,
                "cap_bytes": 0,
                "file_count": 0,
                "headroom_bytes": 0,
                "over_cap": False,
            }

    async def _gc_kv_cache(self, max_age_hours: float | None = None, max_files: int = 100) -> int:
        """Background GC for orphaned KV cache files.

        Reclaims .bin/.json pairs that are older than max_age_hours or exceed
        max_files (LRU by mtime), AND enforces a global TOTAL-BYTES ceiling
        (``self.runtime.kv.ram_cache_max_bytes`` — promoted
        from a bespoke env-only read to a real config field, still settable
        via the same ``TURBOHAUL_KVCACHE_MAX_BYTES`` env var through the
        standard config env-override path; default 20 GiB) by evicting
        oldest-first until the summed .bin size is back under the cap. Read
        FRESH from ``self.runtime`` on every call, so a live ``PUT
        /api/config`` change is picked up on the very next GC pass — no
        restart needed (``PUT /api/config`` replaces ``mgr.runtime`` wholesale;
        this method never caches the value). OFF the hot path — call
        periodically from the background sweeper, NOT from save/restore.

        ``max_age_hours``, if omitted (``None``), is read FRESH from
        ``self.runtime.kv.ram_cache_max_age_hours`` (
        promoted the same way as ``ram_cache_max_bytes``
        above — the sole production caller passes no arguments, so config is
        the only value production ever reaches; default 6.0 matches the
        pre-existing code default). The parameter itself is kept, not removed,
        purely so existing tests that disable the age axis to isolate the
        byte-ceiling/LRU-count behavior (e.g. ``max_age_hours=1e9``) keep
        working unchanged — an explicit value always wins over config, same
        relationship ``max_files`` already has (never promoted, always a
        plain override).

        NEVER evicts the per-group pinned clean_prefix anchor, nor ANY bin
        owned by a live thread (active / in-flight / idle-held / resident-idle,
        see ``_live_protected_thread_hashes``). Best-effort throughout: a
        vanished file, a bad stat, or a permission error is caught + logged,
        never raised into the sweeper loop.

        Returns number of .bin files deleted.
        """
        from turbohaul.subprocess_mgr import SLOT_SAVE_DIR
        try:
            if not os.path.isdir(SLOT_SAVE_DIR):
                return 0
            now = time.time()
            # Live-thread guard (constraint): resolve the protected thread_hash
            # set ONCE per GC pass from the manager's live state.
            protected_hashes = self._live_protected_thread_hashes()
            # The keep-warm recency window — the configured
            # `QueueConfig.idle_hot_load_seconds`, read live, NOT a constant —
            # used to gate the clean-anchor pin below: a DEAD anchor still inside
            # this window stays pinned (may resume shortly); once outside it, a
            # dead anchor is no longer exempt from age-prune/ceiling.
            idle_hot_s = self.runtime.queue.idle_hot_load_seconds
            # PIN the clean_prefix bin — it is BOTH the
            # classifier's comparison anchor AND the warm-path restore source; evicting
            # it silently disarms the whole classifier (no anchor -> every request
            # FRESH). BUT (F4) pin only the ONE bin `_find_clean_bin` would actually
            # pick per (model_tag, thread_hash) = NEWEST/LONGEST; every OTHER clean bin
            # (superseded same-thread saves, older-port orphans — never selected) is a
            # NORMAL evictable candidate, else one full-KV dump leaks per save forever
            # (kvcache already ~39GB). First pass: read metas, elect the per-group pin,
            # and remember each bin's thread_hash so the live-thread guard can match it.
            entries = []  # (fn, fpath, mtime, size)
            hash_by_path: dict[str, str] = {}  # fpath -> thread_hash (from sidecar)
            # Shadow diagnostics: fpath -> model_tag (from sidecar) for the
            # SHADOW_EVICT line (the sidecar is unlinked with the bin, so capture now).
            model_by_path: dict[str, str] = {}
            clean_pin = {}  # (model_tag, thread_hash) -> ((prompt_len, mtime), fpath)
            for fn in os.listdir(SLOT_SAVE_DIR):
                if not fn.endswith(".bin"):
                    continue
                fpath = os.path.join(SLOT_SAVE_DIR, fn)
                try:
                    st = os.stat(fpath)
                except OSError:
                    continue
                # Account the PAIR (.bin + .bin.ckpt), not just
                # the .bin — the engine's ckpt ladder sidecar is comparable in size
                # (observed 0.5-2.2x of the bin) and was INVISIBLE to the bytes
                # ceiling: bins summed 'under cap' while the tmpfs sat at 100%,
                # so saves/ckpt-writes silently truncated (ENOSPC) and restored
                # ladders broke -> mass rollbacks (the 2026-07-09 violation).
                _sz = st.st_size
                try:
                    _sz += os.stat(fpath + ".ckpt").st_size
                except OSError:
                    pass
                entries.append((fn, fpath, st.st_mtime, _sz))
                meta = None
                try:
                    with open(fpath[:-4] + ".json") as _mf:
                        meta = json.load(_mf)
                except (OSError, ValueError):
                    meta = None
                if meta:
                    th = meta.get("thread_hash")
                    if th:
                        hash_by_path[fpath] = th
                    _mtag = meta.get("model_tag")
                    if _mtag:
                        model_by_path[fpath] = _mtag
                    # Only a bin we can POSITIVELY confirm clean (+ has a thread_hash to
                    # group on) is eligible for the per-group pin; anything else evictable.
                    if meta.get("clean_prefix") and th:
                        # Elect into the pin only if `th` is LIVE or
                        # still inside the keep-warm recency window — a DEAD anchor
                        # past that window is NOT pinned, so it falls through
                        # `_protected()` to the age-prune + ceiling below.
                        if th in protected_hashes or st.st_mtime > (now - idle_hot_s):
                            grp = (meta.get("model_tag", ""), th)
                            rank = (int(meta.get("prompt_len", 0) or 0), st.st_mtime)  # longest, tie newest
                            cur = clean_pin.get(grp)
                            if cur is None or rank > cur[0]:
                                clean_pin[grp] = (rank, fpath)
            pinned_paths = {v[1] for v in clean_pin.values()}
            deleted_paths: set[str] = set()

            def _unlink_pair(fpath: str) -> bool:
                """Delete a .bin + its .json sidecar, best-effort. Returns True iff
                the .bin was removed. Tolerates a concurrent unlink (the file may
                vanish between scandir and here) and a permission error — neither
                aborts the GC pass.
                
                MOD (PL v3): invalidate scan cache AFTER every successful unlink,
                so all 3 GC callers (age-based, LRU-count, bytes-ceiling) invalidate
                automatically. Single-source, covers all current + future callers.
                """
                removed = False
                try:
                    os.remove(fpath)
                    removed = True
                except FileNotFoundError:
                    pass
                except OSError:
                    log.debug("slot KV GC: cannot remove %s (best-effort)", fpath, exc_info=True)
                # The engine-state sidecar pairs with the bin
                # (KV contract: every KV move moves the .ckpt with it) — evicting
                # the bin without it leaked a multi-GB orphan ckpt per eviction.
                # Guard: remove the ckpt ONLY while the bin is gone — if a
                # concurrent re-save landed a fresh bin between the two removes,
                # its brand-new ladder must survive (the age-floored orphan sweep
                # handles any genuine leftover later).
                if removed or not os.path.exists(fpath):
                    ckpt_path = fpath + ".ckpt"
                    try:
                        os.remove(ckpt_path)
                    except FileNotFoundError:
                        pass
                    except OSError:
                        log.debug("slot KV GC: cannot remove sidecar %s (best-effort)", ckpt_path, exc_info=True)
                json_path = fpath[:-4] + ".json"
                try:
                    os.remove(json_path)
                except FileNotFoundError:
                    pass
                except OSError:
                    log.debug("slot KV GC: cannot remove sidecar %s (best-effort)", json_path, exc_info=True)
                if removed:
                    deleted_paths.add(fpath)
                    # MOD: invalidate cache after every GC unlink
                    self._kvcache_scan_cache_invalidate()
                return removed

            def _protected(fpath: str) -> bool:
                # per-group clean anchor OR a bin owned by a live thread
                return fpath in pinned_paths or hash_by_path.get(fpath) in protected_hashes

            # candidates = everything EXCEPT the pinned clean winners AND live-thread bins
            candidates = [(fn, fpath, mtime, size) for (fn, fpath, mtime, size) in entries
                          if not _protected(fpath)]
            deleted = 0
            # Orphan-ckpt sweep — a .bin.ckpt whose .bin is gone
            # can never be restored (the pair is atomic per the KV contract) = pure
            # dead bytes. Pre-Wave-K evictions and ENOSPC/crash windows strand them.
            try:
                for _cfn in os.listdir(SLOT_SAVE_DIR):
                    if not _cfn.endswith(".bin.ckpt"):
                        continue
                    _cfp = os.path.join(SLOT_SAVE_DIR, _cfn)
                    # Existence-check the bin at SWEEP time,
                    # NOT via the entries snapshot — a pair finalizing between the
                    # snapshot and this sweep must not lose its ladder. Plus a
                    # 10-min age floor so an engine-side finalization in flight is
                    # never raced (the ckpt is written by a different process).
                    if os.path.exists(_cfp[:-len(".ckpt")]):
                        continue
                    try:
                        if (now - os.stat(_cfp).st_mtime) < 600:
                            continue
                    except OSError:
                        continue
                    try:
                        os.remove(_cfp)
                        self._kvcache_scan_cache_invalidate()
                        log.info("slot KV GC: reaped orphan ckpt %s", _cfn)
                    except OSError:
                        log.debug("slot KV GC: cannot remove orphan ckpt %s (best-effort)", _cfn, exc_info=True)
                # Reap stranded save temporaries (manager died
                # between the engine save and finalize) — .tmp/.tmp.ckpt bytes are
                # invisible to the ceiling accounting and no other path removes them.
                for _tfn in os.listdir(SLOT_SAVE_DIR):
                    if not (_tfn.endswith(".tmp") or _tfn.endswith(".tmp.ckpt")):
                        continue
                    _tfp = os.path.join(SLOT_SAVE_DIR, _tfn)
                    try:
                        if (now - os.stat(_tfp).st_mtime) > 3600:
                            os.remove(_tfp)
                            log.info("slot KV GC: reaped stranded temp %s", _tfn)
                    except OSError:
                        pass
            except Exception:
                log.debug("slot KV GC: orphan-ckpt sweep failed (best-effort)", exc_info=True)
            # --- Age-based eviction (existing knob) ---
            if max_age_hours is None:
                max_age_hours = self.runtime.kv.ram_cache_max_age_hours
            age_cutoff = now - (max_age_hours * 3600)
            for fn, fpath, mtime, size in candidates:
                if mtime < age_cutoff and _unlink_pair(fpath):
                    deleted += 1
            # --- LRU count eviction (existing knob) if still over limit ---
            remaining = [(fn, fp, mt, sz) for (fn, fp, mt, sz) in candidates
                         if fp not in deleted_paths]
            if len(remaining) > max_files:
                remaining.sort(key=lambda x: x[2])  # oldest first
                to_remove = len(remaining) - max_files
                for fn, fpath, mtime, size in remaining[:to_remove]:
                    if _unlink_pair(fpath):
                        deleted += 1
            # --- Global TOTAL-BYTES ceiling ---
            # Read fresh from self.runtime every pass (not
            # cached) so a live PUT /api/config change lands on the next GC
            # tick with no restart.
            max_bytes = self.runtime.kv.ram_cache_max_bytes
            if max_bytes > 0:
                # Total counts ALL surviving bins (pinned/protected included — they
                # occupy disk too); we only EVICT unprotected bins, oldest-first,
                # and stop the instant we're back at/under the cap (no over-evict).
                surviving = [(fn, fp, mt, sz) for (fn, fp, mt, sz) in entries
                             if fp not in deleted_paths]
                total = sum(sz for _, _, _, sz in surviving)
                if total > max_bytes:
                    # Explicit belt-guard — the freshest `.shadow.`
                    # bin per LIVE thread_hash must never be over-cap evicted (it is
                    # what makes the next swap-back byte-match), even though
                    # `_protected()`'s live-thread guard already covers every bin
                    # (incl. all shadows) owned by a live thread.
                    live_shadow_paths: dict[str, tuple[float, str]] = {}
                    for _fn, _fp, _mt, _sz in surviving:
                        if ".shadow." not in _fn:
                            continue
                        _th = hash_by_path.get(_fp)
                        if _th not in protected_hashes:
                            continue
                        _cur = live_shadow_paths.get(_th)
                        if _cur is None or _mt > _cur[0]:
                            live_shadow_paths[_th] = (_mt, _fp)
                    protected_shadow_paths = {v[1] for v in live_shadow_paths.values()}
                    evictable = [(fn, fp, mt, sz) for (fn, fp, mt, sz) in surviving
                                 if not _protected(fp) and fp not in protected_shadow_paths]
                    # TWO-COMPONENT KEY, TIER
                    # DOMINANT. `.shadow.` membership is primary and mtime only
                    # secondary: EVERY non-shadow sorts ahead of EVERY `.shadow.`
                    # bin, and age orders only WITHIN a tier — so the oldest file
                    # on disk is not necessarily the first one taken.
                    # Why the tier exists — shadow bins
                    # were being reaped ahead of dead-session clean anchors, so a
                    # returning client paid a full re-prefill instead of the
                    # sub-second restore the shadow exists to provide. The tier
                    # is the REORDER only; what made those anchors reclaimable is
                    # the gate on the anchor pin, keyed to liveness + recency — a
                    # protected entry is already filtered out of `evictable` just
                    # above, so no sort order could ever have reached one.
                    # ⚠ THE TIER IS BROADER THAN THE DEAD-ANCHOR CASE THAT
                    # MOTIVATED IT: this key reads the filename and the mtime and
                    # nothing else — not liveness, not clean_prefix — so the first
                    # tier also holds ordinary `clean_prefix=False` bins of ANY
                    # age, which are restore-useful; under sustained pressure a
                    # fresh ordinary bin can go ahead of a much older shadow.
                    # Whether that boundary should be narrowed to the case it was
                    # written for is open; this note
                    # describes the mechanism as it is. Rule: the ceiling prune
                    # takes entries in two tiers, not in age order: every non-shadow bin
                    # first, then the shadow bins, oldest first within each tier.
                    evictable.sort(key=lambda x: (".shadow." in x[0], x[2]))
                    for fn, fpath, mtime, size in evictable:
                        if total <= max_bytes:
                            break
                        if _unlink_pair(fpath):
                            deleted += 1
                            total -= size
                            # Shadow diagnostics: candidate (b) saved-but-EVICTED —
                            # a `.shadow` bin (born via `SHADOW_SAVE write=ok`) reaped
                            # HERE under over-cap while pinned dead-session clean anchors
                            # hold the floor. LOG ONLY (does NOT change what is deleted —
                            # the delete already happened above). Grep-join SHADOW_SAVE ->
                            # SHADOW_EVICT on th to see born-then-reaped.
                            if ".shadow." in fn:
                                self._shadow_diag_counts["evictions"]["shadow_evicted"] = (
                                    self._shadow_diag_counts["evictions"].get(
                                        "shadow_evicted", 0) + 1)
                                log.info(
                                    "SHADOW_EVICT th=%s model=%s path=%s age_s=%d "
                                    "size=%d reason=unprotected-over-cap",
                                    hash_by_path.get(fpath, "unknown"),
                                    model_by_path.get(fpath, "unknown"), fn,
                                    int(now - mtime), size)
                    if total > max_bytes:
                        log.warning(
                            "slot KV GC ceiling: still %d byte(s) over cap after evicting "
                            "every unprotected bin (pinned/live-thread bins hold the floor)",
                            total - max_bytes,
                        )
            # --- SSD persist-dir sweep ----------
            # SLOT_PERSIST_DIR is the Option-C unload / ownership-transfer SSD
            # archive. Best-effort second sweep mirroring the SLOT_SAVE_DIR pass:
            # (1) age-prune triplets older than the SAME max_age_hours; (2) enforce
            # a bytes ceiling (env TURBOHAUL_KVCACHE_PERSIST_MAX_BYTES, default
            # 42949672960 = 40GiB) oldest-first by mtime. Triplets
            # (.bin + .bin.ckpt + .json) are deleted together (mirror of
            # _unlink_pair, + the ckpt the persist copy carries). No protected-pins
            # for the persist tier — the tmpfs copy is the live source — EXCEPT a
            # triplet whose .bin mtime is < 60s old is never touched (mid-copy
            # safety: a RAM->SSD persist may be mid-flight). Counted separately
            # from `deleted` so the SLOT_SAVE_DIR diag snapshot stays honest.
            try:
                from turbohaul.subprocess_mgr import SLOT_PERSIST_DIR
                if os.path.isdir(SLOT_PERSIST_DIR):
                    # Use runtime config (FE-adjustable via PUT /api/config)
                    p_max_bytes = int(self.runtime.persist.max_bytes)
                    p_entries = []  # (fpath, mtime, size) — .bin only (triplet head)
                    for fn in os.listdir(SLOT_PERSIST_DIR):
                        if not fn.endswith(".bin"):
                            continue
                        fpath = os.path.join(SLOT_PERSIST_DIR, fn)
                        try:
                            st = os.stat(fpath)
                        except OSError:
                            continue
                        p_entries.append((fpath, st.st_mtime, st.st_size))

                    def _unlink_persist_triplet(fpath: str) -> bool:
                        """Delete a persist .bin + .bin.ckpt + .json together,
                        best-effort (mirror of _unlink_pair's tolerance)."""
                        removed = False
                        try:
                            os.remove(fpath)
                            removed = True
                        except FileNotFoundError:
                            pass
                        except OSError:
                            log.debug("persist KV GC: cannot remove %s (best-effort)",
                                      fpath, exc_info=True)
                        for side in (fpath + ".ckpt", fpath[:-4] + ".json"):
                            try:
                                os.remove(side)
                            except FileNotFoundError:
                                pass
                            except OSError:
                                log.debug(
                                    "persist KV GC: cannot remove sidecar %s "
                                    "(best-effort)", side, exc_info=True)
                        return removed

                    p_deleted = 0
                    fresh_floor = now - 60.0  # mid-copy safety window
                    p_age_cutoff = now - (max_age_hours * 3600)
                    for fpath, mtime, size in p_entries:
                        if mtime < p_age_cutoff and mtime < fresh_floor:
                            if _unlink_persist_triplet(fpath):
                                p_deleted += 1
                    p_surviving = [(fp, mt, sz) for (fp, mt, sz) in p_entries
                                   if os.path.exists(fp)]
                    p_total = sum(sz for _, _, sz in p_surviving)
                    if p_max_bytes > 0 and p_total > p_max_bytes:
                        p_surviving.sort(key=lambda x: x[1])  # oldest first
                        for fpath, mtime, size in p_surviving:
                            if p_total <= p_max_bytes:
                                break
                            if mtime >= fresh_floor:
                                continue  # mid-copy safety: never delete <60s-old
                            if _unlink_persist_triplet(fpath):
                                p_deleted += 1
                                p_total -= size
                    log.info(
                        "persist KV GC: total_bytes=%d ceiling=%d deleted=%d",
                        p_total, p_max_bytes, p_deleted)
            except Exception:
                log.debug("persist KV GC best-effort failed", exc_info=True)
            # --- Shadow diagnostics: KVGC observability. One structured
            # line + snapshot per GC pass naming WHAT pins the floor: the total on-disk
            # bytes, over_cap, and the PROTECTED (pinned clean-anchor OR live-thread)
            # bins + bytes, with the top protected thread_hashes. If protected_bytes
            # alone exceeds the cap, GC CANNOT evict under it = the 64GB floor. Sizes
            # come from the already-stat'd `entries` (NO new stat). Reused by the
            # KV_RESTORE line to correlate a forcing-full restore to pressure. Off the
            # hot path (throttled sweeper). Best-effort — never faults the GC pass.
            try:
                _surv = [(fn, fp, mt, sz) for (fn, fp, mt, sz) in entries
                         if fp not in deleted_paths]
                _total_bytes = sum(sz for _, _, _, sz in _surv)
                _over_cap = max(0, _total_bytes - max_bytes) if max_bytes > 0 else 0
                _prot = [(fn, fp, mt, sz) for (fn, fp, mt, sz) in _surv if _protected(fp)]
                _protected_bytes = sum(sz for _, _, _, sz in _prot)
                # A protected bin is LIVE iff its thread_hash is in the live set; a
                # protected bin that is NOT live = a pinned clean-anchor of a DEAD
                # session (the leak — these hold the floor but should be prunable).
                _dead = [(fn, fp, mt, sz) for (fn, fp, mt, sz) in _prot
                         if hash_by_path.get(fp) not in protected_hashes]
                _dead_bytes = sum(sz for _, _, _, sz in _dead)
                # Per-thread_hash aggregate: bytes + OLDEST mtime (largest age = most
                # stale) + liveness. `now` from the top of the GC pass.
                _agg: dict[str, list] = {}  # th -> [bytes, oldest_mtime, live]
                for _fn, _fp, _mt, _sz in _prot:
                    _th = hash_by_path.get(_fp)
                    _tk = _th or ("pinned-anchor" if _fp in pinned_paths else "unknown")
                    _live = _th in protected_hashes
                    rec = _agg.get(_tk)
                    if rec is None:
                        _agg[_tk] = [_sz, _mt, _live]
                    else:
                        rec[0] += _sz
                        rec[1] = min(rec[1], _mt)
                        rec[2] = rec[2] or _live
                _top = sorted(_agg.items(), key=lambda kv: kv[1][0], reverse=True)[:8]
                _top_fmt = ",".join(
                    f"{k}:{v[0]}:{int(now - v[1])}:{'live' if v[2] else 'dead'}"
                    for k, v in _top)
                _floor_reason = ("live-protected-floor"
                                 if _over_cap > 0 and _protected_bytes > max_bytes
                                 else ("over-cap-evicting" if _over_cap > 0 else "under-cap"))
                self._last_kvgc_snapshot = {
                    "total_bytes": _total_bytes, "ceiling": max_bytes,
                    "over_cap": _over_cap, "deleted": deleted,
                    "protected_bin_count": len(_prot),
                    "protected_bytes": _protected_bytes,
                    "dead_protected_bins": len(_dead),
                    "dead_protected_bytes": _dead_bytes,
                    # th -> {bytes, age_s, live} (top-8 by bytes) so operators SEE which
                    # dead-session anchors pin the floor.
                    "protected_threads": {
                        k: {"bytes": v[0], "age_s": int(now - v[1]),
                            "live": bool(v[2])} for k, v in _top},
                    "floor_reason": _floor_reason,
                    "ts": time.time(),
                }
                log.info(
                    "KVGC total_bytes=%d ceiling=%d over_cap=%d deleted=%d "
                    "protected_bins=%d protected_bytes=%d dead_protected_bins=%d "
                    "dead_protected_bytes=%d protected_threads=[%s] floor_reason=%s",
                    _total_bytes, max_bytes, _over_cap, deleted, len(_prot),
                    _protected_bytes, len(_dead), _dead_bytes, _top_fmt, _floor_reason,
                )
            except Exception:
                log.debug("KVGC diag snapshot best-effort failed", exc_info=True)
            if deleted:
                log.info("slot KV GC: deleted %d stale file(s)", deleted)
            return deleted
        except Exception:
            log.debug("slot KV GC failed", exc_info=True)
            return 0

    # === Build/model/ctx fingerprint + mismatched-bin purge ==
    # File-hygiene / defense-in-depth ONLY. Stamps every sidecar at save + deletes
    # bins that can't belong to the current engine. Reads NO restore decision and
    # changes NONE (resolve_kv / kv_policy / the M4 restore gate are off-limits).

    def _engine_fingerprint(self, model_tag: str) -> dict:
        """Best-effort build/model/ctx fingerprint of the CURRENTLY-loaded engine
        for ``model_tag``. Stamped into every KV sidecar at save (:_save_slot_kv)
        and compared by the purge sweep so a bin can NEVER be silently restored
        into a different engine build / model / ctx-config (= garbage KV).

        Every source is ALREADY known to the manager — there is NO multi-GB gguf
        hashing on the save path:
          - gguf_sha256     = manifest.gguf_blob_sha256 (PRECOMPUTED 64-hex blob
                              digest = the model identity).
          - engine_build_id = boot.runtime.llama_server_binary_sha256 (the pinned
                              llama-server binary digest = the ENGINE BUILD id;
                              empty in dev mode -> None).
          - n_ctx           = llama_server_flags.ctx_size or manifest.context_size
                              (the SAME chokepoint as :1512 / :2749).
          - n_rs_seq        = the engine's recurrent-state rollback budget for the
                              CURRENTLY-LOADED model. That is the MTP speculative
                              draft length (common/common.h need_n_rs_seq: returns
                              draft.n_max for MTP speculators, else 0) -- NOT the
                              slot width. This was stamped from
                              `parallel` (the seq width), which disagrees with the
                              engine's real n_rs_seq on every MTP model, so a cache
                              saved under draft length 2 vs 3 was indistinguishable.

        A field is None when its source is genuinely unavailable (dev mode / no
        manifest). Never raises."""
        fp: dict[str, Any] = {
            "gguf_sha256": None,
            "engine_build_id": None,
            "n_ctx": None,
            "n_rs_seq": None,
            "fp_gen": N_FP_GEN,
        }
        # engine_build_id: global to the manager (one binary serves every model).
        try:
            bid = getattr(self.boot.runtime, "llama_server_binary_sha256", "") or ""
            fp["engine_build_id"] = bid or None
        except Exception:
            pass
        # model + ctx + seq-width from the loaded model's manifest (small YAML read).
        try:
            m = read_manifest(self.boot.storage.manifests_path, model_tag)
            flags = m.llama_server_flags or {}
            fp["gguf_sha256"] = (m.gguf_blob_sha256 or None)
            _ctx = int(flags.get("ctx_size") or m.context_size or 0)
            fp["n_ctx"] = _ctx or None
            # n_rs_seq is the engine's recurrent rollback budget =
            # the draft length for speculators that need one, else 0 -- matching
            # common/common.h need_n_rs_seq(). Reading `parallel` (the slot
            # width) was wrong: it disagrees with the engine's real n_rs_seq on
            # every MTP model, so caches saved under different draft lengths
            # were indistinguishable. Mirror the engine exactly:
            # Widened MTP-only ->
            # SPEC_TYPES_NEEDING_RS_SEQ (MTP/DFlash/DSpark) -- the engine side extended
            # need_n_rs_seq() to cover all three (EAGLE3 stays out), and
            # verified that spec_draft_n_max
            # is what feeds draft.n_max on the engine side for D-Spark exactly
            # the same way it already does for MTP, so the rest of this stamp
            # logic is unchanged -- only the predicate widens.
            _spec_type = str(flags.get("spec_type", "") or "").strip().lower()
            if _spec_type in SPEC_TYPES_NEEDING_RS_SEQ:
                # Mirror the engine's own default (common/common.h:303 n_max=3)
                # when the manifest omits spec_draft_n_max, so the stamp matches
                # the runtime even when the manifest is silent.
                fp["n_rs_seq"] = int(flags.get("spec_draft_n_max") or 3)
            else:
                fp["n_rs_seq"] = 0
        except Exception:
            # Missing manifest (dev/test) or parse error: keep whatever we have.
            pass
        return fp

    @staticmethod
    def _fingerprint_matches(saved_meta: dict, current_fp: dict) -> bool:
        """True IFF the saved sidecar's stamp PROVES same build/model/ctx/seq as the
        current engine. A missing/None field on EITHER side = cannot prove same-
        build = NO MATCH (an unstamped legacy bin can't prove same-build -> unsafe
        to keep). String-normalized compare so None-vs-"" / int-vs-str can't
        false-match into a wrongful keep."""
        for k in ("gguf_sha256", "engine_build_id", "n_ctx", "n_rs_seq"):
            sv = saved_meta.get(k)
            cv = current_fp.get(k)
            if sv is None or cv is None:
                return False
            if str(sv) != str(cv):
                return False
        return True

    @staticmethod
    def _fingerprint_match_except_n_rs_seq(saved_meta: dict, current_fp: dict) -> bool:
        """True IFF the saved stamp matches the current fingerprint on ALL fields
        EXCEPT n_rs_seq (used for the one-release migration grace). Mirrors
        _fingerprint_matches but never compares the n_rs_seq field. A None on any
        OTHER field is still a non-match (same string-normalized rules)."""
        for k in ("gguf_sha256", "engine_build_id", "n_ctx"):
            sv = saved_meta.get(k)
            cv = current_fp.get(k)
            if sv is None or cv is None:
                return False
            if str(sv) != str(cv):
                return False
        return True

    @staticmethod
    def _restamp_legacy_meta(meta_path: str, saved_meta: dict, current_fp: dict) -> bool:
        """In-place re-stamp (one-release migration grace): rewrite a legacy
        (pre-fix, n_rs_seq=parallel) sidecar's .json so its n_rs_seq == the corrected
        MTP-draft value and fp_gen == N_FP_GEN. Atomic .tmp+os.replace so a crash
        never leaves a half-written sidecar. Returns True on success; False if the
        write failed (caller logs + keeps the bin as-is rather than purging it).

        This makes the grace SELF-LIMITING: the bin stops being a one-release case the
        moment it is re-stamped, so it can never shelter a genuine mismatch in a later
        sweep, and never-re-saved legacy bins get a correct label."""
        try:
            updated = dict(saved_meta)
            updated["n_rs_seq"] = current_fp.get("n_rs_seq")
            updated["fp_gen"] = N_FP_GEN
            tmp = f"{meta_path}.tmp"
            with open(tmp, "w") as f:
                json.dump(updated, f)
            os.replace(tmp, meta_path)
            return True
        except OSError:
            return False

    @staticmethod
    def _fp_summary(fp: dict) -> dict:
        """Compact fingerprint for logs — truncate the 64-hex digests to 12 chars."""
        out = {}
        for k in ("gguf_sha256", "engine_build_id", "n_ctx", "n_rs_seq"):
            v = fp.get(k)
            out[k] = v[:12] if isinstance(v, str) and len(v) > 12 else v
        return out

    def _purge_protected_basenames(self) -> set:
        """Basenames (no extension) of KV bins the LIVE idle holder is anchored on
        RIGHT NOW — never delete these even on a fingerprint miss. Yanking a live
        warm-path anchor mid-flight silently disarms the warm-path classifier (the exact
        harm the GC's clean-pin guards against, :_gc_kv_cache). A current-build
        anchor is ALSO preserved by the fingerprint match; this is the extra belt
        for a legacy (unstamped) anchor a live idle thread still depends on.
        Best-effort -> empty set on any error. Reads _find_clean_bin ONLY to build
        a PROTECT list (never makes a restore decision).

        Guard CANNOT FIRE at cap>=2. It gates on
        `if h is not None and mt` where h=self._idle_handle, mt=self._idle_model_tag
        — both PERMANENTLY unwritten at cap>=2 (written only inside
        _teardown_idle_holder, whose body is unreachable because its second
        statement returns early when self._idle_handle is None, which is always
        the case at cap>=2). So this function ALWAYS RETURNS AN EMPTY SET at
        cap>=2. Fingerprint match is still the primary protection; what is inert
        is the extra legacy-anchor belt. Not a catastrophe — but a guard that
        returns cleanly while structurally unable to protect anything is exactly
        why this note exists. Documented here for maintainers.
        """
        protected: set = set()
        try:
            h = self._idle_handle
            mt = self._idle_model_tag
            if h is not None and mt:
                found = self._find_clean_bin(h.port, mt, self._idle_thread_id or "")
                if found:
                    bin_fn = found[0]
                    protected.add(
                        bin_fn[:-4] if bin_fn.endswith(".bin") else bin_fn
                    )
        except Exception:
            pass
        return protected

    def _maybe_purge_mismatched_bins(self, reason: str) -> int:
        """Throttled wrapper for the sweeper: run the fingerprint purge at most once
        per FINGERPRINT_PURGE_MIN_INTERVAL_S. The flag is checked FIRST so the
        throttle clock only advances when purge is enabled (a fresh enable purges on
        the next sweep, not one interval later)."""
        if not _fingerprint_purge_enabled():
            return 0
        now = time.monotonic()
        if (now - self._last_fp_purge_mono) < FINGERPRINT_PURGE_MIN_INTERVAL_S:
            return 0
        self._last_fp_purge_mono = now
        return self._purge_mismatched_bins(reason=reason)

    def _purge_mismatched_bins(self, *, reason: str) -> int:
        """FILE-level sweep: delete every KV .bin+.json sidecar whose stamped
        fingerprint != its model's CURRENT engine fingerprint (different build /
        model / ctx / seq-width = garbage KV). Unstamped legacy bins (missing the
        fields) = UNKNOWN build = purged (a missing stamp can't PROVE same-build ->
        unsafe to keep). Gated by TURBOHAUL_FINGERPRINT_PURGE; best-effort (never
        raises); returns the count of bins removed.

        PURELY a file-deletion sweep. It reads NO restore decision and changes
        NONE (resolve_kv / kv_policy / the M4 restore gate are separately gated +
        OFF-LIMITS). Each sidecar is evaluated against ITS OWN model's current
        manifest (grouped by the stamped model_tag) — so a swap/reload that bumped
        a model's ctx or re-quantized its gguf reclaims THAT model's stale bins
        without touching a co-resident other model's still-valid bins."""
        if not _fingerprint_purge_enabled():
            return 0
        from turbohaul.subprocess_mgr import SLOT_SAVE_DIR
        removed = 0
        try:
            entries = os.listdir(SLOT_SAVE_DIR)
        except OSError:
            return 0
        protected = self._purge_protected_basenames()
        fp_cache: dict[str, dict] = {}
        for fn in entries:
            if not fn.endswith(".json"):
                continue
            base = fn[:-5]
            if base in protected:
                continue
            meta_path = os.path.join(SLOT_SAVE_DIR, fn)
            try:
                with open(meta_path) as f:
                    m = json.load(f)
            except (OSError, ValueError):
                # Unreadable/half-written sidecar -> leave it. The atomic .tmp +
                # os.replace save means a real sidecar is fully present or absent;
                # a transient read error must never trigger a delete.
                continue
            mt = m.get("model_tag")
            if not isinstance(mt, str) or not mt:
                # Can't identify the owning model -> can't compare -> leave it.
                continue
            cur = fp_cache.get(mt)
            if cur is None:
                cur = self._engine_fingerprint(mt)
                fp_cache[mt] = cur
            # Can't establish this model's CURRENT identity -> can't prove mismatch
            # -> skip (never purge blind on an unknown current engine). Guard on BOTH
            # gguf_sha256 (manifest gone / dev mode) AND engine_build_id (PL byte-
            # review MOD a): an UNPINNED/dev binary has llama_server_binary_sha256=""
            # -> engine_build_id=None -> _fingerprint_matches returns False for EVERY
            # bin -> would purge ALL bins incl fresh valid ones = reuse-defeating
            # footgun that would nuke the smoke. Skipping when either identity
            # dimension is unknown is the safe direction.
            if not cur.get("gguf_sha256") or not cur.get("engine_build_id"):
                continue
            if self._fingerprint_matches(m, cur):
                continue
            # MIGRATION GRACE (gen-gated): a bin
            # stamped by the PRE-fix code (n_rs_seq read from `parallel`, so no
            # fp_gen or fp_gen<N_FP_GEN) carries a WRONG label vs the corrected
            # MTP-draft value; the underlying .bin DATA is still for the current
            # real config. Deleting it on the first sweep after this fix would
            # nuke every cache on the machine. So: KEEP + re-stamp a legacy bin whose
            # ONLY mismatch is n_rs_seq. A FIXED-code bin (fp_gen==N_FP_GEN) with
            # an n_rs_seq-only mismatch is a GENUINE draft-length/width change and
            # MUST still purge — never excuse a real config divergence. Fields
            # gguf/engine/ctx mismatch always purge, legacy or not.
            if m.get("fp_gen") != N_FP_GEN and \
                    self._fingerprint_match_except_n_rs_seq(m, cur):
                if self._restamp_legacy_meta(meta_path, m, cur):
                    log.info(
                        "fingerprint purge (%s): KEPT %s — legacy pre-fix "
                        "n_rs_seq stamp (one-release migration grace); re-stamped "
                        "%r -> %r (fp_gen=%d)",
                        reason, base, m.get("n_rs_seq"), cur.get("n_rs_seq"),
                        N_FP_GEN,
                    )
                else:
                    log.warning(
                        "fingerprint purge (%s): KEPT %s — legacy pre-fix "
                        "n_rs_seq stamp (one-release migration grace); could not "
                        "re-stamp, left as-is",
                        reason, base,
                    )
                continue
            # Mismatch OR unstamped -> purge the .bin + .json pair.
            bin_path = os.path.join(SLOT_SAVE_DIR, base + ".bin")
            ok = True
            for p in (bin_path, meta_path):
                try:
                    os.remove(p)
                except FileNotFoundError:
                    pass
                except OSError as e:
                    ok = False
                    log.warning("fingerprint purge (%s): failed to remove %s: %s",
                                reason, p, e)
            if ok:
                removed += 1
                # Invalidate after fingerprint purge
                self._kvcache_scan_cache_invalidate()
                log.info(
                    "fingerprint purge (%s): removed mismatched KV %s "
                    "(saved=%s vs current=%s)",
                    reason, base, self._fp_summary(m), self._fp_summary(cur),
                )
        if removed:
            log.info("fingerprint purge (%s): removed %d mismatched KV bin(s)",
                     reason, removed)
        return removed

    async def _force_cold(self, slot: Slot, reason: str) -> None:
        """Mark a slot COLD when processing dies mid-flight.

        Walk legal transitions to COLD from any non-terminal
        state instead of silent direct-mutation. fsm.py LEGAL_TRANSITIONS now
        carries STAGED→COLD, LOADING→COLD, LOADING_FAIL→POPPED, POPPED→COLD,
        ACTIVE→GRACE→POPPED→COLD, IDLE_HOT→COLD. Memory and DB state stay
        in sync (no drift where slot.state stays e.g. LOADING in Python
        while sqlite reads state='COLD').

        Defensive teardown of any live handle attached
        to this slot BEFORE forcing COLD. Closes the footgun where a
        caller forgot to teardown (the active_match_cancelled path
        raises after _force_cold(matched, ...) without sigterm'ing the
        anchor sidecar). Defense-in-depth.

        Annotate audit with pid_source so post-hoc
        tooling can distinguish matched-row-on-anchor-pid (anchor_shared)
        from genuine standalone (self).
        """
        # SWAP-CLEAR (cap<=1): processing died mid-flight, so
        # the engine/KV state that would produce a consistent cached answer is
        # disrupted -> invalidate the completion-cache (correctness > hit-rate).
        self._completion_cache_clear("force_cold")
        # Identify pid_source, defensive sigterm
        # if the slot owns its own live handle.
        # Resolve cap-awarely (template: _resolve_top_level_active_slot).
        # At cap>=2, self._active_handle / self._active_slot / self._inflight are
        # PERMANENTLY unwritten (only written inside _process_slot / _fan_out_and_drain,
        # which are never reached again after the cap fork at worker_loop). The
        # live per-resident active_slot / inflight / handle are maintained by
        # _drive_resident / _serve_on_resident.
        pid_source = "self"
        residents = self._model_residents()
        if residents:
            # cap>=2: find the resident that owns this slot
            owner_r = None
            for r in residents:
                if r.active_slot is not None and r.active_slot.slot_id == slot.slot_id:
                    owner_r = r
                    break
                if slot in r.inflight:
                    owner_r = r
                    break
            if owner_r is not None and owner_r.handle is not None and slot.pid == owner_r.handle.pid:
                # Count how many slots share this handle (active_slot + inflight)
                sharing_count = (1 if owner_r.active_slot is not None else 0) + len(owner_r.inflight)
                if sharing_count > 1:
                    # The sidecar is serving MULTIPLE concurrent
                    # fan-out riders. Force-colding ONE of them (the ANCHOR or a rider)
                    # must NEVER sigterm the shared handle while siblings are still
                    # streaming. Identity-INDEPENDENT: gate on shared-pid + rider-set
                    # size, NOT slot_id.
                    pid_source = "fanout_shared_no_teardown"
                else:
                    # Slot owns the active handle. Defensive teardown -- processing
                    # died mid-flight, so there is no confirmed-good turn boundary
                    # to save from; this kill was previously unannounced.
                    _log_kv_save_decline(
                        KV_DECLINE_FORCE_COLD_NO_SAVE,
                        thread_id=getattr(slot, "thread_id", "") or "",
                        call_site="force_cold")
                    try:
                        await self._sigterm(
                            owner_r.handle,
                            drained_window_s=float(
                                self.runtime.queue.drained_sigterm_window_active_s
                            ),
                            is_active=False,
                            cold_window_s=float(
                                self.runtime.queue.drained_sigterm_window_cold_s
                            ),
                        )
                        # Clear the resident's handle so the next admit respawns
                        owner_r.handle = None
                    except Exception:
                        log.exception(
                            "_force_cold defensive teardown failed (best-effort)"
                        )
            # else: slot was already decoupled (pid=None on rider drift) — no teardown
        else:
            # cap<=1: legacy singleton (byte-identical to the earlier cap-unaware behaviour)
            if (
                self._active_handle is not None
                and slot.pid
                and slot.pid == self._active_handle.pid
                and len(self._inflight) > 1
            ):
                # The sidecar is serving MULTIPLE concurrent
                # fan-out riders. Force-colding ONE of them (the ANCHOR or a rider)
                # must NEVER sigterm the shared handle while siblings are still
                # streaming. Identity-INDEPENDENT: gate on shared-pid + rider-set
                # size, NOT slot_id (the anchor IS _active_slot, so the slot_id
                # check below would let it fall through to a teardown). Belt-and-
                # suspenders with the admit-path pid=None reset on rider drift.
                pid_source = "fanout_shared_no_teardown"
            elif (
                self._active_slot is not None
                and slot.slot_id != self._active_slot.slot_id
                and self._active_handle is not None
                and slot.pid
                and slot.pid == self._active_handle.pid
            ):
                # matched.pid == anchor.pid via shared warm sidecar
                # (rider drift path). Do NOT teardown — anchor owns it.
                pid_source = "anchor_shared"
            elif (
                slot.pid
                and self._active_handle is not None
                and slot.pid == self._active_handle.pid
            ):
                # Slot owns the active handle. Defensive teardown -- processing
                # died mid-flight, so there is no confirmed-good turn boundary
                # to save from; this kill was previously unannounced.
                _log_kv_save_decline(
                    KV_DECLINE_FORCE_COLD_NO_SAVE,
                    thread_id=getattr(slot, "thread_id", "") or "",
                    call_site="force_cold")
                try:
                    await self._sigterm(
                        self._active_handle,
                        drained_window_s=float(
                            self.runtime.queue.drained_sigterm_window_active_s
                        ),
                        is_active=False,
                        cold_window_s=float(
                            self.runtime.queue.drained_sigterm_window_cold_s
                        ),
                    )
                    self._set_active_handle(None)
                except Exception:
                    log.exception(
                        "_force_cold defensive teardown failed (best-effort)"
                    )

        # Walk legal hops to COLD per the new FSM table.
        # Worst case: ACTIVE → GRACE → POPPED → COLD (3 hops).
        if not is_terminal(slot.state):
            for _ in range(4):  # bounded — FSM diameter to COLD is 3
                if slot.state == SlotState.COLD:
                    break
                legal = LEGAL_TRANSITIONS.get(slot.state, set())
                if SlotState.COLD in legal:
                    transition(slot, SlotState.COLD)
                    break
                # Step toward COLD via the cheapest-distance hop.
                if SlotState.POPPED in legal:
                    transition(slot, SlotState.POPPED)
                elif SlotState.GRACE in legal:
                    transition(slot, SlotState.GRACE)
                elif SlotState.LOADING_FAIL in legal:
                    transition(slot, SlotState.LOADING_FAIL)
                else:
                    # No legal hop — terminal-park as COLD directly only as
                    # absolute last resort. Log for diagnostics.
                    log.warning(
                        "_force_cold: no legal hop from %s — direct-set COLD",
                        slot.state.value,
                    )
                    slot.state = SlotState.COLD
                    break
        # Slot-write stays on state_db_session; audit-write via pool.
        with state_db_session(self.boot.storage.state_db_path) as conn:
            mark_slot_ended(conn, slot.slot_id, reason)

        def _audit_force_cold() -> None:
            with audit_db_session(self.boot.storage.state_db_path) as audit_conn:
                # pid_source annotation
                record_audit_event(
                    audit_conn,
                    "force_cold",
                    {"reason": reason, "pid_source": pid_source},
                    slot_id=slot.slot_id,
                )

        await asyncio.to_thread(_audit_force_cold)

    def _compute_expected_drop_mib(self, model_tag: str) -> int:
        """Dynamic expected_drop_mib derived from manifest.

        Returns max(2048, manifest.expected_vram_bytes/1024**2). Floor
        at 2 GiB absorbs page-cache noise on small models. If manifest
        cannot be read (race during teardown of a just-deleted manifest),
        falls back to 2048 MiB rather than blocking teardown.
        """
        try:
            m = read_manifest(self.boot.storage.manifests_path, model_tag)
            return max(2048, int(m.expected_vram_bytes / (1024 * 1024)))
        except (FileNotFoundError, OSError):
            log.warning(
                "_compute_expected_drop_mib: manifest read failed for %s, "
                "falling back to 2048 MiB",
                model_tag,
            )
            return 2048

    def _live_handle_pids(self) -> set[int]:
        """Set of currently-known live llama-server pids across ALL residents.

        Used by intra_lifetime_orphan_scan + boot_orphan_reaper to tell managed
        sidecars from leaked orphans on the managed port range. UNION over
        EVERY resident's live handle pid + idle_handle pid + each reserving resident's
        ``booting_pid`` (the spawned-but-handle-not-yet-set pid), read from an
        AWAIT-FREE ``list()`` snapshot of the registry so a concurrent dispatcher
        mutation can't 'dict changed size during iteration'. At cap==1 the lone
        resident mirrors ``_active_handle``/``_idle_handle`` so this equals the legacy
        {_active,_idle} set (byte-identical); at cap>=2 the union-ALL is the critical
        fix that stops a co-resident sidecar being reaped as an orphan during another
        resident's teardown, and ``booting_pid`` closes the still-booting-sibling
        window before its handle is set.
        """
        live: set[int] = set()
        # cap-gate the multi-resident union so at cap<=1 this function is LITERALLY
        # the legacy two-if body below (structural byte-identity, not argued — the
        # entire dispatcher/registry surface is unreachable at cap=1, and the
        # _residents singleton's booting_pid is never written on that path).
        if self.runtime.queue.max_parallel_sidecars >= 2:
            for r in list(self._residents.values()):  # await-free atomic snapshot
                h = r.handle
                if h is not None and h.is_alive():
                    live.add(h.pid)
                ih = r.idle_handle
                if ih is not None and ih.is_alive():
                    live.add(ih.pid)
                if r.booting_pid is not None:
                    live.add(r.booting_pid)
        # Legacy manager-global holders (primary mirror) — belt-and-suspenders so
        # cap==1 stays byte-identical even if a singleton mirror ever lagged.
        # Read handle into local var first to avoid TOCTOU between
        # is_alive() check and .pid read (handle could change between reads).
        ah = self._active_handle
        if ah is not None and ah.is_alive():
            live.add(ah.pid)
        ih = self._idle_handle
        if ih is not None and ih.is_alive():
            live.add(ih.pid)
        return live

    async def _audit_async(self, slot: Slot, event_type: str) -> None:
        """Async-context wrapper for `_audit`.

        audit_db_session is sync-only. When called from an
        async function (e.g. `_process_slot`), the sync `_audit` must be
        offloaded to a worker thread or the sync-only guard raises RuntimeError.
        Call this from async code; call `_audit` directly from sync code.
        """
        await asyncio.to_thread(self._audit, slot, event_type)

    async def _audit_event_only_async(
        self,
        slot_id: str,
        event_type: str,
        payload: dict | None = None,
    ) -> None:
        """Async-context wrapper for `_audit_event_only`. See `_audit_async`."""
        await asyncio.to_thread(
            self._audit_event_only, slot_id, event_type, payload
        )

    def _audit(self, slot: Slot, event_type: str) -> None:
        """Audit: upsert current slot row + record event + publish to event bus.

        Slot-write stays on state_db_session; audit-write via pool. Both
        calls are sync (this method is `def`, not `async def`), so the
        audit_db_session sync-only guard is satisfied without to_thread.

        ★ Do NOT call this directly from async code — use
        `_audit_async` instead (the sync-only guard catches direct calls from a
        running event loop).

        The bus publish no longer depends on either DB
        write succeeding. Lifecycle events must be registered *and*
        verified observable on the surface they are read from; previously a
        failure in EITHER write took the publish with it and the event vanished
        from the bus. Both writes are still attempted, in the same order, on
        the same two distinct sessions — the split above is untouched, and
        this method is still `def`, so the sync-only guard still holds
        without `to_thread`.

        ⚠ THE DB ERROR STILL PROPAGATES, deliberately. All 24 `_audit_async`
        call sites keep the contract they have today; making a DB failure
        non-fatal would be an error-propagation POLICY change across the whole
        system and is a separate change, not part of an observability
        fix.

        ⚠ AND THAT IS WHY THE PUBLISH CARRIES THE GUARD RATHER THAN A BARE
        `finally:`. `publish_nowait` is NOT raise-free — `_deliver` swallows
        only `asyncio.QueueFull`, while `call_soon_threadsafe` raises
        `RuntimeError` on a CLOSED loop. Inside a bare `finally:` that
        RuntimeError would REPLACE the in-flight DB exception and hand callers
        a misleading error, destroying the very property this shape preserves.
        On the SUCCESS path the publish is deliberately left unguarded, so a
        publish failure propagates exactly as it always has: the guard exists
        to protect an exception already in flight, not to silence publishing.

        ★ AND THE REASON FOR THAT ASYMMETRY, because the shape looks lopsided
        until it is stated: NEVER DISCARD THE ONLY
        SIGNAL YOU HAVE. On the FAILURE path the DB error is already present
        and is the more informative of the two, so it must win — which is why
        the inner guard logs the publish failure rather than raising it. On
        the SUCCESS path a publish failure is the ONLY evidence that the event
        vanished; swallowing it would lose the event AND the signal, making
        the event contract LESS satisfiable, not more. One rule, applied twice, giving
        opposite-looking code in the two branches.
        """
        def _bus_event() -> dict:
            # Built at PUBLISH time, not hoisted above the writes: `slot.state`
            # is sampled at exactly the moment it was sampled before, so the
            # event's content is unchanged on the success path.
            return {
                "event": event_type,
                "slot_id": slot.slot_id,
                "model_tag": slot.model_tag,
                "state": slot.state.value,
                # Redaction: only first 8 chars of thread_id exposed
                "thread_id_prefix": (slot.thread_id or "")[:8],
            }

        try:
            with state_db_session(self.boot.storage.state_db_path) as conn:
                upsert_slot(
                    conn,
                    {
                        "slot_id": slot.slot_id,
                        "model_tag": slot.model_tag,
                        "thread_id": slot.thread_id,
                        "state": slot.state.value,
                        "port": slot.port,
                        "pid": slot.pid,
                        "extension_count": slot.extension_count,
                        "client_meta": slot.client_meta,
                    },
                )
            with audit_db_session(self.boot.storage.state_db_path) as conn:
                record_audit_event(
                    conn, event_type, {"state": slot.state.value}, slot_id=slot.slot_id,
                )
        except Exception:
            # Publish the event anyway, then re-raise the ORIGINAL
            # error. The inner guard is what stops a raising publish from
            # substituting itself for it; the failure is logged so one hidden
            # failure is not traded for another.
            try:
                self.event_bus.publish_nowait(_bus_event())
            except Exception:
                log.exception(
                    "event_bus publish FAILED while rescuing a %s event for slot %s "
                    "whose DB write already failed — the original DB error is re-raised "
                    "below and is the one callers see",
                    event_type, slot.slot_id,
                )
            raise
        # Publish redacted event to WS subscribers
        self.event_bus.publish_nowait(_bus_event())

    def _record_engine_identity(self, slot: "Slot") -> None:
        """DURABLE ENGINE IDENTITY: persist the spawned engine's (pid, port,
        starttime) to state.sqlite atomically so boot_orphan_reaper can prove
        ownership after a manager crash and reject PID-reused replacements.

        Best-effort: never breaks spawn. Reads /proc/<pid>/stat starttime
        (jiffies-since-boot, field 22) — unique per process instance per boot,
        never changes for the life of a process. A NULL starttime (non-Linux /
        /proc unavailable) leaves the column NULL → the identity proof
        degrades to report-only (the candidate is never reaped), preserving
        the conservative contract.
        """
        if slot.pid is None or slot.port is None:
            return
        try:
            st = _read_proc_starttime(slot.pid)
        except Exception:
            log.debug("engine-identity starttime read failed (best-effort)", exc_info=True)
            st = None
        try:
            with state_db_session(self.boot.storage.state_db_path) as conn:
                record_engine_identity(
                    conn, slot.slot_id, slot.pid, slot.port, st,
                )
        except Exception:
            log.debug("engine-identity record failed (best-effort)", exc_info=True)

    def _audit_event_only(self, slot_id: str, event_type: str, payload: dict | None = None) -> None:
        """Audit: record event ONLY, no slot row mutation.

        Use after teardown when the slot is already COLD in DB and we don't want
        to clobber that state. Routed through audit pool (sync call).
        """
        with audit_db_session(self.boot.storage.state_db_path) as conn:
            record_audit_event(conn, event_type, payload or {}, slot_id=slot_id)

    # === cap>=2 idle-engine-liveness sweep =====================

    async def _idle_engine_liveness_sweep(self) -> None:
        """Originally built as the cap>=2 "twin" of the cap<=1
        idle-dead-holder detection in worker_loop's dead-idle-tick branch:
        PROACTIVELY notice an idle
        resident's engine dying, rather than only discovering it reactively
        (on the next request routed onto it, or whenever an unrelated
        eviction eventually reaches the teardown path). Closes the exact gap
        that cap<=1 branch's own comment names: "the reactive warm_inherit
        is_alive() gate only fires on the next request."

        NOTE: "cap>=2 twin" describes this method's
        origin, not its scope. worker_loop's cap<=1 branch this was built to
        mirror is itself dead code now (the `>= 1` fork routes
        every cap through _dispatch_loop), and the resident it drove
        (self._idle_handle / the singleton) is never the live cap=1 resident
        either -- _route_or_reserve is model-tag-keyed at every cap, with no
        cap branch. This is now the ONLY idle-dead-holder detector that
        exists at any cap, not a cap>=2-specific twin of a still-live cap<=1
        one; see api/main.py's own call site (formerly gated `>= 2`, now
        `>= 1`, still explicit for the same reason worker_loop keeps its own
        always-true `>= 1` check readable) for why.

        _drive_resident's own wait loop is UNTOUCHED by this change — this is a
        separate, standalone task (same wiring shape as
        _periodic_terminal_park_sweep / LiveResidentsSupervisor, spawned
        alongside worker_loop in api/main.py) so the live per-resident
        dispatch path carries zero new risk.

        IDLE SCOPE: on the current code the scope below is exact, not
        an approximation. The
        idle-hot-holder concept is ResidentState.IDLE_EVICTABLE ("warm-idle
        + LRU-evictable" per the enum's own docstring), not "active_slot is
        None" -- but in the current code the two are PROVABLY EQUIVALENT,
        not a coverage widening. Across a full serve->grace->idle-hot
        lifecycle the two predicates
        `active_slot is not None or inflight` and
        `state is not IDLE_EVICTABLE` agree at every point, including every
        tick of the grace window itself. A grace-window death is skipped by
        BOTH predicates identically -- gating on IDLE_EVICTABLE does NOT fix
        a grace-window miss; that miss is real, pre-existing, and NOT closed
        by this change (a resident in grace is not yet in the idle-hot LRU pool
        cap<=1's own self._idle_handle mirrors either -- this sweep is scope-
        matched to that, not the whole resident lifecycle).

        The equivalence rests on two structural invariants, not luck:
        (1) `r.handle` and `r.state=ACTIVE` are only ever assigned TOGETHER,
        atomically, at spawn completion (in the spawn-completion path) -- so
        `handle is None` already excludes RESERVED_LOADING under EITHER
        predicate; (2) `assert not r.inflight` at the end of
        `_serve_on_resident` ("riders drain before GRACE exit") means
        inflight is always empty by the time IDLE_EVICTABLE is reachable, so
        the old predicate's `or inflight` clause is never the deciding
        factor either. IDLE_EVICTABLE is kept anyway -- not for coverage,
        but because it names the SAME set directly via the enum cap<=1's
        self._idle_handle mirrors, rather than re-deriving it from two
        proxy fields whose equivalence depends on invariants a future change
        could quietly break.

        TOCTOU safety: state (IDLE_EVICTABLE) and
        liveness (handle.is_alive(), a sync PID check — confirmed no
        suspension point) are both re-checked and acted on inside the SAME
        _registry_lock acquisition, in one pass — never a separate
        read-then-act. A resident can only leave IDLE_EVICTABLE by another
        coroutine also taking _registry_lock (the HIT-route admit path, or
        this sweep's own eviction), so it cannot flip
        IDLE_EVICTABLE->ACTIVE between this sweep's check and its action.

        On a confirmed idle+dead resident: _record_bin_death_strike (the
        shared helper) attributes the death and drives the
        strike-count/banner/quarantine logic exactly as cap<=1 already does,
        then _begin_unload_locked deregisters it (unchanged:
        a notify does not belong inside it), then
        _make_room_signal.notify_all() wakes any waiter fresh under lock —
        the same third-moment pattern already used elsewhere.
        _begin_unload_locked is correct here even though the process is
        already dead: _unload_teardown's own handle.is_alive() branch already
        has a dedicated already-dead arm (no SIGTERM attempted, just the
        existing IDLE_DEAD_CLASSIFY log) — as the code of that arm
        shows.
        """
        log.info(
            "multi_engine_idle_liveness_sweep started (interval=%.1fs)",
            _MULTI_ENGINE_IDLE_LIVENESS_SWEEP_INTERVAL_S,
        )
        while not self._stop_event.is_set():
            try:
                async with self._registry_lock:
                    for r in self._model_residents():
                        if r.state is not ResidentState.IDLE_EVICTABLE:
                            continue  # not the idle-hot-holder state
                        handle = r.handle
                        if handle is None or handle.is_alive():
                            continue
                        log.warning(
                            "multi-engine idle-hot resident DEAD between requests "
                            "(model=%s port=%s pid=%s)",
                            r.model_tag, handle.port, getattr(handle, "pid", None),
                        )
                        self._record_bin_death_strike(handle.port)
                        self._begin_unload_locked(r)
                        # Wake dispatch loop alongside make-room signal
                        self._dispatch_wake.set()
                        self._make_room_signal.notify_all()
            except asyncio.CancelledError:
                raise
            except Exception:
                log.exception(
                    "multi_engine_idle_liveness_sweep iteration failed (best-effort)"
                )
            await asyncio.sleep(_MULTI_ENGINE_IDLE_LIVENESS_SWEEP_INTERVAL_S)

    # === Background sweeper ==============================

    async def _periodic_terminal_park_sweep(self) -> None:
        """Periodically finalize the state-row for evictions.

        State-row finalization is deferred OFF the
        worker_loop hot path to avoid the 1-3s SQLite fsync stall that
        bypassed the audit pool. Audit-emit fires immediately via
        ``_audit_event_only_async``; the state-row finalize lands here.

        Loop: every ``background_sweep_interval_s`` (default 60s — matches
        audit pool rhythm), the sweeper queries for slots that are:
          - in STAGED state (never reached ACTIVE)
          - older than ``background_sweep_min_age_s`` (default 24h)
          - have no live ``pid`` (no sidecar attached)
          - have ``ended_at IS NULL`` (not already terminal-parked)
        Each match is mark_slot_ended'd with reason
        ``background_sweeper_evicted``. mark_slot_ended sets state=COLD +
        ended_at=now, so the SELECT predicate becomes false on the next
        sweep — naturally idempotent.

        Triple-gate (state=STAGED + age + pid IS NULL) eliminates false
        positives. An in-flight slot has either a non-NULL pid or has
        already transitioned past STAGED; either disqualifies it from the
        sweep. The 24h staleness floor is defense-in-depth — even if a
        pid-check edge case slips through, a 24h+ STAGED-state slot is
        overwhelmingly likely to be an eviction casualty.
        """
        interval = max(1, int(self.runtime.queue.background_sweep_interval_s))
        min_age = max(60, int(self.runtime.queue.background_sweep_min_age_s))
        log.info(
            "periodic_terminal_park_sweep started (interval=%ds, min_age=%ds)",
            interval, min_age,
        )
        while not self._stop_event.is_set():
            try:
                await self._run_one_sweep(min_age)
            except asyncio.CancelledError:
                raise
            except Exception:
                log.exception(
                    "periodic_terminal_park_sweep iteration failed (best-effort)"
                )
            # Piggyback the orphaned-VRAM-credit reconciler
            # on the SAME tick, no separate throttle -- see
            # _reconcile_orphaned_vram_credit's own docstring for why (its
            # common-case cost is a cheap dict scan, unlike the KV-GC
            # scandir below, which DOES need one).
            try:
                await self._reconcile_orphaned_vram_credit()
            except asyncio.CancelledError:
                raise
            except Exception:
                log.exception(
                    "orphaned VRAM credit reconciler iteration failed (best-effort)"
                )
            # Ceiling-GC: piggyback the KV-cache FILE gc on the park-sweep
            # cadence, but THROTTLED to _KV_GC_MIN_INTERVAL_S (a scandir of the multi-
            # GB save dir must not run every park tick). Best-effort — a GC failure
            # NEVER breaks the park loop (own try/except; _gc_kv_cache self-guards too).
            # NOTE: wired into the LOOP, not _run_one_sweep, so unit tests that call
            # _run_one_sweep directly never touch the real on-disk kvcache dir.
            try:
                _mono = time.monotonic()
                if _mono - self._last_kv_gc_monotonic >= self._KV_GC_MIN_INTERVAL_S:
                    self._last_kv_gc_monotonic = _mono
                    await self._gc_kv_cache()
            except asyncio.CancelledError:
                raise
            except Exception:
                log.exception("periodic KV-cache ceiling-GC failed (best-effort)")
            # Reclaim stale KV bins whose stamped build/model/
            # ctx fingerprint no longer matches the current engine (a model/binary
            # rebuild or a manifest ctx-change leaves a swapped/reloaded model's old
            # bins mismatched). Runs on the sweeper task OFF the hot path — gated +
            # throttled + best-effort; offloaded to a thread so the file I/O never
            # blocks the loop. STRICTLY a file sweep — never touches the restore
            # decision. (The M4 restore gate is the synchronous correctness backstop
            # for the sub-interval window; this is disk hygiene / defense-in-depth.)
            try:
                await asyncio.to_thread(
                    self._maybe_purge_mismatched_bins, "sweeper"
                )
            except asyncio.CancelledError:
                raise
            except Exception:
                log.exception(
                    "fingerprint purge (sweeper) failed (best-effort)"
                )
            try:
                await asyncio.wait_for(
                    self._stop_event.wait(), timeout=interval,
                )
                # _stop_event fired during sleep — exit cleanly
                break
            except asyncio.TimeoutError:
                continue  # normal cadence tick — run next sweep
        log.info("periodic_terminal_park_sweep exited")

    async def _run_one_sweep(self, min_age_s: int) -> int:
        """Run one sweep iteration. Returns count of slots finalized.

        Synchronous SQL inside ``state_db_session`` — OK because this method
        runs on the background sweeper task, NOT the worker_loop hot path.
        """
        from datetime import timedelta
        cutoff_iso = (
            datetime.now(timezone.utc) - timedelta(seconds=min_age_s)
        ).isoformat(timespec="seconds")
        finalized: list[str] = []
        with state_db_session(self.boot.storage.state_db_path) as conn:
            cur = conn.execute(
                """SELECT slot_id FROM slots
                   WHERE state = 'STAGED'
                     AND created_at < ?
                     AND pid IS NULL
                     AND ended_at IS NULL
                   LIMIT 100""",  # Batch cap, bounds writer-lock hold time under storm pattern
                (cutoff_iso,),
            )
            stale_slot_ids = [row["slot_id"] for row in cur.fetchall()]
            for slot_id in stale_slot_ids:
                mark_slot_ended(conn, slot_id, "background_sweeper_evicted")
                finalized.append(slot_id)
        # Counters + /status surfacing (single per-run update, not per-row)
        self._slots_finalized_lifetime += len(finalized)
        self._last_sweep_iso = datetime.now(timezone.utc).isoformat(
            timespec="seconds",
        )
        # Single audit per sweep run keeps audit volume bounded under storm.
        try:
            await self._audit_event_only_async(
                None,
                "background_sweeper_run",
                {
                    "slots_finalized": len(finalized),
                    "sweep_ts": self._last_sweep_iso,
                },
            )
        except Exception:
            log.exception(
                "background_sweeper_run audit emit failed (best-effort)"
            )
        return len(finalized)

    # === Shutdown ============================================================

    async def _drain_bg_tasks(self, grace_s: float = 10.0) -> None:
        """Await the detached ``_spawn_bg`` teardown/requeue/reap tasks at shutdown so
        an in-flight ``_unload_teardown`` (sidecar reap) can't leak past process exit
        (P1d N2 fast-follow #2). Snapshot first (the set self-mutates as tasks finish);
        bounded by ``grace_s``; ``gather(return_exceptions=True)`` so one failing task
        can't abort the drain. A timeout cancels the stragglers (acceptable — they are
        best-effort cleanup and the process is exiting).

        NOTE on timing: the SLOW reap (``_reap_booting_pid``'s up-to-3s SIGTERM-poll +
        SIGKILL) runs INLINE in the driver finally, which the sweep already awaits
        with NO timeout in the DRIVERS step BEFORE this drain — and that finally claims
        ``torn_down`` first, so any bg ``_unload_teardown`` here finds it already claimed
        and no-ops. So this drain only awaits the FAST bg tasks (future-fails, requeues,
        no-op teardowns); the generous 10s grace is pure insurance."""
        pending = [t for t in list(self._bg_tasks) if not t.done()]
        if not pending:
            return
        with contextlib.suppress(asyncio.TimeoutError, Exception):
            await asyncio.wait_for(
                asyncio.gather(*pending, return_exceptions=True), timeout=grace_s
            )

    async def shutdown(self) -> None:
        """Clean tear-down. Stops worker loop + sweeper + drains queue + closes state db."""
        self._stop_event.set()
        # === P1e shutdown-sweep: OBSERVERS -> dispatcher -> DRIVERS -> bg-drain ===
        # 1) OBSERVERS FIRST (both the cap<=1 single poller AND the cap>=2 resident
        # supervisor) so neither issues a /slots probe against a sidecar being torn
        # down, nor publishes a generation tick after the loop is gone.
        # Predictor #16 HIGH). Cancelling the supervisor stops ALL N per-resident
        # polls at once.
        for obs in (
            self._live_poller_task,
            self._live_supervisor_task,
            self._plugin_health_task,
        ):
            if obs is not None and not obs.done():
                obs.cancel()
                with contextlib.suppress(asyncio.CancelledError, Exception):
                    await obs
        # 2) DISPATCHER next: stop routing new work onto residents.
        if self._worker_task is not None and not self._worker_task.done():
            self._worker_task.cancel()
            try:
                await self._worker_task
            except asyncio.CancelledError:
                pass
        # 3) DRIVERS (P1e): deterministically cancel every per-resident driver so its
        # finally reaps the handle / booting_pid + drains its inbox (the cap>=2
        # teardown). P1d left drivers to NOTICE _stop_event on their next loop turn;
        # the sweep cancels them so a driver parked in inbox.get()/health-wait tears
        # down NOW (and before queue.close, so drained inbox slots can re-enqueue).
        driver_tasks = [
            r.driver_task
            for r in list(self._residents.values())
            if r.driver_task is not None and not r.driver_task.done()
        ]
        for dt in driver_tasks:
            dt.cancel()
        if driver_tasks:
            # Await the driver teardowns in PARALLEL (gather), not sequentially: each
            # finally may run an up-to-3s SIGTERM-grace reap, so a sequential
            # `for dt: await dt` would serialize N residents to ~N*3s at shutdown.
            # return_exceptions so one failing teardown can't abort the rest (the
            # CancelledError each cancelled driver raises is captured, not propagated)
            # (PL pre-cutover polish #3).
            await asyncio.gather(*driver_tasks, return_exceptions=True)
        # 4) DRAIN the detached bg-tasks (P1d N2 fast-follow #2): the driver finallys +
        # death-reapers schedule teardown/requeue/reap coroutines through _spawn_bg;
        # await them (bounded) so an in-flight _unload_teardown can't LEAK a sidecar
        # past process exit. Must come AFTER the driver awaits (which is when those
        # reapers get scheduled).
        await self._drain_bg_tasks()
        # Cancel + await the background sweeper task.
        if self._sweeper_task is not None and not self._sweeper_task.done():
            self._sweeper_task.cancel()
            with contextlib.suppress(asyncio.CancelledError, Exception):
                await self._sweeper_task
        # Cancel + await the cap>=2 idle-engine-liveness sweep.
        # Same step as the sweeper above (both are mutators, not observers) --
        # must stop taking _registry_lock and calling _begin_unload_locked
        # before this point, or it could act on a resident whose driver task
        # was just cancelled/reaped above.
        if (
            self._idle_liveness_task is not None
            and not self._idle_liveness_task.done()
        ):
            self._idle_liveness_task.cancel()
            with contextlib.suppress(asyncio.CancelledError, Exception):
                await self._idle_liveness_task
        # close() now returns the slots it cleared; fail
        # their completion_futures so callers get a clean CancelledError
        # instead of hanging until submit_and_wait timeout.
        cleared_slots = await self.queue.close()
        for cleared in cleared_slots:
            self._fail_completion_future(
                cleared,
                asyncio.CancelledError(
                    "manager shutdown -- slot was never processed"
                ),
            )
        # Tear down any idle holder so VRAM is released
        # and llama-server child is reaped on graceful shutdown.
        if self._idle_handle is not None:
            try:
                await self._teardown_idle_holder("shutdown")
            except Exception:
                log.exception(
                    "idle teardown during shutdown failed (best-effort)"
                )
        # Release the TOCTOU-pinned binary fd on shutdown
        if self._binary_fd is not None:
            with contextlib.suppress(OSError):
                os.close(self._binary_fd)
            self._binary_fd = None
